INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(3231, 867, 'Description', 'Description', 'A large obelisk. These monuments represent the sun. Obelisks are mission structures requiring high Masonry skill.', '<p><i>A large obelisk. These monuments represent the sun.</i>\n</p>\n<p><b>Obelisks</b> are <a href=\"/index.php/Category:Mission_structures\" title=\"Category:Mission structures\">mission structures</a> requiring high <a href=\"/index.php/Masonry\" title=\"Masonry\">Masonry</a> skill.\n</p>', 0),
(3232, 867, 'Notes', 'Notes', '6% chance to create with 36 QL brick at 55 Masonry. 16% chance to create with 60 QL brick at 55 Masonry. On failure, the brick is damaged by 1 point and the clay is damaged by 10 points. Can not be destroyed once finished.', '<ul><li>6% chance to create with 36 QL brick at 55 Masonry.</li>\n<li>16% chance to create with 60 QL brick at 55 Masonry.</li>\n<li>On failure, the brick is damaged by 1 point and the clay is damaged by 10 points.</li>\n<li>Can not be destroyed once finished.</li></ul>', 1),
(3233, 867, 'See Also', 'See_Also', 'Mission structures , for more information on mission structures in general.', '<ul><li><a href=\"/index.php/Category:Mission_structures\" title=\"Category:Mission structures\">Mission structures</a>, for more information on mission structures in general.</li></ul>', 2),
(3234, 867, 'Images', 'Images', '', '<p><a class=\"image\" href=\"/index.php/File:Obelisk-night.jpg\"><img alt=\"Obelisk-night.jpg\" data-file-height=\"768\" data-file-width=\"1024\" decoding=\"async\" height=\"768\" src=\"/images/8/8b/Obelisk-night.jpg\" width=\"1024\"/></a>\n<a class=\"image\" href=\"/index.php/File:Obelisk.jpg\"><img alt=\"Obelisk.jpg\" data-file-height=\"768\" data-file-width=\"1024\" decoding=\"async\" height=\"768\" src=\"/images/c/c6/Obelisk.jpg\" width=\"1024\"/></a>\n</p>', 3),
(3285, 898, 'Description', 'Description', 'Increases attack and movement speed Grants increased attack speed and movement speed for a duration depending on the cast power.', '<p><i>Increases attack and movement speed</i>\n</p>\n<p>Grants increased attack speed and movement speed for a duration depending on the cast power.\n</p>', 0),
(3286, 898, 'Method', 'Method', 'Activate your deity\'s statuette Right-click a player Select Spells > Frantic charge', '<ol><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> your deity\'s <a href=\"/index.php/Statuette\" title=\"Statuette\">statuette</a></li>\n<li>Right-click a player</li>\n<li>Select <i>Spells</i> &gt; <i>Frantic charge</i></li></ol>', 1),
(3347, 904, 'Spawn settlement', 'Spawn_settlement', 'Green Dog', '<p><a href=\"/index.php/Settlement:Green_Dog\" title=\"Settlement:Green Dog\"> Green Dog</a>\n</p>', 0),
(3348, 904, 'Travel', 'Travel', 'Deliverance may be reached by traveling east from Chaos , north from Exodus , west from Xanadu , and south from Independence . Players may also use plot course from any Southern Isles server. Sailing here from Chaos requires that no enemies be in the local area at the time of attempted server crossing.', '<p>Deliverance may be reached by traveling east from <a href=\"/index.php/Chaos\" title=\"Chaos\">Chaos</a>, north from <a href=\"/index.php/Exodus\" title=\"Exodus\">Exodus</a>, west from <a href=\"/index.php/Xanadu\" title=\"Xanadu\">Xanadu</a>, and south from <a href=\"/index.php/Independence\" title=\"Independence\">Independence</a>. Players may also use <a href=\"/index.php/Plot_course\" title=\"Plot course\">plot course</a> from any Southern Isles server. Sailing here from <a href=\"/index.php/Chaos\" title=\"Chaos\">Chaos</a> requires that no enemies be in the local area at the time of attempted server crossing.\n</p>', 1),
(3349, 904, 'Maps', 'Maps', 'In-game map Map dumps For community maps, see Maps', '<ul><li><a href=\"/index.php/File:Deliverance.jpg\" title=\"File:Deliverance.jpg\"> In-game map</a></li>\n<li><a class=\"external text\" href=\"https://drive.google.com/drive/folders/0B6J_aGQ6URL8S2ZXRjlsdDV2SWM\" rel=\"nofollow\">Map dumps</a></li>\n<li>For community maps, see <a href=\"/index.php/Maps\" title=\"Maps\">Maps</a></li></ul>', 2),
(3350, 904, 'Statistics', 'Statistics', 'Server status Server statistics See server graphs for the statistics of all servers.', '<ul><li><a class=\"external text\" href=\"http://deliverance.game.wurmonline.com/battles/stats.html\" rel=\"nofollow\">Server status</a></li>\n<li><a class=\"external text\" href=\"http://deliverance.game.wurmonline.com/mrtg/\" rel=\"nofollow\">Server statistics</a></li>\n<li>See <a href=\"/index.php/Server_graphs\" title=\"Server graphs\">server graphs</a> for the statistics of all servers.<i></i></li></ul>', 3),
(3351, 908, 'Character', 'Character', 'Tell us about Exodus!', '<p><a class=\"external text\" href=\"http://forum.wurmonline.com/index.php?/topic/130249-what-does-your-server-mean-to-you/\" rel=\"nofollow\">Tell us about Exodus!</a>\n</p>', 0),
(3352, 908, 'Spawn settlements', 'Spawn_settlements', 'Esert', '<ul><li><a href=\"/index.php/Settlement:Esert\" title=\"Settlement:Esert\">Esert</a></li></ul>', 1),
(3353, 908, 'Travel', 'Travel', 'This island may be reached by sailing south from Deliverance or north from Celebration . When leaving, sailing west will take the player to Chaos while east will lead to Xanadu . These are one-way connections, and one cannot cross back to Exodus from either server without first going through Deliverance. Players may also plot a course to Exodus, allowing travel from any Southern Freedom Isles map to Exodus directly. Sailing here from Chaos requires that no enemies be in the local area at the time of attempted server crossing.', '<ul><li>This island may be reached by sailing south from <a href=\"/index.php/Deliverance\" title=\"Deliverance\">Deliverance</a> or north from <a href=\"/index.php/Celebration\" title=\"Celebration\">Celebration</a>. When leaving, sailing west will take the player to <a href=\"/index.php/Chaos\" title=\"Chaos\">Chaos</a> while east will lead to <a href=\"/index.php/Xanadu\" title=\"Xanadu\">Xanadu</a>. These are one-way connections, and one cannot cross back to Exodus from either server without first going through Deliverance.</li></ul>\n<ul><li>Players may also <a href=\"/index.php/Plot_course\" title=\"Plot course\">plot a course</a> to Exodus, allowing travel from any Southern Freedom Isles map to Exodus directly. Sailing here from <a href=\"/index.php/Chaos\" title=\"Chaos\">Chaos</a> requires that no enemies be in the local area at the time of attempted server crossing.</li></ul>', 2),
(3354, 908, 'Maps', 'Maps', 'In-game map Map dumps For community maps, see Maps', '<ul><li><a href=\"/index.php/File:Exodus_01.jpg\" title=\"File:Exodus 01.jpg\"> In-game map</a></li>\n<li><a class=\"external text\" href=\"https://drive.google.com/drive/folders/0B6J_aGQ6URL8eXNqaXBXNl83Y00\" rel=\"nofollow\">Map dumps</a></li>\n<li>For community maps, see <a href=\"/index.php/Maps\" title=\"Maps\">Maps</a></li></ul>', 3),
(3355, 908, 'Statistics', 'Statistics', 'Server status Server statistics See server graphs for the statistics of all servers.', '<ul><li><a class=\"external text\" href=\"http://exodus.game.wurmonline.com/battles/stats.html\" rel=\"nofollow\">Server status</a></li>\n<li><a class=\"external text\" href=\"http://exodus.game.wurmonline.com/mrtg/\" rel=\"nofollow\">Server statistics</a></li>\n<li>See <a href=\"/index.php/Server_graphs\" title=\"Server graphs\">server graphs</a> for the statistics of all servers.<i></i></li></ul>', 4),
(3388, 917, 'Overview', 'Overview', 'In Wurm there are three kingdoms which actively participate in player versus player combat. These are Mol-Rehan, Jenn-Kellon, and The Horde of the Summoned. While all kingdoms are considered to be at war, the lore of Wurm suggest that members of the White Light religions should be at odds with the those of the Black Lighter religions more frequently. Throughout the history of Wurm there has been several alliances created between the different kingdoms, mainly between Mol-Rehan / Jenn-Kellon and Horde of the Summoned. Although members of different kingdoms are naturally aggressive towards each other, players are not forced to enter combat with each other, and different kingdoms can work in unison if the individual members choose to do so. PvP can happen within kingdoms as well, as there are no rules against, or mechanics preventing, combat between members of the same kingdom. On Wild there are no restrictions to PvP. The only downside to attacking members of your own kingdom is the procuring of a bed reputation, which will most likely be crippling in the long run. Wurm\'s PvP acts like all combat, and relies on both player stats, and player ability. Different conditions will change your likeliness to succeed in PvP, including how powerful your in game character is, and how well you execute plans and work as a team. Communication in Wurm PvP is vital, and in organized PvP, it is strongly advised that players have some means of quickly relaying information to each other. Above all, tactics and know how are the diving factors in PvP, and substantial odds can be outweighed with the proper gear, preparation, and teamwork.', '<p>In Wurm there are three kingdoms which actively participate in player versus player combat. These are Mol-Rehan, Jenn-Kellon, and The Horde of the Summoned. While all kingdoms are considered to be at war, the lore of Wurm suggest that members of the White Light religions should be at odds with the those of the Black Lighter religions more frequently. Throughout the history of Wurm there has been several alliances created between the different kingdoms, mainly between Mol-Rehan / Jenn-Kellon and Horde of the Summoned. Although members of different kingdoms are naturally aggressive towards each other, players are not forced to enter combat with each other, and different kingdoms can work in unison if the individual members choose to do so. PvP can happen within kingdoms as well, as there are no rules against, or mechanics preventing, combat between members of the same kingdom. On Wild there are no restrictions to PvP. The only downside to attacking members of your own kingdom is the procuring of a bed reputation, which will most likely be crippling in the long run. Wurm\'s PvP acts like all combat, and relies on both player stats, and player ability. Different conditions will change your likeliness to succeed in PvP, including how powerful your in game character is, and how well you execute plans and work as a team. Communication in Wurm PvP is vital, and in organized PvP, it is strongly advised that players have some means of quickly relaying information to each other. Above all, tactics and know how are the diving factors in PvP, and substantial odds can be outweighed with the proper gear, preparation, and teamwork.  \n</p>\n<p><br/>\n</p>', 0),
(3389, 917, 'PvP Related Skills', 'PvP_Related_Skills', 'Many factors can be considered when one enter PvP in Wurm. All combat skills are used while PvPing, and these including your shield skill, weapon skill, fight skill, fighting stance skill, bow skill, archery skill, and player characteristics. Having higher in any of these can attribute to your success, however it is generally advised to be trained in at least one shield skill, weapon skill, and fighting stance of your choice. Overall fight skill is considered to be the most important skill in PvP, as it adds greatly to your overall combat rating. Having higher fight skill will allow the player to hit more, but so will having greater weapon and fighting sub skills. Having a higher shield skill is important to block both blows in up close pvp, and arrows for long ranged. Fighting stances are another choice the player must make. Currently, they can choose between Defensive, Aggressive, and Normal fighting modes, which all have their specific advantages and disadvantages. In long ranged combat, both bow and archery skill are considered important. Most frequently players use Long Bows, although Medium and Short Bows are considered to have their tactical advantages and lower ranges. Beyond skills the other major character attribute that effects PvP are the player characteristics. Body Strength, Body Stamina, Body Control, Mind Speed, Soul Strength, and Soul Depth all have some effect on PvP. Having higher body strength will allow you to hit harder, while having higher body stamina will increase your stamina. The over all body skill increases a player\'s \"toughness\", and therefor is also considered important, although it levels on its own with your other skills. Body control is believed to increase the players chance dodge and perform critical strikes. While the effects of Mind Speed lets you cast more spells before becoming overheated, it is considered to make focusing easier, and perhaps increase chance to hit, aim, and perform special moves. Soul Strength and Soul Depth factor into spell resistance and ability to cast spells. For priest, having a high Soul Depth and Soul Strength means the ability to cast stronger spells, while for normal players it will improve their resistance to said spells, as well as to the effects of the Orb of Doom. Because of characteristics important roll in PvP, crafters who decide to fight have a notable advantage in combat, assuming they train their skills to certain standards.', '<p>Many factors can be considered when one enter PvP in Wurm. All combat skills are used while PvPing, and these including your shield skill, weapon skill, fight skill, fighting stance skill, bow skill, archery skill, and player characteristics. Having higher in any of these can attribute to your success, however it is generally advised to be trained in at least one shield skill, weapon skill, and fighting stance of your choice. Overall fight skill is considered to be the most important skill in PvP, as it adds greatly to your overall combat rating. Having higher fight skill will allow the player to hit more, but so will having greater weapon and fighting sub skills. Having a higher shield skill is important to block both blows in up close pvp, and arrows for long ranged. Fighting stances are another choice the player must make. Currently, they can choose between Defensive, Aggressive, and Normal fighting modes, which all have their specific advantages and disadvantages. In long ranged combat, both bow and archery skill are considered important. Most frequently players use Long Bows, although Medium and Short Bows are considered to have their tactical advantages and lower ranges. \n</p>\n<p>Beyond skills the other major character attribute that effects PvP are the player characteristics. Body Strength, Body Stamina, Body Control, Mind Speed, Soul Strength, and Soul Depth all have some effect on PvP. Having higher body strength will allow you to hit harder, while having higher body stamina will increase your stamina. The over all body skill increases a player\'s \"toughness\", and therefor is also considered important, although it levels on its own with your other skills. Body control is believed to increase the players chance dodge and perform critical strikes. While the effects of Mind Speed lets you cast more spells before becoming overheated, it is considered to make focusing easier, and perhaps increase chance to hit, aim, and perform special moves. Soul Strength and Soul Depth factor into spell resistance and ability to cast spells. For priest, having a high Soul Depth and Soul Strength means the ability to cast stronger spells, while for normal players it will improve their resistance to said spells, as well as to the effects of the Orb of Doom. Because of characteristics important roll in PvP, crafters who decide to fight have a notable advantage in combat, assuming they train their skills to certain standards.\n</p>', 1),
(3390, 917, 'Player Death', 'Player_Death', 'If you die in PvP you do not lose skills as you usually would. Instead, you take a .25 hit to your fight skill, as well as a small loss in body strength. If a resurrection stone is not active, or the player is not a 70+ faith Magranon priest, all items are dropped on death, and can be picked up by the opposing faction and looted. PvP can be very high risk, because losing all of your items, including valuable scale and drake, is a possibility. Players may also lose an affinity on death, and it is transferred to an opponent who damaged the player. If you kill a player on PvP, or are apart of a kill, you can gain a few possible things. All kills on players with above 10~ fight skill will give fight skill gains. A seventy fight skill player will give roughly .25 at 70 fs. This scales as you or the enemy gains or loses in fight skill. If you get a hit on an enemy, you may also receive their affinity. There is no limit to the number of affinities a player can have other than a max of 5 in any one skill, and all players receive one upon start up. If they lose their last affinity they will receive another after a set period of time. Finally, upon killing a player or dying, a player gains or loses rank. All players start with 1000 rank, and give progressively less as they died. Contrarily, if a player with very high rank dies to one with a very low rank, the amount lost from the player is increased greatly. While you may find yourself gaining only one rank from a group kill, when you die you may lose twenty or more, as your rank has been spread across all of the players that killed you. Likewise, killing an opponent in solo combat will increase the amount of rank you gain, as there are no other players to spread the rank to. The same can be applied to fight skill.', '<p>If you die in PvP you do not lose skills as you usually would. Instead, you take a .25 hit to your fight skill, as well as a small loss in body strength. If a resurrection stone is not active, or the player is not a 70+ faith Magranon priest, all items are dropped on death, and can be picked up by the opposing faction and looted. PvP can be very high risk, because losing all of your items, including valuable scale and drake, is a possibility. Players may also lose an affinity on death, and it is transferred to an opponent who damaged the player. If you kill a player on PvP, or are apart of a kill, you can gain a few possible things. All kills on players with above 10~ fight skill will give fight skill gains. A seventy fight skill player will give roughly .25 at 70 fs. This scales as you or the enemy gains or loses in fight skill. If you get a hit on an enemy, you may also receive their affinity. There is no limit to the number of affinities a player can have other than a max of 5 in any one skill, and all players receive one upon start up. If they lose their last affinity they will receive another after a set period of time. Finally, upon killing a player or dying, a player gains or loses rank. All players start with 1000 rank, and give progressively less as they died. Contrarily, if a player with very high rank dies to one with a very low rank, the amount lost from the player is increased greatly. While you may find yourself gaining only one rank from a group kill, when you die you may lose twenty or more, as your rank has been spread across all of the players that killed you. Likewise, killing an opponent in solo combat will increase the amount of rank you gain, as there are no other players to spread the rank to. The same can be applied to fight skill.\n</p>', 2),
(3391, 917, 'Armour', 'Armour', 'The current most common armour in PvP is a set of chain or leather armour with web armour enchant. Other armours are used less frequently, sometimes due to rarity, and sometimes because they are not useful in combat. Below is a list of armours, their frequency of use in PvP, and their individual advantages and disadvantages. Cloth: Rarely used in PvP. It is considered too weak for combat, however is a decent choice in a 1v1 scenario due to it\'s high dodge chance. Leather: Leather is often used due to it offering decent protection while still giving the 30 % increase to Archery and Spells Studded: Studded armour is rarely seen in PvP do to its weakness against piercing attacks. This makes the wearer highly susceptible to damage from swords, and pierces can often prove fatal. It has a better dodge rate than chain, and is considered to be more practical against blunt weapons. It also weighs much less than a full chain set, and is much less cumbersome to move speed. Chain: It is easy to make, and its supplies are in abundance in the land of Wurm. It provided a decent amount of armour while not being too restricting to speed. The glance rate is higher than that of studded, and being hit results in lighter wounds. Plate: Plate armour is extremely cumbersome to the player. While it does slow the player down immensely, it has an extremely high glance rate, and damage done the player is greatly reduced. The weight of an entire plate set is over 20kgs, and as such, decreases the overall amount a player can hold. Drake: It is made from the hides of dragon hatchlings. Its glance rate is considered to be higher than that of chain, and it has a considerably higher dodge rate. The entire drake set decreases a players movement only slightly more than the great helm alone. While your chances of dying are reduced in drake, the loss is much greater than if one were to lose chain. Drake is expensive when compared the other armour sets, and cannot be as easily replaced. Scale: Scale is the strongest armour available to players. It offers nearly no movement penalty, and has an extremely high (higher than plate) glance rate. The dodge rate is greater than that of drake, and weighs only slightly more than the drake set. Scale is very rare, and only a few players are seen PvPing in it. Wearing scale gives the player a substantial advantage in PvP. Armour, especially the higher tier armours, are often enchanted with Aura of shared pain or web armour to give an additional advantage to the player. AOSP returns a portion of the damage done to the player, and, just as vitally, adds the hurting status to the enemy. Web armour greatly reduced the movement speed of a player, and allows the person who was hit to retreat or call in their allies to go in for the kill. What enchant one gets on their armour is a matter of preference, although it is easier for BL to get web armour, and WL to get AOSP.', '<p>The current most common armour in PvP is a set of chain or leather armour with <a href=\"/index.php/Web_armour\" title=\"Web armour\">web armour</a> enchant. Other armours are used less frequently, sometimes due to rarity, and sometimes because they are not useful in combat. Below is a list of armours, their frequency of use in PvP, and their individual advantages and disadvantages. \n</p>\n<p><b>Cloth:</b> Rarely used in PvP. It is considered too weak for combat, however is a decent choice in a 1v1 scenario due to it\'s high dodge chance.\n</p>\n<p><b>Leather:</b> Leather is often used due to it offering decent protection while still giving the 30 % increase to <a href=\"/index.php/Archery\" title=\"Archery\">Archery</a> and <a class=\"mw-redirect\" href=\"/index.php/Spells\" title=\"Spells\">Spells</a>\n</p>\n<p><b>Studded:</b> Studded armour is rarely seen in PvP do to its weakness against piercing attacks. This makes the wearer highly susceptible to damage from swords, and pierces can often prove fatal. It has a better dodge rate than chain, and is considered to be more practical against blunt weapons. It also weighs much less than a full chain set, and is much less cumbersome to move speed.  \n</p>\n<p><b>Chain:</b> It is easy to make, and its supplies are in abundance in the land of Wurm. It provided a decent amount of armour while not being too restricting to speed. The glance rate is higher than that of studded, and being hit results in lighter wounds.\n</p>\n<p><b>Plate:</b> Plate armour is extremely cumbersome to the player. While it does slow the player down immensely, it has an extremely high glance rate, and damage done the player is greatly reduced. The weight of an entire plate set is over 20kgs, and as such, decreases the overall amount a player can hold.\n</p>\n<p><b>Drake:</b> It is made from the hides of dragon hatchlings. Its glance rate is considered to be higher than that of chain, and it has a considerably higher dodge rate. The entire drake set decreases a players movement only slightly more than the great helm alone. While your chances of dying are reduced in drake, the loss is much greater than if one were to lose chain. Drake is expensive when compared the other armour sets, and cannot be as easily replaced. \n</p>\n<p><b>Scale:</b> Scale is the strongest armour available to players. It offers nearly no movement penalty, and has an extremely high (higher than plate) glance rate. The dodge rate is greater than that of drake, and weighs only slightly more than the drake set. Scale is very rare, and only a few players are seen PvPing in it. Wearing scale gives the player a substantial advantage in PvP.\n</p>\n<p>Armour, especially the higher tier armours, are often enchanted with <a href=\"/index.php/Aura_of_shared_pain\" title=\"Aura of shared pain\">Aura of shared pain</a> or <a href=\"/index.php/Web_armour\" title=\"Web armour\">web armour</a> to give an additional advantage to the player. AOSP returns a portion of the damage done to the player, and, just as vitally, adds the hurting status to the enemy. Web armour greatly reduced the movement speed of a player, and allows the person who was hit to retreat or call in their allies to go in for the kill. What enchant one gets on their armour is a matter of preference, although it is easier for BL to get web armour, and WL to get AOSP.\n</p>', 3),
(3392, 917, 'Weapons', 'Weapons', 'Like armour, weapons are also a matter of preference in PvP. Some are very rarely used, while others are much more common. It is rare to see duel wielding in PvP. Short Sword: The short sword is rarely seen in PvP. It is does low amounts of damage, but has a high swing rate and is very accurate. It is one handed, and thus can be used with a shield. Longsword: The longsword is one of the more commonly seen weapons in PvP. It has a high parry rate, a four second swing timer, and is fairly accurate. It is considered to be the most standard of all weapons, and used to be one of the only ones used in combat. A longsword is a one handed weapon, and thus can be used with a shield. Two Handed Sword: The two handed sword is occasionally seen in PvP. It hits very hard, but is slower and less accurate than the longsword. It is two handed, and cannot be used with a shield. That being said it has a fair parry rate, and is considered to be the most defensive of the heavier weapons. Small Mauls: Small mauls do slightly less damage than long swords, but hit faster and are more accurate. They also benefit from a higher parry rate. A small maul is a one handed weapon, and thus can be used with a shield. Medium Mauls: Medium mauls deal much more damage than long swords, parry marginally less, and are about the same in terms of accuracy. A medium maul is a one handed weapon, and thus can be used with a shield. Large Mauls: Large mauls are extremely powerful, and can cause massive damage upon hit. They are not frequently seen in PvP, but some into occasional use. They parry less than two handed swords, but deal considerable damage. They are two handed weapons. Small Axes: Rarely used. Low/Medium damage. Low swing timer. One handed. Large Axes: Medium/High damage. Average swing timer. One handed. Has smaller chance to parry than both swords and mauls. Huge Axes: Very high damage. High swing timer. Two handed. Very frequently used in PvP as it is the most hard hitting weapon in the game and an excellent choice if you are not targeted. Polearms: Often used. A hard hitting weapon that\'s frequently used in PvP to take down your opponents horses in which the Spear excels at but Huge axe are often preferred against players since they do more damage.', '<p>Like armour, weapons are also a matter of preference in PvP. Some are very rarely used, while others are much more common. It is rare to see duel wielding in PvP.\n</p>\n<p><b>Short Sword:</b> The short sword is rarely seen in PvP. It is does low amounts of damage, but has a high swing rate and is very accurate. It is one handed, and thus can be used with a shield.\n</p>\n<p><b>Longsword:</b> The longsword is one of the more commonly seen weapons in PvP. It has a high parry rate, a four second swing timer, and is fairly accurate. It is considered to be the most standard of all weapons, and used to be one of the only ones used in combat. A longsword is a one handed weapon, and thus can be used with a shield. \n</p>\n<p><b>Two Handed Sword:</b> The two handed sword is occasionally seen in PvP. It hits very hard, but is slower and less accurate than the longsword. It is two handed, and cannot be used with a shield. That being said it has a fair parry rate, and is considered to be the most defensive of the heavier weapons.\n</p>\n<p><b>Small Mauls:</b> Small mauls do slightly less damage than long swords, but hit faster and are more accurate. They also benefit from a higher parry rate. A small maul is a one handed weapon, and thus can be used with a shield.\n</p>\n<p><b>Medium Mauls:</b> Medium mauls deal much more damage than long swords, parry marginally less, and are about the same in terms of accuracy. A medium maul is a one handed weapon, and thus can be used with a shield. \n</p>\n<p><b>Large Mauls:</b> Large mauls are extremely powerful, and can cause massive damage upon hit. They are not frequently seen in PvP, but some into occasional use. They parry less than two handed swords, but deal considerable damage. They are two handed weapons.\n</p>\n<p><b>Small Axes:</b> Rarely used. Low/Medium damage. Low swing timer. One handed.\n</p>\n<p><b>Large Axes:</b> Medium/High damage. Average swing timer. One handed. Has smaller chance to parry than both swords and mauls. \n</p>\n<p><b>Huge Axes:</b> Very high damage. High swing timer. Two handed. Very frequently used in PvP as it is the most hard hitting weapon in the game and an excellent choice if you are not targeted. \n</p>\n<p><b>Polearms:</b> Often used. A hard hitting weapon that\'s frequently used in PvP to take down your opponents horses in which the <a href=\"/index.php/Spear\" title=\"Spear\">Spear</a> excels at but <a href=\"/index.php/Huge_axe\" title=\"Huge axe\">Huge axe</a> are often preferred against players since they do more damage.\n</p>', 4),
(3393, 917, 'Weapon Enchants', 'Weapon_Enchants', 'A high caliber PvP weapon will have around three to four, high power enchants, although they can be quite difficult to obtain. Here are the most commonly used: Humans Demise: Increased chance to hit against humanoids (players). Most frequently found on PvP weapons. Has no cast power, just passive effect. Wind of Ages/Blessings of the Dark: Recent changes have made high power cast of this less necessary. Having over 50 will assure maximum swing timer. Blessing of the Dark also gives increase to weapon skill gained, although this itself is not necessary for PvP. Flaming Aura: Deals an additional fire wound to players equal to (power/3)% of the hit. (99/3 = 33%) (30 damage gives +10 damage burn wound). Frost Brand: The Vynora equivalent of Flaming Aura but causes a frost wound. Rotting Touch: Causes infection wounds that get worse over time, and need special care to be healed. Higher power generates increasingly dire wounds. Instead of adding more wounds Rotting Touch increases the damage of for example the cut done by a sword. Life Transfer: Used many time in PvP. Does no extra damage, but heals the player when they strike another player or creature. The quantity of wounds being healed depends on damage done. Venom: Causes poison wounds that can only be healed with farmer\'s salves. Ignoring these wounds can result in instant death. Striking with a Weapon with Venom also can not glance. Salve: Converts the entire wound that you cause to a single element wound and can be buffed with Glacial to further increase its damage.', '<p>A high caliber PvP weapon will have around three to four, high power enchants, although they can be quite difficult to obtain. Here are the most commonly used:\n</p>\n<p><b>Humans Demise:</b> Increased chance to hit against humanoids (players). Most frequently found on PvP weapons. Has no cast power, just passive effect.\n</p>\n<p><b>Wind of Ages/Blessings of the Dark:</b> Recent changes have made high power cast of this less necessary. Having over 50 will assure maximum swing timer. Blessing of the Dark also gives increase to weapon skill gained, although this itself is not necessary for PvP. \n</p>\n<p><b>Flaming Aura:</b> Deals an additional fire wound to players equal to (power/3)% of the hit. (99/3 = 33%) (30 damage gives +10 damage burn wound). \n</p>\n<p><b>Frost Brand:</b> The Vynora equivalent of Flaming Aura but causes a frost wound.\n</p>\n<p><b>Rotting Touch:</b> Causes infection wounds that get worse over time, and need special care to be healed. Higher power generates increasingly dire wounds. Instead of adding more wounds Rotting Touch increases the damage of for example the cut done by a sword.\n</p>\n<p><b>Life Transfer:</b> Used many time in PvP. Does no extra damage, but heals the player when they strike another player or creature. The quantity of wounds being healed depends on damage done.\n</p>\n<p><b>Venom:</b> Causes poison wounds that can only be healed with farmer\'s salves. Ignoring these wounds can result in instant death. Striking with a Weapon with <a href=\"/index.php/Venom\" title=\"Venom\">Venom</a> also can not glance.\n</p>\n<p><b>Salve:</b> Converts the entire wound that you cause to a single element wound and can be buffed with <a href=\"/index.php/Glacial\" title=\"Glacial\">Glacial</a> to further increase its damage.\n</p>', 5),
(3394, 917, 'Tactics', 'Tactics', 'Tactics are the core of PvP. Different sides will develop their own tactics, and individual players will develop their own fighting styles and preferences. Decision making is a key part of PvP, and weighs heavily on the success of the players involved. There are a few things that are commonly agreed upon, such as taking height advantage, and focusing in one x one encounters. Different parts of the body are often aimed at to cripple or impair the enemy, and opponents are singled out based on their strength and current position in combat. PvP is often a group effort, and so organized tactics are often developed. Below is a list of things that are often considered in one on one combat. Height Advantage: Being a significant distance above the player gives you height advantage. This adds to your combat rating, and thus increases your chance to hit and your general effectiveness in combat. Falling into a pit can be deadly, as a player must climb out with the enemy on them, while suffering from decreased combat rating do to moving, poor footing, and being beneath their enemy. Height advantage can also be gained by riding a horse, although engaging an enemy with a horse that is unequipped with barding could prove fatal to the animal. Movement: Most likely players will be moving frequently when engaged in one on one combat. They will be seeking height advantage, and attempting to get behind the other player. Moving increases your chance to be hit, so this too must be considered while fighting. Flanking Bonus (for being behind players): If you are behind a player, you have a greatly increased chance to hit. If it is possible, it is advised to be behind your enemy as much as possible. This is sometimes too difficult to do however, and can be considered an opportunity more than a tactic. Pets: Having a pet in combat (usually a troll or crocodile) will give you what is known as \'gank bonus\'. This greatly increases your chance to hit, and the chance of your pet hitting. Aiming: Aiming for any spot besides the torso decreases your chance to hit the player, however the torso is also the most resistant of all body parts. While you may land more hits, they will each do considerably less damage than hits to anywhere else on the body. When chasing someone down, people generally aim for the feet/calves, which will cause the greatest slow down in movement speed. If the player is not wearing a helm, the head is often aimed for, as a single powerful shot may kill them if it hits their unprotected face. When no obvious weak spots are present, players will normally aim for whatever piece of armour they think is weakest. Focusing: Each level of focus grants a +1 bonus to CR. This is the equivalent of 5 levels of fight skill in PvP. In one on one combat, it is highly recommended that you focus, in order to gain the upper hand in the fight. If one player gets to high focus, whoever gets the first hit in will often be the victor, as the they will immediately be in a position of power. Focusing takes four seconds, and the player is more vulnerable during this time. If you out focus your enemy, it is arguable that the disadvantage is made up for by the levels of focus already gained.', '<p>Tactics are the core of PvP. Different sides will develop their own tactics, and individual players will develop their own fighting styles and preferences. Decision making is a key part of PvP, and weighs heavily on the success of the players involved. There are a few things that are commonly agreed upon, such as taking height advantage, and focusing in one x one encounters. Different parts of the body are often aimed at to cripple or impair the enemy, and opponents are singled out based on their strength and current position in combat. PvP is often a group effort, and so organized tactics are often developed. Below is a list of things that are often considered in one on one combat. \n</p>\n<p><b>Height Advantage:</b> Being a significant distance above the player gives you height advantage. This adds to your combat rating, and thus increases your chance to hit and your general effectiveness in combat. Falling into a pit can be deadly, as a player must climb out with the enemy on them, while suffering from decreased combat rating do to moving, poor footing, and being beneath their enemy. Height advantage can also be gained by riding a horse, although engaging an enemy with a horse that is unequipped with barding could prove fatal to the animal.\n</p>\n<p><b>Movement:</b> Most likely players will be moving frequently when engaged in one on one combat. They will be seeking height advantage, and attempting to get behind the other player. Moving increases your chance to be hit, so this too must be considered while fighting.\n</p>\n<p><b>Flanking Bonus (for being behind players):</b> If you are behind a player, you have a greatly increased chance to hit. If it is possible, it is advised to be behind your enemy as much as possible. This is sometimes too difficult to do however, and can be considered an opportunity more than a tactic. \n</p>\n<p><b>Pets:</b> Having a pet in combat (usually a troll or crocodile) will give you what is known as \'gank bonus\'. This greatly increases your chance to hit, and the chance of your pet hitting. \n</p>\n<p><b>Aiming:</b> Aiming for any spot besides the torso decreases your chance to hit the player, however the torso is also the most resistant of all body parts. While you may land more hits, they will each do considerably less damage than hits to anywhere else on the body. When chasing someone down, people generally aim for the feet/calves, which will cause the greatest slow down in movement speed. If the player is not wearing a helm, the head is often aimed for, as a single powerful shot may kill them if it hits their unprotected face. When no obvious weak spots are present, players will normally aim for whatever piece of armour they think is weakest. \n</p>\n<p><br/>\n<b>Focusing:</b> Each level of focus grants a +1 bonus to CR. This is the equivalent of 5 levels of fight skill in PvP. In one on one combat, it is highly recommended that you focus, in order to gain the upper hand in the fight. If one player gets to high focus, whoever gets the first hit in will often be the victor, as the they will immediately be in a position of power. Focusing takes four seconds, and the player is more vulnerable during this time. If you out focus your enemy, it is arguable that the disadvantage is made up for by the levels of focus already gained.\n</p>', 6),
(3400, 920, 'Description', 'Description', 'This small metal lump should be attached to a small ceremonial bell and make tingeling.', '<p><i>This small metal lump should be attached to a small ceremonial bell and make tingeling.</i>\n</p>', 0),
(3401, 920, 'Usage', 'Usage', 'A Tiny clapper is used with a small resonator to create a small bell .', '<p>A <b>Tiny clapper</b> is used with a <a href=\"/index.php/Small_resonator\" title=\"Small resonator\">small resonator</a> to create a <a href=\"/index.php/Small_bell\" title=\"Small bell\">small bell</a>.\n</p>', 1),
(3439, 930, 'Description', 'Description', 'A bell cot with a huge bell hanging inside. It will make a powerful sound when rang.', '<p><i>A bell cot with a huge bell hanging inside. It will make a powerful sound when rang.</i>\n</p>', 0),
(3440, 930, 'Usage', 'Usage', 'Right click > use will start swinging the bell on a 1 minute timer that can be stopped with Esc . Plays a bell sound in local area on use. The quality level of the bell tower affects the tone of the bell when rung. <30 ql (lowest tone) 30 - 49.99 ql 50 - 69.99 ql 70+ ql The tones for the different quality levels correspond to B, E, F# and A', '<ul><li>Right click &gt; use will start swinging the bell on a 1 minute timer that can be stopped with <style data-mw-deduplicate=\"TemplateStyles:r120109\">.mw-parser-output .key{border:1px solid #aaa;border-radius:2px;box-shadow:1px 2px 2px #ddd;background-color:#f9f9f9;background-image:linear-gradient(to top,#eee,#f9f9f9,#eee);padding:1px 3px;font-family:inherit;font-size:0.85em}</style></li></ul>\n<p><span class=\"key\">Esc</span>.\n</p>\n<ul><li>Plays a bell sound in local area on use.</li>\n<li>The quality level of the bell tower affects the tone of the bell when rung.\n<ul><li>&lt;30 ql (lowest tone)</li>\n<li>30 - 49.99 ql</li>\n<li>50 - 69.99 ql</li>\n<li>70+ ql</li></ul></li>\n<li>The tones for the different quality levels correspond to B, E, F# and A</li></ul>', 1),
(3441, 930, 'Notes', 'Notes', 'The QL of the huge bell affects creation chance. The bell tower will remain in inventory upon creation, however, once dropped or placed, it cannot be picked up and held in the inventory again. Loading requires a wagon.', '<ul><li>The <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> of the <a href=\"/index.php/Huge_bell\" title=\"Huge bell\">huge bell</a> affects creation chance.</li>\n<li>The bell tower will remain in inventory upon creation, however, once dropped or placed, it cannot be picked up and held in the inventory again.</li>\n<li>Loading requires a wagon.</li></ul>', 2),
(3445, 931, 'Description', 'Description', 'A huge bell that can be put in a cot to ring when celebrating or at a ceremony.', '<p><i>A huge bell that can be put in a cot to ring when celebrating or at a ceremony.</i>\n</p>', 0),
(3446, 931, 'Usage', 'Usage', 'Used in construction of a bell tower when attached to a bell cot .', '<ul><li>Used in construction of a <a href=\"/index.php/Bell_tower\" title=\"Bell tower\">bell tower</a> when attached to a <a href=\"/index.php/Bell_cot\" title=\"Bell cot\">bell cot</a>.</li></ul>', 1),
(3447, 931, 'Notes', 'Notes', 'The large clapper and large bell resonator must be glowing hot to create. The QL of the large clapper influences the chance of making it.', '<ul><li>The <a href=\"/index.php/Large_clapper\" title=\"Large clapper\">large clapper</a> and <a href=\"/index.php/Large_bell_resonator\" title=\"Large bell resonator\">large bell resonator</a> must be glowing hot to create.</li>\n<li>The <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> of the large clapper influences the chance of making it.</li></ul>', 2),
(3448, 933, 'Description', 'Description', 'This is the framework where a huge bell should hang.', '<p><i>This is the framework where a huge bell should hang.</i>\n</p>', 0),
(3449, 933, 'Usage', 'Usage', 'Used in construction of a bell tower when attached to a huge bell .', '<ul><li>Used in construction of a <a href=\"/index.php/Bell_tower\" title=\"Bell tower\">bell tower</a> when attached to a <a href=\"/index.php/Huge_bell\" title=\"Huge bell\">huge bell</a>.</li></ul>', 1),
(3450, 933, 'Notes', 'Notes', 'The wood type is dictated by the wood type of the last wooden item attached.', '<ul><li>The <a href=\"/index.php/Wood\" title=\"Wood\">wood</a> type is dictated by the wood type of the last wooden item attached.</li></ul>', 2),
(3455, 935, 'Description', 'Description', 'A small hand held bell that will make a pleasant tingeling sound to summon spirits.', '<p><i>A small hand held bell that will make a pleasant tingeling sound to summon spirits.</i>\n</p>', 0),
(3456, 935, 'Notes', 'Notes', 'Makes a ringing sound when used. The metal type of the small resonator determines the final metal type of the completed small bell.', '<ul><li>Makes a ringing sound when used.</li>\n<li>The metal type of the <a href=\"/index.php/Small_resonator\" title=\"Small resonator\">small resonator</a> determines the final metal type of the completed small bell.</li></ul>', 1),
(3457, 921, 'Description', 'Description', 'The resonator part of a huge bell. It still needs a clapper if it\'s going to make a sound.', '<p><i>The resonator part of a huge bell. It still needs a clapper if it\'s going to make a sound.</i>\n</p>', 0),
(3458, 921, 'Notes', 'Notes', 'Used with a Large Clapper to make a Huge bell On failure, 0.5kg of the lump is lost.', '<ul><li>Used with a <a class=\"mw-redirect\" href=\"/index.php/Large_Clapper\" title=\"Large Clapper\">Large Clapper</a> to make a <a href=\"/index.php/Huge_bell\" title=\"Huge bell\">Huge bell</a></li>\n<li>On failure, 0.5kg of the lump is lost.</li></ul>', 1),
(3459, 925, 'Description', 'Description', 'The resonator of small hand held bell. It still needs a clapper.', '<p><i>The resonator of small hand held bell. It still needs a clapper.</i>\n</p>', 0),
(3460, 925, 'Usage', 'Usage', 'Used together with a tiny clapper to create a small bell .', '<ul><li>Used together with a <a href=\"/index.php/Tiny_clapper\" title=\"Tiny clapper\">tiny clapper</a> to create a <a href=\"/index.php/Small_bell\" title=\"Small bell\">small bell</a>.</li></ul>', 1),
(3461, 934, 'Description', 'Description', 'This is a lump of metal designed to hang in a large bell and make ding dong.', '<p><i>This is a lump of metal designed to hang in a large bell and make ding dong.</i>\n</p>', 0),
(3462, 934, 'Usage', 'Usage', 'Used to construct a huge bell when attached to a large bell resonator .', '<ul><li>Used to construct a <a href=\"/index.php/Huge_bell\" title=\"Huge bell\">huge bell</a> when attached to a <a href=\"/index.php/Large_bell_resonator\" title=\"Large bell resonator\">large bell resonator</a>.</li></ul>', 1),
(3480, 945, 'Description', 'Description', 'A nice Greek looking pillar. The pillar is of the Ionic type.', '<p><i>A nice Greek looking pillar. The pillar is of the Ionic type.</i>\n</p>', 0),
(3481, 945, 'Notes', 'Notes', 'The brick quality level (QL) determines the success rate. Material types include stone, marble, slate and sandstone. This item is not a Foundation pillar as sometimes requested in missions, when the player will be asked to create a Foundation pillar in a mine with differing details. Can be loaded into knarr and larger vessels, but not carts or wagons. Cannot be dyed. Cannot be continued indoors, however it can be pushed inside. Can be created using stone brick , marble brick , sandstone brick , or slate brick .', '<ul><li>The brick quality level (QL) determines the success rate.</li>\n<li>Material types include stone, marble, slate and sandstone.</li>\n<li>This item is not a <a href=\"/index.php/Foundation_pillar\" title=\"Foundation pillar\">Foundation pillar</a> as sometimes requested in missions, when the player will be asked to create a Foundation pillar in a mine with differing details.</li>\n<li>Can be loaded into knarr and larger vessels, but not carts or wagons.</li>\n<li>Cannot be dyed.</li>\n<li>Cannot be continued indoors, however it can be pushed inside.</li>\n<li>Can be created using <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">stone brick</a>, <a href=\"/index.php/Marble_brick\" title=\"Marble brick\">marble brick</a>, <a href=\"/index.php/Sandstone_brick\" title=\"Sandstone brick\">sandstone brick</a>, or <a href=\"/index.php/Slate_brick\" title=\"Slate brick\">slate brick</a>.</li></ul>', 1);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(3514, 952, 'Description', 'Description', 'Uttacha is a vengeful demigod who lives in the depths of an ocean on Valrei. These huge larvae are hungry and confused abominations here. Spawned by the Gods on Valrei . [11:37:17] Vynora lets loose the Spawn of Uttachas. Acid based attacks and will use AOE\'s hurting nearby players and animals Random Valrei items from butchering may include: Charming Feather Charming Opal Charming totem Golden Strand Powerful quill Powerful Corpse Powerful Opal Shadow totem Shiny Jewel Silvery Circlet Wild diamond Wild opal These items are only different by their name, which seems to be a random combination out of a pool of names.', '<p><i>Uttacha is a vengeful demigod who lives in the depths of an ocean on Valrei. These huge larvae are hungry and confused abominations here. </i>\n</p>\n<p>Spawned by the Gods on <a href=\"/index.php/Valrei_(moon)\" title=\"Valrei (moon)\">Valrei</a>.\n</p>\n<p>[11:37:17] Vynora lets loose the Spawn of Uttachas.\n</p>\n<ul><li>Acid based attacks and will use AOE\'s hurting nearby players and animals</li></ul>\n<p><br/>\nRandom <a href=\"/index.php/Valrei_item\" title=\"Valrei item\">Valrei items</a> from butchering may include:\n</p>\n<ul><li>Charming Feather</li>\n<li>Charming Opal</li>\n<li>Charming totem</li>\n<li>Golden Strand</li>\n<li>Powerful quill</li>\n<li>Powerful Corpse</li>\n<li>Powerful Opal</li>\n<li>Shadow totem</li>\n<li>Shiny Jewel</li>\n<li>Silvery Circlet</li>\n<li>Wild diamond</li>\n<li>Wild opal</li></ul>\n<p>These items are only different by their name, which seems to be a random combination out of a pool of names.\n</p>', 0),
(3515, 952, 'Notes', 'Notes', 'Upon death spawn of uttacha explodes and reforms into smaller versions of itself. The third and final form will yield the corpse.', '<ul><li>Upon death spawn of uttacha explodes and reforms into smaller versions of itself.</li>\n<li>The third and final form will yield the corpse.</li></ul>', 1),
(3519, 956, '111221 Merry Christmas!', '111221_Merry_Christmas.21', 'These updates arrive together with some Merry Christmas wishes to all Wurmians: A bug was found with the visited places on the epic map, and deities should move around the map more properly now. Build, sacrifice and cut down missions on on Epic wild are more meaningful. You should now see enemy missions as well. The bug where the Lady of the Lake was invisible was fixed. A note regarding epic missions until incentives and rewards are improved further: The spirit bonuses refer to +5% Favor gain, +10% Stamina gain, +1 CR, and +5% movement rate. These effects may be transferred to your deity when he or she is \'helped\'. They are reset upon scenario completion.', '<p>These updates arrive together with some Merry Christmas wishes to all Wurmians:\n</p>\n<ul><li>A bug was found with the visited places on the epic map, and deities should move around the map more properly now.</li>\n<li>Build, sacrifice and cut down missions on on Epic wild are more meaningful.</li>\n<li>You should now see enemy missions as well.</li>\n<li>The bug where the Lady of the Lake was invisible was fixed.</li>\n<li>A note regarding epic missions until incentives and rewards are improved further: The spirit bonuses refer to +5% Favor gain, +10% Stamina gain, +1 CR, and +5% movement rate. These effects may be transferred to your deity when he or she is \'helped\'. They are reset upon scenario completion.</li></ul>', 0),
(3520, 956, '111219 Wild joining the freedom cluster', '111219_Wild_joining_the_freedom_cluster', 'The old wild server has joined the freedom cluster in order to keep it attractive. The server will be referred to as Chaos from now on. It is now free to play and no longer requires a premium account. You may travel freely from the other servers to the wild server and back via the western freedom borders. The portals have been removed. Players on the server have been converted to the Freedom Isles kingdom. Chaos is a PvP home server which means you can be attacked by other players although they will receive a reputation hit. You may engage in village wars in order to avoid such penalties. There are discussions on how to make PvP more enjoyable and interesting on the server in the future using a modified alliance system. Note regarding travel to or from Chaos: Your inventorys should merge flawlessly but you may wear double sets of armour pieces on your body after the initial transfer. Settlement guards will now hunt in the closest perimeter of a settlement A bug where archery was possible into structures at long distance was fixed A bug with stealing not triggering guards properly was fixed and some skills reversed A bug with converting religion was fixed', '<ul><li>The old wild server has joined the freedom cluster in order to keep it attractive. The server will be referred to as Chaos from now on. It is now free to play and no longer requires a premium account. You may travel freely from the other servers to the wild server and back via the western freedom borders. The portals have been removed.</li>\n<li>Players on the server have been converted to the Freedom Isles kingdom. Chaos is a PvP home server which means you can be attacked by other players although they will receive a reputation hit. You may engage in village wars in order to avoid such penalties. There are discussions on how to make PvP more enjoyable and interesting on the server in the future using a modified alliance system.</li>\n<li>Note regarding travel to or from Chaos: Your inventorys should merge flawlessly but you may wear double sets of armour pieces on your body after the initial transfer.</li>\n<li>Settlement guards will now hunt in the closest perimeter of a settlement</li>\n<li>A bug where archery was possible into structures at long distance was fixed</li>\n<li>A bug with stealing not triggering guards properly was fixed and some skills reversed</li>\n<li>A bug with converting religion was fixed</li></ul>', 1),
(3521, 956, '111216 Minor change to ganking', '111216_Minor_change_to_ganking', 'The difficulty when parrying is no longer affected by the number of attackers which should reduce the effect of ganking somewhat. This will affect monsters as well.', '<ul><li>The difficulty when parrying is no longer affected by the number of attackers which should reduce the effect of ganking somewhat. This will affect monsters as well.</li></ul>', 2),
(3522, 956, '111214 Wound treatment ease plus slew of fixes', '111214_Wound_treatment_ease_plus_slew_of_fixes', 'Treating wounds now have a minimum 20% chance to succeed Fixed a bug with Crown of Might influence Uniques no longer harm each other with combat moves and creatures may also lose loyalty when attacking other uniques. Drake armour now use material as intended when improving instead of taking damage, which was a serious bug. Because of this, existing dragon armour was sacrificed on Elevation and new dragons spawned. Flatraising was not properly limited on Epic whereas digging was which caused problems. Both are now brought in line. Fixed a bug with enchants carrying over servers. Inactive affinities were lost when changing servers. Fixed.', '<ul><li>Treating wounds now have a minimum 20% chance to succeed</li>\n<li>Fixed a bug with Crown of Might influence</li>\n<li>Uniques no longer harm each other with combat moves and creatures may also lose loyalty when attacking other uniques.</li>\n<li>Drake armour now use material as intended when improving instead of taking damage, which was a serious bug.</li>\n<li>Because of this, existing dragon armour was sacrificed on Elevation and new dragons spawned.</li>\n<li>Flatraising was not properly limited on Epic whereas digging was which caused problems. Both are now brought in line.</li>\n<li>Fixed a bug with enchants carrying over servers.</li>\n<li>Inactive affinities were lost when changing servers. Fixed.</li></ul>', 3),
(3523, 956, '111209 More Epic balancing', '111209_More_Epic_balancing', 'You should now be able to log on inside locked structures if you are allowed to enter them because you\'re a villager or ally. You were allowed to recruit a citizen too many, resulting in double upkeep in certain instances. You should verify if you\'re on the limit. Because of abuse, HOTS is no longer allowed to change kingdom more than once per month. It will be doubled if keeps getting abused. Lockpicking no longer follows the curve since it was deemed overpowered. More kingdom defense creatures should spawn.', '<ul><li>You should now be able to log on inside locked structures if you are allowed to enter them because you\'re a villager or ally.</li>\n<li>You were allowed to recruit a citizen too many, resulting in double upkeep in certain instances. You should verify if you\'re on the limit.</li>\n<li>Because of abuse, HOTS is no longer allowed to change kingdom more than once per month. It will be doubled if keeps getting abused.</li>\n<li>Lockpicking no longer follows the curve since it was deemed overpowered.</li>\n<li>More kingdom defense creatures should spawn.</li></ul>', 4),
(3524, 956, '111205 Weekend bug reports', '111205_Weekend_bug_reports', 'Attacking same side on Epic home servers should no longer give automatic skill penalties but the expected reputation hit. Changed some issues with creature movement code. Bell part mappings fixed. Prospecting on Epic home server surface should now give more proper results. Epic skill levels: Archery and Bow skills should again be easier to increase during target practice. Aiming with the bow will now be properly limited by real and not effective skill. The Lore option is now properly displayed at 10 skill. A note about building Epic target items such as Foundation pillars: The person who finished the pillar may have to push it off and on the placement tile for the trigger mechanism to work. Finger of Fo and Rod of Beguiling used to work only for Fo priests but now works for every faith in order to increase their usage. You should now receive some (30 minutes) sleep bonus when you have participated in an Epic mission that is finished. Make sure you haven\'t reached the limit.', '<ul><li>Attacking same side on Epic home servers should no longer give automatic skill penalties but the expected reputation hit.</li>\n<li>Changed some issues with creature movement code.</li>\n<li>Bell part mappings fixed.</li>\n<li>Prospecting on Epic home server surface should now give more proper results.</li>\n<li>Epic skill levels: Archery and Bow skills should again be easier to increase during target practice. Aiming with the bow will now be properly limited by real and not effective skill. The Lore option is now properly displayed at 10 skill.</li>\n<li>A note about building Epic target items such as Foundation pillars: The person who finished the pillar may have to push it off and on the placement tile for the trigger mechanism to work.</li>\n<li>Finger of Fo and Rod of Beguiling used to work only for Fo priests but now works for every faith in order to increase their usage.</li>\n<li>You should now receive some (30 minutes) sleep bonus when you have participated in an Epic mission that is finished. Make sure you haven\'t reached the limit.</li></ul>', 5),
(3525, 956, '111130 A slew of small bugs', '111130_A_slew_of_small_bugs', 'Creature slay missions should now update more properly. Fixed a bug with collectibles on the Valrei map. Fixed a bug where changing settings in a kingdom didn\'t propagate properly to other servers The /transfer function on Wild was disabled pending what to do with it. It was also rare and considered an exploit by alt characters nowadays. A bug that set your kingdom to Freedom Isles when leaving Epic via portals to Wild was fixed', '<ul><li>Creature slay missions should now update more properly.</li>\n<li>Fixed a bug with collectibles on the Valrei map.</li>\n<li>Fixed a bug where changing settings in a kingdom didn\'t propagate properly to other servers</li>\n<li>The /transfer function on Wild was disabled pending what to do with it. It was also rare and considered an exploit by alt characters nowadays.</li>\n<li>A bug that set your kingdom to Freedom Isles when leaving Epic via portals to Wild was fixed</li></ul>', 6),
(3526, 956, '111125 Minor mission bugfixes', '111125_Minor_mission_bugfixes', '\"Give\" missions should now work properly and not make the receiver go away after the first item\" \"Sacrifice\" missions should now properly verify that the item you are to sacrifice fits in a normal altar.', '<ul><li>\"Give\" missions should now work properly and not make the receiver go away after the first item\"</li>\n<li>\"Sacrifice\" missions should now properly verify that the item you are to sacrifice fits in a normal altar.</li></ul>', 7),
(3527, 956, '111123 Epic balancing', '111123_Epic_balancing', 'Some changes on the Epic servers: Imping dragon armour now requires Drake Hide or Scale and not leather. You may no longer target enemy deeds with aggressive pets. You have to ride onto the deeds on them if you want to bring them. Already in this update on Epic, and upcoming change on the other servers: When you drop the Crown of Might or Charm of Fo, your pet will no longer be charmed or dominated. The creature will stay in a confused state a while.', '<ul><li>Some changes on the Epic servers:</li></ul>\n<ol><li>Imping dragon armour now requires Drake Hide or Scale and not leather.</li>\n<li>You may no longer target enemy deeds with aggressive pets. You have to ride onto the deeds on them if you want to bring them.</li></ol>\n<ul><li>Already in this update on Epic, and upcoming change on the other servers:</li></ul>\n<ol><li>When you drop the Crown of Might or Charm of Fo, your pet will no longer be charmed or dominated. The creature will stay in a confused state a while.</li></ol>', 8),
(3528, 956, '111122 Official map release', '111122_Official_map_release', 'The most recent Wurm maps have been officially released. You don\'t have to look! You can find them at http://www.wlhost.net/view.php . Thanks Mike! The bug to where your fightskill could drop to 1 if it was below 10 was fixed.', '<ul><li>The most recent Wurm maps have been officially released. You don\'t have to look! You can find them at <a class=\"external free\" href=\"http://www.wlhost.net/view.php\" rel=\"nofollow\">http://www.wlhost.net/view.php</a>. Thanks Mike!</li>\n<li>The bug to where your fightskill could drop to 1 if it was below 10 was fixed.</li></ul>\n<p><br/>\n</p>', 9),
(3529, 956, '111121 Epic Home Server improvements', '111121_Epic_Home_Server_improvements', 'A few steps were taken to make the situation better for newbies on the Epic home servers: The limit where no fighting skill is awarded was raised from \"real\" 2 to 10 The quality level of Iron Ore is now unlimited on Epic home servers in order to make it more attractive to stay and defend for premiums. Starter deeds will receive a lot better protection soon. They are supposed to be very safe and barely raidable. PvP is enabled for same side kingdom in order for people to be able to deal with spies and griefers. You will receive a reputation, skill and alignment hit but it may be desirable at times.', '<ul><li>A few steps were taken to make the situation better for newbies on the Epic home servers:</li></ul>\n<ol><li>The limit where no fighting skill is awarded was raised from \"real\" 2 to 10</li>\n<li>The quality level of Iron Ore is now unlimited on Epic home servers in order to make it more attractive to stay and defend for premiums.</li>\n<li>Starter deeds will receive a lot better protection soon. They are supposed to be very safe and barely raidable.</li>\n<li>PvP is enabled for same side kingdom in order for people to be able to deal with spies and griefers. You will receive a reputation, skill and alignment hit but it may be desirable at times.</li></ol>\n<p><br/>\n</p>', 10),
(3530, 956, '111121 Shutdown bugfix', '111121_Shutdown_bugfix', 'Epic portals are now destroyable Minimum time that a deity may stay in a normal hex was lowered to 6 hours. The delay until it enters the next hex is now 2 hours. Maximum time a deity stays in a non-trap hex was raised to 3 days. You should now be able to destroy structures held by enemy players on Epic home servers. The bug that made Exodus shut down this friday and Elevation today was fixed in this update.', '<ul><li>Epic portals are now destroyable</li>\n<li>Minimum time that a deity may stay in a normal hex was lowered to 6 hours. The delay until it enters the next hex is now 2 hours. Maximum time a deity stays in a non-trap hex was raised to 3 days.</li>\n<li>You should now be able to destroy structures held by enemy players on Epic home servers.</li>\n<li>The bug that made Exodus shut down this friday and Elevation today was fixed in this update.</li></ul>\n<p><br/>\n</p>', 11),
(3531, 956, '111118 Mission tweaks', '111118_Mission_tweaks', 'If a deity receives help it now will receive a bonus to attack if fighting. Note that two successful missions are required in order to help your deity at the moment - one on epic wild and one on the home server. \"Decent\" quality level for missions was increased to 30. Epic home servers may now receive drain or ritual missions for tokens and guard towers of enemy kingdoms. There is now a new type of mission where special items spawned on the server may have to be found and sacrificed. The feature that prevented house walls from being destroyed on Epic Home servers was removed. Let\'s not call it a bug.', '<ul><li>If a deity receives help it now will receive a bonus to attack if fighting. Note that two successful missions are required in order to help your deity at the moment - one on epic wild and one on the home server.</li>\n<li>\"Decent\" quality level for missions was increased to 30.</li>\n<li>Epic home servers may now receive drain or ritual missions for tokens and guard towers of enemy kingdoms.</li>\n<li>There is now a new type of mission where special items spawned on the server may have to be found and sacrificed.</li>\n<li>The feature that prevented house walls from being destroyed on Epic Home servers was removed. Let\'s not call it a bug.</li></ul>\n<p><br/>\n</p>', 12),
(3532, 956, '111116 Curve tweaks', '111116_Curve_tweaks', 'The Curve was applied to Combat Rating versus both players and creatures which was unintended. The Curve effect was removed versus creatures. Note that this has effect on deed and kingdom tower guards. Might need further tweaking so bear with the situation please. The penalties for visiting enemy home servers were made less severe again because of this. Other limitations that the curve should not be applied to were found such as meditation, prospecting and archery. The curve is not supposed to affect hard limits but the effect of your skill. Surface mining limits were also affected on Epic. We are going to discuss surface mining and the digging limits in the forums so this is subject to change. Kingdom tower guard spawns should now be properly limited. You will have to kill surplus guards. We are looking at making creatures move a bit smoother and it\'s possible you see some changes today already. Zombie infestation received a cooldown of half an hour.', '<ul><li>The Curve was applied to Combat Rating versus both players and creatures which was unintended.</li>\n<li>The Curve effect was removed versus creatures. Note that this has effect on deed and kingdom tower guards. Might need further tweaking so bear with the situation please.</li>\n<li>The penalties for visiting enemy home servers were made less severe again because of this.</li>\n<li>Other limitations that the curve should not be applied to were found such as meditation, prospecting and archery. The curve is not supposed to affect hard limits but the effect of your skill.</li>\n<li>Surface mining limits were also affected on Epic. We are going to discuss surface mining and the digging limits in the forums so this is subject to change.</li>\n<li>Kingdom tower guard spawns should now be properly limited. You will have to kill surplus guards.</li>\n<li>We are looking at making creatures move a bit smoother and it\'s possible you see some changes today already.</li>\n<li>Zombie infestation received a cooldown of half an hour.</li></ul>', 13),
(3533, 956, '111111 Sermon and limit tweaks', '111111_Sermon_and_limit_tweaks', 'Sermons give more faith again and even for less followers now Tree names in missions are now correct Deities on Valrei moves faster Large cart speeds are returned to normal Farming output quality was returned to the curve algorithm on the Epic servers The limits such as farming yield and slope digging is supposed to work on actual skill and not the curved value. The skillgain speed increase on Epic is supposed to suffice for this.', '<ul><li>Sermons give more faith again and even for less followers now</li>\n<li>Tree names in missions are now correct</li>\n<li>Deities on Valrei moves faster</li>\n<li>Large cart speeds are returned to normal</li>\n<li>Farming output quality was returned to the curve algorithm on the Epic servers</li>\n<li>The limits such as farming yield and slope digging is supposed to work on actual skill and not the curved value. The skillgain speed increase on Epic is supposed to suffice for this.</li></ul>', 14),
(3534, 956, '111110 Successful Epic debugging', '111110_Successful_Epic_debugging', 'Epic code has been seriously debugged. Old missions had to be removed. Certain skill limitations unintentionally used the curve such as for building. Huge Bell weights and sizes were brought into order. Large cart max speed was reduced 30%. Kingdom converts were reset. Steel has more use and reduces item damage somewhat. Enemy home server penalty was increased Epic guards now gank like before Custom kingdoms that were lost on home servers should work again. Requirements were lowered in order to take the kingdom ruler tests.', '<ul><li>Epic code has been seriously debugged. Old missions had to be removed.</li>\n<li>Certain skill limitations unintentionally used the curve such as for building.</li>\n<li>Huge Bell weights and sizes were brought into order.</li>\n<li>Large cart max speed was reduced 30%.</li>\n<li>Kingdom converts were reset.</li>\n<li>Steel has more use and reduces item damage somewhat.</li>\n<li>Enemy home server penalty was increased</li>\n<li>Epic guards now gank like before</li>\n<li>Custom kingdoms that were lost on home servers should work again.</li>\n<li>Requirements were lowered in order to take the kingdom ruler tests.</li></ul>', 15),
(3535, 956, '111101 Epic mission progress', '111101_Epic_mission_progress', 'The Epic missions still have some issues but some may work better now. We\'ll be sorting out the remaining issues soon. HOTS players received negative Combat Rating on their own home server. Fixed. There are now twitter feeds for the new Epic servers: www.twitter.com/epicserv1 ,epicserv2, epicserv3 or epicserv4. Freedom and wild already had twitter accounts: wildserv1, freeserv1, and freedom003.', '<ul><li>The Epic missions still have some issues but some may work better now. We\'ll be sorting out the remaining issues soon.</li>\n<li>HOTS players received negative Combat Rating on their own home server. Fixed.</li>\n<li>There are now twitter feeds for the new Epic servers: www.twitter.com/epicserv1 ,epicserv2, epicserv3 or epicserv4. Freedom and wild already had twitter accounts: wildserv1, freeserv1, and freedom003.</li></ul>', 16),
(3536, 956, '111031 Epic issues fixed', '111031_Epic_issues_fixed', 'The agressive quest avatars should no longer be aggressive to players from the same kingdom Lady of the Lake, The Sword in the Stone and the King Cobra have now arroved to appoint rulers Upkeep cost for deeds are now properly calculated Kingdom towers for Player made kingdoms should now receive the proper kingdom id CA Chat should now be enabled for Epic Home servers Mining and digging now gives strength skill, but strength affects weapon damage a lot less on Epic Resonators and clappers for bells used the same identity numbers, so some of your clappers may have turned into resonators Mission progress is also being debugged, there are failing cases', '<ul><li>The agressive quest avatars should no longer be aggressive to players from the same kingdom</li>\n<li>Lady of the Lake, The Sword in the Stone and the King Cobra have now arroved to appoint rulers</li>\n<li>Upkeep cost for deeds are now properly calculated</li>\n<li>Kingdom towers for Player made kingdoms should now receive the proper kingdom id</li>\n<li>CA Chat should now be enabled for Epic Home servers</li>\n<li>Mining and digging now gives strength skill, but strength affects weapon damage a lot less on Epic</li>\n<li>Resonators and clappers for bells used the same identity numbers, so some of your clappers may have turned into resonators</li>\n<li>Mission progress is also being debugged, there are failing cases</li></ul>', 17),
(3537, 956, '111028 Release of Epic', '111028_Release_of_Epic', 'The Epic cluster is now available. New players should use the Epic portal after the tutorial. As an existing player you can build a portal and pop over. You can always return after one hour!', '<ul><li>The Epic cluster is now available. New players should use the Epic portal after the tutorial.</li>\n<li>As an existing player you can build a portal and pop over. You can always return after one hour!</li></ul>', 18),
(3538, 956, '111024 In-game voice chat live Beta test', '111024_In-game_voice_chat_live_Beta_test', 'The proximity voice chat has been enabled on the live servers. You need to use the unstable client to try it out. You find it on http://www.wurmonline.com/client/wurmclient_unstable.jnlp . You may have to allow the new code in your firewall and anti-virus programs. AVG for instance gives pretty harsh warnings.', '<ul><li>The proximity voice chat has been enabled on the live servers. You need to use the unstable client to try it out.</li>\n<li>You find it on <a class=\"external free\" href=\"http://www.wurmonline.com/client/wurmclient_unstable.jnlp\" rel=\"nofollow\">http://www.wurmonline.com/client/wurmclient_unstable.jnlp</a>. You may have to allow the new code in your firewall and anti-virus programs. AVG for instance gives pretty harsh warnings.</li></ul>', 19),
(3539, 956, '111017 Item transfer bugfix', '111017_Item_transfer_bugfix', 'A reason for missing items during transfers between servers was found and remedied. Items were returned in the cases we were made aware of Attacking into and out from duelling rings have been restricted across the border You should now be able to unlock and lockpick items inside containers Horse breeding now has a maximum of 1 trait up to skill level 20 Fixed a bug with /stuck and structures', '<ul><li>A reason for missing items during transfers between servers was found and remedied. Items were returned in the cases we were made aware of</li>\n<li>Attacking into and out from duelling rings have been restricted across the border</li>\n<li>You should now be able to unlock and lockpick items inside containers</li>\n<li>Horse breeding now has a maximum of 1 trait up to skill level 20</li>\n<li>Fixed a bug with /stuck and structures</li></ul>', 20),
(3540, 956, '111014 Artifacts made more interesting', '111014_Artifacts_made_more_interesting', 'The artifacts received more power in order to increase their use based on some good suggestions from Madt. Note that the cooldown usually is about one hour. Some of the effects listed below will be visible in the Spell Effects window. There are also other older effects that aren\'t listed here. Some of the effects may require you to be of the proper faith, i.e Fo for Finger of Fo. The Glass Eye of Vynora may now be used to cast the spell Locate Soul. The Glass Mouth of Vynora may now give 1 hour of sleep bonus. Glass Ear of Vynora: Drops 1 gem 50% of the time and gems are always over 70QL Silver Finger of Fo: Having this item in your inventory gives every allied person in proximity the effect that wounds do not get worse no matter how big they are. Gold Rod of Beguiling: Having this rod on you gives a 10% weapon damage buff in PvP only. Gold Charm of Fo: Currently this artifact allows you to tame any animal you like. No change. Gold Crown of Might: This artifact currently can be used to dominate fearsome monsters. If you wear the crown on your head it protects as a steel great helm and wearing it gives every allied person in proximity a non-stackable Combat Rating bonus of 1. Steel Sword of Magranon: Buffed Damage and Flaming Aura effect. Bronze Hammer of Magranon: Buffed Damage and Flaming Aura effect. Glass Orb of Doom: Now has a 20 seconds \'Use\' timer. When it reaches 0 the Orb deals a 50 damage wound to enemies that rots with infection. There\'s a 5% chance it backfires immediately and may kill the user and people closeby. Steel Sceptre of Ascension: Buffed Damage and Rotting Touch effect. Iron Scale of Libila: Raise Zombies. No limit on parrying as a shield. Indestructible. Also gives bonus to shield parrying skill. The range where you can build close to altars now has been increased to 50 tiles in order to promote more open recharge warfare which was always intended. Apparently 20 tiles didn\'t do the trick. Existing structures will have to be torn down. Recharging artifacts now properly has to be done at the same side altar. Fo, Magranon and Vynora at the White Light altar, and Libila at the Bone Altar.', '<ul><li>The artifacts received more power in order to increase their use based on some good suggestions from Madt.</li>\n<li>Note that the cooldown usually is about one hour. Some of the effects listed below will be visible in the Spell Effects window.</li>\n<li>There are also other older effects that aren\'t listed here. Some of the effects may require you to be of the proper faith, i.e Fo for Finger of Fo.</li></ul>\n<ol><li>The Glass Eye of Vynora may now be used to cast the spell Locate Soul.</li>\n<li>The Glass Mouth of Vynora may now give 1 hour of sleep bonus.</li>\n<li>Glass Ear of Vynora: Drops 1 gem 50% of the time and gems are always over 70QL</li>\n<li>Silver Finger of Fo: Having this item in your inventory gives every allied person in proximity the effect that wounds do not get worse no matter how big they are.</li>\n<li>Gold Rod of Beguiling: Having this rod on you gives a 10% weapon damage buff in PvP only.</li>\n<li>Gold Charm of Fo: Currently this artifact allows you to tame any animal you like. No change.</li>\n<li>Gold Crown of Might: This artifact currently can be used to dominate fearsome monsters. If you wear the crown on your head it protects as a steel great helm and wearing it gives every allied person in proximity a non-stackable Combat Rating bonus of 1.</li>\n<li>Steel Sword of Magranon: Buffed Damage and Flaming Aura effect.</li>\n<li>Bronze Hammer of Magranon: Buffed Damage and Flaming Aura effect.</li>\n<li>Glass Orb of Doom: Now has a 20 seconds \'Use\' timer. When it reaches 0 the Orb deals a 50 damage wound to enemies that rots with infection. There\'s a 5% chance it backfires immediately and may kill the user and people closeby.</li>\n<li>Steel Sceptre of Ascension: Buffed Damage and Rotting Touch effect.</li>\n<li>Iron Scale of Libila: Raise Zombies. No limit on parrying as a shield. Indestructible. Also gives bonus to shield parrying skill.</li></ol>\n<ul><li>The range where you can build close to altars now has been increased to 50 tiles in order to promote more open recharge warfare which was always intended. Apparently 20 tiles didn\'t do the trick. Existing structures will have to be torn down.</li>\n<li>Recharging artifacts now properly has to be done at the same side altar. Fo, Magranon and Vynora at the White Light altar, and Libila at the Bone Altar.</li></ul>', 21),
(3541, 956, '111012 Horse breeding improvements, spell tweaks', '111012_Horse_breeding_improvements.2C_spell_tweaks', 'Horse breeding should now yield more sensible results at higher skill levels Pain rain now has faith requirement of 40 instead of 60 since it made Fire Pillar look overpowered Worm Brains was also brought into line with Fire Heart', '<ul><li>Horse breeding should now yield more sensible results at higher skill levels</li>\n<li>Pain rain now has faith requirement of 40 instead of 60 since it made Fire Pillar look overpowered</li>\n<li>Worm Brains was also brought into line with Fire Heart</li></ul>', 22),
(3542, 956, '111005 Item weirdness fix', '111005_Item_weirdness_fix', 'The bug where newly created items suddenly became irresponsive was fixed. Some items may still experience this but it should go away over time. A bug where tunnelling creatures created drop shafts was fixed.', '<ul><li>The bug where newly created items suddenly became irresponsive was fixed. Some items may still experience this but it should go away over time.</li>\n<li>A bug where tunnelling creatures created drop shafts was fixed.</li></ul>', 23),
(3543, 956, '110928 Freedom KOS modification', '110928_Freedom_KOS_modification', 'KOS lists are now enabled on Freedom again but generate a 3 minute warning for the criminal to leave the deed Changed large cart seating positions because of possible exploits Area spell casting range was toned down a bit', '<ul><li>KOS lists are now enabled on Freedom again but generate a 3 minute warning for the criminal to leave the deed</li>\n<li>Changed large cart seating positions because of possible exploits</li>\n<li>Area spell casting range was toned down a bit</li></ul>', 24),
(3544, 956, '110927 Reducing strain on settlements (and GMs)', '110927_Reducing_strain_on_settlements_.28and_GMs.29', 'Village guards will now target creatures that bash fences or cave walls (not uniques), however creatures tunneling beneath villages has been disabled for now. It will be enabled initially on the epic servers Picking seeds, fileting meat, cutting cakes and crushing wemp now requires you to have the item on you because of some loopholes Creatures on deeds should now be protected. Make sure the to disable permissions that allow others to attack your creatures You may no longer put people on KOS on freedom settlement deeds since it was abused If you have left a server for two weeks you are no longer considered to be caring about your animals HOTS no longer receive danger bonus for lockpicking off deed since they have the faster thievery (lockpicking, traps, stealing) skillgain as a kingdom bonus Combat spells now have longer range with increased difficulty the longer the range Stumps may now be destroyed quickly', '<ul><li>Village guards will now target creatures that bash fences or cave walls (not uniques), however creatures tunneling beneath villages has been disabled for now. It will be enabled initially on the epic servers</li>\n<li>Picking seeds, fileting meat, cutting cakes and crushing wemp now requires you to have the item on you because of some loopholes</li>\n<li>Creatures on deeds should now be protected. Make sure the to disable permissions that allow others to attack your creatures</li>\n<li>You may no longer put people on KOS on freedom settlement deeds since it was abused</li>\n<li>If you have left a server for two weeks you are no longer considered to be caring about your animals</li>\n<li>HOTS no longer receive danger bonus for lockpicking off deed since they have the faster thievery (lockpicking, traps, stealing) skillgain as a kingdom bonus</li>\n<li>Combat spells now have longer range with increased difficulty the longer the range</li>\n<li>Stumps may now be destroyed quickly</li></ul>', 25),
(3545, 956, '110926 3000 Premium players!', '110926_3000_Premium_players.21', 'On Sep 25, 2011  at 23:34:11 CET Raub made us break the 3000 premium players mark! He has received 3 years free premium just because we\'re so happy! Thanks everyone who keep supporting Wurm in the effort to keep enhancing it into the game we all wish for! Uniques may now break down reinforced cave walls. \"Cave dwellers\" such as the Cave Bug may now tunnel through regular rock walls. Champion cave dwellers may even (very rarely) break reinforcements if untame. Tree stumps will now appear when a tree is cut down (Only wild and Independence has that code but the other servers will receive it asap).', '<ul><li>On Sep 25, 2011  at 23:34:11 CET Raub made us break the 3000 premium players mark! He has received 3 years free premium just because we\'re so happy! Thanks everyone who keep supporting Wurm in the effort to keep enhancing it into the game we all wish for!</li>\n<li>Uniques may now break down reinforced cave walls.</li>\n<li>\"Cave dwellers\" such as the Cave Bug may now tunnel through regular rock walls. Champion cave dwellers may even (very rarely) break reinforcements if untame.</li>\n<li>Tree stumps will now appear when a tree is cut down (Only wild and Independence has that code but the other servers will receive it asap).</li></ul>', 26),
(3546, 956, '110921 Transfer bugs attacked', '110921_Transfer_bugs_attacked', 'A bug with locks and keys when changing servers should be fixed A bug with friends list being disrupted when changing servers should be fixed HOTS should now regain nutrition and food levels at the normal rate again', '<ul><li>A bug with locks and keys when changing servers should be fixed</li>\n<li>A bug with friends list being disrupted when changing servers should be fixed</li>\n<li>HOTS should now regain nutrition and food levels at the normal rate again</li></ul>', 27),
(3547, 956, '110919 More creature updates', '110919_More_creature_updates', 'Fence breaking was toned down in that only Trolls, Lava fiends and Uniques break fences now. Uniques should be a bit harder to trap and break out more. Tougher creature types such as champion and greenish may no longer be hitched since it was considered overpowered. Normal types may though. A rare bug that caused Deliverance to shut down yesterday was fixed.', '<ul><li>Fence breaking was toned down in that only Trolls, Lava fiends and Uniques break fences now.</li>\n<li>Uniques should be a bit harder to trap and break out more.</li>\n<li>Tougher creature types such as champion and greenish may no longer be hitched since it was considered overpowered. Normal types may though.</li>\n<li>A rare bug that caused Deliverance to shut down yesterday was fixed.</li></ul>', 28),
(3548, 956, '110915 Exodus server available!', '110915_Exodus_server_available.21', 'The release of the Exodus server was extremely successful in that it was just like flicking a switch and it was made available on time. Enjoy! The server creature limit is lower than the current amount so the server has a surplus of creatures and the start area could need some help clearing these out. Once killed, these will not return until the lower limit is reached  so you can really make a change in helping people reach the coast. Creatures should move around a lot more now. Very strong creatures will now bash fences and walls (not house walls) unless tamed or dominated.', '<ul><li>The release of the Exodus server was extremely successful in that it was just like flicking a switch and it was made available on time. Enjoy!</li>\n<li>The server creature limit is lower than the current amount so the server has a surplus of creatures and the start area could need some help clearing these out. Once killed, these will not return until the lower limit is reached  so you can really make a change in helping people reach the coast.</li>\n<li>Creatures should move around a lot more now.</li>\n<li>Very strong creatures will now bash fences and walls (not house walls) unless tamed or dominated.</li></ul>', 29),
(3549, 956, '110912 Mailing and boat fixes', '110912_Mailing_and_boat_fixes', 'The problems with COD mail deliveries between servers have been fixed. There were some instances where captains could cross the border but their boats remained behind. Should no longer happen.', '<ul><li>The problems with COD mail deliveries between servers have been fixed.</li>\n<li>There were some instances where captains could cross the border but their boats remained behind. Should no longer happen.</li></ul>', 30),
(3550, 956, '110909 Item bug gone', '110909_Item_bug_gone', 'The aforementioned bug where items became irresponsive fixed itself. It was probably due to some id number confusion because of the rollback where the id counters now have catched up. The problematic items are gone. Luckily it was mostly clay, dirt or wood scraps anyways.', '<ul><li>The aforementioned bug where items became irresponsive fixed itself. It was probably due to some id number confusion because of the rollback where the id counters now have catched up. The problematic items are gone. Luckily it was mostly clay, dirt or wood scraps anyways.</li></ul>', 31),
(3551, 956, '110909 Small weirdness', '110909_Small_weirdness', 'Apparently items sometimes get created and end up irresponsive so you can not interact with them. We haven\'t found the cause for this yet. It mostly appears to be related to recycled item objects, which usually are low worth items but it can be a bit annoying. Shark models may look too large or too small depending on the state of model pack or server code. Eventually we\'ll synch and it will look good.', '<ul><li>Apparently items sometimes get created and end up irresponsive so you can not interact with them. We haven\'t found the cause for this yet. It mostly appears to be related to recycled item objects, which usually are low worth items but it can be a bit annoying.</li>\n<li>Shark models may look too large or too small depending on the state of model pack or server code. Eventually we\'ll synch and it will look good.</li></ul>', 32),
(3552, 956, '110908 Change to throwing creatures', '110908_Change_to_throwing_creatures', 'Creatures such as sharks should no longer throw you out of the larger boats such as Cogs or Corbitas. The smaller sailing or rowing boats do not provide that protection.', '<ul><li>Creatures such as sharks should no longer throw you out of the larger boats such as Cogs or Corbitas. The smaller sailing or rowing boats do not provide that protection.</li></ul>', 33),
(3553, 956, '110907 Wurm is stable!', '110907_Wurm_is_stable.21', 'There! After having to dish out loads of bad news the last 48 hours we have formally pushed through. Boats transfer between servers with thousands of items in the hold. I heard 4k+. Don\'t try to break it please. In case you lack items in inventory or on the body, return to Independence and they will show up and follow you over this time. There are no known severe bugs. The server is running smoothly. Most errors have been sorted. Time to rejoice!', '<ul><li>There! After having to dish out loads of bad news the last 48 hours we have formally pushed through. Boats transfer between servers with thousands of items in the hold. I heard 4k+. Don\'t try to break it please.</li>\n<li>In case you lack items in inventory or on the body, return to Independence and they will show up and follow you over this time.</li>\n<li>There are no known severe bugs. The server is running smoothly. Most errors have been sorted. Time to rejoice!</li></ul>', 34),
(3554, 956, '110907 Two more bug fixes', '110907_Two_more_bug_fixes', 'Boat locks didn\'t transfer properly which caused weirdnesses. If you tried to transfer in the beginning when there was a limit, items on your body or in your inventory may remain on the old server. These appeared if you returned but were stuck there. They should now transfer with you again. If you dropped them or put them in a container or boat you will need to bring that container back as well.', '<ul><li>Boat locks didn\'t transfer properly which caused weirdnesses.</li>\n<li>If you tried to transfer in the beginning when there was a limit, items on your body or in your inventory may remain on the old server. These appeared if you returned but were stuck there. They should now transfer with you again. If you dropped them or put them in a container or boat you will need to bring that container back as well.</li></ul>', 35),
(3555, 956, '110907 Boat transfer bug fixed', '110907_Boat_transfer_bug_fixed', 'The bug that caused boats to remain and players to cross the server border was finally found, glared at and eradicated. The servers are restarting one final time, then we sort out the dispersed accounts and bring them back to their boats. This usually means putting them back on the Independence server and summoning their boat. Most stuff should remain but there may be lost items. Unfortunately we can not spend time looking for them unless they are really valuable. There is still no telling how many items you can bring in your hull. It\'s possible that several thousands can be brought over but it is untested successfully. It could very well work if one thousand items do. If there are more problems we\'ll deal with those in good order. Big hugs to the GM team for all their fantastic work!', '<ul><li>The bug that caused boats to remain and players to cross the server border was finally found, glared at and eradicated.</li>\n<li>The servers are restarting one final time, then we sort out the dispersed accounts and bring them back to their boats. This usually means putting them back on the Independence server and summoning their boat. Most stuff should remain but there may be lost items. Unfortunately we can not spend time looking for them unless they are really valuable.</li>\n<li>There is still no telling how many items you can bring in your hull. It\'s possible that several thousands can be brought over but it is untested successfully. It could very well work if one thousand items do.</li>\n<li>If there are more problems we\'ll deal with those in good order.</li>\n<li>Big hugs to the GM team for all their fantastic work!</li></ul>', 36),
(3556, 956, '110907 Moving ahead', '110907_Moving_ahead', 'Apparently some boats fail to transfer from Independence. The cause is unknown. I suspect some item causes it, but the best suggestion is to move away from the border at least 10 tiles, disembark, embark and try again. Apparently it is an old workaround. You who ended up in the water with no boat around, try to make it back across and see if the boat is still there. There is extensive debug information being written in case there is a special item causing this. Deliverance will open from Golden Valley now. Currently we are losing customers whatever we do and there\'s no telling which is best.', '<ul><li>Apparently some boats fail to transfer from Independence. The cause is unknown. I suspect some item causes it, but the best suggestion is to move away from the border at least 10 tiles, disembark, embark and try again. Apparently it is an old workaround.</li>\n<li>You who ended up in the water with no boat around, try to make it back across and see if the boat is still there.</li>\n<li>There is extensive debug information being written in case there is a special item causing this.</li>\n<li>Deliverance will open from Golden Valley now. Currently we are losing customers whatever we do and there\'s no telling which is best.</li></ul>', 37),
(3557, 956, '110907 Item restrictions for boats', '110907_Item_restrictions_for_boats', 'When we performed the tests as previously explained, things went well. However, there was data loss when people tried to bring many items. We had to hardcode a limit of 300 items in the hull of your boat which should bring you over safely. It may seem little but we prefer to be safe than sorry. We succeeded in bringing more items on test but apparently there is a limit on the live servers that we were not aware of.', '<ul><li>When we performed the tests as previously explained, things went well. However, there was data loss when people tried to bring many items. We had to hardcode a limit of 300 items in the hull of your boat which should bring you over safely. It may seem little but we prefer to be safe than sorry. We succeeded in bringing more items on test but apparently there is a limit on the live servers that we were not aware of.</li></ul>', 38),
(3558, 956, '110907 Small delay but release soon', '110907_Small_delay_but_release_soon', 'We are running a bit late. We need to verify that ships can cross before we open the servers when they are up again. Crossing should be impossible and may make you end up in the water until we open the border. Do not attempt to cross until we give the sign. We will send a volunteer over to verify that the boat crossed properly. Note that there may be sharks on the other side. When we have verified that ships can cross we will open the Golden Valley portal as well.', '<ul><li>We are running a bit late. We need to verify that ships can cross before we open the servers when they are up again.</li>\n<li>Crossing should be impossible and may make you end up in the water until we open the border. Do not attempt to cross until we give the sign.</li>\n<li>We will send a volunteer over to verify that the boat crossed properly.</li>\n<li>Note that there may be sharks on the other side.</li>\n<li>When we have verified that ships can cross we will open the Golden Valley portal as well.</li></ul>', 39);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(3559, 956, '110906 New attempt Wednesday 7th at 18.00 CET', '110906_New_attempt_Wednesday_7th_at_18.00_CET', 'Opening the new server today failed for a few reasons, the worst being malfunctioning hardware. There will be rollbacks and we\'ll put everything back as good as we can then we try to open the Deliverance server again tomorrow at 18.00 hrs CET.', '<ul><li>Opening the new server today failed for a few reasons, the worst being malfunctioning hardware. There will be rollbacks and we\'ll put everything back as good as we can then we try to open the Deliverance server again tomorrow at 18.00 hrs CET.</li></ul>', 40),
(3560, 956, '110906 Herb sizes changed', '110906_Herb_sizes_changed', 'Some herb and seed sizes changed to something more sane. This had a dramatic and unexpected effect on the number in food storage bins, since it uses size to calculate numbers stored. Basically you may lose up to 90% of herbs stored in bins. In order to prevent boat theft on the non-pvp servers, you may not cross borders between these on ships unless you are the owner or friend of the owner. Village permission will not suffice.', '<ul><li>Some herb and seed sizes changed to something more sane. This had a dramatic and unexpected effect on the number in food storage bins, since it uses size to calculate numbers stored. Basically you may lose up to 90% of herbs stored in bins.</li>\n<li>In order to prevent boat theft on the non-pvp servers, you may not cross borders between these on ships unless you are the owner or friend of the owner. Village permission will not suffice.</li></ul>', 41),
(3561, 956, '110902 Small changes to thievery on PvP servers', '110902_Small_changes_to_thievery_on_PvP_servers', 'These changes applies to PvP servers only since you can not perform thievery on the other servers: When you reach -200 reputation you will now (again) join HOTS Mayors and kingdom rulers may no longer go into illegal mode', '<ul><li>These changes applies to PvP servers only since you can not perform thievery on the other servers:</li></ul>\n<ol><li>When you reach -200 reputation you will now (again) join HOTS</li>\n<li>Mayors and kingdom rulers may no longer go into illegal mode</li></ol>', 42),
(3562, 956, '110830 Stuck bugfix and anti-griefing', '110830_Stuck_bugfix_and_anti-griefing', 'A bug with the /stuck command was fixed In order to handle griefers better, area spells now affect same-side players on the wild server who are KOS on your deed. Lurker in the Dark will also locate them.', '<ul><li>A bug with the /stuck command was fixed</li>\n<li>In order to handle griefers better, area spells now affect same-side players on the wild server who are KOS on your deed. Lurker in the Dark will also locate them.</li></ul>', 43),
(3563, 956, '110829 Mount speed bug fixed', '110829_Mount_speed_bug_fixed', 'Wounded mounts will now properly regain their speed when healed Converting will now fail if it would make a mayor change kingdom Shield skill gain speed was increased some Artifact recharging is supposed to be a challenge and have great risk, so it now uses the same dates as altar destruction. Also you can only recharge one artifact at a time. Also, recharging libila artifacts must be done at the White Light while the others are recharged at the Black light You may no longer spawn at the lights since it only served as newbie traps The Dirt spell was too effective in removing clay and can no longer be used to do that. A bug with digging on clay was found though, and may actually lower it properly now.', '<ul><li>Wounded mounts will now properly regain their speed when healed</li>\n<li>Converting will now fail if it would make a mayor change kingdom</li>\n<li>Shield skill gain speed was increased some</li>\n<li>Artifact recharging is supposed to be a challenge and have great risk, so it now uses the same dates as altar destruction. Also you can only recharge one artifact at a time. Also, recharging libila artifacts must be done at the White Light while the others are recharged at the Black light</li>\n<li>You may no longer spawn at the lights since it only served as newbie traps</li>\n<li>The Dirt spell was too effective in removing clay and can no longer be used to do that. A bug with digging on clay was found though, and may actually lower it properly now.</li></ul>\n<p><br/>\n</p>', 44),
(3564, 956, '110721 Minor mount changes', '110721_Minor_mount_changes', 'Chain and leather Bardings now give a bit less movement penalty. The effect together with weight previously was a bit too much. Putting on and removing barding now requires you to stand on solid ground A bug where a movement penalty wasn\'t removed for creatures was fixed', '<ul><li>Chain and leather Bardings now give a bit less movement penalty. The effect together with weight previously was a bit too much.</li>\n<li>Putting on and removing barding now requires you to stand on solid ground</li>\n<li>A bug where a movement penalty wasn\'t removed for creatures was fixed</li></ul>\n<p><br/>\n</p>', 45),
(3565, 956, '110715 Fo priest buff.Horses and guards toned down', '110715_Fo_priest_buff.Horses_and_guards_toned_down', 'Tower guards and horses were a bit too powerful in the new system and now have lower Combat Rating Followers of Fo now receive a passive healing bonus at faith 20 Oakshell power now uses the rule of 70 algorithm and may glance If the power of an Oakshell is above 70 it will grow into a Thornshell and cause wounds like Area of Shared Pain where you wear no armour. The effect name won\'t change yet though.', '<ul><li>Tower guards and horses were a bit too powerful in the new system and now have lower Combat Rating</li>\n<li>Followers of Fo now receive a passive healing bonus at faith 20</li>\n<li>Oakshell power now uses the rule of 70 algorithm and may glance</li>\n<li>If the power of an Oakshell is above 70 it will grow into a Thornshell and cause wounds like Area of Shared Pain where you wear no armour. The effect name won\'t change yet though.</li></ul>\n<p><br/>\n</p>', 46),
(3566, 956, '110713 No more disappearing mounts', '110713_No_more_disappearing_mounts', 'The reason for some mounts disappearing in caves during restarts was that it used code to delete creatures from crowded underground areas. This should happen no more. Armour glance rate versus mobs has a lot less dependency on the type of attack the creature does.', '<ul><li>The reason for some mounts disappearing in caves during restarts was that it used code to delete creatures from crowded underground areas. This should happen no more.</li>\n<li>Armour glance rate versus mobs has a lot less dependency on the type of attack the creature does.</li></ul>\n<p><br/>\n</p>', 47),
(3567, 956, '110712 Mode differentiation and soft spots', '110712_Mode_differentiation_and_soft_spots', 'The effects of defensive and aggressive mode has increased. They are dependant on skill. Max combat rating bonus for normal fighting was raised to 2.5 You need to succeed with the skill rolls for aggressive and defensive mode in order to receive these effects Fightstyle skillgain speed increased Drake and scale received a bit more damage reduction You no longer lose focus when you are hit hard when fighting players since it skews fights very fast There are now \"soft spots\" you can hit depending on your stance versus the opponents. These will give a bit higher chances of critical hits Examining an opponent now gives information on which stance he uses Creatures will try and move into your soft spots', '<ul><li>The effects of defensive and aggressive mode has increased. They are dependant on skill. Max combat rating bonus for normal fighting was raised to 2.5</li>\n<li>You need to succeed with the skill rolls for aggressive and defensive mode in order to receive these effects</li>\n<li>Fightstyle skillgain speed increased</li>\n<li>Drake and scale received a bit more damage reduction</li>\n<li>You no longer lose focus when you are hit hard when fighting players since it skews fights very fast</li>\n<li>There are now \"soft spots\" you can hit depending on your stance versus the opponents. These will give a bit higher chances of critical hits</li>\n<li>Examining an opponent now gives information on which stance he uses</li>\n<li>Creatures will try and move into your soft spots</li></ul>\n<p><br/>\n</p>', 48),
(3568, 956, '110711 More fighting tweaks', '110711_More_fighting_tweaks', 'We are still trying to get the fighting system modifications in balance. This update addresses some more issues. Dominated and charmed creatures now have half the Combat Rating Strongwall can now be cast on entrances while outside Creature spawns now give skill again on the wild server Shield bashing now has a cooldown Creature attack rate was lowered The rate at which your secondary weapon is used increased Shield effectiveness was increased Aggressive stance deals more damage Defensive stance now deals a lot less damage Defensive stance gives more bonuses when parrying and using shield Normal stance gives a bit higher Combat Rating so you hit easier Fungus and Fungustrap casting cost was lowered approx 25% since the combination was weak compared to Fire/Icepillar The max number of guards a settlement may hire was set to 50. No existing settlements currently have more guards. Axes now do more damage per second since they don\'t parry Weapon speed for twohanded weapons in aggressive mode was set to 90% instead of 80%', '<ul><li>We are still trying to get the fighting system modifications in balance. This update addresses some more issues.</li>\n<li>Dominated and charmed creatures now have half the Combat Rating</li>\n<li>Strongwall can now be cast on entrances while outside</li>\n<li>Creature spawns now give skill again on the wild server</li>\n<li>Shield bashing now has a cooldown</li>\n<li>Creature attack rate was lowered</li>\n<li>The rate at which your secondary weapon is used increased</li>\n<li>Shield effectiveness was increased</li>\n<li>Aggressive stance deals more damage</li>\n<li>Defensive stance now deals a lot less damage</li>\n<li>Defensive stance gives more bonuses when parrying and using shield</li>\n<li>Normal stance gives a bit higher Combat Rating so you hit easier</li>\n<li>Fungus and Fungustrap casting cost was lowered approx 25% since the combination was weak compared to Fire/Icepillar</li>\n<li>The max number of guards a settlement may hire was set to 50. No existing settlements currently have more guards.</li>\n<li>Axes now do more damage per second since they don\'t parry</li>\n<li>Weapon speed for twohanded weapons in aggressive mode was set to 90% instead of 80%</li></ul>\n<p><br/>\n</p>', 49),
(3569, 956, '110707 Fight skillgain increased', '110707_Fight_skillgain_increased', 'The skill you gain from slaying creatures increased Parrying with shields and weapons should occur more frequently again. Sometimes a successful parry only reduces the success chance of your opponent instead of fully blocking. Your skill will cause greater chances of deflection Dragon scale armour was buffed a bit compared to drake hide', '<ul><li>The skill you gain from slaying creatures increased</li>\n<li>Parrying with shields and weapons should occur more frequently again. Sometimes a successful parry only reduces the success chance of your opponent instead of fully blocking. Your skill will cause greater chances of deflection</li>\n<li>Dragon scale armour was buffed a bit compared to drake hide</li></ul>\n<p><br/>\n</p>', 50),
(3570, 956, '110706 Minor buffs', '110706_Minor_buffs', 'Drake, Dragon Scale and Plate armour received some more damage reduction Foot and leg wounds are again a bit more severe The lockpicking penalty to boat locks was lowered a bit', '<ul><li>Drake, Dragon Scale and Plate armour received some more damage reduction</li>\n<li>Foot and leg wounds are again a bit more severe</li>\n<li>The lockpicking penalty to boat locks was lowered a bit</li></ul>\n<p><br/>\n</p>', 51),
(3571, 956, '110705 Weapon tweaks', '110705_Weapon_tweaks', 'Weapon skill now affects weapon swing speed maximum 10%. So at weapon skill 50 you have 5% faster swings and at skill 90 you have 9% faster swings. Swinging now has a floating value, so you may swing on average every 3.5th second instead of like before every 3d. Armour glance rates were modified and balanced. If you have achieved and use your mastery title when improving armour or creature wearable items, you now gain improvement speed bonus. The reason behind this is that the demand for armour is very high compared to the time it takes to improve it, especially on PvP servers. Lockpicking boats have been made harder.', '<ul><li>Weapon skill now affects weapon swing speed maximum 10%. So at weapon skill 50 you have 5% faster swings and at skill 90 you have 9% faster swings.</li>\n<li>Swinging now has a floating value, so you may swing on average every 3.5th second instead of like before every 3d.</li>\n<li>Armour glance rates were modified and balanced.</li>\n<li>If you have achieved and use your mastery title when improving armour or creature wearable items, you now gain improvement speed bonus. The reason behind this is that the demand for armour is very high compared to the time it takes to improve it, especially on PvP servers.</li>\n<li>Lockpicking boats have been made harder.</li></ul>\n<p><br/>\n</p>', 52),
(3572, 956, '110704 Combat changes, bug fixes, Wurm meeting date', '110704_Combat_changes.2C_bug_fixes.2C_Wurm_meeting_date', 'Combat was changed in various areas since it was pretty much broken in some aspects: Each armour type has a set base damage reduction affected by quality and the rule of 70 which means it has 91% effectiveness at quality level 70. Armours have a glance rate depending on they type of weapon that tries to penetrate it. This should make various types of armour more interesting. Favor gain was increased by 15%, but armour now affects favor gain speed (using speed reduction formula). Cloth has no penalty and wearing studded leather has about the same gain as before. Weapon parry, dodging and shield use was also tweaked. Since we are not able to mass test these changes unless we put them live, your feedback is important so please test and discuss in the forums. Two handed weapons get a speed bonus when used in aggressive mode Some damage tweaking is still needed but hopefully it\'s within fairly sane ranges. The annual official Wurm meeting date is set to friday the 26th of August in Stockholm. More info in City Hall in the forums at www.wurmonline.com/forum. Leg wounds speed reduction was increased again The increased improve rate for armours made it too hard to gain skill and was removed for now. The rule of 70 effect and the new changes should be enough to ensure you can get hold of good armour easily enough. Creature wearable items such as saddles and horse shoes are now as fast as armour to improve. Lockpicking on enemy deeds with at least 10 guards now give \"risk\" skill gain bonus even if they are dead A bug where animals would not return from being offline when you got a new pet was fixed Debugged leading creatures around mines so it works a lot better and no animals are lost Small carts should no longer visually stay beneath ground when you walk on top You may now use a \"last gasp\" ability on your body to drag yourself out of the water which allows you to climb without slipping for two minutes.', '<ul><li>Combat was changed in various areas since it was pretty much broken in some aspects:</li></ul>\n<ol><li>Each armour type has a set base damage reduction affected by quality and the rule of 70 which means it has 91% effectiveness at quality level 70.</li>\n<li>Armours have a glance rate depending on they type of weapon that tries to penetrate it. This should make various types of armour more interesting.</li>\n<li>Favor gain was increased by 15%, but armour now affects favor gain speed (using speed reduction formula). Cloth has no penalty and wearing studded leather has about the same gain as before.</li>\n<li>Weapon parry, dodging and shield use was also tweaked.</li>\n<li>Since we are not able to mass test these changes unless we put them live, your feedback is important so please test and discuss in the forums.</li>\n<li>Two handed weapons get a speed bonus when used in aggressive mode</li>\n<li>Some damage tweaking is still needed but hopefully it\'s within fairly sane ranges.</li></ol>\n<ul><li>The annual official Wurm meeting date is set to friday the 26th of August in Stockholm. More info in City Hall in the forums at www.wurmonline.com/forum.</li>\n<li>Leg wounds speed reduction was increased again</li>\n<li>The increased improve rate for armours made it too hard to gain skill and was removed for now. The rule of 70 effect and the new changes should be enough to ensure you can get hold of good armour easily enough.</li>\n<li>Creature wearable items such as saddles and horse shoes are now as fast as armour to improve.</li>\n<li>Lockpicking on enemy deeds with at least 10 guards now give \"risk\" skill gain bonus even if they are dead</li>\n<li>A bug where animals would not return from being offline when you got a new pet was fixed</li>\n<li>Debugged leading creatures around mines so it works a lot better and no animals are lost</li>\n<li>Small carts should no longer visually stay beneath ground when you walk on top</li>\n<li>You may now use a \"last gasp\" ability on your body to drag yourself out of the water which allows you to climb without slipping for two minutes.</li></ul>\n<p><br/>\n</p>', 53),
(3573, 956, '110628 Full loot reinstated', '110628_Full_loot_reinstated', 'The partial loot system was abandoned in it\'s cradle and full loot is reinstated with some major improvements to armour instead: The rule of 70 is applied to armour, which means that armour (like weapons) is 91% effective at quality level 70. At quality level 30 it is 51% effective. Armour parts are now twice as fast to improve and polish Magranon faith protection probability was reversed back up to 25% Res stones probability was upped a bit to 25% Foot and leg wounds should have a lot less impact now Damage to ridden mounts should slow them down significantly Structures that have no walls should fall down more properly in the future (may take two days continuous uptime)', '<ul><li>The partial loot system was abandoned in it\'s cradle and full loot is reinstated with some major improvements to armour instead:</li></ul>\n<ol><li>The rule of 70 is applied to armour, which means that armour (like weapons) is 91% effective at quality level 70. At quality level 30 it is 51% effective.</li>\n<li>Armour parts are now twice as fast to improve and polish</li>\n<li>Magranon faith protection probability was reversed back up to 25%</li>\n<li>Res stones probability was upped a bit to 25%</li>\n<li>Foot and leg wounds should have a lot less impact now</li>\n<li>Damage to ridden mounts should slow them down significantly</li></ol>\n<ul><li>Structures that have no walls should fall down more properly in the future (may take two days continuous uptime)</li></ul>', 54),
(3574, 956, '110627 Evalutating partial loot system', '110627_Evalutating_partial_loot_system', 'Horses should now be properly affected by wounds, armour penalties and encumbrance Minedoors off deed is now 5 times faster to destroy in order to curb gatehopping The \"prosperity bonus\" for deeds was removed We will evaluate a partial loot system in order to promote taking risks and testing pvp for a week: The difference is that you now get to keep most of the items you wear on your body Previously you lost everything, but now you only drop the items in your inventory, as well as your weapons, your shield, any containers worn and one piece of armour when you die The effectiveness of res stones and the magranon bonus were reduced to 12.5% each, so accumulated 25% instead BoKs work as previously The reasons behind this change have been discussed in the forums. We\'ll see how it feels and what the real effects are', '<ul><li>Horses should now be properly affected by wounds, armour penalties and encumbrance</li>\n<li>Minedoors off deed is now 5 times faster to destroy in order to curb gatehopping</li>\n<li>The \"prosperity bonus\" for deeds was removed</li>\n<li>We will evaluate a partial loot system in order to promote taking risks and testing pvp for a week:</li></ul>\n<ol><li>The difference is that you now get to keep most of the items you wear on your body</li>\n<li>Previously you lost everything, but now you only drop the items in your inventory, as well as your weapons, your shield, any containers worn and one piece of armour when you die</li>\n<li>The effectiveness of res stones and the magranon bonus were reduced to 12.5% each, so accumulated 25% instead</li>\n<li>BoKs work as previously</li>\n<li>The reasons behind this change have been discussed in the forums. We\'ll see how it feels and what the real effects are</li></ol>\n<p><br/>\n</p>', 55),
(3575, 956, '110623 Altars and prosperity bonus on wild', '110623_Altars_and_prosperity_bonus_on_wild', 'The \"prosperity bonus\" added to the settlements on wild this last update was not well received in its current form and will be modified or reverted. The huge altars may now be destroyed using normal weapons as well. They still heal themselves 1 point approximately every 10 minutes at which time a warning is broadcast. Break altar does some more damage as well and requires lower casting level.', '<ul><li>The \"prosperity bonus\" added to the settlements on wild this last update was not well received in its current form and will be modified or reverted.</li>\n<li>The huge altars may now be destroyed using normal weapons as well. They still heal themselves 1 point approximately every 10 minutes at which time a warning is broadcast. Break altar does some more damage as well and requires lower casting level.</li></ul>\n<p><br/>\n</p>', 56),
(3576, 956, '110616 Small tweaks and bug fixes', '110616_Small_tweaks_and_bug_fixes', 'Tweaked how steppe and grass spreads Jam is now made from maple syrup and berries instead. Winemaking should work properly again Cake slices now take into account the weight of the cake Freezing lava walls no longer should create a huge pit There was suspicion of a stealth bug. We debugged the code and fail to reproduce it You can now destroy enemy unfinished kingdom items such as towers Area spells will no longer affect you when you log on invulnerable A bug where dredging could cause dislocation was fixed.', '<ul><li>Tweaked how steppe and grass spreads</li>\n<li>Jam is now made from maple syrup and berries instead. Winemaking should work properly again</li>\n<li>Cake slices now take into account the weight of the cake</li>\n<li>Freezing lava walls no longer should create a huge pit</li>\n<li>There was suspicion of a stealth bug. We debugged the code and fail to reproduce it</li>\n<li>You can now destroy enemy unfinished kingdom items such as towers</li>\n<li>Area spells will no longer affect you when you log on invulnerable</li>\n<li>A bug where dredging could cause dislocation was fixed.</li></ul>\n<p><br/>\n</p>', 57),
(3577, 956, '110613 This should be interesting', '110613_This_should_be_interesting', 'The Wild Endgame and the functionality of the altars changed. The altars may now be destroyed on Wrath day and the day of Awakening in the first and third week of a Starfall when the moons are aligned to open them up for attacks. You may attack your own altars. If the altar receives critical damage, a random artifact belonging to the deities of the altar is used to channel protective powers to prevent the altar from being destroyed. The artifact shifts and is returned to and hidden by the spirits in the process. The protection causes the altar to immediately disappear and reappear somewhere else. The followers of deities belonging to the altar receives a light internal head wound from channelling their life force into healing the altar. Weapon minimum swing timer was increased to 3 seconds. Spirit guards became too fast with these last changes and should be less deadly again.', '<ul><li>The Wild Endgame and the functionality of the altars changed. The altars may now be destroyed on Wrath day and the day of Awakening in the first and third week of a Starfall when the moons are aligned to open them up for attacks. You may attack your own altars.</li>\n<li>If the altar receives critical damage, a random artifact belonging to the deities of the altar is used to channel protective powers to prevent the altar from being destroyed. The artifact shifts and is returned to and hidden by the spirits in the process.</li>\n<li>The protection causes the altar to immediately disappear and reappear somewhere else.</li>\n<li>The followers of deities belonging to the altar receives a light internal head wound from channelling their life force into healing the altar.</li>\n<li>Weapon minimum swing timer was increased to 3 seconds.</li>\n<li>Spirit guards became too fast with these last changes and should be less deadly again.</li></ul>\n<p><br/>\n</p>', 58),
(3578, 956, '110610 WoA downtoned', '110610_WoA_downtoned', 'A poll showed that more than 2/3ds thought that WoA was overpowered so the effect has been toned down on weapons only. It was perceived as one of the main barriers to entering PvP which was a very undesirable situation. Basically, every weapon is now very fast and WoA may have effect in certain situations increasing speed a little bit more. Creature weapon speeds increased a bit as well in order to balance. Very low Animal Husbandry skill now doesn\'t totally wipe traits. Instead a random number of up to 5 traits will be kept. Note that color is a trait.', '<ul><li>A poll showed that more than 2/3ds thought that WoA was overpowered so the effect has been toned down on weapons only. It was perceived as one of the main barriers to entering PvP which was a very undesirable situation. Basically, every weapon is now very fast and WoA may have effect in certain situations increasing speed a little bit more. Creature weapon speeds increased a bit as well in order to balance.</li>\n<li>Very low Animal Husbandry skill now doesn\'t totally wipe traits. Instead a random number of up to 5 traits will be kept. Note that color is a trait.</li></ul>', 59),
(3579, 956, '110607 Birthdays and Heatwaves', '110607_Birthdays_and_Heatwaves', 'We\'re having a fat heatwave here in Sweden, and I had a long nice weekend. There was a heatwave in Wurm as well, with quite a lot of venerable creatures dying from age that shouldn\'t have because they were cared for. I found a situation that caused it. From what I could see it would have happened even with the previous deed protection but I never received any reports about it so it\'s a bit confusing. In any case I am sorry for your losses. Like a team member put it \"Looking forward to see you at the Wurm meeting in about 2 months. Then I can give vent to my anger at a nearly 2-year breeding program has been destroyed ;)\" Removed some code that prevented bred creatures from spawning in very populated areas. Steppe and moss should spread a bit easier.', '<ul><li>We\'re having a fat heatwave here in Sweden, and I had a long nice weekend. There was a heatwave in Wurm as well, with quite a lot of venerable creatures dying from age that shouldn\'t have because they were cared for. I found a situation that caused it. From what I could see it would have happened even with the previous deed protection but I never received any reports about it so it\'s a bit confusing. In any case I am sorry for your losses. Like a team member put it \"Looking forward to see you at the Wurm meeting in about 2 months. Then I can give vent to my anger at a nearly 2-year breeding program has been destroyed ;)\"</li>\n<li>Removed some code that prevented bred creatures from spawning in very populated areas.</li>\n<li>Steppe and moss should spread a bit easier.</li></ul>', 60),
(3580, 956, '110527 Breeding, spawning, caring, coloring', '110527_Breeding.2C_spawning.2C_caring.2C_coloring', 'In order to bring the animal situation in control you may now start to \"care\" for animals. This prevents them from dying to old age. Starting next wednesday European time venerable creatures will lose their on-deed/tamed/leading/hitched protection and die at venerable age unless \"cared for\". You start and stop caring by right-clicking on an animal. The number of creatures you can care for increases with the animal husbandry skill. Type /stopcaring on the command line in order to stop caring for all animals. Thank Othob Rithol for the caring suggestion Trying to preserve a color when adding more of the same should be a bit easier now. Thank Tich. How traits are generated was changed thanks to a suggestion from Gaeron. The forum post is here: http://wurmonline.com/forum/index.php?topic=55489.0 Creatures should no longer spawn on severe slopes such as mountain sides.', '<ul><li>In order to bring the animal situation in control you may now start to \"care\" for animals. This prevents them from dying to old age.</li></ul>\n<ol><li>Starting next wednesday European time venerable creatures will lose their on-deed/tamed/leading/hitched protection and die at venerable age unless \"cared for\".</li>\n<li>You start and stop caring by right-clicking on an animal. The number of creatures you can care for increases with the animal husbandry skill.</li>\n<li>Type /stopcaring on the command line in order to stop caring for all animals.</li>\n<li>Thank Othob Rithol for the caring suggestion</li></ol>\n<ul><li>Trying to preserve a color when adding more of the same should be a bit easier now. Thank Tich.</li>\n<li>How traits are generated was changed thanks to a suggestion from Gaeron. The forum post is here: <a class=\"external free\" href=\"http://wurmonline.com/forum/index.php?topic=55489.0\" rel=\"nofollow\">http://wurmonline.com/forum/index.php?topic=55489.0</a></li>\n<li>Creatures should no longer spawn on severe slopes such as mountain sides.</li></ul>', 61),
(3581, 956, '110525 Traits and artifact recharging', '110525_Traits_and_artifact_recharging', 'Good traits were a bit too common for animals since the last change. Toned down. Recharging artifacts now gives a server wide message. Recharging also takes up to 4 minutes instead of 30 seconds.', '<ul><li>Good traits were a bit too common for animals since the last change. Toned down.</li>\n<li>Recharging artifacts now gives a server wide message. Recharging also takes up to 4 minutes instead of 30 seconds.</li></ul>', 62),
(3582, 956, '110523 Light and wild modifications', '110523_Light_and_wild_modifications', 'We are looking at solving the problems with lights acting a bit weird. Also, you can soon light candelabras filling them up with candles first and candles should no longer pile. Horses now should slow down when they receive damage. Further tweaks may be required. You should no longer be able to use farwalker twigs and stones very close to the huge altars or duelling rings.', '<ul><li>We are looking at solving the problems with lights acting a bit weird. Also, you can soon light candelabras filling them up with candles first and candles should no longer pile.</li>\n<li>Horses now should slow down when they receive damage. Further tweaks may be required.</li>\n<li>You should no longer be able to use farwalker twigs and stones very close to the huge altars or duelling rings.</li></ul>', 63),
(3583, 956, '110516 Rebranding required', '110516_Rebranding_required', 'A golden opportunity to rebrand your creatures has surfaced! A bug made it so that brands were lost during server restarts, so creatures need to be rebranded. Uncertain Congratulations. Pets were often lost when changing servers since the last pet id was transferred from the previous server and saved. This should work properly in the future.', '<ul><li>A golden opportunity to rebrand your creatures has surfaced! A bug made it so that brands were lost during server restarts, so creatures need to be rebranded. Uncertain Congratulations.</li>\n<li>Pets were often lost when changing servers since the last pet id was transferred from the previous server and saved. This should work properly in the future.</li></ul>', 64),
(3584, 956, '110513 More understandable faith bonus', '110513_More_understandable_faith_bonus', 'The calculations for altars and the bonuses they create was improved and should yield more understandable results.', '<ul><li>The calculations for altars and the bonuses they create was improved and should yield more understandable results.</li></ul>', 65),
(3585, 956, '110509 Yet another small breeding tweak', '110509_Yet_another_small_breeding_tweak', 'Now your creatures can be made to mate so that you can gain skill, but if the creature max limit hit is reached there will be no offspring produced when the time for delivery is up. There is also now a space consisting of 1/25th of max creatures reserved for animals to spawn in the wild.', '<ul><li>Now your creatures can be made to mate so that you can gain skill, but if the creature max limit hit is reached there will be no offspring produced when the time for delivery is up. There is also now a space consisting of 1/25th of max creatures reserved for animals to spawn in the wild.</li></ul>', 66),
(3586, 956, '110502 Creature tweak and fat bug', '110502_Creature_tweak_and_fat_bug', 'A bug where creatures started gaining fat as soon as they lost fat was fixed. Note that creatures will starve to death when they lose all their fat levels. Very old and very young creatures will no longer breed and there is a period in life where animals are more prone to breed. Certain sick creatures stop breeding earlier as well.', '<ul><li>A bug where creatures started gaining fat as soon as they lost fat was fixed. Note that creatures will starve to death when they lose all their fat levels.</li>\n<li>Very old and very young creatures will no longer breed and there is a period in life where animals are more prone to breed. Certain sick creatures stop breeding earlier as well.</li></ul>', 67),
(3587, 956, '110429 Late Easter', '110429_Late_Easter', 'The Easter Bunny has arrived. Since we failed to summon it last weekend we asked for a special appearance now. It was sighted at a LOL on the wild server and in The Howl on Freedom. It seems that you may also accidentally find your easter egg while foraging. A bug where your pet could be attacked by your own tower guards when you attacked an enemy deed was fixed.', '<ul><li>The Easter Bunny has arrived. Since we failed to summon it last weekend we asked for a special appearance now. It was sighted at a LOL on the wild server and in The Howl on Freedom. It seems that you may also accidentally find your easter egg while foraging.</li>\n<li>A bug where your pet could be attacked by your own tower guards when you attacked an enemy deed was fixed.</li></ul>', 68),
(3588, 956, '110426 Long awaited client and server update', '110426_Long_awaited_client_and_server_update', 'The client and server has been updated. This should solve a lot of problems and cause very few new ones. The biggest changes are on the client which no longer uses JOGL, but instead only LWJGL. Major changes on the server: Movement code changed which should cause less disembarking. Creature spawning now has two pools where 50% is reserved for aggressive animals and 50% for non-aggressive. This should even out over time. In the next update, creatures older than approximately 6 months will start dying unless they are on deed, loyal or ridden. Uniques, humans and guards are not affected. There are lots of small bugfixes such as with meditation and artifact recharging.', '<ul><li>The client and server has been updated. This should solve a lot of problems and cause very few new ones.</li>\n<li>The biggest changes are on the client which no longer uses JOGL, but instead only LWJGL.</li>\n<li>Major changes on the server:</li>\n<li>Movement code changed which should cause less disembarking.</li>\n<li>Creature spawning now has two pools where 50% is reserved for aggressive animals and 50% for non-aggressive. This should even out over time. In the next update, creatures older than approximately 6 months will start dying unless they are on deed, loyal or ridden. Uniques, humans and guards are not affected.</li>\n<li>There are lots of small bugfixes such as with meditation and artifact recharging.</li></ul>', 69),
(3589, 956, '110323 Old embarking bug resolved', '110323_Old_embarking_bug_resolved', 'The old bug that often teleported you shortly after embarking a boat was found and fixed in the unstable client. A bug with handing out Slayer of Champion titles was fixed', '<ul><li>The old bug that often teleported you shortly after embarking a boat was found and fixed in the unstable client.</li>\n<li>A bug with handing out Slayer of Champion titles was fixed</li></ul>', 70),
(3590, 956, '110322 Tunneling and ignore powers', '110322_Tunneling_and_ignore_powers', 'Opening tunnels is now a bit harder in certain circumstances as a counter measure to an exploit. This may be improved after some feedback. The weird wild lag should be gone. Experiment: The /ignore command now has the functionality to auto mute for an hour if enough premium players from the same kingdom use it on another player in a short time frame. You only have one such vote within a set time frame as well. This system may be abused for a while so try not to take such mutes too seriously initially.', '<ul><li>Opening tunnels is now a bit harder in certain circumstances as a counter measure to an exploit. This may be improved after some feedback.</li>\n<li>The weird wild lag should be gone.</li>\n<li>Experiment: The /ignore command now has the functionality to auto mute for an hour if enough premium players from the same kingdom use it on another player in a short time frame. You only have one such vote within a set time frame as well. This system may be abused for a while so try not to take such mutes too seriously initially.</li></ul>', 71),
(3591, 956, '110316 Artifacts change', '110316_Artifacts_change', 'Instead of artifacts insta-disappearing after a month of finding them, they will now have 120 charges. Every week 10 charges are removed. Every time you use an artifact one charge is used. You can recharge the artifacts at the enemy altar of light. If an artifact has 0 charges it will disappear within the week.', '<ul><li>Instead of artifacts insta-disappearing after a month of finding them, they will now have 120 charges. Every week 10 charges are removed. Every time you use an artifact one charge is used. You can recharge the artifacts at the enemy altar of light. If an artifact has 0 charges it will disappear within the week.</li></ul>', 72),
(3592, 956, '110311 Sleep bonus frozen by default', '110311_Sleep_bonus_frozen_by_default', 'By default, sleep bonus is now frozen when you log in so don\'t type /fsleep until you want to start using it.', '<ul><li>By default, sleep bonus is now frozen when you log in so don\'t type /fsleep until you want to start using it.</li></ul>', 73),
(3593, 956, '110310 Registration and artifacts', '110310_Registration_and_artifacts', 'Registration emails work again but for yahoo and hotmail they usually end up in the spam folder. We\'ll try to figure out which settings are wrong. Artifacts will now disappear after around a month of use. The current ones will disappear randomly in about 3 weeks. Most artifacts had new functionality added and shorter cooldown. Transfers between different types of servers are now limited to at least one hour.', '<ul><li>Registration emails work again but for yahoo and hotmail they usually end up in the spam folder. We\'ll try to figure out which settings are wrong.</li>\n<li>Artifacts will now disappear after around a month of use. The current ones will disappear randomly in about 3 weeks. Most artifacts had new functionality added and shorter cooldown.</li>\n<li>Transfers between different types of servers are now limited to at least one hour.</li></ul>', 74),
(3594, 956, '110309 Servers moved, all systems online', '110309_Servers_moved.2C_all_systems_online', 'We officially have to declare this last effort to move the server software to new hardware a success. There have been many failures and worries along the way but everything seems to be up and running perfectly now on the new hardware. The registration and shop pages are open and working again.', '<ul><li>We officially have to declare this last effort to move the server software to new hardware a success. There have been many failures and worries along the way but everything seems to be up and running perfectly now on the new hardware.</li>\n<li>The registration and shop pages are open and working again.</li></ul>', 75),
(3595, 956, '110309 Shop and registration down due to server move', '110309_Shop_and_registration_down_due_to_server_move', 'The shop and registration is down because we have moved the game servers to new hardware and operating system which means a lot has changed. Since these pages use dns entries we had to move the servers so that we can pinpoint the problems and find solutions. The forums are also undergoing some changes in case you think they look different.', '<ul><li>The shop and registration is down because we have moved the game servers to new hardware and operating system which means a lot has changed. Since these pages use dns entries we had to move the servers so that we can pinpoint the problems and find solutions.</li>\n<li>The forums are also undergoing some changes in case you think they look different.</li></ul>', 76),
(3596, 956, '110303 Horses buffed and mine door restrictions', '110303_Horses_buffed_and_mine_door_restrictions', 'Horses have received a buff and barding protects the whole horse for now. Various restrictions on surface mining was imposed because of exploitability, and you can no longer attach mine doors to openings larger than \"90\" steps/dirt A bug with staff skill was fixed that prevented them from working properly Archery will act a bit weird and deal damage with a delay until next update because we are making arrows visible during flight.', '<ul><li>Horses have received a buff and barding protects the whole horse for now.</li>\n<li>Various restrictions on surface mining was imposed because of exploitability, and you can no longer attach mine doors to openings larger than \"90\" steps/dirt</li>\n<li>A bug with staff skill was fixed that prevented them from working properly</li>\n<li>Archery will act a bit weird and deal damage with a delay until next update because we are making arrows visible during flight.</li></ul>', 77),
(3597, 956, '110302 Guards and horse barding', '110302_Guards_and_horse_barding', 'Spirit guard combat rating was returned to what it was before Horses now can wear barding (just bug fixed) Armour chains are now created in larger doses. Two handed weapons now give CR bonus versus creatures on vehicles if you\'re not on a vehicle yourself. The brand new polearms give double damage against mounted moving creatures', '<ul><li>Spirit guard combat rating was returned to what it was before</li>\n<li>Horses now can wear barding (just bug fixed)</li>\n<li>Armour chains are now created in larger doses.</li>\n<li>Two handed weapons now give CR bonus versus creatures on vehicles if you\'re not on a vehicle yourself.</li>\n<li>The brand new polearms give double damage against mounted moving creatures</li></ul>', 78),
(3598, 956, '110301 Guards nerfed', '110301_Guards_nerfed', 'Spirit guards were nerfed because they were deemed over powered with the recent changes. The amount of village bonus you get from sacrificing was made ten times higher. There\'s a forum post in City Hall covering the details. The server move was a moderate success but we had to rever again. It seems the servers themselves are very fast but there is something wrong with the network.', '<ul><li>Spirit guards were nerfed because they were deemed over powered with the recent changes.</li>\n<li>The amount of village bonus you get from sacrificing was made ten times higher. There\'s a forum post in City Hall covering the details.</li>\n<li>The server move was a moderate success but we had to rever again. It seems the servers themselves are very fast but there is something wrong with the network.</li></ul>', 79),
(3599, 956, '110228 Village faith bonuses', '110228_Village_faith_bonuses', 'There are now a couple of small faith bonuses that apply to the whole village. You gain these bonuses as you sacrifice items. They are visible in the Settlement Info window. A new attempt at changing the hosting will take place on Tue 1st of March at 10 AM CET. Estimated downtime is up to 4 hours.', '<ul><li>There are now a couple of small faith bonuses that apply to the whole village. You gain these bonuses as you sacrifice items. They are visible in the Settlement Info window.</li>\n<li>A new attempt at changing the hosting will take place on Tue 1st of March at 10 AM CET. Estimated downtime is up to 4 hours.</li></ul>', 80),
(3600, 956, '110217 Champions gone', '110217_Champions_gone', 'Apparently the deities decided that there were too many champions and removed them all. The skill bonuses they received have been reverted. Those who raised channeling a lot after champing long ago have been compensated somewhat. The deities have apparently agreed to only allow a certain number of champions - 3 Magranon champions for Mol Rehan, 3 Vynora or Fo champions for Jenn Kellon, and 6 Libila champions for Horde of the Summoned. Champions no longer have real death - instead they lose 1 point extra characteristic when they lose champion status. They are required to gather champion points by slaying enemies and raiding deeds. A champion starts with 15 champion points and loses 1 per day. In other respects they are the same as before. The three known champions who sacrificed their lives for their deities will stay revered in the memory of the people they served: Longshanks, Teslas and Maincorpse. On another note - spirit guards have changed some and may be a bit too hard now. They may attack mounts and also attack in larger groups on extremely heavily guarded deeds. Give feedback. Most creatures hunt a bit differently - hopefully more effectively. Priests should now be able to finish unfinished items. OH and you are now able to do more things on boats such as crafting in inventory. Possibly archery and spells. This may be disruptive so come with feedback as soon as possible after trying it out.', '<ul><li>Apparently the deities decided that there were too many champions and removed them all. The skill bonuses they received have been reverted. Those who raised channeling a lot after champing long ago have been compensated somewhat.</li>\n<li>The deities have apparently agreed to only allow a certain number of champions - 3 Magranon champions for Mol Rehan, 3 Vynora or Fo champions for Jenn Kellon, and 6 Libila champions for Horde of the Summoned.</li>\n<li>Champions no longer have real death - instead they lose 1 point extra characteristic when they lose champion status. They are required to gather champion points by slaying enemies and raiding deeds. A champion starts with 15 champion points and loses 1 per day. In other respects they are the same as before.</li>\n<li>The three known champions who sacrificed their lives for their deities will stay revered in the memory of the people they served: Longshanks, Teslas and Maincorpse.</li>\n<li>On another note - spirit guards have changed some and may be a bit too hard now. They may attack mounts and also attack in larger groups on extremely heavily guarded deeds. Give feedback.</li>\n<li>Most creatures hunt a bit differently - hopefully more effectively.</li>\n<li>Priests should now be able to finish unfinished items.</li>\n<li>OH and you are now able to do more things on boats such as crafting in inventory. Possibly archery and spells. This may be disruptive so come with feedback as soon as possible after trying it out.</li></ul>', 81),
(3601, 956, '110131 Deeds, contracts, and skill corrections', '110131_Deeds.2C_contracts.2C_and_skill_corrections', 'Merchants now trade ownership when the contract is traded A bug which let you control mounts and vehicles with too little skill was fixed A bug where non-premiums were able to trade deeds for founded settlements was fixed Lamp/sign/flag decay bugfix', '<ul><li>Merchants now trade ownership when the contract is traded</li>\n<li>A bug which let you control mounts and vehicles with too little skill was fixed</li>\n<li>A bug where non-premiums were able to trade deeds for founded settlements was fixed</li>\n<li>Lamp/sign/flag decay bugfix</li></ul>', 82),
(3602, 956, '110124 Zombie skill-gain', '110124_Zombie_skill-gain', 'Skill-gain when fighting summoned Zombies is now lower since people suspected exploits. Skill-gain shouldn\'t need to be 0 since it has summoning cost but it shouldn\'t be safe skill-gain either.', '<ul><li>Skill-gain when fighting summoned Zombies is now lower since people suspected exploits. Skill-gain shouldn\'t need to be 0 since it has summoning cost but it shouldn\'t be safe skill-gain either.</li></ul>', 83);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(3603, 956, '110121 Jewelry enchantments', '110121_Jewelry_enchantments', 'You can now cast no-locate on rings, bracelets and necklaces. This is a first jewelry enchantment and we may get a few more. The chance that it will hide you against a Locate Soul is (ql+power)/2 %. The enchantment slowly gets worn out when a locate soul is cast. You will now see how many more items your personal merchant may put up for sale in the management windows. No-locate cast on creatures now stays 3 times longer as well. Locate Soul was unchanged and never increased favor cost. The time to cast was increased instead but that was reverted.', '<ul><li>You can now cast no-locate on rings, bracelets and necklaces. This is a first jewelry enchantment and we may get a few more. The chance that it will hide you against a Locate Soul is (ql+power)/2 %. The enchantment slowly gets worn out when a locate soul is cast.</li>\n<li>You will now see how many more items your personal merchant may put up for sale in the management windows.</li>\n<li>No-locate cast on creatures now stays 3 times longer as well. Locate Soul was unchanged and never increased favor cost. The time to cast was increased instead but that was reverted.</li></ul>', 84),
(3604, 956, '110120 Locate, creature enchants, and healing', '110120_Locate.2C_creature_enchants.2C_and_healing', 'The locate player spell cost was increased to 20 favor because it made it too cheap to keep track of invaders Creature enchantments and healing now works on allies like they should', '<ul><li>The locate player spell cost was increased to 20 favor because it made it too cheap to keep track of invaders</li>\n<li>Creature enchantments and healing now works on allies like they should</li></ul>', 85),
(3605, 956, '110117 More spell and champion tweaks', '110117_More_spell_and_champion_tweaks', 'Vulnerable actions such as casting and healing are more often interrupted by being hit now A speed bug with web armor was fixed Frantic charge now updates movement properly Using key-bind to repair through walls was fixed Area spells still are too dominant on the battle field so favor cost was increased to 30 Fire Pillar no longer targets creatures. Instead Fire Heart received a buff. The corresponding Vynora spell is Shard of Ice which is a bit slower but with more damage. Willow-spine should work better now Being overheated invalidates your link just as if you are out of range Champions no longer receive Faith bonus in their own territory', '<ul><li>Vulnerable actions such as casting and healing are more often interrupted by being hit now</li>\n<li>A speed bug with web armor was fixed</li>\n<li>Frantic charge now updates movement properly</li>\n<li>Using key-bind to repair through walls was fixed</li>\n<li>Area spells still are too dominant on the battle field so favor cost was increased to 30</li>\n<li>Fire Pillar no longer targets creatures. Instead Fire Heart received a buff. The corresponding Vynora spell is Shard of Ice which is a bit slower but with more damage.</li>\n<li>Willow-spine should work better now</li>\n<li>Being overheated invalidates your link just as if you are out of range</li>\n<li>Champions no longer receive Faith bonus in their own territory</li></ul>', 86),
(3606, 956, '110114 Spell tweaks', '110114_Spell_tweaks', 'The Fo spell Charm Animal is now available, and the Magranon spell Frantic Charge is now available. Ward should have more effect. Creatures should become more careful overall. Web Armour didn\'t have the slow down effect it was supposed to which was fixed. Zombie infestation now creates more powerful zombies. Scorn of Libila casting time was reduced to 15 (from 20) and favor cost to 40 (from 50) Signs, lamps, banners and flags will be maintained by existing spirit guards in villages now', '<ul><li>The Fo spell Charm Animal is now available, and the Magranon spell Frantic Charge is now available.</li>\n<li>Ward should have more effect. Creatures should become more careful overall.</li>\n<li>Web Armour didn\'t have the slow down effect it was supposed to which was fixed.</li>\n<li>Zombie infestation now creates more powerful zombies.</li>\n<li>Scorn of Libila casting time was reduced to 15 (from 20) and favor cost to 40 (from 50)</li>\n<li>Signs, lamps, banners and flags will be maintained by existing spirit guards in villages now</li></ul>', 87),
(3607, 956, '110112 Favor overheating test', '110112_Favor_overheating_test', 'We are going to test a form of cool-down where you get overheated if you use a lot of favor in a short time. The reason behind the solution is that linking was deemed to be a bit too powerful sometimes. If this initial code is too much we\'ll have to ease it up but we need real fight situations to test it on. Area spells now cost 20 favor instead of 10. Pain rain cost was reduced to 40 since the new favor cool-down should make it harder to create death zones with it now. A minor tweak: you should now be able to dig 1 deeper than you can flatten.', '<ul><li>We are going to test a form of cool-down where you get overheated if you use a lot of favor in a short time. The reason behind the solution is that linking was deemed to be a bit too powerful sometimes. If this initial code is too much we\'ll have to ease it up but we need real fight situations to test it on.</li>\n<li>Area spells now cost 20 favor instead of 10. Pain rain cost was reduced to 40 since the new favor cool-down should make it harder to create death zones with it now.</li>\n<li>A minor tweak: you should now be able to dig 1 deeper than you can flatten.</li></ul>', 88),
(3608, 956, '110110 Area spell & leading bug-fix', '110110_Area_spell_.26_leading_bug-fix', 'Casting area spells below ground now properly is obstructed by cave walls The bug with leading your mounts on foreign deeds was fixed', '<ul><li>Casting area spells below ground now properly is obstructed by cave walls</li>\n<li>The bug with leading your mounts on foreign deeds was fixed</li></ul>', 89),
(3609, 956, '110105 Lag situations reduced', '110105_Lag_situations_reduced', 'The lag that occurred after a Fire-pillar spell was cast has been remedied A situation where the server froze like last Friday because of a chase-case with Tweets has also been sorted', '<ul><li>The lag that occurred after a Fire-pillar spell was cast has been remedied</li>\n<li>A situation where the server froze like last Friday because of a chase-case with Tweets has also been sorted</li></ul>', 90),
(3633, 962, '121219 Some fighting and building tweaks', '121219_Some_fighting_and_building_tweaks', 'Various construction issues were sorted Eye and face damages were nerfed The flanking window has been narrowed when attacking from behind', '<ul><li>Various construction issues were sorted</li>\n<li>Eye and face damages were nerfed</li>\n<li>The flanking window has been narrowed when attacking from behind</li></ul>', 0),
(3634, 962, '121217 Mending structures, first person animations', '121217_Mending_structures.2C_first_person_animations', 'Structures should no longer have holes in them after restart Own animations should now properly play for the player as well Paving skillgain for building floors was tweaked An issue occurred with the Chaos server during maintenance which means it will be offline longer while we investigate', '<ul><li>Structures should no longer have holes in them after restart</li>\n<li>Own animations should now properly play for the player as well</li>\n<li>Paving skillgain for building floors was tweaked</li>\n<li>An issue occurred with the Chaos server during maintenance which means it will be offline longer while we investigate</li></ul>', 1),
(3635, 962, '121214 Fixes: Embarking, floor qualitylevels, multilevel fences blocking', '121214_Fixes:_Embarking.2C_floor_qualitylevels.2C_multilevel_fences_blocking', 'Embarking in deep water fixed Fences on top floors will no longer block entrances below after restart The qualitylevels on floors had issues and all existing floor qualitylevels have been set to 30 Some floors could not be saved due to infinite quality levels and was the cause for many missing floors this restart. We fail to reproduce these disappearances now so you can safely rebuild. Some issues with teleport loops being created were fixed More armour types should now show Please note that we have quite a lot of almost finished graphic improvements that we didn’t have time to verify and add to the packs until release. These are now being added over time as soon as possible. We are going to check the availability of slate and marble tiles now after these reprospecting runs and possible add a few more. There is still an issue with some large houses that have ended up with unplanned sections in the middle. We expect to resolve it soon after the weekend and you will be able to resuming building in those parts. There will be no need to remove or redesign the structure.', '<ul><li>Embarking in deep water fixed</li>\n<li>Fences on top floors will no longer block entrances below after restart</li>\n<li>The qualitylevels on floors had issues and all existing floor qualitylevels have been set to 30</li>\n<li>Some floors could not be saved due to infinite quality levels and was the cause for many missing floors this restart. We fail to reproduce these disappearances now so you can safely rebuild.</li>\n<li>Some issues with teleport loops being created were fixed</li>\n<li>More armour types should now show</li>\n<li>Please note that we have quite a lot of almost finished graphic improvements that we didn’t have time to verify and add to the packs until release. These are now being added over time as soon as possible.</li>\n<li>We are going to check the availability of slate and marble tiles now after these reprospecting runs and possible add a few more.</li>\n<li>There is still an issue with some large houses that have ended up with unplanned sections in the middle. We expect to resolve it soon after the weekend and you will be able to resuming building in those parts. There will be no need to remove or redesign the structure.</li></ul>', 2),
(3636, 962, '121213 Falling damage tweak', '121213_Falling_damage_tweak', 'Falling damage was tweaked so that weight carried doesn’t matter More armour types are now visible Custom faces on new players should be fixed You no longer get extra mirror every time you relog A bug with house and fence collision was fixed The rampant slate and marble areas were reversed to iron and the materials were made more rare Thatch roof should now be easier to build Materials used will now affect ql of floors and roof, as well as the skill check. There is a known issue that floors and plans in the middle of buildings disappear during a restart. It will have highest priority until next restart.', '<ul><li>Falling damage was tweaked so that weight carried doesn’t matter</li>\n<li>More armour types are now visible</li>\n<li>Custom faces on new players should be fixed</li>\n<li>You no longer get extra mirror every time you relog</li>\n<li>A bug with house and fence collision was fixed</li>\n<li>The rampant slate and marble areas were reversed to iron and the materials were made more rare</li>\n<li>Thatch roof should now be easier to build</li>\n<li>Materials used will now affect ql of floors and roof, as well as the skill check.</li>\n<li>There is a known issue that floors and plans in the middle of buildings disappear during a restart. It will have highest priority until next restart.</li></ul>', 3),
(3637, 962, '121210 Archery running bug fixed', '121210_Archery_running_bug_fixed', 'The bug that teleported people during archery was fixed Tempering should now yield proper quality increase again Items in containers below ground should again be accessible. It was the new pile code for multistorey acting up a bit.', '<ul><li>The bug that teleported people during archery was fixed</li>\n<li>Tempering should now yield proper quality increase again</li>\n<li>Items in containers below ground should again be accessible. It was the new pile code for multistorey acting up a bit.</li></ul>', 4),
(3638, 962, '121209 Long awaited features added', '121209_Long_awaited_features_added', 'The ability to raise cave and surface level rock using a rudimentary form of concrete has been invented by angry miners Bewildered weapon smiths have invented a way to smelt unused metal with some sort of pottery devide At a workshop in the art of “thinking outside of the forge” smiths understood how to keep improving one item and gain better skill with less improvement, instead of spewing out tons of items. The tutorial area now has increased chance of creating certain basic items in order to keep people from quitting before they understand the beauty and rewards of perseverance. Raiding on the Epic servers are forbidden until noticed due to an archery bug. Caves have started acting up and you should avoid riding in them for the time being. Also you may become glued to walls or end up inside them. Relog in those cases. We are working on fixing these issues with a client update. Falling damage was increased for higher altitudes. New items will no longer have to be polished in order to be finished. For some nice Sunday listening, turn on Wurm Online Radio: http://www.wurmonlineradio.tk/ Changing weapon stance is now easier. Weapon skill affects special moves hit chance more.', '<ul><li>The ability to raise cave and surface level rock using a rudimentary form of concrete has been invented by angry miners</li>\n<li>Bewildered weapon smiths have invented a way to smelt unused metal with some sort of pottery devide</li>\n<li>At a workshop in the art of “thinking outside of the forge” smiths understood how to keep improving one item and gain better skill with less improvement, instead of spewing out tons of items.</li>\n<li>The tutorial area now has increased chance of creating certain basic items in order to keep people from quitting before they understand the beauty and rewards of perseverance.</li>\n<li>Raiding on the Epic servers are forbidden until noticed due to an archery bug.</li>\n<li>Caves have started acting up and you should avoid riding in them for the time being. Also you may become glued to walls or end up inside them. Relog in those cases. We are working on fixing these issues with a client update.</li>\n<li>Falling damage was increased for higher altitudes.</li>\n<li>New items will no longer have to be polished in order to be finished.</li>\n<li>For some nice Sunday listening, turn on Wurm Online Radio: <a class=\"external free\" href=\"http://www.wurmonlineradio.tk/\" rel=\"nofollow\">http://www.wurmonlineradio.tk/</a></li>\n<li>Changing weapon stance is now easier. Weapon skill affects special moves hit chance more.</li></ul>', 5),
(3639, 962, '121128 Fishing rod improvement, Item pile fix, faster huge creatures', '121128_Fishing_rod_improvement.2C_Item_pile_fix.2C_faster_huge_creatures', 'You now have to string a shaft in order to create a fishing rod instead of the old way Mine tiles that share corners with 2 cave entrances can be mined now Item piles of size 4 are now properly created and removed A warmachine skill exploit was rolled back and skills reverted Huge creatures move a lot faster now Being attacked with a spell no longer gives target the Hunted tag You can no longer hitch horses to a cart being dragged You no longer get the option to lead creatures as a passenger since it doesn’t work Dropping dirt should no longer raise cliff tiles', '<ul><li>You now have to string a shaft in order to create a fishing rod instead of the old way</li>\n<li>Mine tiles that share corners with 2 cave entrances can be mined now</li>\n<li>Item piles of size 4 are now properly created and removed</li>\n<li>A warmachine skill exploit was rolled back and skills reverted</li>\n<li>Huge creatures move a lot faster now</li>\n<li>Being attacked with a spell no longer gives target the Hunted tag</li>\n<li>You can no longer hitch horses to a cart being dragged</li>\n<li>You no longer get the option to lead creatures as a passenger since it doesn’t work</li>\n<li>Dropping dirt should no longer raise cliff tiles</li></ul>', 6),
(3640, 962, '121127 Messages, temperatures, names, movement fixes', '121127_Messages.2C_temperatures.2C_names.2C_movement_fixes', 'Fishing poles are no longer replaced when the line snaps, losing their enchantments 50 kg fish now has same ratio of weight loss as less weight Stopping stealth action no longer locks the button Flowers and ropes should start displaying properly in bulk containers Artifact usage messages improved A few poorly designed popup windows such as kingdom status should be easier to read now Dragon scale armour now uses the proper icons Enemy presence counter for enemies should no longer be reset when doing /stuck Failing to light meditation path now gives a message indicating time until next available enlightenment if that’s what’s blocking Creature name should now update properly when becoming diseased Charcoal piles will now properly update damage while unlit Diagonal cave walls were not blocking attacks in certain cases Light tokens and camp fires will now burn out as intended Some new movement for shy creatures trying to avoid players better Path leader window now has an empty line after every level instead of after 10 names Toggling climb while on a mount or vehicle will no longer enable the button Boosted the spell Scorn of Libila Getting hit by archery should now also trigger the 5 minute log-off timer, similar as melee PvP Splitting liquids should transfer properties better Weaponless fighting skill now modifies weaponless damage up to 3 times normal Base damage for weaponless players increased Armour equipped on kingdom guards will now have effect versus archery and normal attacks Warmachines now hit the south and east fence/wall of a tile as well Lamps on deeds are now lit a bit earlier in the evenings Heated and lit lanterns no longer produce twice the light Creatures will now be better blocked by mine doors (a bit too well at the moment maybe) Lockpicking a door or gate with an unlocked lock will now properly lock the lock Newly created street lamps should no longer become instacold Alliance disband and control messages were move to the event window Fixed more corpse name issues There is now a message when your skills are saved by res stones', '<ul><li>Fishing poles are no longer replaced when the line snaps, losing their enchantments</li>\n<li>50 kg fish now has same ratio of weight loss as less weight</li>\n<li>Stopping stealth action no longer locks the button</li>\n<li>Flowers and ropes should start displaying properly in bulk containers</li>\n<li>Artifact usage messages improved</li>\n<li>A few poorly designed popup windows such as kingdom status should be easier to read now</li>\n<li>Dragon scale armour now uses the proper icons</li>\n<li>Enemy presence counter for enemies should no longer be reset when doing /stuck</li>\n<li>Failing to light meditation path now gives a message indicating time until next available enlightenment if that’s what’s blocking</li>\n<li>Creature name should now update properly when becoming diseased</li>\n<li>Charcoal piles will now properly update damage while unlit</li>\n<li>Diagonal cave walls were not blocking attacks in certain cases</li>\n<li>Light tokens and camp fires will now burn out as intended</li>\n<li>Some new movement for shy creatures trying to avoid players better</li>\n<li>Path leader window now has an empty line after every level instead of after 10 names</li>\n<li>Toggling climb while on a mount or vehicle will no longer enable the button</li>\n<li>Boosted the spell Scorn of Libila</li>\n<li>Getting hit by archery should now also trigger the 5 minute log-off timer, similar as melee PvP</li>\n<li>Splitting liquids should transfer properties better</li>\n<li>Weaponless fighting skill now modifies weaponless damage up to 3 times normal</li>\n<li>Base damage for weaponless players increased</li>\n<li>Armour equipped on kingdom guards will now have effect versus archery and normal attacks</li>\n<li>Warmachines now hit the south and east fence/wall of a tile as well</li>\n<li>Lamps on deeds are now lit a bit earlier in the evenings</li>\n<li>Heated and lit lanterns no longer produce twice the light</li>\n<li>Creatures will now be better blocked by mine doors (a bit too well at the moment maybe)</li>\n<li>Lockpicking a door or gate with an unlocked lock will now properly lock the lock</li>\n<li>Newly created street lamps should no longer become instacold</li>\n<li>Alliance disband and control messages were move to the event window</li>\n<li>Fixed more corpse name issues</li>\n<li>There is now a message when your skills are saved by res stones</li></ul>\n<p><br/>\n</p>', 7),
(3641, 962, '121123 All items in containers visible, Poison/disease effects updating', '121123_All_items_in_containers_visible.2C_Poison.2Fdisease_effects_updating', 'The karma option summon corpse will no longer summon corpse from someones inventory You should now be seeing all items when opening a container instead of only the first 100 Poison and disease effects should now be better updated at respawn and login Emotes at bodyparts are still a bit weird but doesn’t always show it as “your” when doing on someone else', '<ul><li>The karma option summon corpse will no longer summon corpse from someones inventory</li>\n<li>You should now be seeing all items when opening a container instead of only the first 100</li>\n<li>Poison and disease effects should now be better updated at respawn and login</li>\n<li>Emotes at bodyparts are still a bit weird but doesn’t always show it as “your” when doing on someone else</li></ul>\n<p><br/>\n</p>', 8),
(3642, 962, '121122 Improving denerfed, Chaos pvp deed restriction lifted', '121122_Improving_denerfed.2C_Chaos_pvp_deed_restriction_lifted', 'You can move around while improving again Attacking enemy alliance members on their deeds is no longer prevented on Chaos Equipping and removing items should now be properly visible to people watching your eqiupment window', '<ul><li>You can move around while improving again</li>\n<li>Attacking enemy alliance members on their deeds is no longer prevented on Chaos</li>\n<li>Equipping and removing items should now be properly visible to people watching your eqiupment window</li></ul>\n<p><br/>\n</p>', 9),
(3643, 962, '121121 Global chat colors', '121121_Global_chat_colors', 'Moderators will now use their colors in global chat A bug with global ignore was fixed Dropping items in cave corners that would end up in the wall should now appear at your feet In the rare occasions where boats and carts in caves would end up in the wall they should now just not move You may no longer vote away mayors from non-democracies Fixed a bug with doors becoming stuck by mines that collapsed Fixed a bug that blocked building kingdom towers on epic', '<ul><li>Moderators will now use their colors in global chat</li>\n<li>A bug with global ignore was fixed</li>\n<li>Dropping items in cave corners that would end up in the wall should now appear at your feet</li>\n<li>In the rare occasions where boats and carts in caves would end up in the wall they should now just not move</li>\n<li>You may no longer vote away mayors from non-democracies</li>\n<li>Fixed a bug with doors becoming stuck by mines that collapsed</li>\n<li>Fixed a bug that blocked building kingdom towers on epic</li></ul>\n<p><br/>\n</p>', 10),
(3644, 962, '121120 Alliance chat fix', '121120_Alliance_chat_fix', 'Alliance chat will now work after renaming your deed Guard tower building fixed for custom kingdoms Planting storage bins no longer triggers the sign planting counter. Also they will properly lose the planted flag when picked up.', '<ul><li>Alliance chat will now work after renaming your deed</li>\n<li>Guard tower building fixed for custom kingdoms</li>\n<li>Planting storage bins no longer triggers the sign planting counter. Also they will properly lose the planted flag when picked up.</li></ul>', 11),
(3645, 962, '121116 Renaming deeds, enchanted grass fix', '121116_Renaming_deeds.2C_enchanted_grass_fix', 'Enchanted grass was both bugged and had too high decay, which was remedied Doors and gates close to caves should now work properly Expelling players from custom kingdoms should now work Villages may now be renamed as per forum suggestion, using the ‘resize’ option', '<ul><li>Enchanted grass was both bugged and had too high decay, which was remedied</li>\n<li>Doors and gates close to caves should now work properly</li>\n<li>Expelling players from custom kingdoms should now work</li>\n<li>Villages may now be renamed as per forum suggestion, using the ‘resize’ option</li></ul>\n<p><br/>\n</p>', 12),
(3646, 962, '121115 Bulk items, global ignore, creature movement', '121115_Bulk_items.2C_global_ignore.2C_creature_movement', 'Bulk items should now have basic theft prevention Setting positive reputation should now properly remove the player from being attacked by settlement guards /ignore <playername> should now work for global kingdom chat Creatures should now move out from most of their stuck positions Hell horse speed and fight skill gain were tweaked Performing actions on creatures while they die no longer should lock up the item and action timer Long action timers such as mining were tweaked downwards', '<ul><li>Bulk items should now have basic theft prevention</li>\n<li>Setting positive reputation should now properly remove the player from being attacked by settlement guards</li>\n<li>/ignore &lt;playername&gt; should now work for global kingdom chat</li>\n<li>Creatures should now move out from most of their stuck positions</li>\n<li>Hell horse speed and fight skill gain were tweaked</li>\n<li>Performing actions on creatures while they die no longer should lock up the item and action timer</li>\n<li>Long action timers such as mining were tweaked downwards</li></ul>', 13),
(3647, 962, '121113 Bug hunt first edition', '121113_Bug_hunt_first_edition', 'Now that the new 3D blocking system works, we can finally focus on the old bug list. It feels very rewarding to sort out old problems. These are the first slew of bug fixes: Timers are now properly affected by stamina again Hell horse speed should now be properly up to date Commanders should now be able to access ship holds (still not work with the items though) Excessive mine doors/cave exit collapsing was fixed Increased creature count on Deliverance and Celebration Thrown creatures are now ridable afterwards Creatures should be less stuck waterside now Filet weight and numbers were tweaked for large fish to less filets with more weight Mouth of Vynora recharge time was increased to approx 12 hours You can now see server status if you go to http://jenn001.game.wurmonline.com/battles/stats.html or the equivalent for your server RT no longer turns into Venom when changing servers Respawning tower guards are no longer equippable Grooming should no longer spam event Woven fences should no longer block actions Turning while dragging no longer prevents stamina regain', '<p>Now that the new 3D blocking system works, we can finally focus on the old bug list. It feels very rewarding to sort out old problems. These are the first slew of bug fixes:\n</p>\n<ul><li>Timers are now properly affected by stamina again</li>\n<li>Hell horse speed should now be properly up to date</li>\n<li>Commanders should now be able to access ship holds (still not work with the items though)</li>\n<li>Excessive mine doors/cave exit collapsing was fixed</li>\n<li>Increased creature count on Deliverance and Celebration</li>\n<li>Thrown creatures are now ridable afterwards</li>\n<li>Creatures should be less stuck waterside now</li>\n<li>Filet weight and numbers were tweaked for large fish to less filets with more weight</li>\n<li>Mouth of Vynora recharge time was increased to approx 12 hours</li>\n<li>You can now see server status if you go to <a class=\"external free\" href=\"http://jenn001.game.wurmonline.com/battles/stats.html\" rel=\"nofollow\">http://jenn001.game.wurmonline.com/battles/stats.html</a> or the equivalent for your server</li>\n<li>RT no longer turns into Venom when changing servers</li>\n<li>Respawning tower guards are no longer equippable</li>\n<li>Grooming should no longer spam event</li>\n<li>Woven fences should no longer block actions</li>\n<li>Turning while dragging no longer prevents stamina regain</li></ul>', 14),
(3648, 962, '121109 Leaking walls status', '121109_Leaking_walls_status', 'One bug with the fences and walls letting creatures escape was found and fixed. As of Saturday there has been more bug fixes. We are gathering reports.', '<ul><li>One bug with the fences and walls letting creatures escape was found and fixed.</li>\n<li>As of Saturday there has been more bug fixes. We are gathering reports.</li></ul>', 15),
(3649, 962, '121108 More fixes with walls and fences', '121108_More_fixes_with_walls_and_fences', 'Since yesterday creatures have occasionally moved through fences and walls. We have found and fixed one reason for this and hopefully that’s it. We will keep on the lookout for more reports. Hell horses now move 20% faster than normal horses. Various small other quick fixes such as stamina regain when turning and dragging, typos etc.', '<ul><li>Since yesterday creatures have occasionally moved through fences and walls. We have found and fixed one reason for this and hopefully that’s it. We will keep on the lookout for more reports.</li>\n<li>Hell horses now move 20% faster than normal horses.</li>\n<li>Various small other quick fixes such as stamina regain when turning and dragging, typos etc.</li></ul>', 16),
(3650, 962, '121107 Preparation Update no 1', '121107_Preparation_Update_no_1', 'Due to a bug when initially releasing this update a lot of creatures escaped their pens. We apologize for this. We will not make a rollback this time since it would mean downtime until tomorrow. We hope you can acknowledge that we are in a state of heavy development and thank you for your continued support. A new feature in the system is that relatively smart creatures like trolls and goblins will escape unlocked pens. They will however not use village settings for passing gates. Only players will be affected by that setting. New 3d collision detection system, mainly intended for multistory houses. Beds are now usable regardless of arch walls New houses now need to be on flat ground. Existing non-flat houses may continue to exist, but these will not support multistory and it’s related features. You may now improve Red, Green and Blue dye using the base material. Spy protection should no longer block players that converted on another server Mine doors should no longer block players that converted on another server Creature equipment window now updates correctly when adding or removing items /refer should not give a markup error while not premium Dredging no longer works on land while in a boat Writs no longer have an arched walls warning Destroyed doors should no longer block players Sleeping in a rented bed should now work Epic terraforming events will now destroy walls on tiles that are too steep', '<ul><li>Due to a bug when initially releasing this update a lot of creatures escaped their pens. We apologize for this. We will not make a rollback this time since it would mean downtime until tomorrow. We hope you can acknowledge that we are in a state of heavy development and thank you for your continued support.</li>\n<li>A new feature in the system is that relatively smart creatures like trolls and goblins will escape unlocked pens. They will however not use village settings for passing gates. Only players will be affected by that setting.</li>\n<li>New 3d collision detection system, mainly intended for multistory houses.</li>\n<li>Beds are now usable regardless of arch walls</li>\n<li>New houses now need to be on flat ground. Existing non-flat houses may continue to exist, but these will not support multistory and it’s related features.</li>\n<li>You may now improve Red, Green and Blue dye using the base material.</li>\n<li>Spy protection should no longer block players that converted on another server</li>\n<li>Mine doors should no longer block players that converted on another server</li>\n<li>Creature equipment window now updates correctly when adding or removing items</li>\n<li>/refer should not give a markup error while not premium</li>\n<li>Dredging no longer works on land while in a boat</li>\n<li>Writs no longer have an arched walls warning</li>\n<li>Destroyed doors should no longer block players</li>\n<li>Sleeping in a rented bed should now work</li>\n<li>Epic terraforming events will now destroy walls on tiles that are too steep</li></ul>', 17),
(3651, 962, '120831 Timer, Invulnerability and Epic mission changes', '120831_Timer.2C_Invulnerability_and_Epic_mission_changes', 'The recent Wind of Ages change was reverted and modified so that low stamina has the same effect as it used to. However, the effect of WoA has increased now and should match peoples expectations better. Removed logon invulnerability outside own deeds on pvp servers since its alt abusability exceeds the rare benefits Fixed the bug where finished Epic missions weren’t registered on the login server. Also balanced the power of the deities. Fixed a bug where the Karma option on body didn’t appear. Signatures no longer reset under 20ql. Creature movement is more smooth in the unstable client. Note that some glitches have been reported where creatures seem to keep moving in a forward line. Consider switching to the stable client for now if you have this problem. Unfinished altars no longer require ‘unknown’ bowls. Casting Bless and Nolocate should give error messages if it’s not possible.', '<ul><li>The recent Wind of Ages change was reverted and modified so that low stamina has the same effect as it used to. However, the effect of WoA has increased now and should match peoples expectations better.</li>\n<li>Removed logon invulnerability outside own deeds on pvp servers since its alt abusability exceeds the rare benefits</li>\n<li>Fixed the bug where finished Epic missions weren’t registered on the login server. Also balanced the power of the deities.</li>\n<li>Fixed a bug where the Karma option on body didn’t appear.</li>\n<li>Signatures no longer reset under 20ql.</li>\n<li>Creature movement is more smooth in the unstable client. Note that some glitches have been reported where creatures seem to keep moving in a forward line. Consider switching to the stable client for now if you have this problem.</li>\n<li>Unfinished altars no longer require ‘unknown’ bowls.</li>\n<li>Casting Bless and Nolocate should give error messages if it’s not possible.</li></ul>\n<p><br/>\n</p>', 18),
(3652, 962, '120827 Monday update', '120827_Monday_update', 'During the update today we ran into some issues when converting the database to handle multi storey buildings. Gate locks and locks to buildings went missing for a short period but we sorted the problem quickly and everything is back to normal. No-drop items such as writs, settlement forms etc. should no longer be lost on server transfer. Fireplaces are now properly impacted by quality level. It has been bugged for a long time Street lamps on deed no longer use up oil. Instead, any spirit guards will use oil barrels to fill street lamps up to 50 tiles from deed. Double house door sound has been removed. Horde of the Summoned recruits will now have Libila as their faith. Non-premiums should now be able to transfer via epic portal between Celebration and Affliction. The faith bonus provided by altars should now work better and bugs there have been fixed. Wind of Ages has been tweaked to deal with some issues it has had at high casts. The bug where walls could go missing was fixed. You no longer get a large reputation hit from lockpicking an enemy house on home servers. Small wine barrels are now correctly named. Note these do not yet have models. Temporary Fix: Animals can no longer pass arched walls. This will be reverted once the bug with arched walls allowing any animals through regardless of door type is fixed.', '<p>During the update today we ran into some issues when converting the database to handle multi storey buildings. Gate locks and locks to buildings went missing for a short period but we sorted the problem quickly and everything is back to normal.\n</p>\n<ul><li>No-drop items such as writs, settlement forms etc. should no longer be lost on server transfer.</li>\n<li>Fireplaces are now properly impacted by quality level. It has been bugged for a long time</li>\n<li>Street lamps on deed no longer use up oil. Instead, any spirit guards will use oil barrels to fill street lamps up to 50 tiles from deed.</li>\n<li>Double house door sound has been removed.</li>\n<li>Horde of the Summoned recruits will now have Libila as their faith.</li>\n<li>Non-premiums should now be able to transfer via epic portal between Celebration and Affliction.</li>\n<li>The faith bonus provided by altars should now work better and bugs there have been fixed.</li>\n<li>Wind of Ages has been tweaked to deal with some issues it has had at high casts.</li>\n<li>The bug where walls could go missing was fixed.</li>\n<li>You no longer get a large reputation hit from lockpicking an enemy house on home servers.</li>\n<li>Small wine barrels are now correctly named. Note these do not yet have models.</li>\n<li>Temporary Fix: Animals can no longer pass arched walls. This will be reverted once the bug with arched walls allowing any animals through regardless of door type is fixed.</li></ul>', 19),
(3653, 962, '120824 Some fixes for next patch', '120824_Some_fixes_for_next_patch', 'The following issues have hopefully been fixed today and will take effect after an upcoming patch: No-drop items such as writs, settlement forms etc. should no longer be lost on server transfer. Double house door sound has been removed. Horde of the Summoned recruits will now have Libila as their faith. Non-premiums should now be able to transfer via epic portal between Celebration and Affliction. The faith bonus provided by altars should now work better and bugs there have been fixed. Wind of Ages has been tweaked to deal with some issues it has had at high casts. The bug where walls could go missing was fixed. You no longer get a large reputation hit from lockpicking an enemy house on home servers. Small wine barrels are now correctly named. Note these do not yet have models. Temporary Fix: Animals can no longer pass arched walls. This will be reverted once the bug with arched walls allowing any animals through regardless of door type is fixed. Oh, and we’ve got news back in the launcher now after fixing an error in the URL from which it reads RSS feeds.', '<p>The following issues have hopefully been fixed today and will take effect after an upcoming patch:\n</p>\n<ul><li>No-drop items such as writs, settlement forms etc. should no longer be lost on server transfer.</li>\n<li>Double house door sound has been removed.</li>\n<li>Horde of the Summoned recruits will now have Libila as their faith.</li>\n<li>Non-premiums should now be able to transfer via epic portal between Celebration and Affliction.</li>\n<li>The faith bonus provided by altars should now work better and bugs there have been fixed.</li>\n<li>Wind of Ages has been tweaked to deal with some issues it has had at high casts.</li>\n<li>The bug where walls could go missing was fixed.</li>\n<li>You no longer get a large reputation hit from lockpicking an enemy house on home servers.</li>\n<li>Small wine barrels are now correctly named. Note these do not yet have models.</li>\n<li>Temporary Fix: Animals can no longer pass arched walls. This will be reverted once the bug with arched walls allowing any animals through regardless of door type is fixed.</li></ul>\n<p><br/>\nOh, and we’ve got news back in the launcher now after fixing an error in the URL from which it reads RSS feeds.\n</p>', 20),
(3654, 962, '120702 Salt renamed', '120702_Salt_renamed', 'Normal salt was erroneously named Source Salt during the weekend. Reverted. Some tools that had no skillgain should now do that again. Non-villager boats may now be conquered on Chaos. Grass growth was enabled again since it was not the reason for lag.', '<ul><li>Normal salt was erroneously named Source Salt during the weekend. Reverted.</li>\n<li>Some tools that had no skillgain should now do that again.</li>\n<li>Non-villager boats may now be conquered on Chaos.</li>\n<li>Grass growth was enabled again since it was not the reason for lag.</li></ul>', 21),
(3655, 962, '120629 Weapon skill changes', '120629_Weapon_skill_changes', 'Weapon skillgain for low quality/damage weapons was too high and weapon skill gain was tweaked upwards a bit overall. Archery skillgain for using shafts on creatures was a bug borderline exploit. 11 players on Epic with archery skill above 75 were assumed to have used this and were tweaked down towards 75. Their body control were also tweaked towards 30 by the same amount (4/5ths). Skills on Epic will be kept in order like this so report these situations faster. Archery skillgain is now more tied to damage dealt as well.', '<ul><li>Weapon skillgain for low quality/damage weapons was too high and weapon skill gain was tweaked upwards a bit overall.</li>\n<li>Archery skillgain for using shafts on creatures was a bug borderline exploit. 11 players on Epic with archery skill above 75 were assumed to have used this and were tweaked down towards 75. Their body control were also tweaked towards 30 by the same amount (4/5ths). Skills on Epic will be kept in order like this so report these situations faster. Archery skillgain is now more tied to damage dealt as well.</li></ul>', 22),
(3656, 962, '120626 Even more oil denerfing', '120626_Even_more_oil_denerfing', 'Olives will weight a bit more and when you press them you’ll get three times as much oil Lamps burn at 1/4th the rate now', '<ul><li>Olives will weight a bit more and when you press them you’ll get three times as much oil</li>\n<li>Lamps burn at 1/4th the rate now</li></ul>', 23),
(3657, 962, '120621 Olive yield increased', '120621_Olive_yield_increased', 'With this update today olive yield has been increased for higher ages. And the previously mentioned oil barrel feature is coming live.', '<p>With this update today olive yield has been increased for higher ages. And the previously mentioned oil barrel feature is coming live.\n</p>', 24),
(3658, 962, '120620 Circumvening the nerf', '120620_Circumvening_the_nerf', 'As expected there are worries that it will become too much of a chore to keep lamps filled with oil or tar. Now, tar isn’t _really_ supposed to be used in lamps but it will still be possible to use of course since it would be too much of a nerf to remove that. Olive oil finally has the use and value it was supposed to from the very beginning. I’ve added the possibility to build an “oil barrel” which will hold huge amounts of olive oil. If you keep a barrel on deed the guards will use the oil within to fill your street lamps. Guards can only deal with olive oil though so you can’t fill it with tar. I also added the possibility to build armour stand and bow rack. The models are lacking for those as well but they will arrive eventually. I just had to restart the Epic servers for another reason so they received this update and can try it out a bit before the other servers which will be restarted tomorrow.', '<p>As expected there are worries that it will become too much of a chore to keep lamps filled with oil or tar. Now, tar isn’t _really_ supposed to be used in lamps but it will still be possible to use of course since it would be too much of a nerf to remove that. Olive oil finally has the use and value it was supposed to from the very beginning.\n</p>\n<p>I’ve added the possibility to build an “oil barrel” which will hold huge amounts of olive oil. If you keep a barrel on deed the guards will use the oil within to fill your street lamps. Guards can only deal with olive oil though so you can’t fill it with tar. \n</p>\n<p>I also added the possibility to build armour stand and bow rack. The models are lacking for those as well but they will arrive eventually.\n</p>\n<p>I just had to restart the Epic servers for another reason so they received this update and can try it out a bit before the other servers which will be restarted tomorrow.\n</p>', 25),
(3659, 962, '120613 Neutral Chaos deeds, portal from GV fix in todays update', '120613_Neutral_Chaos_deeds.2C_portal_from_GV_fix_in_todays_update', 'The starter deed guards on Chaos should now be properly neutral to players The portal from Golden Valley put players in the water on Epic servers which was fixed HOTS can now attack each others settlements properly without declaring war Traders should now display tax rate and how much they have added to upkeep in taxes There is now a note that you need to adhere to the code of conduct when writing Kingdom History entries;) We’ve received reports that Java 7 Update 5 has problems starting Wurm. It seems to be a cache issue. If you upgrade and run into errors: clear the java cache.', '<ul><li>The starter deed guards on Chaos should now be properly neutral to players</li>\n<li>The portal from Golden Valley put players in the water on Epic servers which was fixed</li>\n<li>HOTS can now attack each others settlements properly without declaring war</li>\n<li>Traders should now display tax rate and how much they have added to upkeep in taxes</li>\n<li>There is now a note that you need to adhere to the code of conduct when writing Kingdom History entries;)</li>\n<li>We’ve received reports that Java 7 Update 5 has problems starting Wurm. It seems to be a cache issue. If you upgrade and run into errors: clear the java cache.</li></ul>\n<p><br/>\n</p>', 26),
(3660, 962, '120605 Faith zone changes/Achievement bugfix', '120605_Faith_zone_changes.2FAchievement_bugfix', 'Fixes a bug where achievements didn’t properly transfer between servers. Lost achievements will have to be regained. Due to bugginess and obsolete code, faith zones changed so only one deity may dominate an area', '<ul><li>Fixes a bug where achievements didn’t properly transfer between servers. Lost achievements will have to be regained.</li>\n<li>Due to bugginess and obsolete code, faith zones changed so only one deity may dominate an area</li></ul>', 27),
(3661, 962, '120427 Inner walls by Zcul!', '120427_Inner_walls_by_Zcul.21', 'You may now build walls inside structures, creating rooms. Zcul is the genious behind this addition You may now restrict mine doors to your alliance Gate management for massive amounts of gates was given a nudge but couldn\'t be tested Some methods were added to Chaos to prevent planting of non-allied deeds. Only allies or citizens should now be able to plant within 100 tiles of the perimeter of an existing settlement on Chaos', '<ul><li>You may now build walls inside structures, creating rooms. Zcul is the genious behind this addition</li>\n<li>You may now restrict mine doors to your alliance</li>\n<li>Gate management for massive amounts of gates was given a nudge but couldn\'t be tested</li>\n<li>Some methods were added to Chaos to prevent planting of non-allied deeds. Only allies or citizens should now be able to plant within 100 tiles of the perimeter of an existing settlement on Chaos</li></ul>', 28),
(3662, 962, '120424 PayPal issues being sorted', '120424_PayPal_issues_being_sorted', 'This Friday, PayPal updated their system. Most payments were still working afterwards but one of their servers failed to communicate with our servers. Yesterday we updated our code in order to fix this error. It worked well for several hours but suddenly our server stopped handling orders. We\'re looking into the problem and will handle your payments as soon as possible. Update: The systems are now working again and your payments are being processed automatically as the transactions are re-issued by PayPal during the day. You may use the shop safely.', '<ul><li>This Friday, PayPal updated their system. Most payments were still working afterwards but one of their servers failed to communicate with our servers. Yesterday we updated our code in order to fix this error. It worked well for several hours but suddenly our server stopped handling orders. We\'re looking into the problem and will handle your payments as soon as possible.</li>\n<li>Update: The systems are now working again and your payments are being processed automatically as the transactions are re-issued by PayPal during the day. You may use the shop safely.</li></ul>', 29);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(3663, 962, '120423 Chaos PvP plans', '120423_Chaos_PvP_plans', 'The Chaos server will be removing some of the PvP restrictions that doesn\'t go well with it being a PvP server. Effectively, some time after the 1st of May the changes listed below will be introduced. Up until then those of you who wish to leave will receive free disbands effective only on the Chaos server! (minus the free upkeep added). Any traders on deed will be removed and you will receive 20 silver as a reimbursement. The major changes will be to remove all penalties for attacking each other and give battle ranks and affinities for slaying premium accounts, as well as removing the requirement to declare war before raiding. On a totally unrelated note, large axes henceforth will be called just axes or medium axes.', '<ul><li>The Chaos server will be removing some of the PvP restrictions that doesn\'t go well with it being a PvP server. Effectively, some time after the 1st of May the changes listed below will be introduced. Up until then those of you who wish to leave will receive free disbands effective only on the Chaos server! (minus the free upkeep added). Any traders on deed will be removed and you will receive 20 silver as a reimbursement.</li>\n<li>The major changes will be to remove all penalties for attacking each other and give battle ranks and affinities for slaying premium accounts, as well as removing the requirement to declare war before raiding.</li>\n<li>On a totally unrelated note, large axes henceforth will be called just axes or medium axes.</li></ul>', 30),
(3664, 962, '120419 Fixed timers and gate hopping', '120419_Fixed_timers_and_gate_hopping', 'The mining timers that were increased unintendedly were reduced again You may now have troubles entering a locked gate if you are engaged with a player opponent. Might be able to sometimes, might be unable to sometimes. Gate hopping fix now applies only to non-deeded gates and doors, or ones on the border of the deed. It\'s still being developed and tested. Fishing and digging may now yield rare items Vynora priests will receive alignment for cutting down trees. Alignment gain was changed to require a certain age though.', '<ul><li>The mining timers that were increased unintendedly were reduced again</li>\n<li>You may now have troubles entering a locked gate if you are engaged with a player opponent. Might be able to sometimes, might be unable to sometimes.</li>\n<li>Gate hopping fix now applies only to non-deeded gates and doors, or ones on the border of the deed. It\'s still being developed and tested.</li>\n<li>Fishing and digging may now yield rare items</li>\n<li>Vynora priests will receive alignment for cutting down trees. Alignment gain was changed to require a certain age though.</li></ul>\n<p><br/>\n</p>', 31),
(3665, 962, '120418 Rare item functionalities', '120418_Rare_item_functionalities', 'First a note regarding repairing - it seems to take longer than it should in many cases now and will receive a fix. Most of the planned or possible rare item functionalities have now been implemented. The following list contains suggestions for rare items that have been implemented in one form or another (Many thanks Zao and Klaa for compiling the list): Materials have faster associated timers and may turn constructed item into rare item Locks are harder to pick Lockpicks break less and aid picking Containers (including boats) are harder to pick Arrows hit harder and miss less Bows hit harder and miss less All items get higher default price depending on rarity Ships sail faster (up to max so good only for fewer people) Carts move faster Yoyos and Dolls succeed more Fishing poles dmg less and have better odds at rare fish General tools are faster Fires heat up faster and stay lit longer. Altars get bonus to normal affects and alignment during prayers and sermons Food gives more nutrition Drinks are more potent Gems store more favor Warmachines do more damage Healing items has better effect Signs have a few more letters Horseshoes improve speed Butchering knives increase meat yield and item ql', '<ul><li>First a note regarding repairing - it seems to take longer than it should in many cases now and will receive a fix.</li>\n<li>Most of the planned or possible rare item functionalities have now been implemented. The following list contains suggestions for rare items that have been implemented in one form or another (Many thanks Zao and Klaa for compiling the list):</li></ul>\n<ul><li>Materials have faster associated timers and may turn constructed item into rare item</li>\n<li>Locks are harder to pick</li>\n<li>Lockpicks break less and aid picking</li>\n<li>Containers (including boats) are harder to pick</li>\n<li>Arrows hit harder and miss less</li>\n<li>Bows hit harder and miss less</li>\n<li>All items get higher default price depending on rarity</li>\n<li>Ships sail faster (up to max so good only for fewer people)</li>\n<li>Carts move faster</li>\n<li>Yoyos and Dolls succeed more</li>\n<li>Fishing poles dmg less and have better odds at rare fish</li>\n<li>General tools are faster</li>\n<li>Fires heat up faster and stay lit longer.</li>\n<li>Altars get bonus to normal affects and alignment during prayers and sermons</li>\n<li>Food gives more nutrition</li>\n<li>Drinks are more potent</li>\n<li>Gems store more favor</li>\n<li>Warmachines do more damage</li>\n<li>Healing items has better effect</li>\n<li>Signs have a few more letters</li>\n<li>Horseshoes improve speed</li>\n<li>Butchering knives increase meat yield and item ql</li></ul>', 32),
(3666, 962, '120417 Important changes to item construction and gatehopping', '120417_Important_changes_to_item_construction_and_gatehopping', 'In approximately two weeks you will no longer be able to create larger items inside smaller ones. You will receive warnings about this in order to encourage you to change behaviour. In order to prevent gate hopping, house doors will now stay open for one minute if you pass them while there is an enemy closeby. Certain timers that were increased too much in an earlier update today were brought in line. Minimum repair time was lowered. The orb of doom now has 1 hour cooldown. Area spells now have 2 minutes cooldown. We don\'t support area cooldowns. Fishing rods damage received another tweak.', '<ul><li>In approximately two weeks you will no longer be able to create larger items inside smaller ones. You will receive warnings about this in order to encourage you to change behaviour.</li>\n<li>In order to prevent gate hopping, house doors will now stay open for one minute if you pass them while there is an enemy closeby.</li>\n<li>Certain timers that were increased too much in an earlier update today were brought in line.</li>\n<li>Minimum repair time was lowered.</li>\n<li>The orb of doom now has 1 hour cooldown.</li>\n<li>Area spells now have 2 minutes cooldown. We don\'t support area cooldowns.</li>\n<li>Fishing rods damage received another tweak.</li></ul>', 33),
(3667, 962, '120414 A few minor but annoying bugs fixed', '120414_A_few_minor_but_annoying_bugs_fixed', 'Some items such as imperial lamps used up too little material during creation When attacking crowded creatures the slots shouldn\'t change as easily The health bar in the client should work more properly', '<ul><li>Some items such as imperial lamps used up too little material during creation</li>\n<li>When attacking crowded creatures the slots shouldn\'t change as easily</li>\n<li>The health bar in the client should work more properly</li></ul>', 34),
(3668, 962, '120306 Mainly item damage tweaks', '120306_Mainly_item_damage_tweaks', 'Area spells no longer work underwater Tree harvesting should deal less item damage. Mixing different fruit juices will remove their unique property instead of increasing one of the juice types Fish rod damage was tweaked Liquid creation should use better ratios A bug was fixed with spell buffs that didn\'t time out Those traders that were producing steel items will start to produce normal items once they run out. It was just decorative but it\'s a bug.', '<ul><li>Area spells no longer work underwater</li>\n<li>Tree harvesting should deal less item damage.</li>\n<li>Mixing different fruit juices will remove their unique property instead of increasing one of the juice types</li>\n<li>Fish rod damage was tweaked</li>\n<li>Liquid creation should use better ratios</li>\n<li>A bug was fixed with spell buffs that didn\'t time out</li>\n<li>Those traders that were producing steel items will start to produce normal items once they run out. It was just decorative but it\'s a bug.</li></ul>', 35),
(3669, 962, '120404 Horses save positions more often', '120404_Horses_save_positions_more_often', 'Horses should now save their position approximately every 10th tile so crashes should not have the same impact. Fishing spots will change with seasons. Your fishing spots have probably moved due to this. Bigger fish will be harder to catch but should on the other hand yeild higher quality levels. Repairing no longer leaves damage when complete. Client colors were modified. Dye still shows colors. Rarity is shown in color and wound coloring is back.', '<ul><li>Horses should now save their position approximately every 10th tile so crashes should not have the same impact.</li>\n<li>Fishing spots will change with seasons. Your fishing spots have probably moved due to this. Bigger fish will be harder to catch but should on the other hand yeild higher quality levels.</li>\n<li>Repairing no longer leaves damage when complete.</li>\n<li>Client colors were modified. Dye still shows colors. Rarity is shown in color and wound coloring is back.</li></ul>', 36),
(3670, 962, '120403 Colors showing in inventory', '120403_Colors_showing_in_inventory', 'Colors are now showing on inventory items - thank you Budda! Voice chat binaries were updated, so you may receive a firewall or antivirus warning message but it is safe to install. It works well by the way and we suggest you form a team in your village to try it out.', '<ul><li>Colors are now showing on inventory items - thank you Budda!</li>\n<li>Voice chat binaries were updated, so you may receive a firewall or antivirus warning message but it is safe to install. It works well by the way and we suggest you form a team in your village to try it out.</li></ul>', 37),
(3671, 962, '120402 Fixing some metallurgy, liquid mixing etc', '120402_Fixing_some_metallurgy.2C_liquid_mixing_etc', 'Numbers were off for metallurgy and some liquids such as fruit juice, which is dealt with Fungus trap was useless and can now be cast outside of mycelium and Libila influence like the Ice and Fire pillar counterparts', '<ul><li>Numbers were off for metallurgy and some liquids such as fruit juice, which is dealt with</li>\n<li>Fungus trap was useless and can now be cast outside of mycelium and Libila influence like the Ice and Fire pillar counterparts</li></ul>', 38),
(3672, 962, '120401 Lag reduction', '120401_Lag_reduction', 'Some of the lag that the recent changes introduces should be gone after this update The bug where materials sometimes weren\'t used when building was fixed Creation of lye and other liquids should use proper amounts now We don\'t have any April\'s fools joke this year. Honestly. This isn\'t a joke at all, seriously. Haha April\'s fool! Ok that was really cheap but things are hectic!', '<ul><li>Some of the lag that the recent changes introduces should be gone after this update</li>\n<li>The bug where materials sometimes weren\'t used when building was fixed</li>\n<li>Creation of lye and other liquids should use proper amounts now</li>\n<li>We don\'t have any April\'s fools joke this year. Honestly. This isn\'t a joke at all, seriously. Haha April\'s fool!</li>\n<li>Ok that was really cheap but things are hectic!</li></ul>', 39),
(3673, 962, '120331 Upwards retweaking', '120331_Upwards_retweaking', 'Prices for ropes and locks are back up at what it was before due to the wemp requirements The powerful animal loyalty was unnerfed a bit Keys will not take damage when failing to create moulds The convert bug was fixed Zombies will no longer instadie', '<ul><li>Prices for ropes and locks are back up at what it was before due to the wemp requirements</li>\n<li>The powerful animal loyalty was unnerfed a bit</li>\n<li>Keys will not take damage when failing to create moulds</li>\n<li>The convert bug was fixed</li>\n<li>Zombies will no longer instadie</li></ul>', 40),
(3674, 962, '120329 Wonderful Time(r)s!', '120329_Wonderful_Time.28r.29s.21', 'Faster timers for most actions! Timers now run on tenths of seconds, giving more precise effects of quality, skill and enchantments. This includes fighting. Less item loss on failure! Priests receive alignment modification for actions just as non-priests now Dispel now has range 24 Mounts and carts may be used in shallow water. Less land bridges - more fords! Mounts and carts may be used in steeper terrain. Less obstruction! Older creatures may spawn now - more challenge! Items have rarity! You may now occasionally succeed in creating a rare, supreme or even fantastic item. These tools are faster, weapons do more damage, and armour protects a bit better. This may also happen as you improve or polish items and rare items may turn into even rarer items. Constructing new items using rare materials may turn the unfinished item into a rare item. Rare guard towers spawn more guards, for instance. More functionality will be added over time. Known bugs: Metallurgy needs some more debugging. Chain armour creation erroneously uses up the chain on failure. Fields show the wrong textures.', '<ul><li>Faster timers for most actions!</li>\n<li>Timers now run on tenths of seconds, giving more precise effects of quality, skill and enchantments. This includes fighting.</li>\n<li>Less item loss on failure!</li>\n<li>Priests receive alignment modification for actions just as non-priests now</li>\n<li>Dispel now has range 24</li>\n<li>Mounts and carts may be used in shallow water. Less land bridges - more fords!</li>\n<li>Mounts and carts may be used in steeper terrain. Less obstruction!</li>\n<li>Older creatures may spawn now - more challenge!</li>\n<li>Items have rarity! You may now occasionally succeed in creating a rare, supreme or even fantastic item. These tools are faster, weapons do more damage, and armour protects a bit better. This may also happen as you improve or polish items and rare items may turn into even rarer items. Constructing new items using rare materials may turn the unfinished item into a rare item. Rare guard towers spawn more guards, for instance. More functionality will be added over time.</li>\n<li>Known bugs: Metallurgy needs some more debugging. Chain armour creation erroneously uses up the chain on failure. Fields show the wrong textures.</li></ul>', 41),
(3675, 962, '120315 Scrap bugfix', '120315_Scrap_bugfix', 'Since last update, low ql lumps are supposed to appear instead of metal scraps in order to improve creation. In certain instances these lumps would not appear, which has now been fixed.', '<ul><li>Since last update, low ql lumps are supposed to appear instead of metal scraps in order to improve creation. In certain instances these lumps would not appear, which has now been fixed.</li></ul>', 42),
(3676, 962, '120314 Amsterdam meeting update', '120314_Amsterdam_meeting_update', 'Inspired by the discussions at the Amsterdam Wurm meeting this weekend we\'ve managed to implement a few of the quick improvements mentioned: Only uniques break cave walls now You now get low ql lumps instead of the annoying scrap metal Construction options should now display both ways when selecting an item The max number of concurrent attackers were doubled for uniques Creature spawn points got a kick in the hind NOTE: Ridden creatures will be attacked more often The decay for butchered body parts was increased You should now be able to be passenger through palisade doors Empty bulk containers are now possible to pick up', '<p>Inspired by the discussions at the Amsterdam Wurm meeting this weekend we\'ve managed to implement a few of the quick improvements mentioned:\n</p>\n<ul><li>Only uniques break cave walls now</li>\n<li>You now get low ql lumps instead of the annoying scrap metal</li>\n<li>Construction options should now display both ways when selecting an item</li>\n<li>The max number of concurrent attackers were doubled for uniques</li>\n<li>Creature spawn points got a kick in the hind</li>\n<li>NOTE: Ridden creatures will be attacked more often</li>\n<li>The decay for butchered body parts was increased</li>\n<li>You should now be able to be passenger through palisade doors</li>\n<li>Empty bulk containers are now possible to pick up</li></ul>', 43),
(3677, 962, '120306 Archery skillgain modified', '120306_Archery_skillgain_modified', 'In an effort to make archers hunt creatures and real players instead of alt characters, archery skillgain is now more uniform for all attacks except when there is very little damage dealt, when you are deemed macroing or attacking newbie alts. Skillgain speed may need tweaking. Shieldbashing also gives more skill when damage is dealt. Kingdom rulers may no longer become champions.', '<ul><li>In an effort to make archers hunt creatures and real players instead of alt characters, archery skillgain is now more uniform for all attacks except when there is very little damage dealt, when you are deemed macroing or attacking newbie alts. Skillgain speed may need tweaking.</li>\n<li>Shieldbashing also gives more skill when damage is dealt.</li>\n<li>Kingdom rulers may no longer become champions.</li></ul>', 44),
(3678, 962, '120302 More lockpicking tweaks', '120302_More_lockpicking_tweaks', 'The base chance is still based on lock quality but a bit higher. The chance increase with skill and be maxed at 100 lockpicking skill. Chances increase more the higher skill you get. Expect to start becoming somewhat able at skill 30. The container or wall ql may halve or double the chance. Lockpick quality increases chance more than before. Gates are easier to pick. Large boats are harder to pick. Thievery skillgain was increased. The HOTS skillgain bonus for thievery skills was removed since everyone runs the same risk nowadays.', '<ul><li>The base chance is still based on lock quality but a bit higher. The chance increase with skill and be maxed at 100 lockpicking skill. Chances increase more the higher skill you get. Expect to start becoming somewhat able at skill 30. The container or wall ql may halve or double the chance. Lockpick quality increases chance more than before. Gates are easier to pick. Large boats are harder to pick.</li>\n<li>Thievery skillgain was increased.</li>\n<li>The HOTS skillgain bonus for thievery skills was removed since everyone runs the same risk nowadays.</li></ul>', 45),
(3679, 962, '120301 Changes to thievery and support case handling', '120301_Changes_to_thievery_and_support_case_handling', 'Lockpicking and stealing skillgain now is on timers. Every ten minutes you may gain the skill. We are still tweaking the system at the moment. It is pretty nerfed when it comes to skillgains and success rates especially for doors. Lock ql now sets a base chance for lockpicking difficulty where a lock of ql 99 gives you 1% base chance and a ql 19 lock gives 40%. This is then modified by the skill so that someone with skill 50 has 20% chance to pick a ql 19 lock and 0.5% to pick a ql 99 lock. The container or wall ql modifies this as well, and the difference in lockpick quality increases or decreases the overall chance by multiplying difference/3 %. Stealing is harder closer to deed center and in the vicinity of guards. The 5 tiles closest to the token can be considered extremely safe. The difficulty of stealing things is based on the quality level of the item you steal, so in order to start gaining skill you should steal low quality items. Stealing and lockpicking only works on PvP servers. Compasses are now affected by WoA There\'s now a difference between CA and CM. CM\'s may mute and /support calls now go to the CMs who may elevate them to the GM\'s in case they can\'t help out. Since stealing skillgain was tweaked using a new system everyone on the epic servers had their stealing skill multiplied down to 20%.', '<ul><li>Lockpicking and stealing skillgain now is on timers. Every ten minutes you may gain the skill.</li>\n<li>We are still tweaking the system at the moment. It is pretty nerfed when it comes to skillgains and success rates especially for doors.</li>\n<li>Lock ql now sets a base chance for lockpicking difficulty where a lock of ql 99 gives you 1% base chance and a ql 19 lock gives 40%. This is then modified by the skill so that someone with skill 50 has 20% chance to pick a ql 19 lock and 0.5% to pick a ql 99 lock. The container or wall ql modifies this as well, and the difference in lockpick quality increases or decreases the overall chance by multiplying difference/3 %.</li>\n<li>Stealing is harder closer to deed center and in the vicinity of guards. The 5 tiles closest to the token can be considered extremely safe. The difficulty of stealing things is based on the quality level of the item you steal, so in order to start gaining skill you should steal low quality items.</li>\n<li>Stealing and lockpicking only works on PvP servers.</li>\n<li>Compasses are now affected by WoA</li>\n<li>There\'s now a difference between CA and CM. CM\'s may mute and /support calls now go to the CMs who may elevate them to the GM\'s in case they can\'t help out.</li>\n<li>Since stealing skillgain was tweaked using a new system everyone on the epic servers had their stealing skill multiplied down to 20%.</li></ul>', 46),
(3680, 962, '120228 Reputation tweaks', '120228_Reputation_tweaks', 'Reputation hits for attacking and killing have been tweaked since it caused reversed grief. This applies to PvP servers where you can attack each other. You now take 20 rep hit when killing same kingdom (unless within deed perimeter, or duelling etc) so you can deal with griefers a few times. On the other hand it should be fairly slow business hunting newbies for griefers. If you attack someone out of the blue you get stamped as Hunted for half an hour which means anyone can kill you without penalty. This stays over respawn. The only \"supported solution\" on PvP servers is to get a deed for any land you claim otherwise the game considers it free-for-all. On non-homeservers (Elevation) there is no penalty at all. Magranon now has the spell locate artifact Some people on Elevation found an exploitish situation where they were gaining body control too fast. The skills involved were modified down to more sane levels.', '<ul><li>Reputation hits for attacking and killing have been tweaked since it caused reversed grief. This applies to PvP servers where you can attack each other. You now take 20 rep hit when killing same kingdom (unless within deed perimeter, or duelling etc) so you can deal with griefers a few times. On the other hand it should be fairly slow business hunting newbies for griefers. If you attack someone out of the blue you get stamped as Hunted for half an hour which means anyone can kill you without penalty. This stays over respawn. The only \"supported solution\" on PvP servers is to get a deed for any land you claim otherwise the game considers it free-for-all. On non-homeservers (Elevation) there is no penalty at all.</li>\n<li>Magranon now has the spell locate artifact</li>\n<li>Some people on Elevation found an exploitish situation where they were gaining body control too fast. The skills involved were modified down to more sane levels.</li></ul>', 47),
(3681, 962, '120217 Mount turn rate tweaked', '120217_Mount_turn_rate_tweaked', 'The turn rate for mounts were toned down and you automatically move forward slowly when pressing left or right (A or D) Login problems solved Improving arrows now takes half time More typed creatures should spawn around dens', '<ul><li>The turn rate for mounts were toned down and you automatically move forward slowly when pressing left or right (A or D)</li>\n<li>Login problems solved</li>\n<li>Improving arrows now takes half time</li>\n<li>More typed creatures should spawn around dens</li></ul>', 48),
(3682, 962, '120215 Movement changes', '120215_Movement_changes', 'The bug with doors that appeared in the latest update was resolved Boat speeds were tweaked and should work better with more passengers Mounted movement backwards is now done at 1/3 speed. Turning was made faster. Improved speed hack detection and prevention A bug where Web Armour slowed down creatures too long was fixed Fixed a bug with names disappearing out of local The HOTA was fixed Model size multiplicator for items (visual change only) now has a max value of 5 Shield bashing now toggles the icon properly Armour while worn will make Oakshell inactive on that bodypart', '<ul><li>The bug with doors that appeared in the latest update was resolved</li>\n<li>Boat speeds were tweaked and should work better with more passengers</li>\n<li>Mounted movement backwards is now done at 1/3 speed. Turning was made faster.</li>\n<li>Improved speed hack detection and prevention</li>\n<li>A bug where Web Armour slowed down creatures too long was fixed</li>\n<li>Fixed a bug with names disappearing out of local</li>\n<li>The HOTA was fixed</li>\n<li>Model size multiplicator for items (visual change only) now has a max value of 5</li>\n<li>Shield bashing now toggles the icon properly</li>\n<li>Armour while worn will make Oakshell inactive on that bodypart</li></ul>', 49),
(3683, 962, '120210 Lockpicking', '120210_Lockpicking', 'Lockpicking has been turned into a normal grindable skill which you can practice at home. Previously it gave a bonus when the game considered it to be dangerous but those situations were always avoidable. Two players on Epic have had their skills trimmed to 30 since they gained it in an overly easy way that wasn\'t reported.', '<ul><li>Lockpicking has been turned into a normal grindable skill which you can practice at home. Previously it gave a bonus when the game considered it to be dangerous but those situations were always avoidable. Two players on Epic have had their skills trimmed to 30 since they gained it in an overly easy way that wasn\'t reported.</li></ul>', 50),
(3684, 962, '120201 Stamina regain while swimming bugfix', '120201_Stamina_regain_while_swimming_bugfix', 'You now properly regain stamina offline gradually up to max after 6 hours. You should now receive a message in green when someone from your own kingdom attacks you and you are able to attack the player back without a reputation hit.', '<ul><li>You now properly regain stamina offline gradually up to max after 6 hours.</li>\n<li>You should now receive a message in green when someone from your own kingdom attacks you and you are able to attack the player back without a reputation hit.</li></ul>', 51),
(3685, 962, '120131 A few Tuesday bugfixes', '120131_A_few_Tuesday_bugfixes', 'Polearm damage bonus was increased to 2.5 versus mounted. Spears also do this damage versus mounts. Disbanding now properly modifies alliances Kingdom tower ritual missions should now only spawn on enemy home servers and non-home servers (Elevation) properly. Enemy presense should now trigger for enemy alliances A bug with epic portals allowing you to travel back to your start epic server should have been fixed.', '<ul><li>Polearm damage bonus was increased to 2.5 versus mounted. Spears also do this damage versus mounts.</li>\n<li>Disbanding now properly modifies alliances</li>\n<li>Kingdom tower ritual missions should now only spawn on enemy home servers and non-home servers (Elevation) properly.</li>\n<li>Enemy presense should now trigger for enemy alliances</li>\n<li>A bug with epic portals allowing you to travel back to your start epic server should have been fixed.</li></ul>', 52),
(3686, 962, '120127 Voice chat confusion', '120127_Voice_chat_confusion', 'Funny, the proximity voice chat we\'re advertising experiences some account confusion so the chat clients don\'t manage to log on to the system. The error is on our side but we probably can\'t fix it during the weekend so you\'ll have to wait until next week. Three cheers!', '<ul><li>Funny, the proximity voice chat we\'re advertising experiences some account confusion so the chat clients don\'t manage to log on to the system. The error is on our side but we probably can\'t fix it during the weekend so you\'ll have to wait until next week. Three cheers!</li></ul>', 53),
(3687, 962, '120126 New Client!', '120126_New_Client.21', 'Client update - version 3.1! Voice chat enabled. Try out the automatic proximity chat! New 3D model format supported with things like bones, skinning, mesh replacement and forward kinetics. This will enable us to add new and improved models and animations. Most players should experience better overall performance. You can tweak animation settings in the options panel. Lots of small bug fixes and improvements like this item selection fix: Hovering over items with the mouse should select them properly now around the edges. Support for ingame seasons. Not yet implemented. And of course Gui improvements! Server changes: The Link option should work on tree and farm tiles now. Stealing certain items usable only on ground that didn\'t work before should now work. Led creatures now receive a combat rating penalty Opponents on mounts no longer need to be moving in order to receive double damage from polearms when the attacker is on foot The reputation system for attacking players from the same kingdom on PvP servers received several improvements: There was a reputation hit for killing outlaw allies. Fixed. You may now kill anyone inside your perimeter without reputation hit. You now only receive a reputation hit when a wall of a non-deeded structure from the same kingdom is destroyed instead of previously when attacking it. You will receive a small reputation hit when you first attack someone where it is not allowed. If you are attacked in such a manner you should receive no penalty for slaying the person. The effect stays until you die or until there is a restart. Slaying or attacking someone in PvP zones, duelling areas, and during duels should give no reputation hits. A note: Armour made from glimmersteel or adamantine give better protection. Attack speed of weapons made from glimmersteel is often higher and damage dealt from adamantine. Decay and damage taken by items made from those materials should be a lot less. You can find them in terraforming events on Epic or by winning HotA tournaments. The statues won in Hunts of the Ancients should now be plantable like signs. The Affliction server (HOTS home) is now free to play. You should now be able to spawn on all permanent villages on a home server.', '<h3><span id=\"Client_update_-_version_3.1!\"></span><span class=\"mw-headline\" id=\"Client_update_-_version_3.1.21\">Client update - version 3.1!</span></h3>\n<ul><li>Voice chat enabled. Try out the automatic proximity chat!</li>\n<li>New 3D model format supported with things like bones, skinning, mesh replacement and forward kinetics. This will enable us to add new and improved models and animations.</li>\n<li>Most players should experience better overall performance. You can tweak animation settings in the options panel.</li>\n<li>Lots of small bug fixes and improvements like this item selection fix: Hovering over items with the mouse should select them properly now around the edges.</li>\n<li>Support for ingame seasons. Not yet implemented.</li>\n<li>And of course Gui improvements!</li></ul>\n<h3><span class=\"mw-headline\" id=\"Server_changes:\">Server changes:</span></h3>\n<ul><li>The Link option should work on tree and farm tiles now.</li>\n<li>Stealing certain items usable only on ground that didn\'t work before should now work.</li>\n<li>Led creatures now receive a combat rating penalty</li>\n<li>Opponents on mounts no longer need to be moving in order to receive double damage from polearms when the attacker is on foot</li>\n<li>The reputation system for attacking players from the same kingdom on PvP servers received several improvements:\n<ul><li>There was a reputation hit for killing outlaw allies. Fixed.</li>\n<li>You may now kill anyone inside your perimeter without reputation hit.</li>\n<li>You now only receive a reputation hit when a wall of a non-deeded structure from the same kingdom is destroyed instead of previously when attacking it.</li>\n<li>You will receive a small reputation hit when you first attack someone where it is not allowed. If you are attacked in such a manner you should receive no penalty for slaying the person. The effect stays until you die or until there is a restart.</li>\n<li>Slaying or attacking someone in PvP zones, duelling areas, and during duels should give no reputation hits.</li></ul></li>\n<li>A note: Armour made from glimmersteel or adamantine give better protection. Attack speed of weapons made from glimmersteel is often higher and damage dealt from adamantine. Decay and damage taken by items made from those materials should be a lot less. You can find them in terraforming events on Epic or by winning HotA tournaments.</li>\n<li>The statues won in Hunts of the Ancients should now be plantable like signs.</li>\n<li>The Affliction server (HOTS home) is now free to play.</li>\n<li>You should now be able to spawn on all permanent villages on a home server.</li></ul>\n<p><br/>\n</p>', 54),
(3688, 962, '120125 The Hunter\'s Lodge', '120125_The_Hunter.27s_Lodge', 'A new settlement has been founded on the west border of the HotA zone on Chaos in order to facilitate joining the Hunt of the Ancients. \"Hunter\'s Lodge\" is the new default spawnpoint on the server even if spawning at The Landing still should be possible. New players arriving on Chaos will spawn at Hunter\'s Lodge.', '<ul><li>A new settlement has been founded on the west border of the HotA zone on Chaos in order to facilitate joining the Hunt of the Ancients. \"Hunter\'s Lodge\" is the new default spawnpoint on the server even if spawning at The Landing still should be possible. New players arriving on Chaos will spawn at Hunter\'s Lodge.</li></ul>\n<p><br/>\n</p>', 55),
(3689, 962, '120120 Damage properly applied in PvP zones', '120120_Damage_properly_applied_in_PvP_zones', 'The increased damage on walls and fences as well as the Mine Door restriction is now properly restricted to PvP zones. The Village settting should be saved now when creating such settlement roles. The HotA pillar distribution was skewed and too easy. Next hunt they will be more properly distributed in the zone.', '<ul><li>The increased damage on walls and fences as well as the Mine Door restriction is now properly restricted to PvP zones.</li>\n<li>The Village settting should be saved now when creating such settlement roles.</li>\n<li>The HotA pillar distribution was skewed and too easy. Next hunt they will be more properly distributed in the zone.</li></ul>', 56),
(3690, 962, '120119 Boat kicking and tweak to PvP zones', '120119_Boat_kicking_and_tweak_to_PvP_zones', 'The Village setting for new village specific roles isn\'t saved unless you change to another village then back to the one you want to apply the role for. Or create with the wrong Village and set it to the proper Village afterwards. The bug is fixed next update. Boats should stop before the border now instead of kicking you when you are not allowed to to leave the server in the boat. Fences and walls now take 10 times damage off deed in PvP zones. No mine doors can be built in PvP zones.', '<ul><li>The Village setting for new village specific roles isn\'t saved unless you change to another village then back to the one you want to apply the role for. Or create with the wrong Village and set it to the proper Village afterwards. The bug is fixed next update.</li>\n<li>Boats should stop before the border now instead of kicking you when you are not allowed to to leave the server in the boat.</li>\n<li>Fences and walls now take 10 times damage off deed in PvP zones. No mine doors can be built in PvP zones.</li></ul>', 57),
(3691, 962, '120118 Hunt zones created', '120118_Hunt_zones_created', 'On the Chaos and on the Elevation servers, special Hunt zones have been created. A short description is on http://www.wurmonline.com/blog . Enjoy!', '<ul><li>On the Chaos and on the Elevation servers, special Hunt zones have been created. A short description is on <a class=\"external free\" href=\"http://www.wurmonline.com/blog\" rel=\"nofollow\">http://www.wurmonline.com/blog</a>. Enjoy!</li></ul>', 58),
(3692, 962, '120118 Duelling rings and inventory merges', '120118_Duelling_rings_and_inventory_merges', 'You should now gain fight skill if you slay premium players with skill 20+ of an opposing alliance Duelling rings were added close to the start cities on the Epic servers for removing unwanted kingdom rulers of the non-custom kingdoms Boats on PvP servers no longer have the village or friend restriction when changing servers Because of possible duplicates causing one copy to be automatically deleted, inventories will no longer merge when travelling to or from Chaos like they used to after it joined the freedom cluster', '<ul><li>You should now gain fight skill if you slay premium players with skill 20+ of an opposing alliance</li>\n<li>Duelling rings were added close to the start cities on the Epic servers for removing unwanted kingdom rulers of the non-custom kingdoms</li>\n<li>Boats on PvP servers no longer have the village or friend restriction when changing servers</li>\n<li>Because of possible duplicates causing one copy to be automatically deleted, inventories will no longer merge when travelling to or from Chaos like they used to after it joined the freedom cluster</li></ul>', 59),
(3693, 962, '120117 New Alliance System', '120117_New_Alliance_System', 'The new alliance system is now active and old alliances had to be removed. You have to form new alliances by meeting up with diplomats from other settlements. In the new alliances, there is one settlement that is the \'capital\'. The Mayor from the capital may oust your settlement from the alliance and declare wars on other alliances on PvP Servers. Alliance war have to be accepted in order to not give reputation hits for kills. You may create special village roles for different villages in order to control other members of the alliance. Killing someone from the same kingdom outside PvP Areas will give a reputation hit unless you are at war. Killing someone from the same alliance or village within the PvP zone will still give reputation hit. You should no longer become invulnerable when you lose link since linkdropping was abused. The auto invulnerability when you log on still remains. Players from warring alliances should be able to loot each other. As a diplomat, you may still declare war on other single villages but it does not involve the alliance. The future of this feature is uncertain. In the freedom cluster, if you become outlaw you are now also kicked out of your village. There is also alliance chat. If it doesn\'t turn up automatically, you may have to type /all <text>.', '<ul><li>The new alliance system is now active and old alliances had to be removed. You have to form new alliances by meeting up with diplomats from other settlements. In the new alliances, there is one settlement that is the \'capital\'. The Mayor from the capital may oust your settlement from the alliance and declare wars on other alliances on PvP Servers. Alliance war have to be accepted in order to not give reputation hits for kills.</li>\n<li>You may create special village roles for different villages in order to control other members of the alliance.</li>\n<li>Killing someone from the same kingdom outside PvP Areas will give a reputation hit unless you are at war. Killing someone from the same alliance or village within the PvP zone will still give reputation hit.</li>\n<li>You should no longer become invulnerable when you lose link since linkdropping was abused. The auto invulnerability when you log on still remains.</li>\n<li>Players from warring alliances should be able to loot each other.</li>\n<li>As a diplomat, you may still declare war on other single villages but it does not involve the alliance. The future of this feature is uncertain.</li>\n<li>In the freedom cluster, if you become outlaw you are now also kicked out of your village.</li>\n<li>There is also alliance chat. If it doesn\'t turn up automatically, you may have to type /all &lt;text&gt;.</li></ul>', 60),
(3694, 962, '120113 Voice chat being tampered with', '120113_Voice_chat_being_tampered_with', 'We are updating the voice chat binaries with a fix for unstable and it won\'t work during the weekend. Sacrificing Valrei items should work on all Epic servers. Epic creatures will no longer spawn in the Freedom cluster.', '<ul><li>We are updating the voice chat binaries with a fix for unstable and it won\'t work during the weekend.</li>\n<li>Sacrificing Valrei items should work on all Epic servers.</li>\n<li>Epic creatures will no longer spawn in the Freedom cluster.</li></ul>', 61),
(3695, 962, '120111 Upcoming changes to alliances', '120111_Upcoming_changes_to_alliances', 'Alliances will change in the near future so that a settlement may only belong to one alliance. There will be one town in charge of the alliance and its diplomats will be able to add or oust other settlements to the alliance. The town that invites another town to form an alliance becomes the alliance capital, but this can be changed later on. Diplomats of a settlement may make the settlement leave the alliance. This means that you will have to recreate your existing alliances when that update comes. Please take any steps necessary in order to prepare for a smooth transition to the new system. The reason that we change it is for clarity and things like alliance chat. The reason that we don\'t keep both system at the same time is that it would cause confusing bugridden code and alliance loops. Expect this new code early next week, but in case we run into some serious bug that must be fixed it may happen before the weekend.', '<ul><li>Alliances will change in the near future so that a settlement may only belong to one alliance. There will be one town in charge of the alliance and its diplomats will be able to add or oust other settlements to the alliance. The town that invites another town to form an alliance becomes the alliance capital, but this can be changed later on. Diplomats of a settlement may make the settlement leave the alliance.</li>\n<li>This means that you will have to recreate your existing alliances when that update comes. Please take any steps necessary in order to prepare for a smooth transition to the new system.</li>\n<li>The reason that we change it is for clarity and things like alliance chat. The reason that we don\'t keep both system at the same time is that it would cause confusing bugridden code and alliance loops. Expect this new code early next week, but in case we run into some serious bug that must be fixed it may happen before the weekend.</li></ul>', 62),
(3696, 962, '120109 Nogump nerf among other things', '120109_Nogump_nerf_among_other_things', 'The Sons of Nogump have been nerfed and an extra check for throwing through walls was added. Valrei creatures should no longer spawn inside houses or settlements. Lockpicking on pvp servers received a bug fix. You should now be able to send mail between the Chaos server and the other Freedom servers. Fix to fletching where heads were not consumed properly. Changing server with boat from Chaos should work better for villagers and friends', '<ul><li>The Sons of Nogump have been nerfed and an extra check for throwing through walls was added. Valrei creatures should no longer spawn inside houses or settlements.</li>\n<li>Lockpicking on pvp servers received a bug fix.</li>\n<li>You should now be able to send mail between the Chaos server and the other Freedom servers.</li>\n<li>Fix to fletching where heads were not consumed properly.</li>\n<li>Changing server with boat from Chaos should work better for villagers and friends</li></ul>', 63),
(3697, 962, '120105 Non-prem priests bugfix and structure option', '120105_Non-prem_priests_bugfix_and_structure_option', 'You should no longer be thrown into structures by uniques during combat. There is now an option to allow your kingdom to enter structures (thanks Zcul for coding). Non-premium priests was was a favor linking loophole which should be plugged now.', '<ul><li>You should no longer be thrown into structures by uniques during combat.</li>\n<li>There is now an option to allow your kingdom to enter structures (thanks Zcul for coding).</li>\n<li>Non-premium priests was was a favor linking loophole which should be plugged now.</li></ul>', 64),
(3698, 962, '120102 2012', '120102_2012', 'Happy New Year dear Wurmians! This year we\'ll see some real progress with graphics and lots of game improvements both in existing features and plans are to solve multi storey buildings and bridges as first projects. We also want to add a lot more construction options and hopefully we\'ll be able to look at things like rivers and seasons before this summer. Creatures summoned by the deities on Valrei like the Drakespirits will appear a lot less on non-Epic servers. They will send 1 where before they could send up to 15. Additionally, on Epic servers the toughness of the creatures summoned will be considered so fewer will spawn the tougher they are. Uniques may bash house walls with higher probability now.', '<ul><li>Happy New Year dear Wurmians! This year we\'ll see some real progress with graphics and lots of game improvements both in existing features and plans are to solve multi storey buildings and bridges as first projects. We also want to add a lot more construction options and hopefully we\'ll be able to look at things like rivers and seasons before this summer.</li>\n<li>Creatures summoned by the deities on Valrei like the Drakespirits will appear a lot less on non-Epic servers. They will send 1 where before they could send up to 15. Additionally, on Epic servers the toughness of the creatures summoned will be considered so fewer will spawn the tougher they are.</li>\n<li>Uniques may bash house walls with higher probability now.</li></ul>', 65);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(3761, 977, 'Info', 'Info', 'A player on Jenn-Kellon wild with many varied skills. He is always willing to help and is a very serious person, although the most subtle dirty joke brings his mind to the gutter. Joined in 2007 in a Wild server town called Fort Oak, he got premium in 2008 and joined Kyara. He would eventually leave to join his fellow Facepunchers in their 1-2 month towns then go back to Kyara. Went to Mol Rehan home when it came out and got profoundly disappointed by the community, went back to JK, tried to become HOTS emperor in 2011 but the gods once again corndogged him.\nHe currently lives in Kyara, providing arrows and other kinds of stuff to his village mates. He is rumored to have 99 in all skills including the ones that are yet to be implemented. He can also speak 4 different languages and completely destroy Propheteer in Call of Duty: Black Ops. Some of his friends are: Duce Mojo Einherjar Xallo the Mexican IcarusTheGreat Caius Alyeska Norad Nosyt Inacron Gavin Ganks Extrusion (gives up on every deed plan) Raloc Stickmaus Kix Kswords Kylebooze', '<p>A player on Jenn-Kellon wild with many varied skills. He is always willing to help and is a very serious person, although the most subtle dirty joke brings his mind to the gutter. Joined in 2007 in a Wild server town called Fort Oak, he got premium in 2008 and joined Kyara. He would eventually leave to join his fellow Facepunchers in their 1-2 month towns then go back to Kyara. Went to Mol Rehan home when it came out and got profoundly disappointed by the community, went back to JK, tried to become HOTS emperor in 2011 but the gods once again corndogged him.\nHe currently lives in Kyara, providing arrows and other kinds of stuff to his village mates.\n</p>\n<p>He is rumored to have 99 in all skills including the ones that are yet to be implemented. He can also speak 4 different languages and completely destroy <a class=\"mw-redirect\" href=\"/index.php/User:Propheteer\" title=\"User:Propheteer\">Propheteer</a> in Call of Duty: Black Ops.\n</p>\n<p>Some of his friends are:\n</p>\n<ul><li><a href=\"/index.php/Player:Duce\" title=\"Player:Duce\">Duce</a></li>\n<li><a href=\"/index.php/Player:Mojo\" title=\"Player:Mojo\">Mojo</a></li>\n<li><a href=\"/index.php/Player:Einherjar\" title=\"Player:Einherjar\">Einherjar</a></li>\n<li><a href=\"/index.php/Player:Xallo\" title=\"Player:Xallo\">Xallo</a> the Mexican</li>\n<li><a href=\"/index.php/Player:IcarusTheGreat\" title=\"Player:IcarusTheGreat\">IcarusTheGreat</a></li>\n<li><a href=\"/index.php/Player:Caius\" title=\"Player:Caius\">Caius</a></li>\n<li><a href=\"/index.php/Player:Alyeska\" title=\"Player:Alyeska\">Alyeska</a></li>\n<li><a class=\"new\" href=\"/index.php?title=User:Norad&amp;action=edit&amp;redlink=1\" title=\"User:Norad (page does not exist)\">Norad</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Player:Nosyt\" title=\"Player:Nosyt\">Nosyt</a></li>\n<li><a href=\"/index.php/Player:Inacron\" title=\"Player:Inacron\">Inacron</a></li>\n<li><a href=\"/index.php/Player:Gavin\" title=\"Player:Gavin\">Gavin</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Player:Ganks\" title=\"Player:Ganks\">Ganks</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/User:Propheteer\" title=\"User:Propheteer\">Extrusion</a> (gives up on every deed plan)</li>\n<li><a href=\"/index.php/Player:Raloc\" title=\"Player:Raloc\">Raloc</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Player:Stickmaus\" title=\"Player:Stickmaus\">Stickmaus</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Player:Kix\" title=\"Player:Kix\">Kix</a></li>\n<li><a href=\"/index.php/Player:Kswords\" title=\"Player:Kswords\">Kswords</a></li>\n<li><a href=\"/index.php/Player:Kylebooze\" title=\"Player:Kylebooze\">Kylebooze</a></li></ul>', 0),
(3762, 977, 'Titles and stuff you are allowed to see', 'Titles_and_stuff_you_are_allowed_to_see', 'Trollslayer Kingslayer Slayer of Champions (Doctorchaos) Earl Marshal Order of the Sad Goose', '<ul><li><a class=\"mw-redirect\" href=\"/index.php/Trollslayer\" title=\"Trollslayer\">Trollslayer</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Kingslayer\" title=\"Kingslayer\">Kingslayer</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Slayer_of_Champions\" title=\"Slayer of Champions\">Slayer of Champions</a> (Doctorchaos)</li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Earl_Marshal\" title=\"Earl Marshal\">Earl Marshal</a></li>\n<li><a href=\"/index.php/Titles\" title=\"Titles\">Order of the Sad Goose</a></li></ul>', 1),
(3766, 982, 'Description', 'Description', 'A pillar that is as powerful as it is beautiful. It seems to have some religious or symbolic meaning. Foundation pillars are mission structures requiring Masonry skill.', '<p><i>A pillar that is as powerful as it is beautiful. It seems to have some religious or symbolic meaning.</i>\n</p>\n<p><b>Foundation pillars</b> are <a href=\"/index.php/Category:Mission_structures\" title=\"Category:Mission structures\">mission structures</a> requiring <a href=\"/index.php/Masonry\" title=\"Masonry\">Masonry</a> skill.\n</p>', 0),
(3767, 982, 'Notes', 'Notes', 'Masonry skill and brick quality level (QL) determine the success rate. Building one of these in a specific area is required for certain Epic missions . Note that this item/structure is not the same as a pillar .', '<ul><li>Masonry skill and brick quality level (QL) determine the success rate.</li></ul>\n<ul><li>Building one of these in a specific area is required for certain <a class=\"mw-redirect\" href=\"/index.php/Epic_mission\" title=\"Epic mission\">Epic missions</a>.</li>\n<li>Note that this item/structure is not the same as a <a href=\"/index.php/Pillar\" title=\"Pillar\">pillar</a>.</li></ul>', 1),
(3768, 982, 'See Also', 'See_Also', 'Mission structures , for more information on mission structures in general.', '<ul><li><a href=\"/index.php/Category:Mission_structures\" title=\"Category:Mission structures\">Mission structures</a>, for more information on mission structures in general.</li></ul>', 2),
(3901, 1012, 'Description', 'Description', 'You see a door', '<p><i>You see a door </i>\n</p>', 0),
(3902, 1012, 'Locking', 'Locking', 'It can be locked with a door lock . Any humanoid mob (for example trolls ) or player can pass through an unlocked door.', '<ul><li>It can be locked with a <a href=\"/index.php/Door_lock\" title=\"Door lock\">door lock</a>. Any humanoid mob (for example <a href=\"/index.php/Troll\" title=\"Troll\">trolls</a>) or player can pass through an unlocked door.</li></ul>', 1),
(3903, 1012, 'Skill Requirements', 'Skill_Requirements', 'At least 30 masonry skill is required to build stone walls. See multi-story housing for more information regarding skill requirements on additional floors.', '<ul><li>At least 30 <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill is required to build stone walls.</li>\n<li>See <a href=\"/index.php/Multi-story_housing#Skill_needed\" title=\"Multi-story housing\">multi-story housing</a> for more information regarding skill requirements on additional floors.</li></ul>', 2),
(3904, 1012, 'Creation', 'Creation', 'Have at least 1 Stone brick and 1 mortar in your inventory. Activate a trowel and right-click on a wall plan . Select Build and then Stone double door . Continuation requires at least 1 Stone brick and 1 mortar in your inventory.', '<ul><li>Have at least 1 <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> and 1 <a href=\"/index.php/Mortar\" title=\"Mortar\">mortar</a> in your inventory.</li>\n<li><b>Activate</b> a <a href=\"/index.php/Trowel\" title=\"Trowel\">trowel</a> and <b>right-click</b> on a <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">wall plan</a>.</li>\n<li>Select <b>Build</b> and then <b>Stone double door</b>.</li>\n<li>Continuation requires at least 1 <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> and 1 mortar in your inventory.</li></ul>', 3),
(3905, 1012, 'Modifying', 'Modifying', 'Pliers are used for modifying the wall into its trimless version, the Plain stone double door . Activate the tool and right-click the wall, then select Remove Decorations . You can turn walls to suit your needs by right-clicking them, and selecting Rotate wall .', '<ul><li><a href=\"/index.php/Pliers\" title=\"Pliers\">Pliers</a> are used for modifying the wall into its trimless version, the <a href=\"/index.php/Plain_stone_double_door\" title=\"Plain stone double door\">Plain stone double door</a>.  <b>Activate</b> the tool and <b>right-click</b> the wall, then select <b>Remove Decorations</b>.</li>\n<li>You can turn walls to suit your needs by <b>right-clicking</b> them, and selecting <b>Rotate wall</b>.</li></ul>', 4),
(3906, 1012, 'Improving', 'Improving', 'You must repair any damage on the walls with a Stone brick before improving it. Activate a Stone brick , right-click the wall and select Repair or Improve . The effective quality of the Stone brick is affected by its damage and your masonry skill, it must be higher than the wall\'s current quality.', '<ul><li>You must <a href=\"/index.php/Repairing\" title=\"Repairing\">repair</a> any <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> on the walls with a <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> before <a href=\"/index.php/Improve\" title=\"Improve\">improving</a> it.</li>\n<li>Activate a <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a>, right-click the wall and select <i>Repair</i> or <i>Improve</i>.</li>\n<li>The effective <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> is affected by its damage and your <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill, it must be higher than the wall\'s current quality.</li></ul>\n<p><br/>\n</p>', 5),
(3907, 1012, 'See also', 'See_also', 'Stone wall Stone door Stone portcullis Stone window Stone oriel Stone double door Stone T arch Stone arch right Stone arch left', '<ul><li><a href=\"/index.php/Stone_wall\" title=\"Stone wall\">Stone wall</a></li>\n<li><a href=\"/index.php/Stone_door\" title=\"Stone door\">Stone door</a></li>\n<li><a href=\"/index.php/Stone_portcullis_(wall)\" title=\"Stone portcullis (wall)\"> Stone portcullis</a></li>\n<li><a href=\"/index.php/Stone_window\" title=\"Stone window\">Stone window</a></li>\n<li><a href=\"/index.php/Stone_oriel\" title=\"Stone oriel\">Stone oriel</a></li>\n<li><a class=\"mw-selflink selflink\">Stone double door</a></li>\n<li><a href=\"/index.php/Stone_T_arch\" title=\"Stone T arch\">Stone T arch</a></li>\n<li><a href=\"/index.php/Stone_arch_right\" title=\"Stone arch right\">Stone arch right</a></li>\n<li><a href=\"/index.php/Stone_arch_left\" title=\"Stone arch left\">Stone arch left</a></li></ul>', 6),
(3908, 1013, 'Description', 'Description', 'You see a door.', '<p><i>You see a door. </i>\n</p>', 0),
(3909, 1013, 'Locking', 'Locking', 'It can be locked with a door lock . Any humanoid mob, for example trolls , or player can pass through an unlocked door.', '<ul><li>It can be locked with a <a href=\"/index.php/Door_lock\" title=\"Door lock\">door lock</a>. Any humanoid mob, for example <a href=\"/index.php/Troll\" title=\"Troll\">trolls</a>, or player can pass through an unlocked door.</li></ul>', 1),
(3910, 1013, 'Creation', 'Creation', 'Have at least 1 Plank and 1 Large nails in your inventory. Activate a mallet or hammer and right-click on a wall plan . Select Build and then Wooden double door . Continuation requires at least 1 plank in your inventory.', '<ul><li>Have at least 1 <a href=\"/index.php/Plank\" title=\"Plank\">Plank</a> and 1 <a href=\"/index.php/Large_nails\" title=\"Large nails\">Large nails</a> in your inventory.</li>\n<li><b>Activate</b> a <a href=\"/index.php/Mallet\" title=\"Mallet\">mallet</a> or <a href=\"/index.php/Hammer\" title=\"Hammer\">hammer</a> and <b>right-click</b> on a <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">wall plan</a>.</li>\n<li>Select <b>Build</b> and then <b>Wooden double door</b>.</li>\n<li>Continuation requires at least 1 <a href=\"/index.php/Plank\" title=\"Plank\">plank</a> in your inventory.</li></ul>', 2),
(3911, 1013, 'Modifying', 'Modifying', 'You can turn walls to suit your needs by right-clicking them, and selecting Rotate wall .', '<ul><li>You can turn walls to suit your needs by <b>right-clicking</b> them, and selecting <b>Rotate wall</b>.</li></ul>', 3),
(3912, 1013, 'Improving', 'Improving', 'You must repair any damage on the walls with a plank before improving it. Activate a plank , right-click the wall and select Repair or Improve . The effective quality of the plank is affected by its damage and your Carpentry skill, it must be higher than the wall\'s current quality.', '<ul><li>You must <a href=\"/index.php/Repairing\" title=\"Repairing\">repair</a> any <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> on the walls with a <a href=\"/index.php/Plank\" title=\"Plank\">plank</a> before <a href=\"/index.php/Improve\" title=\"Improve\">improving</a> it.</li>\n<li>Activate a <a href=\"/index.php/Plank\" title=\"Plank\">plank</a>, right-click the wall and select <i>Repair</i> or <i>Improve</i>.</li>\n<li>The effective <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the <a href=\"/index.php/Plank\" title=\"Plank\">plank</a> is affected by its damage and your <a href=\"/index.php/Carpentry\" title=\"Carpentry\">Carpentry</a> skill, it must be higher than the wall\'s current quality.</li></ul>\n<p><br/>\n</p>', 4),
(3913, 1013, 'See also', 'See_also', 'Wooden wall Wooden door Wooden double door Wooden window Wooden wide window Wooden portcullis Wooden canopy Wooden arch Wooden T arch Wooden arch right Wooden arch left', '<ul><li><a href=\"/index.php/Wooden_wall\" title=\"Wooden wall\">Wooden wall</a></li>\n<li><a href=\"/index.php/Wooden_door\" title=\"Wooden door\">Wooden door</a></li>\n<li><a class=\"mw-selflink selflink\">Wooden double door</a></li>\n<li><a href=\"/index.php/Wooden_window\" title=\"Wooden window\">Wooden window</a></li>\n<li><a href=\"/index.php/Wooden_wide_window\" title=\"Wooden wide window\">Wooden wide window</a></li>\n<li><a href=\"/index.php/Wooden_portcullis\" title=\"Wooden portcullis\">Wooden portcullis</a></li>\n<li><a href=\"/index.php/Wooden_canopy\" title=\"Wooden canopy\">Wooden canopy</a></li>\n<li><a href=\"/index.php/Wooden_arch\" title=\"Wooden arch\">Wooden arch</a></li>\n<li><a href=\"/index.php/Wooden_T_arch\" title=\"Wooden T arch\">Wooden T arch</a></li>\n<li><a href=\"/index.php/Wooden_arch_right\" title=\"Wooden arch right\">Wooden arch right</a></li>\n<li><a href=\"/index.php/Wooden_arch_left\" title=\"Wooden arch left\">Wooden arch left</a></li></ul>', 5),
(3953, 1026, 'Description', 'Description', 'You see a strong stone wall.', '<p><i>You see a strong stone wall. </i>\n</p>', 0),
(3954, 1026, 'Skill required', 'Skill_required', 'To calculate the maximum slope you can build on, based on your carpentry or masonry skill, use the following formula submitted by Ketza : Max slope = (3 * √ skill) + 10 Skill Max Slope 6 17 8 18 9 19 12 20 14 21 16 22 19 23 22 24 25 25 29 26 33 27 36 28 41 29 45 30 49 31 54 32 59 33 64 34 70 35 75 36 81 37 88 38 94 39 Note: Maximum slope is rounded down', '<p>To calculate the <a href=\"/index.php/Maximum_slope\" title=\"Maximum slope\">maximum slope</a> you can build on, based on your <a href=\"/index.php/Carpentry\" title=\"Carpentry\">carpentry</a> or <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill, use the following formula submitted by <a href=\"/index.php/Player:Ketza\" title=\"Player:Ketza\">Ketza</a>:\n</p>\n<p><i>Max slope = (3 *</i> √<i>skill) + 10</i>\n</p>\n<table class=\"wikitable\" style=\"text-align: center;\">\n<tbody><tr>\n<th width=\"100\">Skill\n</th>\n<th width=\"100\">Max Slope\n</th></tr>\n<tr>\n<td>6</td>\n<td>17\n</td></tr>\n<tr>\n<td>8</td>\n<td>18\n</td></tr>\n<tr>\n<td>9</td>\n<td>19\n</td></tr>\n<tr>\n<td>12</td>\n<td>20\n</td></tr>\n<tr>\n<td>14</td>\n<td>21\n</td></tr>\n<tr>\n<td>16</td>\n<td>22\n</td></tr>\n<tr>\n<td>19</td>\n<td>23\n</td></tr>\n<tr>\n<td>22</td>\n<td>24\n</td></tr>\n<tr>\n<td>25</td>\n<td>25\n</td></tr>\n<tr>\n<td>29</td>\n<td>26\n</td></tr>\n<tr>\n<td>33</td>\n<td>27\n</td></tr>\n<tr>\n<td>36</td>\n<td>28\n</td></tr>\n<tr>\n<td>41</td>\n<td>29\n</td></tr>\n<tr>\n<td>45</td>\n<td>30\n</td></tr>\n<tr>\n<td>49</td>\n<td>31\n</td></tr>\n<tr>\n<td>54</td>\n<td>32\n</td></tr>\n<tr>\n<td>59</td>\n<td>33\n</td></tr>\n<tr>\n<td>64</td>\n<td>34\n</td></tr>\n<tr>\n<td>70</td>\n<td>35\n</td></tr>\n<tr>\n<td>75</td>\n<td>36\n</td></tr>\n<tr>\n<td>81</td>\n<td>37\n</td></tr>\n<tr>\n<td>88</td>\n<td>38\n</td></tr>\n<tr>\n<td>94</td>\n<td>39\n</td></tr></tbody></table>\n<p><b>Note:</b> Maximum slope is rounded <i>down</i>\n</p>\n<p><br/>\n</p>', 1),
(3955, 1026, 'Notes', 'Notes', 'Repair Low stone wall with stone shards. Each stone shards will repair up to 10 damage depending on quality and repairing skill. At 60 damage, cracks will form on the wall. Can not be build inside buildings. The maximum slope skill requirements are waived when this type of fence is constructed around cave entrances.', '<ul><li>Repair Low stone wall with stone shards. Each stone shards will repair up to 10 damage depending on quality and repairing skill.</li>\n<li>At 60 damage, cracks will form on the wall.</li>\n<li>Can not be build inside buildings.</li></ul>\n<p><br/>\n</p>\n<p><br/>\n</p>\n<ul><li>The maximum slope skill requirements are waived when this type of fence is constructed around cave entrances.</li></ul>', 2),
(3956, 1026, 'See also', 'See_also', 'Fences Fence gates Empirical Evaluation of Fences', '<ul><li><a href=\"/index.php/Category:Fences\" title=\"Category:Fences\">Fences</a></li>\n<li><a href=\"/index.php/Category:Gates\" title=\"Category:Gates\">Fence gates</a></li></ul>\n<ul><li><a href=\"/index.php/Empirical_Evaluation_of_Fences\" title=\"Empirical Evaluation of Fences\">Empirical Evaluation of Fences</a></li></ul>', 3),
(3960, 1008, 'Description', 'Description', 'The hell hound is said to be (one of the) spies and assassins for the demons of Sol .', '<p><i>The hell hound is said to be (one of the) spies and assassins for the demons of <a href=\"/index.php/Sol\" title=\"Sol\">Sol</a>.</i>\n</p>', 0),
(3961, 1008, 'Notes', 'Notes', 'The hell hound has an extremely large aggro range, estimated at 10-20 tiles. One should have at least 40 fight skill and 50QL+ armour/weapons to take one on with the possibility of only medium wounds. Hell hounds will walk in shallow water, but do not swim. Hell hounds do slashing damage from their claws and burn damage.', '<ul><li>The hell hound has an extremely large aggro range, estimated at 10-20 tiles. One should have at least 40 <a href=\"/index.php/Fighting\" title=\"Fighting\">fight</a> skill and 50QL+ armour/weapons to take one on with the possibility of only medium wounds.</li>\n<li>Hell hounds will walk in shallow water, but do not swim.</li>\n<li>Hell hounds do slashing damage from their claws and burn damage.</li></ul>', 1),
(3963, 1031, 'Description', 'Description', 'The pets of the demons of Sol are very playful.', '<p><i>The pets of the demons of Sol are very playful.</i>\n</p>', 0),
(3964, 1031, 'Notes', 'Notes', 'They are stronger than a troll and much stronger than a normal scorpion. At least 60FS-70 fight skill and good gear is recommended to kill one.', '<ul><li>They are stronger than a troll and much stronger than a normal scorpion. At least 60FS-70 <a href=\"/index.php/Fighting\" title=\"Fighting\">fight</a> skill and good gear is recommended to kill one.</li></ul>', 1),
(3967, 1032, 'Description', 'Description', 'The bison are impressive creatures when moving in hordes.', '<p><i>The bison are impressive creatures when moving in hordes.</i>\n</p>', 0),
(3968, 1032, 'Notes', 'Notes', 'Bison are non-aggressive animals that can be tamed. Bison are easy to tame even with a fairly low taming skill using mixed grass or cereals . They graze similar to cows , meaning they will eat grass tiles . Bison, excluding those on deed or hitched, are hunted by carnivorous animals or mobs. Bison can be used to pull large carts and wagons . Bisons have a speed bonus when dragging wagons making them faster than horses when hitched to a wagon. They take a lot of damage and many arrows glance off their thick skin, making them useful for dragging carts in pvp events. Female bison may be milked .', '<ul><li>Bison are non-aggressive <a href=\"/index.php/Creatures\" title=\"Creatures\">animals</a> that can be tamed. Bison are easy to tame even with a fairly low <a class=\"mw-redirect\" href=\"/index.php/Animal_Taming\" title=\"Animal Taming\">taming</a> skill using <a href=\"/index.php/Mixed_grass\" title=\"Mixed grass\">mixed grass</a> or <a href=\"/index.php/Cereals\" title=\"Cereals\">cereals</a>. They graze similar to <a class=\"mw-redirect\" href=\"/index.php/Cows\" title=\"Cows\">cows</a>, meaning they will eat <a class=\"mw-redirect\" href=\"/index.php/Grass_tiles\" title=\"Grass tiles\">grass tiles</a>.</li></ul>\n<ul><li>Bison, excluding those on deed or hitched, are hunted by carnivorous animals or mobs.</li></ul>\n<ul><li>Bison can be used to pull <a href=\"/index.php/Large_cart\" title=\"Large cart\">large carts</a> and <a href=\"/index.php/Wagon\" title=\"Wagon\">wagons</a>. Bisons have a speed bonus when dragging wagons making them faster than horses when hitched to a wagon.</li></ul>\n<ul><li>They take a lot of damage and many <a href=\"/index.php/Arrow\" title=\"Arrow\">arrows</a> glance off their thick skin, making them useful for dragging carts in pvp events.</li></ul>\n<ul><li>Female bison may be <a href=\"/index.php/Milk\" title=\"Milk\">milked</a>.</li></ul>', 1),
(3980, 1039, 'Description', 'Description', 'A brown algae long and slimy with air bladders clearly visible. Kelp is a seaside product gathered from gardening kelp tiles or from foraging Seaweed nodes.', '<p><i>A brown algae long and slimy with air bladders clearly visible.</i>\n</p>\n<p><b>Kelp</b> is a seaside product gathered from gardening <a href=\"/index.php/Kelp_tile\" title=\"Kelp tile\">kelp tiles</a> or from <a href=\"/index.php/Foraging\" title=\"Foraging\">foraging</a> <a href=\"/index.php/Seaweed\" title=\"Seaweed\">Seaweed</a> nodes.\n</p>', 0),
(3981, 1039, 'Usage', 'Usage', 'Kelp can be used to create nori, which is used in cooking . Nori can be stored in a food storage bin.', '<p>Kelp can be used to create nori, which is used in <a href=\"/index.php/Cooking\" title=\"Cooking\">cooking</a>. Nori can be stored in a food storage bin.\n</p>', 1),
(3982, 1039, 'Method', 'Method', 'Kelp tiles Medium, long and wild natural kelp tiles can be harvested to produce kelp. Medium kelp produces 1 plant, tall produces 2 plants and wild produces 3 plants. The quality of the harvest is random. The length of the kelp can be examined : You see a patch of kelp. The kelp is short and seem to like it here. You see a patch of kelp. The kelp is medium and seem to like it here. You see a patch of kelp. The kelp is tall and seem to like it here. You see a patch of kelp. The kelp is wild and seem to like it here. Kelp tiles can be harvested with a Sickle , Shovel , Scythe , Butchering knife or Carving knife . After harvest, it typically takes approximately 4-6 real life days in order for the kelp to regrow to a full, \"growing wild\" state.', '<h3><span class=\"mw-headline\" id=\"Kelp_tiles\">Kelp tiles</span></h3>\n<p>Medium, long and wild natural <a href=\"/index.php/Kelp_tile\" title=\"Kelp tile\">kelp tiles</a> can be harvested to produce kelp. Medium kelp produces 1 plant, tall produces 2 plants and wild produces 3 plants. The quality of the harvest is random.\n</p>\n<p>The length of the kelp can be <a href=\"/index.php/Examine\" title=\"Examine\">examined</a>:\n</p>\n<dl><dd><span style=\"color: #fff; font-family: Sans-Serif; font-size: 0.85em; border: 1px rgb(0, 0, 0) solid; background: rgb(75, 62, 48); line-height: 1.3em; -webkit-border-radius: 5px; -moz-border-radius: 5px; border-radius: 5px; -moz-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); -webkit-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); padding: 2px 10px 2px 10px; display: inline-block;\"> You see a patch of kelp. The kelp is short and seem to like it here. </span></dd>\n<dd><span style=\"color: #fff; font-family: Sans-Serif; font-size: 0.85em; border: 1px rgb(0, 0, 0) solid; background: rgb(75, 62, 48); line-height: 1.3em; -webkit-border-radius: 5px; -moz-border-radius: 5px; border-radius: 5px; -moz-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); -webkit-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); padding: 2px 10px 2px 10px; display: inline-block;\"> You see a patch of kelp. The kelp is medium and seem to like it here. </span></dd>\n<dd><span style=\"color: #fff; font-family: Sans-Serif; font-size: 0.85em; border: 1px rgb(0, 0, 0) solid; background: rgb(75, 62, 48); line-height: 1.3em; -webkit-border-radius: 5px; -moz-border-radius: 5px; border-radius: 5px; -moz-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); -webkit-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); padding: 2px 10px 2px 10px; display: inline-block;\"> You see a patch of kelp. The kelp is tall and seem to like it here. </span></dd>\n<dd><span style=\"color: #fff; font-family: Sans-Serif; font-size: 0.85em; border: 1px rgb(0, 0, 0) solid; background: rgb(75, 62, 48); line-height: 1.3em; -webkit-border-radius: 5px; -moz-border-radius: 5px; border-radius: 5px; -moz-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); -webkit-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); padding: 2px 10px 2px 10px; display: inline-block;\"> You see a patch of kelp. The kelp is wild and seem to like it here. </span></dd></dl>\n<p>Kelp tiles can be harvested with a <a href=\"/index.php/Sickle\" title=\"Sickle\">Sickle</a>, <a href=\"/index.php/Shovel\" title=\"Shovel\">Shovel</a>, <a href=\"/index.php/Scythe\" title=\"Scythe\">Scythe</a>, <a href=\"/index.php/Butchering_knife\" title=\"Butchering knife\">Butchering knife</a> or <a href=\"/index.php/Carving_knife\" title=\"Carving knife\">Carving knife</a>. After harvest, it typically takes approximately 4-6 real life days in order for the kelp to regrow to a full, \"growing wild\" state.\n</p>', 2),
(3983, 1039, 'Notes', 'Notes', 'Kelp can only be found in the wild and cannot be planted like reed . Kelp tiles can be removed by digging one corner of the tile. It turns to dirt. Kelp tiles will also be removed by leveling a tile that shares a corner with the kelp tile. Only the NW corner of the kelp tile must be raised in order for it to be harvested.  Raising it to -8 dirts will put it into reach. To gather kelp, any sharp object will work. Tools aside from the sickle or scythe do, however, limit the kelp quality to a maximum of 20.', '<ul><li>Kelp can only be found in the wild and cannot be planted like <a href=\"/index.php/Reed\" title=\"Reed\">reed</a>.</li>\n<li>Kelp tiles can be removed by digging one corner of the tile. It turns to dirt.</li>\n<li>Kelp tiles will also be removed by leveling a tile that shares a corner with the kelp tile.</li>\n<li>Only the NW corner of the kelp tile must be raised in order for it to be harvested.  Raising it to -8 dirts will put it into reach.</li>\n<li>To gather kelp, any sharp object will work. Tools aside from the sickle or scythe do, however, limit the kelp quality to a maximum of 20.</li></ul>', 3),
(3990, 1042, 'Description', 'Description', 'A few handfuls of reed seed. It can be used to sow with, but reed must be grown under very special conditions.', '<p><i>A few handfuls of reed seed. It can be used to sow with, but reed must be grown under very special conditions.</i>\n</p>', 0),
(3991, 1042, 'Usage', 'Usage', 'Reed seeds can be sown on dirt tiles that are at most 8 dirts steep and have at least one corner between 1 and 4 dirts below water. Error messages: The ground is not flat enough for crops to grow. You need to flatten it first - The tile is steeper than 8 dirts This type of crop can only grow in water of suitable depth - No corner is between 1 and 4 dirts below water. Another way to measure the depth is to dig the maximum depth with a shovel, and then drop 3 dirt in each corner. Pile of reed seeds', '<p>Reed seeds can be sown on dirt tiles that are at most 8 dirts steep and have at least one corner between 1 and 4 dirts below water.\n</p>\n<p>Error messages:\n</p>\n<ul><li>The ground is not flat enough for crops to grow. You need to flatten it first - The tile is steeper than 8 dirts</li>\n<li>This type of crop can only grow in water of suitable depth - No corner is between 1 and 4 dirts below water. Another way to measure the depth is to dig the maximum depth with a shovel, and then drop 3 dirt in each corner.</li></ul>\n<div class=\"thumb tright\"><div class=\"thumbinner\" style=\"width:235px;\"><a class=\"image\" href=\"/index.php/File:Pile_of_reed_seeds.png\"><img alt=\"\" class=\"thumbimage\" data-file-height=\"218\" data-file-width=\"233\" decoding=\"async\" height=\"218\" src=\"/images/0/05/Pile_of_reed_seeds.png\" width=\"233\"/></a> <div class=\"thumbcaption\"><div class=\"magnify\"><a class=\"internal\" href=\"/index.php/File:Pile_of_reed_seeds.png\" title=\"Enlarge\"></a></div>Pile of reed seeds</div></div></div>', 1),
(3992, 1043, 'Description', 'Description', 'Reed tiles occur naturally underwater and spread like grass tiles . Reed plants can be gathered using a sickle or scythe . Other sharp tools work too but limit the reed to 20 QL. If you dig on a reed tile, you create a dirt tile . All the reed tiles surrounding the digged corner will also turn into dirt tiles. You can pack reed tiles with a shovel to convert them to packed dirt, e.g. for faster movement or for preparing them to be cultivated into dirt or paved.', '<p>Reed tiles occur naturally underwater and spread like <a href=\"/index.php/Grass_tile\" title=\"Grass tile\">grass tiles</a>.\n</p>\n<p><a href=\"/index.php/Reed_plants\" title=\"Reed plants\">Reed plants</a> can be gathered using a <a href=\"/index.php/Sickle\" title=\"Sickle\">sickle</a> or <a href=\"/index.php/Scythe\" title=\"Scythe\">scythe</a>. Other sharp tools work too but limit the reed to 20 QL.\n</p>\n<p>If you dig on a reed tile, you create a <a href=\"/index.php/Dirt_tile\" title=\"Dirt tile\">dirt tile</a>. All the reed tiles surrounding the digged corner will also turn into dirt tiles.\n</p>\n<p>You can pack reed tiles with a shovel to convert them to packed dirt, e.g. for faster movement or for preparing them to be cultivated into dirt or paved.\n</p>', 0),
(3993, 1043, 'Notes', 'Notes', 'Planting reed seeds underwater creates reed tiles. Sowing reed seeds underwater creates reed fields instead of reed tiles. Gathering reed gives gardening skill. Reed fields do grow back over time. Reed seeds can now be planted in shallow water to create natural reed tiles. They require a depth of 29 dirts or less, on tiles with a slope of 20 or less. The following types of Resource nodes can spawn on Reed tiles: Seaweed , Wild grasses , Flotsam , and Mineral debris .', '<ul><li>Planting <a href=\"/index.php/Reed_seeds\" title=\"Reed seeds\">reed seeds</a> underwater creates reed tiles.</li>\n<li>Sowing <a href=\"/index.php/Reed_seeds\" title=\"Reed seeds\">reed seeds</a> underwater creates reed <a href=\"/index.php/Field\" title=\"Field\">fields</a> instead of reed tiles.</li>\n<li>Gathering reed gives <a href=\"/index.php/Gardening\" title=\"Gardening\">gardening</a> skill.</li>\n<li>Reed <a href=\"/index.php/Field\" title=\"Field\">fields</a> do grow back over time.</li>\n<li>Reed seeds can now be planted in shallow water to create natural reed tiles. They require a depth of 29 dirts or less, on tiles with a slope of 20 or less.</li>\n<li>The following types of <a href=\"/index.php/Resource_nodes\" title=\"Resource nodes\">Resource nodes</a> can spawn on Reed tiles: <a href=\"/index.php/Seaweed\" title=\"Seaweed\">Seaweed</a>, <a href=\"/index.php/Wild_grasses\" title=\"Wild grasses\">Wild grasses</a>, <a href=\"/index.php/Flotsam\" title=\"Flotsam\">Flotsam</a>, and <a href=\"/index.php/Mineral_debris\" title=\"Mineral debris\">Mineral debris</a>.</li></ul>', 1),
(3994, 1044, 'Description', 'Description', 'A rough pen made from a section of a reed straw.', '<p><i>A rough pen made from a section of a reed straw.</i>\n</p>', 0),
(3995, 1044, 'Usage', 'Usage', 'To use the reed pen as a writing instrument, it must be filled with black ink or any colour of dye . It can hold 0.008 kg total.  All 0.008 kg is used up when the pen is used for writing, even if the scribing action is aborted prematurely. The quality of the pen affects the number of letters that can be written on a papyrus or paper sheet . For details, see inscribing . The reed pen is also used for writing recipes and almanac reports . In these cases, the pen and dye/ink quality do not matter, as the whole document will be written regardless of quality.', '<ul><li>To use the reed pen as a writing instrument, it must be filled with <a href=\"/index.php/Black_ink\" title=\"Black ink\">black ink</a> or any colour of <a href=\"/index.php/Dye\" title=\"Dye\">dye</a>. It can hold 0.008 kg total.  All 0.008 kg is used up when the pen is used for writing, even if the <a href=\"/index.php/Papyrus_sheet#Inscribing\" title=\"Papyrus sheet\">scribing</a> action is aborted prematurely.</li></ul>\n<ul><li>The quality of the pen affects the number of letters that can be written on a <a class=\"mw-redirect\" href=\"/index.php/Papyrus\" title=\"Papyrus\">papyrus</a> or <a href=\"/index.php/Paper_sheet\" title=\"Paper sheet\">paper sheet</a>. For details, see <a href=\"/index.php/Papyrus_sheet#Inscribing\" title=\"Papyrus sheet\">inscribing</a>.</li></ul>\n<ul><li>The reed pen is also used for writing <a class=\"mw-redirect\" href=\"/index.php/Recipes\" title=\"Recipes\">recipes</a> and <a href=\"/index.php/Almanac\" title=\"Almanac\">almanac reports</a>. In these cases, the pen and dye/ink quality do not matter, as the whole document will be written regardless of quality.</li></ul>', 1),
(3996, 1044, 'Additional Notes', 'Additional_Notes', 'The reed pen can be used to hold smaller items which may have zero weight or volume. Examples of items that fit inside include the settlement deed and coins . The reed pen cannot be repaired or improved.', '<ul><li>The reed pen can be used to hold smaller items which may have zero weight or volume. Examples of items that fit inside include the <a href=\"/index.php/Settlement\" title=\"Settlement\">settlement deed</a> and <a href=\"/index.php/Bank_of_Wurm\" title=\"Bank of Wurm\">coins</a>.</li></ul>\n<ul><li>The reed pen cannot be repaired or improved.</li></ul>', 2),
(3997, 1045, 'Description', 'Description', 'Black ink, with a faint smell of fish. Black ink is used for inscribing on a papyrus sheet or paper sheet using a reed pen .', '<p><i>Black ink, with a faint smell of fish.</i>\n</p>\n<p>Black ink is used for inscribing on a <a href=\"/index.php/Papyrus_sheet\" title=\"Papyrus sheet\">papyrus sheet</a> or <a href=\"/index.php/Paper_sheet\" title=\"Paper sheet\">paper sheet</a> using a <a href=\"/index.php/Reed_pen\" title=\"Reed pen\">reed pen</a>.\n</p>', 0),
(3998, 1045, 'Notes', 'Notes', 'A failed creation attempt will result in a 0.01 kg weight loss from the octopus ink sac. A successful attempt will consume 0.20 kg: 0.10 kg black ink, 0.05 kg pig food, and 0.05 with no output.', '<ul><li>A failed creation attempt will result in a 0.01 kg weight loss from the octopus ink sac.</li>\n<li>A successful attempt will consume 0.20 kg: 0.10 kg black ink, 0.05 kg pig food, and 0.05 with no output.</li></ul>', 1),
(4005, 1048, 'Description', 'Description', 'Papyrusmaking is the skill used to make papyrus sheets , paper sheets and wax sealing kits . Books can be made using either of these sheets along with a string of cloth .', '<p><b>Papyrusmaking</b> is the <a class=\"mw-redirect\" href=\"/index.php/Skill\" title=\"Skill\">skill</a> used to make <a href=\"/index.php/Papyrus_sheet\" title=\"Papyrus sheet\">papyrus sheets</a>, <a href=\"/index.php/Paper_sheet\" title=\"Paper sheet\">paper sheets</a> and <a href=\"/index.php/Wax_sealing_kit\" title=\"Wax sealing kit\">wax sealing kits</a>.\n<a href=\"/index.php/Book\" title=\"Book\">Books</a> can be made using either of these sheets along with a <a href=\"/index.php/String_of_cloth\" title=\"String of cloth\">string of cloth</a>.\n</p>\n<p><br/>\n</p>', 0),
(4006, 1048, 'Skills & Characteristics', 'Skills_.26_Characteristics', 'Nature > Papyrusmaking Body > Body strength Soul > Soul depth', '<ul><li><a href=\"/index.php/Nature\" title=\"Nature\">Nature</a> &gt; Papyrusmaking</li>\n<li><a href=\"/index.php/Body\" title=\"Body\">Body</a> &gt; <a href=\"/index.php/Body_strength\" title=\"Body strength\">Body strength</a></li>\n<li><a href=\"/index.php/Soul\" title=\"Soul\">Soul</a> &gt; <a href=\"/index.php/Soul_depth\" title=\"Soul depth\">Soul depth</a></li></ul>', 1),
(4007, 1048, 'Titles', 'Titles', 'Papermaker at 50 skill Pulp-beater at 70 skill Book Maker at 90 skill Bookwurm at 100 skill', '<ul><li>Papermaker at 50 skill</li>\n<li>Pulp-beater at 70 skill</li>\n<li>Book Maker at 90 skill</li>\n<li>Bookwurm at 100 skill</li></ul>', 2),
(4060, 1055, 'Description', 'Description', 'Kelp tiles occur naturally underwater and spread like grass tiles . Kelp can be gathered from them using a sickle . If you dig on a kelp tile, you create a dirt tile . All the kelp tiles surrounding the dug corner will also turn into dirt tiles.\nDropping dirt/sand, however, will raise the kelp without destroying it, allowing deep tiles to be harvested. The following types of Resource nodes can spawn on Kelp tiles: Seaweed , Flotsam and Mineral debris .', '<p>Kelp tiles occur naturally underwater and spread like <a href=\"/index.php/Grass_tile\" title=\"Grass tile\">grass tiles</a>.\n</p>\n<p><a href=\"/index.php/Kelp\" title=\"Kelp\">Kelp</a> can be gathered from them using a <a href=\"/index.php/Sickle\" title=\"Sickle\">sickle</a>.\n</p>\n<p>If you dig on a kelp tile, you create a <a href=\"/index.php/Dirt_tile\" title=\"Dirt tile\">dirt tile</a>. All the kelp tiles surrounding the dug corner will also turn into dirt tiles.\nDropping dirt/sand, however, will raise the kelp without destroying it, allowing deep tiles to be harvested.\n</p>\n<p>The following types of <a href=\"/index.php/Resource_nodes\" title=\"Resource nodes\">Resource nodes</a> can spawn on Kelp tiles: <a href=\"/index.php/Seaweed\" title=\"Seaweed\">Seaweed</a>, <a href=\"/index.php/Flotsam\" title=\"Flotsam\">Flotsam</a> and <a href=\"/index.php/Mineral_debris\" title=\"Mineral debris\">Mineral debris</a>.\n</p>\n<p><br/>\n</p>', 0),
(4061, 1055, 'Examine', 'Examine', 'You see a patch of kelp. The kelp is short and seem to like it here. You see a patch of kelp. The kelp is medium and seem to like it here. You see a patch of kelp. The kelp is tall and seem to like it here. You see a patch of kelp. The kelp is wild and seem to like it here.', '<p>You see a patch of kelp. The kelp is short and seem to like it here.\n</p>\n<p>You see a patch of kelp. The kelp is medium and seem to like it here.\n</p>\n<p>You see a patch of kelp. The kelp is tall and seem to like it here.\n</p>\n<p>You see a patch of kelp. The kelp is wild and seem to like it here.\n</p>', 1),
(4076, 1000, 'Description', 'Description', 'Spawned by the Gods on Valrei . Abilities Large (15+ tiles) aggro range. Walks through walls and buildings. Biting, hitting, tailwhip and wingbuff attacks. Can pick up and throw opponents. (This will dismount you from your horse) Once in a while \"makes a circular powerful sweep!\" Holds it\'s own very nicely versus 3-4 Tower Guards Quite fast, can travel at over 15 km/h Splits into multiple \"fake\" spirits halfway through-out battle', '<p>Spawned by the Gods on <a href=\"/index.php/Valrei_(moon)\" title=\"Valrei (moon)\">Valrei</a>.\n</p>\n<h3><span class=\"mw-headline\" id=\"Abilities\">Abilities</span></h3>\n<ul><li>Large (15+ tiles) aggro range.</li>\n<li>Walks through walls and buildings.</li>\n<li>Biting, hitting, tailwhip and wingbuff attacks.</li>\n<li>Can pick up and throw opponents. (This will dismount you from your horse)</li>\n<li>Once in a while \"makes a circular powerful sweep!\"</li>\n<li>Holds it\'s own very nicely versus 3-4 Tower Guards</li>\n<li>Quite fast, can travel at over 15 km/h</li>\n<li>Splits into multiple \"fake\" spirits halfway through-out battle</li></ul>', 0),
(4077, 1000, 'Drops', 'Drops', 'Eaglespirits do not leave a corpse when they die. Instead they leave a pile of items which includes a Valrei item such as: Black Orb Charming Token Deadly Eye Deadly Feather Deadly Token Deadly Opal Deadly Shard Frozen Jewel Marble Diamond Marble Orb Rotten Eye Shadow Totem These items all share the same description: A weird item belonging on Valrei. , but appear to be a different pool of items from those of other Valrei creatures. See also Drakespirit , Spawn of Uttacha , Son of Nogump .', '<p>Eaglespirits do not leave a corpse when they die. Instead they leave a pile of items which includes a <a href=\"/index.php/Valrei_item\" title=\"Valrei item\">Valrei item</a> such as:\n</p>\n<ul><li>Black Orb</li>\n<li>Charming Token</li>\n<li>Deadly Eye</li>\n<li>Deadly Feather</li>\n<li>Deadly Token</li>\n<li>Deadly Opal</li>\n<li>Deadly Shard</li>\n<li>Frozen Jewel</li>\n<li>Marble Diamond</li>\n<li>Marble Orb</li>\n<li>Rotten Eye</li>\n<li>Shadow Totem</li></ul>\n<p>These items all share the same description: <i>A weird item belonging on Valrei.</i>, but appear to be a different pool of items from those of other Valrei creatures.\n</p>\n<p>See also <a href=\"/index.php/Drakespirit\" title=\"Drakespirit\">Drakespirit</a>, <a href=\"/index.php/Spawn_of_Uttacha\" title=\"Spawn of Uttacha\">Spawn of Uttacha</a>, <a href=\"/index.php/Son_of_Nogump\" title=\"Son of Nogump\">Son of Nogump</a>.\n</p>', 1),
(4078, 1014, 'Description', 'Description', 'Nogump the dirty has given birth to this foul two-headed giant wielding a huge two handed sword. Spawned by the Gods on Valrei . Abilities Can bash down fences. Can pick up and throw opponents. Once in a while \"makes a circular powerful sweep!\" Can use a powerful stun attack, which stuns for several seconds and inflicts severe damage (instant medium through 70ql plate). Images A Son of Nogump on the beach', '<p><i>Nogump the dirty has given birth to this foul two-headed giant wielding a huge two handed sword.</i>\n</p>\n<p>Spawned by the Gods on <a href=\"/index.php/Valrei_(moon)\" title=\"Valrei (moon)\">Valrei</a>.\n</p>\n<h3><span class=\"mw-headline\" id=\"Abilities\">Abilities</span></h3>\n<ul><li>Can bash down fences.</li>\n<li>Can pick up and throw opponents.</li>\n<li>Once in a while \"makes a circular powerful sweep!\"</li>\n<li>Can use a powerful stun attack, which stuns for several seconds and inflicts severe damage (instant medium through 70ql plate).</li></ul>\n<h3><span class=\"mw-headline\" id=\"Images\">Images</span></h3>\n<div class=\"thumb tleft\"><div class=\"thumbinner\" style=\"width:602px;\"><a class=\"image\" href=\"/index.php/File:Son_of_nogump.jpg\"><img alt=\"\" class=\"thumbimage\" data-file-height=\"670\" data-file-width=\"1130\" decoding=\"async\" height=\"356\" src=\"/images/thumb/6/67/Son_of_nogump.jpg/600px-Son_of_nogump.jpg\" srcset=\"/images/thumb/6/67/Son_of_nogump.jpg/900px-Son_of_nogump.jpg 1.5x, /images/6/67/Son_of_nogump.jpg 2x\" width=\"600\"/></a> <div class=\"thumbcaption\"><div class=\"magnify\"><a class=\"internal\" href=\"/index.php/File:Son_of_nogump.jpg\" title=\"Enlarge\"></a></div>A Son of Nogump on the beach</div></div></div>', 0),
(4079, 1047, 'Description', 'Description', 'Blank: A flat piece of papyrus made from pressed reed fibre. It is possible to inscribe on the papyrus sheet if you know how. Inscribed: A flat piece of papyrus made from pressed reed fibre. It appears the papyrus sheet has something written on it.', '<p>Blank: <i>A flat piece of papyrus made from pressed reed fibre. It is possible to inscribe on the papyrus sheet if you know how.</i>\n</p>\n<p>Inscribed: <i>A flat piece of papyrus made from pressed reed fibre. It appears the papyrus sheet has something written on it.</i>\n</p>', 0),
(4080, 1047, 'Inscribing', 'Inscribing', 'It is possible to write notes on paper and papyrus sheets. Fill a reed pen with black ink or dye Activate the reed pen Right-click the sheet and click Inscribe Type the desired text in the window and click Send . The amount of letters you can inscribe is affected by: Choosing dye, granting a base of 10 letters Choosing ink, granting a base of 100 letters QL of sheet QL of reed pen QL of dye or ink The number of letters you can inscribe is therefore equal to (10 for dye or 100 for ink) + (QL of dye/ink) + (QL of papyrus sheet) + (QL of reed pen) You are limited by the characters that you can use when inscribing. If you try to use disallowed characters (including question marks), you will receive the following message: The inscription contains some characters that are too complex for you to inscribe Instead of a reed pen, you may also activate your hand or a corpse instead, and use it to inscribe an imprint on the sheet instead of text. Trying to drop inscribed sheets into a bulk storage bin or crate returns the message: The inscription on the (papyrus/paper) sheet would be destroyed . After a sheet is inscribed it gets the option to Read inscription when right-clicked, which opens a window with the inscribed text. If dye was used to inscribe the sheet, the text will appear in the same color as the dye. Recipes can also be inscribed. To do this, right-click a recipe in your cookbook, click Options , and click Mark recipe to be written . Next, activate a reed pen containing ink or dye, right-click the sheet and click Write recipe .', '<p>It is possible to write notes on paper and papyrus sheets.\n</p>\n<ul><li>Fill a <a href=\"/index.php/Reed_pen\" title=\"Reed pen\">reed pen</a> with <a href=\"/index.php/Black_ink\" title=\"Black ink\">black ink</a> or <a href=\"/index.php/Dye\" title=\"Dye\">dye</a></li>\n<li><b>Activate</b> the reed pen</li>\n<li><b>Right-click</b> the sheet and click <b>Inscribe</b></li>\n<li>Type the desired text in the window and click <b>Send</b>.</li></ul>\n<p>The amount of letters you can inscribe is affected by:\n</p>\n<ul><li>Choosing dye, granting a base of 10 letters</li>\n<li>Choosing ink, granting a base of 100 letters</li>\n<li>QL of sheet</li>\n<li>QL of reed pen</li>\n<li>QL of dye or ink</li></ul>\n<p>The number of letters you can inscribe is therefore equal to <i>(10 for dye or 100 for ink) + (QL of dye/ink) + (QL of papyrus sheet) + (QL of reed pen)</i>\n</p>\n<p>You are limited by the characters that you can use when inscribing. If you try to use disallowed characters (including question marks), you will receive the following message: <i>The inscription contains some characters that are too complex for you to inscribe</i>\n</p>\n<p>Instead of a reed pen, you may also activate your <a href=\"/index.php/Hand\" title=\"Hand\">hand</a> or a <a href=\"/index.php/Corpse\" title=\"Corpse\">corpse</a> instead, and use it to inscribe an imprint on the sheet instead of text.\n</p>\n<p>Trying to drop inscribed sheets into a <a href=\"/index.php/Bulk_storage_bin\" title=\"Bulk storage bin\">bulk storage bin</a> or <a href=\"/index.php/Crate\" title=\"Crate\">crate</a> returns the message: <i>The inscription on the (papyrus/paper) sheet would be destroyed</i>.\n</p>\n<p>After a sheet is inscribed it gets the option to <b>Read inscription</b> when right-clicked, which opens a window with the inscribed text. If dye was used to inscribe the sheet, the text will appear in the same color as the dye.\n</p>\n<p>Recipes can also be inscribed. To do this, <b>right-click</b> a recipe in your cookbook, click <b>Options</b>, and click <b>Mark recipe to be written</b>. Next, activate a reed pen containing ink or dye, <b>right-click</b> the sheet and click <b>Write recipe</b>.\n</p>', 1),
(4081, 1047, 'Notes', 'Notes', 'Failure to create a papyrus sheet will use 0.001kg of the reed fibre.', '<ul><li>Failure to create a papyrus sheet will use 0.001kg of the reed fibre.</li></ul>', 2),
(4082, 1047, 'See Also', 'See_Also', 'Book Paper sheet Press', '<ul><li><a href=\"/index.php/Book\" title=\"Book\">Book</a></li>\n<li><a href=\"/index.php/Paper_sheet\" title=\"Paper sheet\">Paper sheet</a></li>\n<li><a href=\"/index.php/Press\" title=\"Press\">Press</a></li></ul>', 3);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(4083, 1062, 'Cone', 'Cone', 'Example of a Hell horse ( C , flaming cone is X ) C X X X X X X X X X X X X X C X X X X X X', '<p>Example of a Hell horse (<b>C</b>, flaming cone is <font color=\"red\"><b>X</b></font>)\n</p>\n<table border=\"1\" cellpadding=\"4\" cellspacing=\"0\" style=\"text-align:center;\">\n<tbody><tr>\n<td><b>C</b></td>\n<td></td>\n<td></td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td></td>\n<td><font color=\"red\"><b>X</b></font></td>\n<td><font color=\"red\"><b>X</b></font></td>\n<td><font color=\"red\"><b>X</b></font></td>\n<td><font color=\"red\"><b>X</b></font>\n</td></tr>\n<tr>\n<td></td>\n<td><font color=\"red\"><b>X</b></font></td>\n<td><font color=\"red\"><b>X</b></font></td>\n<td><font color=\"red\"><b>X</b></font></td>\n<td>\n</td></tr>\n<tr>\n<td></td>\n<td><font color=\"red\"><b>X</b></font></td>\n<td><font color=\"red\"><b>X</b></font></td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td></td>\n<td><font color=\"red\"><b>X</b></font></td>\n<td></td>\n<td></td>\n<td>\n</td></tr></tbody></table>\n<p><br/>\n</p>\n<table border=\"1\" cellpadding=\"4\" cellspacing=\"0\" style=\"text-align:center;\">\n<tbody><tr>\n<td></td>\n<td></td>\n<td></td>\n<td><font color=\"red\"><b>X</b></font>\n</td></tr>\n<tr>\n<td></td>\n<td></td>\n<td><font color=\"red\"><b>X</b></font></td>\n<td><font color=\"red\"><b>X</b></font>\n</td></tr>\n<tr>\n<td><b>C</b></td>\n<td><font color=\"red\"><b>X</b></font></td>\n<td><font color=\"red\"><b>X</b></font></td>\n<td><font color=\"red\"><b>X</b></font>\n</td></tr>\n<tr>\n<td></td>\n<td></td>\n<td><font color=\"red\"><b>X</b></font></td>\n<td><font color=\"red\"><b>X</b></font>\n</td></tr>\n<tr>\n<td></td>\n<td></td>\n<td></td>\n<td><font color=\"red\"><b>X</b></font>\n</td></tr></tbody></table>', 0),
(4084, 1062, 'Related creatures', 'Related_creatures', 'Hell horse Red dragon', '<ul><li><a href=\"/index.php/Hell_horse\" title=\"Hell horse\">Hell horse</a></li>\n<li>Red <a href=\"/index.php/Dragon\" title=\"Dragon\">dragon</a></li></ul>', 1),
(4085, 1062, 'See also', 'See_also', 'AoE', '<p><a class=\"mw-redirect\" href=\"/index.php/AoE\" title=\"AoE\">AoE</a>\n</p>', 2),
(4086, 1063, 'Description', 'Description', 'Adamantine and glimmersteel lumps are obtained as rewards from the Hota Battlecamp . Can also be a reward from participating in Rifts At the end of Epic scenarios the winning God will sometimes inflict terraforming events upon the territories of opposing kingdoms such as large trenches, towers of dirt and volcanos. Around these changes boulders appear which can be mined for glimmersteel and adamantine.', '<ul><li>Adamantine and glimmersteel lumps are obtained as rewards from the <a href=\"/index.php/Hota_Battlecamp\" title=\"Hota Battlecamp\">Hota Battlecamp</a>.</li>\n<li>Can also be a reward from participating in <a href=\"/index.php/Rift\" title=\"Rift\">Rifts</a></li>\n<li>At the end of Epic scenarios the winning God will sometimes inflict terraforming events upon the territories of opposing kingdoms such as large trenches, towers of dirt and volcanos. Around these changes boulders appear which can be mined for glimmersteel and adamantine.</li></ul>', 0),
(4087, 1063, 'Notes', 'Notes', 'Like other moon metals, this metal has some very special properties .', '<ul><li>Like other moon metals, this metal has some very <a class=\"mw-redirect\" href=\"/index.php/Metal_properties#Adamantine_Properties\" title=\"Metal properties\">special properties</a>.</li></ul>', 1),
(4088, 1063, 'See also', 'See_also', 'Adamantine products', '<ul><li><a href=\"/index.php/Category:Adamantine_products\" title=\"Category:Adamantine products\">Adamantine products</a></li></ul>', 2),
(4107, 899, 'Description', 'Description', 'Last gasp is an ability that will allow you to climb without slipping for two minutes, with the consequence of halted stamina regeneration for the duration.\nIt can be activated by right-clicking your Body from the character screen (or inventory screen if \'display body in inventory\' is selected) and selecting \"Last gasp\".', '<p>Last gasp is an ability that will allow you to <a class=\"mw-redirect\" href=\"/index.php/Climb\" title=\"Climb\">climb</a> without slipping for two minutes, with the consequence of halted <a class=\"mw-redirect\" href=\"/index.php/Stamina\" title=\"Stamina\">stamina</a> regeneration for the duration.\nIt can be activated by right-clicking your Body from the character screen (or inventory screen if \'display body in inventory\' is selected) and selecting \"Last gasp\". \n</p>', 0),
(4108, 899, 'Notes', 'Notes', 'The option to activate Last gasp appears when you are swimming and are low on stamina. There is a 18 hour waiting period before it can be used again.', '<ul><li>The option to activate Last gasp appears when you are <a href=\"/index.php/Swim\" title=\"Swim\">swimming</a> and are low on stamina.</li>\n<li>There is a 18 hour waiting period before it can be used again.</li></ul>', 1),
(4115, 1070, 'Description', 'Description', 'A purposeful bow rack that will hold most types of bows. Used for storing bows .', '<p><i> A purposeful bow rack that will hold most types of bows. </i>\n</p>\n<p>Used for storing <a class=\"mw-redirect\" href=\"/index.php/Bows\" title=\"Bows\">bows</a>.\n</p>', 0),
(4116, 1070, 'Notes', 'Notes', 'The wood type of the rack is determined by the last piece of wood added during construction. Can hold 100 Short Bows or 89 Bows or 67 Long Bows. To continue building it, it must be on the ground. Can not be locked. Can not be picked up once finished, though it can be pushed/pulled/rotated. Can be loaded in a large cart or above.', '<ul><li>The wood type of the rack is determined by the last piece of wood added during construction.</li>\n<li>Can hold 100 Short Bows or 89 Bows or 67 Long Bows.</li>\n<li>To continue building it, it must be on the ground.</li>\n<li>Can not be locked.</li>\n<li>Can not be picked up once finished, though it can be pushed/pulled/rotated.</li>\n<li>Can be loaded in a large cart or above.</li></ul>', 1),
(4123, 984, 'Description', 'Description', 'Elevation was reset on July 11th, 2019. Before that Elevation was the largest Epic server after having been reset on April 15th, 2015. The former Elevation server ran from November 1, 2011 until being taken down on April 13th, 2015 to prepare for the relaunch.', '<p>Elevation was reset on July 11th, 2019. Before that Elevation was the largest Epic server after having been reset on April 15th, 2015. The former Elevation server ran from November 1, 2011 until being taken down on April 13th, 2015 to prepare for the relaunch.\n</p>', 0),
(4124, 984, 'Spawn settlements', 'Spawn_settlements', 'New Hope (JK) Ignis (MR) Doomspine (HOTS)', '<ul><li><a href=\"/index.php/Settlement:New_Hope\" title=\"Settlement:New Hope\">New Hope (JK)</a></li>\n<li><a href=\"/index.php/Settlement:Ignis\" title=\"Settlement:Ignis\">Ignis (MR)</a></li>\n<li><a href=\"/index.php/Settlement:Doomspine\" title=\"Settlement:Doomspine\">Doomspine (HOTS)</a></li></ul>', 1),
(4125, 984, 'Travel', 'Travel', 'This island may be reached by sailing east from Desertion , north from Affliction , and west from Serenity or by using a portal in the starter city on the other servers in the cluster', '<p>This island may be reached by sailing east from <a href=\"/index.php/Desertion\" title=\"Desertion\">Desertion</a>, north from <a href=\"/index.php/Affliction\" title=\"Affliction\">Affliction</a>, and west from <a href=\"/index.php/Serenity\" title=\"Serenity\">Serenity</a> or by using a portal in the starter city on the other servers in the cluster\n</p>', 2),
(4126, 984, 'Maps', 'Maps', 'In-game map Map dumps', '<ul><li><a href=\"/index.php/File:Elevation.png\" title=\"File:Elevation.png\"> In-game map</a></li>\n<li><a class=\"external text\" href=\"https://drive.google.com/drive/folders/0B6J_aGQ6URL8SHlvVG5FV3U3SU0\" rel=\"nofollow\">Map dumps</a></li></ul>', 3),
(4127, 984, 'Restrictions', 'Restrictions', 'Non-premium accounts cannot travel to the Elevation server.', '<ul><li>Non-premium accounts cannot travel to the Elevation server.</li></ul>', 4),
(4128, 984, 'Elevation Rule Set', 'Elevation_Rule_Set', 'A special rule set applies to Elevation: Maximum digging slope has been reduced to 150. Maximum surface mining / tunneling slope has been reduced to 60. There now needs to be a minimum of 3 tiles between mine doors. A deed will disband automatically after five chained deed drains. Meditation abilities over level 9 have been disabled. Hate Damage Bonus Now Increases lockpicking chance. Element Immunity now only lasts 5 minutes down from 30. Characteristics and Fighting related skills receive less combat bonus in the higher levels(scaling). Removed rare bonus from boats(No replacement for now). Rare horse gear now takes less damage instead of granting a speed bonus. Horses give birth faster. Trader contracts will not be purchasable and traders cannot be placed. Traders will only sell Res Stones/Large Magic Chests/Sleep Powder/Shaker Orbs and can only be found in your starter town. Increased cooldowns on Truestrike, Stoneskin and Continuum. Physical damage resistance and penalty effects from sorcery items changed to fall damage. Karma home teleport has been disabled. No new champions, current champions will be dechamped without the stat loss and will be given 70 faith. Hell horses and Unicorns cannot be hitched or ridden. The chest drop table has also been edited to include flint and steels and compasses.', '<p>A special rule set applies to Elevation:\n</p>\n<ul><li>Maximum digging slope has been reduced to 150.</li>\n<li>Maximum surface mining / tunneling slope has been reduced to 60.</li>\n<li>There now needs to be a minimum of 3 tiles between mine doors.</li>\n<li>A deed will disband automatically after five chained deed drains.</li>\n<li>Meditation abilities over level 9 have been disabled.</li>\n<li>Hate Damage Bonus Now Increases lockpicking chance.</li>\n<li>Element Immunity now only lasts 5 minutes down from 30.</li>\n<li>Characteristics and Fighting related skills receive less combat bonus in the higher levels(scaling).</li>\n<li>Removed rare bonus from boats(No replacement for now).</li>\n<li>Rare horse gear now takes less damage instead of granting a speed bonus.</li>\n<li>Horses give birth faster.</li>\n<li>Trader contracts will not be purchasable and traders cannot be placed.\n<ul><li>Traders will only sell Res Stones/Large Magic Chests/Sleep Powder/Shaker Orbs and can only be found in your starter town.</li></ul></li>\n<li>Increased cooldowns on Truestrike, Stoneskin and Continuum.</li>\n<li>Physical damage resistance and penalty effects from sorcery items changed to fall damage.</li>\n<li>Karma home teleport has been disabled.</li>\n<li>No new champions, current champions will be dechamped without the stat loss and will be given 70 faith.</li>\n<li>Hell horses and Unicorns cannot be hitched or ridden.</li>\n<li>The chest drop table has also been edited to include flint and steels and compasses.</li></ul>\n<p><br/>\n</p>', 5),
(4129, 984, 'Statistics', 'Statistics', 'Server status Server statistics See server graphs for the statistics of all servers.', '<ul><li><a class=\"external text\" href=\"http://elevation.wurmonline.com/battles/stats.html\" rel=\"nofollow\">Server status</a></li>\n<li><a class=\"external text\" href=\"http://elevation.wurmonline.com/mrtg/\" rel=\"nofollow\">Server statistics</a></li>\n<li>See <a href=\"/index.php/Server_graphs\" title=\"Server graphs\">server graphs</a> for the statistics of all servers.<i></i></li></ul>', 6),
(4130, 986, 'Description', 'Description', 'Affliction is home to the Horde of the Summoned kingdom in the Epic cluster. The map was relaunched on October 10th, 2014. The previous map for Affliction was released on November 1st, 2011.', '<p>Affliction is home to the <a href=\"/index.php/Horde_of_the_Summoned\" title=\"Horde of the Summoned\">Horde of the Summoned</a> kingdom in the Epic cluster. \n</p>\n<p>The map was relaunched on October 10th, 2014. The previous map for Affliction was released on November 1st, 2011.\n</p>', 0),
(4131, 986, 'Spawn settlements', 'Spawn_settlements', 'Blackbone', '<ul><li><a href=\"/index.php/Settlement:Blackbone\" title=\"Settlement:Blackbone\">Blackbone</a></li></ul>', 1),
(4132, 986, 'Travel', 'Travel', 'This island may be reached by sailing south from Elevation or by using the portal in Doomspine on Elevation .', '<p>This island may be reached by sailing south from <a href=\"/index.php/Elevation\" title=\"Elevation\">Elevation</a> or by using the portal in <a href=\"/index.php/Settlement:Doomspine\" title=\"Settlement:Doomspine\">Doomspine</a> on <a href=\"/index.php/Elevation\" title=\"Elevation\">Elevation</a>.\n</p>', 2),
(4133, 986, 'Maps', 'Maps', 'In-game map Map dumps', '<ul><li><a href=\"/index.php/File:Affliction_01.jpg\" title=\"File:Affliction 01.jpg\"> In-game map</a></li>\n<li><a class=\"external text\" href=\"https://drive.google.com/drive/folders/0B6J_aGQ6URL8VDd0cVlkYzZHdXc\" rel=\"nofollow\">Map dumps</a></li></ul>', 3),
(4134, 986, 'Statistics', 'Statistics', 'Server status Server statistics See server graphs for the statistics of all servers.', '<ul><li><a class=\"external text\" href=\"http://affliction.wurmonline.com/battles/stats.html\" rel=\"nofollow\">Server status</a></li>\n<li><a class=\"external text\" href=\"http://affliction.wurmonline.com/mrtg/\" rel=\"nofollow\">Server statistics</a></li>\n<li>See <a href=\"/index.php/Server_graphs\" title=\"Server graphs\">server graphs</a> for the statistics of all servers.<i></i></li></ul>', 4),
(4135, 985, 'Description', 'Description', 'Desertion is home to the Mol-Rehan kingdom in the Epic cluster.', '<p>Desertion is home to the <a href=\"/index.php/Mol-Rehan\" title=\"Mol-Rehan\">Mol-Rehan</a> kingdom in the Epic cluster.\n</p>', 0),
(4136, 985, 'Spawn settlements', 'Spawn_settlements', 'Glittershore', '<p><a href=\"/index.php/Settlement:Glittershore\" title=\"Settlement:Glittershore\">Glittershore</a>\n</p>', 1),
(4137, 985, 'Travel', 'Travel', 'This island may be reached by sailing west from Elevation or by using the portal in Ignis on Elevation .', '<p>This island may be reached by sailing west from <a href=\"/index.php/Elevation\" title=\"Elevation\">Elevation</a> or by using the portal in <a href=\"/index.php/Settlement:Ignis\" title=\"Settlement:Ignis\">Ignis</a> on <a href=\"/index.php/Elevation\" title=\"Elevation\">Elevation</a>.\n</p>', 2),
(4138, 985, 'Maps', 'Maps', 'In-game map Map dumps', '<ul><li><a href=\"/index.php/File:Desertion_01.jpg\" title=\"File:Desertion 01.jpg\"> In-game map</a></li>\n<li><a class=\"external text\" href=\"https://drive.google.com/drive/folders/0B6J_aGQ6URL8UXlLX3lVQ0ZmM2c\" rel=\"nofollow\">Map dumps</a></li></ul>', 3),
(4139, 985, 'Statistics', 'Statistics', 'Server status Server statistics See server graphs for the statistics of all servers.', '<ul><li><a class=\"external text\" href=\"http://desertion.wurmonline.com/battles/stats.html\" rel=\"nofollow\">Server status</a></li>\n<li><a class=\"external text\" href=\"http://desertion.wurmonline.com/mrtg/\" rel=\"nofollow\">Server statistics</a></li>\n<li>See <a href=\"/index.php/Server_graphs\" title=\"Server graphs\">server graphs</a> for the statistics of all servers.<i></i></li></ul>', 4),
(4140, 987, 'Description', 'Description', 'Serenity is home to the Jenn-Kellon kingdom in the Epic cluster.', '<p>Serenity is home to the <a href=\"/index.php/Jenn-Kellon\" title=\"Jenn-Kellon\">Jenn-Kellon</a> kingdom in the Epic cluster.\n</p>', 0),
(4141, 987, 'Spawn settlements', 'Spawn_settlements', 'Strongbox', '<ul><li><a href=\"/index.php/Settlement:Strongbox\" title=\"Settlement:Strongbox\">Strongbox</a></li></ul>', 1),
(4142, 987, 'Travel', 'Travel', 'This island may be reached by sailing east from Elevation or by using the portal in New Hope on Elevation .', '<p>This island may be reached by sailing east from <a href=\"/index.php/Elevation\" title=\"Elevation\">Elevation</a> or by using the portal in <a href=\"/index.php/Settlement:New_Hope\" title=\"Settlement:New Hope\">New Hope</a> on <a href=\"/index.php/Elevation\" title=\"Elevation\">Elevation</a>.\n</p>', 2),
(4143, 987, 'Maps', 'Maps', 'In-game map Map dumps', '<ul><li><a href=\"/index.php/File:Serenity_01.jpg\" title=\"File:Serenity 01.jpg\"> In-game map</a></li>\n<li><a class=\"external text\" href=\"https://drive.google.com/drive/folders/0B6J_aGQ6URL8QUJGNTF0cktUeE0\" rel=\"nofollow\">Map dumps</a></li></ul>', 3),
(4144, 987, 'Statistics', 'Statistics', 'Server status Server statistics See server graphs for the statistics of all servers.', '<ul><li><a class=\"external text\" href=\"http://serenity.wurmonline.com/battles/stats.html\" rel=\"nofollow\">Server status</a></li>\n<li><a class=\"external text\" href=\"http://serenity.wurmonline.com/mrtg/\" rel=\"nofollow\">Server statistics</a></li>\n<li>See <a href=\"/index.php/Server_graphs\" title=\"Server graphs\">server graphs</a> for the statistics of all servers.<i></i></li></ul>', 4),
(4161, 1080, 'Getting Karma', 'Getting_Karma', 'The following ways are known to give karma: Conquer a tower on epic and chaos Drink source liquid found in source springs and source fountains . Eat source salt found when mining . Contribute to missions .', '<p>The following ways are known to give karma:\n</p>\n<ul><li><a href=\"/index.php/Conquer\" title=\"Conquer\">Conquer</a> a tower on <a class=\"mw-redirect\" href=\"/index.php/Epic\" title=\"Epic\">epic</a> and <a href=\"/index.php/Chaos\" title=\"Chaos\">chaos</a></li>\n<li>Drink <a href=\"/index.php/Source\" title=\"Source\">source</a> liquid found in <a href=\"/index.php/Source_spring\" title=\"Source spring\">source springs</a> and <a href=\"/index.php/Source_fountain\" title=\"Source fountain\">source fountains</a>.</li>\n<li>Eat <a href=\"/index.php/Source_salt\" title=\"Source salt\">source salt</a> found when <a href=\"/index.php/Mining\" title=\"Mining\">mining</a>.</li>\n<li>Contribute to <a href=\"/index.php/Missions\" title=\"Missions\">missions</a>.</li></ul>', 0),
(4162, 1080, 'Uses for Karma', 'Uses_for_Karma', 'Karma is used to cast spells granted to players through sorcery or the default karma spells. Information on the default karma spells can be found below.', '<p>Karma is used to cast spells granted to players through <a href=\"/index.php/Sorcery\" title=\"Sorcery\">sorcery</a> or the default karma spells. Information on the default karma spells can be found below.\n</p>', 1),
(4163, 1080, 'Using Karma', 'Using_Karma', 'You can see the your current karma level in the \"Using your karma\" window. You use karma by right clicking on your body: How to find the karma menu The current options available on the menu Karma options Description Light up 50 tiles radius (500 karma) Lights up any lamps within 50 tiles radius. Light up 100 tiles radius (1500 karma) Lights up any lamps within 100 tiles radius. Light up 200 tiles radius (3000 karma) Lights up any lamps within 200 tiles radius. Summon corpse (3000 karma, 5 minutes delay) Summons your corpse in your inventory. If you have multiple corpses in the world, this summons the corpse with the most items. Town Portal (1000 karma, enemies block) Instantly teleports you back to your village. Any enemies within a certain unknown range will stop you from making the portal. Does not teleport your mount. Only works if you have been a member of the village for more than 24 hours. Does not work cross-servers.', '<p>You can see the your current karma level in the \"Using your karma\" window. You use karma by right clicking on your body:\n</p>\n<table align=\"center\" border=\"2\" cellpadding=\"2\" cellspacing=\"5\" style=\"text-align:center; style=\">\n<tbody><tr style=\"background-color:#a6a290;\">\n<th>How to find the karma menu\n</th>\n<th>The current options available on the menu\n</th></tr>\n<tr>\n<td><a class=\"image\" href=\"/index.php/File:Karma_Menu.png\"><img alt=\"Karma Menu.png\" data-file-height=\"565\" data-file-width=\"339\" decoding=\"async\" height=\"417\" src=\"/images/thumb/d/d3/Karma_Menu.png/250px-Karma_Menu.png\" srcset=\"/images/d/d3/Karma_Menu.png 1.5x\" width=\"250\"/></a>\n</td>\n<td><a class=\"image\" href=\"/index.php/File:Karma_Options.png\"><img alt=\"Karma Options.png\" data-file-height=\"312\" data-file-width=\"325\" decoding=\"async\" height=\"240\" src=\"/images/thumb/3/32/Karma_Options.png/250px-Karma_Options.png\" srcset=\"/images/3/32/Karma_Options.png 1.5x\" width=\"250\"/></a>\n</td></tr></tbody></table>\n<p><br/>\n</p>\n<table align=\"center\" border=\"2\" cellpadding=\"2\" cellspacing=\"5\" style=\"text-align:center; style=\">\n<tbody><tr style=\"background-color:#a6a290;color:#000000;\">\n<th>Karma options\n</th>\n<th>Description\n</th></tr>\n<tr>\n<td>Light up 50 tiles radius (500 karma)\n</td>\n<td>Lights up any lamps within 50 tiles radius.\n</td></tr>\n<tr>\n<td>Light up 100 tiles radius (1500 karma)\n</td>\n<td>Lights up any lamps within 100 tiles radius.\n</td></tr>\n<tr>\n<td>Light up 200 tiles radius (3000 karma)\n</td>\n<td>Lights up any lamps within 200 tiles radius.\n</td></tr>\n<tr>\n<td>Summon corpse (3000 karma, 5 minutes delay)\n</td>\n<td>Summons your corpse in your inventory.\n<ul><li>If you have multiple corpses in the world, this summons the corpse with the most items.</li></ul>\n</td></tr>\n<tr>\n<td>Town Portal (1000 karma, enemies block)\n</td>\n<td>\n<ul><li>Instantly teleports you back to your village.</li>\n<li>Any enemies within a certain unknown range will stop you from making the portal.</li>\n<li>Does <b>not</b> teleport your mount.</li>\n<li>Only works if you have been a member of the village for more than 24 hours.</li>\n<li>Does <b>not</b> work cross-servers.</li></ul>\n</td></tr></tbody></table>', 2),
(4164, 1078, 'Description', 'Description', 'Hedges are planted on tile borders using 5 sprouts of the same type per border. As hedges grow, they will appear taller ranging from low, medium, and peak.', '<p>Hedges are planted on tile borders using 5 sprouts of the same type per border. As hedges grow, they will appear taller ranging from low, medium, and peak.\n</p>', 0),
(4165, 1078, 'Different Hedge Types', 'Different_Hedge_Types', 'Cedar hedge Camellia hedge Oleander hedge Thorn hedge Rose hedge Maple hedge Lavender plantations', '<ul class=\"gallery mw-gallery-traditional\">\n<li class=\"gallerybox\" style=\"width: 155px\"><div style=\"width: 155px\">\n<div class=\"thumb\" style=\"width: 150px;\"><div style=\"margin:40.5px auto;\"><a class=\"image\" href=\"/index.php/File:Cedar_hedge.png\"><img alt=\"\" data-file-height=\"862\" data-file-width=\"1492\" decoding=\"async\" height=\"69\" src=\"/images/thumb/7/7a/Cedar_hedge.png/120px-Cedar_hedge.png\" srcset=\"/images/thumb/7/7a/Cedar_hedge.png/180px-Cedar_hedge.png 1.5x, /images/thumb/7/7a/Cedar_hedge.png/240px-Cedar_hedge.png 2x\" width=\"120\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>Cedar hedge\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 155px\"><div style=\"width: 155px\">\n<div class=\"thumb\" style=\"width: 150px;\"><div style=\"margin:41px auto;\"><a class=\"image\" href=\"/index.php/File:Camellia_hedge.png\"><img alt=\"\" data-file-height=\"1080\" data-file-width=\"1920\" decoding=\"async\" height=\"68\" src=\"/images/thumb/d/d7/Camellia_hedge.png/120px-Camellia_hedge.png\" srcset=\"/images/thumb/d/d7/Camellia_hedge.png/180px-Camellia_hedge.png 1.5x, /images/thumb/d/d7/Camellia_hedge.png/240px-Camellia_hedge.png 2x\" width=\"120\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>Camellia hedge\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 155px\"><div style=\"width: 155px\">\n<div class=\"thumb\" style=\"width: 150px;\"><div style=\"margin:42.5px auto;\"><a class=\"image\" href=\"/index.php/File:Oleander_hedge.jpg\"><img alt=\"\" data-file-height=\"1544\" data-file-width=\"2829\" decoding=\"async\" height=\"65\" src=\"/images/thumb/6/6a/Oleander_hedge.jpg/120px-Oleander_hedge.jpg\" srcset=\"/images/thumb/6/6a/Oleander_hedge.jpg/180px-Oleander_hedge.jpg 1.5x, /images/thumb/6/6a/Oleander_hedge.jpg/240px-Oleander_hedge.jpg 2x\" width=\"120\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>Oleander hedge\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 155px\"><div style=\"width: 155px\">\n<div class=\"thumb\" style=\"width: 150px;\"><div style=\"margin:30px auto;\"><a class=\"image\" href=\"/index.php/File:Thorn_hedge.jpg\"><img alt=\"\" data-file-height=\"768\" data-file-width=\"1024\" decoding=\"async\" height=\"90\" src=\"/images/thumb/4/41/Thorn_hedge.jpg/120px-Thorn_hedge.jpg\" srcset=\"/images/thumb/4/41/Thorn_hedge.jpg/180px-Thorn_hedge.jpg 1.5x, /images/thumb/4/41/Thorn_hedge.jpg/240px-Thorn_hedge.jpg 2x\" width=\"120\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>Thorn hedge\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 155px\"><div style=\"width: 155px\">\n<div class=\"thumb\" style=\"width: 150px;\"><div style=\"margin:42px auto;\"><a class=\"image\" href=\"/index.php/File:Rose_hedge.jpg\"><img alt=\"\" data-file-height=\"1450\" data-file-width=\"2641\" decoding=\"async\" height=\"66\" src=\"/images/thumb/6/67/Rose_hedge.jpg/120px-Rose_hedge.jpg\" srcset=\"/images/thumb/6/67/Rose_hedge.jpg/180px-Rose_hedge.jpg 1.5x, /images/thumb/6/67/Rose_hedge.jpg/240px-Rose_hedge.jpg 2x\" width=\"120\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>Rose hedge\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 155px\"><div style=\"width: 155px\">\n<div class=\"thumb\" style=\"width: 150px;\"><div style=\"margin:34px auto;\"><a class=\"image\" href=\"/index.php/File:High_maple_hedge.jpg\"><img alt=\"\" data-file-height=\"650\" data-file-width=\"950\" decoding=\"async\" height=\"82\" src=\"/images/thumb/b/bc/High_maple_hedge.jpg/120px-High_maple_hedge.jpg\" srcset=\"/images/thumb/b/bc/High_maple_hedge.jpg/180px-High_maple_hedge.jpg 1.5x, /images/thumb/b/bc/High_maple_hedge.jpg/240px-High_maple_hedge.jpg 2x\" width=\"120\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>Maple hedge\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 155px\"><div style=\"width: 155px\">\n<div class=\"thumb\" style=\"width: 150px;\"><div style=\"margin:51px auto;\"><a class=\"image\" href=\"/index.php/File:Lavender_plantation.jpg\"><img alt=\"\" data-file-height=\"400\" data-file-width=\"1000\" decoding=\"async\" height=\"48\" src=\"/images/thumb/c/c9/Lavender_plantation.jpg/120px-Lavender_plantation.jpg\" srcset=\"/images/thumb/c/c9/Lavender_plantation.jpg/180px-Lavender_plantation.jpg 1.5x, /images/thumb/c/c9/Lavender_plantation.jpg/240px-Lavender_plantation.jpg 2x\" width=\"120\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>Lavender plantations\n</p>\n</div>\n</div></li>\n</ul>', 1),
(4166, 1078, 'Planting', 'Planting', 'The types of sprouts that can be used to create hedges are: Camellia , Cedar , Lavender , Maple , Oleander , Rose , and Thorn . Hedges are planted on tile borders using 5 sprouts of the same type per border. Hedges can only be planted on borders where at least one of the bordering tiles is dirt , steppe , or grass (including trees and bushes). Crops and packed dirt do not count as dirt. The tile type can be changed after planting without destroying the hedge (unless both tiles become rock ). Hedges cannot be planted on the same border as an arched wall of any type. Hedges don\'t have slope limitations for creating, unlike fences. Failure to plant will destroy one sprout.', '<ul><li>The types of sprouts that can be used to create hedges are: <a class=\"mw-redirect\" href=\"/index.php/Camellia\" title=\"Camellia\">Camellia</a>, <a class=\"mw-redirect\" href=\"/index.php/Cedar\" title=\"Cedar\">Cedar</a>, <a class=\"mw-redirect\" href=\"/index.php/Lavender\" title=\"Lavender\">Lavender</a>, <a class=\"mw-redirect\" href=\"/index.php/Maple\" title=\"Maple\">Maple</a>, <a href=\"/index.php/Oleander\" title=\"Oleander\">Oleander</a>, <a class=\"mw-redirect\" href=\"/index.php/Rose\" title=\"Rose\">Rose</a>, and <a class=\"mw-redirect\" href=\"/index.php/Thorn\" title=\"Thorn\">Thorn</a>.</li>\n<li>Hedges are planted on tile borders using 5 sprouts of the same type per border.</li>\n<li>Hedges can only be planted on borders where at least one of the bordering tiles is <a href=\"/index.php/Dirt\" title=\"Dirt\">dirt</a>, <a class=\"mw-redirect\" href=\"/index.php/Steppe\" title=\"Steppe\">steppe</a>, or <a class=\"mw-redirect\" href=\"/index.php/Grass\" title=\"Grass\">grass</a> (including trees and bushes).\n<ul><li><a class=\"mw-redirect\" href=\"/index.php/Crops\" title=\"Crops\">Crops</a> and <a class=\"mw-redirect\" href=\"/index.php/Packed_dirt\" title=\"Packed dirt\">packed dirt</a> do not count as dirt.</li>\n<li>The tile type can be changed after planting without destroying the hedge (unless <i>both</i> tiles become <a href=\"/index.php/Rock\" title=\"Rock\">rock</a>).</li></ul></li>\n<li>Hedges cannot be planted on the same border as an arched wall of any type.</li>\n<li>Hedges don\'t have slope limitations for creating, unlike fences.</li>\n<li>Failure to plant will destroy one sprout.</li></ul>', 2),
(4167, 1078, 'Growth', 'Growth', 'Newly planted hedges are \'low\' and wont block movement until reaching a height of \'medium\', or line of sight until \'high\'. The spell Wild Growth will progress a hedge one stage towards its peak height. Hedges can be pruned one stage shorter per pruning action using a sickle (to a minimum of \'low\'), but will eventually re-grow unless destroyed. Hedges do not shrivel with age. Lavender hedges stay at the lowest height and therefore remain passable. Camellia hedges stop growing upon reaching medium height, blocking movement but allowing line of sight. Hedges do not blossom with seasonal produce nor do they produce sprouts. Different Heights Short: Medium: Peak: This low hedge is growing steadily. This medium sized hedge is growing steadily. This hedge seems to be at peak height.', '<ul><li>Newly planted hedges are \'low\' and wont block movement until reaching a height of \'medium\', or line of sight until \'high\'.</li>\n<li>The spell <a class=\"mw-redirect\" href=\"/index.php/Wild_Growth\" title=\"Wild Growth\">Wild Growth</a> will progress a hedge one stage towards its peak height.</li>\n<li>Hedges can be pruned one stage shorter per pruning action using a <a href=\"/index.php/Sickle\" title=\"Sickle\">sickle</a> (to a minimum of \'low\'), but will eventually re-grow unless destroyed.</li>\n<li>Hedges do not shrivel with age.</li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Lavender\" title=\"Lavender\">Lavender</a> hedges stay at the lowest height and therefore remain passable.</li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Camellia\" title=\"Camellia\">Camellia</a> hedges stop growing upon reaching medium height, blocking movement but allowing line of sight.</li>\n<li>Hedges do not blossom with seasonal produce nor do they produce sprouts.</li></ul>\n<table align=\"center\" border=\"2\" cellpadding=\"2\" cellspacing=\"5\" style=\"text-align:center; style=\">\n<caption>Different Heights\n</caption>\n<tbody><tr style=\"background-color:#a6a290;\">\n<th>Short:\n</th>\n<th>Medium:\n</th>\n<th>Peak:\n</th></tr>\n<tr>\n<td><a class=\"image\" href=\"/index.php/File:Low-Hedge.png\"><img alt=\"Low-Hedge.png\" data-file-height=\"650\" data-file-width=\"950\" decoding=\"async\" height=\"171\" src=\"/images/thumb/b/bd/Low-Hedge.png/250px-Low-Hedge.png\" srcset=\"/images/thumb/b/bd/Low-Hedge.png/375px-Low-Hedge.png 1.5x, /images/thumb/b/bd/Low-Hedge.png/500px-Low-Hedge.png 2x\" width=\"250\"/></a>\n</td>\n<td><a class=\"image\" href=\"/index.php/File:Meduim-Hedge.png\"><img alt=\"Meduim-Hedge.png\" data-file-height=\"650\" data-file-width=\"950\" decoding=\"async\" height=\"171\" src=\"/images/thumb/b/ba/Meduim-Hedge.png/250px-Meduim-Hedge.png\" srcset=\"/images/thumb/b/ba/Meduim-Hedge.png/375px-Meduim-Hedge.png 1.5x, /images/thumb/b/ba/Meduim-Hedge.png/500px-Meduim-Hedge.png 2x\" width=\"250\"/></a>\n</td>\n<td><a class=\"image\" href=\"/index.php/File:Peak-Hedge.png\"><img alt=\"Peak-Hedge.png\" data-file-height=\"650\" data-file-width=\"950\" decoding=\"async\" height=\"171\" src=\"/images/thumb/2/23/Peak-Hedge.png/250px-Peak-Hedge.png\" srcset=\"/images/thumb/2/23/Peak-Hedge.png/375px-Peak-Hedge.png 1.5x, /images/thumb/2/23/Peak-Hedge.png/500px-Peak-Hedge.png 2x\" width=\"250\"/></a>\n</td></tr>\n<tr style=\"color:#a6a290\">\n<td>This low hedge is growing steadily.\n</td>\n<td>This medium sized hedge is growing steadily.\n</td>\n<td>This hedge seems to be at peak height.\n</td></tr></tbody></table>', 3),
(4168, 1078, 'Notes', 'Notes', 'With a Body strength of 21, hedges can be destroyed by a Hatchet or any bashing tool. Low hedges are easier to destroy than taller hedges. The border under a hedge cannot be terraformed without first destroying the hedge.', '<ul><li>With a <a href=\"/index.php/Body_strength\" title=\"Body strength\">Body strength</a> of 21, hedges can be destroyed by a <a href=\"/index.php/Hatchet\" title=\"Hatchet\">Hatchet</a> or any bashing tool.</li>\n<li>Low hedges are easier to destroy than taller hedges.</li>\n<li>The border under a hedge cannot be terraformed without first destroying the hedge.</li></ul>', 4),
(4169, 1082, 'Description', 'Description', 'A few stones glisten from the pinkish liquid known as the Source which emanates here. A spring that can contain source . Spawns randomly outside or underground and cannot be created.', '<p><i>A few stones glisten from the pinkish liquid known as the Source which emanates here.</i>\n</p>\n<p>A spring that can contain <a href=\"/index.php/Source\" title=\"Source\">source</a>. Spawns randomly outside or underground and cannot be created.\n</p>\n<p><img alt=\"26005d13c3.jpg\" src=\"http://puu.sh/8Go4T/26005d13c3.jpg\"/> <img alt=\"Ud9BSls.png\" src=\"http://i.imgur.com/Ud9BSls.png\"/>\n</p>', 0),
(4170, 1082, 'Use', 'Use', 'Drinking the contents will grant you karma ; 10 karma for each 0.01 kg, as with source salt .  The source liquid can also be moved into a liquid container.', '<p>Drinking the contents will grant you <a href=\"/index.php/Karma\" title=\"Karma\">karma</a>; 10 karma for each 0.01 kg, as with <a href=\"/index.php/Source_salt\" title=\"Source salt\">source salt</a>.  The <a href=\"/index.php/Source\" title=\"Source\">source</a> liquid can also be moved into a liquid container.\n</p>', 1),
(4171, 1082, 'Notes', 'Notes', 'Can be seen within a 14 tile range. Can be drunk from once; it will then disintegrate afterwards. Cannot be moved or bashed.', '<ul><li>Can be seen within a 14 tile range.</li>\n<li>Can be drunk from once; it will then disintegrate afterwards.</li>\n<li>Cannot be moved or bashed.</li></ul>', 2),
(4172, 1082, 'See also', 'See_also', 'Source fountain', '<ul><li><a href=\"/index.php/Source_fountain\" title=\"Source fountain\">Source fountain</a></li></ul>', 3),
(4173, 1083, 'Description', 'Description', 'An ancient fountain has been built on top of a Source spring. It has a pinkish tint from the mysterious substance. A fountain that can contain Source which is a liquid.', '<p><i>An ancient fountain has been built on top of a Source spring. It has a pinkish tint from the mysterious substance.</i>\n</p>\n<p>A fountain that can contain <a href=\"/index.php/Source\" title=\"Source\">Source</a> which is a liquid.\n</p>', 0),
(4174, 1083, 'Use', 'Use', 'Drinking the contents will grant you Karma ; 10 karma for each 0.01 kg, as with source salt .  The Source liquid can also be moved into a liquid container.', '<p>Drinking the contents will grant you <a href=\"/index.php/Karma\" title=\"Karma\">Karma</a>; 10 karma for each 0.01 kg, as with <a href=\"/index.php/Source_salt\" title=\"Source salt\">source salt</a>.  The <a href=\"/index.php/Source\" title=\"Source\">Source</a> liquid can also be moved into a liquid container.\n</p>', 1),
(4175, 1083, 'Notes', 'Notes', 'Can only be seen within a 4 tile range. Doesn\'t refill. Can`t be moved or bashed.', '<ul><li>Can only be seen within a 4 tile range.</li>\n<li>Doesn\'t refill.</li>\n<li>Can`t be moved or bashed.</li></ul>', 2),
(4176, 1083, 'See also', 'See_also', 'Source spring', '<ul><li><a href=\"/index.php/Source_spring\" title=\"Source spring\">Source spring</a></li></ul>', 3),
(4177, 1069, 'Description', 'Description', 'An armour stand used to keep your armour. This decorative armour rack can be used as a container to store armour . It will change appearance between when being empty, and having at least 1 item stored inside.', '<p><i>An armour stand used to keep your armour.</i>\n</p>\n<p>This decorative armour rack can be used as a <a href=\"/index.php/Container\" title=\"Container\">container</a> to store <a href=\"/index.php/Armour\" title=\"Armour\">armour</a>. It will change appearance between when being empty, and having at least 1 item stored inside.\n</p>', 0),
(4178, 1069, 'Notes', 'Notes', 'Higher quality small nails increase your success chance for creating. Failure creating causes the nails and the plank to take some damage . Currently shows the look of studded leather armour whenever one or more items are inside. Holds at least 1 set of all known types of armour. To continue building it, you must put it on the ground. It cannot be picked up once finished, though it can be push/pull/rotated. Can be loaded into a large cart or wagon. Can be loaded into ships other than rowing/sailboat. Cannot be locked with small or large padlocks . Does not prevent decay of items inside.', '<ul><li>Higher <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> small nails increase your success chance for creating.</li>\n<li><a href=\"/index.php/Failure\" title=\"Failure\">Failure</a> creating causes the nails and the plank to take some <a href=\"/index.php/Damage\" title=\"Damage\">damage</a>.</li>\n<li>Currently shows the look of <a class=\"mw-redirect\" href=\"/index.php/Studded_leather_armour\" title=\"Studded leather armour\">studded leather armour</a> whenever one or more items are inside.</li>\n<li>Holds at least 1 set of all known types of armour.</li>\n<li>To <a class=\"mw-redirect\" href=\"/index.php/Continue\" title=\"Continue\">continue</a> building it, you must put it on the ground.</li>\n<li>It cannot be picked up once finished, though it can be push/pull/rotated.</li>\n<li>Can be loaded into a large cart or wagon.</li>\n<li>Can be loaded into ships other than rowing/sailboat.</li>\n<li>Cannot be locked with <a href=\"/index.php/Small_padlock\" title=\"Small padlock\">small</a> or <a href=\"/index.php/Large_padlock\" title=\"Large padlock\">large padlocks</a>.</li>\n<li>Does not prevent decay of items inside.</li></ul>', 1),
(4179, 1069, 'See Also', 'See_Also', 'Container', '<ul><li><a href=\"/index.php/Container\" title=\"Container\">Container</a></li></ul>', 2),
(4180, 1087, 'Description', 'Description', 'You see an arched wall opening', '<p><i>You see an arched wall opening </i>\n</p>', 0),
(4181, 1087, 'Skill Requirements', 'Skill_Requirements', 'At least 30 masonry skill is required to build stone walls. See multi-story housing for more information regarding skill requirements on additional floors.', '<ul><li>At least 30 <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill is required to build stone walls.</li>\n<li>See <a href=\"/index.php/Multi-story_housing#Skill_needed\" title=\"Multi-story housing\">multi-story housing</a> for more information regarding skill requirements on additional floors.</li></ul>', 1),
(4182, 1087, 'Creation', 'Creation', 'Have at least 1 Stone brick and 1 mortar in your inventory. Activate a trowel and right-click on a wall plan . Select Build and then Stone arched wall . Continuation requires at least 1 Stone brick and 1 mortar in your inventory.', '<ul><li>Have at least 1 <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> and 1 <a href=\"/index.php/Mortar\" title=\"Mortar\">mortar</a> in your inventory.</li>\n<li><b>Activate</b> a <a href=\"/index.php/Trowel\" title=\"Trowel\">trowel</a> and <b>right-click</b> on a <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">wall plan</a>.</li>\n<li>Select <b>Build</b> and then <b>Stone arched wall</b>.</li>\n<li>Continuation requires at least 1 <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> and 1 mortar in your inventory.</li></ul>', 2),
(4183, 1087, 'Modifying', 'Modifying', 'Pliers are used for modifying the wall into its trimless version, the Plain stone arched wall . Activate the tool and right-click the wall, then select Remove Decorations . You can turn walls to suit your needs by right-clicking them, and selecting Rotate wall .', '<ul><li><a href=\"/index.php/Pliers\" title=\"Pliers\">Pliers</a> are used for modifying the wall into its trimless version, the <a href=\"/index.php/Plain_stone_arched_wall\" title=\"Plain stone arched wall\">Plain stone arched wall</a>.  <b>Activate</b> the tool and <b>right-click</b> the wall, then select <b>Remove Decorations</b>.</li>\n<li>You can turn walls to suit your needs by <b>right-clicking</b> them, and selecting <b>Rotate wall</b>.</li></ul>', 3),
(4184, 1087, 'Improving', 'Improving', 'You must repair any damage on the walls with a Stone brick before improving it. Activate a Stone brick , right-click the wall and select Repair or Improve . The effective quality of the Stone brick is affected by its damage and your masonry skill, it must be higher than the wall\'s current quality.', '<ul><li>You must <a href=\"/index.php/Repairing\" title=\"Repairing\">repair</a> any <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> on the walls with a <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> before <a href=\"/index.php/Improve\" title=\"Improve\">improving</a> it.</li>\n<li>Activate a <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a>, right-click the wall and select <i>Repair</i> or <i>Improve</i>.</li>\n<li>The effective <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> is affected by its damage and your <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill, it must be higher than the wall\'s current quality.</li></ul>\n<p><br/>\n</p>', 4),
(4185, 1087, 'See also', 'See_also', 'Stone wall Stone door Stone portcullis Stone window Stone oriel Stone double door Stone T arch Stone arch right Stone arch left', '<ul><li><a href=\"/index.php/Stone_wall\" title=\"Stone wall\">Stone wall</a></li>\n<li><a href=\"/index.php/Stone_door\" title=\"Stone door\">Stone door</a></li>\n<li><a href=\"/index.php/Stone_portcullis_(wall)\" title=\"Stone portcullis (wall)\"> Stone portcullis</a></li>\n<li><a href=\"/index.php/Stone_window\" title=\"Stone window\">Stone window</a></li>\n<li><a href=\"/index.php/Stone_oriel\" title=\"Stone oriel\">Stone oriel</a></li>\n<li><a href=\"/index.php/Stone_double_door\" title=\"Stone double door\">Stone double door</a></li>\n<li><a href=\"/index.php/Stone_T_arch\" title=\"Stone T arch\">Stone T arch</a></li>\n<li><a href=\"/index.php/Stone_arch_right\" title=\"Stone arch right\">Stone arch right</a></li>\n<li><a href=\"/index.php/Stone_arch_left\" title=\"Stone arch left\">Stone arch left</a></li></ul>', 5),
(4186, 1088, 'Description', 'Description', 'An arched wall for a wooden house . Its archway is wide to facilitate vistas and vehicles.', '<p>An arched wall for a wooden <a href=\"/index.php/House\" title=\"House\">house</a>. Its archway is wide to facilitate vistas and vehicles. \n</p>', 0),
(4187, 1088, 'Modifying', 'Modifying', 'You can turn walls to suit your needs. Repairing and improving Any damage must be repaired on the walls with a plank before improving it. Activate a plank, right-click the wall, and select \"Repair\" or \"Improve\". The effective quality of the plank is affected by its damage and the player\'s carpentry skill. Any quality plank can be used to repair and improve a wall (which will improve by between around .04-1.5+ QL per plank--more research needed but a higher QL plank will yield more improved QL). 1 plank will repair up to 10 damage depending on quality and repairing skill.', '<p>You can turn walls to suit your needs.\n</p>\n<h3><span class=\"mw-headline\" id=\"Repairing_and_improving\">Repairing and improving</span></h3>\n<ul><li>Any <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> must be <a href=\"/index.php/Repairing\" title=\"Repairing\">repaired</a> on the walls with a <a href=\"/index.php/Plank\" title=\"Plank\">plank</a> before <a class=\"mw-redirect\" href=\"/index.php/Improving\" title=\"Improving\">improving</a> it.</li>\n<li>Activate a plank, right-click the wall, and select \"Repair\" or \"Improve\".</li>\n<li>The effective <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the plank is affected by its <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> and the <a href=\"/index.php/Player\" title=\"Player\">player\'s</a> <a href=\"/index.php/Carpentry\" title=\"Carpentry\">carpentry</a> skill.</li>\n<li>Any quality plank can be used to repair and improve a wall (which will improve by between around .04-1.5+ QL per plank--more research needed but a higher QL plank will yield more improved QL).</li>\n<li>1 plank will repair up to 10 damage depending on quality and repairing skill.</li></ul>', 1),
(4188, 1088, 'Notes', 'Notes', 'It is possible to build fences in the archway of these walls, but not hedges. 3x Bonus Damage dealt when bashed manually.', '<ul><li>It is possible to build fences in the archway of these walls, but not hedges.</li>\n<li>3x Bonus Damage dealt when bashed manually.</li></ul>', 2),
(4189, 1088, 'See also', 'See_also', 'Wooden wall Wooden door Wooden double door Wooden window Wooden wide window Wooden portcullis Wooden canopy Wooden arch Wooden T arch Wooden arch right Wooden arch left', '<ul><li><a href=\"/index.php/Wooden_wall\" title=\"Wooden wall\">Wooden wall</a></li>\n<li><a href=\"/index.php/Wooden_door\" title=\"Wooden door\">Wooden door</a></li>\n<li><a href=\"/index.php/Wooden_double_door\" title=\"Wooden double door\">Wooden double door</a></li>\n<li><a href=\"/index.php/Wooden_window\" title=\"Wooden window\">Wooden window</a></li>\n<li><a href=\"/index.php/Wooden_wide_window\" title=\"Wooden wide window\">Wooden wide window</a></li>\n<li><a href=\"/index.php/Wooden_portcullis\" title=\"Wooden portcullis\">Wooden portcullis</a></li>\n<li><a href=\"/index.php/Wooden_canopy\" title=\"Wooden canopy\">Wooden canopy</a></li>\n<li><a href=\"/index.php/Wooden_arch\" title=\"Wooden arch\">Wooden arch</a></li>\n<li><a href=\"/index.php/Wooden_T_arch\" title=\"Wooden T arch\">Wooden T arch</a></li>\n<li><a href=\"/index.php/Wooden_arch_right\" title=\"Wooden arch right\">Wooden arch right</a></li>\n<li><a href=\"/index.php/Wooden_arch_left\" title=\"Wooden arch left\">Wooden arch left</a></li></ul>', 3),
(4190, 1089, 'Description', 'Description', 'This is a translucent pink, glittering crystal containing the Source - the essence of the future.', '<p><i>This is a translucent pink, glittering crystal containing the Source - the essence of the future.</i>\n</p>', 0),
(4191, 1089, 'Use', 'Use', 'A source crystal can be crushed with a hammer or mallet into source salt , which provides 30 karma when eaten and can be used to create potions from blood .', '<p>A source crystal can be crushed with a <a href=\"/index.php/Hammer\" title=\"Hammer\">hammer</a> or <a href=\"/index.php/Mallet\" title=\"Mallet\">mallet</a> into <a href=\"/index.php/Source_salt\" title=\"Source salt\">source salt</a>, which provides 30 <a href=\"/index.php/Karma\" title=\"Karma\">karma</a> when eaten and can be used to create <a href=\"/index.php/Potions\" title=\"Potions\">potions</a> from <a href=\"/index.php/Blood\" title=\"Blood\">blood</a>.\n</p>', 1),
(4192, 1089, 'Notes', 'Notes', 'Does not decay .', '<ul><li>Does not <a href=\"/index.php/Decay\" title=\"Decay\">decay</a>.</li></ul>', 2),
(4193, 1089, 'See Also', 'See_Also', 'Source Source salt Source spring Source fountain Karma', '<ul><li><a href=\"/index.php/Source\" title=\"Source\">Source</a></li>\n<li><a href=\"/index.php/Source_salt\" title=\"Source salt\">Source salt</a></li>\n<li><a href=\"/index.php/Source_spring\" title=\"Source spring\">Source spring</a></li>\n<li><a href=\"/index.php/Source_fountain\" title=\"Source fountain\">Source fountain</a></li>\n<li><a href=\"/index.php/Karma\" title=\"Karma\">Karma</a></li></ul>', 3),
(4194, 1090, 'Description', 'Description', 'This pink salt comes from the Source, which is believed to be the essence of the future.', '<p><i>This pink salt comes from the Source, which is believed to be the essence of the future.</i>\n</p>', 0),
(4195, 1090, 'Use', 'Use', 'A 0.03 kg piece of source salt gives 30 karma when eaten. Can be used in the place of normal salt in meals. When combined with blood various tool enhancing potions can be created.', '<ul><li>A 0.03 kg piece of source salt gives 30 <a href=\"/index.php/Karma\" title=\"Karma\">karma</a> when eaten.</li>\n<li>Can be used in the place of normal <a href=\"/index.php/Salt\" title=\"Salt\">salt</a> in meals.</li>\n<li>When combined with <a href=\"/index.php/Blood\" title=\"Blood\">blood</a> various <a class=\"mw-redirect\" href=\"/index.php/Tool\" title=\"Tool\">tool</a> enhancing potions can be created.</li></ul>', 1);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(4196, 1090, 'Notes', 'Notes', 'When placed into a food storage bin or a crate , the source salt stored in units weighing 0.001 kg each; a single 0.03kg piece of source salt turns into 30 individual 0.001 kg units. Since karma is granted per unit of weight, a 0.001kg piece of source salt gives 1 karma, and you do not gain less karma by placing source salt in bins before eating. It takes .01 kg of source salt to make a potion from blood . Source salt is technically food, so eating it may alter your nutrition slightly. Can be combined (maximum combined weight of 0.06 kg)', '<ul><li>When placed into a <a href=\"/index.php/Food_storage_bin\" title=\"Food storage bin\">food storage bin</a> or a <a href=\"/index.php/Crate\" title=\"Crate\">crate</a>, the source salt stored in units weighing 0.001 kg each; a single 0.03kg piece of source salt turns into 30 individual 0.001 kg units.\n<ul><li>Since karma is granted per unit of weight, a 0.001kg piece of source salt gives 1 karma, and you do not gain less karma by placing source salt in bins before eating.</li>\n<li>It takes .01 kg of source salt to make a potion from <a href=\"/index.php/Blood\" title=\"Blood\">blood</a>.</li></ul></li>\n<li>Source salt is technically food, so eating it may alter your nutrition slightly.</li>\n<li>Can be combined (maximum combined weight of 0.06 kg)</li></ul>', 2),
(4197, 1090, 'See Also', 'See_Also', 'Source Source crystal Source spring Source fountain Karma', '<ul><li><a href=\"/index.php/Source\" title=\"Source\">Source</a></li>\n<li><a href=\"/index.php/Source_crystal\" title=\"Source crystal\">Source crystal</a></li>\n<li><a href=\"/index.php/Source_spring\" title=\"Source spring\">Source spring</a></li>\n<li><a href=\"/index.php/Source_fountain\" title=\"Source fountain\">Source fountain</a></li>\n<li><a href=\"/index.php/Karma\" title=\"Karma\">Karma</a></li></ul>', 3),
(4261, 1072, 'Spawn settlements', 'Spawn_settlements', 'Tap Dance', '<ul><li><a href=\"/index.php/Settlement:Tap_Dance\" title=\"Settlement:Tap Dance\">Tap Dance</a></li></ul>', 0),
(4262, 1072, 'Travel', 'Travel', 'This island may be reached by sailing south from Exodus . When leaving, sailing west will take you to Chaos and east will take you to Xanadu . Celebration can also be reached from any Southern Isle server by using plot course .', '<p>This island may be reached by sailing south from <a href=\"/index.php/Exodus\" title=\"Exodus\">Exodus</a>. When leaving, sailing west will take you to <a href=\"/index.php/Chaos\" title=\"Chaos\">Chaos</a> and east will take you to <a href=\"/index.php/Xanadu\" title=\"Xanadu\">Xanadu</a>. Celebration can also be reached from any Southern Isle server by using <a href=\"/index.php/Server_travel\" title=\"Server travel\">plot course</a>. \n</p>', 1),
(4263, 1072, 'Maps', 'Maps', 'In-game map Map dumps For community maps, see Maps', '<ul><li><a href=\"/index.php/File:Celebration_01.jpg\" title=\"File:Celebration 01.jpg\"> In-game map</a></li>\n<li><a class=\"external text\" href=\"https://drive.google.com/drive/folders/0B6J_aGQ6URL8S1g3RlRYcFdmSVk\" rel=\"nofollow\">Map dumps</a></li>\n<li>For community maps, see <a href=\"/index.php/Maps\" title=\"Maps\">Maps</a></li></ul>', 2),
(4264, 1072, 'Statistics', 'Statistics', 'Server status Server statistics See server graphs for the statistics of all servers.', '<ul><li><a class=\"external text\" href=\"http://celebration.live.wurmonline.io/battles/stats.html\" rel=\"nofollow\">Server status</a></li>\n<li><a class=\"external text\" href=\"http://celebration.live.wurmonline.io/mrtg/\" rel=\"nofollow\">Server statistics</a></li>\n<li>See <a href=\"/index.php/Server_graphs\" title=\"Server graphs\">server graphs</a> for the statistics of all servers.<i></i></li></ul>', 3),
(4265, 1104, 'Description', 'Description', '\"Holy ground\" is the term that refers to the special zone that covers 150 tiles around the Bone Altar . Deeds and guard towers cannot be placed within this zone.', '<p>\"Holy ground\" is the term that refers to the special zone that covers 150 tiles around the <a href=\"/index.php/Bone_Altar\" title=\"Bone Altar\">Bone Altar</a>. <a class=\"mw-redirect\" href=\"/index.php/Deed\" title=\"Deed\">Deeds</a> and <a href=\"/index.php/Guard_tower\" title=\"Guard tower\">guard towers</a> cannot be placed within this zone.\n</p>', 0),
(4266, 1105, 'Description', 'Description', 'This is the rare light pink liquid known as the Source. It is said to contain the essence of the future. This is the liquid found from Source springs and Source fountains .', '<p><i>This is the rare light pink liquid known as the Source. It is said to contain the essence of the future.</i>\n</p>\n<p>This is the liquid found from <a href=\"/index.php/Source_spring\" title=\"Source spring\">Source springs</a> and <a href=\"/index.php/Source_fountain\" title=\"Source fountain\">Source fountains</a>.  \n</p>', 0),
(4267, 1105, 'Use', 'Use', 'Drinking it gives you some Karma .', '<p>Drinking it gives you some <a href=\"/index.php/Karma\" title=\"Karma\">Karma</a>.\n</p>', 1),
(4268, 1105, 'Notes', 'Notes', 'Source does not seem to decay. Each 0.01 liquid gives 10 Karma.', '<ul><li>Source does not seem to decay.</li>\n<li>Each 0.01 liquid gives 10 Karma.</li></ul>', 2),
(4279, 1109, 'Description', 'Description', 'A hammer looking item with a handle and a flat surface mounted with flattened nails. It is used to create thatch from reed .', '<p><i>A hammer looking item with a handle and a flat surface mounted with flattened nails. It is used to create <a href=\"/index.php/Thatch\" title=\"Thatch\">thatch</a> from <a href=\"/index.php/Reed\" title=\"Reed\">reed</a>.</i>\n</p>', 0),
(4280, 1109, 'Notes', 'Notes', 'When creating, the quality of the large nails affects the success chance. Uses the Hammer skill when creating thatch . Mixed grass can be used to make thatch too. Thatch is used in making Thatched roof .', '<ul><li>When creating, the <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the large nails affects the success chance.</li>\n<li>Uses the <a href=\"/index.php/Hammer\" title=\"Hammer\">Hammer</a> <a class=\"mw-redirect\" href=\"/index.php/Skill\" title=\"Skill\">skill</a> when creating <a href=\"/index.php/Thatch\" title=\"Thatch\">thatch</a>.</li>\n<li><a href=\"/index.php/Mixed_grass\" title=\"Mixed grass\">Mixed grass</a> can be used to make thatch too.</li>\n<li><a href=\"/index.php/Thatch\" title=\"Thatch\">Thatch</a> is used in making <a href=\"/index.php/Thatched_roof\" title=\"Thatched roof\">Thatched roof</a>.</li></ul>', 1),
(4288, 1112, 'Description', 'Description', 'This monumental structure is said to represent two hills between which the sun rises and sets. It is commonly associated with recreation and birth. Pylons are mission structures requiring high Masonry skill.', '<p><i>This monumental structure is said to represent two hills between which the sun rises and sets. It is commonly associated with recreation and birth.</i>\n</p>\n<p><b>Pylons</b> are <a href=\"/index.php/Category:Mission_structures\" title=\"Category:Mission structures\">mission structures</a> requiring high <a href=\"/index.php/Masonry\" title=\"Masonry\">Masonry</a> skill.\n</p>', 0),
(4289, 1112, 'Mission Text', 'Mission_Text', '[Deity name] request that you build \"Pylon\" on a Flat, 7x7 slabbed area near the water in [Named map region].', '<p><i>[Deity name] request that you build \"Pylon\" on a Flat, 7x7 slabbed area near the water in [Named map region].</i>\n</p>', 1),
(4290, 1112, 'Total Materials', 'Total_Materials', '1000 Stone bricks 2000 Clay 1000 Brass lump 150 Stone slabs (49 slabs used for the area) 4150 total pieces', '<ul><li>1000 <a class=\"mw-redirect\" href=\"/index.php/Stone_bricks\" title=\"Stone bricks\">Stone bricks</a></li>\n<li>2000 <a href=\"/index.php/Clay\" title=\"Clay\">Clay</a></li>\n<li>1000 <a href=\"/index.php/Brass_lump\" title=\"Brass lump\">Brass lump</a></li>\n<li>150 <a href=\"/index.php/Stone_slabs\" title=\"Stone slabs\">Stone slabs</a> (49 slabs used for the area)</li>\n<li>4150 total pieces</li></ul>', 2),
(4291, 1112, 'Notes', 'Notes', 'Slab quality plus masonry skill have to be a combined total of over 108.', '<ul><li>Slab quality plus masonry skill have to be a combined total of over 108.</li></ul>', 3),
(4292, 1112, 'See Also', 'See_Also', 'Mission structures , for more information on mission structures in general.', '<ul><li><a href=\"/index.php/Category:Mission_structures\" title=\"Category:Mission structures\">Mission structures</a>, for more information on mission structures in general.</li></ul>', 4),
(4293, 1113, 'Notes', 'Notes', 'This formula seems to be implemented differently (or is bugged) for check if tile can be sown on.', '<ul><li>This formula seems to be implemented differently (or is bugged) for check if tile can be sown on.</li></ul>', 0),
(4294, 1113, 'See also', 'See_also', 'Slope Farming', '<ul><li><a href=\"/index.php/Slope\" title=\"Slope\">Slope</a></li>\n<li><a href=\"/index.php/Farming\" title=\"Farming\">Farming</a></li></ul>', 1),
(4396, 1139, 'Description', 'Description', 'An unfinished smelting pot that could be hardened by fire. It could be improved with a clay.', '<p><i>An unfinished smelting pot that could be hardened by fire. It could be improved with a clay.</i>\n</p>', 0),
(4397, 1139, 'Usage', 'Usage', 'Place into a campfire , oven , forge or kiln to turn it into a usable pottery smelting pot .', '<ul><li>Place into a <a href=\"/index.php/Campfire\" title=\"Campfire\">campfire</a>, <a href=\"/index.php/Oven\" title=\"Oven\">oven</a>, <a href=\"/index.php/Forge\" title=\"Forge\">forge</a> or <a href=\"/index.php/Kiln\" title=\"Kiln\">kiln</a> to turn it into a usable <a class=\"mw-redirect\" href=\"/index.php/Pottery_smelting_pot\" title=\"Pottery smelting pot\">pottery smelting pot</a>.</li></ul>', 1),
(4398, 1139, 'Notes', 'Notes', 'Once hardened into a pottery smelting pot, it can no longer be improved. The quality of the resulting lump is capped by the quality of the smelting pot, but is otherwise equal to the item that was smelted. There are no known size limitations for items the smelter can smelt. The item only need be metal, not enchanted, and able to be heated to a glowing hot temperature state. The \"\'Smelt\'\" action is not available if the item is not glowing from heat. Smelting a rare or better metal item will produce a corresponding rare or better lump. A small amount of metal from the original item is typically lost to the smelting process. Items that cannot be improved and are not capped by the 20% of total skill when created will now receive a quality penalty when smelted, at the following rates: -7.5% to -2.5% for common metals, -12.5% to -7.5% for moon metals and alloys.', '<ul><li>Once hardened into a pottery smelting pot, it can no longer be improved.</li>\n<li>The quality of the resulting lump is capped by the quality of the smelting pot, but is otherwise equal to the item that was smelted.</li>\n<li>There are no known size limitations for items the smelter can smelt. The item only need be metal, not enchanted, and able to be heated to a glowing hot temperature state.</li>\n<li>The \"\'Smelt\'\" action is not available if the item is not glowing from heat.</li>\n<li>Smelting a rare or better metal item will produce a corresponding rare or better lump.</li>\n<li>A small amount of metal from the original item is typically lost to the smelting process.</li>\n<li>Items that cannot be improved and are not capped by the 20% of total skill when created will now receive a quality penalty when smelted, at the following rates: -7.5% to -2.5% for common metals, -12.5% to -7.5% for moon metals and alloys.</li></ul>', 2),
(4399, 1139, 'Cannot Be Smelted', 'Cannot_Be_Smelted', 'Locks and keys Enchanted Items Runed items', '<ul><li><a href=\"/index.php/Lock\" title=\"Lock\">Locks</a> and <a href=\"/index.php/Key\" title=\"Key\">keys</a></li>\n<li>Enchanted Items</li>\n<li>Runed items</li></ul>', 3),
(4400, 1139, 'See Also', 'See_Also', 'Clay bowl Clay flask Clay jar', '<ul><li><a href=\"/index.php/Clay_bowl\" title=\"Clay bowl\">Clay bowl</a></li>\n<li><a href=\"/index.php/Clay_flask\" title=\"Clay flask\">Clay flask</a></li>\n<li><a href=\"/index.php/Clay_jar\" title=\"Clay jar\">Clay jar</a></li></ul>', 4),
(4401, 1140, 'Description', 'Description', 'A clay brick that could be hardened by fire.', '<p><i>A clay brick that could be hardened by fire.</i>\n</p>', 0),
(4402, 1140, 'Usage', 'Usage', 'Heat to glowing hot to harden it into a pottery brick .', '<ul><li>Heat to glowing hot to harden it into a <a href=\"/index.php/Pottery_brick\" title=\"Pottery brick\">pottery brick</a>.</li></ul>', 1),
(4403, 1140, 'See Also', 'See_Also', 'Clay smelting pot', '<ul><li><a href=\"/index.php/Clay_smelting_pot\" title=\"Clay smelting pot\">Clay smelting pot</a></li></ul>', 2),
(4412, 1146, 'Description', 'Description', 'It is a normal floor made of wood.', '<p><i>It is a normal floor made of wood.</i>\n</p>', 0),
(4413, 1146, 'Notes', 'Notes', 'Must have 1 small nails and 1 plank in inventory to start. Can be repaired and improved with a plank. Can be removed with a carving knife in one action using \"destroy floor\" on deed. Outdoor wooden plank floors do not amass collectable snow during the Wurm winter.', '<ul><li>Must have 1 small nails and 1 plank in inventory to start.</li>\n<li>Can be repaired and improved with a plank.</li>\n<li>Can be removed with a carving knife in one action using \"destroy floor\" on deed.</li>\n<li>Outdoor wooden plank floors do not amass collectable snow during the Wurm winter.</li></ul>', 1),
(4414, 1146, 'See also', 'See_also', 'Wooden plank opening', '<ul><li><a href=\"/index.php/Wooden_plank_opening\" title=\"Wooden plank opening\">Wooden plank opening</a></li></ul>', 2),
(4415, 1147, 'Description', 'Description', 'Floor plan to create pottery brick floors for your buildings.', '<p>Floor plan to create pottery brick floors for your buildings.\n</p>', 0),
(4416, 1147, 'Usage', 'Usage', 'Right click the floor of the house, select Floor below to create a floor plan Activate a trowel , right click The floor plan, select Build and Pottery brick floor', '<ul><li>Right click the floor of the house, select <i>Floor below</i> to create a floor plan</li>\n<li>Activate a <a href=\"/index.php/Trowel\" title=\"Trowel\">trowel</a>, right click The floor plan, select <i>Build</i> and <i>Pottery brick floor</i></li></ul>', 1),
(4417, 1147, 'Notes', 'Notes', 'Must have 1 mortar and pottery brick in inventory to start. Requires 25 paving skill to start. Use clay to repair or improve a pottery brick floor.', '<ul><li>Must have 1 mortar and pottery brick in inventory to start.</li>\n<li>Requires 25 paving skill to start.</li>\n<li>Use clay to repair or improve a pottery brick floor.</li></ul>', 2),
(4418, 1148, 'Description', 'Description', 'Floor plan to create stone brick floors for your buildings.', '<p>Floor plan to create stone brick floors for your buildings.\n</p>', 0),
(4419, 1148, 'Usage', 'Usage', 'Right click the floor of the house, select Floor below to create a floor plan Right click The floor plan, select Build and Stone brick floor', '<ul><li>Right click the floor of the house, select <i>Floor below</i> to create a floor plan</li>\n<li>Right click The floor plan, select <i>Build</i> and <i>Stone brick floor</i></li></ul>', 1),
(4420, 1148, 'Notes', 'Notes', 'Must have one mortar and one stone brick in inventory to start, these materials are not consumed at this time. Requires 21 paving skill to start. Can be repaired and improved with stone bricks.', '<ul><li>Must have one mortar and one stone brick in inventory to start, these materials are not consumed at this time.</li>\n<li>Requires 21 paving skill to start.</li>\n<li>Can be repaired and improved with stone bricks.</li></ul>', 2),
(4427, 1151, 'Description', 'Description', 'You see a crude wooden fence. A crude wooden fence is a less sophisticated looking version of a wooden fence , but it uses the same materials. It also seems to be just as strong as the normal wooden fence, receiving around 5-10 damage per hit with a Huge Axe', '<p><i>You see a crude wooden fence.</i>\n</p>\n<p>A <b>crude wooden fence</b> is a less sophisticated looking version of a <a href=\"/index.php/Wooden_fence\" title=\"Wooden fence\">wooden fence</a>, but it uses the same materials. It also seems to be just as strong as the normal wooden fence, receiving around 5-10 damage per hit with a <a class=\"mw-redirect\" href=\"/index.php/Huge_Axe\" title=\"Huge Axe\">Huge Axe</a>\n</p>', 0),
(4428, 1151, 'Total Materials needed for creation', 'Total_Materials_needed_for_creation', '2 planks 2 shafts 1 small nails', '<ul><li>2 <a href=\"/index.php/Plank\" title=\"Plank\">planks</a></li>\n<li>2 <a href=\"/index.php/Shaft\" title=\"Shaft\">shafts</a></li>\n<li>1 <a href=\"/index.php/Small_nails\" title=\"Small nails\">small nails</a></li></ul>', 1),
(4429, 1151, 'Skill Required', 'Skill_Required', 'To calculate the maximum slope you can build on, based on your carpentry or masonry skill, use the following formula submitted by Ketza : Max slope = (3 * √ skill) + 10 Skill Max Slope 6 17 8 18 9 19 12 20 14 21 16 22 19 23 22 24 25 25 29 26 33 27 36 28 41 29 45 30 49 31 54 32 59 33 64 34 70 35 75 36 81 37 88 38 94 39 Note: Maximum slope is rounded down', '<p>To calculate the <a href=\"/index.php/Maximum_slope\" title=\"Maximum slope\">maximum slope</a> you can build on, based on your <a href=\"/index.php/Carpentry\" title=\"Carpentry\">carpentry</a> or <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill, use the following formula submitted by <a href=\"/index.php/Player:Ketza\" title=\"Player:Ketza\">Ketza</a>:\n</p>\n<p><i>Max slope = (3 *</i> √<i>skill) + 10</i>\n</p>\n<table class=\"wikitable\" style=\"text-align: center;\">\n<tbody><tr>\n<th width=\"100\">Skill\n</th>\n<th width=\"100\">Max Slope\n</th></tr>\n<tr>\n<td>6</td>\n<td>17\n</td></tr>\n<tr>\n<td>8</td>\n<td>18\n</td></tr>\n<tr>\n<td>9</td>\n<td>19\n</td></tr>\n<tr>\n<td>12</td>\n<td>20\n</td></tr>\n<tr>\n<td>14</td>\n<td>21\n</td></tr>\n<tr>\n<td>16</td>\n<td>22\n</td></tr>\n<tr>\n<td>19</td>\n<td>23\n</td></tr>\n<tr>\n<td>22</td>\n<td>24\n</td></tr>\n<tr>\n<td>25</td>\n<td>25\n</td></tr>\n<tr>\n<td>29</td>\n<td>26\n</td></tr>\n<tr>\n<td>33</td>\n<td>27\n</td></tr>\n<tr>\n<td>36</td>\n<td>28\n</td></tr>\n<tr>\n<td>41</td>\n<td>29\n</td></tr>\n<tr>\n<td>45</td>\n<td>30\n</td></tr>\n<tr>\n<td>49</td>\n<td>31\n</td></tr>\n<tr>\n<td>54</td>\n<td>32\n</td></tr>\n<tr>\n<td>59</td>\n<td>33\n</td></tr>\n<tr>\n<td>64</td>\n<td>34\n</td></tr>\n<tr>\n<td>70</td>\n<td>35\n</td></tr>\n<tr>\n<td>75</td>\n<td>36\n</td></tr>\n<tr>\n<td>81</td>\n<td>37\n</td></tr>\n<tr>\n<td>88</td>\n<td>38\n</td></tr>\n<tr>\n<td>94</td>\n<td>39\n</td></tr></tbody></table>\n<p><b>Note:</b> Maximum slope is rounded <i>down</i>\n</p>\n<p><br/>\n</p>', 2),
(4430, 1151, 'See also', 'See_also', 'Crude wooden fence gate', '<ul><li><a href=\"/index.php/Crude_wooden_fence_gate\" title=\"Crude wooden fence gate\">Crude wooden fence gate</a></li></ul>', 3),
(4431, 1152, 'Description', 'Description', 'It is a normal floor made of stone slab. Floor plan to create stone slab floors for your buildings.', '<p><i>It is a normal floor made of stone slab.</i>\n</p>\n<p>Floor plan to create stone slab floors for your buildings.\n</p>', 0),
(4432, 1152, 'Usage', 'Usage', 'Right-click the floor of the house, select Floor below to create a floor plan Right-click the floor plan, select Build and \'Stone slab floor\'', '<ul><li>Right-click the floor of the house, select <i>Floor below</i> to create a floor plan</li>\n<li>Right-click the floor plan, select <i>Build</i> and \'Stone slab floor\'</li></ul>', 1),
(4433, 1152, 'Notes', 'Notes', '21 paving skill is required to create the stone slab floor. Must have 1 slab and mortar in inventory to start. Can be repaired and improved with a stone brick . Higher skill level is required to build at higher floor levels. (see multi-storey housing)', '<ul><li>21 paving skill is required to create the stone slab floor.</li>\n<li>Must have 1 slab and mortar in inventory to start.</li>\n<li>Can be repaired and improved with a <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">stone brick</a>.</li>\n<li>Higher skill level is required to build at higher floor levels. (see multi-storey housing)</li></ul>', 2),
(4455, 1162, 'Description', 'Description', 'A sheaf of grass stems, aligned together and of similar length.', '<p><i>A sheaf of grass stems, aligned together and of similar length.</i>\n</p>', 0),
(4456, 1162, 'Notes', 'Notes', 'Used in the creation of thatched roof . Can be planted on a cultivated dirt tile to create a grass tile . Grass tiles planted using thatch are the only plantable tiles that may be planted indoors. Failure to make a thatch using .05 of mixed grass or reeds results in too little raw materials for a second try.  This is due to round-off; combining two such raw materials that one failed with results in .09 raw material. Combined mixed grass of greater than .05 will only use the required .05 per thatch created, so loss only occurs upon failure. The maximum thatch quality is the quality of the mixed grass used, with exception of using a rare or greater leggat, which increases the maximum quality that is possible. Pile of thatch', '<ul><li>Used in the creation of <a href=\"/index.php/Thatched_roof\" title=\"Thatched roof\">thatched roof</a>.</li>\n<li>Can be planted on a cultivated <a href=\"/index.php/Dirt_tile\" title=\"Dirt tile\">dirt tile</a> to create a <a href=\"/index.php/Grass_tile\" title=\"Grass tile\">grass tile</a>.</li>\n<li>Grass tiles planted using thatch are the only plantable tiles that may be planted indoors.</li>\n<li>Failure to make a thatch using .05 of mixed grass or reeds results in too little raw materials for a second try.  This is due to round-off; combining two such raw materials that one failed with results in .09 raw material.</li>\n<li>Combined mixed grass of greater than .05 will only use the required .05 per thatch created, so loss only occurs upon failure.</li>\n<li>The maximum thatch <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\"> quality</a> is the quality of the mixed grass used, with exception of using a <a href=\"/index.php/Rarity_system\" title=\"Rarity system\">rare</a> or greater leggat, which increases the maximum quality that is possible.</li></ul>\n<div class=\"thumb tleft\"><div class=\"thumbinner\" style=\"width:252px;\"><a class=\"image\" href=\"/index.php/File:Pile_of_thatch.png\"><img alt=\"\" class=\"thumbimage\" data-file-height=\"404\" data-file-width=\"306\" decoding=\"async\" height=\"330\" src=\"/images/thumb/9/95/Pile_of_thatch.png/250px-Pile_of_thatch.png\" srcset=\"/images/9/95/Pile_of_thatch.png 1.5x\" width=\"250\"/></a> <div class=\"thumbcaption\"><div class=\"magnify\"><a class=\"internal\" href=\"/index.php/File:Pile_of_thatch.png\" title=\"Enlarge\"></a></div>Pile of thatch</div></div></div>', 1),
(4461, 1156, 'Description', 'Description', 'It is a normal roof made of slate shingles.', '<p><i>It is a normal roof made of slate shingles.</i>\n</p>', 0),
(4462, 1156, 'Notes', 'Notes', 'Requires 30 masonry skill to build Can be repaired and improved with slate shards. Gives Paving skill upon repair.', '<ul><li>Requires 30 <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill to build</li>\n<li>Can be repaired and improved with slate shards.</li>\n<li>Gives <a href=\"/index.php/Paving\" title=\"Paving\">Paving</a> skill upon repair.</li></ul>', 1),
(4463, 1159, 'Description', 'Description', 'Slate chiselled into a flat shingle. Chiselled from a slate shard into a shingle.', '<p><i>Slate chiselled into a flat shingle.</i>\n</p>\n<p>Chiselled from a <a class=\"mw-redirect\" href=\"/index.php/Slate_shard\" title=\"Slate shard\">slate shard</a> into a shingle.\n</p>', 0),
(4464, 1159, 'Usage', 'Usage', 'Slate shingle roof', '<ul><li><a href=\"/index.php/Slate_shingle_roof\" title=\"Slate shingle roof\">Slate shingle roof</a></li></ul>', 1),
(4465, 1160, 'Description', 'Description', 'A flat and square slate slab made from shingles. It is about your length and width.', '<p><i>A flat and square slate slab made from shingles. It is about your length and width.</i>\n</p>', 0),
(4466, 1160, 'Usage', 'Usage', 'Slate slab floor Slate slabs pavement', '<ul><li><a href=\"/index.php/Slate_slab_floor\" title=\"Slate slab floor\">Slate slab floor</a></li>\n<li><a href=\"/index.php/Slate_slabs\" title=\"Slate slabs\">Slate slabs</a> <a class=\"mw-redirect\" href=\"/index.php/Pavement\" title=\"Pavement\">pavement</a></li></ul>', 1),
(4467, 1158, 'Description', 'Description', 'It is a normal roof made of thatch. A thatched roof for a building.', '<p><i>It is a normal roof made of thatch.</i>\n</p>\n<p>A thatched roof for a building.\n</p>', 0),
(4468, 1158, 'Notes', 'Notes', 'Requires 21 thatching skill to build. Can be repaired and improved with planks. A roof located on top of the 1st story of a building, otherwise called the 1st-floor roof, is technically built on the 2nd story and so the chart below reflects this for accuracy. (Example:  a 1-story building has a roof, and that roof is located above the 1st floor as the 2nd story)', '<ul><li>Requires 21 thatching skill to build.</li>\n<li>Can be repaired and improved with planks.</li>\n<li>A roof located on top of the 1st story of a building, otherwise called the 1st-floor roof, is technically built on the 2nd story and so the chart below reflects this for accuracy. (Example:  a 1-story building has a roof, and that roof is located above the 1st floor as the 2nd story)</li></ul>', 1),
(4469, 1158, 'Skill Requirements', 'Skill_Requirements', 'This section is a work in progress through recent experimentation. Please note the chart begins with the 2nd floor because the roof on top of the 1st floor is technically located on the 2nd floor. Floor Thatching 2nd 21 3rd 22 4th 30 5th 40 6th 47 Floor Thatching 7th ? 8th ? 9th ? 10th ? 11th ? Floor Thatching 12th ? 13th ? 14th ? 15th ? 16th ?', '<p><i>This section is a work in progress through recent experimentation.</i>\n<i>Please note the chart begins with the 2nd floor because the roof on top of the 1st floor is technically located on the 2nd floor.</i>\n</p>\n<p><br/>\n</p>\n<table width=\"40%\">\n<tbody><tr>\n<th style=\"width: 33%;\">\n</th>\n<th style=\"width: 33%;\">\n</th>\n<th style=\"width: 33%;\">\n</th></tr>\n<tr>\n<td style=\"padding: 5px;\">\n<table align=\"left\" class=\"wikitable\">\n<tbody><tr>\n<th>Floor</th>\n<th><a href=\"/index.php/Thatching\" title=\"Thatching\">Thatching</a>\n</th></tr>\n<tr>\n<td>2nd</td>\n<td>21\n</td></tr>\n<tr>\n<td>3rd</td>\n<td>22\n</td></tr>\n<tr>\n<td>4th</td>\n<td>30\n</td></tr>\n<tr>\n<td>5th</td>\n<td>40\n</td></tr>\n<tr>\n<td>6th</td>\n<td>47\n</td></tr>\n</tbody></table>\n</td>\n<td style=\"padding: 5px;\">\n<table align=\"center\" class=\"wikitable\">\n<tbody><tr>\n<th>Floor</th>\n<th><a href=\"/index.php/Thatching\" title=\"Thatching\">Thatching</a>\n</th></tr>\n<tr>\n<td>7th</td>\n<td>?\n</td></tr>\n<tr>\n<td>8th</td>\n<td>?\n</td></tr>\n<tr>\n<td>9th</td>\n<td>?\n</td></tr>\n<tr>\n<td>10th</td>\n<td>?\n</td></tr>\n<tr>\n<td>11th</td>\n<td>?\n</td></tr>\n</tbody></table>\n</td>\n<td style=\"padding: 5px;\">\n<table class=\"wikitable\">\n<tbody><tr>\n<th>Floor</th>\n<th><a href=\"/index.php/Thatching\" title=\"Thatching\">Thatching</a>\n</th></tr>\n<tr>\n<td>12th</td>\n<td>?\n</td></tr>\n<tr>\n<td>13th</td>\n<td>?\n</td></tr>\n<tr>\n<td>14th</td>\n<td>?\n</td></tr>\n<tr>\n<td>15th</td>\n<td>?\n</td></tr>\n<tr>\n<td>16th</td>\n<td>?\n</td></tr></tbody></table>\n</td></tr></tbody></table>', 2),
(4470, 1154, 'Description', 'Description', 'It is a normal roof made of wood shingles. A roof made of wooden shingles for houses .', '<p><i>It is a normal roof made of wood shingles.</i>\n</p>\n<p>A roof made of <a href=\"/index.php/Wood_shingle\" title=\"Wood shingle\">wooden shingles</a> for <a href=\"/index.php/House\" title=\"House\">houses</a>.\n</p>', 0),
(4471, 1154, 'Notes', 'Notes', 'A minimum carpentry level of 5 is required to begin the roof on a one story building. Uses planks for repairing and improving.', '<ul><li>A minimum <a href=\"/index.php/Carpentry\" title=\"Carpentry\">carpentry</a> level of 5 is required to begin the roof on a one story building.</li>\n<li>Uses <a href=\"/index.php/Plank\" title=\"Plank\">planks</a> for repairing and improving.</li></ul>', 1),
(4472, 1144, 'Description', 'Description', 'Wood carved into a flat shingle. Carved from a plank into a shingle.', '<p><i>Wood carved into a flat shingle.</i>\n</p>\n<p>Carved from a <a href=\"/index.php/Plank\" title=\"Plank\">plank</a> into a shingle.\n</p>', 0),
(4473, 1144, 'Usage', 'Usage', 'Used for making a Wood shingle roof . Also used in constructing a Tackle box , a Stamp box , and a Squared wood ceiling .', '<p>Used for making a <a href=\"/index.php/Wood_shingle_roof\" title=\"Wood shingle roof\">Wood shingle roof</a>.<br/>\nAlso used in constructing a <a href=\"/index.php/Tackle_box\" title=\"Tackle box\">Tackle box</a>, a <a href=\"/index.php/Stamp_box\" title=\"Stamp box\">Stamp box</a>, and a <a href=\"/index.php/Squared_wood_ceiling\" title=\"Squared wood ceiling\">Squared wood ceiling</a>.\n</p>', 1),
(4474, 1157, 'Description', 'Description', 'It is a normal roof made of pottery shingles. A terracotta pottery style building roof.', '<p><i>It is a normal roof made of pottery shingles.</i>\n</p>\n<p>A terracotta pottery style building roof.\n</p>', 0),
(4475, 1157, 'Notes', 'Notes', '25 masonry is required to begin a pottery shingle roof. 25 Masonry is required to begin a second-story pottery shingle roof. Can be repaired and improved with clay. Paving skill used for improving.', '<ul><li>25 masonry is required to begin a pottery shingle roof.</li>\n<li>25 Masonry is required to begin a second-story pottery shingle roof.</li>\n<li>Can be repaired and improved with clay.</li>\n<li>Paving skill used for improving.</li></ul>\n<p><br/>\n</p>', 1),
(4476, 1157, 'Other views', 'Other_views', '', '<p><a class=\"image\" href=\"/index.php/File:Pottery_shingle_roof-inside.png\"><img alt=\"Pottery shingle roof-inside.png\" data-file-height=\"150\" data-file-width=\"200\" decoding=\"async\" height=\"150\" src=\"/images/5/54/Pottery_shingle_roof-inside.png\" width=\"200\"/></a>\n</p>', 2),
(4477, 1161, 'Description', 'Description', 'A pottery shingle hardened by fire. The clay shingle can be heated in any fire . When it reaches glowing hot it turns into a pottery shingle.', '<p><i>A pottery shingle hardened by fire.</i>\n</p>\n<p>The clay shingle can be heated in any <a href=\"/index.php/Category:Fire_sources\" title=\"Category:Fire sources\">fire</a>. When it reaches glowing hot it turns into a pottery shingle.\n</p>', 0),
(4478, 1161, 'Usage', 'Usage', 'Pottery shingle roof', '<ul><li><a href=\"/index.php/Pottery_shingle_roof\" title=\"Pottery shingle roof\">Pottery shingle roof</a></li></ul>', 1),
(4479, 1142, 'Description', 'Description', 'Clay shaped into a flat shingle.', '<p><i>Clay shaped into a flat shingle.</i>\n</p>', 0),
(4480, 1142, 'Usage', 'Usage', 'Heat to glowing hot to harden it into a pottery shingle . They can be fired in a campfire , oven , forge , or kiln .', '<ul><li>Heat to glowing hot to harden it into a <a href=\"/index.php/Pottery_shingle\" title=\"Pottery shingle\">pottery shingle</a>. They can be fired in a <a href=\"/index.php/Campfire\" title=\"Campfire\">campfire</a>, <a href=\"/index.php/Oven\" title=\"Oven\">oven</a>, <a href=\"/index.php/Forge\" title=\"Forge\">forge</a>, or <a href=\"/index.php/Kiln\" title=\"Kiln\">kiln</a>.</li></ul>', 1),
(4483, 1174, 'Description', 'Description', 'You see a strong stone parapet.', '<p><i>You see a strong stone parapet. </i>\n</p>', 0),
(4484, 1174, 'Skill required', 'Skill_required', 'To calculate the maximum slope you can build on, based on your carpentry or masonry skill, use the following formula submitted by Ketza : Max slope = (3 * √ skill) + 10 Skill Max Slope 6 17 8 18 9 19 12 20 14 21 16 22 19 23 22 24 25 25 29 26 33 27 36 28 41 29 45 30 49 31 54 32 59 33 64 34 70 35 75 36 81 37 88 38 94 39 Note: Maximum slope is rounded down', '<p>To calculate the <a href=\"/index.php/Maximum_slope\" title=\"Maximum slope\">maximum slope</a> you can build on, based on your <a href=\"/index.php/Carpentry\" title=\"Carpentry\">carpentry</a> or <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill, use the following formula submitted by <a href=\"/index.php/Player:Ketza\" title=\"Player:Ketza\">Ketza</a>:\n</p>\n<p><i>Max slope = (3 *</i> √<i>skill) + 10</i>\n</p>\n<table class=\"wikitable\" style=\"text-align: center;\">\n<tbody><tr>\n<th width=\"100\">Skill\n</th>\n<th width=\"100\">Max Slope\n</th></tr>\n<tr>\n<td>6</td>\n<td>17\n</td></tr>\n<tr>\n<td>8</td>\n<td>18\n</td></tr>\n<tr>\n<td>9</td>\n<td>19\n</td></tr>\n<tr>\n<td>12</td>\n<td>20\n</td></tr>\n<tr>\n<td>14</td>\n<td>21\n</td></tr>\n<tr>\n<td>16</td>\n<td>22\n</td></tr>\n<tr>\n<td>19</td>\n<td>23\n</td></tr>\n<tr>\n<td>22</td>\n<td>24\n</td></tr>\n<tr>\n<td>25</td>\n<td>25\n</td></tr>\n<tr>\n<td>29</td>\n<td>26\n</td></tr>\n<tr>\n<td>33</td>\n<td>27\n</td></tr>\n<tr>\n<td>36</td>\n<td>28\n</td></tr>\n<tr>\n<td>41</td>\n<td>29\n</td></tr>\n<tr>\n<td>45</td>\n<td>30\n</td></tr>\n<tr>\n<td>49</td>\n<td>31\n</td></tr>\n<tr>\n<td>54</td>\n<td>32\n</td></tr>\n<tr>\n<td>59</td>\n<td>33\n</td></tr>\n<tr>\n<td>64</td>\n<td>34\n</td></tr>\n<tr>\n<td>70</td>\n<td>35\n</td></tr>\n<tr>\n<td>75</td>\n<td>36\n</td></tr>\n<tr>\n<td>81</td>\n<td>37\n</td></tr>\n<tr>\n<td>88</td>\n<td>38\n</td></tr>\n<tr>\n<td>94</td>\n<td>39\n</td></tr></tbody></table>\n<p><b>Note:</b> Maximum slope is rounded <i>down</i>\n</p>\n<p><br/>\n</p>', 1),
(4485, 1174, 'Notes', 'Notes', 'Repair Stone parapet with stone brick. Each stone brick will repair up to 10 damage depending on quality and repairing skill. At 60 damage, cracks will form on the wall. A stone parapet which alternates between the height of a small barrel and a large barrel .  Can easily be seen over by an avatar.  Can only be built on building borders. It is not possible to shoot arrows over either a stone parapet or a wooden parapet while target shooting. However, it works just fine when aiming at a living target.', '<ul><li>Repair Stone parapet with stone brick. Each stone brick will repair up to 10 damage depending on quality and repairing skill.</li>\n<li>At 60 damage, cracks will form on the wall.</li></ul>\n<p><br/>\n</p>\n<p><br/>\n</p>\n<ul><li>A stone parapet which alternates between the height of a <a href=\"/index.php/Small_barrel\" title=\"Small barrel\">small barrel</a> and a <a href=\"/index.php/Large_barrel\" title=\"Large barrel\">large barrel</a>.  Can easily be seen over by an avatar.  Can only be built on building borders. It is not possible to shoot arrows over either a stone parapet or a <a href=\"/index.php/Wooden_parapet\" title=\"Wooden parapet\">wooden parapet</a> while target shooting. However, it works just fine when aiming at a living target.</li></ul>\n<p><br/>\n</p>', 2),
(4486, 1174, 'See also', 'See_also', 'Fences Fence gates Empirical Evaluation of Fences', '<ul><li><a href=\"/index.php/Category:Fences\" title=\"Category:Fences\">Fences</a></li>\n<li><a href=\"/index.php/Category:Gates\" title=\"Category:Gates\">Fence gates</a></li></ul>\n<ul><li><a href=\"/index.php/Empirical_Evaluation_of_Fences\" title=\"Empirical Evaluation of Fences\">Empirical Evaluation of Fences</a></li></ul>', 3),
(4487, 1175, 'Description', 'Description', 'You see a strong parapet made of stone and iron. This stone and iron parapet is nearly identical to the iron fence . It is about 75% the size of the iron fence. The top of the stone part is just below shoulder height.', '<p><i>You see a strong parapet made of stone and iron.</i>\n</p>\n<p>This stone and iron parapet is nearly identical to the <a href=\"/index.php/Iron_fence\" title=\"Iron fence\">iron fence</a>. It is about 75% the size of the iron fence. The top of the stone part is just below shoulder height.\n</p>', 0),
(4488, 1175, 'Notes', 'Notes', 'Repair stone and iron parapet with a stone brick. Each stone brick will repair up to 10 damage depending on quality and repairing skill.', '<ul><li>Repair stone and iron parapet with a stone brick. Each stone brick will repair up to 10 damage depending on quality and repairing skill.</li></ul>', 1),
(4489, 1175, 'See also', 'See_also', 'Fences Empirical Evaluation of Fences', '<ul><li><a href=\"/index.php/Category:Fences\" title=\"Category:Fences\">Fences</a></li>\n<li><a href=\"/index.php/Empirical_Evaluation_of_Fences\" title=\"Empirical Evaluation of Fences\">Empirical Evaluation of Fences</a></li></ul>', 2),
(4490, 1143, 'Description', 'Description', 'A clay brick hardened by fire.', '<p><i>A clay brick hardened by fire.</i>\n</p>', 0),
(4491, 1143, 'Usage', 'Usage', 'Pottery bricks can be used to create a wide variety of walls, floors, and structures as well as to pave roads.', '<ul><li>Pottery bricks can be used to create a wide variety of walls, floors, and structures as well as to pave roads.</li></ul>', 1),
(4492, 1143, 'Notes', 'Notes', 'Clay bricks must bake in a campfire , kiln , oven , or forge until they turn into pottery bricks. This may take some time.', '<ul><li><a href=\"/index.php/Clay_brick\" title=\"Clay brick\">Clay bricks</a> must bake in a <a href=\"/index.php/Campfire\" title=\"Campfire\">campfire</a>, <a href=\"/index.php/Kiln\" title=\"Kiln\">kiln</a>, <a href=\"/index.php/Oven\" title=\"Oven\">oven</a>, or <a href=\"/index.php/Forge\" title=\"Forge\">forge</a> until they turn into pottery bricks. This may take some time.</li></ul>', 2),
(4493, 1143, 'See Also', 'See_Also', 'Paving Pottery', '<ul><li><a href=\"/index.php/Paving\" title=\"Paving\">Paving</a></li>\n<li><a href=\"/index.php/Pottery\" title=\"Pottery\">Pottery</a></li></ul>', 3),
(4566, 1189, 'Images', 'Images', 'House floor types, from left to right: Top row: Wooden plank floor , Stone brick floor , Stone slab floor , Pottery brick floor Bottom row: Marble slab floor , Slate slab floor , Sandstone slab floor , Unfinished floor plan', '<p>House floor types, from left to right: <br/>\nTop row: <a href=\"/index.php/Wooden_plank_floor\" title=\"Wooden plank floor\">Wooden plank floor</a>, <a href=\"/index.php/Stone_brick_floor\" title=\"Stone brick floor\">Stone brick floor</a>, <a href=\"/index.php/Stone_slab_floor\" title=\"Stone slab floor\">Stone slab floor</a>, <a href=\"/index.php/Pottery_brick_floor\" title=\"Pottery brick floor\">Pottery brick floor</a> <br/>\nBottom row: <a href=\"/index.php/Marble_slab_floor\" title=\"Marble slab floor\">Marble slab floor</a>, <a href=\"/index.php/Slate_slab_floor\" title=\"Slate slab floor\">Slate slab floor</a>, <a href=\"/index.php/Sandstone_slab_floor\" title=\"Sandstone slab floor\">Sandstone slab floor</a>, Unfinished floor plan\n</p>\n<p><a class=\"image\" href=\"/index.php/File:House_floor_types.jpg\" title=\"All seven types of house floor styles and unfinished floor in comparison.\"><img alt=\"All seven types of house floor styles and unfinished floor in comparison.\" data-file-height=\"938\" data-file-width=\"1240\" decoding=\"async\" height=\"469\" src=\"/images/thumb/2/2a/House_floor_types.jpg/620px-House_floor_types.jpg\" srcset=\"/images/thumb/2/2a/House_floor_types.jpg/930px-House_floor_types.jpg 1.5x, /images/2/2a/House_floor_types.jpg 2x\" width=\"620\"/></a>\n</p>', 0),
(4567, 1190, 'Description', 'Description', 'Thatching is the layering of dry vegetation such as reed or mixed grass.', '<p>Thatching is the layering of dry vegetation such as reed or mixed grass.\n</p>', 0),
(4568, 1190, 'Usage', 'Usage', 'Creating a thatched roof on top of buildings. Bundling hay into hay bundles or hay stacks for animals to eat from. Creating grass tiles outside and in buildings. When creating a grass tile, you would plant thatch in a cultivated dirt tile just like you would a flower or mixed grass.', '<ul><li>Creating a <a href=\"/index.php/Thatched_roof\" title=\"Thatched roof\">thatched roof</a> on top of buildings.</li>\n<li>Bundling <a href=\"/index.php/Hay\" title=\"Hay\">hay</a> into <a class=\"mw-redirect\" href=\"/index.php/Hay_bundles\" title=\"Hay bundles\">hay bundles</a> or <a class=\"mw-redirect\" href=\"/index.php/Hay_stacks\" title=\"Hay stacks\">hay stacks</a> for animals to eat from.</li>\n<li>Creating <a class=\"mw-redirect\" href=\"/index.php/Grass_tiles\" title=\"Grass tiles\">grass tiles</a> outside and in buildings.</li>\n<li>When creating a grass tile, you would plant <a href=\"/index.php/Thatch\" title=\"Thatch\">thatch</a> in a cultivated <a href=\"/index.php/Dirt_tile\" title=\"Dirt tile\">dirt tile</a> just like you would a flower or mixed grass.</li></ul>', 1),
(4569, 1190, 'Items required', 'Items_required', 'Reed OR Mixed grass Wire (for making a thatched roof) String for bundling hay.', '<dl><dd><ul><li><a href=\"/index.php/Reed\" title=\"Reed\">Reed</a> <b>OR</b> <a href=\"/index.php/Mixed_grass\" title=\"Mixed grass\">Mixed grass</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Wire\" title=\"Wire\">Wire</a> (for making a thatched roof)</li>\n<li><a href=\"/index.php/String_of_cloth\" title=\"String of cloth\">String</a> for bundling hay.</li></ul></dd></dl>', 2),
(4570, 1190, 'Tools required', 'Tools_required', 'Leggat Pitchfork', '<dl><dd><ul><li><a href=\"/index.php/Leggat\" title=\"Leggat\">Leggat</a></li>\n<li><a href=\"/index.php/Pitchfork\" title=\"Pitchfork\">Pitchfork</a></li></ul></dd></dl>', 3),
(4571, 1190, 'Products', 'Products', 'Thatch Thatched roof Hay products.', '<dl><dd><ul><li><a href=\"/index.php/Thatch\" title=\"Thatch\">Thatch</a></li>\n<li><a href=\"/index.php/Thatched_roof\" title=\"Thatched roof\">Thatched roof</a></li>\n<li><a href=\"/index.php/Hay\" title=\"Hay\">Hay</a> products.</li></ul></dd></dl>', 4),
(4572, 1190, 'Skills & Characteristics', 'Skills_.26_Characteristics', 'Thatching Body > Body control Mind > Mind logic', '<ul><li>Thatching</li>\n<li><a href=\"/index.php/Body\" title=\"Body\">Body</a> &gt; <a href=\"/index.php/Body_control\" title=\"Body control\">Body control</a></li>\n<li><a href=\"/index.php/Mind\" title=\"Mind\">Mind</a> &gt; <a href=\"/index.php/Mind_logic\" title=\"Mind logic\">Mind logic</a></li></ul>', 5),
(4573, 1190, 'Titles', 'Titles', 'Thatcher at 50 skill Roofer at 70 skill Master Thatcher at 90 skill', '<ul><li>Thatcher at 50 skill</li>\n<li>Roofer at 70 skill</li>\n<li>Master Thatcher at 90 skill</li></ul>', 6),
(4574, 1191, 'Description', 'Description', 'It is a normal opening made of wood.', '<p><i>It is a normal opening made of wood.</i>\n</p>', 0),
(4575, 1191, 'Creation', 'Creation', 'To plan an opening: Activate a hammer , mallet , or trowel and right click the floor of the house, then select Plan and Build Ladder to create a floor plan . To build an opening once planned: Activate a mallet and right click the floor plan, then select Build and Wooden plank opening .', '<ul><li>To plan an opening: <b>Activate</b> a <a href=\"/index.php/Hammer\" title=\"Hammer\">hammer</a>, <a href=\"/index.php/Mallet\" title=\"Mallet\">mallet</a>, or <a href=\"/index.php/Trowel\" title=\"Trowel\">trowel</a> and <b>right click</b> the floor of the house, then select <b>Plan</b> and <b>Build Ladder</b> to create a <a href=\"/index.php/Floor_plan\" title=\"Floor plan\">floor plan</a>.</li>\n<li>To build an opening once planned: <b>Activate</b> a mallet and <b>right click</b> the floor plan, then select <b>Build</b> and <b>Wooden plank opening</b>.</li></ul>', 1),
(4576, 1191, 'Usage', 'Usage', 'Right click the opening its ladder, then select climb to move between floors. By standing on the opening of a floor you can activate a rope and right click certain items to haul them, providing both you and the object are on the same tile, albeit one floor apart. Hauling back down will work in the same way and the item does not need to be empty. You need 21 body strength to haul.', '<ul><li><b>Right click</b> the opening its ladder, then select <b>climb</b> to move between floors.</li>\n<li>By standing on the opening of a floor you can <b>activate</b> a <a href=\"/index.php/Rope\" title=\"Rope\">rope</a> and <b>right click</b> certain items to <b>haul</b> them, providing both you and the object are on the same tile, albeit one floor apart. Hauling back down will work in the same way and the item does not need to be empty. You need 21 body strength to haul.</li></ul>', 2),
(4577, 1191, 'Notes', 'Notes', 'Must have 1 small nails and 1 plank in inventory to start. The ladder graphic is always positioned against the south edge of the opening as default. The ladder can be rotated after completion by right click>rotate clockwise/counterclockwise .', '<ul><li>Must have 1 small nails and 1 plank in inventory to start.</li>\n<li>The ladder graphic is always positioned against the south edge of the opening as default.</li>\n<li>The ladder can be rotated after completion by <i>right click&gt;rotate clockwise/counterclockwise</i>.</li></ul>', 3),
(4578, 1191, 'See Also', 'See_Also', 'Marble slab opening Pottery brick opening Stone brick opening Slate slab opening Stone slab opening', '<ul><li><a href=\"/index.php/Marble_slab_opening\" title=\"Marble slab opening\">Marble slab opening</a></li>\n<li><a href=\"/index.php/Pottery_brick_opening\" title=\"Pottery brick opening\">Pottery brick opening</a></li>\n<li><a href=\"/index.php/Stone_brick_opening\" title=\"Stone brick opening\">Stone brick opening</a></li>\n<li><a href=\"/index.php/Slate_slab_opening\" title=\"Slate slab opening\">Slate slab opening</a></li>\n<li><a href=\"/index.php/Stone_slab_opening\" title=\"Stone slab opening\">Stone slab opening</a></li></ul>', 4),
(4579, 1192, 'Description', 'Description', 'You see a wall.', '<p><i>You see a wall.</i>\n</p>', 0),
(4580, 1192, 'Modifying', 'Modifying', 'Pliers are used for modifying the stone house wall into its plain version, the Plain stone wall . You can turn walls to suit your needs.', '<ul><li><a href=\"/index.php/Pliers\" title=\"Pliers\">Pliers</a> are used for modifying the stone house wall into its plain version, the <a href=\"/index.php/Plain_stone_wall\" title=\"Plain stone wall\">Plain stone wall</a>.</li>\n<li>You can turn walls to suit your needs.</li></ul>', 1),
(4581, 1192, 'Improving', 'Improving', 'You must repair any damage on the walls with a stone brick before improving it. Activate a stone brick, right-click the wall and select Repair or Improve . The effective quality of the stone brick is affected by its damage and your masonry skill, it must be higher than the wall\'s current quality.', '<ul><li>You must <a href=\"/index.php/Repairing\" title=\"Repairing\">repair</a> any <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> on the walls with a <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">stone brick</a> before <a href=\"/index.php/Improve\" title=\"Improve\">improving</a> it.</li>\n<li>Activate a stone brick, right-click the wall and select <i>Repair</i> or <i>Improve</i>.</li>\n<li>The effective <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the stone brick is affected by its damage and your <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill, it must be higher than the wall\'s current quality.</li></ul>', 2),
(4582, 1192, 'See also', 'See_also', 'Plain stone wall Wooden house wall', '<ul><li><a href=\"/index.php/Plain_stone_wall\" title=\"Plain stone wall\">Plain stone wall</a></li>\n<li><a href=\"/index.php/Wooden_house_wall\" title=\"Wooden house wall\">Wooden house wall</a></li></ul>', 3),
(4583, 1193, 'Description', 'Description', 'You see a window', '<p><i>You see a window </i>\n</p>', 0),
(4584, 1193, 'Skill Requirements', 'Skill_Requirements', 'At least 30 masonry skill is required to build stone walls. See multi-story housing for more information regarding skill requirements on additional floors.', '<ul><li>At least 30 <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill is required to build stone walls.</li>\n<li>See <a href=\"/index.php/Multi-story_housing#Skill_needed\" title=\"Multi-story housing\">multi-story housing</a> for more information regarding skill requirements on additional floors.</li></ul>', 1),
(4585, 1193, 'Creation', 'Creation', 'Have at least 1 Stone brick and 1 mortar in your inventory. Activate a trowel and right-click on a wall plan . Select Build and then Stone window . Continuation requires at least 1 Stone brick and 1 mortar in your inventory.', '<ul><li>Have at least 1 <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> and 1 <a href=\"/index.php/Mortar\" title=\"Mortar\">mortar</a> in your inventory.</li>\n<li><b>Activate</b> a <a href=\"/index.php/Trowel\" title=\"Trowel\">trowel</a> and <b>right-click</b> on a <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">wall plan</a>.</li>\n<li>Select <b>Build</b> and then <b>Stone window</b>.</li>\n<li>Continuation requires at least 1 <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> and 1 mortar in your inventory.</li></ul>', 2);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(4586, 1193, 'Modifying', 'Modifying', 'Pliers are used for modifying the wall into its trimless version, the Plain stone window . Activate the tool and right-click the wall, then select Remove Decorations . You can turn walls to suit your needs by right-clicking them, and selecting Rotate wall .', '<ul><li><a href=\"/index.php/Pliers\" title=\"Pliers\">Pliers</a> are used for modifying the wall into its trimless version, the <a href=\"/index.php/Plain_stone_window\" title=\"Plain stone window\">Plain stone window</a>.  <b>Activate</b> the tool and <b>right-click</b> the wall, then select <b>Remove Decorations</b>.</li>\n<li>You can turn walls to suit your needs by <b>right-clicking</b> them, and selecting <b>Rotate wall</b>.</li></ul>', 3),
(4587, 1193, 'Improving', 'Improving', 'You must repair any damage on the walls with a Stone brick before improving it. Activate a Stone brick , right-click the wall and select Repair or Improve . The effective quality of the Stone brick is affected by its damage and your masonry skill, it must be higher than the wall\'s current quality.', '<ul><li>You must <a href=\"/index.php/Repairing\" title=\"Repairing\">repair</a> any <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> on the walls with a <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> before <a href=\"/index.php/Improve\" title=\"Improve\">improving</a> it.</li>\n<li>Activate a <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a>, right-click the wall and select <i>Repair</i> or <i>Improve</i>.</li>\n<li>The effective <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> is affected by its damage and your <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill, it must be higher than the wall\'s current quality.</li></ul>\n<p><br/>\n</p>', 4),
(4588, 1193, 'See also', 'See_also', 'Stone wall Stone door Stone portcullis Stone window Stone oriel Stone double door Stone T arch Stone arch right Stone arch left', '<ul><li><a href=\"/index.php/Stone_wall\" title=\"Stone wall\">Stone wall</a></li>\n<li><a href=\"/index.php/Stone_door\" title=\"Stone door\">Stone door</a></li>\n<li><a href=\"/index.php/Stone_portcullis_(wall)\" title=\"Stone portcullis (wall)\"> Stone portcullis</a></li>\n<li><a class=\"mw-selflink selflink\">Stone window</a></li>\n<li><a href=\"/index.php/Stone_oriel\" title=\"Stone oriel\">Stone oriel</a></li>\n<li><a href=\"/index.php/Stone_double_door\" title=\"Stone double door\">Stone double door</a></li>\n<li><a href=\"/index.php/Stone_T_arch\" title=\"Stone T arch\">Stone T arch</a></li>\n<li><a href=\"/index.php/Stone_arch_right\" title=\"Stone arch right\">Stone arch right</a></li>\n<li><a href=\"/index.php/Stone_arch_left\" title=\"Stone arch left\">Stone arch left</a></li></ul>', 5),
(4589, 1194, 'Description', 'Description', 'A trimmed door for a stone house .', '<p><i>A trimmed door for a stone <a href=\"/index.php/House\" title=\"House\">house</a>. </i>\n</p>', 0),
(4590, 1194, 'Locking', 'Locking', 'It can be locked with a door lock . Any humanoid mob (for example trolls ) or player can pass through an unlocked door.', '<ul><li>It can be locked with a <a href=\"/index.php/Door_lock\" title=\"Door lock\">door lock</a>. Any humanoid mob (for example <a href=\"/index.php/Troll\" title=\"Troll\">trolls</a>) or player can pass through an unlocked door.</li></ul>', 1),
(4591, 1194, 'Skill Requirements', 'Skill_Requirements', 'At least 30 masonry skill is required to build stone walls. See multi-story housing for more information regarding skill requirements on additional floors.', '<ul><li>At least 30 <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill is required to build stone walls.</li>\n<li>See <a href=\"/index.php/Multi-story_housing#Skill_needed\" title=\"Multi-story housing\">multi-story housing</a> for more information regarding skill requirements on additional floors.</li></ul>', 2),
(4592, 1194, 'Creation', 'Creation', 'Have at least 1 stone brick and 1 mortar in your inventory. Activate a trowel and right-click on a wall plan . Select Build and then Stone door . Continuation requires at least 1 stone brick and 1 mortar in your inventory.', '<ul><li>Have at least 1 <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">stone brick</a> and 1 <a href=\"/index.php/Mortar\" title=\"Mortar\">mortar</a> in your inventory.</li>\n<li><b>Activate</b> a <a href=\"/index.php/Trowel\" title=\"Trowel\">trowel</a> and <b>right-click</b> on a <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">wall plan</a>.</li>\n<li>Select <b>Build</b> and then <b>Stone door</b>.</li>\n<li>Continuation requires at least 1 <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">stone brick</a> and 1 mortar in your inventory.</li></ul>', 3),
(4593, 1194, 'Modifying', 'Modifying', 'Pliers are used for modifying the wall into its trimless version, the Plain stone door . Activate the tool and right-click the wall, then select Remove Decorations . You can turn walls to suit your needs by right-clicking them, and selecting Rotate wall .', '<ul><li><a href=\"/index.php/Pliers\" title=\"Pliers\">Pliers</a> are used for modifying the wall into its trimless version, the <a href=\"/index.php/Plain_stone_door\" title=\"Plain stone door\">Plain stone door</a>.  <b>Activate</b> the tool and <b>right-click</b> the wall, then select <b>Remove Decorations</b>.</li>\n<li>You can turn walls to suit your needs by <b>right-clicking</b> them, and selecting <b>Rotate wall</b>.</li></ul>', 4),
(4594, 1194, 'Improving', 'Improving', 'You must repair any damage on the walls with a stone brick before improving it. Activate a stone brick , right-click the wall and select Repair or Improve . The effective quality of the stone brick is affected by its damage and your masonry skill, it must be higher than the wall\'s current quality.', '<ul><li>You must <a href=\"/index.php/Repairing\" title=\"Repairing\">repair</a> any <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> on the walls with a <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">stone brick</a> before <a href=\"/index.php/Improve\" title=\"Improve\">improving</a> it.</li>\n<li>Activate a <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">stone brick</a>, right-click the wall and select <i>Repair</i> or <i>Improve</i>.</li>\n<li>The effective <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">stone brick</a> is affected by its damage and your <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill, it must be higher than the wall\'s current quality.</li></ul>\n<p><br/>\n</p>', 5),
(4595, 1194, 'See also', 'See_also', 'Stone wall Stone door Stone portcullis Stone window Stone oriel Stone double door Stone T arch Stone arch right Stone arch left', '<ul><li><a href=\"/index.php/Stone_wall\" title=\"Stone wall\">Stone wall</a></li>\n<li><a class=\"mw-selflink selflink\">Stone door</a></li>\n<li><a href=\"/index.php/Stone_portcullis_(wall)\" title=\"Stone portcullis (wall)\"> Stone portcullis</a></li>\n<li><a href=\"/index.php/Stone_window\" title=\"Stone window\">Stone window</a></li>\n<li><a href=\"/index.php/Stone_oriel\" title=\"Stone oriel\">Stone oriel</a></li>\n<li><a href=\"/index.php/Stone_double_door\" title=\"Stone double door\">Stone double door</a></li>\n<li><a href=\"/index.php/Stone_T_arch\" title=\"Stone T arch\">Stone T arch</a></li>\n<li><a href=\"/index.php/Stone_arch_right\" title=\"Stone arch right\">Stone arch right</a></li>\n<li><a href=\"/index.php/Stone_arch_left\" title=\"Stone arch left\">Stone arch left</a></li></ul>', 6),
(4596, 1195, 'Description', 'Description', 'You see a door.', '<p><i>You see a door. </i>\n</p>', 0),
(4597, 1195, 'Locking', 'Locking', 'It can be locked with a door lock . Any humanoid mob, for example trolls , or player can pass through an unlocked door.', '<ul><li>It can be locked with a <a href=\"/index.php/Door_lock\" title=\"Door lock\">door lock</a>. Any humanoid mob, for example <a href=\"/index.php/Troll\" title=\"Troll\">trolls</a>, or player can pass through an unlocked door.</li></ul>', 1),
(4598, 1195, 'Creation', 'Creation', 'Have at least 1 Plank and 1 Large nails in your inventory. Activate a mallet or hammer and right-click on a wall plan . Select Build and then Wooden door . Continuation requires at least 1 plank in your inventory.', '<ul><li>Have at least 1 <a href=\"/index.php/Plank\" title=\"Plank\">Plank</a> and 1 <a href=\"/index.php/Large_nails\" title=\"Large nails\">Large nails</a> in your inventory.</li>\n<li><b>Activate</b> a <a href=\"/index.php/Mallet\" title=\"Mallet\">mallet</a> or <a href=\"/index.php/Hammer\" title=\"Hammer\">hammer</a> and <b>right-click</b> on a <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">wall plan</a>.</li>\n<li>Select <b>Build</b> and then <b>Wooden door</b>.</li>\n<li>Continuation requires at least 1 <a href=\"/index.php/Plank\" title=\"Plank\">plank</a> in your inventory.</li></ul>', 2),
(4599, 1195, 'Modifying', 'Modifying', 'You can turn walls to suit your needs by right-clicking them, and selecting Rotate wall .', '<ul><li>You can turn walls to suit your needs by <b>right-clicking</b> them, and selecting <b>Rotate wall</b>.</li></ul>', 3),
(4600, 1195, 'Improving', 'Improving', 'You must repair any damage on the walls with a plank before improving it. Activate a plank , right-click the wall and select Repair or Improve . The effective quality of the plank is affected by its damage and your Carpentry skill, it must be higher than the wall\'s current quality.', '<ul><li>You must <a href=\"/index.php/Repairing\" title=\"Repairing\">repair</a> any <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> on the walls with a <a href=\"/index.php/Plank\" title=\"Plank\">plank</a> before <a href=\"/index.php/Improve\" title=\"Improve\">improving</a> it.</li>\n<li>Activate a <a href=\"/index.php/Plank\" title=\"Plank\">plank</a>, right-click the wall and select <i>Repair</i> or <i>Improve</i>.</li>\n<li>The effective <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the <a href=\"/index.php/Plank\" title=\"Plank\">plank</a> is affected by its damage and your <a href=\"/index.php/Carpentry\" title=\"Carpentry\">Carpentry</a> skill, it must be higher than the wall\'s current quality.</li></ul>\n<p><br/>\n</p>', 4),
(4601, 1195, 'See also', 'See_also', 'Wooden wall Wooden door Wooden double door Wooden window Wooden wide window Wooden portcullis Wooden canopy Wooden arch Wooden T arch Wooden arch right Wooden arch left', '<ul><li><a href=\"/index.php/Wooden_wall\" title=\"Wooden wall\">Wooden wall</a></li>\n<li><a class=\"mw-selflink selflink\">Wooden door</a></li>\n<li><a href=\"/index.php/Wooden_double_door\" title=\"Wooden double door\">Wooden double door</a></li>\n<li><a href=\"/index.php/Wooden_window\" title=\"Wooden window\">Wooden window</a></li>\n<li><a href=\"/index.php/Wooden_wide_window\" title=\"Wooden wide window\">Wooden wide window</a></li>\n<li><a href=\"/index.php/Wooden_portcullis\" title=\"Wooden portcullis\">Wooden portcullis</a></li>\n<li><a href=\"/index.php/Wooden_canopy\" title=\"Wooden canopy\">Wooden canopy</a></li>\n<li><a href=\"/index.php/Wooden_arch\" title=\"Wooden arch\">Wooden arch</a></li>\n<li><a href=\"/index.php/Wooden_T_arch\" title=\"Wooden T arch\">Wooden T arch</a></li>\n<li><a href=\"/index.php/Wooden_arch_right\" title=\"Wooden arch right\">Wooden arch right</a></li>\n<li><a href=\"/index.php/Wooden_arch_left\" title=\"Wooden arch left\">Wooden arch left</a></li></ul>', 5),
(4602, 1196, 'Description', 'Description', 'A solid wall for a wooden house .', '<p>A solid wall for a wooden <a href=\"/index.php/House\" title=\"House\">house</a>. \n</p>', 0),
(4603, 1196, 'Modifying', 'Modifying', 'You can turn walls to suit your needs. Repairing and improving Any damage must be repaired on the walls with a plank before improving it. Activate a plank, right-click the wall, and select \"Repair\" or \"Improve\". The effective quality of the plank is affected by its damage and the player \'s carpentry skill. Any quality plank can be used to repair and improve a wall (which will improve by between around .04-1.5+ QL per plank--more research needed but a higher QL plank will yield more improved QL). 1 plank will repair up to 10 damage depending on quality and repairing skill.', '<ul><li>You can turn walls to suit your needs.</li></ul>\n<h3><span class=\"mw-headline\" id=\"Repairing_and_improving\">Repairing and improving</span></h3>\n<ul><li>Any <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> must be <a href=\"/index.php/Repairing\" title=\"Repairing\">repaired</a> on the walls with a <a href=\"/index.php/Plank\" title=\"Plank\">plank</a> before <a class=\"mw-redirect\" href=\"/index.php/Improving\" title=\"Improving\">improving</a> it.</li>\n<li>Activate a plank, right-click the wall, and select \"Repair\" or \"Improve\".</li>\n<li>The effective <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the plank is affected by its <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> and the <a href=\"/index.php/Player\" title=\"Player\">player</a>\'s <a href=\"/index.php/Carpentry\" title=\"Carpentry\">carpentry</a> skill.</li>\n<li>Any quality plank can be used to repair and improve a wall (which will improve by between around .04-1.5+ QL per plank--more research needed but a higher QL plank will yield more improved QL).</li>\n<li>1 plank will repair up to 10 damage depending on quality and repairing skill.</li></ul>', 1),
(4604, 1196, 'Notes', 'Notes', 'For the stone version, see stone house wall', '<ul><li>For the stone version, see <a href=\"/index.php/Stone_house_wall\" title=\"Stone house wall\">stone house wall</a></li></ul>', 2),
(4605, 1196, 'See also', 'See_also', 'Wooden wall Wooden door Wooden double door Wooden window Wooden wide window Wooden portcullis Wooden canopy Wooden arch Wooden T arch Wooden arch right Wooden arch left', '<ul><li><a href=\"/index.php/Wooden_wall\" title=\"Wooden wall\">Wooden wall</a></li>\n<li><a href=\"/index.php/Wooden_door\" title=\"Wooden door\">Wooden door</a></li>\n<li><a href=\"/index.php/Wooden_double_door\" title=\"Wooden double door\">Wooden double door</a></li>\n<li><a href=\"/index.php/Wooden_window\" title=\"Wooden window\">Wooden window</a></li>\n<li><a href=\"/index.php/Wooden_wide_window\" title=\"Wooden wide window\">Wooden wide window</a></li>\n<li><a href=\"/index.php/Wooden_portcullis\" title=\"Wooden portcullis\">Wooden portcullis</a></li>\n<li><a href=\"/index.php/Wooden_canopy\" title=\"Wooden canopy\">Wooden canopy</a></li>\n<li><a href=\"/index.php/Wooden_arch\" title=\"Wooden arch\">Wooden arch</a></li>\n<li><a href=\"/index.php/Wooden_T_arch\" title=\"Wooden T arch\">Wooden T arch</a></li>\n<li><a href=\"/index.php/Wooden_arch_right\" title=\"Wooden arch right\">Wooden arch right</a></li>\n<li><a href=\"/index.php/Wooden_arch_left\" title=\"Wooden arch left\">Wooden arch left</a></li></ul>', 3),
(4606, 1197, 'Description', 'Description', 'You see a window.', '<p><i>You see a window. </i>\n</p>', 0),
(4607, 1197, 'Creation', 'Creation', 'Have at least 1 Plank and 1 Large nails in your inventory. Activate a mallet or hammer and right-click on a wall plan . Select Build and then Wooden window . Continuation requires at least 1 plank in your inventory.', '<ul><li>Have at least 1 <a href=\"/index.php/Plank\" title=\"Plank\">Plank</a> and 1 <a href=\"/index.php/Large_nails\" title=\"Large nails\">Large nails</a> in your inventory.</li>\n<li><b>Activate</b> a <a href=\"/index.php/Mallet\" title=\"Mallet\">mallet</a> or <a href=\"/index.php/Hammer\" title=\"Hammer\">hammer</a> and <b>right-click</b> on a <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">wall plan</a>.</li>\n<li>Select <b>Build</b> and then <b>Wooden window</b>.</li>\n<li>Continuation requires at least 1 <a href=\"/index.php/Plank\" title=\"Plank\">plank</a> in your inventory.</li></ul>', 1),
(4608, 1197, 'Modifying', 'Modifying', 'You can turn walls to suit your needs by right-clicking them, and selecting Rotate wall .', '<ul><li>You can turn walls to suit your needs by <b>right-clicking</b> them, and selecting <b>Rotate wall</b>.</li></ul>', 2),
(4609, 1197, 'Improving', 'Improving', 'You must repair any damage on the walls with a plank before improving it. Activate a plank , right-click the wall and select Repair or Improve . The effective quality of the plank is affected by its damage and your Carpentry skill, it must be higher than the wall\'s current quality.', '<ul><li>You must <a href=\"/index.php/Repairing\" title=\"Repairing\">repair</a> any <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> on the walls with a <a href=\"/index.php/Plank\" title=\"Plank\">plank</a> before <a href=\"/index.php/Improve\" title=\"Improve\">improving</a> it.</li>\n<li>Activate a <a href=\"/index.php/Plank\" title=\"Plank\">plank</a>, right-click the wall and select <i>Repair</i> or <i>Improve</i>.</li>\n<li>The effective <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the <a href=\"/index.php/Plank\" title=\"Plank\">plank</a> is affected by its damage and your <a href=\"/index.php/Carpentry\" title=\"Carpentry\">Carpentry</a> skill, it must be higher than the wall\'s current quality.</li></ul>\n<p><br/>\n</p>', 3),
(4610, 1197, 'See also', 'See_also', 'Wooden wall Wooden door Wooden double door Wooden window Wooden wide window Wooden portcullis Wooden canopy Wooden arch Wooden T arch Wooden arch right Wooden arch left', '<ul><li><a href=\"/index.php/Wooden_wall\" title=\"Wooden wall\">Wooden wall</a></li>\n<li><a href=\"/index.php/Wooden_door\" title=\"Wooden door\">Wooden door</a></li>\n<li><a href=\"/index.php/Wooden_double_door\" title=\"Wooden double door\">Wooden double door</a></li>\n<li><a class=\"mw-selflink selflink\">Wooden window</a></li>\n<li><a href=\"/index.php/Wooden_wide_window\" title=\"Wooden wide window\">Wooden wide window</a></li>\n<li><a href=\"/index.php/Wooden_portcullis\" title=\"Wooden portcullis\">Wooden portcullis</a></li>\n<li><a href=\"/index.php/Wooden_canopy\" title=\"Wooden canopy\">Wooden canopy</a></li>\n<li><a href=\"/index.php/Wooden_arch\" title=\"Wooden arch\">Wooden arch</a></li>\n<li><a href=\"/index.php/Wooden_T_arch\" title=\"Wooden T arch\">Wooden T arch</a></li>\n<li><a href=\"/index.php/Wooden_arch_right\" title=\"Wooden arch right\">Wooden arch right</a></li>\n<li><a href=\"/index.php/Wooden_arch_left\" title=\"Wooden arch left\">Wooden arch left</a></li></ul>', 4),
(4614, 1199, 'Effects', 'Effects', 'Karma Spirit fervor Faith bonus', '<ul><li><a href=\"/index.php/Karma\" title=\"Karma\">Karma</a></li>\n<li><a href=\"/index.php/Spirit_fervor\" title=\"Spirit fervor\">Spirit fervor</a></li>\n<li><a href=\"/index.php/Faith_bonus\" title=\"Faith bonus\">Faith bonus</a></li></ul>\n<p><br/>\n</p>', 0),
(4615, 1199, 'See also', 'See_also', 'Player status effect', '<ul><li><a href=\"/index.php/Player_status_effect\" title=\"Player status effect\">Player status effect</a></li></ul>', 1),
(4616, 1200, 'Description', 'Description', 'Beneficial effect caused by Religion.', '<p>Beneficial effect caused by Religion.\n</p>\n<p><br/>\n</p>', 0),
(4617, 1200, 'See also', 'See_also', 'Spell effects Player status effect', '<ul><li><a href=\"/index.php/Spell_effects\" title=\"Spell effects\">Spell effects</a></li>\n<li><a href=\"/index.php/Player_status_effect\" title=\"Player status effect\">Player status effect</a></li></ul>', 1),
(4618, 1201, 'Description', 'Description', 'Floor plan to create an opening with a ladder for multi-story buildings. Creation Right click the floor of the house, select Plan > Build floor with opening above to create a floor plan Right click the floor plan, select Build > Pottery brick opening Usage Right click the opening or ladder, select Climb to move between floors. By standing on the opening of a floor you can activate a rope and right click certain items to haul them, providing both you and the object are on the same tile, albeit one floor apart. Hauling back down will work in the same way and the item does not need to be empty. You need 21 body strength to haul.', '<p>Floor plan to create an opening with a ladder for multi-story buildings.\n</p>\n<h3><span class=\"mw-headline\" id=\"Creation\">Creation</span></h3>\n<ul><li>Right click the floor of the house, select <i>Plan</i> &gt; <i>Build floor with opening above</i> to create a floor plan</li>\n<li>Right click the floor plan, select <i>Build</i> &gt; <i>Pottery brick opening</i></li></ul>\n<h3><span class=\"mw-headline\" id=\"Usage\">Usage</span></h3>\n<ul><li>Right click the opening or ladder, select <b>Climb</b> to move between floors.</li>\n<li>By standing on the opening of a floor you can activate a <a href=\"/index.php/Rope\" title=\"Rope\">rope</a> and right click certain items to haul them, providing both you and the object are on the same tile, albeit one floor apart. Hauling back down will work in the same way and the item does not need to be empty. You need 21 body strength to haul.</li></ul>', 0),
(4619, 1201, 'Notes', 'Notes', 'Requires 25 paving skill. Use clay to repair or improve a pottery brick opening.', '<ul><li>Requires 25 paving skill.</li>\n<li>Use clay to repair or improve a pottery brick opening.</li></ul>', 1),
(4620, 1202, 'Description', 'Description', 'Floor plan to create an opening with a ladder for multi-story buildings. Creation Right click the floor of the house, select Plan > Build floor with opening above to create a floor plan Right click the floor plan, select Build > Stone brick opening Usage Right click the opening or ladder, select Climb to move between floors. By standing on the opening of a floor you can activate a rope and right click certain items to haul them, providing both you and the object are on the same tile, albeit one floor apart. Hauling back down will work in the same way and the item does not need to be empty. You need 21 body strength to haul.', '<p>Floor plan to create an opening with a ladder for multi-story buildings.\n</p>\n<h3><span class=\"mw-headline\" id=\"Creation\">Creation</span></h3>\n<ul><li>Right click the floor of the house, select <i>Plan</i> &gt; <i>Build floor with opening above</i> to create a floor plan</li>\n<li>Right click the floor plan, select <i>Build</i> &gt; <i>Stone brick opening</i></li></ul>\n<h3><span class=\"mw-headline\" id=\"Usage\">Usage</span></h3>\n<ul><li>Right click the opening or ladder, select <b>Climb</b> to move between floors.</li>\n<li>By standing on the opening of a floor you can activate a <a href=\"/index.php/Rope\" title=\"Rope\">rope</a> and right click certain items to haul them, providing both you and the object are on the same tile, albeit one floor apart. Hauling back down will work in the same way and the item does not need to be empty. You need 21 body strength to haul.</li></ul>', 0),
(4621, 1202, 'Notes', 'Notes', 'Must have 1 stone brick and 1 mortar in inventory to start.', '<ul><li>Must have 1 stone brick and 1 mortar in inventory to start.</li></ul>', 1),
(4622, 1203, 'Description', 'Description', 'It is a normal opening made of stone slab. Floor plan to create an opening with a ladder for multi-story buildings. Creation Right click the floor of the house, select Plan > Build ladder to create a floor plan Make sure trowel is activated Right click the ladder or floor plan above and select Build > Stone slab opening Usage Right click the opening or ladder, select Climb to move between floors. By standing on the opening of a floor you can activate a rope and right click certain items to haul them, providing both you and the object are on the same tile, albeit one floor apart. Hauling back down will work in the same way and the item does not need to be empty. You need 21 body strength to haul.', '<p><i>It is a normal opening made of stone slab.</i>\n</p>\n<p>Floor plan to create an opening with a ladder for multi-story buildings.\n</p>\n<h3><span class=\"mw-headline\" id=\"Creation\">Creation</span></h3>\n<ul><li>Right click the floor of the house, select <i>Plan</i> &gt; <i>Build ladder</i> to create a floor plan</li>\n<li>Make sure <a href=\"/index.php/Trowel\" title=\"Trowel\">trowel</a> is activated</li>\n<li>Right click the ladder or floor plan above and select <i>Build</i> &gt; <i>Stone slab opening</i></li></ul>\n<h3><span class=\"mw-headline\" id=\"Usage\">Usage</span></h3>\n<ul><li>Right click the opening or ladder, select <b>Climb</b> to move between floors.</li>\n<li>By standing on the opening of a floor you can activate a <a href=\"/index.php/Rope\" title=\"Rope\">rope</a> and right click certain items to haul them, providing both you and the object are on the same tile, albeit one floor apart. Hauling back down will work in the same way and the item does not need to be empty. You need 21 body strength to haul.</li></ul>', 0),
(4623, 1203, 'Notes', 'Notes', '21 paving skill is required to start a stone slab opening.', '<ul><li>21 <a href=\"/index.php/Paving\" title=\"Paving\">paving</a> skill is required to start a stone slab opening.</li></ul>', 1),
(4624, 1204, 'Description', 'Description', 'It is a normal opening made of slate slab. Floor plan to create an opening with a ladder for multi-story buildings. Creation Right click the floor of the house, select Plan > Build floor with opening above to create a floor plan Right click the floor plan, select Build > Slate slab opening Usage Right click the opening or ladder, select Climb to move between floors. By standing on the opening of a floor you can activate a rope and right click certain items to haul them, providing both you and the object are on the same tile, albeit one floor apart. Hauling back down will work in the same way and the item does not need to be empty. You need 21 body strength to haul.', '<p><i>It is a normal opening made of slate slab.</i>\n</p>\n<p>Floor plan to create an opening with a ladder for multi-story buildings.\n</p>\n<h3><span class=\"mw-headline\" id=\"Creation\">Creation</span></h3>\n<ul><li>Right click the floor of the house, select <i>Plan</i> &gt; <i>Build floor with opening above</i> to create a floor plan</li>\n<li>Right click the floor plan, select <i>Build</i> &gt; <i>Slate slab opening</i></li></ul>\n<h3><span class=\"mw-headline\" id=\"Usage\">Usage</span></h3>\n<ul><li>Right click the opening or ladder, select <b>Climb</b> to move between floors.</li>\n<li>By standing on the opening of a floor you can activate a <a href=\"/index.php/Rope\" title=\"Rope\">rope</a> and right click certain items to haul them, providing both you and the object are on the same tile, albeit one floor apart. Hauling back down will work in the same way and the item does not need to be empty. You need 21 body strength to haul.</li></ul>', 0),
(4625, 1204, 'Notes', 'Notes', 'Requires 30 paving skill to start', '<ul><li>Requires 30 paving skill to start</li></ul>', 1),
(4626, 1205, 'Description', 'Description', 'It is a normal opening made of marble slab. Floor plan to create an opening with a ladder for multi-story buildings. Creation Right click the floor of the house, select Plan > Build floor with opening above to create a floor plan Right click the floor plan, select Build > Marble slab opening Usage Right click the opening or ladder, select Climb to move between floors. By standing on the opening of a floor you can activate a rope and right click certain items to haul them, providing both you and the object are on the same tile, albeit one floor apart. Hauling back down will work in the same way and the item does not need to be empty. You need 21 body strength to haul.', '<p><i>It is a normal opening made of marble slab.</i>\n</p>\n<p>Floor plan to create an opening with a ladder for multi-story buildings.\n</p>\n<h3><span class=\"mw-headline\" id=\"Creation\">Creation</span></h3>\n<ul><li>Right click the floor of the house, select <i>Plan</i> &gt; <i>Build floor with opening above</i> to create a floor plan</li>\n<li>Right click the floor plan, select <i>Build</i> &gt; <i>Marble slab opening</i></li></ul>\n<h3><span class=\"mw-headline\" id=\"Usage\">Usage</span></h3>\n<ul><li>Right click the opening or ladder, select <b>Climb</b> to move between floors.</li>\n<li>By standing on the opening of a floor you can activate a <a href=\"/index.php/Rope\" title=\"Rope\">rope</a> and right click certain items to haul them, providing both you and the object are on the same tile, albeit one floor apart. Hauling back down will work in the same way and the item does not need to be empty. You need 21 body strength to haul.</li></ul>', 0),
(4627, 1205, 'Notes', 'Notes', '40 paving skill is required to start a marble slab opening.', '<ul><li>40 <a href=\"/index.php/Paving\" title=\"Paving\">paving</a> skill is required to start a marble slab opening.</li></ul>', 1),
(4630, 1207, 'Description', 'Description', 'A vein of fine-grained, foliated, homogenous metamorphic rock,or slate as we know it, emerges here .', '<p><i>A vein of fine-grained, foliated, homogenous metamorphic rock,or slate as we know it, emerges here</i>.\n</p>', 0),
(4631, 1207, 'Notes', 'Notes', 'Slate veins contain a random amount of slate shards between 1-10000. This page refers to the type of cave wall. For the house wall, see Slate brick wall', '<ul><li>Slate veins contain a random amount of slate shards between 1-10000.</li>\n<li>This page refers to the type of cave wall. For the house wall, see <a href=\"/index.php/Slate_brick_wall\" title=\"Slate brick wall\">Slate brick wall</a></li></ul>', 1),
(4632, 1207, 'See also', 'See_also', 'Category:Slate items Masonry Stonecutting Mining Prospecting Analyze', '<ul><li><a href=\"/index.php/Category:Slate_items\" title=\"Category:Slate items\">Category:Slate items</a></li>\n<li><a href=\"/index.php/Masonry\" title=\"Masonry\">Masonry</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Stonecutting\" title=\"Stonecutting\">Stonecutting</a></li>\n<li><a href=\"/index.php/Mining\" title=\"Mining\">Mining</a></li>\n<li><a href=\"/index.php/Prospecting\" title=\"Prospecting\">Prospecting</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Analyze\" title=\"Analyze\">Analyze</a></li></ul>', 2),
(4694, 1138, 'Description', 'Description', 'Concrete, for instance used to raise cave floors. Concrete is used to raise a cave floor or the rock surface layer .', '<p><i>Concrete, for instance used to raise cave floors.</i>\n</p>\n<p>Concrete is used to <a href=\"/index.php/Slope\" title=\"Slope\">raise</a> a <a href=\"/index.php/Cave_floor\" title=\"Cave floor\">cave floor</a> or the <a href=\"/index.php/Rock_tile\" title=\"Rock tile\">rock surface layer</a>.\n</p>', 0),
(4695, 1138, 'Use', 'Use', 'Right click a cave floor tile or exterior rock tile with the concrete and select > raise corner - this raises the corner the equivalent of 1 dirt. The corner closest to where you are standing will be the one that is raised, just like when dropping dirt. Concrete can be used to raise an underwater cave tile as long as the tile is 25 dirts deep or less; below that you get the message: The water is too deep and would only dissolve the concrete. Can be used to raise a corner to a maximum of 25 slope on PvP servers or 40 slope on PvE servers. Cannot be used on any corner of a cliff tile regardless of slope. If used to raise the corner of a surface rock tile, the surrounding area must also be rock. The actual application of concrete and raising corners gives masonry skill. The quality of the concrete and your masonry skill affects the speed of which the concrete is applied. You cannot raise reinforced cave floors.', '<ul><li>Right click a cave floor tile or exterior rock tile with the <a class=\"mw-selflink selflink\">concrete</a> and select &gt; raise corner - this raises the corner the equivalent of 1 dirt.</li>\n<li>The corner closest to where you are standing will be the one that is raised, just like when dropping dirt.</li>\n<li>Concrete can be used to raise an underwater cave tile as long as the tile is 25 dirts deep or less; below that you get the message: <span style=\"color: #fff; font-family: Sans-Serif; font-size: 0.85em; border: 1px rgb(0, 0, 0) solid; background: rgb(75, 62, 48); line-height: 1.3em; -webkit-border-radius: 5px; -moz-border-radius: 5px; border-radius: 5px; -moz-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); -webkit-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); padding: 2px 10px 2px 10px; display: inline-block;\"> The water is too deep and would only dissolve the concrete. </span></li>\n<li>Can be used to raise a corner to a maximum of 25 slope on PvP servers or 40 slope on PvE servers.</li>\n<li>Cannot be used on any corner of a cliff tile regardless of slope.</li>\n<li>If used to raise the corner of a surface rock tile, the surrounding area must also be rock.</li>\n<li>The actual application of concrete and raising corners gives masonry skill.</li>\n<li>The quality of the concrete and your masonry skill affects the speed of which the concrete is applied.</li>\n<li>You cannot raise reinforced cave floors.</li></ul>', 1),
(4696, 1138, 'Creation', 'Creation', 'The quality of the lye used to create the concrete affects your success chance. On failure, 0.05 kg of lye and 0.30 kg of mortar are wasted. To utilize Circle of cunning or Wind of ages when creating, it must be cast on the lye.', '<ul><li>The <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the <a href=\"/index.php/Lye\" title=\"Lye\">lye</a> used to create the <a class=\"mw-selflink selflink\">concrete</a> affects your success chance.</li>\n<li>On failure, 0.05 kg of lye and 0.30 kg of mortar are wasted.</li>\n<li>To utilize <a href=\"/index.php/Circle_of_cunning\" title=\"Circle of cunning\">Circle of cunning</a> or <a href=\"/index.php/Wind_of_ages\" title=\"Wind of ages\">Wind of ages</a> when creating, it must be cast on the lye.</li></ul>', 2),
(4697, 1138, 'Notes', 'Notes', 'Using \"Raise Corner\" on a cave ceiling tile will raise the floor below with no effect on the ceiling.', '<p>Using \"Raise Corner\" on a cave ceiling tile will raise the floor below with no effect on the ceiling.\n</p>', 3),
(4698, 1138, 'Skills & Characteristics', 'Skills_.26_Characteristics', 'Natural Substances Masonry', '<ul><li><a class=\"mw-redirect\" href=\"/index.php/Natural_Substances\" title=\"Natural Substances\">Natural Substances</a></li>\n<li><a href=\"/index.php/Masonry\" title=\"Masonry\">Masonry</a></li></ul>', 4),
(4722, 1217, 'Description', 'Description', 'A roof plan is the frame of an incomplete building roof. This is the top-most tile space of a building, if constructed, and no other plans may be built above this.', '<p>A <a class=\"mw-selflink selflink\">roof plan</a> is the frame of an incomplete building roof. This is the top-most tile space of a building, if constructed, and no other plans may be built above this.\n</p>', 0),
(4723, 1217, 'Notes', 'Notes', 'To start planning a roof, activate a mallet or hammer , right-click a tile within the building, and then select Plan roof . To remove a roof plan from a tile, right-click the tile, and select Remove roof plan here . Roofs count as the same story you are currently building and do not require any extra skill. Additional information for calculating carpentry and material requirements can be found by visiting the Toolkits page.', '<ul><li>To start planning a roof, activate a <a href=\"/index.php/Mallet\" title=\"Mallet\">mallet</a> or <a href=\"/index.php/Hammer\" title=\"Hammer\">hammer</a>, right-click a <a href=\"/index.php/Tile\" title=\"Tile\">tile</a> within the building, and then select <i>Plan roof</i>.</li>\n<li>To remove a roof plan from a tile, right-click the tile, and select <i>Remove roof plan here</i>.</li>\n<li>Roofs count as the same story you are currently building and do not require any extra skill.</li>\n<li>Additional information for calculating carpentry and material requirements can be found by visiting the <a href=\"/index.php/Toolkits\" title=\"Toolkits\">Toolkits</a> page.</li></ul>', 1),
(4735, 1182, 'Skill needed', 'Skill_needed', 'The more floors your house has, the more skill is needed; see the table below for the required skill levels. Only the first (ground) floor planning needs 1 carpentry skill per wall and 1 skill per tile. With 5 skill a roof may be placed over the first floor, but not an opening or floor above. The roof counts as the same story you are currently building and does not require any extra skill to roof. i.e Roof added to a 8 story building would still only require 70 skill. You may have a total of 16 floors (counting ground level as the first floor) Carpentry is the primary skill checked for planning each floor and building floors, openings, staircases, walls and fences out of wood. The first floor always requires a skill of at least 5, even if the building plan has already been finalized by another character. Paving is required for stone floors, openings, and staircases. Masonry is required for stone walls, fences, parapets, as well as pottery and slate roofs. It is required in increasing amounts for multi story houses similar to Carpentry skill for wooden things. Thatching is required for thatch roofs. Some materials might have higher skill requirements than the numbers mentioned below, in which case the highest requirement applies Floors Skill Requirement 1 5 2 21 3 30 4 39 5 47 6 55 Floors Skill Requirement 7 63 8 70 9 77 10 83 11 88 Floors Skill Requirement 12 92 13 95 14 97 15 98 16 99', '<p>The more floors your house has, the more skill is needed; see the table below for the required skill levels. Only the first (ground) floor planning needs 1 <a href=\"/index.php/Carpentry\" title=\"Carpentry\">carpentry</a> skill per wall and 1 skill per tile. With 5 skill a roof may be placed over the first floor, but not an opening or floor above. The roof counts as the same story you are currently building and does not require any extra skill to roof. i.e Roof added to a 8 story building would still only require 70 skill.\n</p>\n<ul><li>You may have a total of 16 floors (counting ground level as the first floor)</li>\n<li><a href=\"/index.php/Carpentry\" title=\"Carpentry\">Carpentry</a> is the primary skill checked for planning each floor and building floors, openings, staircases, walls and fences out of wood.</li>\n<li>The first floor always requires a skill of at least 5, even if the building plan has already been finalized by another character.</li>\n<li><a href=\"/index.php/Paving\" title=\"Paving\">Paving</a> is required for stone floors, openings, and staircases.</li>\n<li><a href=\"/index.php/Masonry\" title=\"Masonry\">Masonry</a> is required for stone walls, fences, parapets, as well as pottery and slate roofs. It is required in increasing amounts for multi story houses similar to Carpentry skill for wooden things.</li>\n<li><a href=\"/index.php/Thatching\" title=\"Thatching\">Thatching</a> is required for thatch roofs.</li>\n<li>Some materials might have higher skill requirements than the numbers mentioned below, in which case the highest requirement applies</li></ul>\n<table width=\"40%\">\n<tbody><tr>\n<th style=\"width: 33%;\">\n</th>\n<th style=\"width: 33%;\">\n</th>\n<th style=\"width: 33%;\">\n</th></tr>\n<tr>\n<td style=\"padding: 5px;\">\n<table align=\"left\" class=\"wikitable\">\n<tbody><tr>\n<th>Floors</th>\n<th>Skill Requirement\n</th></tr>\n<tr>\n<td>1</td>\n<td>5\n</td></tr>\n<tr>\n<td>2</td>\n<td>21\n</td></tr>\n<tr>\n<td>3</td>\n<td>30\n</td></tr>\n<tr>\n<td>4</td>\n<td>39\n</td></tr>\n<tr>\n<td>5</td>\n<td>47\n</td></tr>\n<tr>\n<td>6</td>\n<td>55\n</td></tr>\n</tbody></table>\n</td>\n<td style=\"padding: 5px;\">\n<table align=\"center\" class=\"wikitable\">\n<tbody><tr>\n<th>Floors</th>\n<th>Skill Requirement\n</th></tr>\n<tr>\n<td>7</td>\n<td>63\n</td></tr>\n<tr>\n<td>8</td>\n<td>70\n</td></tr>\n<tr>\n<td>9</td>\n<td>77\n</td></tr>\n<tr>\n<td>10</td>\n<td>83\n</td></tr>\n<tr>\n<td>11</td>\n<td>88\n</td></tr>\n</tbody></table>\n</td>\n<td style=\"padding: 5px;\">\n<table class=\"wikitable\">\n<tbody><tr>\n<th>Floors</th>\n<th>Skill Requirement\n</th></tr>\n<tr>\n<td>12</td>\n<td>92\n</td></tr>\n<tr>\n<td>13</td>\n<td>95\n</td></tr>\n<tr>\n<td>14</td>\n<td>97\n</td></tr>\n<tr>\n<td>15</td>\n<td>98\n</td></tr>\n<tr>\n<td>16</td>\n<td>99\n</td></tr></tbody></table>\n</td></tr></tbody></table>', 0),
(4736, 1182, 'Adding a roof', 'Adding_a_roof', 'Plan and completely build the walls. Both floor and roof are planned by activating a mallet and right clicking the tiles on the ground beneath you. Each tile needs to be planned. Build both.', '<ol><li>Plan and completely build the walls.</li>\n<li>Both floor and roof are planned by activating a <a href=\"/index.php/Mallet\" title=\"Mallet\">mallet</a> and right clicking the tiles on the ground beneath you. Each tile needs to be planned.</li>\n<li>Build both.</li></ol>', 1),
(4737, 1182, 'How to make another floor', 'How_to_make_another_floor', 'Plan and completely build the first floor outer walls. Activate a mallet on a tile below and plan floor above Plan at least one tile with an opening above to make a ladder for a spot to climb up to upper floors or plan your staircase. Build the floors from below. Activate a mallet, right click tile borders to plan walls. Notes In-game descriptions describe the bottom floor as being the 1st, which is a US standard.  Therefore the Wurmpedia will describe this as such.  The use of the term ground floor or ground will be kept to a minimum. You can not build floors above fences, walls or parapets. You can drag carts up ladders to get them to an upper floor. You can fall and take damage from upper floors if there is no wall/fence of roof to stop you. (Please be careful as people have died in 1 fall from 4th floor drops) Ladders will always be on the south side of the opening. The 1st floor must be complete before walls on the 2nd can be planned. This is not true, however, of any additional floors. Where a mallet is mentioned a hammer can be used in its place. When you destroy a structure all items on upper levels will fall to the ground. Wall types can be found on the wall page.', '<ol><li>Plan and completely build the first floor outer walls.</li>\n<li>Activate a mallet on a tile below and plan floor above</li>\n<li>Plan at least one tile with an opening above to make a ladder for a spot to climb up to upper floors or plan your staircase.</li>\n<li>Build the floors from below.</li>\n<li>Activate a mallet, right click tile borders to plan walls.</li></ol>\n<h3><span class=\"mw-headline\" id=\"Notes\">Notes</span></h3>\n<ul><li>In-game descriptions describe the bottom floor as being the 1st, which is a US standard.  Therefore the Wurmpedia will describe this as such.  The use of the term ground floor or ground will be kept to a minimum.</li>\n<li>You can not build floors above fences, walls or parapets.</li>\n<li>You can drag <a href=\"/index.php/Cart\" title=\"Cart\">carts</a> up ladders to get them to an upper floor.</li>\n<li>You can fall and take damage from upper floors if there is no wall/fence of roof to stop you. (Please be careful as people have died in 1 fall from 4th floor drops)</li>\n<li>Ladders will always be on the south side of the opening.</li>\n<li>The 1st floor must be complete before walls on the 2nd can be planned. This is not true, however, of any additional floors.</li>\n<li>Where a mallet is mentioned a <a href=\"/index.php/Hammer\" title=\"Hammer\">hammer</a> can be used in its place.</li>\n<li>When you destroy a structure all items on upper levels will fall to the ground.</li>\n<li>Wall types can be found on the <a href=\"/index.php/Wall\" title=\"Wall\">wall</a> page.</li></ul>', 2),
(4738, 1182, 'Floor and Opening types', 'Floor_and_Opening_types', 'Housing floor types. Floors Openings Staircases Wooden plank floor Wooden plank opening Wooden plank staircase Pottery brick floor Pottery brick opening Pottery brick staircase Sandstone slab floor Sandstone slab opening Sandstone slab staircase Stone slab floor Stone slab opening Stone slab staircase Marble slab floor Marble slab opening Marble slab staircase Stone brick floor Stone brick opening Stone brick staircase Slate slab floor Slate slab opening Slate slab staircase Standalone staircase', '<div class=\"thumb tright\"><div class=\"thumbinner\" style=\"width:302px;\"><a class=\"image\" href=\"/index.php/File:House_floor_types.jpg\"><img alt=\"\" class=\"thumbimage\" data-file-height=\"938\" data-file-width=\"1240\" decoding=\"async\" height=\"227\" src=\"/images/thumb/2/2a/House_floor_types.jpg/300px-House_floor_types.jpg\" srcset=\"/images/thumb/2/2a/House_floor_types.jpg/450px-House_floor_types.jpg 1.5x, /images/thumb/2/2a/House_floor_types.jpg/600px-House_floor_types.jpg 2x\" width=\"300\"/></a> <div class=\"thumbcaption\"><div class=\"magnify\"><a class=\"internal\" href=\"/index.php/File:House_floor_types.jpg\" title=\"Enlarge\"></a></div>Housing floor types.</div></div></div>\n<table style=\"text-align: center;\" width=\"40%\">\n<tbody><tr>\n<th style=\"width: 33%;\">Floors\n</th>\n<th style=\"width: 33%;\">Openings\n</th>\n<th style=\"width: 33%;\">Staircases\n</th></tr>\n<tr>\n<td><a href=\"/index.php/Wooden_plank_floor\" title=\"Wooden plank floor\">Wooden plank floor</a></td>\n<td><a href=\"/index.php/Wooden_plank_opening\" title=\"Wooden plank opening\">Wooden plank opening</a></td>\n<td><a href=\"/index.php/Wooden_plank_staircase\" title=\"Wooden plank staircase\">Wooden plank staircase</a>\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Pottery_brick_floor\" title=\"Pottery brick floor\">Pottery brick floor</a></td>\n<td><a href=\"/index.php/Pottery_brick_opening\" title=\"Pottery brick opening\">Pottery brick opening</a></td>\n<td><a href=\"/index.php/Pottery_brick_staircase\" title=\"Pottery brick staircase\">Pottery brick staircase</a>\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Sandstone_slab_floor\" title=\"Sandstone slab floor\">Sandstone slab floor</a></td>\n<td><a href=\"/index.php/Sandstone_slab_opening\" title=\"Sandstone slab opening\">Sandstone slab opening</a></td>\n<td><a href=\"/index.php/Sandstone_slab_staircase\" title=\"Sandstone slab staircase\">Sandstone slab staircase</a>\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Stone_slab_floor\" title=\"Stone slab floor\">Stone slab floor</a></td>\n<td><a href=\"/index.php/Stone_slab_opening\" title=\"Stone slab opening\">Stone slab opening</a></td>\n<td><a href=\"/index.php/Stone_slab_staircase\" title=\"Stone slab staircase\">Stone slab staircase</a>\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Marble_slab_floor\" title=\"Marble slab floor\">Marble slab floor</a></td>\n<td><a href=\"/index.php/Marble_slab_opening\" title=\"Marble slab opening\">Marble slab opening</a></td>\n<td><a href=\"/index.php/Marble_slab_staircase\" title=\"Marble slab staircase\">Marble slab staircase</a>\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Stone_brick_floor\" title=\"Stone brick floor\">Stone brick floor</a></td>\n<td><a href=\"/index.php/Stone_brick_opening\" title=\"Stone brick opening\">Stone brick opening</a></td>\n<td><a href=\"/index.php/Stone_brick_staircase\" title=\"Stone brick staircase\">Stone brick staircase</a>\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Slate_slab_floor\" title=\"Slate slab floor\">Slate slab floor</a></td>\n<td><a href=\"/index.php/Slate_slab_opening\" title=\"Slate slab opening\">Slate slab opening</a></td>\n<td><a href=\"/index.php/Slate_slab_staircase\" title=\"Slate slab staircase\">Slate slab staircase</a>\n</td></tr>\n<tr>\n<td></td>\n<td></td>\n<td><a href=\"/index.php/Standalone_staircase\" title=\"Standalone staircase\">Standalone staircase</a>\n</td></tr>\n</tbody></table>', 3),
(4739, 1182, 'Roof types', 'Roof_types', 'Wood shingle roof Slate shingle roof Pottery shingle roof Thatched roof', '<p><a href=\"/index.php/Wood_shingle_roof\" title=\"Wood shingle roof\">Wood shingle roof</a>\n</p>\n<p><a href=\"/index.php/Slate_shingle_roof\" title=\"Slate shingle roof\">Slate shingle roof</a>\n</p>\n<p><a href=\"/index.php/Pottery_shingle_roof\" title=\"Pottery shingle roof\">Pottery shingle roof</a>\n</p>\n<p><a href=\"/index.php/Thatched_roof\" title=\"Thatched roof\">Thatched roof</a>\n</p>\n<p><br/>\n</p>', 4),
(4740, 1182, 'Fence types', 'Fence_types', 'Wooden fence Wooden parapet -- More info needed Stone parapet -- More info needed Stone and iron parapet -- More info needed Low stone wall Tall stone wall Iron fence Crude wooden fence', '<p><a href=\"/index.php/Wooden_fence\" title=\"Wooden fence\">Wooden fence</a>\n</p>\n<p><a href=\"/index.php/Wooden_parapet\" title=\"Wooden parapet\">Wooden parapet</a> -- More info needed\n</p>\n<p><a href=\"/index.php/Stone_parapet\" title=\"Stone parapet\">Stone parapet</a> -- More info needed\n</p>\n<p><a href=\"/index.php/Stone_and_iron_parapet\" title=\"Stone and iron parapet\">Stone and iron parapet</a> -- More info needed\n</p>\n<p><a href=\"/index.php/Low_stone_wall\" title=\"Low stone wall\">Low stone wall</a>\n</p>\n<p><a href=\"/index.php/Tall_stone_wall\" title=\"Tall stone wall\">Tall stone wall</a>\n</p>\n<p><a href=\"/index.php/Iron_fence\" title=\"Iron fence\">Iron fence</a>\n</p>\n<p><a href=\"/index.php/Crude_wooden_fence\" title=\"Crude wooden fence\">Crude wooden fence</a>\n</p>', 5);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(4741, 1182, 'More Info', 'More_Info', 'For More Images and Info please check: [1] and [2]', '<p>For More Images and Info please check:\n</p>\n<p><a class=\"external autonumber\" href=\"http://forum.wurmonline.com/index.php?/topic/71182-documentation-for-new-multi-storey-houses/\" rel=\"nofollow\">[1]</a>\n</p>\n<p>and \n</p>\n<p><a class=\"external autonumber\" href=\"http://forum.wurmonline.com/index.php?/topic/70962-test-server-screenshots-help/\" rel=\"nofollow\">[2]</a>\n</p>', 6),
(4742, 1180, 'Spawn settlement', 'Spawn_settlement', 'Sloping Sands', '<p>Sloping Sands\n</p>', 0),
(4743, 1180, 'Travel', 'Travel', 'This island may be reached by boat from any other Southern Island.', '<p>This island may be reached by boat from any other Southern Island. \n</p>', 1),
(4744, 1180, 'Maps', 'Maps', 'In-game map Map dumps For community maps, see Maps', '<ul><li><a href=\"/index.php/File:Release_01.jpg\" title=\"File:Release 01.jpg\"> In-game map</a></li>\n<li><a class=\"external text\" href=\"https://drive.google.com/drive/folders/0B6J_aGQ6URL8dW96YXB3dldhZDA\" rel=\"nofollow\">Map dumps</a></li>\n<li>For community maps, see <a href=\"/index.php/Maps\" title=\"Maps\">Maps</a></li></ul>', 2),
(4745, 1180, 'Statistics', 'Statistics', 'Server status Server statistics See server graphs for the statistics of all servers.', '<ul><li><a class=\"external text\" href=\"http://release.game.wurmonline.com/battles/stats.html\" rel=\"nofollow\">Server status</a></li>\n<li><a class=\"external text\" href=\"http://release.game.wurmonline.com/mrtg/\" rel=\"nofollow\">Server statistics</a></li>\n<li>See <a href=\"/index.php/Server_graphs\" title=\"Server graphs\">server graphs</a> for the statistics of all servers.<i></i></li></ul>', 3),
(4746, 1179, 'Spawn settlements', 'Spawn_settlements', 'Blossom', '<ul><li><a href=\"/index.php/Settlement:Blossom\" title=\"Settlement:Blossom\">Blossom</a></li></ul>', 0),
(4747, 1179, 'Travel', 'Travel', 'This island may be reached by sailing north from Release . You may sail west to Xanadu , or south to Release . Pristine can also be reached from any Southern Isle server by using plot course .', '<p>This island may be reached by sailing north from <a href=\"/index.php/Release\" title=\"Release\">Release</a>. You may sail west to <a href=\"/index.php/Xanadu\" title=\"Xanadu\">Xanadu</a>, or south to <a href=\"/index.php/Release\" title=\"Release\">Release</a>. Pristine can also be reached from any Southern Isle server by using <a href=\"/index.php/Server_travel\" title=\"Server travel\">plot course</a>. \n</p>', 1),
(4748, 1179, 'Maps', 'Maps', 'In-game map Map dumps For community maps, see Maps', '<ul><li><a href=\"/index.php/File:Pristine_01.jpg\" title=\"File:Pristine 01.jpg\"> In-game map</a></li>\n<li><a class=\"external text\" href=\"https://drive.google.com/drive/folders/0B6J_aGQ6URL8cTV5QnBfcEpXbEU\" rel=\"nofollow\">Map dumps</a></li>\n<li>For community maps, see <a href=\"/index.php/Maps\" title=\"Maps\">Maps</a></li></ul>', 2),
(4749, 1179, 'Statistics', 'Statistics', 'Server status Server statistics See server graphs for the statistics of all servers.', '<ul><li><a class=\"external text\" href=\"http://pristine.game.wurmonline.com/battles/stats.html\" rel=\"nofollow\">Server status</a></li>\n<li><a class=\"external text\" href=\"http://pristine.game.wurmonline.com/mrtg/\" rel=\"nofollow\">Server statistics</a></li>\n<li>See <a href=\"/index.php/Server_graphs\" title=\"Server graphs\">server graphs</a> for the statistics of all servers.<i></i></li></ul>', 3),
(4750, 1107, 'Description', 'Description', 'A small, carefully crafted wooden barrel with the sole purpose to store precious wine.', '<p><i>A small, carefully crafted wooden barrel with the sole purpose to store precious wine.</i>\n</p>', 0),
(4751, 1107, 'Notes', 'Notes', 'Holds up to 45kg of liquid or items . Can be sealed with a wood scrap to ferment alcoholic beverages inside. Activate the wood scrap, right-click the filled wine barrel and select create , then the fermenting beverage. You may unseal the barrel only when it is fully fermented. Can be sealed with a peg to stop decay of the contents. This seal can be undone at any time, destroying the peg. Note that sealing the barrel in this way will not ferment beverages. It has a capacity of 45ℓ. It is the quality of the small nails that determines the success rate. If the initial creation fails, the nails and the plank are damaged. The barrel\'s wood type is dictated by the type of plank you attach last. Any barrel will allow aging to occur, but oak benefits from a slight bonus for aging. Some items may be placed on top of the barrel, as decoration. Since the item is a container already, any items placed on it will be dropped on the ground when it is picked up; a message in event log will notify the player of this.', '<ul><li>Holds up to 45kg of <a href=\"/index.php/Liquid\" title=\"Liquid\">liquid</a> or <a href=\"/index.php/Item\" title=\"Item\">items</a>.</li>\n<li>Can be sealed with a <a href=\"/index.php/Wood_scrap\" title=\"Wood scrap\">wood scrap</a> to ferment <a href=\"/index.php/Alcohol\" title=\"Alcohol\">alcoholic beverages</a> inside. Activate the wood scrap, right-click the filled wine barrel and select <i>create</i>, then the fermenting beverage.\n<ul><li>You may unseal the barrel only when it is fully fermented.</li></ul></li>\n<li>Can be sealed with a <a href=\"/index.php/Peg\" title=\"Peg\">peg</a> to stop decay of the contents.\n<ul><li>This seal can be undone at any time, destroying the peg.</li>\n<li>Note that sealing the barrel in this way will not ferment beverages.</li></ul></li>\n<li>It has a capacity of 45ℓ.</li>\n<li>It is the quality of the small nails that determines the success rate.</li>\n<li>If the initial creation fails, the nails and the plank are damaged.</li>\n<li>The barrel\'s <a href=\"/index.php/Wood\" title=\"Wood\">wood</a> type is dictated by the type of plank you attach last.</li>\n<li>Any barrel will allow aging to occur, but oak benefits from a slight bonus for aging.</li>\n<li>Some items may be placed on top of the barrel, as decoration. Since the item is a container already, any items placed on it will be dropped on the ground when it is picked up; a message in event log will notify the player of this.</li></ul>', 1),
(4752, 1107, 'See Also', 'See_Also', 'Large barrel Small barrel', '<ul><li><a href=\"/index.php/Large_barrel\" title=\"Large barrel\">Large barrel</a></li>\n<li><a href=\"/index.php/Small_barrel\" title=\"Small barrel\">Small barrel</a></li></ul>', 2),
(4769, 1233, 'Informational messages', 'Informational_messages', 'These messages do not prevent mining but inform the player of the result of their actions should mining continue.  These may be intentional or otherwise. The cave walls sound hollow. This appears when mining into another shaft and the height difference is not dangerous.', '<p>These messages do not prevent mining but inform the player of the result of their actions should mining continue.  These may be intentional or otherwise.\n</p>\n<dl><dt>The cave walls sound hollow. </dt>\n<dd>This appears when mining into another shaft and the height difference is not dangerous.</dd></dl>', 0),
(4770, 1233, 'Preventative messages', 'Preventative_messages', 'Mining will be no longer possible when receiving one of the following messages: Side shaft You hear crumbling on the other side of the wall and the floor starts to crack. The shaft would be too steep and unstable. This message appears when undermining previous tile mined above, as in a steep upwards dropshaft would be created. There is no fix for this, though mining another wall, and changing tunnel direction, may work. Going from the other side down should work. A <item name> on the surface disturbs your operation. This message appears when an item like a felled tree, an altar, a forge, large chest or other item is on the surface over or near the tile where you are attempting to mine or tunnel. Move the item to proceed. A surface highway interferes with your tunneling operation. This message appears when tunneling would break through a highway on the surface. The current tile needs a flat border level with the bottom of the adjacent cave entrance. This message appears when you need to surface mine the bottom slope of the adjacent tile to match the slope of the mine entrance, only when creating a multi-tile entrance. The current tile needs to face the same direction as the adjacent cave entrance. Adjacent entrance tiles must all face the same direction. Lowering the floor further with such a high ceiling would make the cavern unstable. This message appears when the ceiling is too high above the floor. The cave walls echo strangely. There must be an open tunnel diagonal from the wall you are mining, and you would need to approach it from a different direction. This message appears when the tile being mined shares a single corner with an existing tunnel. To continue, adjacent tiles must be mined out before mining can continue on this tile. See example on the right. The cave walls look very unstable. Mining here would open a cave exit, but there aren\'t enough solid walls to support it, so you stop mining. This message appears when mining close to the top of the rock layer. The ceiling of the newly mined tile would break the rock layer in a way that would try to form an impossible entrance. This can sometimes be avoided by mining downwards or by lowering the mine floor and opening the new tile a bit lower. The cave walls look very unstable and dirt flows in. Mining here would open a cave exit, but the dirt above would bury you alive, so you stop mining. This message appears when the tile being mined will break out to the surface, but the surface is not exposed rock. To open the entrance, the rock on the surface must be fully exposed. To continue mining forward this can sometimes be avoided by mining downwards or by lowering the mine floor and opening the new tile a bit lower. The ceiling is too close. Occurs when using concrete to raise a floor tile that is less than 20 distance from the ceiling. The ground is too steep to mine at here. You need to make it more flat. This message appears occasionally when mining the floor down.  The cause is unknown. You cannot create a tunnel here. The ground sounds strangely hollow, and there must be open space under the surface that would make the entrance unstable. This message appears when there\'s already a tunnel on the tile being tunneled. An entrance cannot be mined here. You hear crumbling beneath your feet. The tunnel to the open cave underneath would be far too steep and unstable. Occurs when opening a new tunnel from the surface. This message appears when there is already a tunnel to the back or the sides of the entrance tile or if a tunnel is ahead but too far down to connect to. Surface mine down to reduce the slopes, then attempt to tunnel again. The mountainside would risk crumbling. You can\'t open a tunnel on a surface this steep. This message appears when attempting to create a mine entrance on a rock tile that is too steep.  The maximum slope is 270. You realize you can\'t open a tunnel here, because the surface is too flat. This message appears when trying to create a mine entrance on a perfectly flat rock tile. One corner must be lowered with surface mining to continue. This can also occur if both corners nearest the lowest corner are the same height. Has also been reported underground, probably when mining that tile would create a flat mine entrance.  Mining downwards may work in this case. You notice dirt flowing in, so you stop mining. Breaking through the ceiling here would bury you alive. This message appears when mining the ceiling too close to the surface and it is not dug to rock on the surface. The water is too deep to mine here. This message appears when trying to mine too far under the water table. Also occurs when trying to open a tunnel in which the northwest corner of the tile being mined is at or more than 12 dirts below the water table. The roof sounds dangerously weak and you stop mining. It must be too close to the rock surface to continue. This message indicates the rock layer above is very close to the ceiling, so there is no more room to mine further. The rock sounds hollow, and you would breach a cave ceiling. You need to tunnel to proceed. This message appears when trying to surface mine above an open tile underground, and you are already at the ceiling height of the mine. You are not allowed to remove that reinforcement. This message appears when you have tried to mine into a reinforced tile that you do not have permission to remove. The cave wall is already destroyed, so you stop mining. This message appears after a wall breaks and you still have mining actions left in your action queue (trying to mine thin air). This tile is protected by the gods. You can not mine here. This message appears when a GM protected highway tile above the tile that is being mined. There is no space to mine here. Clear the area first. This message appears when the tile occupied by the player contains 100 items.  Clear the area or move the character onto another tile and make a new pile of shards. You cannot have cave entrances meeting diagonally. This message appears when there is another cave entrance diagonally. It can be two tiles away from the tile giving the message. Mine out the adjacent tiles, so you can connect the two entrances by a tunnel. You fail to produce anything here. The rock is stone hard. This message appears when tunneling on the surface. This means the tile you are attempting to excavate is actually an ore vein. There\'s nothing to do about it, you simply have to make your entrance on another tile. Note that if you make the entrance one tile below the vein, the tunnel will open right into the vein and cannot be extended until the vein is depleted. The best course of action at this point would probably be to mine out a rock tile next to the one you get this message on. You hear falling rocks from the other side of the wall. A deep shaft will probably emerge. This message appears when there is already another mine nearby, but there is too much of a height difference to connect the two mines. You cannot create a tunnel here. The stone under the surface is something harder than normal rock. This message appears when attempting to open a tunnel directly onto a vein, a reinforced tile or a rock tile with salt. You are not allowed to mine here. Deed permissions have disabled mining. (PvP deeds may require at least one spirit templar to uphold the law.) You are not skilled enough to mine on such steep slopes. This message appears when trying to surface mine higher than your skill allows. Freedom Formula: 3 x Mining Skill. Epic Formula: 1 x Mining Skill (Not-curved). You cannot reach the ceiling. Occurs when trying to mine the cave ceiling that is more than 61 height away from the floor. You need at least 21 Mining skill to install a stone or metal mine door. Occurs when attempting to install a metal or stone mine door without 21 Mining skill', '<p>Mining will be no longer possible when receiving one of the following messages:\n</p>\n<div class=\"thumb tright\"><div class=\"thumbinner\" style=\"width:173px;\"><a class=\"image\" href=\"/index.php/File:Sideshaft.png\"><img alt=\"\" class=\"thumbimage\" data-file-height=\"265\" data-file-width=\"171\" decoding=\"async\" height=\"265\" src=\"/images/7/76/Sideshaft.png\" width=\"171\"/></a> <div class=\"thumbcaption\">Side shaft</div></div></div>\n<dl><dt>You hear crumbling on the other side of the wall and the floor starts to crack. The shaft would be too steep and unstable.</dt>\n<dd>This message appears when undermining previous tile mined above, as in a steep upwards dropshaft would be created. There is no fix for this, though mining another wall, and changing tunnel direction, may work. Going from the other side down should work.</dd></dl>\n<dl><dt>A <i>&lt;item name&gt;</i> on the surface disturbs your operation.</dt>\n<dd>This message appears when an item like a felled tree, an altar, a forge, large chest or other item is on the surface over or near the tile where you are attempting to mine or tunnel. Move the item to proceed.</dd></dl>\n<dl><dt>A surface highway interferes with your tunneling operation.</dt>\n<dd>This message appears when tunneling would break through a highway on the surface.</dd></dl>\n<dl><dt>The current tile needs a flat border level with the bottom of the adjacent cave entrance.</dt>\n<dd>This message appears when you need to surface mine the bottom slope of the adjacent tile to match the slope of the mine entrance, only when creating a multi-tile entrance.</dd></dl>\n<dl><dt>The current tile needs to face the same direction as the adjacent cave entrance.</dt>\n<dd>Adjacent entrance tiles must all face the same direction.</dd></dl>\n<dl><dt>Lowering the floor further with such a high ceiling would make the cavern unstable.</dt>\n<dd>This message appears when the ceiling is too high above the floor.</dd></dl>\n<dl><dt>The cave walls echo strangely. There must be an open tunnel diagonal from the wall you are mining, and you would need to approach it from a different direction.</dt>\n<dd>This message appears when the tile being mined shares a single corner with an existing tunnel. To continue, adjacent tiles must be mined out before mining can continue on this tile. See example on the right.</dd></dl>\n<dl><dt>The cave walls look very unstable. Mining here would open a cave exit, but there aren\'t enough solid walls to support it, so you stop mining.</dt>\n<dd>This message appears when mining close to the top of the rock layer. The ceiling of the newly mined tile would break the rock layer in a way that would try to form an impossible entrance. This can sometimes be avoided by mining downwards or by lowering the mine floor and opening the new tile a bit lower.</dd></dl>\n<dl><dt>The cave walls look very unstable and dirt flows in. Mining here would open a cave exit, but the dirt above would bury you alive, so you stop mining.</dt>\n<dd>This message appears when the tile being mined will break out to the surface, but the surface is not exposed rock. To open the entrance, the rock on the surface must be fully exposed. To continue mining forward this can sometimes be avoided by mining downwards or by lowering the mine floor and opening the new tile a bit lower.</dd></dl>\n<dl><dt>The ceiling is too close.</dt>\n<dd>Occurs when using concrete to raise a floor tile that is less than 20 distance from the ceiling.</dd>\n<dt>The ground is too steep to mine at here. You need to make it more flat.</dt>\n<dd>This message appears occasionally when mining the floor down.  The cause is unknown.</dd></dl>\n<dl><dt>You cannot create a tunnel here. The ground sounds strangely hollow, and there must be open space under the surface that would make the entrance unstable.</dt>\n<dd>This message appears when there\'s already a tunnel on the tile being tunneled. An entrance cannot be mined here.</dd></dl>\n<dl><dt>You hear crumbling beneath your feet. The tunnel to the open cave underneath would be far too steep and unstable.</dt>\n<dd>Occurs when opening a new tunnel from the surface. This message appears when there is already a tunnel to the back or the sides of the entrance tile or if a tunnel is ahead but too far down to connect to. Surface mine down to reduce the slopes, then attempt to tunnel again.</dd></dl>\n<dl><dt>The mountainside would risk crumbling. You can\'t open a tunnel on a surface this steep.</dt>\n<dd>This message appears when attempting to create a mine entrance on a rock tile that is too steep.  The maximum slope is 270.</dd></dl>\n<dl><dt>You realize you can\'t open a tunnel here, because the surface is too flat.</dt>\n<dd>This message appears when trying to create a mine entrance on a perfectly flat rock tile. One corner must be lowered with surface mining to continue.<br/>This can also occur if both corners nearest the lowest corner are the same height.<br/>Has also been reported underground, probably when mining that tile would create a flat mine entrance.  Mining downwards may work in this case.</dd></dl>\n<dl><dt>You notice dirt flowing in, so you stop mining. Breaking through the ceiling here would bury you alive.</dt>\n<dd>This message appears when mining the ceiling too close to the surface and it is not dug to rock on the surface.</dd></dl>\n<dl><dt>The water is too deep to mine here.</dt>\n<dd>This message appears when trying to mine too far under the water table.</dd>\n<dd>Also occurs when trying to open a tunnel in which the northwest corner of the tile being mined is at or more than 12 dirts below the water table.</dd></dl>\n<dl><dt>The roof sounds dangerously weak and you stop mining. It must be too close to the rock surface to continue.</dt>\n<dd>This message indicates the rock layer above is very close to the ceiling, so there is no more room to mine further.</dd></dl>\n<dl><dt>The rock sounds hollow, and you would breach a cave ceiling. You need to tunnel to proceed.</dt>\n<dd>This message appears when trying to <a href=\"/index.php/Surface_mining\" title=\"Surface mining\">surface mine</a> above an open tile underground, and you are already at the ceiling height of the mine.</dd></dl>\n<dl><dt>You are not allowed to remove that reinforcement.</dt>\n<dd>This message appears when you have tried to mine into a reinforced tile that you do not have permission to remove.</dd></dl>\n<dl><dt>The cave wall is already destroyed, so you stop mining.</dt>\n<dd>This message appears after a wall breaks and you still have mining actions left in your action queue (trying to mine thin air).</dd></dl>\n<dl><dt>This tile is protected by the gods. You can not mine here.</dt>\n<dd>This message appears when a GM protected highway tile above the tile that is being mined.</dd></dl>\n<dl><dt>There is no space to mine here. Clear the area first.</dt>\n<dd>This message appears when the tile occupied by the player contains 100 items.  Clear the area or move the character onto another tile and make a new pile of shards.</dd></dl>\n<dl><dt>You cannot have cave entrances meeting diagonally.</dt>\n<dd>This message appears when there is another cave entrance diagonally. It can be two tiles away from the tile giving the message. Mine out the adjacent tiles, so you can connect the two entrances by a tunnel.</dd></dl>\n<dl><dt>You fail to produce anything here. The rock is stone hard.</dt>\n<dd>This message appears when tunneling on the surface. This means the tile you are attempting to excavate is actually an ore vein. There\'s nothing to do about it, you simply have to make your entrance on another tile.</dd></dl>\n<p><i>Note that if you make the entrance one tile below the vein, the tunnel will open right into the vein and cannot be extended until the vein is depleted. The best course of action at this point would probably be to mine out a rock tile next to the one you get this message on.</i>\n</p>\n<dl><dt>You hear falling rocks from the other side of the wall. A deep shaft will probably emerge.</dt>\n<dd>This message appears when there is already another mine nearby, but there is too much of a height difference to connect the two mines.</dd></dl>\n<dl><dt>You cannot create a tunnel here. The stone under the surface is something harder than normal rock.</dt>\n<dd>This message appears when attempting to open a tunnel directly onto a vein, a reinforced tile or a rock tile with salt.</dd></dl>\n<dl><dt>You are not allowed to mine here.</dt>\n<dd>Deed permissions have disabled mining. (PvP deeds may require at least one <a href=\"/index.php/Spirit_templar\" title=\"Spirit templar\">spirit templar</a> to uphold the law.)</dd></dl>\n<dl><dt>You are not skilled enough to mine on such steep slopes.</dt>\n<dd>This message appears when trying to surface mine higher than your skill allows. Freedom Formula: 3 x Mining Skill. Epic Formula: 1 x Mining Skill (Not-curved).</dd></dl>\n<dl><dt>You cannot reach the ceiling.</dt>\n<dd>Occurs when trying to mine the cave ceiling that is more than 61 height away from the floor.</dd></dl>\n<dl><dt>You need at least 21 Mining skill to install a stone or metal mine door.</dt>\n<dd>Occurs when attempting to install a metal or stone mine door without 21 Mining skill</dd></dl>', 1),
(4771, 1150, 'Description', 'Description', 'Lots of different sized slate shards.', '<p><i>Lots of different sized slate shards.</i>\n</p>', 0),
(4772, 1150, 'Notes', 'Notes', 'Slate shards are mostly used in masonry for building walls, roofs, and paved floors and roads. Shards can be discarded by right-clicking, and selecting \'Discard\'. This will dispose of them immediately. Can be foraged from Rubble Resource nodes', '<ul><li>Slate shards are mostly used in <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> for building walls, roofs, and  <a href=\"/index.php/Paving\" title=\"Paving\">paved</a> floors and roads.</li>\n<li>Shards can be discarded by right-clicking, and selecting \'Discard\'. This will dispose of them immediately.</li>\n<li>Can be foraged from <a href=\"/index.php/Rubble\" title=\"Rubble\">Rubble</a> <a href=\"/index.php/Resource_nodes\" title=\"Resource nodes\">Resource nodes</a></li></ul>', 1),
(4773, 1150, 'See also', 'See_also', 'Stone shards Marble shards Sandstone shards', '<ul><li><a href=\"/index.php/Stone_shards\" title=\"Stone shards\">Stone shards</a></li>\n<li><a href=\"/index.php/Marble_shards\" title=\"Marble shards\">Marble shards</a></li>\n<li><a href=\"/index.php/Sandstone_shards\" title=\"Sandstone shards\">Sandstone shards</a></li></ul>', 2),
(4774, 1149, 'Description', 'Description', 'Lots of different sized marble shards.', '<p><i>Lots of different sized marble shards.</i>\n</p>\n<p><br/>\n</p>', 0),
(4775, 1149, 'Notes', 'Notes', 'Marble shards can be used in creating marble keystones for bridges, marble bricks , and marble slabs for floors and roads. You can also find marble shards while foraging on Rubble .', '<ul><li>Marble shards can be used in creating <a class=\"mw-redirect\" href=\"/index.php/Marble_keystone\" title=\"Marble keystone\">marble keystones</a> for bridges, <a href=\"/index.php/Marble_brick\" title=\"Marble brick\">marble bricks</a>, and <a href=\"/index.php/Marble_slab\" title=\"Marble slab\">marble slabs</a> for floors and roads.</li>\n<li>You can also find marble shards while <a href=\"/index.php/Foraging\" title=\"Foraging\">foraging</a> on <a href=\"/index.php/Rubble\" title=\"Rubble\">Rubble</a>.</li></ul>', 1),
(4776, 1149, 'See also', 'See_also', 'Category:Marble items Stone shards Slate shards Sandstone shards', '<ul><li><a href=\"/index.php/Category:Marble_items\" title=\"Category:Marble items\">Category:Marble items</a></li>\n<li><a href=\"/index.php/Stone_shards\" title=\"Stone shards\">Stone shards</a></li>\n<li><a href=\"/index.php/Slate_shards\" title=\"Slate shards\">Slate shards</a></li>\n<li><a href=\"/index.php/Sandstone_shards\" title=\"Sandstone shards\">Sandstone shards</a></li></ul>', 2),
(4792, 1173, 'Description', 'Description', 'You see a strong wooden parapet', '<p><i>You see a strong wooden parapet</i>\n</p>', 0),
(4793, 1173, 'Notes', 'Notes', 'Wooden parapets currently block archery while target shooting.  However, it is still possible to use archery against a living target.', '<ul><li>Wooden parapets currently block archery while target shooting.  However, it is still possible to use archery against a living target.</li></ul>', 1),
(4832, 1249, 'Description', 'Description', 'The most nutritious type of food. When eaten hot it gives more nutrition.', '<p>The most nutritious type of food. When eaten hot it gives more nutrition.\n</p>', 0),
(4833, 1249, 'Method', 'Method', 'A basic meal consists of meat / fish and potato / corn / onion / pumpkin (commonly referred to as vegetables) or rice that you heat up in a frying pan. Do not use fish and meat at the same time as that will only make a stew. If there are no vegetables available, they can be substituted by bread. Adding salt halves the meal\'s decay rate. Examine the frying pan before cooking to determine the difficulty and whether or not it will become a meal. Herbs, cheese, and some other foraged and harvested items can be added for additional difficulty. Typically the more ingredients a meal has the more difficult it will be to cook.\nBerries added to the frypan will produce stew instead of a meal. Meals have higher base difficulty than other dishes, so at low HFC skill it is recommended to use stone ovens when cooking them. If difficulty isn\'t an issue, any fire source can be used. Experienced cooks will sometimes use campfires or stone forges to intentionally increase the difficulty and therefore their skill gain.\nAdded difficulty: Oven 0 Campfire 5 Forge 10 The base QL of a meal is your hot food cooking skill, and at lower skill it will match this most of the time. As hot food cooking becomes higher, it also becomes harder and harder to maintain maximum quality. When it exceeds 70, the meal QL will drop and become more dependent on the ql of the items and the difficulty of making it (the easier the meal, the higher QL meal made). Requirements Fire source Campfire, Stone forge, Stone oven Cooking implement Frying pan Meat part Either meat or fish (regular or fillet) Vegetable part Potato, corn, onion, rice or pumpkin. Alternatively: bread. Resulting Product 1x meal Skills used Hot food cooking', '<p>A basic meal consists of meat / fish and potato / corn / onion / pumpkin (commonly referred to as vegetables) or rice that you heat up in a frying pan. Do not use fish and meat at the same time as that will only make a stew.\n</p>\n<p>If there are no vegetables available, they can be substituted by bread. Adding salt halves the meal\'s decay rate.\n</p>\n<p>Examine the frying pan before cooking to determine the difficulty and whether or not it will become a meal. Herbs, cheese, and some other foraged and harvested items can be added for additional difficulty. Typically the more ingredients a meal has the more difficult it will be to cook.\nBerries added to the frypan will produce stew instead of a meal.\n</p>\n<p>Meals have higher base difficulty than other dishes, so at low HFC skill it is recommended to use stone ovens when cooking them. If difficulty isn\'t an issue, any fire source can be used. Experienced cooks will sometimes use campfires or stone forges to intentionally increase the difficulty and therefore their skill gain.\nAdded difficulty:\n</p>\n<ul><li>Oven 0</li>\n<li>Campfire 5</li>\n<li>Forge 10</li></ul>\n<p><br/>\nThe base QL of a meal is your hot food cooking skill, and at lower skill it will match this most of the time. As hot food cooking becomes higher, it also becomes harder and harder to maintain maximum quality. When it exceeds 70, the meal QL will drop and become more dependent on the ql of the items and the difficulty of making it (the easier the meal, the higher QL meal made).\n</p>\n<h3><span class=\"mw-headline\" id=\"Requirements\">Requirements</span></h3>\n<dl><dt>Fire source</dt>\n<dd>Campfire, Stone forge, Stone oven</dd>\n<dt>Cooking implement</dt>\n<dd>Frying pan</dd>\n<dt>Meat part</dt>\n<dd>Either meat or fish (regular or fillet)</dd>\n<dt>Vegetable part</dt>\n<dd>Potato, corn, onion, rice or pumpkin.</dd>\n<dd>Alternatively: bread.</dd></dl>\n<h3><span class=\"mw-headline\" id=\"Resulting_Product\">Resulting Product</span></h3>\n<ul><li>1x <b>meal</b></li></ul>\n<h3><span class=\"mw-headline\" id=\"Skills_used\">Skills used</span></h3>\n<ul><li>Hot food cooking</li></ul>', 1),
(4834, 1249, 'Some Recipes and Difficulty (2016 April 27)', 'Some_Recipes_and_Difficulty_.282016_April_27.29', 'Meat + Onion = 22 difficulty Meat + Onion + Corn = 25 difficulty Meat + Onion + Potato = 25 difficulty Meat + Corn = 27 difficulty Meat + Potato = 27 difficulty Meat + Rice = 27 difficulty Meat + Onion + Pumpkin = 28 difficulty Meat + Pumpkin = 30 difficulty Meat + Bread = 30 difficulty Meat + Corn + Onion + Cheese = 32 difficulty Meat + Corn + Rice = 33 difficulty Meat + Potato + Rice = 33 difficulty Meat + Pumpkin + Potato = 33 difficulty Meat + Pumpkin + Corn = 33 difficulty Meat + Pumpkin + Grain = 33 difficulty Meat + Pumpkin + Corn + Potato + Onion = 39 difficulty Meat + Corn + Onion + Cheese + Grain = 39 difficulty Meat + Pumpkin + Corn + Potato = 40 difficulty Meat + Pumpkin + Corn + Rice = 40 difficulty', '<ul><li>Meat + Onion = 22 difficulty</li>\n<li>Meat + Onion + Corn = 25 difficulty</li>\n<li>Meat + Onion + Potato = 25 difficulty</li>\n<li>Meat + Corn = 27 difficulty</li>\n<li>Meat + Potato = 27 difficulty</li>\n<li>Meat + Rice = 27 difficulty</li>\n<li>Meat + Onion + Pumpkin = 28 difficulty</li>\n<li>Meat + Pumpkin = 30 difficulty</li>\n<li>Meat + Bread = 30 difficulty</li>\n<li>Meat + Corn + Onion + Cheese = 32 difficulty</li>\n<li>Meat + Corn + Rice = 33 difficulty</li>\n<li>Meat + Potato + Rice = 33 difficulty</li>\n<li>Meat + Pumpkin + Potato = 33 difficulty</li>\n<li>Meat + Pumpkin + Corn = 33 difficulty</li>\n<li>Meat + Pumpkin + <a class=\"mw-redirect\" href=\"/index.php/Grain\" title=\"Grain\">Grain</a> = 33 difficulty</li>\n<li>Meat + Pumpkin + Corn + Potato + Onion = 39 difficulty</li>\n<li>Meat + Corn + Onion + Cheese + Grain = 39 difficulty</li>\n<li>Meat + Pumpkin + Corn + Potato = 40 difficulty</li>\n<li>Meat + Pumpkin + Corn + Rice = 40 difficulty</li></ul>', 2),
(4835, 1249, 'Additional notes', 'Additional_notes', 'Meals decay very fast in inventories. You\'re better off storing them in a larder. They do take damage in your inventory even if you are logged off.', '<ul><li>Meals decay very fast in inventories. You\'re better off storing them in a larder.</li>\n<li>They do take damage in your inventory even if you are logged off.</li></ul>', 3),
(4850, 960, 'Description', 'Description', 'Drakespirits are usually found in their gardens on Valrei. They are hungry and aggressive. Spawned by the Gods on Valrei . They can be seen in Wurm world flying around, stalking their prey.', '<p><i>Drakespirits are usually found in their gardens on Valrei. They are hungry and aggressive.</i>\n</p>\n<p>Spawned by the Gods on <a href=\"/index.php/Valrei_(moon)\" title=\"Valrei (moon)\">Valrei</a>. They can be seen in Wurm world flying around, stalking their prey.\n</p>', 0),
(4851, 960, 'Abilities', 'Abilities', 'Can swim. Can climb everything. Large (15+ tiles) aggro range. Has slashing, biting, hitting, tailwhip and wingbuff attacks. Has stun area effect with a 1-2 tiles range, which deals internal wounds . Hits very quickly. Cannot be tamed . Cannot be hitched . Can bash down fences when penned. Will starve if not fed (similar to a chicken). Lays eggs when fed (similar to a hen - eggs indistinguishable from those of a chicken). Holds its own very nicely versus 3-4 Tower Guards', '<ul><li>Can swim.</li>\n<li>Can climb everything.</li>\n<li>Large (15+ tiles) aggro range.</li>\n<li>Has slashing, biting, hitting, tailwhip and wingbuff attacks.</li>\n<li>Has stun area effect with a 1-2 tiles range, which deals internal <a href=\"/index.php/Wound\" title=\"Wound\">wounds</a>.</li>\n<li>Hits very quickly.</li>\n<li>Cannot be <a class=\"mw-redirect\" href=\"/index.php/Taming\" title=\"Taming\">tamed</a>.</li>\n<li>Cannot be <a href=\"/index.php/Large_cart\" title=\"Large cart\">hitched</a>.</li>\n<li>Can bash down <a href=\"/index.php/Fence\" title=\"Fence\">fences</a> when penned.</li>\n<li>Will starve if not fed (similar to a chicken).</li>\n<li>Lays eggs when fed (similar to a hen - eggs indistinguishable from those of a chicken).</li>\n<li>Holds its own very nicely versus 3-4 Tower Guards</li></ul>', 1),
(4852, 960, 'Drops', 'Drops', 'Drakespirits do not leave a corpse when they die. Instead they leave a pile of items which includes a Valrei item such as: Burning Harp Deadly Spirit Frozen Token Lustrous Diamond Lustrous Shard Shadow Opal Shiny Circlet Shiny Jewel Silvery Crystal Silvery Token Soulstruck Opal Soulstruck Token These items all share the same description: A weird item belonging on Valrei. , but appear to be a different pool of items from Spawn of Uttacha .', '<p>Drakespirits do not leave a corpse when they die. Instead they leave a pile of items which includes a <a href=\"/index.php/Valrei_item\" title=\"Valrei item\">Valrei item</a> such as:\n</p>\n<ul><li>Burning Harp</li>\n<li>Deadly Spirit</li>\n<li>Frozen Token</li>\n<li>Lustrous Diamond</li>\n<li>Lustrous Shard</li>\n<li>Shadow Opal</li>\n<li>Shiny Circlet</li>\n<li>Shiny Jewel</li>\n<li>Silvery Crystal</li>\n<li>Silvery Token</li>\n<li>Soulstruck Opal</li>\n<li>Soulstruck Token</li></ul>\n<p>These items all share the same description: <i>A weird item belonging on Valrei.</i>, but appear to be a different pool of items from <a href=\"/index.php/Spawn_of_Uttacha\" title=\"Spawn of Uttacha\">Spawn of Uttacha</a>.\n</p>', 2),
(4857, 1257, 'Description', 'Description', 'By following the steps below, you can create custom toolbelt profiles, which you can use to switch swiftly between sets of tools.', '<p>By following the steps below, you can create custom <a href=\"/index.php/Toolbelt\" title=\"Toolbelt\">toolbelt</a> profiles, which you can use to switch swiftly between sets of tools.\n</p>', 0),
(4858, 1257, 'Overview', 'Overview', 'By using the command \"settoolbelt\" you can set any toolbelt slot to any item. You need to know the unique item id for this (which is a large number).', '<p>By using the command \"settoolbelt\" you can set any toolbelt slot to any item. You need to know the unique item id for this (which is a large number).\n</p>', 1),
(4859, 1257, 'Steps', 'Steps', 'In the following section \"~/wurm\" is used to denote the directory where your wurm data is stored. Under Windows, this is probably \"C:\\users\\<username>\\wurm\", under Linux, it is mostly \"/home/<username>/wurm\". 1) Set your toolbelt up in the way you want it in Wurm. Note which tool is in which slot (numbered from the left, starting with 1). Quit the game. 2) Open the file \"~/wurm/players/<wurm playername>/playerdata.txt\". This contains a number of lines that look like toolSlot<X>=<number> Remember the order from step 1, write down which <number> corresponds to which tool. 3) Create a new file \"~/wurm/configs/default/blacksmithing.txt\" (or any other name you want in that directory). Insert as many lines for setting the toolbelt (and custom keybindings and whatever else you want) as follows: settoolbelt <number> 1 // <comment describing the tool>\n settoolbelt 266029938770434 2 // mallet\n settoolbelt 812487435879682 3 // file\n ... 4) Restart Wurm. Open the console (by default bound to F1). Type bind Alt+1 \"exec blacksmithing.txt\" You can use any other keybinding you want, and use any other file.', '<p>In the following section \"~/wurm\" is used to denote the directory where your wurm data is stored. Under Windows, this is probably \"C:\\users\\&lt;username&gt;\\wurm\", under Linux, it is mostly \"/home/&lt;username&gt;/wurm\".\n</p>\n<p>1) Set your toolbelt up in the way you want it in Wurm. Note which tool is in which slot (numbered from the left, starting with 1). Quit the game.\n</p>\n<p>2) Open the file \"~/wurm/players/&lt;wurm playername&gt;/playerdata.txt\". This contains a number of lines that look like \n</p>\n<pre> toolSlot&lt;X&gt;=&lt;number&gt;\n</pre>\n<p>Remember the order from step 1, write down which &lt;number&gt; corresponds to which tool.\n</p>\n<p>3) Create a new file \"~/wurm/configs/default/blacksmithing.txt\" (or any other name you want in that directory). Insert as many lines for setting the toolbelt (and custom keybindings and whatever else you want) as follows:\n</p>\n<pre> settoolbelt &lt;number&gt; 1 // &lt;comment describing the tool&gt;\n settoolbelt 266029938770434 2 // mallet\n settoolbelt 812487435879682 3 // file\n ...\n</pre>\n<p>4) Restart Wurm. Open the console (by default bound to F1). Type \n</p>\n<pre> bind Alt+1 \"exec blacksmithing.txt\"\n</pre>\n<p>You can use any other keybinding you want, and use any other file.\n</p>', 2),
(4860, 1257, 'References', 'References', 'Also see http://www.youtube.com/watch?v=__T9ExMnjAI and http://forum.wurmonline.com/index.php?/topic/57806-the-settoolbelt-console-command/ for more information.', '<p>Also see <a class=\"external free\" href=\"https://www.youtube.com/watch?v=__T9ExMnjAI\" rel=\"nofollow\">http://www.youtube.com/watch?v=__T9ExMnjAI</a> and <a class=\"external free\" href=\"http://forum.wurmonline.com/index.php?/topic/57806-the-settoolbelt-console-command/\" rel=\"nofollow\">http://forum.wurmonline.com/index.php?/topic/57806-the-settoolbelt-console-command/</a> for more information.\n</p>', 3),
(4871, 1153, 'Description', 'Description', 'It is a normal floor made of slate slab. Floor plan to create slate slab floors for your buildings.', '<p><i>It is a normal floor made of slate slab.</i>\n</p>\n<p>Floor plan to create slate slab floors for your buildings.\n</p>', 0),
(4872, 1153, 'Usage', 'Usage', 'Right-click the floor of the house, select Floor below to create a floor plan Right-click the floor plan select Build and Slate slab floor', '<ul><li>Right-click the floor of the house, select <i>Floor below</i> to create a floor plan</li>\n<li>Right-click the floor plan select <i>Build</i> and <i>Slate slab floor</i></li></ul>', 1),
(4873, 1153, 'Notes', 'Notes', 'Requires 30 paving skill to start.', '<ul><li>Requires 30 paving skill to start.</li></ul>', 2),
(4885, 1256, 'Description', 'Description', 'Levelling is the digging process of taking an adjacent tile to the same level as the one being stood on (the reference tile). The reference tile must be flat;  a tile is considered flat when all four corners are of the same height, which can be seen by examining tile borders. If all 4 borders around a tile are reported as \"level\", the tile is flat.', '<p><b>Levelling</b> is the <a href=\"/index.php/Digging\" title=\"Digging\">digging</a> process of taking an adjacent <a href=\"/index.php/Tile\" title=\"Tile\">tile</a> to the same level as the one being stood on (the reference tile). The reference tile must be flat;  a tile is considered flat when all four corners are of the same height, which can be seen by examining tile borders. If all 4 borders around a tile are reported as \"level\", the tile is flat.\n</p>', 0),
(4886, 1256, 'How to level a tile', 'How_to_level_a_tile', 'When standing on an already flat tile, select the level command by right-clicking on the required adjacent tile with a shovel activated. If the tile to be levelled is lower (or contains less dirt) than the reference tile, dirt (or sand ) must be held in the player inventory to begin. If the tile to be levelled is higher (or contains more dirt) than the reference tile, the player inventory must have space for at least one dirt to begin. This dirt is then dropped or collected automatically to bring the selected tile to the same height as the reference tile.  The process will continue until the tile is level as long as new dirt is brought into the inventory for raising, emptied from the inventory for lowering, or the player runs out of stamina .', '<p>When standing on an already flat tile, select the <b>level</b> command by right-clicking on the required adjacent tile with a <a href=\"/index.php/Shovel\" title=\"Shovel\">shovel</a> activated.\n</p>\n<ul><li>If the tile to be levelled is lower (or contains less dirt) than the reference tile, <a href=\"/index.php/Dirt\" title=\"Dirt\">dirt</a> (or <a class=\"mw-redirect\" href=\"/index.php/Sand\" title=\"Sand\">sand</a>) must be held in the player inventory to begin.</li>\n<li>If the tile to be levelled is higher (or contains more dirt) than the reference tile, the player inventory must have space for at least one dirt to begin.</li></ul>\n<p>This dirt is then dropped or collected automatically to bring the selected tile to the same height as the reference tile.  The process will continue until the tile is level as long as new dirt is brought into the inventory for raising, emptied from the inventory for lowering, or the player runs out of <a class=\"mw-redirect\" href=\"/index.php/Stamina\" title=\"Stamina\">stamina</a>.\n</p>', 1),
(4887, 1256, 'Notes', 'Notes', 'As with flattening , when lowering a tile levelling will stop once rock is found in one corner.  Since levelling typically takes or adds two dirts at a time it is possible to repeatedly select level to remove the one dirt from the corner which has not hit rock. With at least 70 digging skill you can level resource tiles, such as clay or tar , as long as no corner needs to be raised. You will get dirt for lowering the corner instead of the resource. If a corner needs to be raised you will receive the message Some corners can\'t be modified and the levelling action stops. If used on a dirt(or similar) tile, you will lower one corner every 5 seconds. If used on a cave floor tile, you will lower one corner every 10 seconds.', '<ul><li>As with <a class=\"mw-redirect\" href=\"/index.php/Flattening\" title=\"Flattening\">flattening</a>, when lowering a tile levelling will stop once rock is found in one corner.  Since levelling typically takes or adds two dirts at a time it is possible to repeatedly select level to remove the one dirt from the corner which has not hit rock.</li>\n<li>With at least 70 digging skill you can level resource tiles, such as <a href=\"/index.php/Clay\" title=\"Clay\">clay</a> or <a href=\"/index.php/Tar\" title=\"Tar\">tar</a>, as long as no corner needs to be raised. You will get dirt for lowering the corner instead of the resource. If a corner needs to be raised you will receive the message <i>Some corners can\'t be modified</i> and the levelling action stops.</li>\n<li>If used on a dirt(or similar) tile, you will lower one corner every 5 seconds. If used on a cave floor tile, you will lower one corner every 10 seconds.</li></ul>', 2),
(4888, 1256, 'See also', 'See_also', 'Tile types Flattening Flatraising Landbridges Sculpting rock layer with a pickaxe', '<ul><li><a href=\"/index.php/Tile_types\" title=\"Tile types\">Tile types</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Guides/Flattening\" title=\"Guides/Flattening\">Flattening</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Guides/FlatRaising\" title=\"Guides/FlatRaising\">Flatraising</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Guides/Landbridges\" title=\"Guides/Landbridges\">Landbridges</a></li>\n<li><a href=\"/index.php/Mining#Surface_excavation\" title=\"Mining\">Sculpting rock layer with a pickaxe</a></li></ul>', 3),
(4890, 1267, 'Description', 'Description', 'A statue of a proud stallion.', '<p><i>A statue of a proud stallion.</i>\n</p>', 0),
(4891, 1267, 'Notes', 'Notes', 'Statues can be improved with stone shards or marble shards and a stone chisel . Statues cannot be picked up by hand once finished, but can be moved with \'Push\',\'Pull\' and \"Turn\" commands. They can also be moved to the center of a tile, or placed in a certain spot using the \'Place\' command. Statues can be loaded into large carts or wagons (23 body strength required for loading them).', '<p>Statues can be improved with <a href=\"/index.php/Stone_shards\" title=\"Stone shards\">stone shards</a> or <a href=\"/index.php/Marble_shards\" title=\"Marble shards\">marble shards</a> and a <a href=\"/index.php/Stone_chisel\" title=\"Stone chisel\">stone chisel</a>.\n</p>\n<p>Statues cannot be picked up by hand once finished, but can be moved with \'Push\',\'Pull\' and \"Turn\" commands. They can also be moved to the center of a tile, or placed in a certain spot using the \'Place\' command.\n</p>\n<p>Statues can be loaded into large carts or wagons (23 body strength required for loading them).\n</p>', 1),
(4896, 1269, 'Description', 'Description', 'You see a low rope fence. About the same height as a low stone wall.  This is a decorative item and does not restrict passage of players or mobs.', '<p><i>You see a low rope fence.</i>\n</p>\n<p>About the same height as a low stone wall.  This is a decorative item and does not restrict passage of players or mobs.\n</p>', 0),
(4897, 1269, 'Notes', 'Notes', 'Each plank will repair up to 10 damage depending on quality and repairing skill. You must have at least one shaft in your inventory to start building it. You must have all materials in your inventory to complete. Canceling or interrupting the Continue Building action can result in loss of a Shaft .', '<ul><li>Each plank will repair up to 10 damage depending on quality and repairing skill.</li>\n<li>You must have at least one <a href=\"/index.php/Shaft\" title=\"Shaft\">shaft</a> in your <a href=\"/index.php/Inventory\" title=\"Inventory\">inventory</a> to start building it.</li>\n<li>You must have all materials in your inventory to complete.</li>\n<li>Canceling or interrupting the Continue Building action can result in loss of a <a href=\"/index.php/Shaft\" title=\"Shaft\">Shaft</a>.</li></ul>', 1);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(4898, 1269, 'Skill Required', 'Skill_Required', 'To calculate the maximum slope you can build on, based on your carpentry or masonry skill, use the following formula submitted by Ketza : Max slope = (3 * √ skill) + 10 Skill Max Slope 6 17 8 18 9 19 12 20 14 21 16 22 19 23 22 24 25 25 29 26 33 27 36 28 41 29 45 30 49 31 54 32 59 33 64 34 70 35 75 36 81 37 88 38 94 39 Note: Maximum slope is rounded down', '<p>To calculate the <a href=\"/index.php/Maximum_slope\" title=\"Maximum slope\">maximum slope</a> you can build on, based on your <a href=\"/index.php/Carpentry\" title=\"Carpentry\">carpentry</a> or <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill, use the following formula submitted by <a href=\"/index.php/Player:Ketza\" title=\"Player:Ketza\">Ketza</a>:\n</p>\n<p><i>Max slope = (3 *</i> √<i>skill) + 10</i>\n</p>\n<table class=\"wikitable\" style=\"text-align: center;\">\n<tbody><tr>\n<th width=\"100\">Skill\n</th>\n<th width=\"100\">Max Slope\n</th></tr>\n<tr>\n<td>6</td>\n<td>17\n</td></tr>\n<tr>\n<td>8</td>\n<td>18\n</td></tr>\n<tr>\n<td>9</td>\n<td>19\n</td></tr>\n<tr>\n<td>12</td>\n<td>20\n</td></tr>\n<tr>\n<td>14</td>\n<td>21\n</td></tr>\n<tr>\n<td>16</td>\n<td>22\n</td></tr>\n<tr>\n<td>19</td>\n<td>23\n</td></tr>\n<tr>\n<td>22</td>\n<td>24\n</td></tr>\n<tr>\n<td>25</td>\n<td>25\n</td></tr>\n<tr>\n<td>29</td>\n<td>26\n</td></tr>\n<tr>\n<td>33</td>\n<td>27\n</td></tr>\n<tr>\n<td>36</td>\n<td>28\n</td></tr>\n<tr>\n<td>41</td>\n<td>29\n</td></tr>\n<tr>\n<td>45</td>\n<td>30\n</td></tr>\n<tr>\n<td>49</td>\n<td>31\n</td></tr>\n<tr>\n<td>54</td>\n<td>32\n</td></tr>\n<tr>\n<td>59</td>\n<td>33\n</td></tr>\n<tr>\n<td>64</td>\n<td>34\n</td></tr>\n<tr>\n<td>70</td>\n<td>35\n</td></tr>\n<tr>\n<td>75</td>\n<td>36\n</td></tr>\n<tr>\n<td>81</td>\n<td>37\n</td></tr>\n<tr>\n<td>88</td>\n<td>38\n</td></tr>\n<tr>\n<td>94</td>\n<td>39\n</td></tr></tbody></table>\n<p><b>Note:</b> Maximum slope is rounded <i>down</i>\n</p>', 2),
(4907, 1271, 'Description', 'Description', 'A round shield made from a hammered metal sheet.', '<p><i>A round shield made from a hammered metal sheet.</i>\n</p>', 0),
(4908, 1271, 'Notes', 'Notes', 'In comparison to the large and small versions, the medium shield has a balance between speed and block percentage. It can be can be made of any metal .', '<ul><li>In comparison to the large and small versions, the medium shield has a balance between speed and block percentage.</li>\n<li>It can be can be made of any <a class=\"mw-redirect\" href=\"/index.php/Metal_lump\" title=\"Metal lump\">metal</a>.</li></ul>', 1),
(4909, 1271, 'Skills & Characteristics', 'Skills_.26_Characteristics', 'When using a Medium metal shield Shields > Medium metal shield Body > Body control Mind > Mind speed When creating a medium metal shield Armour smithing > Shield smithing', '<p>When using a Medium metal shield\n</p>\n<ul><li><a href=\"/index.php/Shields\" title=\"Shields\">Shields</a> &gt; Medium metal shield</li>\n<li><a href=\"/index.php/Body\" title=\"Body\">Body</a> &gt; <a href=\"/index.php/Body_control\" title=\"Body control\">Body control</a></li>\n<li><a href=\"/index.php/Mind\" title=\"Mind\">Mind</a> &gt; <a href=\"/index.php/Mind_speed\" title=\"Mind speed\">Mind speed</a></li></ul>\n<p>When creating a medium metal shield\n</p>\n<ul><li><a href=\"/index.php/Armour_smithing\" title=\"Armour smithing\">Armour smithing</a> &gt; <a href=\"/index.php/Shield_smithing\" title=\"Shield smithing\">Shield smithing</a></li></ul>', 2),
(4910, 1271, 'Titles', 'Titles', 'Sturdy Defender at 50 skill Sturdy Bastion at 70 skill Sturdy Bulwark at 90 skill Aegis at 100 skill', '<ul><li>Sturdy Defender at 50 skill</li>\n<li>Sturdy Bastion at 70 skill</li>\n<li>Sturdy Bulwark at 90 skill</li>\n<li>Aegis at 100 skill</li></ul>', 3),
(4911, 1271, 'See Also', 'See_Also', 'Small metal shield Large metal shield', '<ul><li><a href=\"/index.php/Small_metal_shield\" title=\"Small metal shield\">Small metal shield</a></li>\n<li><a href=\"/index.php/Large_metal_shield\" title=\"Large metal shield\">Large metal shield</a></li></ul>', 4),
(4918, 1273, 'Description', 'Description', 'The bent blade of a sacrificial knife.', '<p><i>The bent blade of a sacrificial knife.</i>\n</p>', 0),
(4919, 1273, 'Usage', 'Usage', 'Needed for the creation of a Sacrificial knife .', '<p>Needed for the creation of a <a href=\"/index.php/Sacrificial_knife\" title=\"Sacrificial knife\">Sacrificial knife</a>.\n</p>', 1),
(4920, 1275, 'Description', 'Description', 'A curved, sharp knife with a long decorated blade inset with gems. A knife used for sacrificing missions.', '<p><i>A curved, sharp knife with a long decorated blade inset with gems.</i>\n</p>\n<p>A <a href=\"/index.php/Knife\" title=\"Knife\">knife</a> used for <a class=\"mw-redirect\" href=\"/index.php/Sacrificing\" title=\"Sacrificing\">sacrificing</a> missions.\n</p>', 0),
(4921, 1275, 'Usage', 'Usage', 'Sacrificing an animal must be done within the influence of an altar , the domain range of the god. With Sacrificial knife activated, right-click the animal and sacrifice. Sacrificing of animals gives favor for a priest . Animals that can be sacrificed only when there is an active mission for sacrifice. This includes: Bison Bull Cow Donkey Drake spirit Hen / Chicken Horse Mule Pig Ram Rooster Sheep Animals that can be sacrificed even when there is no active mission for sacrifice. This includes: Anaconda Black bear Brown bear Black wolf Cave bug Crab Crocodile Deer Dolphin Goblin Hell hound Hell scorpious Large rat Lava spider Mountain lion Octopus Pheasant Scorpion Seal Spider Tortoise Troll Whale Wild cat Favor gains are dependent on animal age : Young = 4.5 Adolescent = 5.0 Mature = 5.5 Aged = 6.0 Old = 6.5 Venerable = 7.0', '<p>Sacrificing an animal must be done within the influence of an <a href=\"/index.php/Altar\" title=\"Altar\">altar</a>, the domain range of the god. With Sacrificial knife activated, right-click the animal and sacrifice.\n</p>\n<p>Sacrificing of animals gives <a href=\"/index.php/Favor\" title=\"Favor\">favor</a> for a <a href=\"/index.php/Priest\" title=\"Priest\">priest</a>.\n</p>\n<hr/>\n<p>Animals that can be sacrificed only when there is an active mission for sacrifice. This includes:\n</p>\n<ul><li><a href=\"/index.php/Bison\" title=\"Bison\">Bison</a></li>\n<li><a href=\"/index.php/Bull\" title=\"Bull\">Bull</a></li>\n<li><a href=\"/index.php/Cow\" title=\"Cow\">Cow</a></li>\n<li><a href=\"/index.php/Donkey\" title=\"Donkey\">Donkey</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Drake_spirit\" title=\"Drake spirit\">Drake spirit</a></li>\n<li><a href=\"/index.php/Hen\" title=\"Hen\">Hen</a>/<a href=\"/index.php/Chicken\" title=\"Chicken\">Chicken</a></li>\n<li><a href=\"/index.php/Horse\" title=\"Horse\">Horse</a></li>\n<li><a href=\"/index.php/Mule\" title=\"Mule\">Mule</a></li>\n<li><a href=\"/index.php/Pig\" title=\"Pig\">Pig</a></li>\n<li><a href=\"/index.php/Ram\" title=\"Ram\">Ram</a></li>\n<li><a href=\"/index.php/Rooster\" title=\"Rooster\">Rooster</a></li>\n<li><a href=\"/index.php/Sheep\" title=\"Sheep\">Sheep</a></li></ul>\n<p>Animals that can be sacrificed even when there is no active mission for sacrifice. This includes:\n</p>\n<ul><li><a href=\"/index.php/Anaconda\" title=\"Anaconda\">Anaconda</a></li>\n<li><a href=\"/index.php/Black_bear\" title=\"Black bear\">Black bear</a></li>\n<li><a href=\"/index.php/Brown_bear\" title=\"Brown bear\">Brown bear</a></li>\n<li><a href=\"/index.php/Black_wolf\" title=\"Black wolf\">Black wolf</a></li>\n<li><a href=\"/index.php/Cave_bug\" title=\"Cave bug\">Cave bug</a></li>\n<li><a href=\"/index.php/Crab\" title=\"Crab\">Crab</a></li>\n<li><a href=\"/index.php/Crocodile\" title=\"Crocodile\">Crocodile</a></li>\n<li><a href=\"/index.php/Deer\" title=\"Deer\">Deer</a></li>\n<li><a href=\"/index.php/Dolphin\" title=\"Dolphin\">Dolphin</a></li>\n<li><a href=\"/index.php/Goblin\" title=\"Goblin\">Goblin</a></li>\n<li><a href=\"/index.php/Hell_hound\" title=\"Hell hound\">Hell hound</a></li>\n<li><a href=\"/index.php/Hell_scorpious\" title=\"Hell scorpious\">Hell scorpious</a></li>\n<li><a href=\"/index.php/Large_rat\" title=\"Large rat\">Large rat</a></li>\n<li><a href=\"/index.php/Lava_spider\" title=\"Lava spider\">Lava spider</a></li>\n<li><a href=\"/index.php/Mountain_lion\" title=\"Mountain lion\">Mountain lion</a></li>\n<li><a href=\"/index.php/Octopus\" title=\"Octopus\">Octopus</a></li>\n<li><a href=\"/index.php/Pheasant\" title=\"Pheasant\">Pheasant</a></li>\n<li><a href=\"/index.php/Scorpion\" title=\"Scorpion\">Scorpion</a></li>\n<li><a href=\"/index.php/Seal\" title=\"Seal\">Seal</a></li>\n<li><a href=\"/index.php/Spider\" title=\"Spider\">Spider</a></li>\n<li><a href=\"/index.php/Tortoise\" title=\"Tortoise\">Tortoise</a></li>\n<li><a href=\"/index.php/Troll\" title=\"Troll\">Troll</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Whale\" title=\"Whale\">Whale</a></li>\n<li><a href=\"/index.php/Wild_cat\" title=\"Wild cat\">Wild cat</a></li></ul>\n<p>Favor gains are dependent on animal <a href=\"/index.php/Age\" title=\"Age\">age</a>:\n</p>\n<ul><li>Young = 4.5</li>\n<li>Adolescent = 5.0</li>\n<li>Mature = 5.5</li>\n<li>Aged = 6.0</li>\n<li>Old = 6.5</li>\n<li>Venerable = 7.0</li></ul>', 1),
(4922, 1275, 'Notes', 'Notes', 'Sacrifice creature success for missions take a player\'s FS and creature CR into account, so weaker creatures can be sacrificed at more health with the max of 50% health as the cap. Can also be used used for butchering and filleting meat and fish . Butchering only produces maximum one meat. Uses butchering knife skill', '<ul><li>Sacrifice creature success for missions take a player\'s FS and creature CR into account, so weaker creatures can be sacrificed at more health with the max of 50% health as the cap.</li>\n<li>Can also be used used for <a href=\"/index.php/Butchering\" title=\"Butchering\">butchering</a> and filleting <a href=\"/index.php/Meat\" title=\"Meat\">meat</a> and <a href=\"/index.php/Fish\" title=\"Fish\">fish</a>. Butchering only produces maximum one meat.</li>\n<li>Uses <a href=\"/index.php/Butchering_knife\" title=\"Butchering knife\">butchering knife</a> skill</li></ul>', 2),
(4923, 1276, 'Description', 'Description', 'A wooden handle wound with leather.', '<p><i>A wooden handle wound with leather.</i>\n</p>', 0),
(4924, 1276, 'Usage', 'Usage', 'Used in the creation of: Sacrificial knife Medium fishing reel Reinforced handle', '<p>Used in the creation of:\n</p>\n<ul><li><a href=\"/index.php/Sacrificial_knife\" title=\"Sacrificial knife\">Sacrificial knife</a></li>\n<li><a href=\"/index.php/Medium_fishing_reel\" title=\"Medium fishing reel\">Medium fishing reel</a></li>\n<li><a href=\"/index.php/Reinforced_handle\" title=\"Reinforced handle\">Reinforced handle</a></li></ul>', 1),
(4925, 1276, 'Notes', 'Notes', 'Handles can not be improved . The handle quality depends upon the quality of the shaft used.', '<ul><li>Handles can not be <a href=\"/index.php/Improve\" title=\"Improve\">improved</a>.</li>\n<li>The handle <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> depends upon the quality of the shaft used.</li></ul>', 2),
(4941, 1280, 'Description', 'Description', 'Analyse is an action granted by the prospecting skill. When used on recently mined stone shard , or even ores , it allows you to determine if any ore veins are nearby the tile the shard was mined from, as well as their approximate distance and direction from that tile.  The action is first unlocked at prospecting skill level 20, and requires a premium account to perform. To Analyse, right-click a stone shard or ore, and select \"Analyse.\"', '<p>Analyse is an action granted by the <a href=\"/index.php/Prospecting\" title=\"Prospecting\">prospecting</a> skill. When used on recently mined <a href=\"/index.php/Stone_shards\" title=\"Stone shards\">stone shard</a>, or even <a class=\"mw-redirect\" href=\"/index.php/Ore\" title=\"Ore\">ores</a>, it allows you to determine if any ore veins are nearby the tile the shard was mined from, as well as their approximate distance and direction from that tile.  The action is first unlocked at prospecting skill level 20, and requires a <a href=\"/index.php/Account_types\" title=\"Account types\">premium account</a> to perform. To Analyse, right-click a stone shard or ore, and select \"Analyse.\"\n</p>', 0),
(4942, 1280, 'Event messages', 'Event_messages', 'You are unable to work out how to analyse the shard. - You are below prospecting skill level 20. It looks like someone has tampered with the stone shards and therefore you decide not to analyse it. - The shard has already been analysed and cannot be analysed again..  Also appears if part of the shards have been used to make something or used in improving. The stone shards looks too old for a decent analysis and therefore you decide not to analyse it. - Appears if you try to analyse a shard from a bulk storage bin .', '<p><span style=\"color: #fff; font-family: Sans-Serif; font-size: 0.85em; border: 1px rgb(0, 0, 0) solid; background: rgb(75, 62, 48); line-height: 1.3em; -webkit-border-radius: 5px; -moz-border-radius: 5px; border-radius: 5px; -moz-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); -webkit-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); padding: 2px 10px 2px 10px; display: inline-block;\"> You are unable to work out how to analyse the shard. </span> - You are below prospecting skill level 20.\n</p>\n<p><span style=\"color: #fff; font-family: Sans-Serif; font-size: 0.85em; border: 1px rgb(0, 0, 0) solid; background: rgb(75, 62, 48); line-height: 1.3em; -webkit-border-radius: 5px; -moz-border-radius: 5px; border-radius: 5px; -moz-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); -webkit-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); padding: 2px 10px 2px 10px; display: inline-block;\"> It looks like someone has tampered with the stone shards and therefore you decide not to analyse it. </span> - The shard has already been analysed and cannot be analysed again..  Also appears if part of the shards have been used to make something or used in improving.  \n</p>\n<p><span style=\"color: #fff; font-family: Sans-Serif; font-size: 0.85em; border: 1px rgb(0, 0, 0) solid; background: rgb(75, 62, 48); line-height: 1.3em; -webkit-border-radius: 5px; -moz-border-radius: 5px; border-radius: 5px; -moz-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); -webkit-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); padding: 2px 10px 2px 10px; display: inline-block;\"> The stone shards looks too old for a decent analysis and therefore you decide not to analyse it. </span> - Appears if you try to analyse a shard from a <a href=\"/index.php/Bulk_storage_bin\" title=\"Bulk storage bin\">bulk storage bin</a>.\n</p>', 1),
(4943, 1280, 'How to use', 'How_to_use', 'When analysing a shard, several messages will appear in the event window over several seconds. Distance Depending on your prospecting skill, you will receive different amounts of information from the shard. Nearby ores will appear as traces every few lines. The strength of the traces shows the distance from the tile the shard originated from, to the tile with the ore vein.  The level of your prospecting skill will determine the strength of the traces you can detect. The six different strengths: \"Traces\" - Shows for ore that is 1 tile away. Unlocked with Analyse at prospecting level 20. \"Slight traces\" - Shows for ore that is 2 tiles away.  Unlocked with Analyse at prospecting level 20. \"Faint traces\" - Shows for ore that is 3 tiles away.  Unlocked at prospecting level 35. \"Minuscule traces\" - Shows for ore that is 4 tiles away. Unlocked at prospecting level 51. \"Vague traces\" - Shows for ore that is 5 tiles away. Unlocked at prospecting level 68. \"Indistinct traces\" - Shows for ore that is 6 tiles away. Unlocked at prospecting level 85. The distance away from the analysed stone shard/tile is referring to a square around the tile analysed, as shown in this picture: (white = 1 tile, blue = 2 tiles, cyan = 3 tiles, green = 4 tiles, orange = 5 tiles, pink = 6 tiles) Quality Additionally, at higher prospecting levels, you can begin to see the quality of veins.  Veins farther away require more skill in order to assess the quality.  Rather than a specific quality, it lists a range of quality.  This is the same vein quality system used in prospecting. The quality ranges are: Poor: 20-29 QL Acceptable: 30-39 QL Normal: 40-59 QL Good: 60-79 QL Very good: 80-94 QL Utmost: 95-99 QL Level necessary to see quality at specific distances: \"Traces\" quality, unlocked at level 22 \"Slight traces\" quality, unlocked at level 40 \"Faint traces\" quality, unlocked at level 50 \"Minuscule traces\" quality, unlocked at level 60 \"Vague traces\" quality, unlocked at level 90 (Needs confirmation) NOTE By the most new experiments ( done at 20 skill in prospecting ), it looks like the more distance the ore is at, the more difficult is to determine what its.\nA message like [xx:xx:xx] You notice a slight trace of something, but cannot quite make it out. would be shown then, as an example, for some ore in the 2nd tile radius, displaying the ore vein as unknown (even if the vein is exposed and you can see it). Anyway, such given message does not mean that there is an ore beyond that point (and if there is, at that lvl of skill its imposible to say), but that there is an ore in the given radius. It also looks like different kinds of ore have their own difficulty for being detected. So, since the message from above has been given at 20 prospecting skill and with a Silver Vein , the message [xx:xx:xx] You spot a slight trace of zinc ore . has been given with a Zinc Vein at 2 tiles away. So far, for now, Silver and Lead are not identificable at 20 skill in Prospecting, but Zinc is when its beyond the 1st tile radius. Direction In addition to type, quality and distance of the vein , a direction is available from the analyze messages if you have a compass in your inventory . The direction is given as one of 16 possible values: the 4 cardinal directions north , east , south and west if the prospected ore is in a straight horizontal or vertical line on the grid the 4 intermediate directions northeast , southeast , southwest and northwest if the prospected ore is in straight diagonal line on the grid all other locations fall into the 8 directions east/west of north , north/south of east , east/west of south and north/south of west Example This is a possible analyse readout at prospecting level 20-29: You start to analyse the shard.\nLots of different sized stone shards.\nYou notice a trace of silver ore (northeast).\nYou take a closer look.\nYou notice a slight trace of iron ore (south of west).\nYou finish analysing the shard. This says that there\'s a silver ore vein right to the northeast from the tile from which the analysed stone shard was mined. The distance one is the square of tiles immediately surrounding the analysed one.  Each increment of distance beyond this is the square of tiles immediately surrounding the previous one. In this example the second square, of distance two, holds the iron ore . Quick reference Prospecting skill needed to view type and quality of ore : (fields with \"?\" are unconfirmed, \"unknown\" means you will see something like You notice a slight trace of something, but cannot quite make it out .) resource type unknown iron tin zinc lead copper slate silver marble gold rocksalt sandstone flint salt Traces (1 tile) - 20 20 20 20 20 20 20 20 20 20 ? 20 40 Slight traces (2 tiles) - 20 20 20 21 22 24 25 26 27 20 30 20 40 Faint traces (3 tiles) 34 35 36 37 38 39 41 42 43 44 35 47 37 40 Minuscule traces (4 tiles) 51 52 53 54 55 56 58 59 60 61 52 64 54 57 Vague traces (5 tiles) 68 69 70 71 72 73 75 76 77 78 69 81 71 74 Indistinct traces (6 tiles) 85 86 87 88 89 90 92 93 94 95 86 ? 88 91', '<p>When analysing a shard, several messages will appear in the event window over several seconds.\n</p>\n<h3><span class=\"mw-headline\" id=\"Distance\">Distance</span></h3>\n<p>Depending on your prospecting skill, you will receive different amounts of information from the shard. Nearby ores will appear as traces every few lines. The strength of the traces shows the distance from the tile the shard originated from, to the tile with the ore vein.  The level of your prospecting skill will determine the strength of the traces you can detect.\n</p>\n<p>The six different strengths:\n</p>\n<ul><li><b>\"Traces\"</b> - Shows for ore that is 1 tile away. Unlocked with Analyse at prospecting level 20.</li>\n<li><b>\"Slight traces\"</b> - Shows for ore that is 2 tiles away.  Unlocked with Analyse at prospecting level 20.</li>\n<li><b>\"Faint traces\"</b> - Shows for ore that is 3 tiles away.  Unlocked at prospecting level 35.</li>\n<li><b>\"Minuscule traces\"</b> - Shows for ore that is 4 tiles away. Unlocked at prospecting level 51.</li>\n<li><b>\"Vague traces\"</b> - Shows for ore that is 5 tiles away. Unlocked at prospecting level 68.</li>\n<li><b>\"Indistinct traces\"</b> - Shows for ore that is 6 tiles away. Unlocked at prospecting level 85.</li></ul>\n<p>The distance away from the analysed stone shard/tile is referring to a square around the tile analysed, as shown in this picture:\n</p>\n<p><a class=\"image\" href=\"/index.php/File:Analyze.png\"><img alt=\"Analyze.png\" data-file-height=\"302\" data-file-width=\"301\" decoding=\"async\" height=\"302\" src=\"/images/8/8a/Analyze.png\" width=\"301\"/></a>\n</p>\n<p>(white = 1 tile, blue = 2 tiles, cyan = 3 tiles, green = 4 tiles, orange = 5 tiles, pink = 6 tiles)\n</p>\n<h3><span class=\"mw-headline\" id=\"Quality\">Quality</span></h3>\n<p>Additionally, at higher prospecting levels, you can begin to see the quality of veins.  Veins farther away require more skill in order to assess the quality.  Rather than a specific quality, it lists a range of quality.  This is the same vein quality system used in prospecting. \n</p>\n<p>The quality ranges are:\n</p>\n<ul><li>Poor: 20-29 QL</li>\n<li>Acceptable: 30-39 QL</li>\n<li>Normal: 40-59 QL</li>\n<li>Good: 60-79 QL</li>\n<li>Very good: 80-94 QL</li>\n<li>Utmost: 95-99 QL</li></ul>\n<p>Level necessary to see quality at specific distances:\n</p>\n<ul><li>\"Traces\" quality, unlocked at level 22</li>\n<li>\"Slight traces\" quality, unlocked at level 40</li>\n<li>\"Faint traces\" quality, unlocked at level 50</li>\n<li>\"Minuscule traces\" quality, unlocked at level 60</li>\n<li>\"Vague traces\" quality, unlocked at level 90 (Needs confirmation)</li></ul>\n<p><br/>\n<i><b>NOTE</b></i>\n</p>\n<p>By the most new experiments (<i>done at 20 skill in prospecting</i>), it looks like the more distance the ore is at, the more difficult is to determine what its.\nA message like <i><b>[xx:xx:xx] You notice a slight trace of something, but cannot quite make it out.</b></i> would be shown then, as an example, for some ore in the 2nd tile radius, displaying the ore vein as unknown (even if the vein is exposed and you can see it).\n</p>\n<p>Anyway, such given message does not mean that there is an ore beyond that point (and if there is, at that lvl of skill its imposible to say), but that there is an ore in the given radius.\n</p>\n<p>It also looks like different kinds of ore have their own difficulty for being detected. So, since the message from above has been given at 20 prospecting skill and with a <b>Silver Vein</b>, the message <i><b>[xx:xx:xx] You spot a slight trace of zinc ore</b>.</i> has been given with a Zinc Vein at 2 tiles away.\n</p>\n<p>So far, for now, <b>Silver</b> and <b>Lead</b> are not identificable at <b>20 skill</b> in Prospecting, but <b>Zinc</b> is when its beyond the 1st tile radius.\n</p>\n<h3><span class=\"mw-headline\" id=\"Direction\">Direction</span></h3>\n<p>In addition to type, quality and distance of the <a class=\"mw-redirect\" href=\"/index.php/Vein\" title=\"Vein\">vein</a>, a direction is available from the analyze messages if you have a <a href=\"/index.php/Compass\" title=\"Compass\">compass</a> in your <a href=\"/index.php/Inventory\" title=\"Inventory\">inventory</a>. The direction is given as one of 16 possible values:\n</p>\n<ul><li>the 4 cardinal directions <i>north</i>, <i>east</i>, <i>south</i> and <i>west</i> if the prospected ore is in a straight horizontal or vertical line on the grid</li>\n<li>the 4 intermediate directions  <i>northeast</i>, <i>southeast</i>, <i>southwest</i> and <i>northwest</i> if the prospected ore is in straight diagonal line on the grid</li>\n<li>all other locations fall into the 8 directions <i>east/west of north</i>, <i>north/south of east</i>, <i>east/west of south</i> and <i>north/south of west</i></li></ul>\n<h3><span class=\"mw-headline\" id=\"Example\">Example</span></h3>\n<p>This is a possible analyse readout at prospecting level 20-29:\n</p>\n<pre>You start to analyse the shard.\nLots of different sized stone shards.\nYou notice a trace of silver ore (northeast).\nYou take a closer look.\nYou notice a slight trace of iron ore (south of west).\nYou finish analysing the shard.\n</pre>\n<p>This says that there\'s a <a href=\"/index.php/Silver_ore\" title=\"Silver ore\">silver ore</a> vein right to the northeast from the tile from which the analysed stone shard was mined. The distance one is the square of tiles immediately surrounding the analysed one.  Each increment of distance beyond this is the square of tiles immediately surrounding the previous one. In this example the second square, of distance two, holds the <a href=\"/index.php/Iron_ore\" title=\"Iron ore\">iron ore</a>.\n</p>\n<h3><span class=\"mw-headline\" id=\"Quick_reference\">Quick reference</span></h3>\n<p>Prospecting skill needed to view type and quality of ore : (fields with \"?\" are unconfirmed, \"unknown\" means you will see something like <i>You notice a slight trace of something, but cannot quite make it out</i>.)\n</p>\n<table border=\"1\" style=\"text-align:center;\">\n<tbody><tr>\n<th>resource type</th>\n<th>unknown</th>\n<th>iron</th>\n<th>tin</th>\n<th>zinc</th>\n<th>lead</th>\n<th>copper</th>\n<th>slate</th>\n<th>silver</th>\n<th>marble</th>\n<th>gold</th>\n<th>rocksalt</th>\n<th>sandstone</th>\n<th>flint</th>\n<th>salt\n</th></tr>\n<tr>\n<td>Traces (1 tile)</td>\n<td>-</td>\n<td>20</td>\n<td>20</td>\n<td>20</td>\n<td>20</td>\n<td>20</td>\n<td>20</td>\n<td>20</td>\n<td>20</td>\n<td>20</td>\n<td>20</td>\n<td>?</td>\n<td>20</td>\n<td>40\n</td></tr>\n<tr>\n<td>Slight traces (2 tiles)</td>\n<td>-</td>\n<td>20</td>\n<td>20</td>\n<td>20</td>\n<td>21</td>\n<td>22</td>\n<td>24</td>\n<td>25</td>\n<td>26</td>\n<td>27</td>\n<td>20</td>\n<td>30</td>\n<td>20</td>\n<td>40\n</td></tr>\n<tr>\n<td>Faint traces (3 tiles)</td>\n<td>34</td>\n<td>35</td>\n<td>36</td>\n<td>37</td>\n<td>38</td>\n<td>39</td>\n<td>41</td>\n<td>42</td>\n<td>43</td>\n<td>44</td>\n<td>35</td>\n<td>47</td>\n<td>37</td>\n<td>40\n</td></tr>\n<tr>\n<td>Minuscule traces (4 tiles)</td>\n<td>51</td>\n<td>52</td>\n<td>53</td>\n<td>54</td>\n<td>55</td>\n<td>56</td>\n<td>58</td>\n<td>59</td>\n<td>60</td>\n<td>61</td>\n<td>52</td>\n<td>64</td>\n<td>54</td>\n<td>57\n</td></tr>\n<tr>\n<td>Vague traces (5 tiles)</td>\n<td>68</td>\n<td>69</td>\n<td>70</td>\n<td>71</td>\n<td>72</td>\n<td>73</td>\n<td>75</td>\n<td>76</td>\n<td>77</td>\n<td>78</td>\n<td>69</td>\n<td>81</td>\n<td>71</td>\n<td>74\n</td></tr>\n<tr>\n<td>Indistinct traces (6 tiles)</td>\n<td>85</td>\n<td>86</td>\n<td>87</td>\n<td>88</td>\n<td>89</td>\n<td>90</td>\n<td>92</td>\n<td>93</td>\n<td>94</td>\n<td>95</td>\n<td>86</td>\n<td>?</td>\n<td>88</td>\n<td>91\n</td></tr>\n</tbody></table>', 2),
(4944, 1280, 'Notes', 'Notes', 'Rare pickaxe will not add another line of information. Ores may also be analysed. There is a skill tick chance for each trace strength analysis. (ex. If you can go up to \"faint traces\" you get 3 skill tick chances.) It is possible to detect two veins in the same distance zone. Both can have its quality range listed and be of same type, each on separate lines. Stone shard QL plays no part in how much information is given. Flint and salt detection is possible. Analysing can be done while moving, so long as you do not move too far away (two tiles) from the tile you are currently working on. Direction information is included in messages only when you have a compass. A visual representation of the messages can be found on this Guide for Analysing.', '<ul><li>Rare pickaxe will not add another line of information.</li>\n<li>Ores may also be analysed.</li>\n<li>There is a skill tick chance for each trace strength analysis. (ex. If you can go up to \"faint traces\" you get 3 skill tick chances.)</li>\n<li>It is possible to detect two veins in the same distance zone. Both can have its quality range listed and be of same type, each on separate lines.</li>\n<li>Stone shard QL plays no part in how much information is given.</li>\n<li><a href=\"/index.php/Flint\" title=\"Flint\">Flint</a> and <a href=\"/index.php/Salt\" title=\"Salt\">salt</a> detection is possible.</li>\n<li>Analysing can be done while moving, so long as you do not move too far away (two tiles) from the tile you are currently working on.</li>\n<li>Direction information is included in messages only when you have a compass.</li>\n<li>A visual representation of the messages can be found on this <a class=\"external text\" href=\"https://forum.wurmonline.com/index.php?/topic/186608-a-visual-guide-to-prospecting-and-mining-directions/&amp;tab=comments#comment-1876552\" rel=\"nofollow\">Guide for Analysing.</a></li></ul>', 3),
(4945, 1280, 'See also', 'See_also', 'Prospecting', '<ul><li><a href=\"/index.php/Prospecting\" title=\"Prospecting\">Prospecting</a></li></ul>', 4),
(4960, 1286, 'Description', 'Description', 'You see a curb. Does not impede movement.', '<p><i>You see a curb.</i>\n</p>\n<p>Does not impede movement.\n</p>', 0),
(4961, 1286, 'Skill Required', 'Skill_Required', 'To calculate the maximum slope you can build on, based on your carpentry or masonry skill, use the following formula submitted by Ketza : Max slope = (3 * √ skill) + 10 Skill Max Slope 6 17 8 18 9 19 12 20 14 21 16 22 19 23 22 24 25 25 29 26 33 27 36 28 41 29 45 30 49 31 54 32 59 33 64 34 70 35 75 36 81 37 88 38 94 39 Note: Maximum slope is rounded down', '<p>To calculate the <a href=\"/index.php/Maximum_slope\" title=\"Maximum slope\">maximum slope</a> you can build on, based on your <a href=\"/index.php/Carpentry\" title=\"Carpentry\">carpentry</a> or <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill, use the following formula submitted by <a href=\"/index.php/Player:Ketza\" title=\"Player:Ketza\">Ketza</a>:\n</p>\n<p><i>Max slope = (3 *</i> √<i>skill) + 10</i>\n</p>\n<table class=\"wikitable\" style=\"text-align: center;\">\n<tbody><tr>\n<th width=\"100\">Skill\n</th>\n<th width=\"100\">Max Slope\n</th></tr>\n<tr>\n<td>6</td>\n<td>17\n</td></tr>\n<tr>\n<td>8</td>\n<td>18\n</td></tr>\n<tr>\n<td>9</td>\n<td>19\n</td></tr>\n<tr>\n<td>12</td>\n<td>20\n</td></tr>\n<tr>\n<td>14</td>\n<td>21\n</td></tr>\n<tr>\n<td>16</td>\n<td>22\n</td></tr>\n<tr>\n<td>19</td>\n<td>23\n</td></tr>\n<tr>\n<td>22</td>\n<td>24\n</td></tr>\n<tr>\n<td>25</td>\n<td>25\n</td></tr>\n<tr>\n<td>29</td>\n<td>26\n</td></tr>\n<tr>\n<td>33</td>\n<td>27\n</td></tr>\n<tr>\n<td>36</td>\n<td>28\n</td></tr>\n<tr>\n<td>41</td>\n<td>29\n</td></tr>\n<tr>\n<td>45</td>\n<td>30\n</td></tr>\n<tr>\n<td>49</td>\n<td>31\n</td></tr>\n<tr>\n<td>54</td>\n<td>32\n</td></tr>\n<tr>\n<td>59</td>\n<td>33\n</td></tr>\n<tr>\n<td>64</td>\n<td>34\n</td></tr>\n<tr>\n<td>70</td>\n<td>35\n</td></tr>\n<tr>\n<td>75</td>\n<td>36\n</td></tr>\n<tr>\n<td>81</td>\n<td>37\n</td></tr>\n<tr>\n<td>88</td>\n<td>38\n</td></tr>\n<tr>\n<td>94</td>\n<td>39\n</td></tr></tbody></table>\n<p><b>Note:</b> Maximum slope is rounded <i>down</i>\n</p>', 1),
(4974, 1290, 'Description', 'Description', 'A tabard that is worn to show off which kingdom you belong to.', '<p><i>A tabard that is worn to show off which kingdom you belong to.</i>\n</p>', 0),
(4975, 1290, 'Notes', 'Notes', 'Tabard\'s image depends and changes based on the player\'s current kingdom. Fits in the Tabard slot on the paperdoll in-game. Player made kingdom (PmK\'s) can submit their own design for display on Banner / Flag / Tabard .', '<ul><li>Tabard\'s image depends and changes based on the player\'s current kingdom.</li>\n<li>Fits in the Tabard slot on the paperdoll in-game.</li>\n<li><a href=\"/index.php/Player_made_kingdom\" title=\"Player made kingdom\">Player made kingdom</a> (PmK\'s) can submit their own design for display on <a href=\"/index.php/Banner\" title=\"Banner\">Banner</a> / <a href=\"/index.php/Flag\" title=\"Flag\">Flag</a> / <a class=\"mw-selflink selflink\">Tabard</a>.</li></ul>', 1),
(4976, 1290, 'Images', 'Images', 'From left to right: Jenn-Kellon , Horde of the Summoned', '<p><a class=\"image\" href=\"/index.php/File:Tabard.png\"><img alt=\"Tabard.png\" data-file-height=\"608\" data-file-width=\"245\" decoding=\"async\" height=\"372\" src=\"/images/thumb/c/ce/Tabard.png/150px-Tabard.png\" srcset=\"/images/thumb/c/ce/Tabard.png/225px-Tabard.png 1.5x, /images/c/ce/Tabard.png 2x\" width=\"150\"/></a>\n<a class=\"image\" href=\"/index.php/File:Bl_tabard.png\"><img alt=\"Bl tabard.png\" data-file-height=\"608\" data-file-width=\"268\" decoding=\"async\" height=\"372\" src=\"/images/thumb/1/1c/Bl_tabard.png/164px-Bl_tabard.png\" srcset=\"/images/thumb/1/1c/Bl_tabard.png/246px-Bl_tabard.png 1.5x, /images/1/1c/Bl_tabard.png 2x\" width=\"164\"/></a><br/>\nFrom left to right: <a href=\"/index.php/Jenn-Kellon\" title=\"Jenn-Kellon\">Jenn-Kellon</a>, <a href=\"/index.php/Horde_of_the_Summoned\" title=\"Horde of the Summoned\">Horde of the Summoned</a>\n</p>', 2),
(4977, 1291, 'Description', 'Description', 'A long, well polished staff with a fantastic sapphire attached.', '<p><i>A long, well polished staff with a fantastic sapphire attached.</i>\n</p>', 0),
(4978, 1291, 'Uses', 'Uses', 'Gem staffs are used to cast sorcery spells. Generally, use of the staff to cast such spells involves a right-click and activation on some type of target that is within a certain acceptable range. The player must have access to the spells to be used with the staff in addition to having the sapphire staff itself. Gem staffs cannot be improved or repaired, and their quality level is unimportant to function. They do not take damage from using spells, however.', '<ul><li>Gem staffs are used to cast sorcery spells. Generally, use of the staff to cast such spells involves a right-click and activation on some type of target that is within a certain acceptable range. The player must have access to the spells to be used with the staff in addition to having the sapphire staff itself.</li></ul>\n<ul><li>Gem staffs cannot be improved or repaired, and their quality level is unimportant to function. They do not take damage from using spells, however.</li></ul>', 1),
(4979, 1291, 'Additional Notes', 'Additional_Notes', 'Gem staffs are not considered melee weapons in Wurm and subsequently cause the player to use unarmed combat when they are equipped during melee combat situations. As such, they do not take damage from combat. A 37ql star gem and an 89ql staff combine to make a 51ql gem staff at 10 skill level in alchemy and 24 in natural substances. Further testing is needed for additional production details.', '<ul><li>Gem staffs are not considered melee weapons in Wurm and subsequently cause the player to use unarmed combat when they are equipped during melee combat situations. As such, they do not take damage from combat.</li></ul>\n<ul><li>A 37ql star gem and an 89ql staff combine to make a 51ql gem staff at 10 skill level in alchemy and 24 in natural substances. Further testing is needed for additional production details.</li></ul>', 2),
(4980, 1291, 'Images', 'Images', 'The Sapphire Staff', '<ul class=\"gallery mw-gallery-packed-hover\">\n<li class=\"gallerybox\" style=\"width: 558.66666666667px\"><div style=\"width: 558.66666666667px\">\n<div class=\"thumb\" style=\"width: 556.66666666667px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Unequippedsapphirestaff.png\"><img alt=\"\" data-file-height=\"244\" data-file-width=\"1131\" decoding=\"async\" height=\"120\" src=\"/images/thumb/f/fb/Unequippedsapphirestaff.png/835px-Unequippedsapphirestaff.png\" srcset=\"/images/f/fb/Unequippedsapphirestaff.png 1.5x\" width=\"557\"/></a></div></div>\n<div class=\"gallerytextwrapper\" style=\"width: 537px\"><div class=\"gallerytext\">\n<p>The Sapphire Staff\n</p>\n</div></div>\n</div></li>\n</ul>\n<p><br/>\n</p>', 3),
(4981, 1291, 'See Also', 'See_Also', 'Sorcery Emerald staff Opal staff Ruby staff Diamond staff', '<ul><li><a href=\"/index.php/Sorcery\" title=\"Sorcery\">Sorcery</a></li>\n<li><a href=\"/index.php/Emerald_staff\" title=\"Emerald staff\">Emerald staff</a></li>\n<li><a href=\"/index.php/Opal_staff\" title=\"Opal staff\">Opal staff</a></li>\n<li><a href=\"/index.php/Ruby_staff\" title=\"Ruby staff\">Ruby staff</a></li>\n<li><a href=\"/index.php/Diamond_staff\" title=\"Diamond staff\">Diamond staff</a></li></ul>', 4),
(4982, 1292, 'Description', 'Description', 'Quickbar The quickbar is a handy interface with buttons linked to common shortcuts and activities. The quickbar consists of two rows for slots, each slot able to hold an item or a quick bar button You can drag items from your inventory onto quickbar slots You can remove buttons by dragging them off the quickbar Clicking the [+] icon at the top right of the quick bar opens a menu with more buttons which can be dragged onto the quickbar The top row of the quickbar changes its contents based on the selected tab on the quickbar, making large amounts of items and buttons available for it You can create up to 10 tabs by clicking the [+] next to an existing tab The bottom row of the quickbar will not change when selecting a different tab, allowing a static list of commonly used items or buttons Clicking an item on a quickbar slot will activate it Quickbar slots can be bound to a key by hovering the slot with your mouse pointer and holding the key you want to bind it to You can scroll with your mouse wheel to activate items in the top row when hovering your mouse pointer over the quick bar The arrow on the far right corner of the quickbar allows you to toggle the select bar The lock icon on the quick bar locks all slots to prevent accidental changes to them If you would like to change the size of the toolbelt, right-click the three lines at the top right of the toolbelt and choose toggle size. Putting a container in the quickbar and activating it selects items in the container if there are any. This is especially useful when sowing large fields or attaching lots of identical items to large creations such as ships. Filling up several containers on the quickbar and using an attach or sow keybind, one can queue up lots of actions without ever using the mouse.', '<div class=\"thumb tright\"><div class=\"thumbinner\" style=\"width:302px;\"><a class=\"image\" href=\"/index.php/File:Quickbar.png\"><img alt=\"\" class=\"thumbimage\" data-file-height=\"149\" data-file-width=\"601\" decoding=\"async\" height=\"74\" src=\"/images/thumb/6/6c/Quickbar.png/300px-Quickbar.png\" srcset=\"/images/thumb/6/6c/Quickbar.png/450px-Quickbar.png 1.5x, /images/thumb/6/6c/Quickbar.png/600px-Quickbar.png 2x\" width=\"300\"/></a> <div class=\"thumbcaption\"><div class=\"magnify\"><a class=\"internal\" href=\"/index.php/File:Quickbar.png\" title=\"Enlarge\"></a></div>Quickbar</div></div></div>\n<p>The quickbar is a handy interface with buttons linked to common shortcuts and activities.\n</p>\n<ul><li>The quickbar consists of two rows for slots, each slot able to hold an item or a quick bar button</li>\n<li>You can drag items from your inventory onto quickbar slots</li>\n<li>You can remove buttons by dragging them off the quickbar</li>\n<li>Clicking the [+] icon at the top right of the quick bar opens a menu with more buttons which can be dragged onto the quickbar</li>\n<li>The top row of the quickbar changes its contents based on the selected tab on the quickbar, making large amounts of items and buttons available for it</li>\n<li>You can create up to 10 tabs by clicking the [+] next to an existing tab</li>\n<li>The bottom row of the quickbar will not change when selecting a different tab, allowing a static list of commonly used items or buttons</li>\n<li>Clicking an item on a quickbar slot will activate it</li>\n<li>Quickbar slots can be bound to a key by hovering the slot with your mouse pointer and holding the key you want to bind it to</li>\n<li>You can scroll with your mouse wheel to activate items in the top row when hovering your mouse pointer over the quick bar</li>\n<li>The arrow on the far right corner of the quickbar allows you to toggle the select bar</li>\n<li>The lock icon on the quick bar locks all slots to prevent accidental changes to them</li>\n<li>If you would like to change the size of the toolbelt, right-click the three lines at the top right of the toolbelt and choose toggle size.</li>\n<li>Putting a container in the quickbar and activating it selects items in the container if there are any. This is especially useful when sowing large fields or attaching lots of identical items to large creations such as ships. Filling up several containers on the quickbar and using an attach or sow keybind, one can queue up lots of actions without ever using the mouse.</li></ul>', 0),
(4983, 1292, 'Buttons', 'Buttons', 'You can add the following buttons to the quickbar. Quickbar Buttons Climbing : Toggle climbing mode on or off. Faithful : Ignore or not religions limitations. Lawful : Respect or not local laws Stealth : Toggle the attempt to be invisible on or off. Auto-Fight : Toggle fighting automatically on or off. Sleep bonus : Toggle usage of sleep bonus on or off. Quiver : Display the contents of an equipped quiver. Backpack : Display the contents of an equipped backpack. Inventory : Display the inventory window. Skills : Display the skills window. Character : Display the Character window. Journal : Display the journal window. Toolbelt : Display the toolbelt window. Crafting : Display the crafting window. Cooking : Display the cookbook. World map : Display the in-game world map. Main menu : Display the main menu The quickbar can be shrunk to show only the climbing icon by right-clicking and selecting Partially Hide Window .  The same action can restore the window to full-size.  It can also be locked and hidden just as any other window via the right-click menu.', '<p>You can add the following buttons to the quickbar.\n</p>\n<div class=\"thumb tright\"><div class=\"thumbinner\" style=\"width:302px;\"><a class=\"image\" href=\"/index.php/File:Quickbar_Menu.png\"><img alt=\"\" class=\"thumbimage\" data-file-height=\"453\" data-file-width=\"788\" decoding=\"async\" height=\"172\" src=\"/images/thumb/5/51/Quickbar_Menu.png/300px-Quickbar_Menu.png\" srcset=\"/images/thumb/5/51/Quickbar_Menu.png/450px-Quickbar_Menu.png 1.5x, /images/thumb/5/51/Quickbar_Menu.png/600px-Quickbar_Menu.png 2x\" width=\"300\"/></a> <div class=\"thumbcaption\"><div class=\"magnify\"><a class=\"internal\" href=\"/index.php/File:Quickbar_Menu.png\" title=\"Enlarge\"></a></div>Quickbar Buttons</div></div></div>\n<ul><li><a href=\"/index.php/Climbing\" title=\"Climbing\">Climbing</a>: Toggle climbing mode on or off.</li>\n<li><a href=\"/index.php/Faithful\" title=\"Faithful\">Faithful</a>: Ignore or not religions limitations.</li>\n<li><a href=\"/index.php/Lawful\" title=\"Lawful\">Lawful</a>: Respect or not local laws</li>\n<li><a href=\"/index.php/Stealth\" title=\"Stealth\">Stealth</a>: Toggle the attempt to be invisible on or off.</li>\n<li><a href=\"/index.php/Fighting\" title=\"Fighting\">Auto-Fight</a>: Toggle fighting automatically on or off.</li>\n<li><a href=\"/index.php/Sleep_bonus\" title=\"Sleep bonus\">Sleep bonus</a>: Toggle usage of sleep bonus on or off.</li>\n<li><a href=\"/index.php/Quiver\" title=\"Quiver\">Quiver</a>: Display the contents of an equipped quiver.</li>\n<li><a href=\"/index.php/Backpack\" title=\"Backpack\">Backpack</a>: Display the contents of an equipped backpack.</li>\n<li><a href=\"/index.php/Inventory\" title=\"Inventory\">Inventory</a>: Display the inventory window.</li>\n<li><a href=\"/index.php/Skills\" title=\"Skills\">Skills</a>: Display the skills window.</li>\n<li><a href=\"/index.php/Character\" title=\"Character\">Character</a>: Display the Character window.</li>\n<li><a href=\"/index.php/Journal\" title=\"Journal\">Journal</a>: Display the journal window.</li>\n<li><a href=\"/index.php/Toolbelt\" title=\"Toolbelt\">Toolbelt</a>: Display the toolbelt window.</li>\n<li><a href=\"/index.php/Crafting\" title=\"Crafting\">Crafting</a>: Display the crafting window.</li>\n<li><a href=\"/index.php/Cooking\" title=\"Cooking\">Cooking</a>: Display the cookbook.</li>\n<li><a href=\"/index.php/World_map\" title=\"World map\">World map</a>: Display the in-game world map.</li>\n<li><a href=\"/index.php/Main_menu\" title=\"Main menu\">Main menu</a>: Display the main menu</li></ul>\n<p>The quickbar can be shrunk to show only the <a href=\"/index.php/Climbing\" title=\"Climbing\">climbing</a> icon by right-clicking and selecting <b>Partially Hide Window</b>.  The same action can restore the window to full-size.  It can also be locked and hidden just as any other window via the right-click menu.\n</p>', 1),
(4984, 1292, 'See also', 'See_also', 'Toolbelt', '<p><a href=\"/index.php/Toolbelt\" title=\"Toolbelt\">Toolbelt</a>\n</p>', 2),
(4985, 1293, 'Description', 'Description', 'A clay flowerpot that could be hardened by fire.', '<p><i>A clay flowerpot that could be hardened by fire.</i>\n</p>', 0),
(4986, 1293, 'Usage', 'Usage', 'Place into a campfire , oven , forge or kiln to turn it into a usable pottery flowerpot .', '<ul><li>Place into a <a href=\"/index.php/Campfire\" title=\"Campfire\">campfire</a>, <a href=\"/index.php/Oven\" title=\"Oven\">oven</a>, <a href=\"/index.php/Forge\" title=\"Forge\">forge</a> or <a href=\"/index.php/Kiln\" title=\"Kiln\">kiln</a> to turn it into a usable <a href=\"/index.php/Pottery_flowerpot\" title=\"Pottery flowerpot\">pottery flowerpot</a>.</li></ul>', 1),
(4987, 1293, 'Notes', 'Notes', 'Once hardened into a flowerpot, it can no longer be improved.', '<ul><li>Once hardened into a flowerpot, it can no longer be improved.</li></ul>', 2),
(4998, 1297, 'Description', 'Description', 'A long, well polished staff with a fantastic emerald attached.', '<p><i>A long, well polished staff with a fantastic emerald attached.</i>\n</p>', 0),
