(5001, 1297, 'Additional Images', 'Additional_Images', '', '<ul class=\"gallery mw-gallery-packed-hover\">\n<li class=\"gallerybox\" style=\"width: 535.33333333333px\"><div style=\"width: 535.33333333333px\">\n<div class=\"thumb\" style=\"width: 533.33333333333px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Emeraldstaffunequipped.jpg\"><img alt=\"Emeraldstaffunequipped.jpg\" data-file-height=\"1080\" data-file-width=\"1920\" decoding=\"async\" height=\"300\" src=\"/images/thumb/b/b6/Emeraldstaffunequipped.jpg/800px-Emeraldstaffunequipped.jpg\" srcset=\"/images/thumb/b/b6/Emeraldstaffunequipped.jpg/1200px-Emeraldstaffunequipped.jpg 1.5x, /images/thumb/b/b6/Emeraldstaffunequipped.jpg/1600px-Emeraldstaffunequipped.jpg 2x\" width=\"534\"/></a></div></div>\n</div></li>\n</ul>\n<p><br/>\n</p>', 3);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(5002, 1297, 'See Also', 'See_Also', 'Sorcery Sapphire staff Opal staff Ruby staff Diamond staff', '<ul><li><a href=\"/index.php/Sorcery\" title=\"Sorcery\">Sorcery</a></li>\n<li><a href=\"/index.php/Sapphire_staff\" title=\"Sapphire staff\">Sapphire staff</a></li>\n<li><a href=\"/index.php/Opal_staff\" title=\"Opal staff\">Opal staff</a></li>\n<li><a href=\"/index.php/Ruby_staff\" title=\"Ruby staff\">Ruby staff</a></li>\n<li><a href=\"/index.php/Diamond_staff\" title=\"Diamond staff\">Diamond staff</a></li></ul>', 4),
(5003, 1298, 'Description', 'Description', 'A long, well polished staff with a fantastic opal attached.', '<p><i>A long, well polished staff with a fantastic opal attached.</i>\n</p>', 0),
