(7152, 1884, 'Allies on Home Server', 'Allies_on_Home_Server', 'Whosville OldGuard Death To The Animals Donners Pass Mist West Point Harbor', '<dl><dd><ul><li>Whosville<br/></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/OldGuard\" title=\"OldGuard\">OldGuard</a><br/></li>\n<li><a href=\"/index.php/Undefined_settlement\" title=\"Undefined settlement\">Death To The Animals</a><br/></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Donners_Pass\" title=\"Donners Pass\">Donners Pass</a><br/></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Mist\" title=\"Mist\">Mist</a><br/></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/West_Point_Harbor\" title=\"West Point Harbor\">West Point Harbor</a><br/></li></ul></dd></dl>', 2),
