(7617, 2048, 'Outposts', 'Outposts', '', '', 5),
(7618, 2049, 'Port Benden', 'Port_Benden', 'We are an oceanfront settlement, taking on the look of the southern United States Victorian era towns.  Our homes overlook the wharf and the deed encompasses a small section of the sea in which we harbor our ships.  Our farms are terraced into the hillside.  We are a friendly but semi-private settlement in that we choose to keep to ourselves for the most part.  Make no mistake, friendliness does not mean pacifist, we will defend our home. We are proud to be in the JK HQ Alliance.', '<p>We are an oceanfront settlement, taking on the look of the southern United States Victorian era towns.  Our homes overlook the wharf and the deed encompasses a small section of the sea in which we harbor our ships.  Our farms are terraced into the hillside.  We are a friendly but semi-private settlement in that we choose to keep to ourselves for the most part.  Make no mistake, friendliness does not mean pacifist, we will defend our home.\n</p>\n<p>We are proud to be in the JK HQ Alliance.\n</p>', 0),
(7619, 2049, 'Recruiting', 'Recruiting', 'We are closed to any recruiting, our town was built with only us in mind.', '<p>We are closed to any recruiting, our town was built with only us in mind.\n</p>', 1),
(7620, 2049, 'Villagers', 'Villagers', 'Ramoth Blacksmith, Mason, Landscaper Extraordinaire Wildeyedstorm Cook, Farmer, Mason, Carpenter Nomadikhan Shipbuilder, Winemaker, Engineer, Mason Faranth Official Mayor, Animal Caretaker, Vynoran Priest', '<ul><li><a href=\"/index.php/Undefined_player\" title=\"Undefined player\">Ramoth</a><br/>Blacksmith, Mason, Landscaper Extraordinaire</li>\n<li><a href=\"/index.php/Undefined_player\" title=\"Undefined player\">Wildeyedstorm</a><br/>Cook, Farmer, Mason, Carpenter</li>\n<li><a href=\"/index.php/Player:Nomadikhan\" title=\"Player:Nomadikhan\">Nomadikhan</a><br/>Shipbuilder, Winemaker, Engineer, Mason</li>\n<li><a href=\"/index.php/Undefined_player\" title=\"Undefined player\">Faranth</a><br/>Official Mayor, Animal Caretaker, Vynoran Priest</li></ul>', 2),
(7621, 2050, 'History', 'History', 'The village of Riverside was founded at November the 1st 2011 by the glory hands of Sklo', '<p>The village of Riverside was founded at November the 1st 2011 by the glory hands of <a href=\"/index.php/Player:Sklo\" title=\"Player:Sklo\">Sklo</a>\n</p>\n<p><br/>\n</p>', 0),
