INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(9841, 2653, 'Notes', 'Notes', 'Repair Rounded stone fence with Rounded stone. Each Rounded stone will repair up to 10 damage depending on quality and repairing skill. At 60 damage, cracks will form on the wall.', '<ul><li>Repair Rounded stone fence with Rounded stone. Each Rounded stone will repair up to 10 damage depending on quality and repairing skill.</li>\n<li>At 60 damage, cracks will form on the wall.</li></ul>\n<p><br/>\n</p>\n<p><br/>\n</p>\n<p><br/>\n</p>', 2),
(9842, 2653, 'See also', 'See_also', 'Fences Fence gates Empirical Evaluation of Fences', '<ul><li><a href=\"/index.php/Category:Fences\" title=\"Category:Fences\">Fences</a></li>\n<li><a href=\"/index.php/Category:Gates\" title=\"Category:Gates\">Fence gates</a></li></ul>\n<ul><li><a href=\"/index.php/Empirical_Evaluation_of_Fences\" title=\"Empirical Evaluation of Fences\">Empirical Evaluation of Fences</a></li></ul>', 3),
(9857, 2674, 'Description', 'Description', 'This is a large bush with round, green leaves.', '<p>This is a large bush with round, green leaves. \n</p>', 0),
(9858, 2674, 'Notes', 'Notes', 'Hazelnuts can be harvested from this bush with a sickle during the appropriate season .', '<ul><li><a href=\"/index.php/Hazelnuts\" title=\"Hazelnuts\">Hazelnuts</a> can be harvested from this bush with a <a href=\"/index.php/Sickle\" title=\"Sickle\">sickle</a> during the appropriate <a class=\"mw-redirect\" href=\"/index.php/Season\" title=\"Season\">season</a>.</li></ul>', 1),
(9859, 2674, 'Images', 'Images', 'A Hazelnut bush Hazelnut shrub in season', '<ul class=\"gallery mw-gallery-packed-hover\">\n<li class=\"gallerybox\" style=\"width: 284.66666666667px\"><div style=\"width: 284.66666666667px\">\n<div class=\"thumb\" style=\"width: 282.66666666667px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Hazelnut_bush.png\"><img alt=\"\" data-file-height=\"400\" data-file-width=\"377\" decoding=\"async\" height=\"300\" src=\"/images/5/52/Hazelnut_bush.png\" width=\"283\"/></a></div></div>\n<div class=\"gallerytextwrapper\" style=\"width: 263px\"><div class=\"gallerytext\">\n<p>A Hazelnut bush\n</p>\n</div></div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 262px\"><div style=\"width: 262px\">\n<div class=\"thumb\" style=\"width: 260px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Hazelnut_shrub_nuts.jpg\"><img alt=\"\" data-file-height=\"725\" data-file-width=\"628\" decoding=\"async\" height=\"300\" src=\"/images/thumb/8/80/Hazelnut_shrub_nuts.jpg/390px-Hazelnut_shrub_nuts.jpg\" srcset=\"/images/thumb/8/80/Hazelnut_shrub_nuts.jpg/585px-Hazelnut_shrub_nuts.jpg 1.5x, /images/8/80/Hazelnut_shrub_nuts.jpg 2x\" width=\"260\"/></a></div></div>\n<div class=\"gallerytextwrapper\" style=\"width: 240px\"><div class=\"gallerytext\">\n<p>Hazelnut shrub in season\n</p>\n</div></div>\n</div></li>\n</ul>', 2),
(9860, 2675, 'Description', 'Description', 'This is a lush green bush of medium height.', '<p>This is a lush green bush of medium height. \n</p>', 0),
(9861, 2675, 'Notes', 'Notes', 'Blueberries can be harvested from this bush when in season. Blueberries can be used in some cooking and beverages recipes. Sprouts can be harvested from mature, old, and very old plants and can be found by foraging . The plant can be studied for an almanac . When the plant is not in season, you will see this message when examining: You see a blueberry bush. When the bush is in season: The bush has some juicy blueberries', '<ul><li><a href=\"/index.php/Blueberries\" title=\"Blueberries\">Blueberries</a> can be harvested from this bush when in season.</li>\n<li>Blueberries can be used in some <a href=\"/index.php/Cooking\" title=\"Cooking\">cooking</a> and <a href=\"/index.php/Beverages\" title=\"Beverages\">beverages</a> recipes.</li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Sprouts\" title=\"Sprouts\">Sprouts</a> can be harvested from mature, old, and very old plants and can be found by <a href=\"/index.php/Foraging\" title=\"Foraging\">foraging</a>.</li>\n<li>The plant can be studied for an <a href=\"/index.php/Almanac\" title=\"Almanac\">almanac</a>.</li>\n<li>When the plant is not in season, you will see this message when examining:<i>You see a blueberry bush.</i></li>\n<li>When the bush is in season:<i>The bush has some juicy blueberries</i></li></ul>\n<p><br/>\n</p>', 1),
(9862, 2675, 'Images', 'Images', 'Blueberry bush while in season', '<ul class=\"gallery mw-gallery-packed-hover\">\n<li class=\"gallerybox\" style=\"width: 288.66666666667px\"><div style=\"width: 288.66666666667px\">\n<div class=\"thumb\" style=\"width: 286.66666666667px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Blueberry_bush_fruit.png\"><img alt=\"\" data-file-height=\"661\" data-file-width=\"632\" decoding=\"async\" height=\"300\" src=\"/images/thumb/8/87/Blueberry_bush_fruit.png/430px-Blueberry_bush_fruit.png\" srcset=\"/images/8/87/Blueberry_bush_fruit.png 1.5x\" width=\"287\"/></a></div></div>\n<div class=\"gallerytextwrapper\" style=\"width: 267px\"><div class=\"gallerytext\">\n<p>Blueberry bush while in season\n</p>\n</div></div>\n</div></li>\n</ul>', 2),
(9863, 2676, 'Description', 'Description', 'This is a large bush with green leaves and white flowers.', '<p>This is a large bush with green leaves and white flowers. \n</p>', 0),
(9864, 2676, 'Notes', 'Notes', 'Camellia can be harvested from this bush with a sickle during the appropriate season . Camellia bushes are notorious for spreading incredibly fast. The leaves can be used in some cooking recipes or to make tea . Leaves can be used also in alchemy to make healing covers (healing potency 3). Sprouts can be used to create a hedge . Prior to season message you will see this when examining: The bush has started to give off an interesting scent. When ready to harvest, this message is shown: The bush has a number of leaves that look and smell perfect.', '<ul><li><a class=\"mw-redirect\" href=\"/index.php/Camellia\" title=\"Camellia\">Camellia</a> can be harvested from this bush with a <a href=\"/index.php/Sickle\" title=\"Sickle\">sickle</a> during the appropriate <a class=\"mw-redirect\" href=\"/index.php/Season\" title=\"Season\">season</a>.</li>\n<li>Camellia bushes are notorious for spreading incredibly fast.</li>\n<li>The leaves can be used in some <a href=\"/index.php/Cooking\" title=\"Cooking\">cooking</a> recipes or to make <a href=\"/index.php/Tea\" title=\"Tea\">tea</a>.</li>\n<li>Leaves can be used also in <a href=\"/index.php/Alchemy\" title=\"Alchemy\">alchemy</a> to make <a href=\"/index.php/Healing_cover\" title=\"Healing cover\">healing covers</a> (healing potency 3).</li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Sprouts\" title=\"Sprouts\">Sprouts</a> can be used to create a <a class=\"mw-redirect\" href=\"/index.php/Hedge\" title=\"Hedge\">hedge</a>.</li>\n<li>Prior to <a class=\"mw-redirect\" href=\"/index.php/Seasons\" title=\"Seasons\">season</a> message you will see this when examining:<i>The bush has started to give off an interesting scent.</i></li>\n<li>When ready to harvest, this message is shown:<i>The bush has a number of leaves that look and smell perfect.</i></li></ul>', 1),
(9868, 2678, 'Description', 'Description', 'This is a large bush with violet flowers and long green leaves.', '<p>This is a large bush with violet flowers and long green leaves.\n</p>', 0),
(9869, 2678, 'Notes', 'Notes', 'Prior to season message on examine: The bush has a couple of buds. When ready to harvest, this message will appear: The bush has some beautiful flowers. Lavender flowers can be harvested from this bush with a sickle during the appropriate season . Lavender bushes are notorious for spreading incredibly fast. The flowers can be used in some cooking recipes. Flowers can be used also in alchemy to make healing covers (healing potency 2). Sprouts can be used to grow a hedge .', '<ul><li>Prior to <a class=\"mw-redirect\" href=\"/index.php/Seasons\" title=\"Seasons\">season</a> message on examine:<i>The bush has a couple of buds.</i></li>\n<li>When ready to harvest, this message will appear:<i>The bush has some beautiful flowers.</i></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Lavender_flower\" title=\"Lavender flower\">Lavender flowers</a> can be harvested from this bush with a <a href=\"/index.php/Sickle\" title=\"Sickle\">sickle</a> during the appropriate <a class=\"mw-redirect\" href=\"/index.php/Season\" title=\"Season\">season</a>.</li>\n<li>Lavender bushes are notorious for spreading incredibly fast.</li>\n<li>The flowers can be used in some <a href=\"/index.php/Cooking\" title=\"Cooking\">cooking</a> recipes.</li>\n<li>Flowers can be used also in <a href=\"/index.php/Alchemy\" title=\"Alchemy\">alchemy</a> to make <a href=\"/index.php/Healing_cover\" title=\"Healing cover\">healing covers</a> (healing potency 2).</li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Sprouts\" title=\"Sprouts\">Sprouts</a> can be used to grow a <a class=\"mw-redirect\" href=\"/index.php/Hedge\" title=\"Hedge\">hedge</a>.</li></ul>', 1),
(9876, 2681, 'Description', 'Description', 'Oleander is a large bush with pink flowers. Oleander bushes are notorious for spreading incredibly fast.', '<p>Oleander is a large bush with pink flowers. Oleander bushes are notorious for spreading incredibly fast.\n</p>', 0),
(9877, 2681, 'Examine Message', 'Examine_Message', 'Prior to season message on examine: The bush has started to smell rather badly. When ready to harvest, this message will appear: The bush has a number of strongly smelling leaves.', '<p>Prior to <a class=\"mw-redirect\" href=\"/index.php/Seasons\" title=\"Seasons\">season</a> message on examine:\n</p>\n<p><i>The bush has started to smell rather badly.</i>\n</p>\n<p>When ready to harvest, this message will appear: \n</p>\n<p><i>The bush has a number of strongly smelling leaves.</i>\n</p>', 1),
(9878, 2681, 'Notes', 'Notes', 'Oleander can be harvested from this bush with a sickle during the appropriate season . The leaves can be used in some cooking recipes. Sprouts can be used to grow a hedge . Cutting an oleander bush does not result in an oleander log. Oleander logs are obtained from plants at a rift', '<ul><li><a href=\"/index.php/Oleander\" title=\"Oleander\">Oleander</a> can be harvested from this bush with a <a href=\"/index.php/Sickle\" title=\"Sickle\">sickle</a> during the appropriate <a class=\"mw-redirect\" href=\"/index.php/Season\" title=\"Season\">season</a>.</li>\n<li>The leaves can be used in some <a href=\"/index.php/Cooking\" title=\"Cooking\">cooking</a> recipes.</li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Sprouts\" title=\"Sprouts\">Sprouts</a> can be used to grow a <a class=\"mw-redirect\" href=\"/index.php/Hedge\" title=\"Hedge\">hedge</a>.</li>\n<li>Cutting an oleander bush does not result in an oleander log. Oleander logs are obtained from plants at a <a href=\"/index.php/Rift\" title=\"Rift\">rift</a></li></ul>', 2),
(9879, 2682, 'Description', 'Description', 'This is a lush green bush of medium height. Raspberries can be harvested from this bush with a sickle during the appropriate season .', '<p>This is a lush green bush of medium height. <a href=\"/index.php/Raspberries\" title=\"Raspberries\">Raspberries</a> can be harvested from this bush with a <a href=\"/index.php/Sickle\" title=\"Sickle\">sickle</a> during the appropriate <a class=\"mw-redirect\" href=\"/index.php/Season\" title=\"Season\">season</a>.\n</p>', 0),
(9880, 2682, 'Examine Message', 'Examine_Message', 'When the plant is not in season: You see a raspberry bush When the Plant is in season: The bush has some juicy raspberries', '<p>When the plant is not in season:\n</p>\n<ul><li><i>You see a raspberry bush</i></li></ul>\n<p>When the Plant is in season:\n</p>\n<ul><li><i>The bush has some juicy raspberries</i></li></ul>', 1),
(9881, 2682, 'Usage', 'Usage', 'Raspberries can be harvested from this bush when in season. Raspberries can be used in some cooking recipes. Sprouts can be harvested from mature, old, and very old plants and can be found by foraging . The plant can be studied for an almanac .', '<ul><li><a href=\"/index.php/Raspberries\" title=\"Raspberries\">Raspberries</a> can be harvested from this bush when in season.</li>\n<li>Raspberries can be used in some <a href=\"/index.php/Cooking\" title=\"Cooking\">cooking</a> recipes.</li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Sprouts\" title=\"Sprouts\">Sprouts</a> can be harvested from mature, old, and very old plants and can be found by <a href=\"/index.php/Foraging\" title=\"Foraging\">foraging</a>.</li>\n<li>The plant can be studied for an <a href=\"/index.php/Almanac\" title=\"Almanac\">almanac</a>.</li></ul>', 2),
(9882, 2682, 'Images', 'Images', 'Raspberry bush while in season', '<ul class=\"gallery mw-gallery-packed-hover\">\n<li class=\"gallerybox\" style=\"width: 206px\"><div style=\"width: 206px\">\n<div class=\"thumb\" style=\"width: 204px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Raspberry_bush_fruit.png\"><img alt=\"\" data-file-height=\"786\" data-file-width=\"802\" decoding=\"async\" height=\"200\" src=\"/images/thumb/8/8f/Raspberry_bush_fruit.png/306px-Raspberry_bush_fruit.png\" srcset=\"/images/thumb/8/8f/Raspberry_bush_fruit.png/459px-Raspberry_bush_fruit.png 1.5x, /images/thumb/8/8f/Raspberry_bush_fruit.png/612px-Raspberry_bush_fruit.png 2x\" width=\"204\"/></a></div></div>\n<div class=\"gallerytextwrapper\" style=\"width: 184px\"><div class=\"gallerytext\">\n<p>Raspberry bush while in season\n</p>\n</div></div>\n</div></li>\n</ul>', 3),
(9899, 2688, 'Description', 'Description', 'Living in packs, the blue sharks could be called the wolves of the sea. Only a fool would fail to respect their menacing jaws.', '<p><i>Living in packs, the blue sharks could be called the wolves of the sea. Only a fool would fail to respect their menacing jaws.</i>\n</p>', 0),
(9900, 2688, 'Notes', 'Notes', 'Blue shark can only be caught on special fishing tiles. For the animal that lives in Wurm oceans that you can fight, see Shark (creature) . When catching blue sharks, they deal a small poison damage wound. Used in some cooking recipes. Can be eaten raw or cooked to relieve a small amount of hunger. Can be used as food for taming. Fish decay extremely rapidly after a few hours in your inventory and out of water. To prevent decay, fish can be stored in food storage bins and in crates. Bait ranking is from 1-10. The higher the number, the more likely that fish is to bite. Fishing time ranking is from 1-4. The higher the number, the more likely you are to see that fish.', '<ul><li>Blue shark can only be caught on special fishing tiles.</li>\n<li>For the animal that lives in Wurm oceans that you can fight, see <a href=\"/index.php/Shark_(creature)\" title=\"Shark (creature)\">Shark (creature)</a>.</li>\n<li>When catching blue sharks, they deal a small <a href=\"/index.php/Poison\" title=\"Poison\">poison</a> damage wound.</li></ul>\n<ul><li>Used in some cooking recipes.</li>\n<li>Can be eaten raw or cooked to relieve a small amount of hunger.</li>\n<li>Can be used as food for taming.</li>\n<li>Fish decay extremely rapidly after a few hours in your inventory and out of water. To prevent decay, fish can be stored in food storage bins and in crates.</li>\n<li>Bait ranking is from 1-10. The higher the number, the more likely that fish is to bite.</li>\n<li>Fishing time ranking is from 1-4. The higher the number, the more likely you are to see that fish.</li></ul>\n<p><br/>\n</p>', 1),
(9901, 2688, 'Fishing Guidelines', 'Fishing_Guidelines', 'Blue shark Water types Sea Only surface Fishing height Any Special fish tiles only Swim depths 250-1000 Equipment Professional rod Fishing times Morning 4 Afternoon 3 Evening 4 Night 2 Baits Best: Sardines (none) 0 Cheese piece 1 Corn kernel 1 Dough Ball 1 Fish bait 0 Fly 0 Grub 1 Minnow 5 Perch 5 Roach 5 Sardines 10 Wheat Grain 1 Wurm 1 Weight at 10ql 4.00kg Multiplier by ql 0.4 Rod damage 1', '<table class=\"mw-collapsible wikitable\" style=\"width: 90%;\">\n<tbody><tr>\n<th colspan=\"5\"><a class=\"mw-selflink selflink\">Blue shark</a>\n</th></tr>\n<tr>\n<td>Water types</td>\n<td colspan=\"3\">Sea</td>\n<td>Only surface\n</td></tr>\n<tr>\n<td>Fishing height</td>\n<td colspan=\"3\">Any</td>\n<td>Special fish tiles only\n</td></tr>\n<tr>\n<td>Swim depths</td>\n<td colspan=\"4\">250-1000\n</td></tr>\n<tr>\n<td>Equipment</td>\n<td colspan=\"4\">Professional rod\n</td></tr>\n<tr>\n<td>Fishing times</td>\n<td bgcolor=\"#90EE90\">Morning 4</td>\n<td>Afternoon 3</td>\n<td bgcolor=\"#90EE90\">Evening 4</td>\n<td>Night 2\n</td></tr>\n<tr>\n<td rowspan=\"4\">Baits</td>\n<td bgcolor=\"#90EE90\" colspan=\"3\">Best: Sardines</td>\n<td>(none) 0\n</td></tr>\n<tr>\n<td>Cheese piece 1</td>\n<td>Corn kernel 1</td>\n<td>Dough Ball 1</td>\n<td>Fish bait 0\n</td></tr>\n<tr>\n<td>Fly 0</td>\n<td>Grub 1</td>\n<td>Minnow 5</td>\n<td>Perch 5\n</td></tr>\n<tr>\n<td>Roach 5</td>\n<td>Sardines 10</td>\n<td>Wheat Grain 1</td>\n<td>Wurm 1\n</td></tr>\n<tr>\n<td>Weight at 10ql</td>\n<td colspan=\"4\">4.00kg\n</td></tr>\n<tr>\n<td>Multiplier by ql</td>\n<td colspan=\"4\">0.4\n</td></tr>\n<tr>\n<td>Rod damage</td>\n<td colspan=\"4\">1\n</td></tr></tbody></table>', 2),
(9902, 2689, 'Description', 'Description', 'This marlin is a bluish silvery sturdy thick fish with a distinctive upper jaw that forms a pointed spear or bill and some pretty extraordinary fins.', '<p><i>This marlin is a bluish silvery sturdy thick fish with a distinctive upper jaw that forms a pointed spear or bill and some pretty extraordinary fins.</i>\n</p>', 0),
(9903, 2689, 'Notes', 'Notes', 'Marlin can only be caught on special fishing tiles. Used in some cooking recipes. Can be eaten raw or cooked to relieve a small amount of hunger. Can be used as food for taming. Fish decay extremely rapidly after a few hours in your inventory and out of water. To prevent decay, fish can be stored in food storage bins and in crates. Bait ranking is from 1-10. The higher the number, the more likely that fish is to bite. Fishing time ranking is from 1-4. The higher the number, the more likely you are to see that fish.', '<ul><li>Marlin can only be caught on special fishing tiles.</li>\n<li>Used in some cooking recipes.</li>\n<li>Can be eaten raw or cooked to relieve a small amount of hunger.</li>\n<li>Can be used as food for taming.</li>\n<li>Fish decay extremely rapidly after a few hours in your inventory and out of water. To prevent decay, fish can be stored in food storage bins and in crates.</li>\n<li>Bait ranking is from 1-10. The higher the number, the more likely that fish is to bite.</li>\n<li>Fishing time ranking is from 1-4. The higher the number, the more likely you are to see that fish.</li></ul>', 1),
(9904, 2689, 'Fishing Guidelines', 'Fishing_Guidelines', 'Marlin Water types Sea Only surface Fishing height Top Special fish tiles Swim depths 250-1000 Equipment Deep water rod, Professional rod Fishing times Morning 4 Afternoon 2 Evening 4 Night 3 Baits Best: Minnow (none) 0 Cheese piece 1 Corn kernel 1 Dough Ball 1 Fish bait 0 Fly 0 Grub 1 Minnow 10 Perch 5 Roach 5 Sardines 5 Wheat Grain 1 Wurm 1 Weight at 10ql 20.00kg Multiplier by ql 2 Rod damage 1', '<table class=\"mw-collapsible wikitable\" style=\"width: 90%;\">\n<tbody><tr>\n<th colspan=\"5\"><a class=\"mw-selflink selflink\">Marlin</a>\n</th></tr>\n<tr>\n<td>Water types</td>\n<td colspan=\"3\">Sea</td>\n<td>Only surface\n</td></tr>\n<tr>\n<td>Fishing height</td>\n<td colspan=\"3\">Top</td>\n<td>Special fish tiles\n</td></tr>\n<tr>\n<td>Swim depths</td>\n<td colspan=\"4\">250-1000\n</td></tr>\n<tr>\n<td>Equipment</td>\n<td colspan=\"4\">Deep water rod, Professional rod\n</td></tr>\n<tr>\n<td>Fishing times</td>\n<td bgcolor=\"#90EE90\">Morning 4</td>\n<td>Afternoon 2</td>\n<td bgcolor=\"#90EE90\">Evening 4</td>\n<td>Night 3\n</td></tr>\n<tr>\n<td rowspan=\"4\">Baits</td>\n<td bgcolor=\"#90EE90\" colspan=\"3\">Best: Minnow</td>\n<td>(none) 0\n</td></tr>\n<tr>\n<td>Cheese piece 1</td>\n<td>Corn kernel 1</td>\n<td>Dough Ball 1</td>\n<td>Fish bait 0\n</td></tr>\n<tr>\n<td>Fly 0</td>\n<td>Grub 1</td>\n<td>Minnow 10</td>\n<td>Perch 5\n</td></tr>\n<tr>\n<td>Roach 5</td>\n<td>Sardines 5</td>\n<td>Wheat Grain 1</td>\n<td>Wurm 1\n</td></tr>\n<tr>\n<td>Weight at 10ql</td>\n<td colspan=\"4\">20.00kg\n</td></tr>\n<tr>\n<td>Multiplier by ql</td>\n<td colspan=\"4\">2\n</td></tr>\n<tr>\n<td>Rod damage</td>\n<td colspan=\"4\">1\n</td></tr></tbody></table>', 2),
(9905, 2690, 'Description', 'Description', 'This is a weird beast with eight legs. You have heard scary rumours that larger variants sometimes attack ships.', '<p><i>This is a weird beast with eight legs. You have heard scary rumours that larger variants sometimes attack ships.</i>\n</p>', 0),
(9906, 2690, 'Notes', 'Notes', 'Octopus (fishing) can be caught on special fishing tiles. For the animal that lives in Wurm oceans that you can fight, see Octopus . Used in some cooking recipes. Can be eaten raw or cooked to relieve a small amount of hunger. Can be used as food for taming. Fish decay extremely rapidly after a few hours in your inventory and out of water. To prevent decay, fish can be stored in food storage bins and in crates. Bait ranking is from 1-10. The higher the number, the more likely that fish is to bite. Fishing time ranking is from 1-4. The higher the number, the more likely you are to see that fish.', '<ul><li>Octopus (fishing) can be caught on special fishing tiles.</li>\n<li>For the animal that lives in Wurm oceans that you can fight, see <a href=\"/index.php/Octopus\" title=\"Octopus\">Octopus</a>.</li>\n<li>Used in some cooking recipes.</li>\n<li>Can be eaten raw or cooked to relieve a small amount of hunger.</li>\n<li>Can be used as food for taming.</li>\n<li>Fish decay extremely rapidly after a few hours in your inventory and out of water. To prevent decay, fish can be stored in food storage bins and in crates.</li>\n<li>Bait ranking is from 1-10. The higher the number, the more likely that fish is to bite.</li>\n<li>Fishing time ranking is from 1-4. The higher the number, the more likely you are to see that fish.</li></ul>', 1),
(9907, 2690, 'Fishing Guidelines', 'Fishing_Guidelines', 'Octopus Water types Sea Only surface Fishing height Any Special fish tiles Swim depths 200-800 Equipment Deep water rod, Professional rod Fishing times Morning 2 Afternoon 4 Evening 1 Night 4 Baits Best: Cheese piece (none) 0 Cheese piece 10 Corn kernel 1 Dough Ball 1 Fish bait 5 Fly 0 Grub 1 Minnow 1 Perch 1 Roach 1 Sardines 5 Wheat Grain 1 Wurm 1 Weight at 10ql 1.00kg Multiplier by ql 0.1 Rod damage ?', '<table class=\"mw-collapsible wikitable\" style=\"width: 90%;\">\n<tbody><tr>\n<th colspan=\"5\"><a class=\"mw-selflink selflink\">Octopus</a>\n</th></tr>\n<tr>\n<td>Water types</td>\n<td colspan=\"3\">Sea</td>\n<td>Only surface\n</td></tr>\n<tr>\n<td>Fishing height</td>\n<td colspan=\"3\">Any</td>\n<td>Special fish tiles\n</td></tr>\n<tr>\n<td>Swim depths</td>\n<td colspan=\"4\">200-800\n</td></tr>\n<tr>\n<td>Equipment</td>\n<td colspan=\"4\">Deep water rod, Professional rod\n</td></tr>\n<tr>\n<td>Fishing times</td>\n<td>Morning 2</td>\n<td bgcolor=\"#90EE90\">Afternoon 4</td>\n<td>Evening 1</td>\n<td bgcolor=\"#90EE90\">Night 4\n</td></tr>\n<tr>\n<td rowspan=\"4\">Baits</td>\n<td bgcolor=\"#90EE90\" colspan=\"3\">Best: Cheese piece</td>\n<td>(none) 0\n</td></tr>\n<tr>\n<td>Cheese piece 10</td>\n<td>Corn kernel 1</td>\n<td>Dough Ball 1</td>\n<td>Fish bait 5\n</td></tr>\n<tr>\n<td>Fly 0</td>\n<td>Grub 1</td>\n<td>Minnow 1</td>\n<td>Perch 1\n</td></tr>\n<tr>\n<td>Roach 1</td>\n<td>Sardines 5</td>\n<td>Wheat Grain 1</td>\n<td>Wurm 1\n</td></tr>\n<tr>\n<td>Weight at 10ql</td>\n<td colspan=\"4\">1.00kg\n</td></tr>\n<tr>\n<td>Multiplier by ql</td>\n<td colspan=\"4\">0.1\n</td></tr>\n<tr>\n<td>Rod damage</td>\n<td colspan=\"4\">?\n</td></tr></tbody></table>', 2),
(9939, 2698, 'Description', 'Description', 'You see an arched wall opening', '<p><i>You see an arched wall opening </i>\n</p>', 0),
(9940, 2698, 'Skill Requirements', 'Skill_Requirements', 'At least 30 masonry skill is required to build stone walls. See multi-story housing for more information regarding skill requirements on additional floors.', '<ul><li>At least 30 <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill is required to build stone walls.</li>\n<li>See <a href=\"/index.php/Multi-story_housing#Skill_needed\" title=\"Multi-story housing\">multi-story housing</a> for more information regarding skill requirements on additional floors.</li></ul>', 1),
(9941, 2698, 'Creation', 'Creation', 'Have at least 1 Pottery brick and 1 mortar in your inventory. Activate a trowel and right-click on a wall plan . Select Build and then Pottery T arch . Continuation requires at least 1 Pottery brick and 1 mortar in your inventory.', '<ul><li>Have at least 1 <a href=\"/index.php/Pottery_brick\" title=\"Pottery brick\">Pottery brick</a> and 1 <a href=\"/index.php/Mortar\" title=\"Mortar\">mortar</a> in your inventory.</li>\n<li><b>Activate</b> a <a href=\"/index.php/Trowel\" title=\"Trowel\">trowel</a> and <b>right-click</b> on a <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">wall plan</a>.</li>\n<li>Select <b>Build</b> and then <b>Pottery T arch</b>.</li>\n<li>Continuation requires at least 1 <a href=\"/index.php/Pottery_brick\" title=\"Pottery brick\">Pottery brick</a> and 1 mortar in your inventory.</li></ul>', 2),
(9942, 2698, 'Modifying', 'Modifying', 'You can turn walls to suit your needs by right-clicking them, and selecting Rotate wall .', '<ul><li>You can turn walls to suit your needs by <b>right-clicking</b> them, and selecting <b>Rotate wall</b>.</li></ul>', 3),
(9943, 2698, 'Improving', 'Improving', 'You must repair any damage on the walls with a Pottery brick before improving it. Activate a Pottery brick , right-click the wall and select Repair or Improve . The effective quality of the Pottery brick is affected by its damage and your masonry skill, it must be higher than the wall\'s current quality.', '<ul><li>You must <a href=\"/index.php/Repairing\" title=\"Repairing\">repair</a> any <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> on the walls with a <a href=\"/index.php/Pottery_brick\" title=\"Pottery brick\">Pottery brick</a> before <a href=\"/index.php/Improve\" title=\"Improve\">improving</a> it.</li>\n<li>Activate a <a href=\"/index.php/Pottery_brick\" title=\"Pottery brick\">Pottery brick</a>, right-click the wall and select <i>Repair</i> or <i>Improve</i>.</li>\n<li>The effective <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the <a href=\"/index.php/Pottery_brick\" title=\"Pottery brick\">Pottery brick</a> is affected by its damage and your <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill, it must be higher than the wall\'s current quality.</li></ul>\n<p><br/>\n</p>', 4),
(9944, 2698, 'See also', 'See_also', 'Pottery brick wall Pottery window Pottery door Pottery double door Pottery oriel Pottery narrow window Pottery portcullis Pottery barred wall Pottery arched wall Pottery T arch Pottery arch left Pottery arch right', '<ul><li><a href=\"/index.php/Pottery_brick_wall\" title=\"Pottery brick wall\">Pottery brick wall</a></li>\n<li><a href=\"/index.php/Pottery_window\" title=\"Pottery window\">Pottery window</a></li>\n<li><a href=\"/index.php/Pottery_door\" title=\"Pottery door\">Pottery door</a></li>\n<li><a href=\"/index.php/Pottery_double_door\" title=\"Pottery double door\">Pottery double door</a></li>\n<li><a href=\"/index.php/Pottery_oriel\" title=\"Pottery oriel\">Pottery oriel</a></li>\n<li><a href=\"/index.php/Pottery_narrow_window\" title=\"Pottery narrow window\">Pottery narrow window</a></li>\n<li><a href=\"/index.php/Pottery_portcullis_(wall)\" title=\"Pottery portcullis (wall)\">Pottery portcullis</a></li>\n<li><a href=\"/index.php/Pottery_barred_wall\" title=\"Pottery barred wall\">Pottery barred wall</a></li>\n<li><a href=\"/index.php/Pottery_arched_wall\" title=\"Pottery arched wall\">Pottery arched wall</a></li>\n<li><a class=\"mw-selflink selflink\">Pottery T arch</a></li>\n<li><a href=\"/index.php/Pottery_arch_left\" title=\"Pottery arch left\">Pottery arch left</a></li>\n<li><a href=\"/index.php/Pottery_arch_right\" title=\"Pottery arch right\">Pottery arch right</a></li></ul>', 5),
(9955, 2700, 'Description', 'Description', 'You see a wall', '<p><i>You see a wall </i>\n</p>', 0),
(9956, 2700, 'Skill Requirements', 'Skill_Requirements', 'At least 30 masonry skill is required to build stone walls. See multi-story housing for more information regarding skill requirements on additional floors.', '<ul><li>At least 30 <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill is required to build stone walls.</li>\n<li>See <a href=\"/index.php/Multi-story_housing#Skill_needed\" title=\"Multi-story housing\">multi-story housing</a> for more information regarding skill requirements on additional floors.</li></ul>', 1),
(9957, 2700, 'Creation', 'Creation', 'Have at least 1 Pottery brick and 1 mortar in your inventory. Activate a trowel and right-click on a wall plan . Select Build and then Pottery arch left . Continuation requires at least 1 Pottery brick and 1 mortar in your inventory.', '<ul><li>Have at least 1 <a href=\"/index.php/Pottery_brick\" title=\"Pottery brick\">Pottery brick</a> and 1 <a href=\"/index.php/Mortar\" title=\"Mortar\">mortar</a> in your inventory.</li>\n<li><b>Activate</b> a <a href=\"/index.php/Trowel\" title=\"Trowel\">trowel</a> and <b>right-click</b> on a <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">wall plan</a>.</li>\n<li>Select <b>Build</b> and then <b>Pottery arch left</b>.</li>\n<li>Continuation requires at least 1 <a href=\"/index.php/Pottery_brick\" title=\"Pottery brick\">Pottery brick</a> and 1 mortar in your inventory.</li></ul>', 2),
(9958, 2700, 'Modifying', 'Modifying', 'You can turn walls to suit your needs by right-clicking them, and selecting Rotate wall .', '<ul><li>You can turn walls to suit your needs by <b>right-clicking</b> them, and selecting <b>Rotate wall</b>.</li></ul>', 3),
(9959, 2700, 'Improving', 'Improving', 'You must repair any damage on the walls with a Pottery brick before improving it. Activate a Pottery brick , right-click the wall and select Repair or Improve . The effective quality of the Pottery brick is affected by its damage and your masonry skill, it must be higher than the wall\'s current quality.', '<ul><li>You must <a href=\"/index.php/Repairing\" title=\"Repairing\">repair</a> any <a href=\"/index.php/Damage\" title=\"Damage\">damage</a> on the walls with a <a href=\"/index.php/Pottery_brick\" title=\"Pottery brick\">Pottery brick</a> before <a href=\"/index.php/Improve\" title=\"Improve\">improving</a> it.</li>\n<li>Activate a <a href=\"/index.php/Pottery_brick\" title=\"Pottery brick\">Pottery brick</a>, right-click the wall and select <i>Repair</i> or <i>Improve</i>.</li>\n<li>The effective <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> of the <a href=\"/index.php/Pottery_brick\" title=\"Pottery brick\">Pottery brick</a> is affected by its damage and your <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill, it must be higher than the wall\'s current quality.</li></ul>\n<p><br/>\n</p>', 4),
(9960, 2700, 'See also', 'See_also', 'Pottery brick wall Pottery window Pottery door Pottery double door Pottery oriel Pottery narrow window Pottery portcullis Pottery barred wall Pottery arched wall Pottery T arch Pottery arch left Pottery arch right', '<ul><li><a href=\"/index.php/Pottery_brick_wall\" title=\"Pottery brick wall\">Pottery brick wall</a></li>\n<li><a href=\"/index.php/Pottery_window\" title=\"Pottery window\">Pottery window</a></li>\n<li><a href=\"/index.php/Pottery_door\" title=\"Pottery door\">Pottery door</a></li>\n<li><a href=\"/index.php/Pottery_double_door\" title=\"Pottery double door\">Pottery double door</a></li>\n<li><a href=\"/index.php/Pottery_oriel\" title=\"Pottery oriel\">Pottery oriel</a></li>\n<li><a href=\"/index.php/Pottery_narrow_window\" title=\"Pottery narrow window\">Pottery narrow window</a></li>\n<li><a href=\"/index.php/Pottery_portcullis_(wall)\" title=\"Pottery portcullis (wall)\">Pottery portcullis</a></li>\n<li><a href=\"/index.php/Pottery_barred_wall\" title=\"Pottery barred wall\">Pottery barred wall</a></li>\n<li><a href=\"/index.php/Pottery_arched_wall\" title=\"Pottery arched wall\">Pottery arched wall</a></li>\n<li><a href=\"/index.php/Pottery_T_arch\" title=\"Pottery T arch\">Pottery T arch</a></li>\n<li><a class=\"mw-selflink selflink\">Pottery arch left</a></li>\n<li><a href=\"/index.php/Pottery_arch_right\" title=\"Pottery arch right\">Pottery arch right</a></li></ul>', 5),
(9961, 2701, 'Description', 'Description', 'You see a wall', '<p><i>You see a wall </i>\n</p>', 0),
(9962, 2701, 'Skill Requirements', 'Skill_Requirements', 'At least 30 masonry skill is required to build stone walls. See multi-story housing for more information regarding skill requirements on additional floors.', '<ul><li>At least 30 <a href=\"/index.php/Masonry\" title=\"Masonry\">masonry</a> skill is required to build stone walls.</li>\n<li>See <a href=\"/index.php/Multi-story_housing#Skill_needed\" title=\"Multi-story housing\">multi-story housing</a> for more information regarding skill requirements on additional floors.</li></ul>', 1),
(9963, 2701, 'Creation', 'Creation', 'Have at least 1 Pottery brick and 1 mortar in your inventory. Activate a trowel and right-click on a wall plan . Select Build and then Pottery arch right . Continuation requires at least 1 Pottery brick and 1 mortar in your inventory.', '<ul><li>Have at least 1 <a href=\"/index.php/Pottery_brick\" title=\"Pottery brick\">Pottery brick</a> and 1 <a href=\"/index.php/Mortar\" title=\"Mortar\">mortar</a> in your inventory.</li>\n<li><b>Activate</b> a <a href=\"/index.php/Trowel\" title=\"Trowel\">trowel</a> and <b>right-click</b> on a <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">wall plan</a>.</li>\n<li>Select <b>Build</b> and then <b>Pottery arch right</b>.</li>\n<li>Continuation requires at least 1 <a href=\"/index.php/Pottery_brick\" title=\"Pottery brick\">Pottery brick</a> and 1 mortar in your inventory.</li></ul>', 2),
(9964, 2701, 'Modifying', 'Modifying', 'You can turn walls to suit your needs by right-clicking them, and selecting Rotate wall .', '<ul><li>You can turn walls to suit your needs by <b>right-clicking</b> them, and selecting <b>Rotate wall</b>.</li></ul>', 3),
