INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(14195, 1851, 'Towns in the Alliance', 'Towns_in_the_Alliance', 'White Towns: - Mist - Avalon - East Haven - West Haven - Amishland - The Isle of Memories - Minas Mortis Dark Towns: - New Mirage - Devils peak - Fairy Castle - Sandhurst - Band of Brothers - Nightshade', '<p><b><ins>White Towns:</ins><br/></b>\n- <b><a class=\"mw-redirect\" href=\"/index.php/Mist\" title=\"Mist\">Mist</a></b><br/>\n- <b>Avalon</b><br/>\n- <b>East Haven</b><br/>\n- <b><a class=\"mw-redirect\" href=\"/index.php/West_Haven\" title=\"West Haven\">West Haven</a></b><br/>\n- <b>Amishland</b><br/>\n- <b>The Isle of Memories</b><br/>\n- <b><a class=\"mw-redirect\" href=\"/index.php/Minas_Mortis\" title=\"Minas Mortis\">Minas Mortis</a></b><br/>\n</p>\n<p><b><ins>Dark Towns:</ins><br/></b>\n- <b>New Mirage</b><br/>\n- <b><a class=\"mw-redirect\" href=\"/index.php/Devils_peak\" title=\"Devils peak\">Devils peak</a></b><br/>\n- <b><a class=\"mw-redirect\" href=\"/index.php/Fairy_Castle\" title=\"Fairy Castle\">Fairy Castle</a></b><br/>\n- <b><a class=\"mw-redirect\" href=\"/index.php/Sandhurst\" title=\"Sandhurst\">Sandhurst</a></b><br/>\n- <b>Band of Brothers</b><br/> \n- <b>Nightshade</b><br/>\n</p>', 0),
(14216, 3722, 'Description', 'Description', 'A translucent necklace.', '<p><i>A translucent necklace.</i>\n</p>', 0),
(14217, 3722, 'Notes', 'Notes', 'Obtained from certain treasure chests, found by following exploration clues from a treasure map. The translucent necklace takes on the same model as the medallion necklace, when it is not worn.', '<ul><li>Obtained from certain treasure chests, found by following exploration clues from a treasure map.</li>\n<li>The translucent necklace takes on the same model as the medallion necklace, when it is not worn.</li></ul>', 1),
(14234, 3725, 'Description', 'Description', 'A necklace with an Aquamarine gem inside.', '<p><i>A necklace with an Aquamarine gem inside.</i>\n</p>', 0),
(14235, 3725, 'Notes', 'Notes', 'Obtained from certain treasure chests, found by following exploration clues from a treasure map. The aquamarine necklace takes on the same model as the medallion necklace, when it is not worn.', '<ul><li>Obtained from certain treasure chests, found by following exploration clues from a treasure map.</li>\n<li>The aquamarine necklace takes on the same model as the medallion necklace, when it is not worn.</li></ul>', 1),
(14236, 2533, 'Description', 'Description', 'A wooden cupboard, used to store small amounts of precious liquids. Used to store a variety of Alchemical supplies and liquids with reduced decay.', '<p><i>A wooden cupboard, used to store small amounts of precious liquids.</i>\n</p>\n<p>Used to store a variety of Alchemical supplies and <a href=\"/index.php/Liquid\" title=\"Liquid\">liquids</a> with reduced decay.\n</p>', 0),
(14237, 2533, 'Notes', 'Notes', 'Has ten measuring flasks with a maximum of 5kg capacity each. Measuring flasks can be set to a specific volume (like the measuring jug ) by right-clicking and can be sealed and unsealed at will without requiring a peg or wax sealing kit. To set the volume of the flasks, pick up the Alchemist\'s cupboard, open it up while inside inventory, right click the flasks to set volume. Has 2 Basins with 60 kg capacity each. Basins can be sealed with a Wax sealing kit. Has 4 storage cabinets which can store any kind of bulk item (food and non-food) and can be locked (including quality locks), but they do have a much smaller capacity than a food or bulk storage bin. Can be planted. Cannot be mailed . Has to be empty in order to be picked up. Can be loaded into a large cart - even without being empty Cannot be dyed. Requires 20 fine carpentry Some items may be placed on top of the cupboard, as decoration. Since the item is a container already, any items placed on it will be dropped on the ground when it is picked up; a message in event log will notify the player of this.', '<ul><li>Has ten measuring flasks with a maximum of 5kg capacity each.\n<ul><li>Measuring flasks can be set to a specific volume (like the <a href=\"/index.php/Measuring_jug\" title=\"Measuring jug\">measuring jug</a>) by right-clicking and can be sealed and unsealed at will without requiring a peg or wax sealing kit. To set the volume of the flasks, pick up the Alchemist\'s cupboard, open it up while inside inventory, right click the flasks to set volume.</li></ul></li>\n<li>Has 2 Basins with 60 kg capacity each.\n<ul><li>Basins can be sealed with a Wax sealing kit.</li></ul></li>\n<li>Has 4 storage cabinets which can store any kind of bulk item (food and non-food) and can be locked (including quality locks), but they do have a much smaller capacity than a food or bulk storage bin.</li>\n<li>Can be planted.</li>\n<li>Cannot be <a href=\"/index.php/Mail\" title=\"Mail\">mailed</a>.</li>\n<li>Has to be empty in order to be picked up.</li>\n<li>Can be loaded into a large cart - even without being empty</li>\n<li>Cannot be dyed.</li>\n<li>Requires 20 fine carpentry</li>\n<li>Some items may be placed on top of the cupboard, as decoration. Since the item is a container already, any items placed on it will be dropped on the ground when it is picked up; a message in event log will notify the player of this.</li></ul>', 1),
(14238, 2456, 'Description', 'Description', 'A seed from air-dried fruits of the chili pepper family of the species Capsicum annum.', '<p><i>A seed from air-dried fruits of the chili pepper family of the species Capsicum annum.</i>\n</p>', 0),
(14239, 2456, 'Notes', 'Notes', 'Can be used in some cooking recipes. Can be planted in a pottery planter in order to grow more.', '<ul><li>Can be used in some cooking recipes.</li>\n<li>Can be planted in a <a href=\"/index.php/Pottery_planter\" title=\"Pottery planter\">pottery planter</a> in order to grow more.</li></ul>', 1),
(14240, 2456, 'Images', 'Images', 'Paprika planted in a pottery planter', '<ul class=\"gallery mw-gallery-traditional\">\n<li class=\"gallerybox\" style=\"width: 155px\"><div style=\"width: 155px\">\n<div class=\"thumb\" style=\"width: 150px;\"><div style=\"margin:15px auto;\"><a class=\"image\" href=\"/index.php/File:Paprika2.jpg\"><img alt=\"\" data-file-height=\"419\" data-file-width=\"330\" decoding=\"async\" height=\"120\" src=\"/images/thumb/7/70/Paprika2.jpg/94px-Paprika2.jpg\" srcset=\"/images/thumb/7/70/Paprika2.jpg/142px-Paprika2.jpg 1.5x, /images/thumb/7/70/Paprika2.jpg/189px-Paprika2.jpg 2x\" width=\"94\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>Paprika planted in a pottery planter\n</p>\n</div>\n</div></li>\n</ul>', 2),
(14241, 2456, 'See Also', 'See_Also', 'Paprika Pottery planter Spices Cooking', '<ul><li><a href=\"/index.php/Paprika\" title=\"Paprika\">Paprika</a></li>\n<li><a href=\"/index.php/Pottery_planter\" title=\"Pottery planter\">Pottery planter</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Spices\" title=\"Spices\">Spices</a></li>\n<li><a href=\"/index.php/Cooking\" title=\"Cooking\">Cooking</a></li></ul>', 3),
(14242, 3728, 'Description', 'Description', 'The seeds from a carrot.', '<p><i>The seeds from a carrot.</i>\n</p>', 0),
(14243, 3728, 'Usage', 'Usage', 'Carrot seed is a farming product used to grow Carrots .', '<ul><li><b>Carrot seed</b> is a <a href=\"/index.php/Farming\" title=\"Farming\">farming</a> product used to grow <a href=\"/index.php/Carrot\" title=\"Carrot\">Carrots</a>.</li></ul>', 1),
(14244, 3728, 'Method', 'Method', 'Carrot seed can be sown on a dirt tile to grow Carrots . To get a seed, right-click a Carrot and choose Pick seeds . The Carrot must be full weight (0.50 kg). Carrot seed can also be found by Foraging at Animal burrow and Critter nest Resource nodes .', '<ul><li>Carrot seed can be <a href=\"/index.php/Farming\" title=\"Farming\">sown</a> on a <a href=\"/index.php/Dirt_tile\" title=\"Dirt tile\">dirt tile</a> to grow <a href=\"/index.php/Carrot\" title=\"Carrot\">Carrots</a>.</li>\n<li>To get a seed, right-click a <a href=\"/index.php/Carrot\" title=\"Carrot\">Carrot</a> and choose <i>Pick seeds</i>. The Carrot must be full weight (0.50 kg).</li>\n<li>Carrot seed can also be found by <a href=\"/index.php/Foraging\" title=\"Foraging\">Foraging</a> at <a href=\"/index.php/Animal_burrow\" title=\"Animal burrow\">Animal burrow</a> and <a href=\"/index.php/Critter_nest\" title=\"Critter nest\">Critter nest</a> <a href=\"/index.php/Resource_nodes\" title=\"Resource nodes\">Resource nodes</a>.</li></ul>', 2),
(14245, 3729, 'Description', 'Description', 'The seed from a cucumber.', '<p><i>The seed from a cucumber.</i>\n</p>', 0),
(14246, 3729, 'Usage', 'Usage', 'Cucumber seed is a farming product used to grow Cucumbers .', '<ul><li><b>Cucumber seed</b> is a <a href=\"/index.php/Farming\" title=\"Farming\">farming</a> product used to grow <a href=\"/index.php/Cucumber\" title=\"Cucumber\">Cucumbers</a>.</li></ul>', 1),
(14247, 3729, 'Method', 'Method', 'Cucumber seed can be sown on a dirt tile to grow Cucumbers . To get a seed, right-click a Cucumber and choose Pick seeds . The Cucumber must be full weight (0.50 kg). Cucumber seed can also be found by Foraging at Animal burrow and Critter nest Resource nodes .', '<ul><li>Cucumber seed can be <a href=\"/index.php/Farming\" title=\"Farming\">sown</a> on a <a href=\"/index.php/Dirt_tile\" title=\"Dirt tile\">dirt tile</a> to grow <a href=\"/index.php/Cucumber\" title=\"Cucumber\">Cucumbers</a>.</li>\n<li>To get a seed, right-click a <a href=\"/index.php/Cucumber\" title=\"Cucumber\">Cucumber</a> and choose <i>Pick seeds</i>. The Cucumber must be full weight (0.50 kg).</li>\n<li>Cucumber seed can also be found by <a href=\"/index.php/Foraging\" title=\"Foraging\">Foraging</a> at <a href=\"/index.php/Animal_burrow\" title=\"Animal burrow\">Animal burrow</a> and <a href=\"/index.php/Critter_nest\" title=\"Critter nest\">Critter nest</a> <a href=\"/index.php/Resource_nodes\" title=\"Resource nodes\">Resource nodes</a>.</li></ul>', 2),
(14248, 3730, 'Description', 'Description', 'The seed from a lettuce.', '<p><i>The seed from a lettuce.</i>\n</p>', 0),
(14249, 3730, 'Usage', 'Usage', 'Lettuce seed is a farming product used to grow Lettuce .', '<ul><li><b>Lettuce seed</b> is a <a href=\"/index.php/Farming\" title=\"Farming\">farming</a> product used to grow <a href=\"/index.php/Lettuce\" title=\"Lettuce\">Lettuce</a>.</li></ul>', 1),
(14250, 3730, 'Method', 'Method', 'Lettuce seed can be sown on a dirt tile to grow Lettuce . To get a seed, right-click Lettuce and choose Pick seeds . The Lettuce must be full weight (0.50 kg). Lettuce seed can also be found by Foraging at Animal burrow and Critter nest Resource nodes .', '<ul><li>Lettuce seed can be <a href=\"/index.php/Farming\" title=\"Farming\">sown</a> on a <a href=\"/index.php/Dirt_tile\" title=\"Dirt tile\">dirt tile</a> to grow <a href=\"/index.php/Lettuce\" title=\"Lettuce\">Lettuce</a>.</li>\n<li>To get a seed, right-click <a href=\"/index.php/Lettuce\" title=\"Lettuce\">Lettuce</a> and choose <i>Pick seeds</i>. The Lettuce must be full weight (0.50 kg).</li>\n<li>Lettuce seed can also be found by <a href=\"/index.php/Foraging\" title=\"Foraging\">Foraging</a> at <a href=\"/index.php/Animal_burrow\" title=\"Animal burrow\">Animal burrow</a> and <a href=\"/index.php/Critter_nest\" title=\"Critter nest\">Critter nest</a> <a href=\"/index.php/Resource_nodes\" title=\"Resource nodes\">Resource nodes</a>.</li></ul>', 2),
(14251, 3731, 'Description', 'Description', 'The seed from a tomato.', '<p><i>The seed from a tomato.</i>\n</p>', 0),
(14252, 3731, 'Usage', 'Usage', 'Created by picking tomatoes . Can be sown in dirt to create a field of tomatoes .', '<p>Created by <a href=\"/index.php/Farming\" title=\"Farming\">picking tomatoes</a>. Can be <a href=\"/index.php/Farming\" title=\"Farming\">sown</a> in <a href=\"/index.php/Dirt_tile\" title=\"Dirt tile\">dirt</a> to create a <a href=\"/index.php/Field\" title=\"Field\">field</a> of <a href=\"/index.php/Tomato\" title=\"Tomato\">tomatoes</a>.\n</p>', 1),
(14253, 3732, 'Description', 'Description', 'The seed from a sugar beet.', '<p><i>The seed from a sugar beet.</i>\n</p>', 0),
(14254, 3732, 'Usage', 'Usage', 'Sugar beet seed is a farming product used to grow Sugar beets .', '<ul><li><b>Sugar beet seed</b> is a <a href=\"/index.php/Farming\" title=\"Farming\">farming</a> product used to grow <a href=\"/index.php/Sugar_beet\" title=\"Sugar beet\">Sugar beets</a>.</li></ul>', 1),
(14255, 3732, 'Method', 'Method', 'Sugar beet seed can be sown on a dirt tile to grow Sugar beets . To get a seed, right-click a Sugar beet and choose Pick seeds . The Sugar beet must be full weight (1.00 kg). Sugar beet seed can also be found by Foraging at Animal burrow and Critter nest Resource nodes .', '<ul><li>Sugar beet seed can be <a href=\"/index.php/Farming\" title=\"Farming\">sown</a> on a <a href=\"/index.php/Dirt_tile\" title=\"Dirt tile\">dirt tile</a> to grow <a href=\"/index.php/Sugar_beet\" title=\"Sugar beet\">Sugar beets</a>.</li>\n<li>To get a seed, right-click a <a href=\"/index.php/Sugar_beet\" title=\"Sugar beet\">Sugar beet</a> and choose <i>Pick seeds</i>. The Sugar beet must be full weight (1.00 kg).</li>\n<li>Sugar beet seed can also be found by <a href=\"/index.php/Foraging\" title=\"Foraging\">Foraging</a> at <a href=\"/index.php/Animal_burrow\" title=\"Animal burrow\">Animal burrow</a> and <a href=\"/index.php/Critter_nest\" title=\"Critter nest\">Critter nest</a> <a href=\"/index.php/Resource_nodes\" title=\"Resource nodes\">Resource nodes</a>.</li></ul>', 2),
(14287, 1001, 'Introduction', 'Introduction', 'This mystical, magical system creates items of an improved functionality. There are three classes of item improvements; Rare Rare items have a dark blue font color when held in your inventory, and shimmer slightly of white when on the ground. Rare items are, as the name suggests, rare. Only a few items turn rare, even after attempting to get one for a prolonged time. Supreme Supreme items have a light blue (cyan) font color when in inventory, and shimmer blue when on the ground This is the intermediate rarity, and while it\'s rarer than rare items, it\'s not unheard of. Fantastic Fantastic items have a pink font color when in your inventory, and shimmer gold when on the ground. This is the highest rarity one can achieve.', '<p>This mystical, magical system creates items of an improved functionality. \n</p>\n<p>There are three classes of item improvements;\n</p>\n<ul><li><b><span style=\"color: #4299E0;\">Rare</span></b>\n<ul><li>Rare items have a dark blue font color when held in your inventory, and shimmer slightly of white when on the ground.</li>\n<li>Rare items are, as the name suggests, rare. Only a few items turn rare, even after attempting to get one for a prolonged time.</li></ul></li>\n<li><b><span style=\"color: #00FFFF;\">Supreme</span></b>\n<ul><li>Supreme items have a light blue (cyan) font color when in inventory, and shimmer blue when on the ground</li>\n<li>This is the intermediate rarity, and while it\'s rarer than rare items, it\'s not unheard of.</li></ul></li>\n<li><b><span style=\"color: #FF00FF;\">Fantastic</span></b>\n<ul><li>Fantastic items have a pink font color when in your inventory, and shimmer gold when on the ground.</li>\n<li>This is the highest rarity one can achieve.</li></ul></li></ul>', 0),
(14288, 1001, 'Rare Items', 'Rare_Items', 'This is a very rare and interesting version of the item. Players may occasionally succeed in creating or finding rare items. A drum roll plays and visual cue appears when your chance to create or generate a rare item arises. The visual cue is a green halo which will surround the border of the screen, lasting a fraction of a second. Your event text will say You have a moment of inspiration . Players often call this event an MOI, a rare roll, or a drumroll. When you successfully turn an item rare, the text in your inventory will change color.', '<p><i>This is a very rare and interesting version of the item.</i>\n</p>\n<p>Players may occasionally succeed in creating or finding rare items. A drum roll plays and visual cue appears when your chance to create or generate a rare item arises. The visual cue is a green halo which will surround the border of the screen, lasting a fraction of a second. Your event text will say <i>You have a moment of inspiration</i>. Players often call this event an MOI, a rare roll, or a drumroll. \n</p>\n<p><a class=\"image\" href=\"/index.php/File:Drumroll.jpg\" title=\"Moment of inspiration/drumroll visual effect\"><img alt=\"Moment of inspiration/drumroll visual effect\" data-file-height=\"1080\" data-file-width=\"1920\" decoding=\"async\" height=\"169\" src=\"/images/thumb/0/06/Drumroll.jpg/300px-Drumroll.jpg\" srcset=\"/images/thumb/0/06/Drumroll.jpg/450px-Drumroll.jpg 1.5x, /images/thumb/0/06/Drumroll.jpg/600px-Drumroll.jpg 2x\" width=\"300\"/></a>\n</p>\n<p>When you successfully turn an item rare, the text in your inventory will change color. \n</p>\n<p><br/>\n<a class=\"image\" href=\"/index.php/File:Rare_items.jpg\"><img alt=\"Rare items.jpg\" data-file-height=\"77\" data-file-width=\"479\" decoding=\"async\" height=\"77\" src=\"/images/b/b6/Rare_items.jpg\" width=\"479\"/></a>\n</p>', 1),
(14289, 1001, 'Supreme Items', 'Supreme_Items', 'This is a supreme example of the item, with fine details and slick design. Players may occasionally succeed in creating or finding supreme items. A \"drum-roll\" and visual cue appears when your chance to create or generate a supreme item arises, just like with rare items.', '<p><i>This is a supreme example of the item, with fine details and slick design.</i>\n</p>\n<p>Players may occasionally succeed in creating or finding supreme items. A \"drum-roll\" and visual cue appears when your chance to create or generate a supreme item arises, just like with rare items. \n</p>\n<p><a class=\"image\" href=\"/index.php/File:Supreme_item_.png\"><img alt=\"Supreme item .png\" data-file-height=\"18\" data-file-width=\"458\" decoding=\"async\" height=\"18\" src=\"/images/3/35/Supreme_item_.png\" width=\"458\"/></a>\n</p>', 2),
(14290, 1001, 'Fantastic Items', 'Fantastic_Items', 'This is a fantastic example of the item, with fascinating design details and perfect ideas for functionality. Players may occasionally succeed in creating or finding fantastic items. A \"drum-roll\" and visual cue appears when your chance to create or generate a fantastic item arises, just like with rare and supreme items.', '<p><i>This is a fantastic example of the item, with fascinating design details and perfect ideas for functionality.</i>\n</p>\n<p>Players may occasionally succeed in creating or finding fantastic items. A \"drum-roll\" and visual cue appears when your chance to create or generate a fantastic item arises, just like with rare and supreme items.\n</p>\n<p><a class=\"image\" href=\"/index.php/File:Fantasitc_Item.png\"><img alt=\"Fantasitc Item.png\" data-file-height=\"22\" data-file-width=\"418\" decoding=\"async\" height=\"22\" src=\"/images/6/6a/Fantasitc_Item.png\" width=\"418\"/></a>\n</p>', 3),
(14291, 1001, 'Notes', 'Notes', 'The improvement that a rare (or better) status grants varies per item type. Items have a subtle pulsating graphical effect. The pulsating graphic effect is also different colors depending on the rarity: rare items are white, supreme are blue, and fantastic items are gold. Premium accounts have an added bonus to the creation of rare, supreme, and fantastic items over non-premium players. Rare, supreme, and fantastic materials may not be put in a bulk storage bin or food storage bin. Rare items, both materials and finished items, can be protected from damage by keeping them in an inventory, merchant, bank, small magical chest , or large magical chest . All types of item can have \'rarity\', but not all of them have advantages. Using a rare, supreme, or fantastic bow string to string a bow makes it lose the status and become a normal bow string. Any rarity on tool and weapon heads (including blades and spear tips) will transfer over to the completed item. Any rarity on fragments will transfer over to the completed item. Rarity of ore will transfer to a metal lump when smelted. A moment of inspiration while improving has a small chance to turn an item into a rare, supreme or fantastic. Adding a rare material to an item with 3+ parts has a chance of 1/(# of parts) of turning rare. Improving an item with a rare material has a 1/100 chance to transfer the rarity. Moments of inspiration (rare rolls) do not produce rare crops while harvesting, however there is a 1 in 4 chance of discovering a Treasure map while harvesting or tending. It is also believed that a moment of inspiration during a harvest action may increase the chance at a higher yield during that single action.', '<ul><li>The improvement that a rare (or better) status grants varies per item type.</li>\n<li>Items have a subtle pulsating graphical effect. The pulsating graphic effect is also different colors depending on the rarity: rare items are white, supreme are blue, and fantastic items are gold.</li>\n<li>Premium accounts have an added bonus to the creation of rare, supreme, and fantastic items over non-premium players.</li>\n<li>Rare, supreme, and fantastic materials may not be put in a bulk storage bin or food storage bin.</li>\n<li>Rare items, both materials and finished items, can be protected from damage by keeping them in an inventory, merchant, bank, <a href=\"/index.php/Small_magical_chest\" title=\"Small magical chest\">small magical chest</a>, or <a href=\"/index.php/Large_magical_chest\" title=\"Large magical chest\">large magical chest</a>.</li>\n<li>All types of item can have \'rarity\', but not all of them have advantages.</li>\n<li>Using a rare, supreme, or fantastic bow string to string a bow makes it lose the status and become a normal bow string.</li>\n<li>Any rarity on tool and weapon heads (including blades and spear tips) will transfer over to the completed item.</li>\n<li>Any rarity on <a class=\"mw-redirect\" href=\"/index.php/Fragments\" title=\"Fragments\">fragments</a> will transfer over to the completed item.</li>\n<li>Rarity of <a class=\"mw-redirect\" href=\"/index.php/Ore\" title=\"Ore\">ore</a> will transfer to a <a href=\"/index.php/Metal_lumps\" title=\"Metal lumps\">metal lump</a> when smelted.</li>\n<li>A moment of inspiration while improving has a small chance to turn an item into a rare, supreme or fantastic.</li>\n<li>Adding a rare material to an item with 3+ parts has a chance of 1/(# of parts) of turning rare.</li>\n<li>Improving an item with a rare material has a 1/100 chance to transfer the rarity.</li>\n<li>Moments of inspiration (rare rolls) do not produce rare crops while harvesting, however there is a 1 in 4 chance of discovering a <a href=\"/index.php/Treasure_hunt\" title=\"Treasure hunt\"> Treasure map</a> while harvesting or tending. It is also believed that a moment of inspiration during a harvest action may increase the chance at a higher yield during that single action.</li></ul>', 4),
(14292, 1001, 'Rare Functionality', 'Rare_Functionality', 'Note: Rare functionality is still not completely understood and is an exciting aspect of the game.  Most information listed is only an observation of one or more players rather than confirmed by developers. Sacrificing When you sacrifice the item at the altar of your god, you will be granted 99% nutrition, food, and water. If you have any wounds, one of them will also be healed completely, regardless of severity. If the item is supreme, you will also get a random skill tick. If the item is fantastic, you will also get a skill tick, but a much larger one than a supreme. Note : fragments with rarity do not give these bonuses, as they are not completed items. Raw Materials This includes anything you use up to create something else, examples being sand , dirt , planks , nails and so on.\nUpon completely consuming the item - through improving with it, or creating an item with it - there is a small chance of its rarity transferring to the item that are being worked on exists. Tools and Toolbelts Rare tools typically receive less damage during use and enchantments, such as Circle of cunning and Wind of ages , decrease less over time.  Damage reduction from use stacks with the reduction coming from oakenwood and steel materials. Rare: 10% damage reduction from use.  Five times less likely to lose an enchant level on use per this announcement . Supreme: 19% damage reduction from use.  Ten times less likely to lose an enchant level on use. Fantastic: ??% damage reduction, from use.  Fifteen times less likely to lose an enchant level on use. Toolbelts gain an extra slot per rarity level. Go here: Talk page for more and comprehensive individual rare item listings. Gathering Tool Specifics Tools that are used to gather resources - for example shovel or pickaxe , get a slightly faster timer (0.1 seconds subtracted per rarity level) and provides a higher quality resource upon finishing the action. How much higher is determined by a multitude of factors: Your skill. The gains are severely reduced when producing resources over 90 QL The QL cap of the resource. Only applicable to mining. The rarity of your tool. Rare grants 1.5 additional QL at low QL levels, supreme and fantastic more so. Note: The additional QL bonus can and will be above your skill level. Boats Each level of rarity adds another \"shadow passenger\" to the boat, thus making it go faster. The rarity level does NOT overcap the amount of passengers you can have, and you will lose the benefit if you fill the shadow passengers slot with an actual passenger. Rarity and speed bonus of boats You have a fantastic sailing boat , which can hold 5 total players, the commander and 4 passengers. [_] = Empty Slot [C] = Commander [P] = Passenger [S] = Shadow passenger [C][S][S][S][_] So, without any additional players on your boat, you already have 3/4 out of the maximum speed boost you get from passengers. If you pick up two passengers, the situation will look like this: [C][P][P][S][S] This means that you\'ve lost 1/3 of the bonus that the fantastic boat gives since it will not go over the cap on how much speed bonus a boat can get. Armour Armour pieces that have been granted the boon of rarity will have additional damage mitigation. Each level of rarity grants another 3% damage mitigation on top of the static mitigation from the armour type. It has also been shown to increase the glance rate when compared to normal, non-rare, armour. Weapons Weapons that turn rare, supreme, or fantastic are granted increased critical strike chance on hit. Rare: 10% Supreme: 30% Fantastic: 50% This is a modifier on the default critical strike chance (usually 0-2%). Critical hits are enabled in PvE combat and deal 150% of the original damage. Horse Shoes Horse shoes that turn rare, supreme, or fantastic will give an added speed bonus. Rare: 0.48 km/h speed bonus. Supreme: 0.96 km/h speed bonus. Fantastic: 1.44 km/h speed bonus.', '<table style=\"background-color:#f8f8f8; -moz-border-radius:10px; width:50%; border:2px solid #e0e0e0; margin-left:0 auto; padding:5px; -moz-outline-style: outset; -moz-outline-radius: 10px; -moz-outline-color: #e0e0e0;\">\n<tbody><tr>\n<td><div class=\"floatleft\"><a class=\"image\" href=\"/index.php/File:Information_icon.png\"><img alt=\"Information icon.png\" data-file-height=\"62\" data-file-width=\"62\" decoding=\"async\" height=\"30\" src=\"/images/thumb/1/1c/Information_icon.png/30px-Information_icon.png\" srcset=\"/images/thumb/1/1c/Information_icon.png/45px-Information_icon.png 1.5x, /images/thumb/1/1c/Information_icon.png/60px-Information_icon.png 2x\" width=\"30\"/></a></div>\n</td>\n<td><b>Note:</b> <a class=\"mw-selflink selflink\">Rare</a> functionality is still not completely understood and is an exciting aspect of the game.  Most information listed is only an observation of one or more players rather than confirmed by developers.\n</td></tr></tbody></table>\n<h3><span class=\"mw-headline\" id=\"Sacrificing\">Sacrificing</span></h3>\n<p>When you <a class=\"mw-redirect\" href=\"/index.php/Sacrifice\" title=\"Sacrifice\">sacrifice</a> the item at the altar of your god, you will be granted 99% nutrition, food, and water. If you have any wounds, one of them will also be healed completely, regardless of severity.\n</p>\n<ul><li>If the item is supreme, you will also get a random skill tick.</li>\n<li>If the item is fantastic, you will also get a skill tick, but a much larger one than a supreme.</li>\n<li><b>Note</b>: <a href=\"/index.php/Unidentified_fragment\" title=\"Unidentified fragment\">fragments</a> with rarity do not give these bonuses, as they are not completed items.</li></ul>\n<h3><span class=\"mw-headline\" id=\"Raw_Materials\">Raw Materials</span></h3>\n<p>This includes anything you use up to create something else, examples being <a class=\"mw-redirect\" href=\"/index.php/Sand\" title=\"Sand\">sand</a>, <a href=\"/index.php/Dirt\" title=\"Dirt\">dirt</a>, <a class=\"mw-redirect\" href=\"/index.php/Planks\" title=\"Planks\">planks</a>, <a href=\"/index.php/Nails\" title=\"Nails\">nails</a> and so on.\nUpon completely consuming the item - through improving with it, or creating an item with it - there is a <i>small</i> chance of its rarity transferring to the item that are being worked on exists.\n</p>\n<h3><span class=\"mw-headline\" id=\"Tools_and_Toolbelts\">Tools and Toolbelts</span></h3>\n<p>Rare tools typically receive less damage during use and enchantments, such as <a href=\"/index.php/Circle_of_cunning\" title=\"Circle of cunning\">Circle of cunning</a> and <a href=\"/index.php/Wind_of_ages\" title=\"Wind of ages\">Wind of ages</a>, decrease less over time.  Damage reduction from use stacks with the reduction coming from oakenwood and steel materials.\n</p>\n<ul><li>Rare: 10% damage reduction from use.  Five times less likely to lose an enchant level on use per <a class=\"external text\" href=\"https://forum.wurmonline.com/index.php?/topic/157432-valrei-international-035/\" rel=\"nofollow\">this announcement</a>.</li>\n<li>Supreme: 19% damage reduction from use.  Ten times less likely to lose an enchant level on use.</li>\n<li>Fantastic: ??% damage reduction, from use.  Fifteen times less likely to lose an enchant level on use.</li></ul>\n<p><a href=\"/index.php/Toolbelt\" title=\"Toolbelt\">Toolbelts</a> gain an extra slot per rarity level.\n</p>\n<p>Go here: <a href=\"/index.php/Talk:Rare_item#Individual_Item_Reports\" title=\"Talk:Rare item\">Talk page</a> for more and comprehensive individual rare item listings.\n</p>\n<h3><span class=\"mw-headline\" id=\"Gathering_Tool_Specifics\">Gathering Tool Specifics</span></h3>\n<p>Tools that are used to gather resources - for example <a href=\"/index.php/Shovel\" title=\"Shovel\">shovel</a> or <a href=\"/index.php/Pickaxe\" title=\"Pickaxe\">pickaxe</a>, get a slightly faster timer (0.1 seconds subtracted per rarity level) and provides a higher quality resource upon finishing the action. How much higher is determined by a multitude of factors:\n</p>\n<ul><li>Your skill. The gains are severely reduced when producing resources over 90 QL</li>\n<li>The QL cap of the resource. Only applicable to mining.</li>\n<li>The rarity of your tool. Rare grants 1.5 additional QL at low QL levels, supreme and fantastic more so.</li>\n<li>Note: The additional QL bonus can and will be above your skill level.</li></ul>\n<h3><span class=\"mw-headline\" id=\"Boats\">Boats</span></h3>\n<p>Each level of rarity adds another \"shadow passenger\" to the boat, thus making it go faster. The rarity level does <b>NOT</b> overcap the amount of passengers you can have, and you will lose the benefit if you fill the shadow passengers slot with an actual passenger.\n</p>\n<h4><span class=\"mw-headline\" id=\"Rarity_and_speed_bonus_of_boats\">Rarity and speed bonus of boats</span></h4>\n<dl><dd>You have a fantastic <a class=\"mw-redirect\" href=\"/index.php/Sailing_boat\" title=\"Sailing boat\">sailing boat</a>, which can hold 5 total players, the commander and 4 passengers.</dd></dl>\n<dl><dd><dl><dd>[_] = Empty Slot<br/></dd>\n<dd>[C] = Commander<br/></dd>\n<dd>[P] = Passenger <br/></dd>\n<dd>[S] = Shadow passenger<br/></dd></dl></dd></dl>\n<dl><dd><dl><dd>[C][S][S][S][_]</dd></dl></dd></dl>\n<dl><dd>So, without any additional players on your boat, you already have 3/4 out of the maximum speed boost you get from passengers.</dd>\n<dd>If you pick up two passengers, the situation will look like this:</dd></dl>\n<dl><dd><dl><dd>[C][P][P][S][S]</dd></dl></dd></dl>\n<dl><dd>This means that you\'ve lost 1/3 of the bonus that the fantastic boat gives since it will not go over the cap on how much speed bonus a boat can get.</dd></dl>\n<h3><span class=\"mw-headline\" id=\"Armour\">Armour</span></h3>\n<p>Armour pieces that have been granted the boon of rarity will have additional damage mitigation. Each level of rarity grants another 3% damage mitigation on top of the static mitigation from the armour type. It has also been shown to increase the glance rate when compared to normal, non-rare, armour.\n</p>\n<h3><span class=\"mw-headline\" id=\"Weapons\">Weapons</span></h3>\n<p>Weapons that turn rare, supreme, or fantastic are granted increased critical strike chance on hit.\n</p>\n<ul><li>Rare: 10%</li>\n<li>Supreme: 30%</li>\n<li>Fantastic: 50%</li></ul>\n<p>This is a modifier on the default critical strike chance (usually 0-2%).\n</p>\n<p>Critical hits are enabled in PvE combat and deal 150% of the original damage.\n</p>\n<h3><span class=\"mw-headline\" id=\"Horse_Shoes\">Horse Shoes</span></h3>\n<p>Horse shoes that turn rare, supreme, or fantastic will give an added speed bonus.\n</p>\n<ul><li>Rare: 0.48 km/h speed bonus.</li>\n<li>Supreme: 0.96 km/h speed bonus.</li>\n<li>Fantastic: 1.44 km/h speed bonus.</li></ul>', 5),
(14293, 1001, 'External links', 'External_links', 'Rare Item Reports on the Wurm Forum Manny explains rare item timer and effects of rare items Rolf explains possible rare creation improving with rare materials Talk page with more and comprehensive individual item listings.', '<ul><li><a class=\"external text\" href=\"http://forum.wurmonline.com/index.php?/topic/59948-rare-item-reports/\" rel=\"nofollow\">Rare Item Reports on the Wurm Forum</a></li>\n<li><a class=\"external text\" href=\"http://forum.wurmonline.com/index.php?/topic/59948-rare-item-reports/page__st__20#entry592357\" rel=\"nofollow\">Manny explains rare item timer and effects of rare items</a></li>\n<li><a class=\"external text\" href=\"http://forum.wurmonline.com/index.php?/topic/94002-rare-raw-resource-to-rare-refined-item/?p=945189\" rel=\"nofollow\">Rolf explains possible rare creation improving with rare materials</a></li>\n<li><a href=\"/index.php/Talk:Rare_item#Individual_Item_Reports\" title=\"Talk:Rare item\">Talk page</a> with more and comprehensive individual item listings.</li></ul>', 6),
(14294, 1001, 'Developer comments', 'Developer_comments', 'When rare items were introduced players were told \"You get approximately 1 chance of 50% each hour to create a rare item.\"  What this actually means to game play is unknown.  The odds of creating a rare seem to be much higher than improving an item and making it rare. January 2014, Rolf : There is already a chance that using rare materials transfer to the thing you create or improve. Consuming a rare material when improving has a 1/100 possibility to transfer rarity. When improving or polishing a drum roll doesn\'t always mean rarity. The window is 20 seconds plus up to 10 of village faith creation bonus .', '<ul><li>When rare items were introduced players were told \"You get approximately 1 chance of 50% each hour to create a rare item.\"  What this actually means to game play is unknown.  The odds of creating a rare seem to be much higher than improving an item and making it rare.</li>\n<li><a class=\"external text\" href=\"https://forum.wurmonline.com/index.php?/topic/94002-rare-raw-resource-to-rare-refined-item/&amp;do=findComment&amp;comment=945189%7C14th\" rel=\"nofollow\">January 2014, Rolf</a>: There is already a chance that using rare materials transfer to the thing you create or improve. Consuming a rare material when improving has a 1/100 possibility to transfer rarity. When improving or polishing a drum roll doesn\'t always mean rarity. The window is 20 seconds plus up to 10 of <a href=\"/index.php/Faith_bonus#Deed_Faith_Bonus\" title=\"Faith bonus\">village faith creation bonus</a>.</li></ul>', 7),
(14295, 3743, 'Description', 'Description', 'Tich and Keyos constructing the cathedral, painted by RoseDragon.', '<p><i>Tich and Keyos constructing the cathedral, painted by RoseDragon.</i>\n</p>', 0),
(14296, 3743, 'See also', 'See_also', 'Battle of Kyara tapestry Beige tapestry Cavalry motif tapestry Festivities motif tapestry Green tapestry Orange tapestry Tapestry of Ehizellbob Tapestry of Evening Tapestry of Faeldray Tapestry of Mclavin', '<ul><li><a href=\"/index.php/Battle_of_Kyara_tapestry\" title=\"Battle of Kyara tapestry\">Battle of Kyara tapestry</a></li>\n<li><a href=\"/index.php/Beige_tapestry\" title=\"Beige tapestry\">Beige tapestry</a></li>\n<li><a href=\"/index.php/Cavalry_motif_tapestry\" title=\"Cavalry motif tapestry\">Cavalry motif tapestry</a></li>\n<li><a href=\"/index.php/Festivities_motif_tapestry\" title=\"Festivities motif tapestry\">Festivities motif tapestry</a></li>\n<li><a href=\"/index.php/Green_tapestry\" title=\"Green tapestry\">Green tapestry</a></li>\n<li><a href=\"/index.php/Orange_tapestry\" title=\"Orange tapestry\">Orange tapestry</a></li>\n<li><a href=\"/index.php/Tapestry_of_Ehizellbob\" title=\"Tapestry of Ehizellbob\">Tapestry of Ehizellbob</a></li>\n<li><a href=\"/index.php/Tapestry_of_Evening\" title=\"Tapestry of Evening\">Tapestry of Evening</a></li>\n<li><a href=\"/index.php/Tapestry_of_Faeldray\" title=\"Tapestry of Faeldray\">Tapestry of Faeldray</a></li>\n<li><a href=\"/index.php/Tapestry_of_Mclavin\" title=\"Tapestry of Mclavin\">Tapestry of Mclavin</a></li></ul>', 1),
(14297, 3744, 'Description', 'Description', 'A necklace with a marbled pattern on it.', '<p><i>A necklace with a marbled pattern on it.</i>\n</p>', 0),
(14298, 3744, 'Notes', 'Notes', 'Obtained from certain treasure chests, found by following exploration clues from a treasure map. The marbled necklace takes on the same model as the medallion necklace, when it is not worn.', '<ul><li>Obtained from certain treasure chests, found by following exploration clues from a treasure map.</li>\n<li>The marbled necklace takes on the same model as the medallion necklace, when it is not worn.</li></ul>', 1),
(14299, 3746, 'Description', 'Description', 'A necklace with an anchor hung from it.', '<p><i>A necklace with an anchor hung from it.</i>\n</p>', 0),
(14300, 3746, 'Notes', 'Notes', 'Obtained from certain treasure chests, found by following exploration clues from a treasure map.', '<ul><li>Obtained from certain treasure chests, found by following exploration clues from a treasure map.</li></ul>', 1),
(14323, 3307, 'Description', 'Description', 'Stone strike is cast on a pick to improve the success chance of a surface mining action.', '<p><b>Stone strike</b> is cast on a pick to improve the success chance of a surface mining action. \n</p>', 0),
(14324, 3307, 'Notes', 'Notes', 'Stone strike increases your likelihood of a successful surface mining action (lowering the tile) rock by power of the cast / 10. So 10% at 100, 5% at 50, etc. with a cap of 60% at 100 mining, 100 stone strike cast. Without stone strike, 100 mining would give you a 50% chance.', '<ul><li>Stone strike increases your likelihood of a successful surface mining action (lowering the tile) rock by power of the cast / 10. So 10% at 100, 5% at 50, etc. with a cap of 60% at 100 mining, 100 stone strike cast.</li>\n<li>Without stone strike, 100 mining would give you a 50% chance.</li></ul>', 1),
(14325, 3752, 'Description', 'Description', 'A small glass bottle.', '<p><i>A small glass bottle.</i>\n</p>', 0),
(14326, 3752, 'Notes', 'Notes', 'Obtained randomly from certain treasure chests, found by treasure hunting . The liquids contained within Glass Jugs are able to provide unique affinities from their crafted counterparts. Can be sealed with a Wax sealing kit , which will prevent decay. Holds up to 2.00 kg of liquid. The Glass jug can also hold non liquid items.', '<ul><li>Obtained randomly from certain treasure chests, found by <a href=\"/index.php/Treasure_hunt\" title=\"Treasure hunt\">treasure hunting</a>.</li>\n<li>The liquids contained within Glass Jugs are able to provide unique affinities from their crafted counterparts.</li>\n<li>Can be sealed with a <a href=\"/index.php/Wax_sealing_kit\" title=\"Wax sealing kit\">Wax sealing kit</a>, which will prevent decay.</li>\n<li>Holds up to 2.00 kg of liquid.</li>\n<li>The Glass jug can also hold non liquid items.</li></ul>', 1),
(14327, 1614, 'Description', 'Description', 'This is a large mounted crossbow firing enormous darts.', '<p><i>This is a large mounted crossbow firing enormous darts.</i>\n</p>', 0),
(14328, 1614, 'Usage', 'Usage', 'This war machine fires ballista darts and is used like catapults . To load a ballista , activate a ballista dart, right-click the ballista, and select Machine > Load . You will then have the right-click options to Machine > Unload to remove the dart, Winch , Winch five laps , and Winch ten laps , shoot 1, 5, or 10 tiles further. This will start an action timer and each lap will take 1 second to winch. While winching, the winch at the back of the ballista is animated. Having winched it, you can unload the dart, or unwind the ballista which results in an event log message. To fire the ballista, have it loaded and winched, and place it so it faces in the direction you wish to fire in by picking it up and dropping it. When dropped, it will always face away from you. Right-click the ballista, select Machine > Fire , and watch your event log for messages. Firing the ballista will animate the model. A higher quality machine mount increases your success chance for creating. It can picked up by hand, and loaded into large carts and wagons . Requires 60 fine carpentry skill to create.', '<ul><li>This <a href=\"/index.php/War_machines\" title=\"War machines\">war machine</a> fires <a href=\"/index.php/Ballista_dart\" title=\"Ballista dart\">ballista darts</a> and is used like <a class=\"mw-redirect\" href=\"/index.php/Catapult\" title=\"Catapult\">catapults</a>.</li>\n<li>To load a <a class=\"mw-selflink selflink\">ballista</a>, <a href=\"/index.php/Activate\" title=\"Activate\">activate</a> a ballista dart, <b>right-click</b> the ballista, and select <b>Machine &gt; Load</b>.\n<ul><li>You will then have the right-click options to <b>Machine &gt; Unload</b> to remove the dart, <b>Winch</b>, <b>Winch five laps</b>, and <b>Winch ten laps</b>, shoot 1, 5, or 10 tiles further. This will start an action timer and each lap will take 1 second to winch. While winching, the winch at the back of the ballista is animated.</li>\n<li>Having winched it, you can unload the dart, or unwind the ballista which results in an event log message.</li>\n<li>To fire the ballista, have it loaded and winched, and place it so it faces in the direction you wish to fire in by picking it up and dropping it. When dropped, it will always face away from you. <b>Right-click</b> the ballista, select <b>Machine &gt; Fire</b>, and watch your event log for messages. Firing the ballista will animate the model.</li></ul></li>\n<li>A higher <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a> machine mount increases your success chance for creating.</li>\n<li>It can picked up by hand, and <a href=\"/index.php/Load_cargo\" title=\"Load cargo\">loaded</a> into <a href=\"/index.php/Large_cart\" title=\"Large cart\">large carts</a> and <a href=\"/index.php/Wagon\" title=\"Wagon\">wagons</a>.</li>\n<li>Requires 60 fine carpentry skill to create.</li></ul>', 1),
(14329, 1614, 'Skills & Characteristics', 'Skills_.26_Characteristics', 'When using a ballista War machines Mind > Mind logic When creating a ballista Carpentry > Fine carpentry', '<p>When using a ballista\n</p>\n<ul><li><a href=\"/index.php/War_machines\" title=\"War machines\">War machines</a></li>\n<li><a href=\"/index.php/Mind\" title=\"Mind\">Mind</a> &gt; <a href=\"/index.php/Mind_logic\" title=\"Mind logic\">Mind logic</a></li></ul>\n<p>When creating a ballista\n</p>\n<ul><li><a href=\"/index.php/Carpentry\" title=\"Carpentry\">Carpentry</a> &gt; <a href=\"/index.php/Fine_carpentry\" title=\"Fine carpentry\">Fine carpentry</a></li></ul>', 2),
(14330, 1614, 'Titles', 'Titles', 'Destroyer at 50 skill Demolisher at 70 skill Siege Master at 90 skill', '<ul><li>Destroyer at 50 skill</li>\n<li>Demolisher at 70 skill</li>\n<li>Siege Master at 90 skill</li></ul>', 3),
(14339, 3755, 'Description', 'Description', 'The mask swiftly fuses with your face. Will it ever come off again?', '<p><i>The mask swiftly fuses with your face. Will it ever come off again?</i>\n</p>', 0),
(14340, 3755, 'Notes', 'Notes', 'The maker signature will be that of the creature that dropped it. Obtainable as one of a number of possible drop rewards given by the killing of hunter creatures during the 2022 and 2023 Halloween Events. Can be colored by Adamantine Jackal rune .', '<ul><li>The maker signature will be that of the creature that dropped it.</li>\n<li>Obtainable as one of a number of possible drop rewards given by the killing of hunter creatures during the 2022 and 2023 Halloween Events.</li>\n<li>Can be colored by Adamantine Jackal <a href=\"/index.php/Runes#Properties\" title=\"Runes\">rune</a>.</li></ul>', 1),
(14341, 3756, 'Description', 'Description', 'Hah, outplayed by trickster Jackal! Now you must follow his every command!', '<p><i>Hah, outplayed by trickster Jackal! Now you must follow his every command!</i>\n</p>', 0),
(14342, 3756, 'Notes', 'Notes', 'The maker signature will be that of the creature that dropped it. It was one of a number of possible drop rewards given off by the killing of hunter creatures during the 2022 Halloween Event. Obtainable as part of the 2022 Halloween Event.', '<ul><li>The maker signature will be that of the creature that dropped it.</li>\n<li>It was one of a number of possible drop rewards given off by the killing of hunter creatures during the 2022 Halloween Event.</li>\n<li>Obtainable as part of the 2022 Halloween Event.</li></ul>', 1),
(14369, 3760, 'Description', 'Description', 'A wooden table with placements for various cartography tools used in the process of creating maps.', '<p><i>A wooden table with placements for various cartography tools used in the process of creating maps.</i>\n</p>', 0),
(14370, 3760, 'Usage', 'Usage', 'A cartography table can hold a maximum of 25 blank maps.', '<p>A cartography table can hold a maximum of 25 blank maps. \n</p>', 1);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
