INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(14576, 3791, 'Notes', 'Notes', 'The base can be dyed using 1000g of dye. The trim can be dyed using 300g of dye.(This currently is broken, and appears to dye the base instead** being fixed) Existing color can be removed using lye to remove the dye. Can be mailed', '<ul><li>The base can be dyed using 1000g of dye.</li>\n<li>The trim can be dyed using 300g of dye.(This currently is broken, and appears to dye the base instead** being fixed)</li>\n<li>Existing color can be removed using <a href=\"/index.php/Lye\" title=\"Lye\">lye</a> to remove the dye.</li>\n<li>Can be <a href=\"/index.php/Mail\" title=\"Mail\">mailed</a></li></ul>', 2),
(14577, 3791, 'See Also', 'See_Also', 'Small intricate carpet Small delicate carpet', '<ul><li><a href=\"/index.php/Small_intricate_carpet\" title=\"Small intricate carpet\">Small intricate carpet</a></li>\n<li><a href=\"/index.php/Small_delicate_carpet\" title=\"Small delicate carpet\">Small delicate carpet</a></li></ul>', 3),
(14578, 3792, 'Description', 'Description', 'This carpet adds a nice patch of color to any house or castle.', '<p><i>This carpet adds a nice patch of color to any house or castle.</i>\n</p>', 0),
(14579, 3792, 'Usage', 'Usage', 'Used as decoration.', '<ul><li>Used as decoration.</li></ul>', 1),
(14580, 3792, 'Notes', 'Notes', 'The base can be dyed with 500g of dye. The trim can be dyed with 150g of dye. Existing color can be removed using lye to remove the dye. Can be mailed', '<ul><li>The base can be dyed with 500g of dye.</li>\n<li>The trim can be dyed with 150g of dye.</li>\n<li>Existing color can be removed using <a href=\"/index.php/Lye\" title=\"Lye\">lye</a> to remove the dye.</li>\n<li>Can be <a href=\"/index.php/Mail\" title=\"Mail\">mailed</a></li></ul>', 2),
(14581, 3792, 'See Also', 'See_Also', 'Small intricate carpet Large flower carpet', '<ul><li><a href=\"/index.php/Small_intricate_carpet\" title=\"Small intricate carpet\">Small intricate carpet</a></li>\n<li><a href=\"/index.php/Large_flower_carpet\" title=\"Large flower carpet\">Large flower carpet</a></li></ul>', 3),
(14582, 3793, 'Description', 'Description', 'This carpet adds a nice patch of color to any house or castle.', '<p><i>This carpet adds a nice patch of color to any house or castle.</i>\n</p>', 0),
(14583, 3793, 'Usage', 'Usage', 'Used as decoration.', '<ul><li>Used as decoration.</li></ul>', 1),
(14584, 3793, 'Notes', 'Notes', 'The base can be dyed using 500g of dye. The trim can be dyed using 150g of dye. Existing color can be removed using lye to remove the dye. Can be mailed', '<ul><li>The base can be dyed using 500g of dye.</li>\n<li>The trim can be dyed using 150g of dye.</li>\n<li>Existing color can be removed using <a href=\"/index.php/Lye\" title=\"Lye\">lye</a> to remove the dye.</li>\n<li>Can be <a href=\"/index.php/Mail\" title=\"Mail\">mailed</a></li></ul>', 2),
(14585, 3793, 'See Also', 'See_Also', 'Small delicate carpet Large flower carpet', '<ul><li><a href=\"/index.php/Small_delicate_carpet\" title=\"Small delicate carpet\">Small delicate carpet</a></li>\n<li><a href=\"/index.php/Large_flower_carpet\" title=\"Large flower carpet\">Large flower carpet</a></li></ul>', 3),
(14586, 3794, 'Description', 'Description', 'A sullen skeleton hangs around, wondering where it all went wrong.', '<p><i>A sullen skeleton hangs around, wondering where it all went wrong. </i>\n</p>', 0),
(14587, 3794, 'Notes', 'Notes', 'A decorative item obtained through Archaeology only during the annual Halloween event. Can be created by combining 5 statue of sigvard the skeleton fragments. Sigvard periodically cracks his head, and makes skeleton jokes/puns in local. You also have the option to Kick him, which gives this message in Event: \"Well that was not very nice! Sigvard seems to be mad and ignoring you now.\" You can then Apologise, which gives this message in Event: \"Sigvard accepts your apology.\"', '<ul><li>A decorative item obtained through <a href=\"/index.php/Archaeology\" title=\"Archaeology\">Archaeology</a> only during the annual Halloween event.</li>\n<li>Can be created by combining 5 statue of sigvard the skeleton fragments.</li>\n<li>Sigvard periodically cracks his head, and makes skeleton jokes/puns in local. You also have the option to Kick him, which gives this message in Event: \"Well that was not very nice! Sigvard seems to be mad and ignoring you now.\" You can then Apologise, which gives this message in Event: \"Sigvard accepts your apology.\"</li></ul>', 1),
(14588, 3795, 'Description', 'Description', 'Wierdly decorative, were it not for the nightly screaming.', '<p><i>Wierdly decorative, were it not for the nightly screaming.</i>\n</p>', 0),
(14589, 3795, 'Notes', 'Notes', 'A decorative item obtained through Archaeology only during the annual Halloween event. Can be created by combining 3 flaming skull fragments. The skull must be filled with at least 1 candle before it can be lit.', '<ul><li>A decorative item obtained through <a href=\"/index.php/Archaeology\" title=\"Archaeology\">Archaeology</a> only during the annual Halloween event.</li>\n<li>Can be created by combining 3 flaming skull fragments.</li>\n<li>The skull must be filled with at least 1 <a href=\"/index.php/Candle\" title=\"Candle\">candle</a> before it can be lit.</li></ul>', 1),
(14590, 3796, 'Description', 'Description', 'From the shadows a small creature watches with hungry, terrifyingly intelligent eyes.', '<p><i>From the shadows a small creature watches with hungry, terrifyingly intelligent eyes. </i>\n</p>', 0),
(14591, 3796, 'Notes', 'Notes', 'A statue obtained through Archaeology only during the annual Halloween event. Can be created by combining 10 statue of pet bat fragments. The pet bat statue will periodically open and close its wings. You can Poke the bat, prompting the following Event tab messages: \"I really shouldn\'t. . . but why not!\" \"Ouch, it bit me!\"', '<ul><li>A statue obtained through <a href=\"/index.php/Archaeology\" title=\"Archaeology\">Archaeology</a> only during the annual Halloween event.</li>\n<li>Can be created by combining 10 statue of pet bat fragments.</li>\n<li>The pet bat statue will periodically open and close its wings.</li>\n<li>You can Poke the bat, prompting the following Event tab messages: \"I really shouldn\'t. . . but why not!\" \"Ouch, it bit me!\"</li></ul>', 1),
(14592, 3797, 'Description', 'Description', 'Have you been naughty? Have you been nice? Wurmian Santa knows. A hangable cotton stocking that comes at 99 quality .', '<p><i>Have you been naughty? Have you been nice? Wurmian Santa knows.</i>\n</p>\n<p>A hangable cotton stocking that comes at 99 <a class=\"mw-redirect\" href=\"/index.php/Quality\" title=\"Quality\">quality</a>.\n</p>', 0),
(14593, 3797, 'Usage', 'Usage', 'It was used as a Christmas decoration as well as a way to check for daily gifts.', '<p>It was used as a Christmas decoration as well as a way to check for daily gifts. \n</p>', 1),
(14594, 3797, 'History', 'History', 'Stockings were given to premium players as a Christmas gift in 2022.', '<p>Stockings were given to <a class=\"mw-redirect\" href=\"/index.php/Premium\" title=\"Premium\">premium</a> players as a Christmas gift in 2022.\n</p>', 2),
(14609, 3800, 'Description', 'Description', 'A hard, shiny type of iron that fell from beyond the sky.', '<p><i>A hard, shiny type of iron that fell from beyond the sky.</i>\n</p>', 0),
(14610, 3800, 'Creation', 'Creation', 'Empyrean lumps are obtained by rummaging at the Otherworldly Monolith at a Holy site of Magranon and can also be found in meteorites from the Ritual of the Sun .', '<p>Empyrean lumps are obtained by rummaging at the Otherworldly Monolith at a <a class=\"mw-redirect\" href=\"/index.php/Holy_site\" title=\"Holy site\">Holy site</a> of <a href=\"/index.php/Magranon\" title=\"Magranon\">Magranon</a> and can also be found in <a href=\"/index.php/Meteorite\" title=\"Meteorite\">meteorites</a> from the <a class=\"mw-redirect\" href=\"/index.php/Ritual_of_the_Sun\" title=\"Ritual of the Sun\">Ritual of the Sun</a>. \n</p>', 1),
(14611, 3800, 'Notes', 'Notes', 'Like other rare metals, this metal has some very special properties .', '<ul><li>Like other rare metals, this metal has some very <a href=\"/index.php/Metal_lumps#Table_of_properties\" title=\"Metal lumps\">special properties</a>.</li></ul>', 2),
(14612, 3800, 'Usage', 'Usage', 'See metal products list for items that can be made from empyrean.', '<ul><li>See <a href=\"/index.php/Category:Any-metal_products\" title=\"Category:Any-metal products\">metal products list</a> for items that can be made from empyrean.</li></ul>', 3),
(14613, 3801, 'Description', 'Description', 'These opalescent berries have sweet, black flesh and tiny, white, glowing seeds.', '<p><i>These opalescent berries have sweet, black flesh and tiny, white, glowing seeds.</i>\n</p>', 0),
(14614, 3801, 'Notes', 'Notes', 'Starberries can be picked from a Wishing Tree at a Fo Holy site . (more information coming soon) Starberries can be foraged from Briar patch Resource nodes . Starberries can be used in cooking recipes and in making juice. (Testing needed to verify)', '<ul><li>Starberries can be picked from a Wishing Tree at a Fo <a class=\"mw-redirect\" href=\"/index.php/Holy_site\" title=\"Holy site\">Holy site</a>. (more information coming soon)</li>\n<li>Starberries can be foraged from <a href=\"/index.php/Briar_patch\" title=\"Briar patch\">Briar patch</a> <a href=\"/index.php/Resource_nodes\" title=\"Resource nodes\">Resource nodes</a>.</li>\n<li>Starberries can be used in <a href=\"/index.php/Hot_food_cooking\" title=\"Hot food cooking\">cooking</a> recipes and in making juice. (Testing needed to verify)</li></ul>', 1),
(14615, 3802, 'Description', 'Description', 'A rich, thick coffee to be enjoyed socially along with a glass of water.', '<p><i> A rich, thick coffee to be enjoyed socially along with a glass of water.</i>\n</p>', 0),
(14616, 3802, 'Creation', 'Creation', 'Coffee is a beverage that can be brewed using coffee beans .', '<p><b>Coffee</b> is a <a class=\"mw-redirect\" href=\"/index.php/Beverage\" title=\"Beverage\">beverage</a> that can be brewed using <a class=\"mw-redirect\" href=\"/index.php/Coffee_beans\" title=\"Coffee beans\">coffee beans</a>.\n</p>', 1),
(14617, 3802, 'Usage', 'Usage', 'Coffee is a drink that contains caffeine . Caffeine can be used to increase the consumption rate of sleep bonus up to 2x the normal rate at 100 caffeine power. Drinking a caffeinated beverage within 10 minutes of logging in yields ten free minutes of sleep bonus .', '<ul><li>Coffee is a drink that contains <a href=\"/index.php/Caffeine\" title=\"Caffeine\">caffeine</a>.</li>\n<li><a href=\"/index.php/Caffeine\" title=\"Caffeine\">Caffeine</a> can be used to increase the consumption rate of <a href=\"/index.php/Sleep_bonus\" title=\"Sleep bonus\">sleep bonus</a> up to 2x the normal rate at 100 <a href=\"/index.php/Caffeine\" title=\"Caffeine\">caffeine</a> power.</li>\n<li>Drinking a caffeinated beverage within 10 minutes of logging in yields ten free minutes of <a href=\"/index.php/Sleep_bonus\" title=\"Sleep bonus\">sleep bonus</a>.</li></ul>', 2),
(14618, 3802, 'Notes', 'Notes', 'The QL of the coffee beans and the beverages skill affect the resulting QL of the coffee.', '<p>The <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> of the <a class=\"mw-redirect\" href=\"/index.php/Coffee_beans\" title=\"Coffee beans\">coffee beans</a> and the <a href=\"/index.php/Beverages\" title=\"Beverages\">beverages</a> skill affect the resulting <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> of the coffee.\n</p>', 3),
(14619, 3802, 'Tools required', 'Tools_required', 'campfire , oven , coffee pot', '<ul><li><a href=\"/index.php/Campfire\" title=\"Campfire\">campfire</a>, <a href=\"/index.php/Oven\" title=\"Oven\">oven</a>, <a href=\"/index.php/Coffee_pot\" title=\"Coffee pot\">coffee pot</a></li></ul>', 4),
(14620, 3802, 'Notes', 'Notes_2', 'Beverages below 10ql are not drinkable at all.', '<ul><li><a href=\"/index.php/Beverages\" title=\"Beverages\">Beverages</a> below 10ql are not drinkable at all.</li></ul>', 5),
(14621, 3799, 'Description', 'Description', 'Holy sites are randomly spawned zones for players to find. They are themed after specific Gods and biomes, in unsettled areas of the map. Priests and followers of that deity can maintain the site through prayers and sermons . The Holy site will provide bonuses to all who have a Premium account. The site will also have some additional positive effects within it radius. Some of these benefits will be available to all premium accounts even if they do not follow that particular deity . Holy sites are temporary and will last approximately 2 weeks.', '<p><b>Holy sites</b> are randomly spawned zones for players to find. They are themed after specific Gods and biomes, in unsettled areas of the map. Priests and followers of that <a class=\"mw-redirect\" href=\"/index.php/Deity\" title=\"Deity\">deity</a> can maintain the site through <a href=\"/index.php/Prayer\" title=\"Prayer\">prayers</a> and <a href=\"/index.php/Sermon\" title=\"Sermon\">sermons</a>. The Holy site will provide bonuses to all who have a <a class=\"mw-redirect\" href=\"/index.php/Premium\" title=\"Premium\">Premium</a> account. The site will also have some additional positive effects within it radius. Some of these benefits will be available to all <a class=\"mw-redirect\" href=\"/index.php/Premium\" title=\"Premium\">premium</a> accounts even if they do not follow that particular <a class=\"mw-redirect\" href=\"/index.php/Deity\" title=\"Deity\">deity</a>.  \n</p>\n<ul><li>Holy sites are temporary and will last approximately 2 weeks.</li></ul>', 0),
(14622, 3799, 'Discovery', 'Discovery', 'Each type of Holy site can only spawn in places matching certain features, limiting the areas you might need to search in order to find them. You can receive a map, which will help guide you to a Holy site through prayer , sermons or meditation . Note that only actions that would give a chance to gain faith or meditation skill has a chance to give a map. These maps have various modifiers applied to make them less clear than a normal Treasure map or Cartography map, so you may need to compare maps with others or combine them with your understanding of the server layout in order to locate the Holy site. Ex: divine vision orb These maps hints will be given for Holy sites that have not yet been located and activated. They will also be associated with the God you follow. On PVP servers, you may also get hint about opposite-light gods\' (i.e. maps of a White light Holy site if your God is Libila and vice-versa). Holy sites that have been located and activated can be seen by right clicking an altar and choosing \"locate Holy sites\". this will show the locations of all activated Holy sites on the in-game map.', '<p>Each type of Holy site can only spawn in places matching certain features, limiting the areas you might need to search in order to find them.\n</p>\n<ul><li>You can receive a map, which will help guide you to a Holy site through <a href=\"/index.php/Prayer\" title=\"Prayer\">prayer</a>, <a href=\"/index.php/Sermon\" title=\"Sermon\">sermons</a> or <a class=\"mw-redirect\" href=\"/index.php/Meditation\" title=\"Meditation\">meditation</a>. Note that only actions that would give a chance to gain <a href=\"/index.php/Faith\" title=\"Faith\">faith</a> or <a class=\"mw-redirect\" href=\"/index.php/Meditation\" title=\"Meditation\">meditation</a> skill has a chance to give a map. These maps have various modifiers applied to make them less clear than a normal <a class=\"mw-redirect\" href=\"/index.php/Treasure_map\" title=\"Treasure map\">Treasure map</a> or <a href=\"/index.php/Cartography\" title=\"Cartography\">Cartography</a> map, so you may need to compare maps with others or combine them with your understanding of the server layout in order to locate the Holy site. Ex: <a href=\"/index.php/Divine_vision_orb\" title=\"Divine vision orb\">divine vision orb</a></li></ul>\n<ul><li>These maps hints will be given for Holy sites that have not yet been located and activated. They will also be associated with the God you follow.</li></ul>\n<ul><li>On PVP servers, you may also get hint about opposite-light gods\' (i.e. maps of a White light Holy site if your God is Libila and vice-versa).</li></ul>\n<ul><li>Holy sites that have been located and activated can be seen by right clicking an altar and choosing \"locate Holy sites\". this will show the locations of all activated Holy sites on the in-game map.</li></ul>', 1),
(14623, 3799, 'Activation', 'Activation', 'A Holy site is dormant and provides no benefits until it is found and activated by a priest of the site\'s deity . To activate the Holy site, pray or hold a sermon (with enough listeners for faith gain at the special item in the center of the Holy site. Once activated, the expiration timer of the Holy site will reset, in order to guarantee that a site will last for its full duration after being found.', '<p>A Holy site is dormant and provides no benefits until it is found and activated by a priest of the site\'s <a class=\"mw-redirect\" href=\"/index.php/Deity\" title=\"Deity\">deity</a>.\n</p>\n<ul><li>To activate the Holy site, pray or hold a sermon (with enough listeners for <a href=\"/index.php/Faith\" title=\"Faith\">faith</a> gain at the special item in the center of the Holy site.</li>\n<li>Once activated, the expiration timer of the Holy site will reset, in order to guarantee that a site will last for its full duration after being found.</li></ul>', 2),
(14624, 3799, 'Power and Corruption', 'Power_and_Corruption', 'Power and Corruption are the two most important characteristics of a Holy site. Each ranges from 0 to 100. Power is the strength of the deity \'s influence. This is represented by the QL level of the special item at the center of the Holy site, and can be seen by examining it. Power affects The size of the Holy site. The power or effectiveness of almost all Holy site benefits, such as the QL level of goods received from it. There is a possibility of the Holy site expiring early, if the power ever reaches 0. Power is increased by: Prayers and sermons within the Holy site by followers and priests of the site God. The prayers and sermons may be done at the Holy site\'s special item, but any altar will work, as long as it is within the current borders of the Holy site. Power is decreased by: Natural decay over time once the Holy site is activated. Chance for decay occurs at the same time as Pulse events. Amount of power decay is randomized and may not occur at all. Corruption The malicious taint and impurity, which makes the Holy site less effective and possibly resulting in negative effects. This is represented by the damage of the special item at the center of the Holy site, and can be seen by examining it. Corruption affects: Damage on items received from the Holy site. Chance of backlash effects when performing prayers or sermons to increase the Holy site\'s power. Disabling of pulse effects, item improvement bonuses, and some passive bonuses if the corruption is at least 40. The effective power of the Holy site when providing benefits. For example, a Holy site with 80 QL that has 50 damage will only have the effective QL of 40 power for most purposes. The corruption will not affect the size of the Holy site. Corruption is increased by: There is a random chance when performing prayers , sermons , or special Holy site actions within the site. This is far more likely if the current corruption is already above 0. Power-affecting actions (prayers/sermons) have a higher chance to corrupt the site than special actions do. Any corruption from performing an action may be partially or fully resisted by a soul strength skill check. Chance of corruption over time is triggered on pulse events and scales with the number of players who have contributed to the site\'s power since the last pulse. Natural chance of corruption over time once the Holy site is activated. Just like power decay, this chance occurs at the same time as pulse events. (PVP only) Desecration actions performed by followers or priests of an opposing deity , using the exorcism skill. Corruption is decreased by: Purify actions performed on the Holy site item by followers or priests of the Holy site\'s deity , using the exorcism skill. Scaling effects on decay Chance of corruption gain and power decay over time is increased with the number of players who have somehow contributed to the Holy site\'s power since the last pulse event. Rarity Has a significant impact on favor granted to the deity upon expiration. This is represented by the rarity of the special item at the center of the Holy site, and can be seen by examining it. Rarity of the Holy site is determined randomly when it spawns, and does not change.', '<p>Power and Corruption are the two most important characteristics of a Holy site. Each ranges from 0 to 100.\n</p>\n<p><b>Power</b> is the strength of the <a class=\"mw-redirect\" href=\"/index.php/Deity\" title=\"Deity\">deity</a>\'s influence. \n</p>\n<p>This is represented by the <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> level of the special item at the center of the Holy site, and can be seen by examining it.\n</p>\n<p><b>Power affects</b>\n</p>\n<ul><li>The size of the Holy site.</li>\n<li>The power or effectiveness of almost all Holy site benefits, such as the <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> level of goods received from it.</li>\n<li>There is a possibility of the Holy site expiring early, if the power ever reaches 0.</li></ul>\n<p><b>Power is increased by:</b>\n</p>\n<ul><li><a href=\"/index.php/Prayer\" title=\"Prayer\">Prayers</a> and <a href=\"/index.php/Sermon\" title=\"Sermon\">sermons</a> within the Holy site by <a href=\"/index.php/Follower\" title=\"Follower\">followers</a> and <a href=\"/index.php/Priest\" title=\"Priest\">priests</a> of the site God.</li>\n<li>The <a href=\"/index.php/Prayer\" title=\"Prayer\">prayers</a> and <a href=\"/index.php/Sermon\" title=\"Sermon\">sermons</a> may be done at the Holy site\'s special item, but any altar will work, as long as it is within the current borders of the Holy site.</li></ul>\n<p><b>Power is decreased by:</b>\n</p>\n<ul><li>Natural decay over time once the Holy site is activated.</li>\n<li>Chance for decay occurs at the same time as Pulse events.</li>\n<li>Amount of power decay is randomized and may not occur at all.</li></ul>\n<p><b>Corruption</b>\n</p>\n<ul><li>The malicious taint and impurity, which makes the Holy site less effective and possibly resulting in negative effects.</li></ul>\n<ul><li>This is represented by the damage of the special item at the center of the Holy site, and can be seen by examining it.</li></ul>\n<p><b>Corruption affects:</b>\n</p>\n<ul><li>Damage on items received from the Holy site.</li>\n<li>Chance of backlash effects when performing <a href=\"/index.php/Prayer\" title=\"Prayer\">prayers</a> or <a href=\"/index.php/Sermon\" title=\"Sermon\">sermons</a> to increase the Holy site\'s power.</li>\n<li>Disabling of pulse effects, item improvement bonuses, and some passive bonuses if the corruption is at least 40.</li>\n<li>The effective power of the Holy site when providing benefits. For example, a Holy site with 80 <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> that has 50 damage will only have the effective <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> of 40 power for most purposes.</li>\n<li>The corruption will not affect the size of the Holy site.</li></ul>\n<p><b>Corruption is increased by:</b>\n</p>\n<p>There is a random chance when performing <a href=\"/index.php/Prayer\" title=\"Prayer\">prayers</a> , <a href=\"/index.php/Sermon\" title=\"Sermon\">sermons</a>, or special Holy site actions within the site.\n</p>\n<ul><li>This is far more likely if the current corruption is already above 0.</li>\n<li>Power-affecting actions (prayers/sermons) have a higher chance to corrupt the site than special actions do.</li>\n<li>Any corruption from performing an action may be partially or fully resisted by a soul strength skill check.</li>\n<li>Chance of corruption over time is triggered on pulse events and scales with the number of players who have contributed to the site\'s power since the last pulse.</li></ul>\n<p>Natural chance of corruption over time once the Holy site is activated. \n</p>\n<ul><li>Just like power decay, this chance occurs at the same time as pulse events.</li></ul>\n<p>(PVP only) Desecration actions performed by <a href=\"/index.php/Follower\" title=\"Follower\">followers</a> or <a href=\"/index.php/Priest\" title=\"Priest\">priests</a> of an opposing <a class=\"mw-redirect\" href=\"/index.php/Deity\" title=\"Deity\">deity</a>, using the <a href=\"/index.php/Exorcism\" title=\"Exorcism\">exorcism</a> skill. \n</p>\n<p><b>Corruption is decreased by:</b>\n</p>\n<p>Purify actions performed on the Holy site item by <a href=\"/index.php/Follower\" title=\"Follower\">followers</a> or <a href=\"/index.php/Priest\" title=\"Priest\">priests</a> of the Holy site\'s <a class=\"mw-redirect\" href=\"/index.php/Deity\" title=\"Deity\">deity</a>, using the <a href=\"/index.php/Exorcism\" title=\"Exorcism\">exorcism</a> skill. \n</p>\n<p><b>Scaling effects on decay</b>\n</p>\n<p>Chance of corruption gain and power decay over time is increased with the number of players who have somehow contributed to the Holy site\'s power since the last pulse event. \n</p>\n<p><b>Rarity</b>\nHas a significant impact on <a href=\"/index.php/Favor\" title=\"Favor\">favor</a> granted to the <a class=\"mw-redirect\" href=\"/index.php/Deity\" title=\"Deity\">deity</a> upon expiration. \n</p>\n<ul><li>This is represented by the rarity of the special item at the center of the Holy site, and can be seen by examining it.</li>\n<li>Rarity of the Holy site is determined randomly when it spawns, and does not change.</li></ul>', 3),
(14625, 3799, 'Holy Site Types', 'Holy_Site_Types', 'Fo Holy Sites Wishing Tree A magical tree, blossoming with many types of fruit and other produce. Spawns in dense forests. Sampo A strange divine mechanism, dispensing the necessities of life. Spawns on steppe. Vynora Holy Sites Wellspring of Knowledge A mystical fountain dispensing knowledge. Spawns on beaches and other natural waterfronts. Akashic Mirror A weird, black mirror that appears to be peering into another world. Spawns on roads and other paved areas. Magranon Holy Sites Glowing Fissure A glowing, volcanic crack in the rock. Spawns in barren, rocky terrain. Otherworldly monolith An obelisk that has fallen from the sky and buried itself into the ground. Spawns on sand. Libila Holy Sites Abyssal Circle An unholy ritual circle of uncertain purpose. Spawns on tundra. Pillar of Decay A crude totem of skulls, viscera, and decay. Spawns on tar and peat.', '<p><a href=\"/index.php/Fo_Holy_Site\" title=\"Fo Holy Site\">Fo Holy Sites</a>\n</p>\n<p><b>Wishing Tree</b>\n</p>\n<ul><li>A magical tree, blossoming with many types of fruit and other produce. Spawns in dense forests.</li></ul>\n<p><b>Sampo</b>\n</p>\n<ul><li>A strange divine mechanism, dispensing the necessities of life. Spawns on steppe.</li></ul>\n<p><a href=\"/index.php/Vynora_Holy_Site\" title=\"Vynora Holy Site\">Vynora Holy Sites</a>\n</p>\n<p><b>Wellspring of Knowledge</b>\n</p>\n<ul><li>A mystical fountain dispensing knowledge. Spawns on beaches and other natural waterfronts.</li></ul>\n<p><b>Akashic Mirror</b>\n</p>\n<ul><li>A weird, black mirror that appears to be peering into another world. Spawns on roads and other paved areas.</li></ul>\n<p><a href=\"/index.php/Magranon_Holy_Site\" title=\"Magranon Holy Site\">Magranon Holy Sites</a>\n</p>\n<p><b>Glowing Fissure</b>\n</p>\n<ul><li>A glowing, volcanic crack in the rock. Spawns in barren, rocky terrain.</li></ul>\n<p><b>Otherworldly monolith</b>\n</p>\n<ul><li>An obelisk that has fallen from the sky and buried itself into the ground. Spawns on sand.</li></ul>\n<p><a href=\"/index.php/Libila_Holy_Site\" title=\"Libila Holy Site\">Libila Holy Sites</a>\n</p>\n<p><b>Abyssal Circle</b>\n</p>\n<ul><li>An unholy ritual circle of uncertain purpose. Spawns on tundra.</li></ul>\n<p><b>Pillar of Decay</b>\n</p>\n<ul><li>A crude totem of skulls, viscera, and decay. Spawns on tar and peat.</li></ul>', 4),
(14626, 3799, 'Restrictions', 'Restrictions', 'Holy sites are special places protected by their Gods, and are meant to be accessed and used by the public. As such, the following activities are disallowed within Holy sites: Founding a settlement Expanding an existing settlement into the Holy site. Terraforming (digging, mining, etc.). Building structures or fences. Changing tile types by packing, cultivating, adding or removing pavement, dropping dirt/sand, transmuting, planting or cutting trees, or any similar actions. Creatures grazing or moving will also not pack tiles within Holy sites. (PVE server only) Blocking in intentionally restricting access to the Holy site in any way.', '<p>Holy sites are special places protected by their Gods, and are meant to be accessed and used by the public. As such, the following activities are disallowed within Holy sites:\n</p>\n<ul><li>Founding a settlement</li>\n<li>Expanding an existing settlement into the Holy site.</li>\n<li>Terraforming (digging, mining, etc.).</li>\n<li>Building structures or fences.</li>\n<li>Changing tile types by packing, cultivating, adding or removing pavement, dropping dirt/sand, transmuting, planting or cutting trees, or any similar actions.</li>\n<li>Creatures grazing or moving will also not pack tiles within Holy sites.</li>\n<li>(PVE server only) Blocking in intentionally restricting access to the Holy site in any way.</li></ul>', 5),
(14683, 3805, 'Description', 'Description', 'A divine mechanism supplying all that sustains life. It bears an aura of Fo. A Fo Holy site will spawn randomly and will have a Fo theme and biome. It will be in a unsettled area of the map. There are two different types of Fo Holy sites that can spawn Wishing Tree A magical tree, blossoming with many types of fruit and other produce. This type of site will spawn in dense forests. Sampo A strange divine mechanism, dispensing the necessities of life. This type of site will spawn on steppe.', '<p><i> A divine mechanism supplying all that sustains life. It bears an aura of Fo.</i>\n</p>\n<p>A Fo <a class=\"mw-redirect\" href=\"/index.php/Holy_site\" title=\"Holy site\">Holy site</a> will spawn randomly and will have a Fo theme and biome. It will be in a unsettled area of the map.\n</p>\n<p>There are two different types of Fo <a href=\"/index.php/Holy_sites\" title=\"Holy sites\">Holy sites</a> that can spawn\n</p>\n<p><b>Wishing Tree</b>\n</p>\n<ul><li>A magical tree, blossoming with many types of fruit and other produce.</li>\n<li>This type of site will spawn in dense forests.</li></ul>\n<p><b>Sampo</b>\n</p>\n<ul><li>A strange divine mechanism, dispensing the necessities of life.</li>\n<li>This type of site will spawn on steppe.</li></ul>', 0),
(14684, 3805, 'Positive effects', 'Positive_effects', 'Holy Sites have several positive effects. Except when otherwise stated, all these effects are available only to accounts with Premium time, and that have at least 30 Faith with the Holy Site’s deity.', '<p>Holy Sites have several positive effects. Except when otherwise stated, all these effects are available only to accounts with Premium time, and that have at least 30 Faith with the Holy Site’s deity.\n</p>', 1),
(14685, 3805, 'Passive effects', 'Passive_effects', 'These are active whenever you are within the Holy Site. Special visual effects and a spell effect icon will make it clear when you are within the Holy Site’s current borders. Doubled QL gain bonus for items favored by Fo, which means items receive +20% to QL increases from improvement, rather than 10%. Fo grants this effect to clay and cloth items. Hostile monsters will no longer be hostile towards you. This is the same effect the Fo priests are granted at 60 faith . These monsters include the hostile creatures that are considered animals. This does not include dragons , trolls , lava fiends , goblins or scorpions . Higher faith gain, and greater favor gain for Fo, for all prayers and sermons held at any altar within the site or at the Holy site itself.', '<p>These are active whenever you are within the Holy Site. Special visual effects and a spell effect icon will make it clear when you are within the Holy Site’s current borders.\n</p>\n<p>Doubled <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> gain bonus for items favored by Fo, which means items receive +20% to <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> increases from improvement, rather than 10%. \n</p>\n<ul><li>Fo grants this effect to <a href=\"/index.php/Clay\" title=\"Clay\">clay</a> and <a href=\"/index.php/Cloth\" title=\"Cloth\">cloth</a> items.</li></ul>\n<p>Hostile <a class=\"mw-redirect\" href=\"/index.php/Monster\" title=\"Monster\">monsters</a> will no longer be hostile towards you. \n</p>\n<ul><li>This is the same effect the Fo priests are granted at 60 <a href=\"/index.php/Faith\" title=\"Faith\">faith</a>. These <a class=\"mw-redirect\" href=\"/index.php/Monsters\" title=\"Monsters\">monsters</a> include the hostile creatures that are considered animals. This does not include <a href=\"/index.php/Dragon\" title=\"Dragon\">dragons</a>, <a href=\"/index.php/Troll\" title=\"Troll\">trolls</a>, <a href=\"/index.php/Lava_fiend\" title=\"Lava fiend\">lava fiends</a>, <a href=\"/index.php/Goblin\" title=\"Goblin\">goblins</a> or <a href=\"/index.php/Scorpion\" title=\"Scorpion\">scorpions</a>.</li>\n<li>Higher <a href=\"/index.php/Faith\" title=\"Faith\">faith</a> gain, and greater <a href=\"/index.php/Favor\" title=\"Favor\">favor</a> gain for Fo, for all prayers and sermons held at any altar within the site or at the Holy site itself.</li></ul>', 2),
(14686, 3805, 'Special actions', 'Special_actions', 'Wishing Tree You may harvest a random harvestable product from the tree using a sickle . The product may be any type of fruit , berry , nut , herb , spice . The tree will provide more items than harvesting a normal tree or bush, and at a higher QL . The tree can also give special item within those categories that are not available anywhere else, and that grant more complexity than normal food to any dishes they are used in. Sampo Feast for a refresh effect giving you a maximum food , water , stamina , and CCFP bars. Cures any disease Gives a random temporary affinity of long duration similar to a food affinity. Give a significant amounts of source salt . There is a rare chance to get a source seed along with the source salt, which when fed to an animal will increase your effective animal husbandry skill when breeding it. I will last for 1 hour.', '<p><b>Wishing Tree</b>\n</p>\n<ul><li>You may harvest a random harvestable product from the tree using a <a href=\"/index.php/Sickle\" title=\"Sickle\">sickle</a>.</li>\n<li>The product may be any type of <a href=\"/index.php/Fruit\" title=\"Fruit\">fruit</a>, <a href=\"/index.php/Berry\" title=\"Berry\">berry</a>, <a href=\"/index.php/Nut\" title=\"Nut\">nut</a>, <a href=\"/index.php/Herb\" title=\"Herb\">herb</a>, <a href=\"/index.php/Spice\" title=\"Spice\">spice</a>.</li>\n<li>The tree will provide more items than harvesting a normal tree or bush, and at a higher <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a>.</li>\n<li>The tree can also give special item within those categories that are not available anywhere else, and that grant more complexity than normal food to any dishes they are used in.</li></ul>\n<p><b>Sampo</b>\n</p>\n<ul><li>Feast for a refresh effect giving you a maximum <a href=\"/index.php/Food\" title=\"Food\">food</a>, <a href=\"/index.php/Water\" title=\"Water\">water</a>, <a class=\"mw-redirect\" href=\"/index.php/Stamina\" title=\"Stamina\">stamina</a>, and CCFP bars.</li>\n<li>Cures any disease</li>\n<li>Gives a random temporary <a href=\"/index.php/Affinity\" title=\"Affinity\">affinity</a> of long duration similar to a food affinity.</li>\n<li>Give a significant amounts of <a href=\"/index.php/Source_salt\" title=\"Source salt\">source salt</a>.</li>\n<li>There is a rare chance to get a <a href=\"/index.php/Source_seeds\" title=\"Source seeds\">source seed</a> along with the source salt, which when fed to an animal will increase your effective <a href=\"/index.php/Animal_husbandry\" title=\"Animal husbandry\">animal husbandry</a> skill when <a class=\"mw-redirect\" href=\"/index.php/Breeding\" title=\"Breeding\">breeding</a> it. I will last for 1 hour.</li></ul>', 3),
(14687, 3805, 'Pulse effects', 'Pulse_effects', 'Wishing Tree Spawns flowers randomly on grass tiles in and near the site. It will make all trees and bushes harvestable even if they are not in season. Sampo Humid Drizzle effect on all animals in and near the Holy Site. It resets the shearing status of sheep and rams .', '<p><b>Wishing Tree</b>\n</p>\n<ul><li>Spawns <a class=\"mw-redirect\" href=\"/index.php/Flowers\" title=\"Flowers\">flowers</a> randomly on grass tiles in and near the site.</li>\n<li>It will make all trees and bushes harvestable even if they are not in season.</li></ul>\n<p><b>Sampo</b>\n</p>\n<ul><li>Humid Drizzle effect on all animals in and near the Holy Site.</li>\n<li>It resets the shearing status of <a href=\"/index.php/Sheep\" title=\"Sheep\">sheep</a> and <a href=\"/index.php/Ram\" title=\"Ram\">rams</a>.</li></ul>', 4),
(14688, 3805, 'Creature spawns', 'Creature_spawns', 'Creatures, often with conditions, may spawn in or near the holy sites . This may include creatures with conditions that cannot spawn normally. For example, a scared seal or champion sheep. The types of creatures that can spawn, and the condition they are likely to have, depends on the type of Holy site.', '<p>Creatures, often with conditions, may spawn in or near the <a href=\"/index.php/Holy_sites\" title=\"Holy sites\">holy sites</a>. \n</p>\n<ul><li>This may include creatures with conditions that cannot spawn normally. For example, a scared seal or champion sheep.</li>\n<li>The types of creatures that can spawn, and the condition they are likely to have, depends on the type of Holy site.</li></ul>', 5),
(14689, 3805, 'Backlash effects', 'Backlash_effects', 'When performing any action at a Holy Site that might affect its Power or Corruption level (praying, preaching, purifying, or desecrating), there is a chance of a negative “Backlash” effect happening to you. This effect usually shares a theme with the Holy Site type or deity. The chance of a Backlash effect, and the average intensity of them, is increased by: The Holy Site’s Corruption being above 40. Higher Corruption if praying or preaching to increase Power. Higher Power if attempting to desecrate the site. Lower skill for a Power or Corruption influencing action ( Praying , Preaching , or Exorcism ). Actions relating directly to Corruption (purifying or desecrating). If the Holy Site’s Corruption is above 40, there is also a small chance to trigger a Backlash effect when performing the Holy Site’s special action. All Backlash effects may be partially or completely resisted by a Soul Strength skill check. Various Backlash effects are possible, including a random wound, various hostile spell effects being applied to you, or hostile creatures being summoned against you.', '<p>When performing any action at a Holy Site that might affect its Power or Corruption level (praying, preaching, purifying, or desecrating), there is a chance of a negative “Backlash” effect happening to you. This effect usually shares a theme with the Holy Site type or deity.\n</p>\n<p>The chance of a Backlash effect, and the average intensity of them, is increased by:\n</p>\n<ul><li>The Holy Site’s Corruption being above 40.</li>\n<li>Higher Corruption if praying or preaching to increase Power.</li>\n<li>Higher Power if attempting to desecrate the site.</li>\n<li>Lower skill for a Power or Corruption influencing action (<a class=\"mw-redirect\" href=\"/index.php/Praying\" title=\"Praying\">Praying</a>, <a href=\"/index.php/Preaching\" title=\"Preaching\">Preaching</a>, or <a href=\"/index.php/Exorcism\" title=\"Exorcism\">Exorcism</a>).</li>\n<li>Actions relating directly to Corruption (purifying or desecrating).</li></ul>\n<p>If the Holy Site’s Corruption is above 40, there is also a small chance to trigger a Backlash effect when performing the Holy Site’s special action.\n</p>\n<p>All Backlash effects may be partially or completely resisted by a Soul Strength skill check.\n</p>\n<p>Various Backlash effects are possible, including a random wound, various hostile spell effects being applied to you, or hostile creatures being summoned against you.\n</p>', 6),
(14690, 3805, 'Expiration effects', 'Expiration_effects', 'When the activated Holy sites expires, the following things will happen: A very large amount of favor , for charging Holy Crop will be granted. the amount will be increased by rarity and power values and decreased by corruption. One last pulse effect is triggered, but with a significantly enhanced effect, as if the site had a power closer to 100.', '<p>When the activated <a href=\"/index.php/Holy_sites\" title=\"Holy sites\">Holy sites</a> expires, the following things will happen:\n</p>\n<ul><li>A very large amount of <a href=\"/index.php/Favor\" title=\"Favor\">favor</a>, for charging <a class=\"mw-redirect\" href=\"/index.php/Holy_Crop\" title=\"Holy Crop\">Holy Crop</a> will be granted. the amount will be increased by rarity and power values and decreased by corruption.</li>\n<li>One last pulse effect is triggered, but with a significantly enhanced effect, as if the site had a power closer to 100.</li></ul>', 7),
(14699, 3806, 'Description', 'Description', 'A mystical fountain whose waters quench curiosity as well as thirst. It bears an aura of Vynora. A Vynora Holy site will spawn randomly and will have a Vynora theme and biome. It will be in a unsettled area of the map. There are two different types of Vynora Holy sites that can spawn Wellspring of knowledge A mystical fountain dispensing knowledge. Spawns on beaches and other natural waterfronts. Akashic mirror. A weird, black mirror that appears to be peering into another world. Spawns on roads and other paved areas.', '<p><i>A mystical fountain whose waters quench curiosity as well as thirst. It bears an aura of Vynora.</i>\n</p>\n<p>A Vynora <a class=\"mw-redirect\" href=\"/index.php/Holy_site\" title=\"Holy site\">Holy site</a> will spawn randomly and will have a Vynora theme and biome. It will be in a unsettled area of the map.\n</p>\n<p>There are two different types of Vynora <a href=\"/index.php/Holy_sites\" title=\"Holy sites\">Holy sites</a> that can spawn\n</p>\n<p><b>Wellspring of knowledge</b>\n</p>\n<ul><li>A mystical fountain dispensing knowledge.</li>\n<li>Spawns on beaches and other natural waterfronts.</li></ul>\n<p><b>Akashic mirror.</b>\n</p>\n<ul><li>A weird, black mirror that appears to be peering into another world.</li>\n<li>Spawns on roads and other paved areas.</li></ul>', 0),
(14700, 3806, 'Positive effects', 'Positive_effects', 'Holy Sites have several positive effects. Except when otherwise stated, all these effects are available only to accounts with Premium time, and that have at least 30 Faith with the Holy Site’s deity.', '<p>Holy Sites have several positive effects. Except when otherwise stated, all these effects are available only to accounts with Premium time, and that have at least 30 Faith with the Holy Site’s deity.\n</p>', 1),
(14701, 3806, 'Passive effects', 'Passive_effects', 'Doubled QL gain bonus for items favored by Vynora, which means items receive +20% to QL increases from improvement, rather than 10%. Vynora grants this effect to wooden items. Higher faith gains, greater favor gains for Vynora, for all prayers and sermons held at any altar within the site or at the Holy site itself.', '<p>Doubled <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> gain bonus for items favored by Vynora, which means items receive +20% to <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> increases from improvement, rather than 10%. \n</p>\n<ul><li>Vynora grants this effect to wooden items.</li>\n<li>Higher <a href=\"/index.php/Faith\" title=\"Faith\">faith</a> gains, greater <a href=\"/index.php/Favor\" title=\"Favor\">favor</a> gains for Vynora, for all prayers and sermons held at any altar within the site or at the Holy site itself.</li></ul>', 2),
(14702, 3806, 'Special actions', 'Special_actions', 'Wellspring of Knowledge A small chance to catch any special fish while fishing, as long as you are using a tool that can be used to catch that type of fish When you imbibe the Wellspring of Knowledge you drink a liquid that grants a long spell effect, which grants additional chance of rarity while improving items. This bonus it for any items you are improving (not just Vynora\'s favored items). Akashic mirror Gaze into the mirror for skill checks (with significant potential skill gain) in various characteristics, a meditating skill check with half the skill gain of a normal meditating action but without affecting your meditation cooldown timers, and a small increase to a random skill.', '<p><b>Wellspring of Knowledge</b>\n</p>\n<ul><li>A small chance to catch any special fish while fishing, as long as you are using a tool that can be used to catch that type of fish</li>\n<li>When you <b>imbibe</b> the Wellspring of Knowledge you drink a <a href=\"/index.php/Liquid\" title=\"Liquid\">liquid</a> that grants a long spell effect, which grants additional chance of rarity while improving items. This bonus it for any items you are improving (not just Vynora\'s favored items).</li></ul>\n<p><b>Akashic mirror</b>\n</p>\n<ul><li>Gaze into the mirror for skill checks (with significant potential skill gain) in various characteristics, a meditating skill check with half the skill gain of a normal meditating action but without affecting your meditation cooldown timers, and a small increase to a random skill.</li></ul>', 3),
(14703, 3806, 'Pulse effects', 'Pulse_effects', 'Wellspring of Knowledge Awards a small amount of Sleep Bonus to everyone present within the Holy Site. Akashic mirror Awards a small amount of Sleep Bonus to everyone present within the Holy Site, and has a slight chance of giving a treasure hunt map.', '<p><b>Wellspring of Knowledge</b>\n</p>\n<ul><li>Awards a small amount of Sleep Bonus to everyone present within the Holy Site.</li></ul>\n<p><b>Akashic mirror</b>\n</p>\n<ul><li>Awards a small amount of Sleep Bonus to everyone present within the Holy Site, and has a slight chance of giving a treasure hunt map.</li></ul>', 4),
(14704, 3806, 'Creature spawns', 'Creature_spawns', 'Creatures, often with conditions, may spawn in or near the holy sites . This may include creatures with conditions that cannot spawn normally. For example, a scared seal or champion sheep. The types of creatures that can spawn, and the condition they are likely to have, depends on the type of Holy site.', '<p>Creatures, often with conditions, may spawn in or near the <a href=\"/index.php/Holy_sites\" title=\"Holy sites\">holy sites</a>. \n</p>\n<ul><li>This may include creatures with conditions that cannot spawn normally. For example, a scared seal or champion sheep.</li>\n<li>The types of creatures that can spawn, and the condition they are likely to have, depends on the type of Holy site.</li></ul>', 5);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(14705, 3806, 'Backlash effects', 'Backlash_effects', 'When performing any action at a Holy Site that might affect its Power or Corruption level (praying, preaching, purifying, or desecrating), there is a chance of a negative “Backlash” effect happening to you. This effect usually shares a theme with the Holy Site type or deity. The chance of a Backlash effect, and the average intensity of them, is increased by: The Holy Site’s Corruption being above 40. Higher Corruption if praying or preaching to increase Power. Higher Power if attempting to desecrate the site. Lower skill for a Power or Corruption influencing action ( Praying , Preaching , or Exorcism ). Actions relating directly to Corruption (purifying or desecrating). If the Holy Site’s Corruption is above 40, there is also a small chance to trigger a Backlash effect when performing the Holy Site’s special action. All Backlash effects may be partially or completely resisted by a Soul Strength skill check. Various Backlash effects are possible, including a random wound, various hostile spell effects being applied to you, or hostile creatures being summoned against you.', '<p>When performing any action at a Holy Site that might affect its Power or Corruption level (praying, preaching, purifying, or desecrating), there is a chance of a negative “Backlash” effect happening to you. This effect usually shares a theme with the Holy Site type or deity.\n</p>\n<p>The chance of a Backlash effect, and the average intensity of them, is increased by:\n</p>\n<ul><li>The Holy Site’s Corruption being above 40.</li>\n<li>Higher Corruption if praying or preaching to increase Power.</li>\n<li>Higher Power if attempting to desecrate the site.</li>\n<li>Lower skill for a Power or Corruption influencing action (<a class=\"mw-redirect\" href=\"/index.php/Praying\" title=\"Praying\">Praying</a>, <a href=\"/index.php/Preaching\" title=\"Preaching\">Preaching</a>, or <a href=\"/index.php/Exorcism\" title=\"Exorcism\">Exorcism</a>).</li>\n<li>Actions relating directly to Corruption (purifying or desecrating).</li></ul>\n<p>If the Holy Site’s Corruption is above 40, there is also a small chance to trigger a Backlash effect when performing the Holy Site’s special action.\n</p>\n<p>All Backlash effects may be partially or completely resisted by a Soul Strength skill check.\n</p>\n<p>Various Backlash effects are possible, including a random wound, various hostile spell effects being applied to you, or hostile creatures being summoned against you.\n</p>', 6),
(14706, 3806, 'Expiration effects', 'Expiration_effects', 'When the activated Holy sites expires, the following things will happen: A very large amount of favor , for charging Rite of Spring will be granted. The amount will be increased by rarity and power values and decreased by corruption. One last pulse effect is triggered, but with a significantly enhanced effect, as if the site had a power closer to 100.', '<p>When the activated <a href=\"/index.php/Holy_sites\" title=\"Holy sites\">Holy sites</a> expires, the following things will happen:\n</p>\n<ul><li>A very large amount of <a href=\"/index.php/Favor\" title=\"Favor\">favor</a>, for charging <a class=\"mw-redirect\" href=\"/index.php/Rite_of_Spring\" title=\"Rite of Spring\">Rite of Spring</a> will be granted. The amount will be increased by rarity and power values and decreased by corruption.</li>\n<li>One last pulse effect is triggered, but with a significantly enhanced effect, as if the site had a power closer to 100.</li></ul>', 7),
(14707, 3807, 'Description', 'Description', 'A mysterious, impenetrable obelisk that has fallen from the sky and embedded itself into the sand like a spear. It bears an aura of Magranon. A Magranon Holy site will spawn randomly and will have a Magranon theme and biome. It will be in a unsettled area of the map. There are two different types of Magranon Holy sites that can spawn Glowing Fissure A glowing, volcanic crack in the rock. Spawns in barren, rocky terrain. Otherworldly Monolith An obelisk that has fallen from the sky and buried itself into the ground. Spawns on sand.', '<p><i> A mysterious, impenetrable obelisk that has fallen from the sky and embedded itself into the sand like a spear. It bears an aura of Magranon.</i>\n</p>\n<p>A Magranon <a class=\"mw-redirect\" href=\"/index.php/Holy_site\" title=\"Holy site\">Holy site</a> will spawn randomly and will have a Magranon theme and biome. It will be in a unsettled area of the map.\n</p>\n<p>There are two different types of Magranon <a href=\"/index.php/Holy_sites\" title=\"Holy sites\">Holy sites</a> that can spawn\n</p>\n<p><b>Glowing Fissure</b>\n</p>\n<ul><li>A glowing, volcanic crack in the rock.</li>\n<li>Spawns in barren, rocky terrain.</li></ul>\n<p><b>Otherworldly Monolith</b>\n</p>\n<ul><li>An obelisk that has fallen from the sky and buried itself into the ground.</li>\n<li>Spawns on sand.</li></ul>', 0),
(14708, 3807, 'Positive effects', 'Positive_effects', 'Holy Sites have several positive effects. Except when otherwise stated, all these effects are available only to accounts with Premium time, and that have at least 30 Faith with the Holy Site’s deity.', '<p>Holy Sites have several positive effects. Except when otherwise stated, all these effects are available only to accounts with Premium time, and that have at least 30 Faith with the Holy Site’s deity.\n</p>', 1),
(14709, 3807, 'Passive effects', 'Passive_effects', 'These are active whenever you are within the Holy Site. Special visual effects and a spell effect icon will make it clear when you are within the Holy Site’s current borders. Doubled QL gain bonus for items favored by Magranon, which means items receive +20% to QL increases from improvement, rather than 10%. Magranon grants this effect to metal items. Higher faith gain, and greater favor gain for Magranon, for all prayers and sermons held at any altar within the site or at the Holy site itself.', '<p>These are active whenever you are within the Holy Site. Special visual effects and a spell effect icon will make it clear when you are within the Holy Site’s current borders.\n</p>\n<p>Doubled <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> gain bonus for items favored by Magranon, which means items receive +20% to <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> increases from improvement, rather than 10%. \n</p>\n<ul><li>Magranon grants this effect to metal items.</li>\n<li>Higher <a href=\"/index.php/Faith\" title=\"Faith\">faith</a> gain, and greater <a href=\"/index.php/Favor\" title=\"Favor\">favor</a> gain for Magranon, for all prayers and sermons held at any altar within the site or at the Holy site itself.</li></ul>', 2),
(14710, 3807, 'Special actions', 'Special_actions', 'Glowing Fissure Unearth a random item using a pickaxe , shovel , or trowel . This will usually be a gem and may come stored with favor . There is a small chance of receiving a large source crystal . There is a very small chance of receiving a random unique blood . On rare actions, there is a chance of receiving a strange bone fragment instead. Otherworldly Monolith Rummage at the monolith for a random metal lump from the impact site. These can be, in order of decreasing likelihood: a random base metal (any metal that can be mined as ore), a random alloy , empyrean lump , and a random moon metal . Only followers of Magranon may rummage.', '<p><b>Glowing Fissure</b>\n</p>\n<ul><li>Unearth a random item using a <a href=\"/index.php/Pickaxe\" title=\"Pickaxe\">pickaxe</a>, <a href=\"/index.php/Shovel\" title=\"Shovel\">shovel</a>, or <a href=\"/index.php/Trowel\" title=\"Trowel\">trowel</a>.</li>\n<li>This will usually be a gem and may come stored with <a href=\"/index.php/Favor\" title=\"Favor\">favor</a>.</li>\n<li>There is a small chance of receiving a large <a href=\"/index.php/Source_crystal\" title=\"Source crystal\">source crystal</a>.</li>\n<li>There is a very small chance of receiving a random unique <a href=\"/index.php/Blood\" title=\"Blood\">blood</a>.</li>\n<li>On rare actions, there is a chance of receiving a <a href=\"/index.php/Strange_bone\" title=\"Strange bone\">strange bone</a> fragment instead.</li></ul>\n<p><br/>\n<b>Otherworldly Monolith</b>\n</p>\n<ul><li>Rummage at the monolith for a random metal lump from the impact site. These can be, in order of decreasing likelihood: a random base <a class=\"mw-redirect\" href=\"/index.php/Metal\" title=\"Metal\">metal</a> (any metal that can be mined as ore), a random <a class=\"mw-redirect\" href=\"/index.php/Alloy\" title=\"Alloy\">alloy</a>, <a href=\"/index.php/Empyrean_lump\" title=\"Empyrean lump\">empyrean lump</a>, and a random <a class=\"mw-redirect\" href=\"/index.php/Moon_metal\" title=\"Moon metal\">moon metal</a>.</li>\n<li>Only followers of <a href=\"/index.php/Magranon\" title=\"Magranon\">Magranon</a> may rummage.</li></ul>', 3),
(14711, 3807, 'Pulse effects', 'Pulse_effects', 'Glowing Fissure Erupts, giving one archaeology fragment to everyone within the Holy Site. Fragment item types are drawn from a different list than usual. Some items that are impossible to find through normal archaeology can be found. Some items that can be found normally through archaeology are excluded especially wooden items. Fragments should generally have somewhat better end results in terms of enchantments, runes, and materials. Otherworldly Monolith Summons a quantity of Magranon ritual meteorites to land on random tiles within and near the Holy Site. These function identically to normal Ritual of the Sun meteorites, and cannot harm players by falling on them.', '<p><b>Glowing Fissure</b>\nErupts, giving one archaeology fragment to everyone within the Holy Site.\n</p>\n<ul><li>Fragment item types are drawn from a different list than usual.</li>\n<li>Some items that are impossible to find through normal <a href=\"/index.php/Archaeology\" title=\"Archaeology\">archaeology</a> can be found.</li>\n<li>Some items that can be found normally through <a href=\"/index.php/Archaeology\" title=\"Archaeology\">archaeology</a> are excluded especially wooden items.</li>\n<li>Fragments should generally have somewhat better end results in terms of enchantments, runes, and materials.</li></ul>\n<p><b>Otherworldly Monolith</b>\nSummons a quantity of Magranon ritual meteorites to land on random tiles within and near the Holy Site.\n</p>\n<ul><li>These function identically to normal Ritual of the Sun meteorites, and cannot harm players by falling on them.</li></ul>', 4),
(14712, 3807, 'Creature spawns', 'Creature_spawns', 'Creatures, often with conditions, may spawn in or near the holy sites . This may include creatures with conditions that cannot spawn normally. For example, a scared seal or champion sheep. The types of creatures that can spawn, and the condition they are likely to have, depends on the type of Holy site. Magranon sites have a slightly higher chance to spawn champion creatures.', '<p>Creatures, often with conditions, may spawn in or near the <a href=\"/index.php/Holy_sites\" title=\"Holy sites\">holy sites</a>. \n</p>\n<ul><li>This may include creatures with conditions that cannot spawn normally. For example, a scared seal or champion sheep.</li>\n<li>The types of creatures that can spawn, and the condition they are likely to have, depends on the type of Holy site.</li>\n<li>Magranon sites have a slightly higher chance to spawn champion creatures.</li></ul>', 5),
(14713, 3807, 'Backlash effects', 'Backlash_effects', 'When performing any action at a Holy Site that might affect its Power or Corruption level (praying, preaching, purifying, or desecrating), there is a chance of a negative “Backlash” effect happening to you. This effect usually shares a theme with the Holy Site type or deity. The chance of a Backlash effect, and the average intensity of them, is increased by: The Holy Site’s Corruption being above 40. Higher Corruption if praying or preaching to increase Power. Higher Power if attempting to desecrate the site. Lower skill for a Power or Corruption influencing action ( Praying , Preaching , or Exorcism ). Actions relating directly to Corruption (purifying or desecrating). If the Holy Site’s Corruption is above 40, there is also a small chance to trigger a Backlash effect when performing the Holy Site’s special action. All Backlash effects may be partially or completely resisted by a Soul Strength skill check. Various Backlash effects are possible, including a random wound, various hostile spell effects being applied to you, or hostile creatures being summoned against you.', '<p>When performing any action at a Holy Site that might affect its Power or Corruption level (praying, preaching, purifying, or desecrating), there is a chance of a negative “Backlash” effect happening to you. This effect usually shares a theme with the Holy Site type or deity.\n</p>\n<p>The chance of a Backlash effect, and the average intensity of them, is increased by:\n</p>\n<ul><li>The Holy Site’s Corruption being above 40.</li>\n<li>Higher Corruption if praying or preaching to increase Power.</li>\n<li>Higher Power if attempting to desecrate the site.</li>\n<li>Lower skill for a Power or Corruption influencing action (<a class=\"mw-redirect\" href=\"/index.php/Praying\" title=\"Praying\">Praying</a>, <a href=\"/index.php/Preaching\" title=\"Preaching\">Preaching</a>, or <a href=\"/index.php/Exorcism\" title=\"Exorcism\">Exorcism</a>).</li>\n<li>Actions relating directly to Corruption (purifying or desecrating).</li></ul>\n<p>If the Holy Site’s Corruption is above 40, there is also a small chance to trigger a Backlash effect when performing the Holy Site’s special action.\n</p>\n<p>All Backlash effects may be partially or completely resisted by a Soul Strength skill check.\n</p>\n<p>Various Backlash effects are possible, including a random wound, various hostile spell effects being applied to you, or hostile creatures being summoned against you.\n</p>', 6),
(14714, 3807, 'Expiration effects', 'Expiration_effects', 'When the activated Holy sites expires, the following things will happen: A very large amount of favor , for charging Ritual of the Sun will be granted.the amount will be increased by rarity and power values and decreased by corruption. One last pulse effect is triggered, but with a significantly enhanced effect, as if the site had a power closer to 100.', '<p>When the activated <a href=\"/index.php/Holy_sites\" title=\"Holy sites\">Holy sites</a> expires, the following things will happen:\n</p>\n<ul><li>A very large amount of <a href=\"/index.php/Favor\" title=\"Favor\">favor</a>, for charging <a class=\"mw-redirect\" href=\"/index.php/Ritual_of_the_Sun\" title=\"Ritual of the Sun\">Ritual of the Sun</a> will be granted.the amount will be increased by rarity and power values and decreased by corruption.</li>\n<li>One last pulse effect is triggered, but with a significantly enhanced effect, as if the site had a power closer to 100.</li></ul>', 7),
(14723, 3808, 'Description', 'Description', 'An unholy ritual circle of uncertain purpose. A crude totem of skulls, viscera, and decay. A Libila Holy site will spawn randomly and will have a Libila theme and biome. It will be in a unsettled area of the map. There are two different types of Libila Holy sites that can spawn Abyssal Circle An unholy ritual circle of uncertain purpose. Spawns on tundra. Pillar of Decay A crude totem of skulls, viscera, and decay. Spawns on tar and peat.', '<p><i>An unholy ritual circle of uncertain purpose.</i>\n</p>\n<p><i>A crude totem of skulls, viscera, and decay. </i>\n</p>\n<p>A Libila <a class=\"mw-redirect\" href=\"/index.php/Holy_site\" title=\"Holy site\">Holy site</a> will spawn randomly and will have a Libila theme and biome. It will be in a unsettled area of the map.\n</p>\n<p>There are two different types of Libila <a href=\"/index.php/Holy_sites\" title=\"Holy sites\">Holy sites</a> that can spawn\n</p>\n<p><b>Abyssal Circle</b>\n</p>\n<ul><li>An unholy ritual circle of uncertain purpose.</li>\n<li>Spawns on tundra.</li></ul>\n<p><b>Pillar of Decay</b>\n</p>\n<ul><li>A crude totem of skulls, viscera, and decay.</li>\n<li>Spawns on tar and peat.</li></ul>', 0),
(14724, 3808, 'Positive effects', 'Positive_effects', 'Holy Sites have several positive effects. Except when otherwise stated, all these effects are available only to accounts with Premium time, and that have at least 30 Faith with the Holy Site’s deity.', '<p>Holy Sites have several positive effects. Except when otherwise stated, all these effects are available only to accounts with Premium time, and that have at least 30 Faith with the Holy Site’s deity.\n</p>', 1),
(14725, 3808, 'Passive effects', 'Passive_effects', 'These are active whenever you are within the Holy Site. Special visual effects and a spell effect icon will make it clear when you are within the Holy Site’s current borders. Doubled QL gain bonus for items favored by Libila, which means items receive +20% to QL increases from improvement, rather than 10%. Libila grants this effect to leather items. Higher faith gain, and greater favor gain for Libila, for all prayers and sermons held at any altar within the site or at the Holy site itself. Hostile monsters will no longer be hostile towards you. This is the same effect that Libila priests are granted at 60 faith . They are ignored by monsters (this does not apply to all hostile creatures, as some are not considered monsters (like bears). This also excludes rift monsters and legendary creatures. Higher faith gain, and greater favor gain for Libila, for all prayers and sermons held at any altar within the site or at the Holy site itself.*', '<p>These are active whenever you are within the Holy Site. Special visual effects and a spell effect icon will make it clear when you are within the Holy Site’s current borders.\n</p>\n<p>Doubled <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> gain bonus for items favored by Libila, which means items receive +20% to <a class=\"mw-redirect\" href=\"/index.php/QL\" title=\"QL\">QL</a> increases from improvement, rather than 10%. \n</p>\n<ul><li>Libila grants this effect to leather items.</li></ul>\n<ul><li>Higher <a href=\"/index.php/Faith\" title=\"Faith\">faith</a> gain, and greater <a href=\"/index.php/Favor\" title=\"Favor\">favor</a> gain for Libila, for all prayers and sermons held at any altar within the site or at the Holy site itself.</li></ul>\n<ul><li>Hostile monsters will no longer be hostile towards you. This is the same effect that Libila priests are granted at 60 <a href=\"/index.php/Faith\" title=\"Faith\">faith</a>. They are ignored by monsters (this does not apply to all hostile creatures, as some are not considered monsters (like bears). This also excludes rift monsters and legendary creatures.</li></ul>\n<p><br/>\n</p>\n<ul><li>Higher faith gain, and greater favor gain for Libila, for all prayers and sermons held at any altar within the site or at the Holy site itself.*</li></ul>', 2),
(14726, 3808, 'Special actions', 'Special_actions', 'Abyssal Circle Channel a crystal containing the soul of a random type creature, possibly with the Champion or Diseased condition. A soul crystal can be broken with a hammer, blunt weapon, or sacrificial knife in exchange for a powerful Mind Stealer-like effect, using the creature template to determine possible skills. “Diseased” condition gives less skill and “Champion” condition gives more. Pillar of Decay Extract a flesh pod using any valid butchering tool. The flesh pod may be hatched into a tamed Simulacrum creature by using it on any tile. If the flesh pod has a condition such as “Champion” or “Greenish”, the creature will have that condition. Quality of flesh pod, rarity of flesh pod, and type of tile used to hatch the Simulacrum will affect its size and the values of several of its characteristics, making it weaker or stronger in combat.', '<p><b>Abyssal Circle</b> \nChannel a crystal containing the soul of a random type creature, possibly with the Champion or Diseased condition.\n</p>\n<ul><li>A soul crystal can be broken with a hammer, blunt weapon, or sacrificial knife in exchange for a powerful Mind Stealer-like effect, using the creature template to determine possible skills. “Diseased” condition gives less skill and “Champion” condition gives more.</li></ul>\n<p><br/>\n<b>Pillar of Decay</b> \nExtract a flesh pod using any valid butchering tool.\n</p>\n<ul><li>The flesh pod may be hatched into a tamed Simulacrum creature by using it on any tile. If the flesh pod has a condition such as “Champion” or “Greenish”, the creature will have that condition.</li>\n<li>Quality of flesh pod, rarity of flesh pod, and type of tile used to hatch the Simulacrum will affect its size and the values of several of its characteristics, making it weaker or stronger in combat.</li></ul>', 3),
(14727, 3808, 'Pulse effects', 'Pulse_effects', 'Abyssal Circle or Pillar of Decay Long-lasting “Rampage” spell effect on everyone within the Holy Site. This effect provides an offensive CR bonus and a significant reduction in stamina drain. The power and duration of this effect can be extended by killing creatures while the effect is active', '<p><b>Abyssal Circle</b> or <b>Pillar of Decay</b>\n</p>\n<ul><li>Long-lasting “Rampage” spell effect on everyone within the Holy Site.</li>\n<li>This effect provides an offensive CR bonus and a significant reduction in stamina drain.</li>\n<li>The power and duration of this effect can be extended by killing creatures while the effect is active</li></ul>', 4),
(14728, 3808, 'Creature spawns', 'Creature_spawns', 'Creatures, often with conditions, may spawn in or near the holy sites . This may include creatures with conditions that cannot spawn normally. For example, a scared seal or champion sheep. The types of creatures that can spawn, and the condition they are likely to have, depends on the type of Holy site. Libila sites have a slightly higher chance to spawn champion creatures.', '<p>Creatures, often with conditions, may spawn in or near the <a href=\"/index.php/Holy_sites\" title=\"Holy sites\">holy sites</a>. \n</p>\n<ul><li>This may include creatures with conditions that cannot spawn normally. For example, a scared seal or champion sheep.</li>\n<li>The types of creatures that can spawn, and the condition they are likely to have, depends on the type of Holy site.</li>\n<li>Libila sites have a slightly higher chance to spawn champion creatures.</li></ul>', 5),
(14729, 3808, 'Backlash effects', 'Backlash_effects', 'When performing any action at a Holy Site that might affect its Power or Corruption level (praying, preaching, purifying, or desecrating), there is a chance of a negative “Backlash” effect happening to you. This effect usually shares a theme with the Holy Site type or deity. The chance of a Backlash effect, and the average intensity of them, is increased by: The Holy Site’s Corruption being above 40. Higher Corruption if praying or preaching to increase Power. Higher Power if attempting to desecrate the site. Lower skill for a Power or Corruption influencing action ( Praying , Preaching , or Exorcism ). Actions relating directly to Corruption (purifying or desecrating). If the Holy Site’s Corruption is above 40, there is also a small chance to trigger a Backlash effect when performing the Holy Site’s special action. All Backlash effects may be partially or completely resisted by a Soul Strength skill check. Various Backlash effects are possible, including a random wound, various hostile spell effects being applied to you, or hostile creatures being summoned against you.', '<p>When performing any action at a Holy Site that might affect its Power or Corruption level (praying, preaching, purifying, or desecrating), there is a chance of a negative “Backlash” effect happening to you. This effect usually shares a theme with the Holy Site type or deity.\n</p>\n<p>The chance of a Backlash effect, and the average intensity of them, is increased by:\n</p>\n<ul><li>The Holy Site’s Corruption being above 40.</li>\n<li>Higher Corruption if praying or preaching to increase Power.</li>\n<li>Higher Power if attempting to desecrate the site.</li>\n<li>Lower skill for a Power or Corruption influencing action (<a class=\"mw-redirect\" href=\"/index.php/Praying\" title=\"Praying\">Praying</a>, <a href=\"/index.php/Preaching\" title=\"Preaching\">Preaching</a>, or <a href=\"/index.php/Exorcism\" title=\"Exorcism\">Exorcism</a>).</li>\n<li>Actions relating directly to Corruption (purifying or desecrating).</li></ul>\n<p>If the Holy Site’s Corruption is above 40, there is also a small chance to trigger a Backlash effect when performing the Holy Site’s special action.\n</p>\n<p>All Backlash effects may be partially or completely resisted by a Soul Strength skill check.\n</p>\n<p>Various Backlash effects are possible, including a random wound, various hostile spell effects being applied to you, or hostile creatures being summoned against you.\n</p>', 6),
(14730, 3808, 'Expiration effects', 'Expiration_effects', 'When the activated Holy sites expires, the following things will happen: A very large amount of favor , for charging Rite of death will be granted..the amount will be increased by rarity and power values and decreased by corruption. One last pulse effect is triggered, but with a significantly enhanced effect, as if the site had a power closer to 100.', '<p>When the activated <a href=\"/index.php/Holy_sites\" title=\"Holy sites\">Holy sites</a> expires, the following things will happen:\n</p>\n<ul><li>A very large amount of <a href=\"/index.php/Favor\" title=\"Favor\">favor</a>, for charging <a href=\"/index.php/Rite_of_death\" title=\"Rite of death\">Rite of death</a> will be granted..the amount will be increased by rarity and power values and decreased by corruption.</li>\n<li>One last pulse effect is triggered, but with a significantly enhanced effect, as if the site had a power closer to 100.</li></ul>', 7),
(14738, 3818, 'Description', 'Description', 'A small woven basket with something inside it.', '<p><i>A small woven basket with something inside it.</i>\n</p>', 0),
(14739, 3818, 'Notes', 'Notes', 'Destroyed when opened Contains a one step treasure map Easter bunny map', '<ul><li>Destroyed when opened</li>\n<li>Contains a one step treasure map <i><a class=\"mw-redirect\" href=\"/index.php/Treasure_map\" title=\"Treasure map\">Easter bunny map</a></i></li></ul>\n<p><a class=\"image\" href=\"/index.php/File:Easter_bunny_map.png\"><img alt=\"Easter bunny map.png\" data-file-height=\"337\" data-file-width=\"489\" decoding=\"async\" height=\"207\" src=\"/images/thumb/b/b6/Easter_bunny_map.png/300px-Easter_bunny_map.png\" srcset=\"/images/thumb/b/b6/Easter_bunny_map.png/450px-Easter_bunny_map.png 1.5x, /images/b/b6/Easter_bunny_map.png 2x\" width=\"300\"/></a>\n</p>', 1),
(14746, 1237, 'Description', 'Description', 'Contains many preset countdown timers and custom timers you can create.', '<p>Contains many preset countdown timers and custom timers you can create.\n</p>', 0),
(14747, 1237, 'Show / Hide Timers', 'Show_.2F_Hide_Timers', 'Timers window a priest might see with one custom timer To show or hide the timers window on your GUI : Open the main menu with Esc , select Tools then Timers , or... Open the console with F1 and enter toggle timers . The window, which is labeled Timers can be moved around as required by left-click/dragging.', '<div class=\"thumb tright\"><div class=\"thumbinner\" style=\"width:202px;\"><a class=\"image\" href=\"/index.php/File:Timers.jpg\"><img alt=\"\" class=\"thumbimage\" data-file-height=\"192\" data-file-width=\"266\" decoding=\"async\" height=\"144\" src=\"/images/thumb/6/6b/Timers.jpg/200px-Timers.jpg\" srcset=\"/images/6/6b/Timers.jpg 1.5x\" width=\"200\"/></a> <div class=\"thumbcaption\"><div class=\"magnify\"><a class=\"internal\" href=\"/index.php/File:Timers.jpg\" title=\"Enlarge\"></a></div>Timers window a priest might see with one custom timer</div></div></div>\n<p>To show or hide the timers window on your <a href=\"/index.php/Interface_and_controls\" title=\"Interface and controls\">GUI</a>:\n</p>\n<ul><li>Open the main menu with <span class=\"key\"> Esc </span>, select <b>Tools</b> then <b>Timers</b>, or...</li>\n<li>Open the console with <span class=\"key\"> F1 </span> and enter <b>toggle timers</b>.</li></ul>\n<p>The window, which is labeled <b>Timers</b> can be moved around as required by left-click/dragging.\n</p>', 1),
(14748, 1237, 'Preset Timers', 'Preset_Timers', 'Preset timers are countdown timers displaying the time remaining until you can perform certain actions: Access your bank account after a move Change your village Change your kingdom Change your religion Pray for Faith Pray/exorcise at a Holy Site Give a sermon Receive an Alignment change Meditate for skill Use a meditation path ability Receive your next meditation question', '<p>Preset timers are countdown timers displaying the time remaining until you can perform certain actions:\n</p>\n<ul><li>Access your bank account after a move</li>\n<li>Change your village</li>\n<li>Change your kingdom</li>\n<li>Change your religion</li>\n<li>Pray for Faith</li>\n<li>Pray/exorcise at a Holy Site</li>\n<li>Give a sermon</li>\n<li>Receive an Alignment change</li>\n<li>Meditate for skill</li>\n<li>Use a meditation path ability</li>\n<li>Receive your next meditation question</li></ul>', 2),
(14749, 1237, 'Notes:', 'Notes:', 'Some timers will not be displayed if they are irrelevant to your character. i.e. you will not see the “Sermon” timer if you are not a priest. To avoid clutter, some timers will not display at all unless a cooldown period is active. These include bank movement, changing village/deity/kingdom, and receiving Alignment changes. Timers can be hovered over with the mouse to display a description. For timers with a maximum amount associated with them, like Faith gains per day, the amount you have left will also be shown. To hide a timer, right click the timer, hover over its name, and click “Hide”. Even if hidden, the timer’s current time can be viewed by right clicking anywhere on the Timers panel and hovering over “Show hidden timers”. Clicking the name of the timer in this list will unhide it. A sound will now play when any running timer finishes. Finished timers display their text in a different color, preset and custom timers have differently colored progress bars, and paused/stopped custom timers have their progress bars darkened.', '<ul><li>Some timers will not be displayed if they are irrelevant to your character. i.e. you will not see the “Sermon” timer if you are not a priest.</li>\n<li>To avoid clutter, some timers will not display at all unless a cooldown period is active. These include bank movement, changing village/deity/kingdom, and receiving Alignment changes.</li>\n<li>Timers can be hovered over with the mouse to display a description. For timers with a maximum amount associated with them, like Faith gains per day, the amount you have left will also be shown.</li>\n<li>To hide a timer, right click the timer, hover over its name, and click “Hide”. Even if hidden, the timer’s current time can be viewed by right clicking anywhere on the Timers panel and hovering over “Show hidden timers”. Clicking the name of the timer in this list will unhide it.</li>\n<li>A sound will now play when any running timer finishes.</li>\n<li>Finished timers display their text in a different color, preset and custom timers have differently colored progress bars, and paused/stopped custom timers have their progress bars darkened.</li></ul>\n<p><br/>\n</p>', 3),
(14750, 1237, 'Custom Timers', 'Custom_Timers', 'Add timers Right click on the timer window and select Add timer . Enter a name for the timer. No name may be used but it will be called null by the server. Maximum name length is 10 characters. Enter a duration for the timer Any integer not required may be left blank. Select whether or not the timer should begin immediately. Click \'Add Timer\' to begin the timer or add it to the list ready to start. Manage timers The right-click interface will present the player with a number of options. Lock window This will prevent accidental moving of the timer window.  Repeat to remove the lock. Hide timers This will hide the window from the GUI.  To display the window again see the relevant section above. Add timer See above. Timer name Restart Pause/Resume Reset counter (resets the number of times the counter has run). Remove Hovering the mouse over a particular timer will display the name, time remaining and how many times the counter has been started.  Pausing and resuming does not count towards the starts counter however restarting or stopping and starting the timer does.', '<h3><span class=\"mw-headline\" id=\"Add_timers\">Add timers</span></h3>\n<ol><li>Right click on the timer window and select <i>Add timer</i>.</li>\n<li>Enter a name for the timer.\n<ul><li>No name may be used but it will be called <i>null</i> by the server.</li>\n<li>Maximum name length is 10 characters.</li></ul></li>\n<li>Enter a duration for the timer\n<ul><li>Any integer not required may be left blank.</li></ul></li>\n<li>Select whether or not the timer should begin immediately.</li>\n<li>Click \'Add Timer\' to begin the timer or add it to the list ready to start.</li></ol>\n<h3><span class=\"mw-headline\" id=\"Manage_timers\">Manage timers</span></h3>\n<p>The right-click interface will present the player with a number of options.\n</p>\n<dl><dt>Lock window</dt>\n<dd>This will prevent accidental moving of the timer window.  Repeat to remove the lock.</dd>\n<dt>Hide timers</dt>\n<dd>This will hide the window from the GUI.  To display the window again see the relevant section above.</dd>\n<dt>Add timer</dt>\n<dd>See above.</dd>\n<dt>Timer name</dt>\n<dd></dd></dl>\n<ul><li>Restart</li>\n<li>Pause/Resume</li>\n<li>Reset counter (resets the number of times the counter has run).</li>\n<li>Remove</li></ul>\n<p>Hovering the mouse over a particular timer will display the name, time remaining and how many times the counter has been started.  Pausing and resuming does not count towards the <i>starts</i> counter however restarting or stopping and starting the timer does.\n</p>', 4),
(14751, 1237, 'Notes', 'Notes', 'A maximum of 5 timers may be created at any one time. On reconnect custom timers will reset to their full time but not start counting down until started by the player. Start counts do not reset on reconnect. Timers may be hidden when resizing the game window.  To re-display simply drag the timer header around the screen.', '<ul><li>A maximum of 5 timers may be created at any one time.</li>\n<li>On reconnect custom timers will reset to their full time but not start counting down until started by the player.</li>\n<li>Start counts do not reset on reconnect.</li>\n<li>Timers may be hidden when resizing the game window.  To re-display simply drag the timer header around the screen.</li></ul>', 5),
(14752, 3823, 'Server border sharks (mechanics)', 'Server_border_sharks_.28mechanics.29', 'One of Wurm\'s game features is that of traveling to other servers which can be connected at mutual map borders: north, east, south, or west. If you\'re getting close to a border that is not connected during such attempted travel, you will get orange event messages to warn you: You see dark shadows moving beneath the waves.\n An enourmous shark scouts you from below.\n Suddenly, strong winds and waves throw you overboard! Soon after seeing these messages, you will automatically and repeatedly be disembarked from your ship or boat . If you\'re AFK and sailing with Autorun enabled, you may be saved from an otherwise certain drowning death. At this point, you must turn around and try another route. The currents work against you and you get nowhere If you\'re too close to the border, this will be the final warning message that immediately disembarks you. Boats have to be turned around using the right-click options Move > Turn item clockwise or Move > Turn item counterclockwise , or being dragged . If you can\'t drag, you might need to pull or push using Move > Push and Move >> Pull respectively, to get away from the border.', '<p>One of Wurm\'s game features is that of traveling to other <a class=\"mw-redirect\" href=\"/index.php/Server\" title=\"Server\">servers</a> which can be connected at mutual <a class=\"mw-redirect\" href=\"/index.php/Map\" title=\"Map\">map</a> borders: north, east, south, or west. If you\'re getting close to a border that is not connected during such attempted travel, you will get orange event messages to warn you:\n</p>\n<pre> You see dark shadows moving beneath the waves.\n An enourmous shark scouts you from below.\n Suddenly, strong winds and waves throw you overboard!\n</pre>\n<p>Soon after seeing these messages, you will automatically and repeatedly be disembarked from your <a href=\"/index.php/Ship\" title=\"Ship\">ship</a> or <a class=\"mw-redirect\" href=\"/index.php/Boat\" title=\"Boat\">boat</a>. If you\'re AFK and sailing with <a href=\"/index.php/Key_bindings#Default_keybindings\" title=\"Key bindings\">Autorun</a> enabled, you may be saved from an otherwise certain <a href=\"/index.php/Drown\" title=\"Drown\">drowning</a> death. At this point, you must turn around and try another route.\n</p>\n<h3><span class=\"mw-headline\" id=\"The_currents_work_against_you_and_you_get_nowhere\">The currents work against you and you get nowhere</span></h3>\n<p>If you\'re too close to the border, this will be the final warning message that immediately disembarks you. Boats have to be turned around using the right-click options <i>Move &gt; Turn item clockwise</i> or <i>Move &gt; Turn item counterclockwise</i>, or being <a class=\"mw-redirect\" href=\"/index.php/Drag\" title=\"Drag\">dragged</a>. If you can\'t drag, you might need to pull or push using <i>Move &gt; Push</i> and <i>Move &gt;&gt; Pull</i> respectively, to get away from the border.\n</p>', 0),
(14753, 3823, 'See also', 'See_also', 'Shark', '<ul><li><a href=\"/index.php/Shark\" title=\"Shark\">Shark</a></li></ul>', 1),
(14754, 3824, 'Introduction', 'Introduction', 'When you first enter the lands of Wurm you can obtain nutritious food from a Bartender in any starter town for 24 playing hours. After that you\'re on your own. \nPlayers usually Forage to survive after that. Foraging is an important skill to develop and the better you are at it the better the items you forage will be. So, if I get really good at foraging, why would I ever need to cook?', '<p>When you first enter the lands of Wurm you can obtain nutritious food from a <a href=\"/index.php/Bartender\" title=\"Bartender\">Bartender</a> in any starter town for 24 playing hours. After that you\'re on your own. \nPlayers usually <a class=\"mw-redirect\" href=\"/index.php/Forage\" title=\"Forage\">Forage</a> to survive after that. Foraging is an important skill to develop and the better you are at it the better the items you forage will be. \n<i>So, if I get really good at foraging, why would I ever need to cook?</i>\n</p>', 0),
(14755, 3824, 'Why Cook?', 'Why_Cook.3F', '1. Good Nutrition - Cooked food is always more nutritious than raw food. Good nutrition has many advantages such as having to eat less often and faster stamina regeneration. A healthy character is a more capable character! 2. Temporary Affinities - Prepared foods can give a temporary boost to certain characteristics or skills. You will learn more about Affinities later.', '<p>1. Good Nutrition - Cooked food is always more nutritious than raw food. Good nutrition has many advantages such as having to eat less often and faster stamina regeneration. A healthy character is a more capable character!<br/>\n2. Temporary Affinities - Prepared foods can give a temporary boost to certain characteristics or skills. You will learn more about Affinities later.\n</p>', 1),
(14756, 3824, 'But cooking is hard and it takes a long time!', 'But_cooking_is_hard_and_it_takes_a_long_time.21', 'Actually, its not and it doesn\'t have to! Cooking can be as simple and quick as you want it to be. And you want to start out simple anyway because that\'s how you get better faster, by cooking very simple easy things.', '<p>Actually, its not and it doesn\'t have to! Cooking can be as simple and quick as you want it to be. And you want to start out simple anyway because that\'s how you get better faster, by cooking very simple easy things. \n</p>', 2),
(14757, 3824, 'What will I need?', 'What_will_I_need.3F', 'To start cooking all you will need is a Pottery bowl , something to put in it and a campfire . That\'s it. You received a pottery bowl in your inventory when you first started but if you\'re like me you may have misplaced it by now. Not to worry as they are very easy to make! Dig some clay , (usually found by water) and mold it into a clay bowl using the Hand icon in your character window. Drop the clay bowl into a fire and wait until the description changes from Clay bow to Pottery bowl.', '<p>To start cooking all you will need is a <a href=\"/index.php/Pottery_bowl\" title=\"Pottery bowl\">Pottery bowl</a>, something to put in it and a <a href=\"/index.php/Campfire\" title=\"Campfire\">campfire</a>. That\'s it. You received a pottery bowl in your inventory when you first started but if you\'re like me you may have misplaced it by now. Not to worry as they are very easy to make! Dig some <a href=\"/index.php/Clay\" title=\"Clay\">clay</a>, (usually found by water) and mold it into a clay bowl using the Hand icon in your character window. Drop the clay bowl into a fire and wait until the description changes from Clay bow to Pottery bowl. \n</p>', 3),
(14758, 3824, 'Using Lore', 'Using_Lore', 'So you\'ve got your bowl and something to put in it, lets say you foraged a vegetable or had good luck hunting and butchered an animal. Put something in the Pottery bowl, (one thing is enough) then right click the bowl and select \'Lore\'. This useful function will tell you ahead of time what will happen if you cook it. You can receive a variety of messages from the Lore function but the one were interested in now is: \"The ingredients in the pottery bowl would make a <item name> when cooked in a cooker.\" If you see a message like that drop the bowl in a campfire and before you know it you\'ll have some cooked food to eat. If you don\'t see a message like that try something else in the bowl until you do.', '<p>So you\'ve got your bowl and something to put in it, lets say you foraged a vegetable or had good luck hunting and butchered an animal. Put something in the Pottery bowl, (one thing is enough) then right click the bowl and select \'Lore\'. This useful function will tell you ahead of time what will happen if you cook it. You can receive a variety of messages from the Lore function but the one were interested in now is: \"The ingredients in the pottery bowl would make a <i>&lt;item name&gt;</i>  when cooked in a cooker.\" If you see a message like that drop the bowl in a campfire and before you know it you\'ll have some cooked food to eat. If you don\'t see a message like that try something else in the bowl until you do. \n</p>', 4),
(14759, 3824, 'Recipes', 'Recipes', 'Quickbar When you cook something you may see a message saying that a new recipe has been added to your cookbook. This happens when you cook something unique that you have never cooked before. Your cookbook can be accessed from a button on your Quickbar (see image at right). The bowl over the campfire button will open your cookbook. The cookbook comes loaded with many recipes already which are show in green, the ones you create yourself are white.', '<div class=\"thumb tright\"><div class=\"thumbinner\" style=\"width:302px;\"><a class=\"image\" href=\"/index.php/File:Quickbar.png\"><img alt=\"\" class=\"thumbimage\" data-file-height=\"149\" data-file-width=\"601\" decoding=\"async\" height=\"74\" src=\"/images/thumb/6/6c/Quickbar.png/300px-Quickbar.png\" srcset=\"/images/thumb/6/6c/Quickbar.png/450px-Quickbar.png 1.5x, /images/thumb/6/6c/Quickbar.png/600px-Quickbar.png 2x\" width=\"300\"/></a> <div class=\"thumbcaption\"><div class=\"magnify\"><a class=\"internal\" href=\"/index.php/File:Quickbar.png\" title=\"Enlarge\"></a></div>Quickbar</div></div></div>\n<p>When you cook something you may see a message saying that a new recipe has been added to your cookbook. This happens when you cook something unique that you have never cooked before. Your cookbook can be accessed from a button on your Quickbar (see image at right). The bowl over the campfire button will open your cookbook. The cookbook comes loaded with many recipes already which are show in green, the ones you create yourself are white. \n</p>', 5),
(14760, 3824, 'Affinities', 'Affinities', 'When you eat prepared food you may see a message like \"You suddenly realize you have more of an insight about <something> . Affinities are a complex subject beyond the scope of this guide but for now just know that they are called Temporary Affinities and cooking the same thing in the same way will always give you the same affinity. At first they will not last very long but as your cooking skill improves the affinities your food will give you will last longer.', '<p>When you eat prepared food you may see a message like \"You suddenly realize you have more of an insight about <i>&lt;something&gt;</i>. <a class=\"mw-redirect\" href=\"/index.php/Affinities\" title=\"Affinities\">Affinities</a> are a complex subject beyond the scope of this guide but for now just know that they are called Temporary Affinities and cooking the same thing in the same way will always give you the same affinity. At first they will not last very long but as your cooking skill improves the affinities your food will give you will last longer. \n</p>', 6),
(14761, 3824, 'Getting fancy', 'Getting_fancy', 'Once you have the simple basics of feeding yourself under your belt (and it really is as simple as just described) you may want to begin experimenting. While a single ingredient in a bowl will work, you certainly are not limited to that. Try combining multiple ingredients of different types to see what you get. Try different containers like maybe make yourself a frying pan and see what happens when you put something in that. Don\'t forget about the Lore function. Adding ingredients found through Botanizing will add to the variety of your food. You can get as creative as you like.', '<p>Once you have the simple basics of feeding yourself under your belt (and it really is as simple as just described) you may want to begin experimenting. While a single ingredient in a bowl will work, you certainly are not limited to that. Try combining multiple ingredients of different types to see what you get. Try different containers like maybe make yourself a frying pan and see what happens when you put something in that. Don\'t forget about the Lore function. Adding ingredients found through <a class=\"mw-redirect\" href=\"/index.php/Botanize\" title=\"Botanize\">Botanizing</a> will add to the variety of your food. You can get as creative as you like. \n</p>', 7),
(14762, 3824, 'Branching out', 'Branching_out', 'Cooking goes way beyond heating food in a container. (But it certainly doesn\'t have to!) There are several other skills, tools and materials that all are part of the cooking experience. While you are enjoying your first cooked food, have a look at some of the following cooking related articles. Bon Appétit', '<p>Cooking goes way beyond heating food in a container. (But it certainly doesn\'t have to!)<br/>\nThere are several other skills, tools and materials that all are part of the cooking experience.\n</p>\n<p>While you are enjoying your first cooked food, have a look at some of the following cooking related articles. \n</p>\n<p>Bon Appétit\n</p>', 8),
(14763, 3824, 'Further reading', 'Further_reading', 'Baking Beverages Botanizing Butchering Dairy Food Making Farming Foraging Forestry Gardening', '<ul><li><a href=\"/index.php/Baking\" title=\"Baking\">Baking</a></li>\n<li><a href=\"/index.php/Beverages\" title=\"Beverages\">Beverages</a></li>\n<li><a href=\"/index.php/Botanizing\" title=\"Botanizing\">Botanizing</a></li>\n<li><a href=\"/index.php/Butchering\" title=\"Butchering\">Butchering</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Dairy_Food_Making\" title=\"Dairy Food Making\">Dairy Food Making</a></li>\n<li><a href=\"/index.php/Farming\" title=\"Farming\">Farming</a></li>\n<li><a href=\"/index.php/Foraging\" title=\"Foraging\">Foraging</a></li>\n<li><a href=\"/index.php/Forestry\" title=\"Forestry\">Forestry</a></li>\n<li><a href=\"/index.php/Gardening\" title=\"Gardening\">Gardening</a></li></ul>', 9),
(14772, 3821, 'Description', 'Description', 'A unit to hold several food storage bins.', '<p><i>A unit to hold several food storage bins.</i>\n</p>', 0);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(14773, 3821, 'Notes', 'Notes', 'Requires 50 fine carpentry to begin and/or continue creation. Can be planted. Cannot be mailed . Must be empty to pick up. Acts like a four-times-capacity food storage bin with four shelves for sorting. Individual food storage bins cannot be added or removed once created. To rename the shelves: after creation, \"take\" the Large pantry cupboard into your inventory to establish ownership. Then you can plant the unit, and rename the shelves as the owner. Each individual shelf can be locked with a large padlock or small padlock , which prevents use until unlocked unless permissions are set. The minimum allowed quality of items put into each individual shelf can be dictated by the Quality lock feature.', '<ul><li>Requires 50 fine carpentry to begin and/or continue creation.</li>\n<li>Can be planted.</li>\n<li>Cannot be <a href=\"/index.php/Mail\" title=\"Mail\">mailed</a>.</li>\n<li>Must be empty to pick up.</li>\n<li>Acts like a four-times-capacity food storage bin with four shelves for sorting.</li>\n<li>Individual food storage bins cannot be added or removed once created.</li>\n<li>To rename the shelves: after creation, \"take\" the Large pantry cupboard into your inventory to establish ownership. Then you can plant the unit, and rename the shelves as the owner.</li>\n<li>Each individual shelf can be locked with a <a href=\"/index.php/Large_padlock\" title=\"Large padlock\">large padlock</a> or <a href=\"/index.php/Small_padlock\" title=\"Small padlock\">small padlock</a>, which prevents use until unlocked unless <a href=\"/index.php/Permissions\" title=\"Permissions\">permissions</a> are set.</li>\n<li>The minimum allowed quality of items put into each individual shelf can be dictated by the <a href=\"/index.php/Quality_lock\" title=\"Quality lock\">Quality lock</a> feature.</li></ul>', 1),
(14774, 2898, 'Description', 'Description', 'Faith is the ethereal power of religious belief. In Wurm, it also gives priests the ability to cast spells and commit to other unique activities.', '<p>Faith is the ethereal power of religious belief. In Wurm, it also gives <a href=\"/index.php/Priest\" title=\"Priest\">priests</a> the ability to cast spells and commit to other unique activities.\n</p>', 0),
(14775, 2898, 'Prayer', 'Prayer', 'To gain faith (and also favor ), a player can pray at an altar . In order to do this, however, one must first choose and convert to a religion . Praying may take place in back-to-back sessions, but a 20-minute cool-down period is needed between prayers in order for each subsequent prayer to count toward further faith skill gain, up to five times per day. While additional prayer attempts between these cool-down periods will not raise faith, they will increase the player\'s prayer skill. If faith is not gained from a prayer, the action will not be counted against the five prayer per day limit.  This scenario occurs when praying as non- premium .', '<ul><li>To gain faith (and also <a href=\"/index.php/Favor\" title=\"Favor\">favor</a>), a player can <a class=\"mw-redirect\" href=\"/index.php/Praying\" title=\"Praying\">pray</a> at an <a href=\"/index.php/Altar\" title=\"Altar\">altar</a>. In order to do this, however, one must first choose and <a href=\"/index.php/Convert\" title=\"Convert\">convert</a> to a <a href=\"/index.php/Religion\" title=\"Religion\">religion</a>.</li></ul>\n<ul><li>Praying may take place in back-to-back sessions, but a 20-minute cool-down period is needed between prayers in order for each subsequent prayer to count toward further faith skill gain, up to five times per day.</li></ul>\n<ul><li>While additional prayer attempts between these cool-down periods will not raise faith, they will increase the player\'s prayer skill. If faith is not gained from a prayer, the action will not be counted against the five prayer per day limit.  This scenario occurs when praying as non-<a href=\"/index.php/Account_types\" title=\"Account types\">premium</a>.</li></ul>', 1),
(14776, 2898, 'Faith-Based Abilities', 'Faith-Based_Abilities', 'As a player gains faith along their religious journey, they can expect to also discover new, faith-based abilities. The following are some but not all of those reported abilities: - At 10 faith, it becomes possible to sacrifice at altars and to desecrate altars. - At 20 faith, god-specific bonuses become available. ( Vynora -Small Exp. gain / Fo -Healing bonus / Magranon -Fight skill bonus / Libila --Fight skill bonus) - At 30 faith, it becomes possible to become a priest of your chosen god. For additional information on the process of achieving such priesthood at this point, see priest . At 30 faith, it also becomes possible to receive the rewards granted by global spell casts. - At 40 faith, it becomes possible to identify to which god an item was blessed: examining a blessed item will have \"It bears an aura of <god>\" in its description. - At 50 faith, one can become a champion of their chosen god. For more detailed information on championhood, see champion .', '<p>As a player gains faith along their religious journey, they can expect to also discover new, faith-based abilities. The following are some but not all of those reported abilities: \n</p>\n<p>- At 10 faith, it becomes possible to <a href=\"/index.php/Favor#Sacrificing\" title=\"Favor\">sacrifice</a> at altars and to <a href=\"/index.php/Exorcism\" title=\"Exorcism\">desecrate</a> altars.\n</p>\n<p>- At 20 faith, god-specific bonuses become available. (<a href=\"/index.php/Vynora\" title=\"Vynora\">Vynora</a>-Small Exp. gain / <a href=\"/index.php/Fo\" title=\"Fo\">Fo</a>-Healing bonus / <a href=\"/index.php/Magranon\" title=\"Magranon\">Magranon</a>-Fight skill bonus / <a href=\"/index.php/Libila\" title=\"Libila\">Libila</a>--Fight skill bonus)\n</p>\n<p>- At 30 faith, it becomes possible to become a priest of your chosen god. For additional information on the process of achieving such priesthood at this point, see <a href=\"/index.php/Priest\" title=\"Priest\">priest</a>. At 30 faith, it also becomes possible to receive the rewards granted by global spell casts.\n</p>\n<p>- At 40 faith, it becomes possible to identify to which god an item was blessed: examining a blessed item will have \"It bears an aura of &lt;god&gt;\" in its description.\n</p>\n<p>- At 50 faith, one can become a champion of their chosen god. For more detailed information on championhood, see <a href=\"/index.php/Champion\" title=\"Champion\">champion</a>.\n</p>', 2),
(14777, 2898, 'Additional Notes', 'Additional_Notes', 'Without becoming a priest, it is not possible to raise faith above 30. Faith-gain is not affected any differently by sleep bonus or by praying at different altar or tile types; all faith-gain is the same. Faith is not lost when a player dies. Faith gained on sermon is affected by altar rarity. (+1% for rare, +2% for supreme, +3% for fantastic). Faith can be lost when going Unfaithful and performing actions your deity does not approve of. The faith loss occurs even if the action is cancelled before it is completed.', '<ul><li>Without becoming a priest, it is not possible to raise faith above 30.</li></ul>\n<ul><li>Faith-gain is not affected any differently by <a href=\"/index.php/Sleep_bonus\" title=\"Sleep bonus\">sleep bonus</a> or by praying at different altar or tile types; all faith-gain is the same.</li></ul>\n<ul><li>Faith is not lost when a player dies.</li></ul>\n<ul><li>Faith gained on sermon is affected by altar rarity. (+1% for rare, +2% for supreme, +3% for fantastic).</li></ul>\n<ul><li>Faith can be lost when going Unfaithful and performing actions your deity does not approve of. The faith loss occurs even if the action is cancelled before it is completed.</li></ul>', 3),
(14778, 2898, 'Sermons', 'Sermons', 'Holding a sermon is yet one more way in which a player may gain faith-related bonuses. This involves holding a service and preaching to a group of nearby listeners. Procedure To hold a sermon, activate a statuette , right click an altar, and select Preach . A valid listener is a premium player of the same kingdom and of any religion, who is within 4 tiles of the one giving the sermon (being mounted or on foot within this distance does not matter; being embarked on any type of vehicle, cart, however, invalidates the listener). Listeners are allowed to sit. They must also have not gained or lost any alignment within the past 30 minutes. If the player is already at maximum alignment, the alignment change might not be visible, but will still invalidate the listener. Note that listening to a sermon will always result in an alignment change. The minimum number of listeners for faith-gain to take place is 4. At a normal altar the priest successfully holding a sermon gains 0.02 faith per valid listener. Faith bonus for altar rarity is an extra 1% for rare, 2% for supreme, and 3% for fantastic. The priest giving the sermon does not count as a listener. Sermons have a three-hour cooldown period for the sermon-giver, and within this time, the player cannot give another sermon. Within this cool-down period, however, the same preacher can effectively serve as a listener in another priest\'s sermon. Note: if you did not gain at least 0.12 faith from the sermon itself, there were not enough valid listeners present to reset your prayer counter. Listener Benefits If listeners have less than 100.00 alignment, they may gain up to 4 alignment depending on the number of listeners (+ for WL , - for BL ) Note: sermons given by different priests need to be spaced at least 30 minutes apart in order to continue to benefit the listener. Additional Priest Benefits Sermons reset the prayer counter for the preacher if at least 6 valid listeners attended. Sermons also indicate how much praying is required until the chosen god\'s ritual ( Ritual of the sun , Rite of spring , Holy crop , or Rite of death ) is ready to be performed. Holy sites Players can receive a map of a Holy site from giving sermons, but only on those actions that could possibly give faith.', '<p>Holding a sermon is yet one more way in which a player may gain faith-related bonuses. This involves holding a service and preaching to a group of nearby listeners. \n</p>\n<p><br/>\n<b>Procedure</b>\n</p>\n<ul><li>To hold a sermon, activate a <a href=\"/index.php/Statuette\" title=\"Statuette\">statuette</a>, <b>right click</b> an altar, and select <b>Preach</b>.</li>\n<li>A valid listener is a <a class=\"mw-redirect\" href=\"/index.php/Premium\" title=\"Premium\">premium</a> player of the same <a href=\"/index.php/Kingdom\" title=\"Kingdom\">kingdom</a> and of any religion, who is within 4 tiles of the one giving the sermon (being mounted or on foot within this distance does not matter; being embarked on any type of vehicle, cart, however, invalidates the listener). Listeners are allowed to sit. They must also have not gained or lost any <a href=\"/index.php/Alignment\" title=\"Alignment\">alignment</a> within the past 30 minutes. If the player is already at maximum alignment, the alignment change might not be visible, but will still invalidate the listener. Note that listening to a sermon will always result in an alignment change.</li></ul>\n<ul><li>The minimum number of listeners for faith-gain to take place is 4. At a normal altar the priest successfully holding a sermon gains 0.02 faith per valid listener. Faith bonus for altar rarity is an extra 1% for rare, 2% for supreme, and 3% for fantastic.</li></ul>\n<ul><li>The priest giving the sermon does not count as a listener.</li></ul>\n<ul><li>Sermons have a three-hour cooldown period for the sermon-giver, and within this time, the player cannot give another sermon. Within this cool-down period, however, the same preacher can effectively serve as a listener in another priest\'s sermon.</li></ul>\n<ul><li>Note: if you did not gain at least 0.12 faith from the sermon itself, there were not enough valid listeners present to reset your prayer counter.</li></ul>\n<p><br/>\n<b>Listener Benefits</b>\n</p>\n<ul><li>If listeners have less than 100.00 alignment, they may gain up to 4 alignment depending on the number of listeners (+ for <a href=\"/index.php/Whitelighter\" title=\"Whitelighter\">WL</a>, - for <a href=\"/index.php/Blacklighter\" title=\"Blacklighter\">BL</a>)</li></ul>\n<ul><li>Note: sermons given by different priests need to be spaced at least 30 minutes apart in order to continue to benefit the listener.</li></ul>\n<p><br/>\n<b>Additional Priest Benefits</b>\n</p>\n<ul><li>Sermons reset the prayer counter for the preacher if at least 6 valid listeners attended.</li></ul>\n<ul><li>Sermons also indicate how much praying is required until the chosen god\'s ritual (<a href=\"/index.php/Ritual_of_the_sun\" title=\"Ritual of the sun\">Ritual of the sun</a>, <a href=\"/index.php/Rite_of_spring\" title=\"Rite of spring\">Rite of spring</a>, <a href=\"/index.php/Holy_crop\" title=\"Holy crop\">Holy crop</a>, or <a href=\"/index.php/Rite_of_death\" title=\"Rite of death\">Rite of death</a>) is ready to be performed.</li></ul>\n<p><br/>\n<b>Holy sites</b>\n</p>\n<p>Players can receive a map of a <a class=\"mw-redirect\" href=\"/index.php/Holy_site\" title=\"Holy site\">Holy site</a> from giving sermons, but only on those actions that could possibly give faith.\n</p>', 4),
(14779, 2898, 'Faith swap', 'Faith_swap', 'Priests may swap their faith to another god by purchasing a Faith swap token from the Silver shop for 40 Silver coins or the Marks shop for 27000 Marks. This bypasses the 7 day cooldown period that generally applies on PVE servers and immediately changes the priest to another faith. If on a PVP server, changing faiths will be subject to the kingdom change cooldown period . This purchase does NOT give a token, but is used by right-clicking on an altar and selecting \'Swap faith\'.', '<p>Priests may swap their faith to another god by purchasing a Faith swap token from the <a href=\"/index.php/Silver_shop\" title=\"Silver shop\">Silver shop</a> for 40 <a class=\"mw-redirect\" href=\"/index.php/Silver_coin\" title=\"Silver coin\">Silver coins</a> or the <a href=\"/index.php/Loyalty_program\" title=\"Loyalty program\">Marks shop</a> for 27000 Marks. \n</p>\n<ul><li>This bypasses the 7 day cooldown period that generally applies on PVE servers and immediately changes the priest to another faith.\n<ul><li>If on a PVP server, changing faiths will be subject to the <a href=\"/index.php/Convert#Changing_Kingdom\" title=\"Convert\">kingdom change cooldown period</a>.</li></ul></li>\n<li>This purchase does NOT give a token, but is used by right-clicking on an altar and selecting \'Swap faith\'.</li></ul>\n<p><br/>\n</p>', 5),
(14780, 2898, 'Tools', 'Tools', 'Note : The value returned by the tool below is much too high.  Dividing the answer by 2 will give you an approximate estimate. Online Faith gain Calculator', '<p><i>Note : The value returned by the tool below is much too high.  Dividing the answer by 2 will give you an approximate estimate.</i>\n<br/><a class=\"external text\" href=\"http://webdepp.sense-net.at/~toni/wurm/faithcalc.php\" rel=\"nofollow\">Online Faith gain Calculator</a>\n</p>', 6),
(14781, 2898, 'Titles', 'Titles', 'Padre/Norn at 50 faith Devout/Mystic at 70 faith Enlightened at 90 faith Illuminated at 100 faith', '<ul><li>Padre/Norn at 50 faith</li>\n<li>Devout/Mystic at 70 faith</li>\n<li>Enlightened at 90 faith</li>\n<li>Illuminated at 100 faith</li></ul>', 7),
(14782, 3769, 'Description', 'Description', 'Cartography is a skill that allows players to create maps of the land around them. Creating a map is started by creating a survey of the land you would like a map of, then using a completed survey on a cartography table to create the map. You can then copy the map, expand the map, and stamp the map at your cartography table, and prepare them for adding to an Atlas.', '<p>Cartography is a skill that allows players to create maps of the land around them. Creating a map is started by creating a survey of the land you would like a map of, then using a completed survey on a cartography table to create the map. You can then copy the map, expand the map, and stamp the map at your cartography table, and prepare them for adding to an Atlas.\n</p>', 0),
(14783, 3769, 'Required Tools', 'Required_Tools', 'Surveying requires a dioptra , range pole , reed pen , dye or black ink , and a papyrus sheet or paper sheet , with (optionally) an ink pot . Creating maps requires a cartography table , ink pot , ink brush , blank map , and either dye or black ink . Stamping uses at least one stamp and different types of gems , and optionally a stamp box and stamp eraser . Players may also choose to create an atlas to store their maps.', '<p>Surveying requires a <a href=\"/index.php/Dioptra\" title=\"Dioptra\">dioptra</a>, <a href=\"/index.php/Range_pole\" title=\"Range pole\">range pole</a>, <a href=\"/index.php/Reed_pen\" title=\"Reed pen\">reed pen</a>, <a href=\"/index.php/Dye\" title=\"Dye\">dye</a> or <a href=\"/index.php/Black_ink\" title=\"Black ink\">black ink</a>, and a <a href=\"/index.php/Papyrus_sheet\" title=\"Papyrus sheet\">papyrus sheet</a> or <a href=\"/index.php/Paper_sheet\" title=\"Paper sheet\">paper sheet</a>, with (optionally) an <a href=\"/index.php/Ink_pot\" title=\"Ink pot\">ink pot</a>.\n</p>\n<p>Creating maps requires a <a href=\"/index.php/Cartography_table\" title=\"Cartography table\">cartography table</a>, <a href=\"/index.php/Ink_pot\" title=\"Ink pot\">ink pot</a>, <a href=\"/index.php/Ink_brush\" title=\"Ink brush\">ink brush</a>, <a href=\"/index.php/Blank_map\" title=\"Blank map\">blank map</a>, and either <a href=\"/index.php/Dye\" title=\"Dye\">dye</a> or <a href=\"/index.php/Black_ink\" title=\"Black ink\">black ink</a>.\n</p>\n<p>Stamping uses at least one <a href=\"/index.php/Stamp\" title=\"Stamp\">stamp</a> and different types of <a href=\"/index.php/Gems\" title=\"Gems\">gems</a>, and optionally a <a href=\"/index.php/Stamp_box\" title=\"Stamp box\">stamp box</a> and <a href=\"/index.php/Stamp_eraser\" title=\"Stamp eraser\">stamp eraser</a>.\n</p>\n<p>Players may also choose to create an <a href=\"/index.php/Atlas\" title=\"Atlas\">atlas</a> to store their maps.\n</p>', 1),
(14784, 3769, 'Surveying', 'Surveying', 'Surveying involves exploring the area you wish to map, hunting down survey points and collecting data to increase the quality of your survey, which will increase the quality of the map you eventually create. This is main way to gain cartography XP, and is how you improve a map\'s quality. Each successful survey adds to the quality a little bit, depending on the quality of your dioptra and your skill level. You need at least four successful surveys to convert your incomplete survey to a complete survey that can be used to paint a map. To survey: Drop or plant your range pole on the tile you wish to be the center of your survey/map. Activate your blank paper or papyrus sheet, right click the range pole and click Survey Area. If successful, the paper will be converted into an incomplete survey and a new compass interface element represented by a golden spyglass icon will appear. The spyglass leads you to the next survey point, which is represented in the world by a floating ball of light. Head in the direction that spyglass icon points. Hovering over it will tell you roughly how close you are to the survey point. The distances are \"too far\", \"poor\", \"okay\", \"good\" and \"best\". Note: This ball of light and spyglass icon will stay visible for a predetermined length of time, which seems to be based on how close or far you are from the next survey point (e.g. it will stay visible longer if you have farther to travel to get to it). However, if you do not reach the survey point in time, both will fade from view. If the spyglass icon and ball of light disappear, activate your dioptra, right-click your survey, and select \"Find survey location\" and they will reappear. When you get as close to the survey point as you can, turn to face the location of your range pole, activate your dioptra, right-click your survey, and select \"Continue survey\". If successful, your survey will be improved and you\'ll receive a new survey point to go to. Rinse and repeat as needed.', '<p>Surveying involves exploring the area you wish to map, hunting down survey points and collecting data to increase the quality of your survey, which will increase the quality of the map you eventually create. This is main way to gain cartography XP, and is how you improve a map\'s quality. Each successful survey adds to the quality a little bit, depending on the quality of your dioptra and your skill level. You need at least four successful surveys to convert your incomplete survey to a complete survey that can be used to paint a map.\n</p>\n<p>To survey: \n</p>\n<ul><li>Drop or plant your range pole on the tile you wish to be the center of your survey/map.</li>\n<li>Activate your blank paper or papyrus sheet, right click the range pole and click Survey Area. If successful, the paper will be converted into an incomplete survey and a new compass interface element represented by a golden spyglass icon will appear.</li>\n<li>The spyglass leads you to the next survey point, which is represented in the world by a floating ball of light. Head in the direction that spyglass icon points. Hovering over it will tell you roughly how close you are to the survey point. The distances are \"too far\", \"poor\", \"okay\", \"good\" and \"best\".</li>\n<li>Note: This ball of light and spyglass icon will stay visible for a predetermined length of time, which seems to be based on how close or far you are from the next survey point (e.g. it will stay visible longer if you have farther to travel to get to it). However, if you do not reach the survey point in time, both will fade from view. If the spyglass icon and ball of light disappear, activate your dioptra, right-click your survey, and select \"Find survey location\" and they will reappear.</li>\n<li>When you get as close to the survey point as you can, turn to face the location of your range pole, activate your dioptra, right-click your survey, and select \"Continue survey\". If successful, your survey will be improved and you\'ll receive a new survey point to go to.</li>\n<li>Rinse and repeat as needed.</li></ul>', 2),
(14785, 3769, 'Surveying Messages', 'Surveying_Messages', 'The closer you are to the survey point when you continue the survey, the more XP you will gain, and the more information will be added to the survey, leading to a better quality survey. You may see some of the following messages: If you do not face the right location you will get a \"To record any usable data you need to be facing towards the starting location.\" error. If you can\'t remember the direction of the range pole from your current location, activate your dioptra, right-click your survey, and select \"Find starting location\", which will cause a dioptra icon pointing to the range pole to appear in the same compass as the spyglass. If you are too far from the survey point you will get a \"This area is too far from the best location to gather any useful data. You\'ll need to get closer to the required location.\" error. If you are near the area, but not close enough, you will get a \"This spot is far from the best location for the data you need, but you continue to record what little information you can from here anyway.\" message. This indicates you will not get the full XP or data you needed, and your map will gain very little QL. When you are close to the survey point it will give you a \"You feel confident that you\'re in the best location to get the data required.\" message, indicating you are in the right location, and will gain the maximum amount from your survey. You cannot move while surveying, but you can move while finding survey locations and finding starting locations.', '<p>The closer you are to the survey point when you continue the survey, the more XP you will gain, and the more information will be added to the survey, leading to a better quality survey. You may see some of the following messages:\n</p>\n<ul><li>If you do not face the right location you will get a \"To record any usable data you need to be facing towards the starting location.\" error. If you can\'t remember the direction of the range pole from your current location, activate your dioptra, right-click your survey, and select \"Find starting location\", which will cause a dioptra icon pointing to the range pole to appear in the same compass as the spyglass.</li>\n<li>If you are too far from the survey point you will get a \"This area is too far from the best location to gather any useful data. You\'ll need to get closer to the required location.\" error.</li>\n<li>If you are near the area, but not close enough, you will get a \"This spot is far from the best location for the data you need, but you continue to record what little information you can from here anyway.\" message. This indicates you will not get the full XP or data you needed, and your map will gain very little QL.</li>\n<li>When you are close to the survey point it will give you a \"You feel confident that you\'re in the best location to get the data required.\" message, indicating you are in the right location, and will gain the maximum amount from your survey.</li>\n<li>You cannot move while surveying, but you can move while finding survey locations and finding starting locations.</li></ul>', 3),
(14786, 3769, 'Painting Maps', 'Painting_Maps', 'You need: A cartography table . A blank map . An ink pot . Dye or black ink in the ink pot. An ink brush . Right click on the table to Create Map. once completed you will have a Painted Map added to your inventory, spending the Survey. This painted map can be added to the cartography table if you wish to copy it, or expand a map. \nExpanding a map requires 2 or more Painted Maps to be stored inside your Cartography Table. 4 maps are preferred for a small expansion (since the map formed will be a square - using 2 or 3 maps will leave a large gap on the final enlarged map.) Once selected you will get an interface that allows you to move the maps into whatever form you want with the final product being a copy of everything imposed over each other. Stamps are an extension to the cartography system.  They allow you to attach additional data to your maps and atlases which show in game map links to detailed locations, structures, time/date stamps, deeds, and annotations.', '<p>You need:\n</p>\n<ul><li>A <a href=\"/index.php/Cartography_table\" title=\"Cartography table\">cartography table</a>.</li>\n<li>A <a href=\"/index.php/Blank_map\" title=\"Blank map\">blank map</a>.</li>\n<li>An <a href=\"/index.php/Ink_pot\" title=\"Ink pot\">ink pot</a>.</li>\n<li><a href=\"/index.php/Dye\" title=\"Dye\">Dye</a> or <a href=\"/index.php/Black_ink\" title=\"Black ink\">black ink</a> in the ink pot.</li>\n<li>An <a href=\"/index.php/Ink_brush\" title=\"Ink brush\">ink brush</a>.</li></ul>\n<p>Right click on the table to Create Map. once completed you will have a Painted Map added to your inventory, spending the Survey. This painted map can be added to the cartography table if you wish to copy it, or expand a map. \nExpanding a map requires 2 or more Painted Maps to be stored inside your Cartography Table. 4 maps are preferred for a small expansion (since the map formed will be a square - using 2 or 3 maps will leave a large gap on the final enlarged map.) Once selected you will get an interface that allows you to move the maps into whatever form you want with the final product being a copy of everything imposed over each other. \n</p>\n<p><br/>\n<a href=\"/index.php/Stamp\" title=\"Stamp\">Stamps</a> are an extension to the cartography system.  They allow you to attach additional data to your maps and atlases which show in game map links to detailed locations, structures, time/date stamps, deeds, and annotations.  \n</p>', 4),
(14787, 3769, 'Skills & Characteristics', 'Skills_.26_Characteristics', 'Cartography Mind > Mind logic Body > Body stamina', '<ul><li>Cartography</li>\n<li><a href=\"/index.php/Mind\" title=\"Mind\">Mind</a> &gt; <a href=\"/index.php/Mind_logic\" title=\"Mind logic\">Mind logic</a></li>\n<li><a href=\"/index.php/Body\" title=\"Body\">Body</a> &gt; <a href=\"/index.php/Body_stamina\" title=\"Body stamina\">Body stamina</a></li></ul>', 5),
(14788, 3769, 'Titles', 'Titles', 'Mapmaker from Journal, Introduction: Cartography Philatelist from Journal, Introduction: Stamps Surveyor at 50 skill Geographer at 70 skill Cartographer at 90 skill', '<ul><li>Mapmaker from Journal, Introduction: Cartography</li>\n<li>Philatelist from Journal, Introduction: Stamps</li>\n<li>Surveyor at 50 skill</li>\n<li>Geographer at 70 skill</li>\n<li>Cartographer at 90 skill</li></ul>', 6),
(14789, 3769, 'See Also', 'See_Also', 'Atlas Blank map Cartography table Ink brush Ink pot Stamp', '<ul><li><a href=\"/index.php/Atlas\" title=\"Atlas\">Atlas</a></li>\n<li><a href=\"/index.php/Blank_map\" title=\"Blank map\">Blank map</a></li>\n<li><a href=\"/index.php/Cartography_table\" title=\"Cartography table\">Cartography table</a></li>\n<li><a href=\"/index.php/Ink_brush\" title=\"Ink brush\">Ink brush</a></li>\n<li><a href=\"/index.php/Ink_pot\" title=\"Ink pot\">Ink pot</a></li>\n<li><a href=\"/index.php/Stamp\" title=\"Stamp\">Stamp</a></li></ul>', 7),
(14809, 3701, 'Description', 'Description', 'A board for playing chess.', '<p><i>A board for playing chess.</i>\n</p>', 0),
(14810, 3701, 'Notes', 'Notes', 'This board is not only decoration but allows the player to make moves and actually play a game of chess in wurm. The chess pieces are not craftable, but are only found through Treasure hunts . 30 toy making skill is required to start creation. The final piece added determines the wood type; wood colors do show.', '<ul><li>This board is not only decoration but allows the player to make moves and actually play a game of chess in wurm.</li>\n<li>The chess pieces are not craftable, but are only found through <a href=\"/index.php/Treasure_hunt\" title=\"Treasure hunt\">Treasure hunts</a>.</li>\n<li>30 <a href=\"/index.php/Toy_making\" title=\"Toy making\">toy making</a> skill is required to start creation.</li>\n<li>The final piece added determines the wood type; wood colors do show.</li></ul>', 1),
(14811, 3701, 'See Also', 'See_Also', 'Treasure hunt', '<ul><li><a href=\"/index.php/Treasure_hunt\" title=\"Treasure hunt\">Treasure hunt</a></li></ul>', 2),
(14816, 2010, 'Village Description', 'Village_Description', 'Roadside was a size 10 (formerly Size 15) deed that was located along the west road from Newtown, past Aegis , off Public Highway . There is currently a central area for the citizens of the town, a 300 tile farm, a mine with all veins, housing area and a staging area for recruits. The village was formed a few days after the server restart (Gold 2) and disbanded after about two years of being founded. It is 02:00:00 on day of Tears in week 3 of the starfall of Silence in the year of 996. The village of Roadside has just been disbanded by Roadsidemayor. The village disbanded at 06:31 GMT on the 27/04/09. This was due to the rising treat of PvP.', '<p>Roadside was a size 10 (formerly Size 15) deed that was located along the west road from Newtown, past <a class=\"new\" href=\"/index.php?title=Aegis&amp;action=edit&amp;redlink=1\" title=\"Aegis (page does not exist)\">Aegis</a>, off <i>Public Highway</i>. There is currently a central area for the citizens of the town, a 300 tile farm, a mine with all veins, housing area and a staging area for recruits. The village was formed a few days after the server restart (Gold 2) and disbanded after about two years of being founded.\n</p>\n<p>It is 02:00:00 on day of Tears in week 3 of the starfall of Silence in the year of 996. The village of Roadside has just been disbanded by Roadsidemayor. The village disbanded at 06:31 GMT on the 27/04/09. This was due to the rising treat of PvP.\n</p>', 0),
(14817, 2010, 'Village Buildings', 'Village_Buildings', 'The centre of the village was the location for the majority of the village buildings, these included the Farmhouse/Cookery, the Smithy, the Town Hall (where the Trader is located), the Larder (where our farm produce is kept), two Raw Material Warehouses and a Storehouse for general items. Around the outside of the centre there are on-deed houses for citizens as well as the farm and the mine. Just off deed to the west of the village was the Barracks, which houses beds for citizen usage, practice dolls and an archery range, north there is the Farm Annex and a Vineyard. Currently, there was an Arena under construction to the east of the village as well as two dirt towers with Colossi (Romulus & Remus), on the top of each, which are on either side of the Goon Highway and serveed as a \"Gateway to Roadside.\"', '<p>The centre of the village was the location for the majority of the village buildings, these included the Farmhouse/Cookery, the Smithy, the Town Hall (where the Trader is located), the Larder (where our farm produce is kept), two Raw Material Warehouses and a Storehouse for general items. Around the outside of the centre there are on-deed houses for citizens as well as the farm and the mine.\n</p>\n<p>Just off deed to the west of the village was the Barracks, which houses beds for citizen usage, practice dolls and an archery range, north there is the Farm Annex and a Vineyard. Currently, there was an Arena under construction to the east of the village as well as two dirt towers with Colossi (Romulus &amp; Remus), on the top of each, which are on either side of the Goon Highway and serveed as a \"Gateway to Roadside.\"\n</p>', 1),
(14818, 2010, 'Village Politics', 'Village_Politics', 'The Town was under control of the Council and Higher Citizens of Roadside. Higher Citizens were long term members of the village who had contributed widly. The Council voted on all inportant decisions in the village and controled the village as a whole. The Council and Higher Citizens managed citizens and made sure that the citizens of Roadside do not get out of hand. If you want to report any misconduct in Wurm by are members, you can contact Mollsmolyneux, Magic, TheJanitor, Ayesha, Pentaxpilot, Komataguri or Lono.', '<p>The Town was under control of the Council and Higher Citizens of Roadside. Higher Citizens were long term members of the village who had contributed widly. The Council voted on all inportant decisions in the village and controled the village as a whole. The Council and Higher Citizens managed citizens and made sure that the citizens of Roadside do not get out of hand. If you want to report any misconduct in Wurm by are members, you can contact Mollsmolyneux, Magic, TheJanitor, Ayesha, Pentaxpilot, Komataguri or Lono.\n</p>', 2),
(14819, 2010, 'Village Resources', 'Village_Resources', 'The village had access to a wide varity of resources these including Peat, Tar, all vein types and all tree types. The farm grows all the types of food that is avaliable which then are cooked or sold. Roadside never goes hungry.', '<p>The village had access to a wide varity of resources these including Peat, Tar, all vein types and all tree types. The farm grows all the types of food that is avaliable which then are cooked or sold. Roadside never goes hungry.\n</p>', 3),
(14820, 2010, 'Village Members', 'Village_Members', 'Mayor of Roadside Roadsidemayor Council of Roadside Ayesha Komataguri [Mason], [Digger], [Miner], [Trollslayer], [Lumberjack], [Handyman] Lono [Farmer], [Digger], [Handyman], [Miner], [Mason], [Carpenter], [Caterer], [Blacksmith], [Trollslayer] TheJanitor - Founder [Excavator], [Lumberjack], [Handyman], [Trollslayer] Magic - Founder [Mason], [Miner], [Trollslayer], [Handyman], [Digger], [Tanner], [Excavator], [Farmer], [Repairman], [Carpenter], [Blacksmith] Mollsmolyneux - Founder [Carpenter], [Renowned Carpenter], [Handyman], [Trollslayer], [Tanner], [Fine Carpenter] Pentaxpilot Higher Citizens of Roadside Binari [Blacksmith], [Trollslayer] Hobo [Ageless], [Miner], [Blacksmith] Infrared Kopite [Mason], [Trollslayer] Yerbs [Excavator], [Trollslayer],[Carpenter] Yeti Citizens of Roadside Felthanne Kickasskyle [Chainsmith] Radioactive Rosie Zerobite Scorn Darkmessiah Beastenator Temetrix Thehitchhiker Vel Alts Dukenukem Erazortp [Vynoran Priest] [Channeler] Kahuna Likoma Niraga Magest Recruits of Roadside Roadside is not currently recruiting Most of the members shown here have moved on to bigger and wider things in Wurm, if you were in the past a member of Roadside, please place your name in here, as there was many many more.', '<h3><span class=\"mw-headline\" id=\"Mayor_of_Roadside\">Mayor of Roadside</span></h3>\n<ul><li><a href=\"/index.php/Player:Roadsidemayor\" title=\"Player:Roadsidemayor\">Roadsidemayor</a></li></ul>\n<h3><span class=\"mw-headline\" id=\"Council_of_Roadside\">Council of Roadside</span></h3>\n<ul><li><a href=\"/index.php/Player:Ayesha\" title=\"Player:Ayesha\">Ayesha</a></li>\n<li><a href=\"/index.php/Player:Komataguri\" title=\"Player:Komataguri\">Komataguri</a> <b>[Mason], [Digger], [Miner], [Trollslayer], [Lumberjack], [Handyman]</b></li>\n<li><a href=\"/index.php/Player:Lono\" title=\"Player:Lono\">Lono</a> <b>[Farmer], [Digger], [Handyman], [Miner], [Mason], [Carpenter], [Caterer], [Blacksmith], [Trollslayer]</b></li>\n<li><a href=\"/index.php/User:Thejanitor\" title=\"User:Thejanitor\">TheJanitor</a> - Founder <b>[Excavator], [Lumberjack], [Handyman], [Trollslayer]</b></li>\n<li><a href=\"/index.php/Player:Magic\" title=\"Player:Magic\">Magic</a> - Founder <b>[Mason], [Miner], [Trollslayer], [Handyman], [Digger], [Tanner], [Excavator], [Farmer], [Repairman], [Carpenter], [Blacksmith]</b></li>\n<li><a href=\"/index.php/User:Mollsmolyneux\" title=\"User:Mollsmolyneux\">Mollsmolyneux</a> - Founder <b>[Carpenter], [Renowned Carpenter], [Handyman], [Trollslayer], [Tanner], [Fine Carpenter]</b></li>\n<li><a href=\"/index.php/Player:Pentaxpilot\" title=\"Player:Pentaxpilot\">Pentaxpilot</a></li></ul>\n<h3><span class=\"mw-headline\" id=\"Higher_Citizens_of_Roadside\">Higher Citizens of Roadside</span></h3>\n<ul><li><a class=\"mw-redirect\" href=\"/index.php/Player:Binari\" title=\"Player:Binari\">Binari</a> <b>[Blacksmith], [Trollslayer]</b></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Player:Hobo\" title=\"Player:Hobo\">Hobo</a> <b>[Ageless], [Miner], [Blacksmith]</b></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Player:Infrared\" title=\"Player:Infrared\">Infrared</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Player:Kopite\" title=\"Player:Kopite\">Kopite</a> <b>[Mason], [Trollslayer]</b></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Player:Yerbs\" title=\"Player:Yerbs\">Yerbs</a> <b>[Excavator], [Trollslayer],[Carpenter]</b></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Player:Yeti\" title=\"Player:Yeti\">Yeti</a></li></ul>\n<h3><span class=\"mw-headline\" id=\"Citizens_of_Roadside\">Citizens of Roadside</span></h3>\n<ul><li><a href=\"/index.php/Player:Felthanne\" title=\"Player:Felthanne\">Felthanne</a></li>\n<li><a href=\"/index.php/Undefined_player\" title=\"Undefined player\">Kickasskyle</a> <b>[Chainsmith]</b></li>\n<li><a href=\"/index.php/Undefined_player\" title=\"Undefined player\">Radioactive</a></li>\n<li><a href=\"/index.php/Player:Rosie\" title=\"Player:Rosie\">Rosie</a></li>\n<li><a href=\"/index.php/Undefined_player\" title=\"Undefined player\">Zerobite</a></li>\n<li><a href=\"/index.php/Player:Scorn\" title=\"Player:Scorn\">Scorn</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Player:Darkmessiah\" title=\"Player:Darkmessiah\">Darkmessiah</a></li>\n<li><a href=\"/index.php/Player:Beastenator\" title=\"Player:Beastenator\">Beastenator</a></li>\n<li><a href=\"/index.php/Undefined_player\" title=\"Undefined player\">Temetrix</a></li>\n<li><a href=\"/index.php/Undefined_player\" title=\"Undefined player\">Thehitchhiker</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Player:Vel\" title=\"Player:Vel\">Vel</a></li></ul>\n<h3><span class=\"mw-headline\" id=\"Alts\">Alts</span></h3>\n<ul><li><a class=\"mw-redirect\" href=\"/index.php/Player:Dukenukem\" title=\"Player:Dukenukem\">Dukenukem</a></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Player:Erazortp\" title=\"Player:Erazortp\">Erazortp</a> [Vynoran Priest] <b>[Channeler]</b></li>\n<li><a class=\"mw-redirect\" href=\"/index.php/Player:Kahuna\" title=\"Player:Kahuna\">Kahuna</a></li>\n<li><a href=\"/index.php/Undefined_player\" title=\"Undefined player\">Likoma</a></li>\n<li><a href=\"/index.php/Undefined_player\" title=\"Undefined player\">Niraga</a></li>\n<li><a href=\"/index.php/Player:Magest\" title=\"Player:Magest\">Magest</a></li></ul>\n<h3><span class=\"mw-headline\" id=\"Recruits_of_Roadside\">Recruits of Roadside</span></h3>\n<p><i>Roadside is not currently recruiting</i>\n</p>\n<p><b>Most of the members shown here have moved on to bigger and wider things in Wurm, if you were in the past a member of Roadside, please place your name in here, as there was many many more.</b>\n</p>', 4),
(14821, 2010, 'Village Merchants', 'Village_Merchants', 'Trader Megan Private trader Access for village Citizens only Merchant Ben Stocked with farm produce, leather items and fishing rods, as well as other occasional items Located in New Town\'s Merchants row Merchant Lizi Stocked with farm produce On the highway outside Roadside (Merchant Centre) Merchant Lani Stocked with general items On the highway outside Roadside (Merchant Centre)', '<ul><li>Trader Megan</li></ul>\n<dl><dd><ul><li>Private trader</li>\n<li>Access for village Citizens only</li></ul></dd></dl>\n<ul><li>Merchant Ben</li></ul>\n<dl><dd><ul><li>Stocked with farm produce, leather items and fishing rods, as well as other occasional items</li>\n<li>Located in New Town\'s Merchants row</li></ul></dd></dl>\n<ul><li>Merchant Lizi</li></ul>\n<dl><dd><ul><li>Stocked with farm produce</li>\n<li>On the highway outside Roadside (Merchant Centre)</li></ul></dd></dl>\n<ul><li>Merchant Lani</li></ul>\n<dl><dd><ul><li>Stocked with general items</li>\n<li>On the highway outside Roadside (Merchant Centre)</li></ul></dd></dl>', 5),
(14822, 2010, 'Village Colonies', 'Village_Colonies', 'Roadside Harbour Roadside Harbour was a small homestead near the Village of Small Bears , there was an 11 tile pier stretching out into the Great Eastern Ocean. Slightly north is Roadside\'s boatyard where boats are constructed, they are then moored at the pier. The harbour was to have be used to facilitate trips to other parts of the home server or even trips to wild. The harbour was located here as Roadside was far inland. Mayor: Portadmiral Roadside Island Roadside Island is a small Island constructed by Yerbs east of black hills and is used as a port of call for all east business for Roadside - the Island used to be called legacy island.', '<h3><span class=\"mw-headline\" id=\"Roadside_Harbour\">Roadside Harbour</span></h3>\n<p>Roadside Harbour was a small homestead near the <a class=\"mw-redirect\" href=\"/index.php/Village_of_Small_Bears\" title=\"Village of Small Bears\">Village of Small Bears</a>, there was an 11 tile pier stretching out into the Great Eastern Ocean. Slightly north is Roadside\'s boatyard where boats are constructed, they are then moored at the pier. The harbour was to have be used to facilitate trips to other parts of the home server or even trips to wild. The harbour was located here as Roadside was far inland.\n</p>\n<p>Mayor: Portadmiral\n</p>\n<h3><span class=\"mw-headline\" id=\"Roadside_Island\">Roadside Island</span></h3>\n<p>Roadside Island is a small Island constructed by Yerbs east of black hills and is used as a port of call for all east business for Roadside - the Island used to be called legacy island.\n</p>', 6),
(14823, 2010, 'Village External Links', 'Village_External_Links', 'Forums', '<ul><li><a class=\"external text\" href=\"http://roadside.freeforums.org\" rel=\"nofollow\">Forums</a></li></ul>', 7),
(14824, 2020, 'Citizens', 'Citizens', 'Bold = Title Mayor: Eliasthecrimson - [High Tanner] , [Farmer] , [Trollslayer] , [Dragonslayer] , [Digger] , [Alchemist] [Soldier] , [Handyman] , Tailor Elders: Delamore - Founder Glorpax - Weaponsmith Froggeryz - [Renowned Blacksmith] , [Handyman] , [Prime Minester] , [Soldier] , [Butcher] , [Digger] , [Repairman] , [Keeper of Faith] , [Lumberjack] Currently working Villagers Yanko [Trollslayer] Hallin Khalid Jein Merf Mrjdrake Aeris [Prime Minester] , [Handywoman] Aichi Freyasson Mastadjmax (by mayor called Batman due to his mining preferences) Paterso Ryldice Stalk Zhang Rstheking Boo Robbinman Pow - Priest of Vynora, [Trollslayer] Silvertail - Priest of Vynora, (also known as \"Silverfail\" after an impressive display of shattering :] ) (numerous freelancers/freshies not included) Villagers who joined on Freedom already: Elias, Froggeryz, Aeris, Balder, Mastadjmax, Yanko, Jackofblades and Kotten. Hey, people, we\'re still waiting for you ;-)', '<p><b>Bold</b> = Title\n</p>\n<h4><span class=\"mw-headline\" id=\"Mayor:\">Mayor:</span></h4>\n<ul><li><a href=\"/index.php/Player:Eliasthecrimson\" title=\"Player:Eliasthecrimson\">Eliasthecrimson</a> - <b>[High Tanner]</b>, <b>[Farmer]</b>, <b>[Trollslayer]</b>, <b>[Dragonslayer]</b>, <b>[Digger]</b>, <b>[Alchemist]</b> <b>[Soldier]</b>, <b>[Handyman]</b>, Tailor</li></ul>\n<h4><span class=\"mw-headline\" id=\"Elders:\">Elders:</span></h4>\n<ul><li><a class=\"new\" href=\"/index.php?title=Player:Delamore&amp;action=edit&amp;redlink=1\" title=\"Player:Delamore (page does not exist)\">Delamore</a> - Founder</li>\n<li><a href=\"/index.php/Player:Glorpax\" title=\"Player:Glorpax\">Glorpax</a> - Weaponsmith</li>\n<li><a href=\"/index.php/Player:Froggeryz\" title=\"Player:Froggeryz\">Froggeryz</a> - <b>[Renowned Blacksmith]</b>, <b>[Handyman]</b>, <b>[Prime Minester]</b>, <b>[Soldier]</b>, <b>[Butcher]</b>, <b>[Digger]</b>, <b>[Repairman]</b>, <b>[Keeper of Faith]</b>, <b>[Lumberjack]</b></li></ul>\n<h4><span class=\"mw-headline\" id=\"Currently_working_Villagers\">Currently working Villagers</span></h4>\n<ul><li>Yanko <b>[Trollslayer]</b></li>\n<li>Hallin</li>\n<li>Khalid</li>\n<li>Jein</li>\n<li>Merf</li>\n<li>Mrjdrake</li>\n<li>Aeris <b>[Prime Minester]</b>, <b>[Handywoman]</b></li>\n<li>Aichi</li>\n<li>Freyasson</li>\n<li><a href=\"/index.php/User:Mastadjmax\" title=\"User:Mastadjmax\">Mastadjmax</a> <i>(by mayor called Batman due to his mining preferences)</i></li>\n<li>Paterso</li>\n<li>Ryldice</li>\n<li>Stalk</li>\n<li>Zhang</li>\n<li>Rstheking</li>\n<li>Boo</li>\n<li>Robbinman</li></ul>\n<ul><li>Pow - Priest of Vynora, <b>[Trollslayer]</b></li>\n<li>Silvertail - Priest of Vynora, <i>(also known as \"Silverfail\" after an impressive display of shattering :] )</i></li></ul>\n<p>(numerous freelancers/freshies not included)\n</p>\n<p>Villagers who joined on Freedom already: Elias, Froggeryz, Aeris, Balder, Mastadjmax, Yanko, Jackofblades and Kotten. Hey, people, we\'re still waiting for you ;-)\n</p>', 0),
(14825, 2020, 'Pictures', 'Pictures', 'Town centre: Overview at night, with a thunderstorm overhead: Farm complex: \"The mesa of Awesomeness\" - Shot of the highway, with the Silent Hill mesa in background, SH lake to the left: Part of the SH-NT highway, stretching actoss the steppe: Village area map: Roadmap:', '<p>Town centre:\n</p>\n<p><img alt=\"1c510a3c.png\" src=\"http://i121.photobucket.com/albums/o218/ImCrimson/1c510a3c.png\"/>\n</p>\n<p><img alt=\"2f282966.png\" src=\"http://i121.photobucket.com/albums/o218/ImCrimson/2f282966.png\"/>\n</p>\n<p><br/>\nOverview at night, with a thunderstorm overhead:\n</p>\n<p><img alt=\"03d46327.png\" src=\"http://i121.photobucket.com/albums/o218/ImCrimson/03d46327.png\"/>\n</p>\n<p><br/>\nFarm complex:\n</p>\n<p><img alt=\"652d872c.png\" src=\"http://i121.photobucket.com/albums/o218/ImCrimson/652d872c.png\"/>\n</p>\n<p><br/>\n\"The mesa of Awesomeness\" - Shot of the highway, with the Silent Hill mesa in background, SH lake to the left:\n</p>\n<p><img alt=\"25079201.png\" src=\"http://i121.photobucket.com/albums/o218/ImCrimson/25079201.png\"/>\n</p>\n<p><br/>\nPart of the SH-NT highway, stretching actoss the steppe:\n</p>\n<p><img alt=\"868a6417.png\" src=\"http://i121.photobucket.com/albums/o218/ImCrimson/868a6417.png\"/>\n<br/>\n</p>\n<hr/>\n<p><br/>\n</p>\n<p>Village area map:\n</p>\n<p><img alt=\"silenthill.png\" src=\"http://i121.photobucket.com/albums/o218/ImCrimson/silenthill.png\"/>\n</p>\n<p>Roadmap:\n</p>\n<p><img alt=\"SH-NTmap-1.png\" src=\"http://i121.photobucket.com/albums/o218/ImCrimson/SH-NTmap-1.png\"/>\n</p>', 1),
(14826, 2020, 'External Links', 'External_Links', 'Silent Hill Official Website (Work in progress...) Silent Hill Official Forums', '<ul><li><a class=\"external text\" href=\"http://www.geocities.com/elias_the_ace/\" rel=\"nofollow\">Silent Hill Official Website</a> (Work in progress...)</li>\n<li><a class=\"external text\" href=\"http://silenthill.nxserve.net/forum\" rel=\"nofollow\">Silent Hill Official Forums</a></li></ul>', 2);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(14827, 3840, 'Residents', 'Residents', 'Mayors MainCorpse Miner , Trollslayer , Keeper of Faith Tigiot Digger , Excavator , Trollslayer , Keeper of Faith Iaqb Lumberjack , Digger , Excavator , Miner , Goldsmith , Handyman , Trollslayer , Chainsmith Citizens Inactive citizens Any citizen not on for more than 5 days without prior notice may be moved to this category. Morik Keeper of Faith Vorg Digger , Excavator , Keeper of Faith Acesfury Keeper of Faith Cheater Keeper of Faith , Lumberjack Serph Miner , Trollslayer , Destroyer of Faith Tough Miner , Destroyer of Faith Kael Keeper of Faith', '<h3><span class=\"mw-headline\" id=\"Mayors\">Mayors</span></h3>\n<dl><dt><a href=\"/index.php/Player:Maincorpse\" title=\"Player:Maincorpse\">MainCorpse</a></dt>\n<dd><a class=\"mw-redirect\" href=\"/index.php/Miner\" title=\"Miner\">Miner</a>, <a class=\"mw-redirect\" href=\"/index.php/Trollslayer\" title=\"Trollslayer\">Trollslayer</a>, <a class=\"mw-redirect\" href=\"/index.php/Keeper_of_Faith\" title=\"Keeper of Faith\">Keeper of Faith</a></dd>\n<dt><a href=\"/index.php/Player:Tigiot\" title=\"Player:Tigiot\">Tigiot</a></dt>\n<dd><a class=\"mw-redirect\" href=\"/index.php/Digger\" title=\"Digger\">Digger</a>, <a class=\"mw-redirect\" href=\"/index.php/Excavator\" title=\"Excavator\">Excavator</a>, <a class=\"mw-redirect\" href=\"/index.php/Trollslayer\" title=\"Trollslayer\">Trollslayer</a>, <a class=\"mw-redirect\" href=\"/index.php/Keeper_of_Faith\" title=\"Keeper of Faith\">Keeper of Faith</a></dd>\n<dt><a href=\"/index.php/Player:Iaqb\" title=\"Player:Iaqb\">Iaqb</a></dt>\n<dd><a class=\"mw-redirect\" href=\"/index.php/Lumberjack\" title=\"Lumberjack\">Lumberjack</a>, <a class=\"mw-redirect\" href=\"/index.php/Digger\" title=\"Digger\">Digger</a>, <a class=\"mw-redirect\" href=\"/index.php/Excavator\" title=\"Excavator\">Excavator</a>, <a class=\"mw-redirect\" href=\"/index.php/Miner\" title=\"Miner\">Miner</a>, <a class=\"mw-redirect\" href=\"/index.php/Goldsmith\" title=\"Goldsmith\">Goldsmith</a>, <a class=\"mw-redirect\" href=\"/index.php/Handyman\" title=\"Handyman\">Handyman</a>, <a class=\"mw-redirect\" href=\"/index.php/Trollslayer\" title=\"Trollslayer\">Trollslayer</a>, <a class=\"mw-redirect\" href=\"/index.php/Chainsmith\" title=\"Chainsmith\">Chainsmith</a></dd></dl>\n<h3><span class=\"mw-headline\" id=\"Citizens\">Citizens</span></h3>\n<h3><span class=\"mw-headline\" id=\"Inactive_citizens\">Inactive citizens</span></h3>\n<pre>Any citizen not on for more than 5 days without prior notice may be moved to this category.\n</pre>\n<dl><dt><a href=\"/index.php/Player:Morik\" title=\"Player:Morik\">Morik</a></dt>\n<dd><a class=\"mw-redirect\" href=\"/index.php/Keeper_of_Faith\" title=\"Keeper of Faith\">Keeper of Faith</a></dd>\n<dt><a href=\"/index.php/Player:Vorg\" title=\"Player:Vorg\">Vorg</a></dt>\n<dd><a class=\"mw-redirect\" href=\"/index.php/Digger\" title=\"Digger\">Digger</a>, <a class=\"mw-redirect\" href=\"/index.php/Excavator\" title=\"Excavator\">Excavator</a>, <a class=\"mw-redirect\" href=\"/index.php/Keeper_of_Faith\" title=\"Keeper of Faith\">Keeper of Faith</a></dd>\n<dt><a class=\"mw-redirect\" href=\"/index.php/Player:Acesfury\" title=\"Player:Acesfury\">Acesfury</a></dt>\n<dd><a class=\"mw-redirect\" href=\"/index.php/Keeper_of_Faith\" title=\"Keeper of Faith\">Keeper of Faith</a></dd>\n<dt><a href=\"/index.php/Player:Cheater\" title=\"Player:Cheater\">Cheater</a></dt>\n<dd><a class=\"mw-redirect\" href=\"/index.php/Keeper_of_Faith\" title=\"Keeper of Faith\">Keeper of Faith</a>, <a class=\"mw-redirect\" href=\"/index.php/Lumberjack\" title=\"Lumberjack\">Lumberjack</a></dd>\n<dt><a href=\"/index.php/Player:Serph\" title=\"Player:Serph\">Serph</a></dt>\n<dd><a class=\"mw-redirect\" href=\"/index.php/Miner\" title=\"Miner\">Miner</a>, <a class=\"mw-redirect\" href=\"/index.php/Trollslayer\" title=\"Trollslayer\">Trollslayer</a>, <a href=\"/index.php/Destroyer_of_Faith\" title=\"Destroyer of Faith\">Destroyer of Faith</a></dd>\n<dt><a class=\"mw-redirect\" href=\"/index.php/Player:Tough\" title=\"Player:Tough\">Tough</a></dt>\n<dd><a class=\"mw-redirect\" href=\"/index.php/Miner\" title=\"Miner\">Miner</a>, <a href=\"/index.php/Destroyer_of_Faith\" title=\"Destroyer of Faith\">Destroyer of Faith</a></dd>\n<dt><a class=\"mw-redirect\" href=\"/index.php/Player:Kael\" title=\"Player:Kael\">Kael</a></dt>\n<dd><a class=\"mw-redirect\" href=\"/index.php/Keeper_of_Faith\" title=\"Keeper of Faith\">Keeper of Faith</a></dd></dl>', 0),
(14828, 3840, 'Directions', 'Directions', 'From Newtown Take BBM highway west out of NT until you get to the T intersection. Caveat : There are numerous wildlife hazards present along the rest of the trip. \nCasual travelers are advised to take caution. \nSpider assassins are encouraged to do their thing. Head north along the highway towards Garden of the Gods. When you arrive at Garden of the Gods, head northwest past the village and you will intersect the new West Coast highway. Head along this until you come to the switchbacks descending the cliff. Descend the switchbacks carefully until you hit the water. Follow the coastline north until you come to a forested island (which is inhabited by Waffles). Turn right at this island into the bay and proceed straight down the bay from the island towards the huge beach visible in the distance. Ascend the relatively steep beach and proceed ahead in the same direction. After about 1-3 minutes travel you will arrive either at the exposed rock face above Ademar (ideal), the mini-highway heading east out of Ademar (acceptable; Ademar is at the west end of this highway), or the shore of Lake Ademar which is to the west of Ademar (you didn\'t go straight did you). From The Landing Head due east from The Landing to the ocean and hit auto-run for 20-40 minutes and you will end up on Home server Once on Home server look for a pointy shaped mountain (shown below) and aim for that When you hit the coast look for clay ON the coast and when you see that head due east once more. You will come upon Lake Ademar and should see clay on the east coast of that lake, Ademar is right next to that clay.', '<h3><span class=\"mw-headline\" id=\"From_Newtown\">From Newtown</span></h3>\n<ul><li>Take BBM highway <b>west</b> out of NT until you get to the T intersection.</li></ul>\n<pre><b>Caveat</b>: There are numerous wildlife hazards present along the rest of the trip. \nCasual travelers are advised to take caution. \nSpider assassins are encouraged to do their thing.  \n</pre>\n<ul><li>Head <b>north</b> along the highway towards Garden of the Gods.</li>\n<li>When you arrive at Garden of the Gods, head <b>northwest</b> past the village and you will intersect the new West Coast highway.</li>\n<li>Head along this until you come to the switchbacks descending the cliff.</li>\n<li>Descend the switchbacks carefully until you hit the water.</li>\n<li>Follow the coastline north until you come to a forested island (which is inhabited by Waffles).</li>\n<li>Turn right at this island into the bay and proceed straight down the bay from the island towards the huge beach visible in the distance.</li>\n<li>Ascend the relatively steep beach and proceed ahead in the same direction.</li>\n<li>After about 1-3 minutes travel you will arrive either at the exposed rock face above Ademar (ideal), the mini-highway heading <b>east</b> out of Ademar (acceptable; Ademar is at the <b>west</b> end</li></ul>\n<p>of this highway), or the shore of Lake Ademar which is to the <b>west</b> of Ademar (you didn\'t go straight did you).\n</p>\n<h3><span class=\"mw-headline\" id=\"From_The_Landing\">From The Landing</span></h3>\n<ul><li>Head due <b>east</b> from The Landing to the ocean and hit auto-run for 20-40 minutes and you will end up on <a class=\"mw-redirect\" href=\"/index.php/Home_server\" title=\"Home server\">Home server</a></li>\n<li>Once on Home server look for a pointy shaped mountain (shown below) and aim for that</li></ul>\n<p><a class=\"external text\" href=\"http://img145.imageshack.us/img145/407/wurm078kb1.png\" rel=\"nofollow\"><img alt=\"wurm078kb1.png\" src=\"http://img145.imageshack.us/img145/407/wurm078kb1.png\"/></a>\n</p>\n<ul><li>When you hit the coast look for clay <b>ON</b> the coast and when you see that head due <b>east</b> once more.</li>\n<li>You will come upon Lake Ademar and should see clay on the east coast of that lake, Ademar is right next to that clay.</li></ul>', 1),
(14829, 3840, 'Screenshots', 'Screenshots', '', '<p><a class=\"image\" href=\"/index.php/File:Ademar.jpg\" title=\"Ademar.\"><img alt=\"Ademar.\" data-file-height=\"606\" data-file-width=\"800\" decoding=\"async\" height=\"606\" src=\"/images/3/36/Ademar.jpg\" width=\"800\"/></a>\n</p>', 2),
(14830, 3840, 'External links', 'External_links', 'Ademar IRC channel', '<ul><li><a class=\"external text\" href=\"irc://irc.heavenlyplace.net/Ademar\" rel=\"nofollow\">Ademar IRC channel</a></li></ul>', 3),
(14831, 3841, 'Description', 'Description', 'A small token that can be applied to a valid item to apply a different skin to it.', '<p><i>A small token that can be applied to a valid item to apply a different skin to it.</i>\n</p>', 0),
(14832, 3841, 'Notes', 'Notes', 'This was a gift awarded to premium players in April 2020 (part of a Covid bonus). Also referred to as the Ancient large chest skin in the Silver shop (unsure of how the dual names came about). Can be applied to large chest , including GM-spawned, renamed versions. Like all other skins , can only be applied once and is destroyed when removed.', '<ul><li>This was a gift awarded to premium players in April 2020 (part of a Covid bonus).</li>\n<li>Also referred to as the Ancient large chest skin in the <a href=\"/index.php/Silver_shop\" title=\"Silver shop\">Silver shop</a> (unsure of how the dual names came about).</li>\n<li>Can be applied to <a href=\"/index.php/Large_chest\" title=\"Large chest\">large chest</a>, including GM-spawned, renamed versions.</li>\n<li>Like all other <a class=\"mw-redirect\" href=\"/index.php/Skins\" title=\"Skins\">skins</a>, can only be applied once and is destroyed when removed.</li></ul>', 1),
(14837, 3842, 'Description', 'Description', 'The silver shop is accessible from the ingame menu as well as from the Wurm Online website. Some of the items previously only available for marks, can now be purchased with in game silver coins. Silver shop interface Caution: Some shop items, such as Magical ink are not tradeable to other player accounts. See their respective wiki pages.', '<p>The silver shop is accessible from the ingame menu as well as from the Wurm Online website. Some of the items previously only available for marks, can now be purchased with in game silver coins. \n</p>\n<p><br/>\n</p>\n<ul class=\"gallery mw-gallery-traditional\">\n<li class=\"gallerybox\" style=\"width: 155px\"><div style=\"width: 155px\">\n<div class=\"thumb\" style=\"width: 150px;\"><div style=\"margin:33.5px auto;\"><a class=\"image\" href=\"/index.php/File:Silvershop.JPG\"><img alt=\"\" data-file-height=\"685\" data-file-width=\"995\" decoding=\"async\" height=\"83\" src=\"/images/thumb/2/21/Silvershop.JPG/120px-Silvershop.JPG\" srcset=\"/images/thumb/2/21/Silvershop.JPG/180px-Silvershop.JPG 1.5x, /images/thumb/2/21/Silvershop.JPG/240px-Silvershop.JPG 2x\" width=\"120\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>Silver shop interface\n</p>\n</div>\n</div></li>\n</ul>\n<table style=\"background-color:#f8f8f8; -moz-border-radius:10px; width:50%; border:2px solid #e0e0e0; margin-left:0 auto; padding:5px; -moz-outline-style: outset; -moz-outline-radius: 10px; -moz-outline-color: #e0e0e0;\">\n<tbody><tr>\n<td><div class=\"floatleft\"><a class=\"image\" href=\"/index.php/File:Information_icon.png\"><img alt=\"Information icon.png\" data-file-height=\"62\" data-file-width=\"62\" decoding=\"async\" height=\"30\" src=\"/images/thumb/1/1c/Information_icon.png/30px-Information_icon.png\" srcset=\"/images/thumb/1/1c/Information_icon.png/45px-Information_icon.png 1.5x, /images/thumb/1/1c/Information_icon.png/60px-Information_icon.png 2x\" width=\"30\"/></a></div>\n</td>\n<td><b>Caution:</b> Some shop items, such as <a href=\"/index.php/Magical_ink\" title=\"Magical ink\">Magical ink</a> are not tradeable to other player accounts. See their respective wiki pages.\n</td></tr></tbody></table>', 0),
(14838, 3842, 'Items for sale', 'Items_for_sale', 'Item name Cost Additional information Declaration of independence 100s a special document, needed to found a PMK . Only available on servers allowing founding a PMK Extra care for slot 30s A player can care for one extra animal above your animal husbandry skill. Faith swap 40s Allows a priest to swap to another god without losing faith . Farwalker stone 4s Resurrection stone is used for protection in case of death. Farwalker twig 4s Allows you to teleport once to a distant location that has been set on some tree.. Golden mirror 15s Allows a player to change their character\'s appearance and gender once. Large magical chest 40s Provides greatly reduced decay on contents. Holds the same amount and types of items as a normal large chest . Magical ink 15s Allows the player to change the name of an item. The player\'s name will be added to the item as well (Regular Wurm rules about naming apply). Meditation path change 40s Allows a player to change their meditation path without losing the path progress. Resurrection stone 4s Resurrection stone is used for protection in case of death. Rod of transmutation 40s The Rod of transmutation turns a normal cave rock tile into the vein of your choice. Sleep bonus 40s Adds one additional hour to your maximum sleep bonus limit. Small magical chest 20s Provides greatly reduced decay on contents. Holds the same amount and types of items as a normal small chest . Wagoner contract 10s A contract that allows you to place a wagoner . Water spring seeds 8s Seeds you plant on a dirt tile, which produces a small spring creating a water tile for one year. Wooden nameplate 20s The wooden nameplate is used on a cared for animal to give it a custom name. This completely replaces its birth name. Merchant contract 8s A contract that allows you to place a merchant. Shaker orb 4s A shaker orb is used to collapse cave tiles , like the Strongwall spell. Sleep powder 3s Proves 1 hour of sleep bonus Solar Cinder 15s Used for firestarting instead of a steel and flint , to start fires without kindling .', '<table class=\"wikitable sortable\">\n<tbody><tr>\n<th width=\"200\">Item name\n</th>\n<th data-sort-type=\"number\" width=\"10\">Cost\n</th>\n<th>Additional information\n</th></tr>\n<tr>\n<td><a class=\"mw-redirect\" href=\"/index.php/Declaration_of_independence\" title=\"Declaration of independence\">Declaration of independence</a>\n</td>\n<td>100s\n</td>\n<td>a special document, needed to found a <a class=\"mw-redirect\" href=\"/index.php/PMK\" title=\"PMK\">PMK</a>. Only available on servers allowing founding a PMK\n</td></tr>\n<tr>\n<td>Extra <a href=\"/index.php/Animal_husbandry#Caring\" title=\"Animal husbandry\">care for</a> slot\n</td>\n<td>30s\n</td>\n<td>A player can care for one extra animal above your <a href=\"/index.php/Animal_husbandry\" title=\"Animal husbandry\">animal husbandry</a> skill.\n</td></tr>\n<tr>\n<td><a class=\"mw-redirect\" href=\"/index.php/Faith_swap\" title=\"Faith swap\">Faith swap</a>\n</td>\n<td>40s\n</td>\n<td>Allows a <a href=\"/index.php/Priest\" title=\"Priest\">priest</a> to swap to another <a href=\"/index.php/Gods\" title=\"Gods\">god</a> without losing <a href=\"/index.php/Faith\" title=\"Faith\">faith</a>.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Farwalker_stone\" title=\"Farwalker stone\">Farwalker stone</a>\n</td>\n<td>4s\n</td>\n<td>Resurrection stone is used for protection in case of death.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Farwalker_twig\" title=\"Farwalker twig\">Farwalker twig</a>\n</td>\n<td>4s\n</td>\n<td>Allows you to teleport once to a distant location that has been set on some tree..\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Golden_mirror\" title=\"Golden mirror\">Golden mirror</a>\n</td>\n<td>15s\n</td>\n<td>Allows a player to change their character\'s appearance and gender once.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Large_magical_chest\" title=\"Large magical chest\">Large magical chest</a>\n</td>\n<td>40s\n</td>\n<td>Provides greatly reduced decay on contents. Holds the same amount and types of items as a normal <a href=\"/index.php/Large_chest\" title=\"Large chest\">large chest</a>.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Magical_ink\" title=\"Magical ink\">Magical ink</a>\n</td>\n<td>15s\n</td>\n<td>Allows the player to change the name of an item. The player\'s name will be added to the item as well (Regular Wurm rules about naming apply).\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Meditating#Path_Management_and_Advancement\" title=\"Meditating\">Meditation path</a> change\n</td>\n<td>40s\n</td>\n<td>Allows a player to change their meditation path without losing the path progress.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Resurrection_stone\" title=\"Resurrection stone\">Resurrection stone</a>\n</td>\n<td>4s\n</td>\n<td>Resurrection stone is used for protection in case of death.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Rod_of_transmutation\" title=\"Rod of transmutation\">Rod of transmutation</a>\n</td>\n<td>40s\n</td>\n<td>The Rod of transmutation turns a normal cave rock tile into the vein of your choice.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Sleep_bonus\" title=\"Sleep bonus\">Sleep bonus</a>\n</td>\n<td>40s\n</td>\n<td>Adds one additional hour to your maximum sleep bonus limit.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Small_magical_chest\" title=\"Small magical chest\">Small magical chest</a>\n</td>\n<td>20s\n</td>\n<td>Provides greatly reduced decay on contents. Holds the same amount and types of items as a normal <a href=\"/index.php/Small_chest\" title=\"Small chest\">small chest</a>.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Wagoner\" title=\"Wagoner\">Wagoner contract</a>\n</td>\n<td>10s\n</td>\n<td>A contract that allows you to place a <a href=\"/index.php/Wagoner\" title=\"Wagoner\">wagoner</a>.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Water_spring\" title=\"Water spring\">Water spring</a> seeds\n</td>\n<td>8s\n</td>\n<td>Seeds you plant on a dirt tile, which produces a small spring creating a water tile for one year.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Wooden_nameplate\" title=\"Wooden nameplate\">Wooden nameplate</a>\n</td>\n<td>20s\n</td>\n<td>The wooden nameplate is used on a cared for animal to give it a custom name. This completely replaces its birth name.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Personal_merchant#Contract\" title=\"Personal merchant\">Merchant contract</a>\n</td>\n<td>8s\n</td>\n<td>A contract that allows you to place a merchant.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Shaker_orb\" title=\"Shaker orb\">Shaker orb</a>\n</td>\n<td>4s\n</td>\n<td>A shaker orb is used to collapse <a href=\"/index.php/Cave\" title=\"Cave\">cave</a> <a href=\"/index.php/Tile\" title=\"Tile\">tiles</a>, like the <a href=\"/index.php/Strongwall\" title=\"Strongwall\">Strongwall</a> spell.\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Sleep_powder\" title=\"Sleep powder\">Sleep powder</a>\n</td>\n<td>3s\n</td>\n<td>Proves 1 hour of <a href=\"/index.php/Sleep_bonus\" title=\"Sleep bonus\">sleep bonus</a>\n</td></tr>\n<tr>\n<td><a href=\"/index.php/Solar_Cinder\" title=\"Solar Cinder\">Solar Cinder</a>\n</td>\n<td>15s\n</td>\n<td>Used for firestarting instead of a <a href=\"/index.php/Steel_and_flint\" title=\"Steel and flint\">steel and flint</a>, to start fires without <a href=\"/index.php/Kindling\" title=\"Kindling\">kindling</a>.\n</td></tr></tbody></table>', 1),
(14839, 3842, 'Silver shop skins', 'Silver_shop_skins', 'The Silver shop also features monthly skins - some unique to the silver shop and some re-runs of previous Loyalty program skins. \nThe skins unique to the Silver shop are listed below: September 2023 Inviting Wooden Chair (Wooden Chair) Comfortable chair with cushioning made of reed fibre, providing a superior sitting experience. October 2023 Crow Helm (Open Helm) A skin for an open helm. +1 to Intelligence and Curiosity. November 2023 Jousting Helm (Great Helm) A jousting helm, offering an excellent degree of protection from lances and other frightfully pointy objects. November 2023 Uncovered Wagon (Wagon) A fairly large wagon designed to be dragged by four animals. Its iconic cotton fabric over the back has been tidily rolled up and placed in the back. April 2024 Adorned Shovel (Shovel) A beautifully crafted shovel adorned with intricate details, which helps to shape the land with ease. 2024 Ancient Large Chest (Large chest) A very old yet rigid large chest for storing items for decades to come. 2024 Small Round Fountain (Stone Fountain) A small round water feature carved from the finest of marble. 2024 Nymph Fountain (Stone Fountain) A round marble fountain featuring a shapely nymph holding an amphora, its water supply never ending. 2024 Vintage Giftbox Pack (Small chest (x5)) A collection of vintage giftboxes with nice decorations, perfect for packing gifts in the Holiday season. 2024 Wheel Chandelier (Metal chandelier) A repurposed cart wheel made into an impressive chandelier. It has six candles. 2025 Thunder Forge (Forge) A spacious forge that makes shaping any metal item an absolute joy. 2025 Fancy Large Cart (Large Cart) The almost luxurious alternative to the regular large cart, providing a cushioned ride without sacrificing any cargo space.', '<p>The Silver shop also features monthly skins - some unique to the silver shop and some re-runs of previous <a href=\"/index.php/Loyalty_program\" title=\"Loyalty program\">Loyalty program</a> skins. \nThe skins unique to the Silver shop are listed below:\n</p>\n<p><br/>\n</p>\n<div class=\"toccolours mw-collapsible mw-collapsed\" style=\"width:relative; overflow: hidden;\">\n<p><br/>\n</p>\n<ul class=\"gallery mw-gallery-packed\">\n<li class=\"gallerybox\" style=\"width: 240.66666666667px\"><div style=\"width: 240.66666666667px\">\n<div class=\"thumb\" style=\"width: 238.66666666667px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Inviting_chair2.png\"><img alt=\"\" data-file-height=\"154\" data-file-width=\"245\" decoding=\"async\" height=\"150\" src=\"/images/0/08/Inviting_chair2.png\" width=\"239\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>September 2023 <br/><b>Inviting Wooden Chair</b> (Wooden Chair) <br/> <i>Comfortable chair with cushioning made of reed fibre, providing a superior sitting experience.</i>\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 240px\"><div style=\"width: 240px\">\n<div class=\"thumb\" style=\"width: 238px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Crow_Helm.png\"><img alt=\"\" data-file-height=\"209\" data-file-width=\"331\" decoding=\"async\" height=\"150\" src=\"/images/5/55/Crow_Helm.png\" width=\"238\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>October 2023 <br/><b>Crow Helm</b> (Open Helm) <br/> <i>A skin for an open helm. +1 to Intelligence and Curiosity.</i>\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 242.66666666667px\"><div style=\"width: 242.66666666667px\">\n<div class=\"thumb\" style=\"width: 240.66666666667px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Jousting_Helm.png\"><img alt=\"\" data-file-height=\"208\" data-file-width=\"333\" decoding=\"async\" height=\"150\" src=\"/images/1/12/Jousting_Helm.png\" width=\"241\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>November 2023 <br/><b>Jousting Helm</b> (Great Helm) <br/> <i>A jousting helm, offering an excellent degree of protection from lances and other frightfully pointy objects.</i>\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 246px\"><div style=\"width: 246px\">\n<div class=\"thumb\" style=\"width: 244px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Uncovered_Wagon.png\"><img alt=\"\" data-file-height=\"206\" data-file-width=\"335\" decoding=\"async\" height=\"150\" src=\"/images/e/e6/Uncovered_Wagon.png\" width=\"244\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>November 2023 <br/><b>Uncovered Wagon</b> (Wagon) <br/> <i>A fairly large wagon designed to be dragged by four animals. Its iconic cotton fabric over the back has been tidily rolled up and placed in the back.</i>\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 241.33333333333px\"><div style=\"width: 241.33333333333px\">\n<div class=\"thumb\" style=\"width: 239.33333333333px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Adorned_shovel.png\"><img alt=\"\" data-file-height=\"209\" data-file-width=\"333\" decoding=\"async\" height=\"150\" src=\"/images/3/3f/Adorned_shovel.png\" width=\"240\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>April 2024 <br/><b>Adorned Shovel</b> (Shovel) <br/> <i>A beautifully crafted shovel adorned with intricate details, which helps to shape the land with ease.</i>\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 245.33333333333px\"><div style=\"width: 245.33333333333px\">\n<div class=\"thumb\" style=\"width: 243.33333333333px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Ancient_large_chest.png\"><img alt=\"\" data-file-height=\"210\" data-file-width=\"340\" decoding=\"async\" height=\"150\" src=\"/images/6/60/Ancient_large_chest.png\" width=\"244\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>2024 <br/><b>Ancient Large Chest</b> (Large chest) <br/> <i>A very old yet rigid large chest for storing items for decades to come.</i>\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 244.66666666667px\"><div style=\"width: 244.66666666667px\">\n<div class=\"thumb\" style=\"width: 242.66666666667px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Small_round_fountain.png\"><img alt=\"\" data-file-height=\"210\" data-file-width=\"339\" decoding=\"async\" height=\"150\" src=\"/images/8/8a/Small_round_fountain.png\" width=\"243\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>2024 <br/><b>Small Round Fountain</b> (Stone Fountain) <br/> <i>A small round water feature carved from the finest of marble.</i>\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 246.66666666667px\"><div style=\"width: 246.66666666667px\">\n<div class=\"thumb\" style=\"width: 244.66666666667px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Nymph_fountain.png\"><img alt=\"\" data-file-height=\"208\" data-file-width=\"339\" decoding=\"async\" height=\"150\" src=\"/images/e/e3/Nymph_fountain.png\" width=\"245\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>2024 <br/><b>Nymph Fountain</b> (Stone Fountain) <br/> <i>A round marble fountain featuring a shapely nymph holding an amphora, its water supply never ending.</i>\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 250px\"><div style=\"width: 250px\">\n<div class=\"thumb\" style=\"width: 248px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Vintage_gift_box.png\"><img alt=\"\" data-file-height=\"206\" data-file-width=\"340\" decoding=\"async\" height=\"150\" src=\"/images/0/05/Vintage_gift_box.png\" width=\"248\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>2024 <br/><b>Vintage Giftbox Pack</b> (Small chest (x5)) <br/> <i>A collection of vintage giftboxes with nice decorations, perfect for packing gifts in the Holiday season.</i>\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 248px\"><div style=\"width: 248px\">\n<div class=\"thumb\" style=\"width: 246px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Wheel_chandelier.png\"><img alt=\"\" data-file-height=\"207\" data-file-width=\"339\" decoding=\"async\" height=\"150\" src=\"/images/b/bd/Wheel_chandelier.png\" width=\"246\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>2024 <br/><b>Wheel Chandelier</b> (Metal chandelier) <br/> <i>A repurposed cart wheel made into an impressive chandelier. It has six candles.</i>\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 240px\"><div style=\"width: 240px\">\n<div class=\"thumb\" style=\"width: 238px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Thunder_Forge.png\"><img alt=\"\" data-file-height=\"208\" data-file-width=\"330\" decoding=\"async\" height=\"150\" src=\"/images/6/60/Thunder_Forge.png\" width=\"238\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>2025 <br/><b>Thunder Forge</b> (Forge) <br/> <i>A spacious forge that makes shaping any metal item an absolute joy.</i>\n</p>\n</div>\n</div></li>\n<li class=\"gallerybox\" style=\"width: 247.33333333333px\"><div style=\"width: 247.33333333333px\">\n<div class=\"thumb\" style=\"width: 245.33333333333px;\"><div style=\"margin:0px auto;\"><a class=\"image\" href=\"/index.php/File:Fancy_Large_Cart.png\"><img alt=\"\" data-file-height=\"207\" data-file-width=\"338\" decoding=\"async\" height=\"150\" src=\"/images/a/a8/Fancy_Large_Cart.png\" width=\"246\"/></a></div></div>\n<div class=\"gallerytext\">\n<p>2025 <br/><b>Fancy Large Cart</b> (Large Cart) <br/> <i>The almost luxurious alternative to the regular large cart, providing a cushioned ride without sacrificing any cargo space.</i>\n</p>\n</div>\n</div></li>\n</ul>\n</div>\n<p><br/>\n</p>', 2),
(14840, 3842, 'Notes', 'Notes', 'Prices may vary from time to time, as some items can be on sale Some items can be bought with a discount when buying more than one', '<ul><li>Prices may vary from time to time, as some items can be on sale</li>\n<li>Some items can be bought with a discount when buying more than one</li></ul>', 3),
(14841, 3845, 'Notes', 'Notes', 'Files is still located in the install folder', '<ul><li>Files is still located in the install folder</li></ul>', 0),
(14847, 3847, 'Description', 'Description', 'A decorative wooden star-shaped ornament.', '<p><i>A decorative wooden star-shaped ornament.</i>\n</p>', 0),
(14848, 3847, 'Notes', 'Notes', 'A hangable decorative item obtained through Archaeology only during the annual Christmas event, introduced during Christmas 2022. Can be created by combining 3 wooden star fragments. Can be placed flat on tables etc or hung vertically on any wall type except doors and some arched wall types.', '<ul><li>A hangable decorative item obtained through <a href=\"/index.php/Archaeology\" title=\"Archaeology\">Archaeology</a> only during the annual Christmas event, introduced during Christmas 2022.</li>\n<li>Can be created by combining 3 wooden star fragments.</li>\n<li>Can be placed flat on tables etc or hung vertically on any wall type except doors and some arched wall types.</li></ul>', 1),
(14849, 3848, 'Description', 'Description', 'A decorative wooden snowflake-shaped ornament.', '<p><i>A decorative wooden snowflake-shaped ornament.</i>\n</p>', 0),
(14850, 3848, 'Notes', 'Notes', 'A decorative item obtained through Archaeology only during the annual Christmas event, introduced during Christmas 2022. Can be created by combining 3 wooden snowflake fragments. Can be placed flat on tables etc or vertically on any wall type except doors and some arched wall types. Not to be confused with the new (2024) snowflakes that can be hung from ceilings.', '<ul><li>A decorative item obtained through <a href=\"/index.php/Archaeology\" title=\"Archaeology\">Archaeology</a> only during the annual Christmas event, introduced during Christmas 2022.</li>\n<li>Can be created by combining 3 wooden snowflake fragments.</li>\n<li>Can be placed flat on tables etc or vertically on any wall type except doors and some arched wall types.</li>\n<li>Not to be confused with the new (2024) snowflakes that can be hung from ceilings.</li></ul>', 1),
(14851, 3849, 'Description', 'Description', 'Multicolored festive balls twinkling in the candlelight.', '<p><i>Multicolored festive balls twinkling in the candlelight.</i>\n</p>', 0),
(14852, 3849, 'Notes', 'Notes', 'A hangable decorative item obtained through Archaeology only during the annual Christmas event, introduced during Christmas 2022. Can be created by combining 3 ornamental baubles fragments. Can be placed flat on tables etc or hung vertically on any wall type except doors and some arched wall types. Also hangs on fireplace ledges, shelves, etc. Does NOT show dye.', '<ul><li>A hangable decorative item obtained through <a href=\"/index.php/Archaeology\" title=\"Archaeology\">Archaeology</a> only during the annual Christmas event, introduced during Christmas 2022.</li>\n<li>Can be created by combining 3 ornamental baubles fragments.</li>\n<li>Can be placed flat on tables etc or hung vertically on any wall type except doors and some arched wall types. Also hangs on fireplace ledges, shelves, etc.</li>\n<li>Does NOT show dye.</li></ul>', 1),
(14853, 3850, 'Description', 'Description', 'A decorative tree-shaped wooden ornament.', '<p><i>A decorative tree-shaped wooden ornament.</i>\n</p>', 0),
(14854, 3850, 'Notes', 'Notes', 'A hangable decorative item obtained through Archaeology only during the annual Christmas event, introduced during Christmas 2022. Can be created by combining 3 wooden fir tree fragments. Can be placed flat on tables etc or hung vertically on any wall type except doors and some arched wall types.', '<ul><li>A hangable decorative item obtained through <a href=\"/index.php/Archaeology\" title=\"Archaeology\">Archaeology</a> only during the annual Christmas event, introduced during Christmas 2022.</li>\n<li>Can be created by combining 3 wooden fir tree fragments.</li>\n<li>Can be placed flat on tables etc or hung vertically on any wall type except doors and some arched wall types.</li></ul>', 1),
(14855, 3851, 'Description', 'Description', 'Two candy canes. Double the licks and an incredible sugary rush!', '<p><i>Two candy canes. Double the licks and an incredible sugary rush!</i>\n</p>', 0),
(14856, 3851, 'Notes', 'Notes', 'A hangable decorative item obtained through Archaeology only during the annual Christmas event, introduced during Christmas 2022. Can be created by combining 3 candy canes fragments. Can be placed flat on tables etc or hung vertically on any wall type except doors and some arched wall types. Does show wood type.', '<ul><li>A hangable decorative item obtained through <a href=\"/index.php/Archaeology\" title=\"Archaeology\">Archaeology</a> only during the annual Christmas event, introduced during Christmas 2022.</li>\n<li>Can be created by combining 3 candy canes fragments.</li>\n<li>Can be placed flat on tables etc or hung vertically on any wall type except doors and some arched wall types.</li>\n<li>Does show wood type.</li></ul>', 1),
(14857, 3852, 'Description', 'Description', 'May induce visions of bright green, flowery meadows. Small furry creatures can be seen frolicking about. You can easily make out the signature of its maker, \'Easter Bunny\'.', '<p><i>May induce visions of bright green, flowery meadows. Small furry creatures can be seen frolicking about. You can easily make out the signature of its maker, \'Easter Bunny\'.</i>\n</p>', 0),
(14858, 3852, 'Notes', 'Notes', 'Obtained through completing a one step treasure map found in the 2023 Easter event Easter basket .', '<p>Obtained through completing a one step <a class=\"mw-redirect\" href=\"/index.php/Treasure_map\" title=\"Treasure map\">treasure map</a> found in the 2023 Easter event <a href=\"/index.php/Easter_basket\" title=\"Easter basket\">Easter basket</a>.\n</p>', 1),
(14875, 3143, 'Description', 'Description', 'A small village token from investigating the history of a deed. You can barely make out the signature of its maker,  \'.er..ar\'. Ql: 47.25219, Dam: 0.0.', '<p><i>A small village token from investigating the history of a deed. You can barely make out the signature of its maker,  \'.er..ar\'. Ql: 47.25219, Dam: 0.0.</i>\n</p>', 0),
(14876, 3143, 'Notes', 'Notes', 'Small tokens are not craftable, and otherwise, can only be found by successfully locating a cache . They represent the previous settlement and its token found at that cache location. Small tokens do not decay when placed as decorations on deed. While a lump may appear in the improvement column for a small token held in inventory, as of this time, the token will not actually improve once the attempt is made. Duplicate small tokens can exist, either through multiple players discovering one old settlement\'s cache or by one player repeatedly discovering the same cache. The material type of the small token can be composed of any of the game\'s many metal types, and it is yet to be fully known which exact factors determine the type assigned to each small token. The quality level assigned to small tokens is also not fully understood as of this time. The maker\'s signature denotes the past settlement\'s mayor in which the cache was found. A mouse-hover over and examine on the token will provide the past settlement\'s name, last mayor, founder and time since disbanded). Small tokens indicate the direction to their associated deed.', '<ul><li>Small tokens are not craftable, and otherwise, can only be found by successfully locating a <a href=\"/index.php/Archaeology_journal\" title=\"Archaeology journal\">cache</a>. They represent the previous settlement and its token found at that cache location.</li>\n<li>Small tokens do not decay when placed as decorations on deed.</li>\n<li>While a lump may appear in the improvement column for a small token held in inventory, as of this time, the token will not actually improve once the attempt is made.</li>\n<li>Duplicate small tokens can exist, either through multiple players discovering one old settlement\'s cache or by one player repeatedly discovering the same cache.</li>\n<li>The material type of the small token can be composed of any of the game\'s many <a class=\"mw-redirect\" href=\"/index.php/Metal\" title=\"Metal\">metal</a> types, and it is yet to be fully known which exact factors determine the type assigned to each small token. The quality level assigned to small tokens is also not fully understood as of this time.</li>\n<li>The maker\'s signature denotes the past settlement\'s mayor in which the cache was found. A mouse-hover over and examine on the token will provide the past settlement\'s name, last mayor, founder and time since disbanded).</li>\n<li>Small tokens indicate the direction to their associated deed.</li></ul>', 1),
(14877, 3143, 'Images', 'Images', 'Here is the size difference between a settlement token and cache found token', '<div class=\"thumb tleft\"><div class=\"thumbinner\" style=\"width:302px;\"><a class=\"image\" href=\"/index.php/File:Small_token_size.png\"><img alt=\"\" class=\"thumbimage\" data-file-height=\"590\" data-file-width=\"515\" decoding=\"async\" height=\"344\" src=\"/images/thumb/0/0e/Small_token_size.png/300px-Small_token_size.png\" srcset=\"/images/thumb/0/0e/Small_token_size.png/450px-Small_token_size.png 1.5x, /images/0/0e/Small_token_size.png 2x\" width=\"300\"/></a> <div class=\"thumbcaption\"><div class=\"magnify\"><a class=\"internal\" href=\"/index.php/File:Small_token_size.png\" title=\"Enlarge\"></a></div>Here is the size difference between a settlement token and cache found token</div></div></div>', 2),
(14878, 3143, 'See Also', 'See_Also', 'Archaeology journal (Info on Caches Found Here) Archaeology Restoration', '<ul><li><a href=\"/index.php/Archaeology_journal\" title=\"Archaeology journal\">Archaeology journal</a> (Info on Caches Found Here)</li>\n<li><a href=\"/index.php/Archaeology\" title=\"Archaeology\">Archaeology</a></li>\n<li><a href=\"/index.php/Restoration\" title=\"Restoration\">Restoration</a></li></ul>', 3),
(14879, 3820, 'Description', 'Description', 'A tiny yule goat. +1 to festive atmosphere within 4 tiles.', '<p><i>A tiny yule goat. +1 to festive atmosphere within 4 tiles.</i>\n</p>', 0),
(14880, 3820, 'Notes', 'Notes', 'A figurine obtained through Archaeology only during the annual Christmas/Wurmmas holiday event. Can be created by combining 5 yule goat figurine fragments. The yule goat figurine is used as a decoration and does not take damage on deed. The finished material is \"straw\" and will burn if placed on an oven or forge . This tiny figurine is not to be confused with the larger Yule goat .', '<ul><li>A figurine obtained through <a href=\"/index.php/Archaeology\" title=\"Archaeology\">Archaeology</a> only during the annual Christmas/Wurmmas holiday event.</li>\n<li>Can be created by combining 5 yule goat figurine fragments.</li>\n<li>The yule goat figurine is used as a decoration and does not take damage on deed.</li>\n<li>The finished material is \"straw\" and will burn if placed on an <a href=\"/index.php/Oven\" title=\"Oven\">oven</a> or <a href=\"/index.php/Forge\" title=\"Forge\">forge</a>.</li>\n<li>This tiny figurine is not to be confused with the larger <a href=\"/index.php/Yule_goat\" title=\"Yule goat\">Yule goat</a>.</li></ul>', 1),
(14881, 3819, 'Description', 'Description', 'A tiny yule reindeer. +1 to festive atmosphere within 4 tiles.', '<p><i>A tiny yule reindeer. +1 to festive atmosphere within 4 tiles.</i>\n</p>', 0),
(14882, 3819, 'Notes', 'Notes', 'A figurine obtained through Archaeology only during the annual Christmas/Wurmmas holiday event. Can be created by combining 5 yule reindeer figurine fragments. The yule reindeer figurine is used as a decoration and does not take damage on deed. The finished material is \"straw\" and will burn if placed on an oven or forge . This tiny figurine is not to be confused with the larger Yule reindeer .', '<ul><li>A figurine obtained through <a href=\"/index.php/Archaeology\" title=\"Archaeology\">Archaeology</a> only during the annual Christmas/Wurmmas holiday event.</li>\n<li>Can be created by combining 5 yule reindeer figurine fragments.</li>\n<li>The yule reindeer figurine is used as a decoration and does not take damage on deed.</li>\n<li>The finished material is \"straw\" and will burn if placed on an <a href=\"/index.php/Oven\" title=\"Oven\">oven</a> or <a href=\"/index.php/Forge\" title=\"Forge\">forge</a>.</li>\n<li>This tiny figurine is not to be confused with the larger <a href=\"/index.php/Yule_reindeer\" title=\"Yule reindeer\">Yule reindeer</a>.</li></ul>', 1),
(14883, 3860, 'Description', 'Description', 'The golden statue of challenges.', '<p><i>The golden statue of challenges.</i>\n</p>', 0),
(14884, 3860, 'Notes', 'Notes', 'Originally gifted to the winners of a temporary PvP server called Storm, Players now have a chance to receive one by purchasing a Gift pack at the token with Marks. Can be carried in inventory and placed like other decorations . Available in gold, silver, bronze and marble.', '<ul><li>Originally gifted to the winners of a temporary PvP server called Storm, Players now have a chance to receive one by purchasing a <a href=\"/index.php/Gift_pack\" title=\"Gift pack\">Gift pack</a> at the token with Marks.</li>\n<li>Can be carried in inventory and placed like other <a class=\"mw-redirect\" href=\"/index.php/Decoration\" title=\"Decoration\">decorations</a>.</li>\n<li>Available in gold, silver, bronze and marble.</li></ul>', 1),
(14893, 3862, 'About', 'About', 'Challenge001, is a Challenge server, also named Storm. It was opened on December 10, 2014. In order to play in that server you would have had to made a new account. This server is no longer active, as it was a time-limited challenge (hence the name). Server status Server statistics See server graphs for the statistics of all servers.', '<p>Challenge001, is a <a class=\"mw-redirect\" href=\"/index.php/Challenge\" title=\"Challenge\">Challenge</a> server, also named Storm. It was opened on December 10, 2014.\n</p>\n<p>In order to play in that server you would have had to made a new account.\n</p>\n<p>This server is no longer active, as it was a time-limited challenge (hence the name).\n</p>\n<p><br/>\n</p>\n<ul><li><a class=\"external text\" href=\"http://c001.game.wurmonline.com/battles/stats.html\" rel=\"nofollow\">Server status</a></li>\n<li><a class=\"external text\" href=\"http://c001.game.wurmonline.com/mrtg/\" rel=\"nofollow\">Server statistics</a></li>\n<li>See <a href=\"/index.php/Server_graphs\" title=\"Server graphs\">server graphs</a> for the statistics of all servers.<i></i></li></ul>', 0),
(14894, 3863, 'About', 'About', 'Molr001 was the Mol-Rehan home server. It was shut down July 15th 2009.', '<p>Molr001 was the Mol-Rehan home server. It was shut down July 15th 2009.\n</p>', 0),
(14895, 3865, 'The Wurm Calendar', 'The_Wurm_Calendar', 'The Wurm year lasts 42 real days The Wurm year is divided into 12 equal periods call Starfalls lasting 3.5 real days each. Each Starfall is divided into 4 equal Wurm weeks lasting 21 real hours each. Each Wurm week is divided into 7 days lasting 3 real hours each. The days of the week are each named and have the following sequence: Day of the Ant Day of Luck Day of the Wurm Day of Wrath Day of Tears Day of Sleep Day of Awakening', '<ul><li>The Wurm year lasts 42 real days</li>\n<li>The Wurm year is divided into 12 equal periods call <b>Starfalls</b> lasting 3.5 real days each.</li>\n<li>Each Starfall is divided into 4 equal Wurm weeks lasting 21 real hours each.</li>\n<li>Each Wurm week is divided into 7 days lasting 3 real hours each.</li>\n<li>The days of the week are each named and have the following sequence:</li></ul>\n<ol><li>Day of the Ant</li>\n<li>Day of Luck</li>\n<li>Day of the Wurm</li>\n<li>Day of Wrath</li>\n<li>Day of Tears</li>\n<li>Day of Sleep</li>\n<li>Day of Awakening</li></ol>', 0),
(14896, 3865, 'Telling time in Wurm', 'Telling_time_in_Wurm', 'To be able to determine what, if anything, may be available to harvest, you first must be able to determine what time of year it is in Wurm. By typing /time into a chat window Wurm will respond with the current date and time in Wurm. The output in the Event window will look something like this: It is 17:30:50 on the day of Awakening in week 2 of the starfall of the Raven in the year of 1102.', '<p>To be able to determine what, if anything, may be available to harvest, you first must be able to determine what time of year it is in Wurm.<br/>\nBy typing <b>/time</b> into a chat window Wurm will respond with the current date and time in Wurm. The output in the Event window will look something like this:<br/>\n</p>\n<p><span style=\"color: #fff; font-family: Sans-Serif; font-size: 0.85em; border: 1px rgb(0, 0, 0) solid; background: rgb(75, 62, 48); line-height: 1.3em; -webkit-border-radius: 5px; -moz-border-radius: 5px; border-radius: 5px; -moz-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); -webkit-box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); box-shadow: 2px 2px 5px 1px rgb(101, 101, 101); padding: 2px 10px 2px 10px; display: inline-block;\"> It is 17:30:50 on the day of Awakening in week 2 of the starfall of the Raven in the year of 1102. </span>\n</p>', 1);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(14897, 3865, 'The Harvest calendar', 'The_Harvest_calendar', 'The information provided by the /time chat command gives you all you need to determine what time of year it is and what may be available for harvest. Look up the Starfall and the Week indicated in the table below. The length of time a harvest is available is usually longer than the Wurm week indicated. It is not unusual to see harvests become available several Wurm days before the Wurm week indicated and last several days after the indicated week has passed. Starfall Week 1 Week 2 Week 3 Week 4 Diamonds Pinenut Saw Digging Leaf Oleander Camellia Bear Lavender Rose Maple Snake Acorns White Shark Cherries Fire Olives Blueberries Hops Oranges Raven Grapes Lemons Apples Chestnuts Dancer Raspberries Walnuts Hazelnuts Lingonberries Omen Silence', '<ul><li>The information provided by the <b>/time</b> chat command gives you all you need to determine what time of year it is and what may be available for harvest.</li>\n<li>Look up the Starfall and the Week indicated in the table below.</li>\n<li>The length of time a harvest is available is usually longer than the Wurm week indicated. It is not unusual to see harvests become available several Wurm days before the Wurm week indicated and last several days after the indicated week has passed.</li></ul>\n<table class=\"wikitable\">\n<tbody><tr>\n<th>Starfall</th>\n<th>Week 1</th>\n<th>Week 2</th>\n<th>Week 3</th>\n<th>Week 4\n</th></tr>\n<tr>\n<td>Diamonds</td>\n<td><a href=\"/index.php/Pinenut\" title=\"Pinenut\">Pinenut</a></td>\n<td></td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td>Saw</td>\n<td></td>\n<td></td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td>Digging</td>\n<td></td>\n<td></td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td>Leaf</td>\n<td></td>\n<td><a href=\"/index.php/Oleander\" title=\"Oleander\">Oleander</a></td>\n<td></td>\n<td><a class=\"mw-redirect\" href=\"/index.php/Camellia\" title=\"Camellia\">Camellia</a>\n</td></tr>\n<tr>\n<td>Bear</td>\n<td></td>\n<td><a href=\"/index.php/Lavender_flowers\" title=\"Lavender flowers\">Lavender</a></td>\n<td><a href=\"/index.php/Rose_flowers\" title=\"Rose flowers\">Rose</a></td>\n<td><a class=\"mw-redirect\" href=\"/index.php/Maple\" title=\"Maple\">Maple</a>\n</td></tr>\n<tr>\n<td>Snake</td>\n<td></td>\n<td><a href=\"/index.php/Acorns\" title=\"Acorns\">Acorns</a></td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td>White Shark</td>\n<td><a href=\"/index.php/Cherry\" title=\"Cherry\">Cherries</a></td>\n<td></td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td>Fire</td>\n<td><a href=\"/index.php/Olive\" title=\"Olive\">Olives</a></td>\n<td><a href=\"/index.php/Blueberries\" title=\"Blueberries\">Blueberries</a></td>\n<td><a href=\"/index.php/Hops\" title=\"Hops\">Hops</a></td>\n<td><a href=\"/index.php/Orange\" title=\"Orange\">Oranges</a>\n</td></tr>\n<tr>\n<td>Raven</td>\n<td><a href=\"/index.php/Grapes\" title=\"Grapes\">Grapes</a></td>\n<td><a class=\"mw-redirect\" href=\"/index.php/Lemons\" title=\"Lemons\">Lemons</a></td>\n<td><a class=\"mw-redirect\" href=\"/index.php/Apples\" title=\"Apples\">Apples</a></td>\n<td><a href=\"/index.php/Chestnuts\" title=\"Chestnuts\">Chestnuts</a>\n</td></tr>\n<tr>\n<td>Dancer</td>\n<td><a href=\"/index.php/Raspberries\" title=\"Raspberries\">Raspberries</a></td>\n<td><a href=\"/index.php/Walnuts\" title=\"Walnuts\">Walnuts</a></td>\n<td><a href=\"/index.php/Hazelnuts\" title=\"Hazelnuts\">Hazelnuts</a></td>\n<td><a href=\"/index.php/Lingonberries\" title=\"Lingonberries\">Lingonberries</a>\n</td></tr>\n<tr>\n<td>Omen</td>\n<td></td>\n<td></td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td>Silence</td>\n<td></td>\n<td></td>\n<td></td>\n<td>\n</td></tr>\n</tbody></table>', 2),
(14901, 3867, 'Description', 'Description', 'It\'s said that this particular gnome\'s thirst for ale and good times is matched only by its love for practical jokes and pranks. Ql: 80.0, Dam: 0.0. The Drunkard garden gnome is available in the Silver shop for 10 silver coins, or as part of a \"Merry Gnomes pack\" for 20 silver coins, which also includes the Axeman garden gnome and the Miner garden gnome . Upon purchase, your signature will be added to the gnome\'s display line upon examining. Appears as \"drunkard gnome\" in your inventory.', '<p><i>It\'s said that this particular gnome\'s thirst for ale and good times is matched only by its love for practical jokes and pranks. Ql: 80.0, Dam: 0.0.</i>\n</p>\n<p>The Drunkard garden gnome is available in the <a href=\"/index.php/Silver_shop\" title=\"Silver shop\">Silver shop</a> for 10 silver coins, or as part of a \"Merry Gnomes pack\" for 20 silver coins, which also includes the <a href=\"/index.php/Axeman_garden_gnome\" title=\"Axeman garden gnome\">Axeman garden gnome</a> and the <a href=\"/index.php/Miner_garden_gnome\" title=\"Miner garden gnome\">Miner garden gnome</a>. Upon purchase, your signature will be added to the gnome\'s display line upon examining. Appears as \"drunkard gnome\" in your inventory.\n</p>', 0),
(14902, 3867, 'Usage', 'Usage', 'Clay gnomes can be decoratively placed on-deed without decaying.', '<ul><li>Clay gnomes can be decoratively placed on-deed without decaying.</li></ul>', 1),
(14903, 3868, 'Description', 'Description', 'This industrious little gnome is happiest deep underground, mining away for precious ores and gems. Ql: 80.0, Dam: 0.0. The Miner garden gnome is available in the Silver shop for 10 silver coins, or as part of a \"Merry Gnomes pack\" for 20 silver coins, which also includes the Axeman garden gnome and the Drunkard garden gnome . Upon purchase, your signature will be added to the gnome\'s display line upon examining. Appears as \"mining gnome\" in your inventory.', '<p><i>This industrious little gnome is happiest deep underground, mining away for precious ores and gems. Ql: 80.0, Dam: 0.0.</i>\n</p>\n<p>The Miner garden gnome is available in the <a href=\"/index.php/Silver_shop\" title=\"Silver shop\">Silver shop</a> for 10 silver coins, or as part of a \"Merry Gnomes pack\" for 20 silver coins, which also includes the <a href=\"/index.php/Axeman_garden_gnome\" title=\"Axeman garden gnome\">Axeman garden gnome</a> and the <a href=\"/index.php/Drunkard_garden_gnome\" title=\"Drunkard garden gnome\">Drunkard garden gnome</a>. Upon purchase, your signature will be added to the gnome\'s display line upon examining. Appears as \"mining gnome\" in your inventory. \n</p>', 0),
(14904, 3868, 'Usage', 'Usage', 'Clay gnomes can be decoratively placed on-deed without decaying.', '<ul><li>Clay gnomes can be decoratively placed on-deed without decaying.</li></ul>', 1),
(14905, 3869, 'Description', 'Description', 'With its trusty axe and fierce focus, this little gnome can take down foes many times its size. Ql: 80.0, Dam: 0.0. The Axeman garden gnome is available in the Silver shop for 10 silver coins, or as part of a \"Merry Gnomes pack\" for 20 silver coins, which also includes the Miner garden gnome and the Drunkard garden gnome . Upon purchase, your signature will be added to the gnome\'s display line upon examining. Appears as \"axeman gnome\" in your inventory.', '<p><i>With its trusty axe and fierce focus, this little gnome can take down foes many times its size. Ql: 80.0, Dam: 0.0.</i>\n</p>\n<p>The Axeman garden gnome is available in the <a href=\"/index.php/Silver_shop\" title=\"Silver shop\">Silver shop</a> for 10 silver coins, or as part of a \"Merry Gnomes pack\" for 20 silver coins, which also includes the <a href=\"/index.php/Miner_garden_gnome\" title=\"Miner garden gnome\">Miner garden gnome</a> and the <a href=\"/index.php/Drunkard_garden_gnome\" title=\"Drunkard garden gnome\">Drunkard garden gnome</a>. Upon purchase, your signature will be added to the gnome\'s display line upon examining. Appears as \"axeman gnome\" in your inventory.\n</p>', 0),
(14906, 3869, 'Usage', 'Usage', 'Clay gnomes can be decoratively placed on-deed without decaying.', '<ul><li>Clay gnomes can be decoratively placed on-deed without decaying.</li></ul>', 1),
(14912, 3871, 'Wurmpedia task list', 'Wurmpedia_task_list', 'Number Status Date Task Priority Type Task Manager 1 In Progress 18-Jan-2021 https://forum.wurmonline.com/index.php?/topic/182058-quality-pagerule-of-70/ Something from 2011? Has this not all been changed since then? Waiting on info from Darklords. <--He\'s working on it. Will get back. No ETA. Normal Research 2 New 23-Jan-2021 Cast power makes no sense here: Lurker in the dark Also is LITD different that the other 2 spells as it\'s not listed as being dependent on server size? Normal Research 4 New 23-Jan-2021 https://forum.wurmonline.com/index.php?/topic/182286-priests-and-bashdestroy/ Normal Research 5 New 23-Jan-2021 Journal Someone updated that the \"Improve weapon to 50ql\" doesn\'t need to be weaponsmithing. Maybe we can add examples? Normal Research 6 New 23-Jan-2021  - Revisited 08-Jan-2024 Project time? Favor page needs to be updated. Linking updated. https://forum.wurmonline.com/index.php?/topic/177781-sacrifice-favor-value/ High Project Oluffus 8 New 29-Jan-2021 Idea in its very beginnings: Okay, thoughts: a page/pages with the total breakdown of settlement management windows with pics and detailed instructions. A serious how to. Normal Project 9 In Progress 02-Feb-2021 Check all pages linked to the front page of the wiki for completeness, style issues, and accuracy. Combat/Fighting updated, needs some love from someone who knows more than I do. ASAP Project 10 New 05-Feb-2021 Move definitely out of date guides into historical? Leave redirect. Maybe move \"Official WA guides\" into a new namespace? Normal Project 11 New 09-Feb-2021 Bowyery page has grind info. A guide would be better. Normal Project 12 New 17-Feb-2021 What tiles do animals spawn on? What has changed? Normal Research 13 New 11-Mar-2021 Guide for fighting/combat update? Special move Normal New Article 14 Ongoing 12-Mar-2021 Add breadcrumbs everywhere (Example: Main / Game mechanics / Wurmpedia tasklist ) Low Cleanup 15 Ongoing 12-Mar-2021 Check all items for dye amounts/dye-ability/color runing, add to itembox (just as you go, pls) Low Cleanup 16 In Progress 29-Mar-2021 Condense and redo bridge pages. One per type? Rope and wood done Normal Cleanup 18 New 14-Jul-2022 - Revisited 21-Jan-2024 Container Make sure info is correct, add missing info, maybe split into smaller tables (discuss)? High Cleanup Kyoko 19 New 19-Jul-2022 Ship We need to just totally rewrite this for clarity and updates. ASAP Update 20 New 13-Oct-2022 Suggestion for the Hay page improvements: There should be information about hay making working on grass tiles able for farming (<=9 slope), on steeper slope mixed grass possible yield and time to harvest depending on skill, tool ql, tool enchantment/runes hay drying best and losses least during summer, worst in winter Normal Cleanup 21 New 25-Feb-2023 Add wagonner messages to Wagonner page (success, failure, etc) Normal Update 22 New 07-May-2023 Go over Interface page, make sure it\'s up to date. Normal Update 26 Ongoing Verify that pictures are uploaded to the wiki, and added to the appropriate page. Normal Ongoing Kyoko 27 Ongoing Copy Release notes to wiki page Normal Ongoing Kyoko 28 New 20-Sep-2023 Work on rift changes - Shoulder pads need updates on improving and skills Normal Update Notes When adding new tasks, assign the next number. When tasks are completed and moved to table below - do not renumber tasks. And of course: Keep on Wurming', '<table border=\"1\" cellpadding=\"3\" cellspacing=\"0\" class=\"wikitable sortable\">\n<tbody><tr>\n<th>Number</th>\n<th>Status</th>\n<th>Date</th>\n<th>Task</th>\n<th>Priority</th>\n<th>Type</th>\n<th>Task Manager\n</th></tr>\n<tr>\n<td>1</td>\n<td>In Progress</td>\n<td>18-Jan-2021</td>\n<td><a class=\"external free\" href=\"https://forum.wurmonline.com/index.php?/topic/182058-quality-pagerule-of-70/\" rel=\"nofollow\">https://forum.wurmonline.com/index.php?/topic/182058-quality-pagerule-of-70/</a> <br/>Something from 2011? Has this not all been changed since then? Waiting on info from Darklords. &lt;--He\'s working on it. Will get back. No ETA.</td>\n<td>Normal</td>\n<td>Research</td>\n<td>\n</td></tr>\n<tr>\n<td>2</td>\n<td>New</td>\n<td>23-Jan-2021</td>\n<td>Cast power makes no sense here: <a href=\"/index.php/Lurker_in_the_dark\" title=\"Lurker in the dark\">Lurker in the dark</a> <br/>Also is LITD different that the other 2 spells as it\'s not listed as being dependent on server size?</td>\n<td>Normal</td>\n<td>Research</td>\n<td>\n<p><br/>\n</p>\n</td></tr>\n<tr>\n<td>4</td>\n<td>New</td>\n<td>23-Jan-2021</td>\n<td><a class=\"external free\" href=\"https://forum.wurmonline.com/index.php?/topic/182286-priests-and-bashdestroy/\" rel=\"nofollow\">https://forum.wurmonline.com/index.php?/topic/182286-priests-and-bashdestroy/</a></td>\n<td>Normal</td>\n<td>Research</td>\n<td>\n</td></tr>\n<tr>\n<td>5</td>\n<td>New</td>\n<td>23-Jan-2021</td>\n<td><a href=\"/index.php/Journal\" title=\"Journal\">Journal</a> Someone updated that the \"Improve weapon to 50ql\" doesn\'t need to be weaponsmithing. Maybe we can add examples?</td>\n<td>Normal</td>\n<td>Research</td>\n<td>\n</td></tr>\n<tr>\n<td>6</td>\n<td>New</td>\n<td>23-Jan-2021  - Revisited 08-Jan-2024</td>\n<td>Project time? Favor page needs to be updated. Linking updated.  <a class=\"external free\" href=\"https://forum.wurmonline.com/index.php?/topic/177781-sacrifice-favor-value/\" rel=\"nofollow\">https://forum.wurmonline.com/index.php?/topic/177781-sacrifice-favor-value/</a></td>\n<td>High</td>\n<td>Project</td>\n<td>Oluffus\n</td></tr>\n<tr>\n<td>8</td>\n<td>New</td>\n<td>29-Jan-2021</td>\n<td>Idea in its very beginnings: Okay, thoughts: a page/pages with the total breakdown of settlement management windows with pics and detailed instructions. A serious how to.</td>\n<td>Normal</td>\n<td>Project</td>\n<td>\n</td></tr>\n<tr>\n<td>9</td>\n<td>In Progress</td>\n<td>02-Feb-2021</td>\n<td>Check all pages linked to the front page of the wiki for completeness, style issues, and accuracy. Combat/Fighting updated, needs some love from someone who knows more than I do.</td>\n<td>ASAP</td>\n<td>Project</td>\n<td>\n</td></tr>\n<tr>\n<td>10</td>\n<td>New</td>\n<td>05-Feb-2021</td>\n<td>Move definitely out of date guides into historical? Leave redirect. Maybe move \"Official WA guides\" into a new namespace?</td>\n<td>Normal</td>\n<td>Project</td>\n<td>\n</td></tr>\n<tr>\n<td>11</td>\n<td>New</td>\n<td>09-Feb-2021</td>\n<td>Bowyery page has grind info. A guide would be better.</td>\n<td>Normal</td>\n<td>Project</td>\n<td>\n</td></tr>\n<tr>\n<td>12</td>\n<td>New</td>\n<td>17-Feb-2021</td>\n<td>What tiles do animals spawn on? What has changed?</td>\n<td>Normal</td>\n<td>Research</td>\n<td>\n</td></tr>\n<tr>\n<td>13</td>\n<td>New</td>\n<td>11-Mar-2021</td>\n<td>Guide for fighting/combat update? <a href=\"/index.php/Special_move\" title=\"Special move\">Special move</a></td>\n<td>Normal</td>\n<td>New Article</td>\n<td>\n</td></tr>\n<tr>\n<td>14</td>\n<td>Ongoing</td>\n<td>12-Mar-2021</td>\n<td>Add breadcrumbs everywhere (Example:<a class=\"mw-redirect\" href=\"/index.php/CDB\" title=\"CDB\">Main</a> / <a href=\"/index.php/Category:Game_mechanics\" title=\"Category:Game mechanics\">Game mechanics</a> / <b>Wurmpedia tasklist</b>)</td>\n<td>Low</td>\n<td>Cleanup</td>\n<td>\n</td></tr>\n<tr>\n<td>15</td>\n<td>Ongoing</td>\n<td>12-Mar-2021</td>\n<td>Check all items for dye amounts/dye-ability/color runing, add to itembox (just as you go, pls)</td>\n<td>Low</td>\n<td>Cleanup</td>\n<td>\n</td></tr>\n<tr>\n<td>16</td>\n<td>In Progress</td>\n<td>29-Mar-2021</td>\n<td>Condense and redo bridge pages. One per type? Rope and wood done</td>\n<td>Normal</td>\n<td>Cleanup</td>\n<td>\n</td></tr>\n<tr>\n<td>18</td>\n<td>New</td>\n<td>14-Jul-2022 - Revisited 21-Jan-2024</td>\n<td><a href=\"/index.php/Container\" title=\"Container\">Container</a> Make sure info is correct, add missing info, maybe split into smaller tables (discuss)?</td>\n<td>High</td>\n<td>Cleanup</td>\n<td>Kyoko\n</td></tr>\n<tr>\n<td>19</td>\n<td>New</td>\n<td>19-Jul-2022</td>\n<td><a href=\"/index.php/Ship\" title=\"Ship\">Ship</a> We need to just totally rewrite this for clarity and updates.</td>\n<td>ASAP</td>\n<td>Update</td>\n<td>\n</td></tr>\n<tr>\n<td>20</td>\n<td>New</td>\n<td>13-Oct-2022</td>\n<td>Suggestion for the Hay page improvements: There should be information about hay making working on grass tiles able for farming (&lt;=9 slope), on steeper slope mixed grass possible yield and time to harvest depending on skill, tool ql, tool enchantment/runes hay drying best and losses least during summer, worst in winter</td>\n<td>Normal</td>\n<td>Cleanup</td>\n<td>\n</td></tr>\n<tr>\n<td>21</td>\n<td>New</td>\n<td>25-Feb-2023</td>\n<td>Add wagonner messages to Wagonner page (success, failure, etc)</td>\n<td>Normal</td>\n<td>Update</td>\n<td>\n</td></tr>\n<tr>\n<td>22</td>\n<td>New</td>\n<td>07-May-2023</td>\n<td>Go over Interface page, make sure it\'s up to date.</td>\n<td>Normal</td>\n<td>Update</td>\n<td>\n<p><br/>\n</p>\n</td></tr>\n<tr>\n<td>26</td>\n<td>Ongoing</td>\n<td></td>\n<td>Verify that pictures are uploaded to the wiki, and added to the appropriate page.</td>\n<td>Normal</td>\n<td>Ongoing</td>\n<td>Kyoko\n</td></tr>\n<tr>\n<td>27</td>\n<td>Ongoing</td>\n<td></td>\n<td>Copy Release notes to wiki page</td>\n<td>Normal</td>\n<td>Ongoing</td>\n<td>Kyoko\n</td></tr>\n<tr>\n<td>28</td>\n<td>New</td>\n<td>20-Sep-2023</td>\n<td>Work on rift changes - Shoulder pads need updates on improving and skills</td>\n<td>Normal</td>\n<td>Update</td>\n<td>\n</td></tr></tbody></table>\n<h3><span class=\"mw-headline\" id=\"Notes\">Notes</span></h3>\n<ul><li>When adding new tasks, assign the next number.</li>\n<li>When tasks are completed and moved to table below - do not renumber tasks.</li></ul>\n<p><br/>\n</p>\n<p>And of course: Keep on Wurming\n</p>', 0),
(14913, 3871, 'Completed tasks', 'Completed_tasks', 'Number Status Date Task Priority Type Task Manager 3 Completed 23-Jan-2021 German language Your first days in Wurm (being translated by Yaga) Normal Project Yaga 25 Completed  Sept 2023 16-Aug-2023 Move Wurmpedia Assistant Handbook into a Wiki page Normal Project Oluffus 17 Completed Sept 2023 20-May-2021 Make a section of skins at the silver shop page Low New Article Goldfinch 23 Completed 4-Aug-2023 16-Jul-2023 Page should not have forums links - let\'s go over these posts, make sure we have all the information from it (correctly) and delete the link on the Bridge page. Bridge#Links Normal Cleanup 29 New 23-Sept-2023 Add pages for Christmas archaeology decor items and foraged easter eggs decor Normal New Articles Goldfinch 24 Completed 16-Jul-2023 Check Task 17 List Tab from Kyoko (6th tab on the old tasklist sheet) as it combines several updates needed, listed by page. Normal Cleanup 7 Completed 23-Jan-2021 Russian language Wurm page(s) (by Sheder? and Kyoko?) Update: Project marked as abandoned.  Can\'t contact Sheder; hasn\'t been online since Jan 2022 and in-game was the only point of contact. -- Kyoko Normal Project Kyoko', '<table border=\"1\" cellpadding=\"3\" cellspacing=\"0\" class=\"wikitable sortable\">\n<tbody><tr>\n<th>Number</th>\n<th>Status</th>\n<th>Date</th>\n<th>Task</th>\n<th>Priority</th>\n<th>Type</th>\n<th>Task Manager\n</th></tr>\n<tr>\n<td>3</td>\n<td>Completed</td>\n<td>23-Jan-2021</td>\n<td>German language Your first days in Wurm (being translated by Yaga)</td>\n<td>Normal</td>\n<td>Project</td>\n<td>Yaga\n</td></tr>\n<tr>\n<td>25</td>\n<td>Completed  Sept 2023</td>\n<td>16-Aug-2023</td>\n<td>Move Wurmpedia Assistant Handbook into a Wiki page</td>\n<td>Normal</td>\n<td>Project</td>\n<td>Oluffus\n</td></tr>\n<tr>\n<td>17</td>\n<td>Completed Sept 2023</td>\n<td>20-May-2021</td>\n<td>Make a section of skins at the <a href=\"/index.php/Silver_shop\" title=\"Silver shop\">silver shop</a> page</td>\n<td>Low</td>\n<td>New Article</td>\n<td>Goldfinch\n</td></tr>\n<tr>\n<td>23</td>\n<td>Completed 4-Aug-2023</td>\n<td>16-Jul-2023</td>\n<td>Page should not have forums links - let\'s go over these posts, make sure we have all the information from it (correctly) and delete the link on the Bridge page.  <a href=\"/index.php/Bridge#Links\" title=\"Bridge\">Bridge#Links</a></td>\n<td>Normal</td>\n<td>Cleanup\n</td></tr>\n<tr>\n<td>29</td>\n<td>New</td>\n<td>23-Sept-2023</td>\n<td>Add pages for Christmas archaeology decor items and foraged easter eggs decor</td>\n<td>Normal</td>\n<td>New Articles</td>\n<td>Goldfinch\n</td></tr>\n<tr>\n<td>24</td>\n<td>Completed</td>\n<td>16-Jul-2023</td>\n<td>Check Task 17 List Tab from Kyoko (6th tab on the old tasklist sheet) as it combines several updates needed, listed by page.</td>\n<td>Normal</td>\n<td>Cleanup</td>\n<td>\n</td></tr>\n<tr>\n<td>7</td>\n<td>Completed</td>\n<td>23-Jan-2021</td>\n<td>Russian language Wurm page(s) (by Sheder? and Kyoko?) <br/> Update: Project marked as abandoned.  Can\'t contact Sheder; hasn\'t been online since Jan 2022 and in-game was the only point of contact. -- Kyoko</td>\n<td>Normal</td>\n<td>Project</td>\n<td>Kyoko\n</td></tr></tbody></table>\n<p><br/>\n</p>\n<p><br/>\n</p>\n<p><br/>\n</p>', 1);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(14914, 3871, 'Resource nodes info, observations and pages requiring changes', 'Resource_nodes_info.2C_observations_and_pages_requiring_changes', 'Number Node Location Action Resources 1 Alpine brush High Altitudes Botanize Onions, sassafras, lingonberries, potatoes, cabbages, carrots, sugar beets, green apples, low quality cotton, green tea leaves, and honey nuts. Onions, lingonberries, potatoes, cabbages, carrots, sassafras, sugar beets, green apples, low quality cotton, green tea leaves, and honey nuts. Lingonberries, potatoes, cabbages, onions, carrots, sugar beets, sassafras, green apples, low quality cotton, green tea leaves, and honey nuts. 2 Animal burrow Everywhere Forage Nuts, berries, crop seeds, carrots, potatoes, cabbages, low quality wool, low quality cotton, grubs, and very low quality gems. Berries, nuts, crop seeds, carrots, potatoes, cabbages, grubs, low quality wool, low quality cotton, and very low quality gems. Nuts, berries, crop seeds, carrots, potatoes, cabbages, grubs, low quality wool, low quality cotton, and very low quality gems. 3 Bog muck Tar / Peat Forage Tar, horns, hooves, blueberries, low quality iron rocks, and goblin skulls\nTar, horns, hooves, blueberries, low quality iron rocks, goblin skulls, and lost footwear. 4 Briar patch Woodland, Steppe, Peat Botanize Blueberries, handfuls of raspberries, rose flowers, branches, bush sprouts, and starberries. Blueberries, handfuls of raspberries, rose flowers, bush sprouts, branches, and starberries. 5 Critter nest Woodland Forage Nuts, eggs, acorns, berries, feathers, crop seeds, low quality wool, low quality cotton, and low quality jewelry. Nuts, eggs, berries, acorns, feathers, crop seeds, low quality wool, low quality cotton, and low quality jewelry. Nuts, acorns, berries, feathers, crop seeds, eggs, low quality wool, low quality cotton, and low quality jewelry. 6 Desert weeds Sandy area Botanize Cumin, fennel plant, low quality sage, low quality oregano, low quality bunches of mixed grass, cotton, and golden pepper. 7 Dune grass Sand Botanize Rice, pea pods, fennel plant, low quality grains, reed plants, cotton, and bunches of mixed grass. Rice, pea pods, fennel plant, low quality grains, reed plants, bunches of mixed grass, and cotton. 8 Flotsam Water near Shore Forage Low quality wood scrap, low quality square pieces of cloth, wemp fibre, low quality shafts, low quality logs, low quality ropes, spice jars, very low quality nails, low quality wooden ship parts, low quality sailing ropes, low quality liquor bottles, and liquor barrels. Low quality wood scrap, wemp fibre, low quality shafts, low quality logs, low quality ropes, spice jars, very low quality nails, low quality wooden ship parts, low quality square pieces of cloth, low quality sailing ropes, low quality liquor bottles, and liquor barrels. 9 Fungus Underground Forage Brown mushrooms, green mushrooms, yellow mushrooms, black mushrooms, red mushrooms, and blue mushrooms. 10 Lichen Rock / paving / Dirt Forage Moss, green mushrooms, low quality stone shards, and very low quality iron rocks. 11 Low brush Steppe Botanize Woad, strawberries, wemp plants, cotton, thyme, basil, nutmeg, cacao beans, and coffee cherries. Strawberries, thyme, basil, woad, wemp plants, cotton, nutmeg, cacao beans, and coffee cherries. Woad, thyme, strawberries, wemp plants, cotton, basil, cacao beans, and coffee cherries. 12 Mineral debris Everywhere Forage Low quality stone shards, very low quality clay, very low quality iron rocks, low quality salt, and low quality gold and silver lumps. Low quality stone shards, very low quality iron rocks, very low quality clay, low quality salt, and low quality gold and silver lumps. 13 Mints Woodland Botanize Mint, rosemary, sage, thyme, oregano, basil, and lavender flowers. 14 Nightshades Woodland / Steppe / Moss Botanize Bouquets of purple flowers, potatoes, belladonna, tomatoes, paprika, and worgsbane. Bouquets of purple flowers, belladonna, tomatoes, potatoes, paprika, and worgsbane. 15 Roots and bulbs Woodland Botanize Onions, garlic, potatoes, carrots, ginger, turmeric, and sugar beets. Onions, garlic, potatoes, carrots, ginger, sugar beets, and turmeric. 16 Rotting wood Woodland / Moss Forage Nettles, brown mushrooms, red mushrooms, blue mushrooms, low quality branches, low quality tree sprouts, low quality seedlings, moss, and very low quality logs. Brown mushrooms, nettles, red mushrooms, blue mushrooms, low quality branches, low quality tree sprouts, low quality seedlings, moss, and very low quality logs. Brown mushrooms, red mushrooms, moss, blue mushrooms, nettles, low quality branches, low quality tree sprouts, low quality seedlings, and very low quality logs. Brown mushrooms, red mushrooms, nettles, blue mushrooms, low quality branches, very low quality logs, moss, low quality tree sprouts, and low quality seedlings. Brown mushrooms, red mushrooms, nettles, moss, blue mushrooms, low quality branches, low quality tree sprouts, low quality seedlings, and very low quality logs. Nettles, brown mushrooms, red mushrooms, low quality branches, low quality tree sprouts, low quality seedlings, blue mushrooms, moss, and very low quality logs. 17 Rubble Rock / Gravel / Underground Forage Stone shards, sandstone shards, slate shards, vlq iron rocks, marble shards, lq ore, lq flints, lq gems, lq rock salts, and ash. 18 Seaweed Shoreline / Shallow waters Forage Rice, reed plants, bunches of kelp, low quality small freshwater fish, fishing hooks, clams, and pearls. Bunches of kelp, low quality small ocean fish, rice, reed plants, clams, fishing hooks, and pearls. Bunches of kelp, reed plants, clams, low quality small ocean fish, rice, fishing hooks, and pearls. 19 Snow pile Everywhere in Winter/Higher Alts in other seasons Collect Snowballs 20 Swampy puddle Clay / Moss / Peat Botanize Brown mushrooms, red mushrooms, reed plants, low quality rice, mint, low quality handfuls of raspberries, moss, and low quality blueberries. Brown mushrooms, reed plants, red mushrooms, low quality rice, moss, mint, low quality handfuls of raspberries, and low quality blueberries. 21 Thicket Woodland Botanize Bush sprouts, fruit tree sprouts, berries, sassafras, hazelnuts, grapes, green apples, olives, red cherries, cotton, pineapples, and coconuts. Hazelnuts, bush sprouts, grapes, green apples, olives, fruit tree sprouts, red cherries, berries, sassafras, cotton, pineapples, and coconuts. Hazelnuts, sassafras, bush sprouts, grapes, green apples, olives, fruit tree sprouts, red cherries, berries, cotton, pineapples, and coconuts. 22 Tropical foliage Grassland / Woodland at Lower alts Botanize Paprika, turmeric, nutmeg, coffee cherries, cacao beans, green tea leaves, pineapples, and coconuts. 23 Umbellifers Grassland / Woodland Botanize Carrots, parsley, fennel plant, lovage, and cumin. 24 Undergrowth Woodland Forage Branches, nettles, sprouts, acorns, nuts, low quality logs, wemp plants, and cotton. Nettles, branches, sprouts, acorns, wemp plants, nuts, low quality logs, and cotton. Nettles, branches, sprouts, acorns, nuts, wemp plants, low quality logs, and cotton. 25 Vines Woodland / Steppe Botanize Grapes, pea pods, cucumbers, pumpkins, tomatoes, seedlings, hops, and drakemelons. 26 Wild grasses Woodland / Steppe / Shoreline Botanize Barley, wheat, oats, rye, bunches of mixed grass, reed plants, corn, rice, and source seeds. Barley, wheat, oats, rye, corn, rice, bunches of mixed grass, reed plants, and source seeds. Barley, wheat, rice, oats, rye, corn, reed plants, bunches of mixed grass, and source seeds. 27 Wildflowers Grassland / Woodland / Steppe Botanize Bouquets of common flowers, lavender flowers, camellia flowers, parsley, oleander, rosemary, lovage, belladonna, woad, rose flowers, and bouquets of dotted flowers. Camellia flowers, bouquets of common flowers, oleander, rosemary, parsley, lavender flowers, lovage, belladonna, woad, rose flowers, and bouquets of dotted flowers. 28 Monster camp Everywhere? Forage Meat, wool, furs, low quality strips of leather, teeth, ash, low quality charcoal, low quality planks, low quality nails, exceptional quality common monster cuisine, very low quality human clothing, exceptional quality rare monster cuisine, exceptional quality supreme monster cuisine, low quality human jewelry, and exceptional quality fantastic monster cuisine. Important note:	Changing the tile a resource node is on in certain ways, i.e. cutting the grass, planting in the dirt, chopping down a tree or dropping sand/dirt will destroy the node! Strangely digging sand does not destroy the node. Digging sand from a tile containing a dune grass node does not harm the node. Dropping the sand back makes the node disappear. Digging dirt from under gravel pavement on a tile neighboring a tile with a resource node makes the node disappear. Chopping down a tree makes the node disappear. Cutting long grass with a sickle or scythe does not harm the node. Cutting wild grass with a sickle does not harm the node. Cutting wild grass with a scythe makes the node disappear. Planting seeds on dirt makes the node disappear. Surface mining does not harm the node. A node spawning on a farm tile does not harm crops More notes: \nCutting down a tree with a snow node on it removes the node. Cutting down a tree with other node types on it removes the node. Cutting down a tree with nodes on the tiles next to it on grass (north and west) doesn\'t destroy the nodes. Digging on sand with a node doesn\'t destroy it, however dropping the sand does. Digging on sand next to a node (eastern side) doesn\'t remove the node, however dropping the sand back does destroy it. Digging on a grass tile with a snow node does remove the node. Digging on a grass tile with another node type does remove the node. Digging on a grass tile with a node next to it on a grass tile (west of) doesn\'t destroy it, and neither does dropping the dirt back down. Digging on a tile with clay doesn\'t destroy the node (swampy puddle) Digging on the sand tile next to it (eastern side of the above clay) doesn\'t destroy the node next to it and dropping the sand doesn\'t destroy the node next to it (swampy puddle) Mining on a rock tile doesn\'t destroy the node (mineral debris) with this message \'You chip away at the rock.\' Mining on a rock tile doesn\'t destroy the node (mineral debris) with this message \'You mine some stone shards.\' Prospecting on a rock tile doesn\'t destroy the node (mineral debris) Tunnelling on a rock tile doesn\'t destroy the node (mineral debris) A pile of stone shards appearing on a rock tile with a node (mineral debris) doesn\'t destroy the node. \'You create a tunnel entrance!\' on the node tile does destroy the node (mineral debris) Grass tile with Orange-red flowers and a Briar patch node, if you pick the flowers with a sickle it doesn\'t destroy the node. Grass tile with a Briar patch node, if you cut the grass with a sickle it doesn\'t destroy the node. Grass tile with Orange-red flowers and a Mints node, with \'wild\' grass, if you cut the grass using a scythe (hay making) it does destroy the node (and flowers as usual) Lavender Bush with Nightshade node, if you cut down the bush it removed the node too. Roots and bulb node on a flower and grass tile, harvest the node and the flowers remain and no change to grass. If you drop dirt on a rock tile with a node (mineral debris) it destroys the node. If you plant a tree sprout on a grass tile with a snow node it removes the node. Cultivate on grass with a node (Animal burrow) removes the node (and turns the tile to dirt as usual) If you use flatten on a sand tile with a node it removes the node. Investigating (Archaeology) with a shovel and trowel seems to work fine on tiles with nodes, definitely getting fragments and dead deed info. Getting bark from a  Birch tree (for fishing float) with a node doesn\'t affect the node. Pruning overaged Birch tree doesn\'t affect the node. Cutting grass (sickle) on a tile with a Birch tree and node, doesn\'t affect the node. Pages that will need updates Acorns (done) Alchemy (no changes needed) Basic Knowledge (done) Basil (done) Belladonna (done) Botanizing (done) \n   Branch (done) Cacao beans (done) Carrot (done) Carrot seeds (done) Cave (done) Clay (done) Cobblestone (done) Cooking for beginners (changes not required) Cotton (done) Cotton seed (done) Cucumber (done) Cucumber seeds (done) Cumin (done) Cut grass (done) Deine ersten Tage in Wurm Online (Yaga working on it) Dirt tile (done) Egg (done) Enchanted grass (done) Feather (done) Fennel plant (done) Field (done) Fish (done) Fishing hook (wooden, bone, and metal pages) (done) Floor board (done) Foraging (done) \n   Garlic (done) Ginger (done) Goblin skull (done) Grass tile (done) Green apple (done) Green coffee beans (done) Green tea leaves (done) Grub (done) Guides:Exploring For Newbies (done) Guides:Farming Tips (done) Guides:Farming With Tritus we do not update player made guides Guides:New Player Walkthrough\n   Guides:Starting with Nothing\n   Guides:The Little Things\n   Guides:Tutorial3\n   Guides:What Do I Do\n   Guides:Wurmians starter guide\n   Hoof (done) Horn (done) Iron rock (done) Ivy seedling (done) Kelp tile (done) Key bindings - possibly - still working on bug\n   Lava (done) Lawn (done) Lettuce (temporarily done - status may change) Lettuce seeds (done) Lovage (done) Marble brick (pavement) (done) Marble slab (pavement) (done) Mint (done) Moss (done) Mycelium (done) Nettles (done) Nutmeg (done) Oregano (done) Paprika (done) Parsley (done) Pea pods (done) Peas (done) Pearl (done) Peat tile (done) Pottery bricks (done) Pumpkin (done) Pumpkin seeds (done) Raspberries (done) Reed plants (done) Rice (done) Rock tile (done) Rough cobblestone (done) Round cobblestone (done) Rosemary (done) Sage (done) Sand (done) Sandstone bricks (done) Sandstone shards (done) Sandstone slab (done) Sassafras (done) Shaft (done) Silver lump (done) Slate bricks (done) Slate shards (done) Slate slabs (done) Small moss (done) Square piece of cloth (done) Starberries (done) Steppe (done) Stone shards (done) Stone slabs (done) Sugar beet (done) Sugar beet seeds (done) Tar (done) Tar tile (done) Tea seeds (done) Thyme span <style=\"background:#00FF00\"> (done) \n   Tile types \n   Tundra (done) Turmeric (done) Vos premiers jours dans Wurm Online\n   Water tile (done) Wemp fibre (done) Wemp seeds (done) Woad (done) Wood scrap (done) Your first days in Wurm Online (Yaga working on it) Основы игры New pages needed Resource nodes (done) One for each resource node type (done) Drakemelons - Vines\n   Golden pepper - Desert weeds (done) Honey nuts - Alpine brush (done) Source seeds - Wild grasses (done) Worgsbane - Nightshades (done) Pineapples - Thicket / Tropical foliage\n   Coconuts - Thicket / Tropical foliage (done)', '<table border=\"1\" cellpadding=\"3\" cellspacing=\"0\" class=\"wikitable sortable\">\n<tbody><tr>\n<th>Number</th>\n<th>Node</th>\n<th>Location</th>\n<th>Action</th>\n<th>Resources\n</th></tr>\n<tr>\n<td>1</td>\n<td>Alpine brush</td>\n<td>High Altitudes</td>\n<td>Botanize</td>\n<td>\n<p>Onions, sassafras, lingonberries, potatoes, cabbages, carrots, sugar beets, green apples, low quality cotton, green tea leaves, and honey nuts.<br/>\nOnions, lingonberries, potatoes, cabbages, carrots, sassafras, sugar beets, green apples, low quality cotton, green tea leaves, and honey nuts.<br/>\nLingonberries, potatoes, cabbages, onions, carrots, sugar beets, sassafras, green apples, low quality cotton, green tea leaves, and honey nuts.\n</p>\n</td></tr>\n<tr>\n<td>2</td>\n<td>Animal burrow</td>\n<td>Everywhere</td>\n<td>Forage</td>\n<td>\n<p>Nuts, berries, crop seeds, carrots, potatoes, cabbages, low quality wool, low quality cotton, grubs, and very low quality gems.<br/>\nBerries, nuts, crop seeds, carrots, potatoes, cabbages, grubs, low quality wool, low quality cotton, and very low quality gems.<br/>\nNuts, berries, crop seeds, carrots, potatoes, cabbages, grubs, low quality wool, low quality cotton, and very low quality gems.\n</p>\n</td></tr>\n<tr>\n<td>3</td>\n<td>Bog muck</td>\n<td>Tar / Peat</td>\n<td>Forage</td>\n<td>\n<p>Tar, horns, hooves, blueberries, low quality iron rocks, and goblin skulls\nTar, horns, hooves, blueberries, low quality iron rocks, goblin skulls, and lost footwear. \n</p>\n</td></tr>\n<tr>\n<td>4</td>\n<td>Briar patch</td>\n<td>Woodland, Steppe, Peat</td>\n<td>Botanize</td>\n<td>\n<p>Blueberries, handfuls of raspberries, rose flowers, branches, bush sprouts, and starberries.<br/>\nBlueberries, handfuls of raspberries, rose flowers, bush sprouts, branches, and starberries.\n</p>\n</td></tr>\n<tr>\n<td>5</td>\n<td>Critter nest</td>\n<td>Woodland</td>\n<td>Forage</td>\n<td>\n<p>Nuts, eggs, acorns, berries, feathers, crop seeds, low quality wool, low quality cotton, and low quality jewelry.<br/>\nNuts, eggs, berries, acorns, feathers, crop seeds, low quality wool, low quality cotton, and low quality jewelry.<br/>\nNuts, acorns, berries, feathers, crop seeds, eggs, low quality wool, low quality cotton, and low quality jewelry.\n</p>\n</td></tr>\n<tr>\n<td>6</td>\n<td>Desert weeds</td>\n<td>Sandy area</td>\n<td>Botanize</td>\n<td>\n<p>Cumin, fennel plant, low quality sage, low quality oregano, low quality bunches of mixed grass, cotton, and golden pepper.\n</p>\n</td></tr>\n<tr>\n<td>7</td>\n<td>Dune grass</td>\n<td>Sand</td>\n<td>Botanize</td>\n<td>\n<p>Rice, pea pods, fennel plant, low quality grains, reed plants, cotton, and bunches of mixed grass.<br/>\nRice, pea pods, fennel plant, low quality grains, reed plants, bunches of mixed grass, and cotton.\n</p>\n</td></tr>\n<tr>\n<td>8</td>\n<td>Flotsam</td>\n<td>Water near Shore</td>\n<td>Forage</td>\n<td>\n<p>Low quality wood scrap, low quality square pieces of cloth, wemp fibre, low quality shafts, low quality logs, low quality ropes, spice jars, very low quality nails, low quality wooden ship parts, low quality sailing ropes, low quality liquor bottles, and liquor barrels.<br/>\nLow quality wood scrap, wemp fibre, low quality shafts, low quality logs, low quality ropes, spice jars, very low quality nails, low quality wooden ship parts, low quality square pieces of cloth, low quality sailing ropes, low quality liquor bottles, and liquor barrels.\n</p>\n</td></tr>\n<tr>\n<td>9</td>\n<td>Fungus</td>\n<td>Underground</td>\n<td>Forage</td>\n<td>Brown mushrooms, green mushrooms, yellow mushrooms, black mushrooms, red mushrooms, and blue mushrooms.\n</td></tr>\n<tr>\n<td>10</td>\n<td>Lichen</td>\n<td>Rock / paving / Dirt</td>\n<td>Forage</td>\n<td>\n<p>Moss, green mushrooms, low quality stone shards, and very low quality iron rocks.\n</p>\n</td></tr>\n<tr>\n<td>11</td>\n<td>Low brush</td>\n<td>Steppe</td>\n<td>Botanize</td>\n<td>\n<p>Woad, strawberries, wemp plants, cotton, thyme, basil, nutmeg, cacao beans, and coffee cherries.<br/>\nStrawberries, thyme, basil, woad, wemp plants, cotton, nutmeg, cacao beans, and coffee cherries.<br/>\nWoad, thyme, strawberries, wemp plants, cotton, basil, cacao beans, and coffee cherries.\n</p>\n</td></tr>\n<tr>\n<td>12</td>\n<td>Mineral debris</td>\n<td>Everywhere</td>\n<td>Forage</td>\n<td>\n<p>Low quality stone shards, very low quality clay, very low quality iron rocks, low quality salt, and low quality gold and silver lumps.<br/>\nLow quality stone shards, very low quality iron rocks, very low quality clay, low quality salt, and low quality gold and silver lumps.\n</p>\n</td></tr>\n<tr>\n<td>13</td>\n<td>Mints</td>\n<td>Woodland</td>\n<td>Botanize</td>\n<td>\n<p>Mint, rosemary, sage, thyme, oregano, basil, and lavender flowers.\n</p>\n</td></tr>\n<tr>\n<td>14</td>\n<td>Nightshades</td>\n<td>Woodland / Steppe / Moss</td>\n<td>Botanize</td>\n<td>\n<p>Bouquets of purple flowers, potatoes, belladonna, tomatoes, paprika, and worgsbane.<br/>\nBouquets of purple flowers, belladonna, tomatoes, potatoes, paprika, and worgsbane.\n</p>\n</td></tr>\n<tr>\n<td>15</td>\n<td>Roots and bulbs</td>\n<td>Woodland</td>\n<td>Botanize</td>\n<td>\n<p>Onions, garlic, potatoes, carrots, ginger, turmeric, and sugar beets.<br/>\nOnions, garlic, potatoes, carrots, ginger, sugar beets, and turmeric.\n</p>\n</td></tr>\n<tr>\n<td>16</td>\n<td>Rotting wood</td>\n<td>Woodland / Moss</td>\n<td>Forage</td>\n<td>\n<p>Nettles, brown mushrooms, red mushrooms, blue mushrooms, low quality branches, low quality tree sprouts, low quality seedlings, moss, and very low quality logs.<br/>\nBrown mushrooms, nettles, red mushrooms, blue mushrooms, low quality branches, low quality tree sprouts, low quality seedlings, moss, and very low quality logs.<br/>\nBrown mushrooms, red mushrooms, moss, blue mushrooms, nettles, low quality branches, low quality tree sprouts, low quality seedlings, and very low quality logs.<br/>\nBrown mushrooms, red mushrooms, nettles, blue mushrooms, low quality branches, very low quality logs, moss, low quality tree sprouts, and low quality seedlings.<br/>\nBrown mushrooms, red mushrooms, nettles, moss, blue mushrooms, low quality branches, low quality tree sprouts, low quality seedlings, and very low quality logs.<br/>\nNettles, brown mushrooms, red mushrooms, low quality branches, low quality tree sprouts, low quality seedlings, blue mushrooms, moss, and very low quality logs.\n</p>\n</td></tr>\n<tr>\n<td>17</td>\n<td>Rubble</td>\n<td>Rock / Gravel / Underground</td>\n<td>Forage</td>\n<td>Stone shards, sandstone shards, slate shards, vlq iron rocks, marble shards, lq ore, lq flints, lq gems, lq rock salts, and ash.\n</td></tr>\n<tr>\n<td>18</td>\n<td>Seaweed</td>\n<td>Shoreline / Shallow waters</td>\n<td>Forage</td>\n<td>\n<p>Rice, reed plants, bunches of kelp, low quality small freshwater fish, fishing hooks, clams, and pearls.<br/>\nBunches of kelp, low quality small ocean fish, rice, reed plants, clams, fishing hooks, and pearls.<br/>\nBunches of kelp, reed plants, clams, low quality small ocean fish, rice, fishing hooks, and pearls.\n</p>\n</td></tr>\n<tr>\n<td>19</td>\n<td>Snow pile</td>\n<td>Everywhere in Winter/Higher Alts in other seasons</td>\n<td>Collect</td>\n<td>Snowballs\n</td></tr>\n<tr>\n<td>20</td>\n<td>Swampy puddle</td>\n<td>Clay / Moss / Peat</td>\n<td>Botanize</td>\n<td>\n<p>Brown mushrooms, red mushrooms, reed plants, low quality rice, mint, low quality handfuls of raspberries, moss, and low quality blueberries.<br/>\nBrown mushrooms, reed plants, red mushrooms, low quality rice, moss, mint, low quality handfuls of raspberries, and low quality blueberries.\n</p>\n</td></tr>\n<tr>\n<td>21</td>\n<td>Thicket</td>\n<td>Woodland</td>\n<td>Botanize</td>\n<td>\n<p>Bush sprouts, fruit tree sprouts, berries, sassafras, hazelnuts, grapes, green apples, olives, red cherries, cotton, pineapples, and coconuts.<br/>\nHazelnuts, bush sprouts, grapes, green apples, olives, fruit tree sprouts, red cherries, berries, sassafras, cotton, pineapples, and coconuts.<br/>\nHazelnuts, sassafras, bush sprouts, grapes, green apples, olives, fruit tree sprouts, red cherries, berries, cotton, pineapples, and coconuts.\n</p>\n</td></tr>\n<tr>\n<td>22</td>\n<td>Tropical foliage</td>\n<td>Grassland / Woodland at Lower alts</td>\n<td>Botanize</td>\n<td>Paprika, turmeric, nutmeg, coffee cherries, cacao beans, green tea leaves, pineapples, and coconuts.\n</td></tr>\n<tr>\n<td>23</td>\n<td>Umbellifers</td>\n<td>Grassland / Woodland</td>\n<td>Botanize</td>\n<td>\n<p>Carrots, parsley, fennel plant, lovage, and cumin.\n</p>\n</td></tr>\n<tr>\n<td>24</td>\n<td>Undergrowth</td>\n<td>Woodland</td>\n<td>Forage</td>\n<td>\n<p>Branches, nettles, sprouts, acorns, nuts, low quality logs, wemp plants, and cotton.<br/>\nNettles, branches, sprouts, acorns, wemp plants, nuts, low quality logs, and cotton.<br/>\nNettles, branches, sprouts, acorns, nuts, wemp plants, low quality logs, and cotton.\n</p>\n</td></tr>\n<tr>\n<td>25</td>\n<td>Vines</td>\n<td>Woodland / Steppe</td>\n<td>Botanize</td>\n<td>\n<p>Grapes, pea pods, cucumbers, pumpkins, tomatoes, seedlings, hops, and drakemelons.\n</p>\n</td></tr>\n<tr>\n<td>26</td>\n<td>Wild grasses</td>\n<td>Woodland / Steppe / Shoreline</td>\n<td>Botanize</td>\n<td>\n<p>Barley, wheat, oats, rye, bunches of mixed grass, reed plants, corn, rice, and source seeds.<br/>\nBarley, wheat, oats, rye, corn, rice, bunches of mixed grass, reed plants, and source seeds.<br/>\nBarley, wheat, rice, oats, rye, corn, reed plants, bunches of mixed grass, and source seeds.\n</p>\n</td></tr>\n<tr>\n<td>27</td>\n<td>Wildflowers</td>\n<td>Grassland / Woodland / Steppe</td>\n<td>Botanize</td>\n<td>\n<p>Bouquets of common flowers, lavender flowers, camellia flowers, parsley, oleander, rosemary, lovage, belladonna, woad, rose flowers, and bouquets of dotted flowers.<br/>\nCamellia flowers, bouquets of common flowers, oleander, rosemary, parsley, lavender flowers, lovage, belladonna, woad, rose flowers, and bouquets of dotted flowers.\n</p>\n</td></tr>\n<tr>\n<td>28</td>\n<td>Monster camp</td>\n<td>Everywhere?</td>\n<td>Forage</td>\n<td>Meat, wool, furs, low quality strips of leather, teeth, ash, low quality charcoal, low quality planks, low quality nails, exceptional quality common monster cuisine, very low quality human clothing, exceptional quality rare monster cuisine, exceptional quality supreme monster cuisine, low quality human jewelry, and exceptional quality fantastic monster cuisine.\n</td></tr></tbody></table>\n<p>Important note:	Changing the tile a resource node is on in certain ways, i.e. cutting the grass, planting in the dirt, chopping down a tree or dropping sand/dirt will destroy the node! Strangely digging sand does not destroy the node.		\n</p>\n<ul><li>Digging sand from a tile containing a dune grass node does not harm the node. Dropping the sand back makes the node disappear.</li>\n<li>Digging dirt from under gravel pavement on a tile neighboring a tile with a resource node makes the node disappear.</li>\n<li>Chopping down a tree makes the node disappear.</li>\n<li>Cutting long grass with a sickle or scythe does not harm the node. Cutting wild grass with a sickle does not harm the node. Cutting wild grass with a scythe makes the node disappear.</li>\n<li>Planting seeds on dirt makes the node disappear.</li>\n<li>Surface mining does not harm the node.</li>\n<li>A node spawning on a farm tile does not harm crops</li></ul>\n<p>More notes: \nCutting down a tree with a snow node on it removes the node.<br/>\nCutting down a tree with other node types on it removes the node.<br/>\nCutting down a tree with nodes on the tiles next to it on grass (north and west) doesn\'t destroy the nodes.<br/>\nDigging on sand with a node doesn\'t destroy it, however dropping the sand does.<br/>\nDigging on sand next to a node (eastern side) doesn\'t remove the node, however dropping the sand back does destroy it.<br/>\nDigging on a grass tile with a snow node does remove the node.<br/>\nDigging on a grass tile with another node type does remove the node.<br/>\nDigging on a grass tile with a node next to it on a grass tile (west of) doesn\'t destroy it, and neither does dropping the dirt back down.<br/>\nDigging on a tile with clay doesn\'t destroy the node (swampy puddle)<br/>\nDigging on the sand tile next to it (eastern side of the above clay) doesn\'t destroy the node next to it and dropping the sand doesn\'t destroy the node next to it (swampy puddle)<br/>\nMining on a rock tile doesn\'t destroy the node (mineral debris) with this message \'You chip away at the rock.\'<br/>\nMining on a rock tile doesn\'t destroy the node (mineral debris) with this message \'You mine some stone shards.\'<br/>\nProspecting on a rock tile doesn\'t destroy the node (mineral debris)<br/>\nTunnelling on a rock tile doesn\'t destroy the node (mineral debris)<br/>\nA pile of stone shards appearing on a rock tile with a node (mineral debris) doesn\'t destroy the node.<br/>\n\'You create a tunnel entrance!\' on the node tile does destroy the node (mineral debris)<br/>\nGrass tile with Orange-red flowers and a Briar patch node, if you pick the flowers with a sickle it doesn\'t destroy the node.<br/>\nGrass tile with a Briar patch node, if you cut the grass with a sickle it doesn\'t destroy the node.<br/>\nGrass tile with Orange-red flowers and a Mints node, with \'wild\' grass, if you cut the grass using a scythe (hay making) it does destroy the node (and flowers as usual)<br/>\nLavender Bush with Nightshade node, if you cut down the bush it removed the node too.<br/>\nRoots and bulb node on a flower and grass tile, harvest the node and the flowers remain and no change to grass.<br/>\nIf you drop dirt on a rock tile with a node (mineral debris) it destroys the node.<br/>\nIf you plant a tree sprout on a grass tile with a snow node it removes the node.<br/>\nCultivate on grass with a node (Animal burrow) removes the node (and turns the tile to dirt as usual)<br/>\nIf you use flatten on a sand tile with a node it removes the node.<br/>\nInvestigating (Archaeology) with a shovel and trowel seems to work fine on tiles with nodes, definitely getting fragments and dead deed info.<br/>\nGetting bark from a  Birch tree (for fishing float) with a node doesn\'t affect the node.<br/>\nPruning overaged Birch tree doesn\'t affect the node.<br/>\nCutting grass (sickle) on a tile with a Birch tree and node, doesn\'t affect the node. <br/>\n</p>\n<h3><span class=\"mw-headline\" id=\"Pages_that_will_need_updates\">Pages that will need updates</span></h3>\n<pre>   Acorns <span style=\"background:#00FF00\"> (done) </span>\n   Alchemy <span style=\"background:#00FF00\"> (no changes needed) </span>\n   Basic Knowledge <span style=\"background:#00FF00\"> (done) </span>\n   Basil <span style=\"background:#00FF00\"> (done) </span>\n   Belladonna <span style=\"background:#00FF00\"> (done) </span>\n   Botanizing (done) \n   Branch <span style=\"background:#00FF00\"> (done) </span>\n   Cacao beans <span style=\"background:#00FF00\"> (done) </span>\n   Carrot <span style=\"background:#00FF00\"> (done) </span>\n   Carrot seeds <span style=\"background:#00FF00\"> (done) </span>\n   Cave <span style=\"background:#00FF00\"> (done) </span>\n   Clay <span style=\"background:#00FF00\"> (done) </span>\n   Cobblestone <span style=\"background:#00FF00\"> (done) </span>\n   Cooking for beginners <span style=\"background:#00FF00\"> (changes not required) </span>\n   Cotton <span style=\"background:#00FF00\"> (done) </span>\n   Cotton seed <span style=\"background:#00FF00\"> (done) </span>\n   Cucumber <span style=\"background:#00FF00\"> (done) </span>\n   Cucumber seeds <span style=\"background:#00FF00\"> (done) </span>\n   Cumin <span style=\"background:#00FF00\"> (done) </span>\n   Cut grass <span style=\"background:#00FF00\"> (done) </span>\n   Deine ersten Tage in Wurm Online <span style=\"background:#00FF00\"> (Yaga working on it) </span>\n   Dirt tile <span style=\"background:#00FF00\"> (done) </span>\n   Egg <span style=\"background:#00FF00\"> (done) </span>\n   Enchanted grass <span style=\"background:#00FF00\"> (done) </span>\n   Feather <span style=\"background:#00FF00\"> (done) </span>\n   Fennel plant <span style=\"background:#00FF00\"> (done) </span>\n   Field <span style=\"background:#00FF00\"> (done) </span>\n   Fish <span style=\"background:#00FF00\"> (done) </span>\n   Fishing hook (wooden, bone, and metal pages) <span style=\"background:#00FF00\"> (done) </span>\n   Floor board <span style=\"background:#00FF00\"> (done) </span>\n   Foraging (done) \n   Garlic <span style=\"background:#00FF00\"> (done) </span>\n   Ginger <span style=\"background:#00FF00\"> (done) </span>\n   Goblin skull <span style=\"background:#00FF00\"> (done) </span>\n   Grass tile <span style=\"background:#00FF00\"> (done) </span>\n   Green apple <span style=\"background:#00FF00\"> (done) </span>\n   Green coffee beans <span style=\"background:#00FF00\"> (done) </span>\n   Green tea leaves <span style=\"background:#00FF00\"> (done) </span>\n   Grub <span style=\"background:#00FF00\"> (done) </span>\n   Guides:Exploring For Newbies <span style=\"background:#00FF00\"> (done) </span>\n   Guides:Farming Tips <span style=\"background:#00FF00\"> (done) </span>\n   Guides:Farming With Tritus <span style=\"background:#00FF00\"> we do not update player made guides </span>\n   Guides:New Player Walkthrough\n   Guides:Starting with Nothing\n   Guides:The Little Things\n   Guides:Tutorial3\n   Guides:What Do I Do\n   Guides:Wurmians starter guide\n   Hoof <span style=\"background:#00FF00\"> (done) </span>\n   Horn <span style=\"background:#00FF00\"> (done) </span>\n   Iron rock <span style=\"background:#00FF00\"> (done) </span>\n   Ivy seedling <span style=\"background:#00FF00\"> (done) </span>\n   Kelp tile <span style=\"background:#00FF00\"> (done) </span>\n   Key bindings - possibly - still working on bug\n   Lava <span style=\"background:#00FF00\"> (done) </span>\n   Lawn <span style=\"background:#00FF00\"> (done) </span>\n   Lettuce <span style=\"background:#00FF00\"> (temporarily done - status may change) </span>\n   Lettuce seeds <span style=\"background:#00FF00\"> (done) </span>\n   Lovage <span style=\"background:#00FF00\"> (done) </span>\n   Marble brick (pavement) <span style=\"background:#00FF00\"> (done) </span>\n   Marble slab (pavement) <span style=\"background:#00FF00\"> (done) </span>\n   Mint <span style=\"background:#00FF00\"> (done) </span>\n   Moss <span style=\"background:#00FF00\"> (done) </span>\n   Mycelium <span style=\"background:#00FF00\"> (done) </span>\n   Nettles <span style=\"background:#00FF00\"> (done) </span>\n   Nutmeg <span style=\"background:#00FF00\"> (done) </span>\n   Oregano <span style=\"background:#00FF00\"> (done) </span>\n   Paprika <span style=\"background:#00FF00\"> (done) </span>\n   Parsley <span style=\"background:#00FF00\"> (done) </span>\n   Pea pods <span style=\"background:#00FF00\"> (done) </span>\n   Peas <span style=\"background:#00FF00\"> (done) </span>\n   Pearl <span style=\"background:#00FF00\"> (done) </span>\n   Peat tile <span style=\"background:#00FF00\"> (done) </span>\n   Pottery bricks <span style=\"background:#00FF00\"> (done) </span>\n   Pumpkin <span style=\"background:#00FF00\"> (done) </span>\n   Pumpkin seeds <span style=\"background:#00FF00\"> (done) </span>\n   Raspberries <span style=\"background:#00FF00\"> (done) </span>\n   Reed plants <span style=\"background:#00FF00\"> (done) </span>\n   Rice <span style=\"background:#00FF00\"> (done) </span>\n   Rock tile <span style=\"background:#00FF00\"> (done) </span>\n   Rough cobblestone <span style=\"background:#00FF00\"> (done) </span>\n   Round cobblestone <span style=\"background:#00FF00\"> (done) </span>\n   Rosemary <span style=\"background:#00FF00\"> (done) </span>\n   Sage <span style=\"background:#00FF00\"> (done) </span>\n   Sand <span style=\"background:#00FF00\"> (done) </span>\n   Sandstone bricks <span style=\"background:#00FF00\"> (done) </span>\n   Sandstone shards <span style=\"background:#00FF00\"> (done) </span>\n   Sandstone slab <span style=\"background:#00FF00\"> (done) </span>\n   Sassafras <span style=\"background:#00FF00\"> (done) </span>\n   Shaft <span style=\"background:#00FF00\"> (done) </span>\n   Silver lump <span style=\"background:#00FF00\"> (done) </span>\n   Slate bricks <span style=\"background:#00FF00\"> (done) </span>\n   Slate shards  <span style=\"background:#00FF00\"> (done) </span>\n   Slate slabs  <span style=\"background:#00FF00\"> (done) </span>\n   Small moss <span style=\"background:#00FF00\"> (done) </span>\n   Square piece of cloth  <span style=\"background:#00FF00\"> (done) </span>\n   Starberries  <span style=\"background:#00FF00\"> (done) </span>\n   Steppe <span style=\"background:#00FF00\"> (done) </span>\n   Stone shards  <span style=\"background:#00FF00\"> (done) </span>\n   Stone slabs <span style=\"background:#00FF00\"> (done) </span>\n   Sugar beet <span style=\"background:#00FF00\"> (done) </span>\n   Sugar beet seeds <span style=\"background:#00FF00\"> (done) </span>\n   Tar <span style=\"background:#00FF00\"> (done) </span>\n   Tar tile <span style=\"background:#00FF00\"> (done) </span>\n   Tea seeds <span style=\"background:#00FF00\"> (done) </span>\n   Thyme span &lt;style=\"background:#00FF00\"&gt; (done) \n   Tile types \n   Tundra <span style=\"background:#00FF00\"> (done) </span>\n   Turmeric <span style=\"background:#00FF00\"> (done) </span>\n   Vos premiers jours dans Wurm Online\n   Water tile <span style=\"background:#00FF00\"> (done) </span>\n   Wemp fibre  <span style=\"background:#00FF00\"> (done) </span>\n   Wemp seeds <span style=\"background:#00FF00\"> (done) </span>\n   Woad <span style=\"background:#00FF00\"> (done) </span>\n   Wood scrap  <span style=\"background:#00FF00\"> (done) </span>\n   Your first days in Wurm Online <span style=\"background:#00FF00\"> (Yaga working on it) </span>\n   Основы игры\n</pre>\n<h3><span class=\"mw-headline\" id=\"New_pages_needed\">New pages needed</span></h3>\n<pre>   Resource nodes <span style=\"background:#00FF00\"> (done) </span>\n   One for each resource node type <span style=\"background:#00FF00\"> (done) </span>\n   Drakemelons - Vines\n   Golden pepper - Desert weeds <span style=\"background:#00FF00\"> (done) </span>\n   Honey nuts - Alpine brush <span style=\"background:#00FF00\"> (done) </span>\n   Source seeds - Wild grasses <span style=\"background:#00FF00\"> (done) </span>\n   Worgsbane - Nightshades <span style=\"background:#00FF00\"> (done) </span>\n   Pineapples - Thicket / Tropical foliage\n   Coconuts - Thicket / Tropical foliage <span style=\"background:#00FF00\"> (done) </span>\n</pre>', 2),
(14923, 3873, 'Description', 'Description', 'You see a cave floor has been reinforced with thick wooden beams and metal bands.', '<p><i>You see a cave floor has been reinforced with thick wooden beams and metal bands.</i>\n</p>', 0),
(14924, 3873, 'Notes', 'Notes', 'A reinforced cave floor is a cave floor that has been reinforced with a support beam , designed to drastically reduce collapse chance. A reinforced cave floor can be prepared with mortar. All walls around a tile need to be reinforced to help protect against collapsing. Reinforcements can be removed from cave floors with a pickaxe.', '<p>A reinforced cave floor is a cave floor that has been reinforced with a <a href=\"/index.php/Support_beam\" title=\"Support beam\">support beam</a>, designed to drastically reduce collapse chance. \n</p>\n<p>A reinforced cave floor can be prepared with mortar.\n</p>\n<p>All walls around a tile need to be reinforced to help protect against collapsing.\n</p>\n<p>Reinforcements can be removed from cave floors with a pickaxe.\n</p>', 1),
(14925, 3874, 'Description', 'Description', 'You see a reinforced cave floor which has been prepared ready for paving.', '<p><i>You see a reinforced cave floor which has been prepared ready for paving.</i>\n</p>', 0),
(14926, 3874, 'Notes', 'Notes', 'A reinforced cave floor that has been prepared with mortar. Preparing a cave floor is necessary before it can be paved. Can be removed from cave floors with a Stone chisel', '<p>A reinforced cave floor that has been prepared with mortar.\n</p>\n<p>Preparing a cave floor is necessary before it can be paved.\n</p>\n<p>Can be removed from cave floors with a <a href=\"/index.php/Stone_chisel\" title=\"Stone chisel\">Stone chisel</a>\n</p>', 1),
(14927, 3877, 'Description', 'Description', 'A tightly bound bundle of arrows.', '<p>A tightly bound bundle of arrows.\n</p>', 0),
(14928, 3877, 'Usage', 'Usage', 'Arrow Bundles allow the player to combine multiple arrows into one item, so that they can all be improved, and spell cast on as one.', '<p>Arrow Bundles allow the player to combine multiple arrows into one item, so that they can all be improved, and spell cast on as one.\n</p>', 1),
(14929, 3877, 'Creating', 'Creating', 'To create a bundle, activate a wire and right click a war arrow or hunting arrow and click Bind . Only one arrow is added to a bundle upon creation. To add another arrow to the bundle activate an arrow, right click the bundle, and click Add to Bundle . Multiple arrows cannot be added to a bundle, they are added one at a time. Arrow types can be mixed in a bundle. Both War arrows and Hunting arrows can be added to the same bundle.', '<ul><li>To create a bundle, activate a <a class=\"mw-redirect\" href=\"/index.php/Wire\" title=\"Wire\">wire</a> and right click a <a href=\"/index.php/War_arrow\" title=\"War arrow\">war arrow</a> or <a href=\"/index.php/Hunting_arrow\" title=\"Hunting arrow\">hunting arrow</a> and click <b>Bind</b>.</li>\n<li>Only one arrow is added to a bundle upon creation.</li>\n<li>To add another arrow to the bundle activate an arrow, right click the bundle, and click <b>Add to Bundle</b>.</li>\n<li>Multiple arrows cannot be added to a bundle, they are added one at a time.</li>\n<li>Arrow types can be mixed in a bundle. Both War arrows and Hunting arrows can be added to the same bundle.</li></ul>', 2),
(14930, 3877, 'Separating', 'Separating', 'To separate the bundle back into arrows, activate a pair of pliers , right click the bundle and click Unbind . The unbind action can not fail The individual arrows will be of the same quality as the bundle Any spells cast upon the bundle will be applied to all arrows Rarity of the bundle will transfer to one arrow in the bundle', '<ul><li>To separate the bundle back into arrows, activate a pair of <a href=\"/index.php/Pliers\" title=\"Pliers\">pliers</a>, right click the bundle and click <b>Unbind</b>.\n<ul><li>The unbind action can not fail</li>\n<li>The individual arrows will be of the same quality as the bundle</li>\n<li>Any spells cast upon the bundle will be applied to all arrows</li>\n<li>Rarity of the bundle will transfer to one arrow in the bundle</li></ul></li></ul>', 3),
(14931, 3877, 'Bundle Sizes', 'Bundle_Sizes', 'Bundle Size Approximate Skill required 1 1 2 1 3 3 4 5 5 8 6 10 7 13 8 15 9 18 10 21 11 23 12 26 13 28 14 31 15 33 16 36 17 38 18 41 19 45 20 48 21 48 22 51 23 54 24 56 25 59 26 61 27 64 28 66 29 69 30 71 31 74 32 75 33 79 34 84 35 87 36 89 37 90 38 91.25 39 93.75 40 ? 41 ?', '<table border=\"1\" cellpadding=\"2\" cellspacing=\"0\" class=\"wikitable sortable\">\n<tbody><tr>\n<th>Bundle Size\n</th>\n<th>Approximate Skill required\n</th></tr>\n<tr>\n<td>1</td>\n<td>1\n</td></tr>\n<tr>\n<td>2</td>\n<td>1\n</td></tr>\n<tr>\n<td>3</td>\n<td>3\n</td></tr>\n<tr>\n<td>4</td>\n<td>5\n</td></tr>\n<tr>\n<td>5</td>\n<td>8\n</td></tr>\n<tr>\n<td>6</td>\n<td>10\n</td></tr>\n<tr>\n<td>7</td>\n<td>13\n</td></tr>\n<tr>\n<td>8</td>\n<td>15\n</td></tr>\n<tr>\n<td>9</td>\n<td>18\n</td></tr>\n<tr>\n<td>10</td>\n<td>21\n</td></tr>\n<tr>\n<td>11</td>\n<td>23\n</td></tr>\n<tr>\n<td>12</td>\n<td>26\n</td></tr>\n<tr>\n<td>13</td>\n<td>28\n</td></tr>\n<tr>\n<td>14</td>\n<td>31\n</td></tr>\n<tr>\n<td>15</td>\n<td>33\n</td></tr>\n<tr>\n<td>16</td>\n<td>36\n</td></tr>\n<tr>\n<td>17</td>\n<td>38\n</td></tr>\n<tr>\n<td>18</td>\n<td>41\n</td></tr>\n<tr>\n<td>19</td>\n<td>45\n</td></tr>\n<tr>\n<td>20</td>\n<td>48\n</td></tr>\n<tr>\n<td>21</td>\n<td>48\n</td></tr>\n<tr>\n<td>22</td>\n<td>51\n</td></tr>\n<tr>\n<td>23</td>\n<td>54\n</td></tr>\n<tr>\n<td>24</td>\n<td>56\n</td></tr>\n<tr>\n<td>25</td>\n<td>59\n</td></tr>\n<tr>\n<td>26</td>\n<td>61\n</td></tr>\n<tr>\n<td>27</td>\n<td>64\n</td></tr>\n<tr>\n<td>28</td>\n<td>66\n</td></tr>\n<tr>\n<td>29</td>\n<td>69\n</td></tr>\n<tr>\n<td>30</td>\n<td>71\n</td></tr>\n<tr>\n<td>31</td>\n<td>74\n</td></tr>\n<tr>\n<td>32</td>\n<td>75\n</td></tr>\n<tr>\n<td>33</td>\n<td>79\n</td></tr>\n<tr>\n<td>34</td>\n<td>84\n</td></tr>\n<tr>\n<td>35</td>\n<td>87\n</td></tr>\n<tr>\n<td>36</td>\n<td>89\n</td></tr>\n<tr>\n<td>37</td>\n<td>90\n</td></tr>\n<tr>\n<td>38</td>\n<td>91.25\n</td></tr>\n<tr>\n<td>39</td>\n<td>93.75\n</td></tr>\n<tr>\n<td>40</td>\n<td>?\n</td></tr>\n<tr>\n<td>41</td>\n<td>?\n</td></tr>\n</tbody></table>', 4),
(14932, 3877, 'Notes', 'Notes', 'The number of arrows you can add to a bundle is limited by your Fletching skill and is scaled between 2 arrows and a maximum of 41 at around 100 skill. Arrow bundles have the amount of arrows they contain appended to the name. The initial quality of a bundle is dictated by the creation arrow. If an arrow is added of a different quality, the bundle will average the quality of the arrows contained. An MOI can cause an arrow bundle to turn rare, but the bundle rarity will be transferred to only one of the arrows when the bundle is unbound. You can mix War arrows and Hunting arrows in the same bundle and their type will not change as a result of being bundled. The items and bundle must be in your inventory to create, add to, or unbind. Rare+ and casted arrows can be added to a bundle but their rarity and spells will be lost. (You are warned at the start of the action, and have time to stop.) Creation time is variable and based on the quality of the arrow, wire and your fletching skill. The materials required when improving a bundle is scaled to match the number of arrows being improved. 41 arrows means 41x the required log amount per imp action. There is no difficulty increase improving the arrows in a bundle no matter how many arrows the bundle contains. Arrow bundles can have spells cast on them, but are substantially more difficult to cast on and can shatter. You can cast any spell onto the bundle that you would be able to cast onto an arrow and that spell will affect each arrow in the bundle. You cannot improve an arrow bundle that has more arrows in it than you can add yourself. You cannot rune or imbue an arrow bundle. You cannot combine bundles, you can only add single arrows. The wood type of the bundle (and all arrows contained in it) is determined by the wood type of the last arrow added. Arrow bundles can be mailed and are a single item, costing 1c to mail', '<ul><li>The number of arrows you can add to a bundle is limited by your <a href=\"/index.php/Fletching\" title=\"Fletching\">Fletching</a> skill and is scaled between 2 arrows and a maximum of 41 at around 100 skill.</li>\n<li>Arrow bundles have the amount of arrows they contain appended to the name.</li>\n<li>The initial quality of a bundle is dictated by the creation arrow. If an arrow is added of a different quality, the bundle will average the quality of the arrows contained.</li>\n<li>An <a class=\"mw-redirect\" href=\"/index.php/MOI\" title=\"MOI\">MOI</a> can cause an arrow bundle to turn rare, but the bundle rarity will be transferred to only one of the arrows when the bundle is unbound.</li>\n<li>You can mix <a href=\"/index.php/War_arrow\" title=\"War arrow\">War arrows</a> and <a href=\"/index.php/Hunting_arrow\" title=\"Hunting arrow\">Hunting arrows</a> in the same bundle and their type will not change as a result of being bundled.</li>\n<li>The items and bundle must be in your inventory to create, add to, or unbind.</li>\n<li>Rare+ and casted arrows can be added to a bundle but their rarity and spells will be lost. (You are warned at the start of the action, and have time to stop.)</li>\n<li>Creation time is variable and based on the quality of the arrow, wire and your fletching skill.</li>\n<li>The materials required when improving a bundle is scaled to match the number of arrows being improved. 41 arrows means 41x the required log amount per imp action.</li>\n<li>There is no difficulty increase improving the arrows in a bundle no matter how many arrows the bundle contains.</li>\n<li>Arrow bundles can have spells cast on them, but are <b>substantially</b> more difficult to cast on and can shatter.</li>\n<li>You can cast any spell onto the bundle that you would be able to cast onto an arrow and that spell will affect each arrow in the bundle.</li>\n<li>You cannot improve an arrow bundle that has more arrows in it than you can add yourself.</li>\n<li>You cannot rune or imbue an arrow bundle.</li>\n<li>You cannot combine bundles, you can only add single arrows.</li>\n<li>The wood type of the bundle (and all arrows contained in it) is determined by the wood type of the last arrow added.</li>\n<li>Arrow bundles can be mailed and are a single item, costing 1c to mail</li></ul>', 5),
(14933, 3878, 'Description', 'Description', 'A small decorative ship, created with enough detail to resemble the real thing.', '<p><i>A small decorative ship, created with enough detail to resemble the real thing.</i>\n</p>', 0);
INSERT INTO `page_sections` (`id`, `page_id`, `heading`, `heading_id`, `content_text`, `content_html`, `section_order`) VALUES
(14934, 3878, 'Notes', 'Notes', 'The Decorative ship skin from the Loyalty program in the Marks shop can be applied to this item. While there is no minimum skill level required, this item is not easily craftable at low levels of Fine Carpentry skill. The ship, (not its plinth), takes on the wood type of the last piece added.', '<ul><li>The Decorative ship skin from the <a href=\"/index.php/Loyalty_program\" title=\"Loyalty program\">Loyalty program</a> in the <a class=\"mw-redirect\" href=\"/index.php/Marks_shop\" title=\"Marks shop\">Marks shop</a> can be applied to this item.</li>\n<li>While there is no minimum skill level required, this item is not easily craftable at low levels of <a class=\"mw-redirect\" href=\"/index.php/Fine_Carpentry\" title=\"Fine Carpentry\">Fine Carpentry</a> skill.</li>\n<li>The ship, (not its plinth), takes on the wood type of the last piece added.</li></ul>\n<div class=\"thumb tleft\"><div class=\"thumbinner\" style=\"width:502px;\"><a class=\"image\" href=\"/index.php/File:Decorative_ships.png\"><img alt=\"Decorative ships.png\" class=\"thumbimage\" data-file-height=\"919\" data-file-width=\"1350\" decoding=\"async\" height=\"340\" src=\"/images/thumb/5/5e/Decorative_ships.png/500px-Decorative_ships.png\" srcset=\"/images/thumb/5/5e/Decorative_ships.png/750px-Decorative_ships.png 1.5x, /images/thumb/5/5e/Decorative_ships.png/1000px-Decorative_ships.png 2x\" width=\"500\"/></a> <div class=\"thumbcaption\"><div class=\"magnify\"><a class=\"internal\" href=\"/index.php/File:Decorative_ships.png\" title=\"Enlarge\"></a></div></div></div></div>', 1),
(15043, 3700, 'Description', 'Description', 'Treasure hunts are an in game activity where players find treasure maps while doing other actions and then follow a series of steps to find a treasure chest.', '<p>Treasure hunts are an in game activity where players find treasure maps while doing other actions and then follow a series of steps to find a treasure chest. \n</p>', 0),
(15044, 3700, 'Maps', 'Maps', 'How to Find Maps Players will have a chance to find treasure maps during rare rolls on the following actions: Farming/Harvesting Botanize/Forage Actions Digging Mining/Surface Mining Investigating Archeology Sites Fishing/Dredging Praying Levels of Maps Different maps have different difficulties. Harder maps will be less common but have better treasures! Novice(1/5 chance on rare roll)(1-29ql) Will be between 2-3 steps long Will not be terribly far from the locations they are found. The spot can be found within 15 tiles of the X. Challenging(1/10 chance on rare roll, supreme rolls will always give one)(30-59ql) Can be 3-5 steps long Will be a moderate distance from the locations they are found. The spot can be found within 10 tiles of the X. Difficult(1/25 chance on rare roll, fantastic rolls will always give one)(60 – 100ql) Can be 4-6 steps long Will always have hidden creatures that can be difficult to kill for most every step Will be long distances away from the locations they are found. The spot can be found within 5 tiles of the X. Clues There are several different clue types to help you find your treasure! Map clue: Shows a map with a location you must go to, will not be super close to villages or in an enclosed area. Right clicking the map and selecting the hint option will draw a circle on your ingame map with a general area to search, the area gets larger on harder clues. Deed Ruins clue: Works similar to the maps but will be focused on areas that past villages have existed. Right clicking the map and selecting the hint option will draw a circle on your ingame map with a general area to search, the area gets larger on harder clues. Will mark nearby disbanded villages on the map as well as the area to dig. Challenge clue: will give an area and some information about an item from a list of items to find. Any guard tower that are not enclosed or near or in a village Colossus that are not enclosed or near or in a village Mission Constructed items that are not in caves/enclosed or near villages. Will mention what map grid it is near, this becomes less precise the more difficult it is. Combat Challenges: when you try to dig up a location you may come across some creatures ambushing you which you must defeat before you can continue digging it up. Will go into hiding again after 45 minutes if not yet killed until you come and dig again, then the same remaining creatures will ambush you again. Creatures from this will drop no corpses but will give skill for fighting.', '<h3><span class=\"mw-headline\" id=\"How_to_Find_Maps\">How to Find Maps</span></h3>\n<p>Players will have a chance to find treasure maps during rare rolls on the following actions:\n</p>\n<ul><li>Farming/Harvesting</li>\n<li>Botanize/Forage Actions</li>\n<li>Digging</li>\n<li>Mining/Surface Mining</li>\n<li>Investigating Archeology Sites</li>\n<li>Fishing/Dredging</li>\n<li>Praying</li></ul>\n<h3><span class=\"mw-headline\" id=\"Levels_of_Maps\">Levels of Maps</span></h3>\n<p>Different maps have different difficulties. Harder maps will be less common but have better treasures! \n</p>\n<ul><li>Novice(1/5 chance on rare roll)(1-29ql)\n<ul><li>Will be between 2-3 steps long</li>\n<li>Will not be terribly far from the locations they are found.</li>\n<li>The spot can be found within 15 tiles of the X.</li></ul></li>\n<li>Challenging(1/10 chance on rare roll, supreme rolls will always give one)(30-59ql)\n<ul><li>Can be 3-5 steps long</li>\n<li>Will be a moderate distance from the locations they are found.</li>\n<li>The spot can be found within 10 tiles of the X.</li></ul></li>\n<li>Difficult(1/25 chance on rare roll, fantastic rolls will always give one)(60 – 100ql)\n<ul><li>Can be 4-6 steps long</li>\n<li>Will always have hidden creatures that can be difficult to kill for most every step</li>\n<li>Will be long distances away from the locations they are found.</li>\n<li>The spot can be found within 5 tiles of the X.</li></ul></li></ul>\n<h3><span class=\"mw-headline\" id=\"Clues\">Clues</span></h3>\n<p>There are several different clue types to help you find your treasure!\n</p>\n<ul><li>Map clue: Shows a map with a location you must go to, will not be super close to villages or in an enclosed area.\n<ul><li>Right clicking the map and selecting the hint option will draw a circle on your ingame map with a general area to search, the area gets larger on harder clues.</li></ul></li>\n<li>Deed Ruins clue: Works similar to the maps but will be focused on areas that past villages have existed.\n<ul><li>Right clicking the map and selecting the hint option will draw a circle on your ingame map with a general area to search, the area gets larger on harder clues.</li>\n<li>Will mark nearby disbanded villages on the map as well as the area to dig.</li></ul></li>\n<li>Challenge clue: will give an area and some information about an item from a list of items to find.\n<ul><li>Any guard tower that are not enclosed or near or in a village</li>\n<li>Colossus that are not enclosed or near or in a village</li>\n<li>Mission Constructed items that are not in caves/enclosed or near villages.</li>\n<li>Will mention what map grid it is near, this becomes less precise the more difficult it is.</li></ul></li>\n<li>Combat Challenges: when you try to dig up a location you may come across some creatures ambushing you which you must defeat before you can continue digging it up.\n<ul><li>Will go into hiding again after 45 minutes if not yet killed until you come and dig again, then the same remaining creatures will ambush you again.</li>\n<li>Creatures from this will drop no corpses but will give skill for fighting.</li></ul></li></ul>', 1),
(15045, 3700, 'Digging Up Treasure', 'Digging_Up_Treasure', 'Use a shovel on the ground and select the dig up treasure option which will check if any clues you have on you are at your location. Has some grace distance, you do not need to dig on the exact tile/item it picks just near it. This grace distance is even larger the easier the clue is. Some of the items found in treasure chests are only found this way and are not craftable any other way. Treasure Hunt Rewards Some of the items you may find in treasure chests: Aquamarine necklace Anchor necklace Blessed water skin Coin purse Cutlass Eye patch Marbled necklace Pirate hat Ruby necklace Sabre Statue of crab Statue of octopus Statue of whale and dolphin Translucent necklace Special versions of liquor may also be found in glass jugs and these have different properties from crafted versions: Ale Bitter Brandy Cerber\'s triple hops Cider Egg nog Gin Moonshine Mead Nicrolis\' gingerbeer Rum Stout Vodka', '<ul><li>Use a shovel on the ground and select the dig up treasure option which will check if any clues you have on you are at your location.</li>\n<li>Has some grace distance, you do not need to dig on the exact tile/item it picks just near it. This grace distance is even larger the easier the clue is.</li>\n<li>Some of the <a href=\"/index.php/Category:Treasure_hunt_items\" title=\"Category:Treasure hunt items\">items</a> found in treasure chests are only found this way and are not craftable any other way.</li></ul>\n<h3><span class=\"mw-headline\" id=\"Treasure_Hunt_Rewards\">Treasure Hunt Rewards</span></h3>\n<p>Some of the items you may find in treasure chests: \n</p>\n<ul><li><a href=\"/index.php/Aquamarine_necklace\" title=\"Aquamarine necklace\">Aquamarine necklace</a></li>\n<li><a href=\"/index.php/Anchor_necklace\" title=\"Anchor necklace\">Anchor necklace</a></li>\n<li><a href=\"/index.php/Blessed_water_skin\" title=\"Blessed water skin\">Blessed water skin</a></li>\n<li><a href=\"/index.php/Coin_purse\" title=\"Coin purse\">Coin purse</a></li>\n<li><a href=\"/index.php/Cutlass\" title=\"Cutlass\">Cutlass</a></li>\n<li><a href=\"/index.php/Eye_patch\" title=\"Eye patch\">Eye patch</a></li>\n<li><a href=\"/index.php/Marbled_necklace\" title=\"Marbled necklace\">Marbled necklace</a></li>\n<li><a href=\"/index.php/Pirate_hat\" title=\"Pirate hat\">Pirate hat</a></li>\n<li><a href=\"/index.php/Ruby_necklace\" title=\"Ruby necklace\">Ruby necklace</a></li>\n<li><a href=\"/index.php/Sabre\" title=\"Sabre\">Sabre</a></li>\n<li><a href=\"/index.php/Statue_of_crab\" title=\"Statue of crab\">Statue of crab</a></li>\n<li><a href=\"/index.php/Statue_of_octopus\" title=\"Statue of octopus\">Statue of octopus</a></li>\n<li><a href=\"/index.php/Statue_of_whale_and_dolphin\" title=\"Statue of whale and dolphin\">Statue of whale and dolphin</a></li>\n<li><a href=\"/index.php/Translucent_necklace\" title=\"Translucent necklace\">Translucent necklace</a></li></ul>\n<p>Special versions of liquor may also be found in <a href=\"/index.php/Glass_jug\" title=\"Glass jug\">glass jugs</a> and these have different properties from crafted versions:\n</p>\n<ul><li>Ale</li>\n<li>Bitter</li>\n<li>Brandy</li>\n<li>Cerber\'s triple hops</li>\n<li>Cider</li>\n<li>Egg nog</li>\n<li>Gin</li>\n<li>Moonshine</li>\n<li>Mead</li>\n<li>Nicrolis\' gingerbeer</li>\n<li>Rum</li>\n<li>Stout</li>\n<li>Vodka</li></ul>', 2),
(15046, 3700, 'See also', 'See_also', 'Category:Treasure hunt items', '<ul><li><a href=\"/index.php/Category:Treasure_hunt_items\" title=\"Category:Treasure hunt items\">Category:Treasure hunt items</a></li></ul>', 3),
(15055, 3896, 'Description', 'Description', 'A decorative wreath, carefully crafted out of branches, leaves and other seasonal bits and bobs.', '<p><i>A decorative wreath, carefully crafted out of branches, leaves and other seasonal bits and bobs.</i>\n</p>', 0),
(15056, 3896, 'Notes', 'Notes', 'A hangable decorative item obtained through Archaeology only during the annual Halloween event, introduced during Halloween 2023. Can be created by combining 3 autumn wreath fragments.', '<ul><li>A hangable decorative item obtained through <a href=\"/index.php/Archaeology\" title=\"Archaeology\">Archaeology</a> only during the annual Halloween event, introduced during Halloween 2023.</li>\n<li>Can be created by combining 3 autumn wreath fragments.</li></ul>', 1),
(15057, 3897, 'Description', 'Description', 'Ever since The Incident Skjaldi does not believe in chasing away birds anymore.', '<p><i>Ever since The Incident Skjaldi does not believe in chasing away birds anymore. </i>\n</p>', 0),
(15058, 3897, 'Notes', 'Notes', 'A decorative item obtained through Archaeology only during the annual Halloween event, introduced at Halloween 2023. Can be created by combining 5 statue of Skjaldi the scarecrow fragments. Skjaldi periodically caws.', '<ul><li>A decorative item obtained through <a href=\"/index.php/Archaeology\" title=\"Archaeology\">Archaeology</a> only during the annual Halloween event, introduced at Halloween 2023.</li>\n<li>Can be created by combining 5 statue of Skjaldi the scarecrow fragments.</li>\n<li>Skjaldi periodically caws.</li></ul>', 1),
(15059, 3898, 'Description', 'Description', 'Fashionable shoulder pads in the shape of a corvid\'s wings.', '<p><i>Fashionable shoulder pads in the shape of a corvid\'s wings.</i>\n</p>', 0),
(15060, 3898, 'Effects', 'Effects', 'No known buff, purely decoration.', '<ul><li>No known buff, purely decoration.</li></ul>', 1),
(15061, 3898, 'Notes', 'Notes', 'First obtained during Halloween 2023 by killing hostile creatures. Shoulder pads take damage when not in the player\'s inventory, on a merchant , in the mail or in a magic chest and cannot be repaired. Signature on the shoulder pad is from the mob that dropped it. i.e: \'a.ol.scent.crocodile\'.', '<ul><li>First obtained during Halloween 2023 by killing hostile creatures.</li>\n<li>Shoulder pads take damage when not in the player\'s inventory, on a <a class=\"mw-redirect\" href=\"/index.php/Merchant\" title=\"Merchant\">merchant</a>, in the <a href=\"/index.php/Mail\" title=\"Mail\">mail</a> or in a <a class=\"mw-redirect\" href=\"/index.php/Magic_chest\" title=\"Magic chest\">magic chest</a> and cannot be repaired.</li>\n<li>Signature on the shoulder pad is from the mob that dropped it. <i>i.e: \'a.ol.scent.crocodile\'.</i></li></ul>', 2),
(15073, 3901, 'Description', 'Description', 'Large marine algae and plants grow here, along with whatever else might be living amongst them.', '<p><i>Large marine algae and plants grow here, along with whatever else might be living amongst them.</i>\n</p>\n<p><br/>\n</p>\n<p><br/>\n</p>\n<link href=\"mw-data:TemplateStyles:r120082\" rel=\"mw-deduplicated-inline-style\"/>', 0),
(15074, 3901, 'Notes', 'Notes', 'Lore can vary slightly from one Seaweed node to the next due to a number of factors such as season, location, tile type and skill. Resource nodes spawn and disappear randomly over time. It can be a few days or more for new resource nodes to appear on an empty tile. Resource nodes are destroyed if the type of the tile changes, such as paving or packing the tile, or when items are collected from them.', '<ul><li>Lore can vary slightly from one Seaweed node to the next due to a number of factors such as season, location, tile type and skill.</li>\n<li>Resource nodes spawn and disappear randomly over time. It can be a few days or more for new resource nodes to appear on an empty tile.</li>\n<li>Resource nodes are destroyed if the type of the tile changes, such as paving or packing the tile, or when items are collected from them.</li></ul>', 1),
(15075, 3901, 'See also', 'See_also', 'Resource nodes List of Node resources', '<ul><li><a href=\"/index.php/Resource_nodes\" title=\"Resource nodes\">Resource nodes</a></li>\n<li>List of <a href=\"/index.php/Node_resources\" title=\"Node resources\">Node resources</a></li></ul>', 2);
