(15709, 4057, 'See also', 'See_also', 'Rustic log arch Rustic log balcony Rustic log canopy Rustic log door Rustic log double door Rustic log double window Rustic log double T arch Rustic log T arch Rustic log wall Rustic log wide window Rustic log window', '<ul><li><a href=\"/index.php/Rustic_log_arch\" title=\"Rustic log arch\">Rustic log arch</a></li>\n<li><a href=\"/index.php/Rustic_log_balcony\" title=\"Rustic log balcony\">Rustic log balcony</a></li>\n<li><a href=\"/index.php/Rustic_log_canopy\" title=\"Rustic log canopy\">Rustic log canopy</a></li>\n<li><a href=\"/index.php/Rustic_log_door\" title=\"Rustic log door\">Rustic log door</a></li>\n<li><a href=\"/index.php/Rustic_log_double_door\" title=\"Rustic log double door\">Rustic log double door</a></li>\n<li><a href=\"/index.php/Rustic_log_double_window\" title=\"Rustic log double window\">Rustic log double window</a></li>\n<li><a class=\"mw-selflink selflink\">Rustic log double T arch</a></li>\n<li><a href=\"/index.php/Rustic_log_T_arch\" title=\"Rustic log T arch\">Rustic log T arch</a></li>\n<li><a href=\"/index.php/Rustic_log_wall\" title=\"Rustic log wall\">Rustic log wall</a></li>\n<li><a href=\"/index.php/Rustic_log_wide_window\" title=\"Rustic log wide window\">Rustic log wide window</a></li>\n<li><a href=\"/index.php/Rustic_log_window\" title=\"Rustic log window\">Rustic log window</a></li></ul>\n<p><br/>\n</p>', 5),
(15710, 4058, 'Description', 'Description', 'You see an arched wall opening.', '<p><i>You see an arched wall opening. </i>\n</p>', 0),
(15711, 4058, 'Creation', 'Creation', 'Have at least 1 wooden beam and 1 peg in your inventory. Activate a mallet or hammer and right-click on a wall plan . Select Build and then Rustic log T arch .', '<ul><li>Have at least 1 <a href=\"/index.php/Wooden_beam\" title=\"Wooden beam\">wooden beam</a> and 1 peg in your inventory.</li>\n<li><b>Activate</b> a <a href=\"/index.php/Mallet\" title=\"Mallet\">mallet</a> or <a href=\"/index.php/Hammer\" title=\"Hammer\">hammer</a> and <b>right-click</b> on a <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">wall plan</a>.</li>\n<li>Select <b>Build</b> and then <b>Rustic log T arch</b>.</li></ul>', 1),
