<td></td>\n<td>\n</td></tr>\n<tr>\n<td>Red wind</td>\n<td>Right</td>\n<td>7</td>\n<td>30</td>\n<td>35</td>\n<td>14,000</td>\n<td>1</td>\n<td>2</td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td>True blood</td>\n<td>High left, high right</td>\n<td>8</td>\n<td>55</td>\n<td>60</td>\n<td>17,000</td>\n<td>2</td>\n<td>2</td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td>Wanderer</td>\n<td>Low left, low right</td>\n<td>8</td>\n<td>25</td>\n<td>30</td>\n<td>14,000</td>\n<td>1</td>\n<td></td>\n<td>13,000</td>\n<td>\n</td></tr>\n<tr>\n<td align=\"center\" rowspan=\"6\"><a href=\"/index.php/Freedom\" title=\"Freedom\">Freedom Isles</a></td>\n<td>Back breaker</td>\n<td>Left</td>\n<td>5</td>\n<td>30</td>\n<td>35</td>\n<td>15,000</td>\n<td>2</td>\n<td>1</td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td>Bloodscion</td>\n<td>Low left, low, low right</td>\n<td>7</td>\n<td>40</td>\n<td>35</td>\n<td>15,000</td>\n<td>3</td>\n<td>1</td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td>Cold clouds</td>\n<td>High left, high, high right</td>\n<td>7</td>\n<td>25</td>\n<td>30</td>\n<td>16,000</td>\n<td>1</td>\n<td></td>\n<td>10,000</td>\n<td>\n</td></tr>\n<tr>\n<td>Low rider</td>\n<td>Low</td>\n<td>5</td>\n<td>19</td>\n<td>25</td>\n<td>15,000</td>\n<td>1</td>\n<td></td>\n<td>2,000</td>\n<td>5\n</td></tr>\n<tr>\n<td>Raktaktak</td>\n<td>Left, right</td>\n<td>4</td>\n<td>50</td>\n<td>55</td>\n<td>15,000</td>\n<td>3</td>\n<td>2</td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td>Tattoo twice</td>\n<td>High left, high, high right</td>\n<td>8</td>\n<td>60</td>\n<td>50</td>\n<td>16,000</td>\n<td>2</td>\n<td>3</td>\n<td></td>\n<td>\n</td></tr></tbody></table>\n<h3><span class=\"mw-headline\" id=\"Blunt\">Blunt</span></h3>\n<p>Blunt weapons specialize in draining the opponent\'s <a class=\"mw-redirect\" href=\"/index.php/Stamina\" title=\"Stamina\">stamina</a> and making them throw up, which reduces their <a href=\"/index.php/Food\" title=\"Food\">food</a> and <a href=\"/index.php/Thirst\" title=\"Thirst\">water</a> bars. These weapons include <a href=\"/index.php/Mauls\" title=\"Mauls\">mauls</a>, <a class=\"mw-redirect\" href=\"/index.php/Steel_staff\" title=\"Steel staff\">staves</a>, and <a href=\"/index.php/Huge_club\" title=\"Huge club\">clubs</a>.\n</p>\n<table class=\"wikitable sortable\">\n<tbody><tr>\n<th>Kingdom</th>\n<th>Name</th>\n<th>Stance</th>\n<th>Timer (seconds)</th>\n<th>Skill needed</th>\n<th>Difficulty</th>\n<th>Stamina cost</th>\n<th>Stamina drain</th>\n<th>Puke</th>\n<th>Stun (seconds)\n</th></tr>\n<tr>\n<td align=\"center\" rowspan=\"6\"><a href=\"/index.php/Jenn-Kellon\" title=\"Jenn-Kellon\">Jenn-Kellon</a></td>\n<td>Falcon</td>\n<td>High left, high, high right</td>\n<td>7</td>\n<td>30</td>\n<td>25</td>\n<td>16,000</td>\n<td>10,000</td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td>Golem roar</td>\n<td>High right</td>\n<td>9</td>\n<td>60</td>\n<td>65</td>\n<td>15,000</td>\n<td>25,000</td>\n<td>Yes</td>\n<td>\n</td></tr>\n<tr>\n<td>Minikill</td>\n<td>High left, high right</td>\n<td>7</td>\n<td>50</td>\n<td>55</td>\n<td>14,000</td>\n<td>15,000</td>\n<td>Yes</td>\n<td>\n</td></tr>\n<tr>\n<td>Sludge</td>\n<td>Low</td>\n<td>5</td>\n<td>19</td>\n<td>25</td>\n<td>15,000</td>\n<td>2,000</td>\n<td></td>\n<td>5\n</td></tr>\n<tr>\n<td>Sour marmalade</td>\n<td>Right</td>\n<td>6</td>\n<td>40</td>\n<td>30</td>\n<td>15,000</td>\n<td>10,000</td>\n<td>Yes</td>\n<td>\n</td></tr>\n<tr>\n<td>Union of the snake</td>\n<td>Low left, low, low right</td>\n<td>5</td>\n<td>30</td>\n<td>35</td>\n<td>13,000</td>\n<td>5,000</td>\n<td></td>\n<td>\n</td></tr>\n<tr>\n<td align=\"center\" rowspan=\"6\"><a href=\"/index.php/Mol-Rehan\" title=\"Mol-Rehan\">Mol-Rehan</a></td>\n<td>Bonker</td>\n<td>Low left, low, low right</td>\n<td>5</td>\n<td>25</td>\n<td>30</td>\n<td>14,000</td>\n<td>5,000</td>\n<td>Yes</td>\n<td>\n</td></tr>\n<tr>\n<td>Cricket</td>\n<td>High left, high, high right</td>\n<td>5</td>\n<td>19</td>\n<td>25</td>\n<td>8,000</td>\n<td>2,000</td>\n<td></td>\n<td>4\n</td></tr>\n<tr>\n<td>Faithpush</t